import { Pipe, PipeTransform } from '@angular/core';
import { DatePipe } from '@angular/common';

@Pipe({ name: 'dateFormat' })
export class DateFormatPipe implements PipeTransform {
  private datePipe: DatePipe;

  constructor() {
    this.datePipe = new DatePipe('fr-FR');
  }

  transform(value: string | Date | null | undefined, format: 'default' | 'relative' | 'short' = 'default'): string {
    if (!value) {
      return '';
    }

    const date = typeof value === 'string' ? new Date(value) : value;

    if (format === 'relative') {
      return this.getRelativeTime(date);
    }

    if (format === 'short') {
      return this.datePipe.transform(date, 'dd/MM/yyyy') || '';
    }

    return this.datePipe.transform(date, 'dd/MM/yyyy HH:mm') || '';
  }

  private getRelativeTime(date: Date): string {
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) {
      return 'À l\'instant';
    } else if (diffMins < 60) {
      return `Il y a ${diffMins} min`;
    } else if (diffHours < 24) {
      return `Il y a ${diffHours}h`;
    } else if (diffDays === 1) {
      return 'Hier';
    } else if (diffDays < 7) {
      return `Il y a ${diffDays}j`;
    } else if (diffDays < 30) {
      const weeks = Math.floor(diffDays / 7);
      return `Il y a ${weeks} sem${weeks > 1 ? 's' : ''}`;
    } else if (diffDays < 365) {
      const months = Math.floor(diffDays / 30);
      return `Il y a ${months} mois`;
    } else {
      const years = Math.floor(diffDays / 365);
      return `Il y a ${years} an${years > 1 ? 's' : ''}`;
    }
  }
}

import { Pipe, PipeTransform } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

@Pipe({ name: 'highlight' })
export class HighlightPipe implements PipeTransform {
  constructor(private sanitizer: DomSanitizer) {}

  transform(text: string, search: string): SafeHtml {
    if (!search || !text) {
      return text;
    }

    const regex = new RegExp(`(${this.escapeRegex(search)})`, 'gi');
    const highlighted = text.replace(regex, '<mark>$1</mark>');
    
    return this.sanitizer.sanitize(1, highlighted) || text;
  }

  private escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
}

import { Pipe, PipeTransform } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

@Pipe({ name: 'lineBreak' })
export class LineBreakPipe implements PipeTransform {
  constructor(private sanitizer: DomSanitizer) {}

  transform(value: string): SafeHtml {
    if (!value) return '';
    const withBreaks = value.replace(/\n/g, '<br>');
    return this.sanitizer.bypassSecurityTrustHtml(withBreaks);
  }
}

import { Pipe, PipeTransform } from '@angular/core';

/**
 * Pipe for localizing strings in templates
 * Note: This is a pass-through pipe since Angular's i18n handles translation at compile-time
 * It's provided for template consistency and potential runtime fallback
 */
@Pipe({ name: 'localize' })
export class LocalizePipe implements PipeTransform {
  transform(value: string): string {
    return value;
  }
}

import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'phoneFormat' })
export class PhoneFormatPipe implements PipeTransform {
  transform(value: string | null | undefined): string {
    if (!value) {
      return '';
    }

    // Remove all non-digit characters
    const digits = value.replace(/\D/g, '');

    // Format French phone numbers (10 digits)
    if (digits.length === 10) {
      return digits.replace(/(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})/, '$1 $2 $3 $4 $5');
    }

    // Format international French phone numbers starting with +33 (11 digits with country code)
    if (digits.length === 11 && digits.startsWith('33')) {
      return '+33 ' + digits.substring(2).replace(/(\d{1})(\d{2})(\d{2})(\d{2})(\d{2})/, '$1 $2 $3 $4 $5');
    }

    // For other formats, just return the original value
    return value;
  }
}

import { Pipe, PipeTransform } from '@angular/core';
import { CurrencyPipe } from '@angular/common';

@Pipe({ name: 'priceFormat' })
export class PriceFormatPipe implements PipeTransform {
  private currencyPipe: CurrencyPipe;

  constructor() {
    this.currencyPipe = new CurrencyPipe('fr-FR');
  }

  transform(value: number | null | undefined, currency = 'EUR'): string {
    if (value === null || value === undefined) {
      return '';
    }
    return this.currencyPipe.transform(value, currency, 'symbol', '1.2-2', 'fr-FR') || '';
  }
}

