import { Injectable } from '@angular/core';
import { MatSnackBar, MatSnackBarRef } from '@angular/material/snack-bar';
import { BehaviorSubject, Observable } from 'rxjs';
import { AriaLiveAnnouncerService } from './aria-live-announcer.service';

export type ToastPosition = 
  | 'top-right' 
  | 'top-left' 
  | 'top-center' 
  | 'bottom-right' 
  | 'bottom-left' 
  | 'bottom-center';

export type ToastType = 'success' | 'error' | 'warning' | 'info';

export interface ToastAction {
  label: string;
  handler: () => void;
}

export interface ToastNotification {
  id?: string;
  message: string;
  type: ToastType;
  action?: ToastAction;
  duration?: number;
  dismissible?: boolean;
  position?: ToastPosition;
  showProgress?: boolean;
}

export interface ActiveToast extends ToastNotification {
  id: string;
  startTime: number;
  timeoutId?: any;
}

@Injectable({
  providedIn: 'root'
})
export class ToastNotificationService {
  private readonly maxSimultaneous = 3;
  private activeToasts$ = new BehaviorSubject<ActiveToast[]>([]);
  private queue: ToastNotification[] = [];
  
  // Legacy support
  private currentSnackBarRef: MatSnackBarRef<any> | null = null;
  private legacyMode = false;

  constructor(
    private snackBar: MatSnackBar,
    private ariaLiveAnnouncer: AriaLiveAnnouncerService
  ) {}

  get activeToasts(): Observable<ActiveToast[]> {
    return this.activeToasts$.asObservable();
  }

  success(
    message: string, 
    action?: string | ToastAction, 
    duration = 5000,
    position: ToastPosition = 'top-right'
  ): string {
    return this.show({
      message,
      type: 'success',
      action: this.normalizeAction(action),
      duration,
      dismissible: true,
      position,
      showProgress: true
    });
  }

  error(
    message: string, 
    action?: string | ToastAction, 
    duration = 7000,
    position: ToastPosition = 'top-right'
  ): string {
    return this.show({
      message,
      type: 'error',
      action: this.normalizeAction(action),
      duration,
      dismissible: true,
      position,
      showProgress: true
    });
  }

  warning(
    message: string, 
    action?: string | ToastAction, 
    duration = 6000,
    position: ToastPosition = 'top-right'
  ): string {
    return this.show({
      message,
      type: 'warning',
      action: this.normalizeAction(action),
      duration,
      dismissible: true,
      position,
      showProgress: true
    });
  }

  info(
    message: string, 
    action?: string | ToastAction, 
    duration = 5000,
    position: ToastPosition = 'top-right'
  ): string {
    return this.show({
      message,
      type: 'info',
      action: this.normalizeAction(action),
      duration,
      dismissible: true,
      position,
      showProgress: true
    });
  }

  show(notification: ToastNotification): string {
    const id = notification.id || this.generateId();
    const toast: ActiveToast = {
      ...notification,
      id,
      startTime: Date.now(),
      position: notification.position || 'top-right',
      showProgress: notification.showProgress !== false,
      dismissible: notification.dismissible !== false
    };

    // Announce to screen readers
    const announcement = `${this.getTypeLabel(toast.type)}: ${toast.message}`;
    this.ariaLiveAnnouncer.announce(
      announcement, 
      toast.type === 'error' ? 'assertive' : 'polite'
    );

    const active = this.activeToasts$.value;
    
    if (active.length >= this.maxSimultaneous) {
      this.queue.push(toast);
    } else {
      this.addToActive(toast);
    }

    return id;
  }

  dismiss(id: string): void {
    const active = this.activeToasts$.value;
    const toast = active.find(t => t.id === id);
    
    if (toast?.timeoutId) {
      clearTimeout(toast.timeoutId);
    }

    const updated = active.filter(t => t.id !== id);
    this.activeToasts$.next(updated);

    // Process queue
    this.processQueue();
  }

  dismissAll(): void {
    const active = this.activeToasts$.value;
    active.forEach(toast => {
      if (toast.timeoutId) {
        clearTimeout(toast.timeoutId);
      }
    });
    this.activeToasts$.next([]);
    this.queue = [];
  }

  clearQueue(): void {
    this.queue = [];
  }

  private addToActive(toast: ActiveToast): void {
    const active = this.activeToasts$.value;
    this.activeToasts$.next([...active, toast]);

    if (toast.duration && toast.duration > 0) {
      toast.timeoutId = setTimeout(() => {
        this.dismiss(toast.id);
      }, toast.duration);
    }
  }

  private processQueue(): void {
    const active = this.activeToasts$.value;
    
    while (this.queue.length > 0 && active.length < this.maxSimultaneous) {
      const next = this.queue.shift();
      if (next) {
        this.addToActive({
          ...next,
          startTime: Date.now()
        } as ActiveToast);
      }
    }
  }

  private normalizeAction(action?: string | ToastAction): ToastAction | undefined {
    if (!action) return undefined;
    
    if (typeof action === 'string') {
      return {
        label: action,
        handler: () => { return; }
      };
    }
    
    return action;
  }

  private getTypeLabel(type: ToastType): string {
    const labels: Record<ToastType, string> = {
      success: 'Succès',
      error: 'Erreur',
      warning: 'Avertissement',
      info: 'Information'
    };
    return labels[type];
  }

  private generateId(): string {
    return `toast-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  // Legacy support methods
  private showLegacy(notification: ToastNotification): void {
    this.legacyMode = true;
    const actionLabel = notification.action?.label ?? 'Fermer';
    this.currentSnackBarRef = this.snackBar.open(notification.message, actionLabel, {
      duration: notification.duration,
      horizontalPosition: 'center',
      verticalPosition: 'top',
      panelClass: [`${notification.type}-snackbar`]
    });

    this.currentSnackBarRef.onAction().subscribe(() => {
      try {
        notification.action?.handler();
      } catch {
        // no-op
      }
    });

    this.currentSnackBarRef.afterDismissed().subscribe(() => {
      this.currentSnackBarRef = null;
    });
  }

  dismissLegacy(): void {
    if (this.currentSnackBarRef) {
      this.currentSnackBarRef.dismiss();
    }
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

export enum ActivityType {
  NOTE = 'NOTE',
  STATUS_CHANGE = 'STATUS_CHANGE',
  APPOINTMENT_CREATED = 'APPOINTMENT_CREATED',
  MESSAGE_SENT = 'MESSAGE_SENT'
}

export enum ActivityVisibility {
  INTERNAL = 'INTERNAL',
  CLIENT_VISIBLE = 'CLIENT_VISIBLE'
}

export interface ActivityResponse {
  id: number;
  type: ActivityType;
  content: string;
  dossierId: number;
  visibility: ActivityVisibility;
  createdAt: string;
  createdBy: string;
  createdByName?: string;
}

export interface ActivityCreateRequest {
  type: ActivityType;
  content: string;
  dossierId: number;
  visibility: ActivityVisibility;
}

export interface ActivityUpdateRequest {
  content?: string;
  visibility?: ActivityVisibility;
}

export interface Page<T> {
  content: T[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
}

@Injectable({
  providedIn: 'root'
})
export class ActivityApiService {
  private baseUrl = '/api/v1/activities';

  constructor(private http: HttpClient) {}

  create(request: ActivityCreateRequest): Observable<ActivityResponse> {
    return this.http.post<ActivityResponse>(this.baseUrl, request);
  }

  getById(id: number): Observable<ActivityResponse> {
    return this.http.get<ActivityResponse>(`${this.baseUrl}/${id}`);
  }

  list(params: {
    dossierId?: number;
    visibility?: ActivityVisibility;
    startDate?: string;
    endDate?: string;
    page?: number;
    size?: number;
    sort?: string;
  }): Observable<Page<ActivityResponse>> {
    let httpParams = new HttpParams();

    if (params.dossierId !== undefined) {
      httpParams = httpParams.set('dossierId', params.dossierId.toString());
    }
    if (params.visibility) {
      httpParams = httpParams.set('visibility', params.visibility);
    }
    if (params.startDate) {
      httpParams = httpParams.set('startDate', params.startDate);
    }
    if (params.endDate) {
      httpParams = httpParams.set('endDate', params.endDate);
    }
    if (params.page !== undefined) {
      httpParams = httpParams.set('page', params.page.toString());
    }
    if (params.size !== undefined) {
      httpParams = httpParams.set('size', params.size.toString());
    }
    if (params.sort) {
      httpParams = httpParams.set('sort', params.sort);
    }

    return this.http.get<Page<ActivityResponse>>(this.baseUrl, { params: httpParams });
  }

  update(id: number, request: ActivityUpdateRequest): Observable<ActivityResponse> {
    return this.http.put<ActivityResponse>(`${this.baseUrl}/${id}`, request);
  }

  delete(id: number): Observable<void> {
    return this.http.delete<void>(`${this.baseUrl}/${id}`);
  }
}

