import { Component, OnInit, input, output } from '@angular/core';
import { FormArray, FormBuilder, FormGroup, Validators, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { debounceTime } from 'rxjs/operators';
import { MatFormField, MatLabel, MatSuffix } from '@angular/material/form-field';
import { MatSelect } from '@angular/material/select';
import { MatOption } from '@angular/material/autocomplete';
import { MatInput } from '@angular/material/input';
import { DsInputComponent } from '../design-system/primitives/ds-input/ds-input.component';
import { MatDatepickerInput, MatDatepickerToggle, MatDatepicker } from '@angular/material/datepicker';
import { DsCardComponent } from '../design-system';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';
import { DsButtonComponent } from '../design-system/primitives/ds-button/ds-button.component';
import { DsIconComponent } from '../design-system/icons/ds-icon.component';

export interface FilterCondition {
  field: string;
  operator: string;
  value: any;
}

export interface AdvancedFilter {
  conditions: FilterCondition[];
  logicOperator: 'AND' | 'OR';
}

export interface FilterField {
  key: string;
  label: string;
  type: 'text' | 'number' | 'date' | 'select' | 'boolean';
  operators: FilterOperator[];
  options?: { value: string; label: string }[];
}

export interface FilterOperator {
  value: string;
  label: string;
  requiresValue: boolean;
}

@Component({
    selector: 'app-advanced-filters',
    templateUrl: './advanced-filters.component.html',
    styleUrls: ['./advanced-filters.component.css'],
    imports: [FormsModule, ReactiveFormsModule, MatFormField, MatLabel, MatSelect, MatOption, MatInput, MatDatepickerInput, MatDatepickerToggle, MatSuffix, MatDatepicker, DsCardComponent, DsSkeletonComponent, DsButtonComponent, DsIconComponent, DsInputComponent]
})
export class AdvancedFiltersComponent implements OnInit {
  readonly fields = input<FilterField[]>([]);
  readonly initialFilter = input<AdvancedFilter>();
  readonly filterChange = output<AdvancedFilter>();
  readonly countRequest = output<AdvancedFilter>();
  readonly filterApplied = output<AdvancedFilter>();

  filterForm!: FormGroup;
  resultCount: number | null = null;
  countLoading = false;

  operators: { [key: string]: FilterOperator[] } = {
    text: [
      { value: 'EQUALS', label: 'Égal à', requiresValue: true },
      { value: 'NOT_EQUALS', label: 'Différent de', requiresValue: true },
      { value: 'CONTAINS', label: 'Contient', requiresValue: true },
      { value: 'NOT_CONTAINS', label: 'Ne contient pas', requiresValue: true },
      { value: 'STARTS_WITH', label: 'Commence par', requiresValue: true },
      { value: 'ENDS_WITH', label: 'Finit par', requiresValue: true },
      { value: 'IS_NULL', label: 'Est vide', requiresValue: false },
      { value: 'IS_NOT_NULL', label: 'N\'est pas vide', requiresValue: false }
    ],
    number: [
      { value: 'EQUALS', label: 'Égal à', requiresValue: true },
      { value: 'NOT_EQUALS', label: 'Différent de', requiresValue: true },
      { value: 'GREATER_THAN', label: 'Supérieur à', requiresValue: true },
      { value: 'GREATER_THAN_OR_EQUAL', label: 'Supérieur ou égal à', requiresValue: true },
      { value: 'LESS_THAN', label: 'Inférieur à', requiresValue: true },
      { value: 'LESS_THAN_OR_EQUAL', label: 'Inférieur ou égal à', requiresValue: true },
      { value: 'BETWEEN', label: 'Entre', requiresValue: true },
      { value: 'IS_NULL', label: 'Est vide', requiresValue: false },
      { value: 'IS_NOT_NULL', label: 'N\'est pas vide', requiresValue: false }
    ],
    date: [
      { value: 'EQUALS', label: 'Égal à', requiresValue: true },
      { value: 'GREATER_THAN', label: 'Après', requiresValue: true },
      { value: 'LESS_THAN', label: 'Avant', requiresValue: true },
      { value: 'BETWEEN', label: 'Entre', requiresValue: true },
      { value: 'EQUALS_TODAY', label: 'Aujourd\'hui', requiresValue: false },
      { value: 'THIS_WEEK', label: 'Cette semaine', requiresValue: false },
      { value: 'LESS_THAN_DAYS_AGO', label: 'Moins de X jours', requiresValue: true },
      { value: 'IS_NULL', label: 'Est vide', requiresValue: false },
      { value: 'IS_NOT_NULL', label: 'N\'est pas vide', requiresValue: false }
    ],
    select: [
      { value: 'EQUALS', label: 'Égal à', requiresValue: true },
      { value: 'NOT_EQUALS', label: 'Différent de', requiresValue: true },
      { value: 'IN', label: 'Parmi', requiresValue: true },
      { value: 'NOT_IN', label: 'Pas parmi', requiresValue: true },
      { value: 'IS_NULL', label: 'Est vide', requiresValue: false },
      { value: 'IS_NOT_NULL', label: 'N\'est pas vide', requiresValue: false }
    ],
    boolean: [
      { value: 'EQUALS', label: 'Égal à', requiresValue: true }
    ]
  };

  constructor(
    private fb: FormBuilder,
    private dialog: MatDialog
  ) {}

  ngOnInit(): void {
    this.initForm();
    this.setupAutoCount();
  }

  private initForm(): void {
    this.filterForm = this.fb.group({
      logicOperator: ['AND'],
      conditions: this.fb.array([])
    });

    const initialFilter = this.initialFilter();
    if (initialFilter && initialFilter.conditions.length > 0) {
      initialFilter.conditions.forEach(condition => {
        this.addCondition(condition);
      });
      this.filterForm.patchValue({
        logicOperator: initialFilter.logicOperator || 'AND'
      });
    } else {
      this.addCondition();
    }
  }

  private setupAutoCount(): void {
    this.filterForm.valueChanges
      .pipe(debounceTime(500))
      .subscribe(() => {
        this.requestCount();
      });
  }

  get conditions(): FormArray {
    return this.filterForm.get('conditions') as FormArray;
  }

  addCondition(condition?: FilterCondition): void {
    const field = condition?.field || (this.fields().length > 0 ? this.fields()[0].key : '');
    const fieldConfig = this.fields().find(f => f.key === field);
    const operator = condition?.operator || (fieldConfig?.operators[0]?.value || 'EQUALS');
    
    const conditionGroup = this.fb.group({
      field: [field, Validators.required],
      operator: [operator, Validators.required],
      value: [condition?.value || '']
    });

    this.conditions.push(conditionGroup);
  }

  setLogicOperator(op: 'AND' | 'OR'): void {
    this.filterForm.patchValue({ logicOperator: op });
  }

  removeCondition(index: number): void {
    this.conditions.removeAt(index);
    if (this.conditions.length === 0) {
      this.addCondition();
    }
  }

  onFieldChange(index: number): void {
    const condition = this.conditions.at(index) as FormGroup;
    const field = condition.get('field')?.value;
    const fieldConfig = this.fields().find(f => f.key === field);
    
    if (fieldConfig && fieldConfig.operators.length > 0) {
      condition.patchValue({
        operator: fieldConfig.operators[0].value,
        value: ''
      });
    }
  }

  onOperatorChange(index: number): void {
    const condition = this.conditions.at(index) as FormGroup;
    const operator = condition.get('operator')?.value;
    const operatorConfig = this.getOperatorConfig(index, operator);
    
    if (operatorConfig && !operatorConfig.requiresValue) {
      condition.patchValue({ value: '' });
    }
  }

  getFieldConfig(fieldKey: string): FilterField | undefined {
    return this.fields().find(f => f.key === fieldKey);
  }

  getOperators(index: number): FilterOperator[] {
    const condition = this.conditions.at(index) as FormGroup;
    const field = condition.get('field')?.value;
    const fieldConfig = this.getFieldConfig(field);
    return fieldConfig?.operators || [];
  }

  getOperatorConfig(index: number, operatorValue: string): FilterOperator | undefined {
    const operators = this.getOperators(index);
    return operators.find(op => op.value === operatorValue);
  }

  requiresValue(index: number): boolean {
    const condition = this.conditions.at(index) as FormGroup;
    const operator = condition.get('operator')?.value;
    const operatorConfig = this.getOperatorConfig(index, operator);
    return operatorConfig?.requiresValue !== false;
  }

  getFieldType(index: number): string {
    const condition = this.conditions.at(index) as FormGroup;
    const field = condition.get('field')?.value;
    const fieldConfig = this.getFieldConfig(field);
    return fieldConfig?.type || 'text';
  }

  getFieldOptions(index: number): { value: string; label: string }[] {
    const condition = this.conditions.at(index) as FormGroup;
    const field = condition.get('field')?.value;
    const fieldConfig = this.getFieldConfig(field);
    return fieldConfig?.options || [];
  }

  isMultiSelect(index: number): boolean {
    const condition = this.conditions.at(index) as FormGroup;
    const operator = condition.get('operator')?.value;
    return operator === 'IN' || operator === 'NOT_IN';
  }

  applyFilter(): void {
    if (this.filterForm.valid) {
      const filter = this.getFilterValue();
      this.filterApplied.emit(filter);
    }
  }

  clearFilter(): void {
    this.conditions.clear();
    this.addCondition();
    this.filterForm.patchValue({ logicOperator: 'AND' });
    this.resultCount = null;
  }

  requestCount(): void {
    if (this.filterForm.valid && this.conditions.length > 0) {
      const filter = this.getFilterValue();
      const firstCondition = this.conditions.at(0) as FormGroup;
      if (firstCondition.get('field')?.value) {
        this.countRequest.emit(filter);
      }
    }
  }

  updateCount(count: number): void {
    this.resultCount = count;
    this.countLoading = false;
  }

  setCountLoading(loading: boolean): void {
    this.countLoading = loading;
  }

  private getFilterValue(): AdvancedFilter {
    const formValue = this.filterForm.value;
    return {
      conditions: formValue.conditions.filter((c: FilterCondition) => c.field),
      logicOperator: formValue.logicOperator
    };
  }

  exportToUrl(): string {
    const filter = this.getFilterValue();
    const encoded = btoa(JSON.stringify(filter));
    return `${window.location.origin}${window.location.pathname}?filter=${encoded}`;
  }

  copyUrlToClipboard(): void {
    const url = this.exportToUrl();
    navigator.clipboard.writeText(url).then(() => {
      console.log('URL copied to clipboard');
    });
  }
}

import { Component, Inject, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef, MatDialogTitle, MatDialogContent, MatDialogActions } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { AdvancedFilter, FilterField, AdvancedFiltersComponent } from './advanced-filters.component';
import { FilterPreset, FilterPresetRequest, FilterPresetService } from '../services/filter-preset.service';
import { DossierFilterApiService, DossierFilterRequest } from '../services/dossier-filter-api.service';
import { CdkScrollable } from '@angular/cdk/scrolling';
import { DsButtonComponent } from '../design-system/primitives/ds-button/ds-button.component';
import { DsIconComponent } from '../design-system/icons/ds-icon.component';
import { FormsModule } from '@angular/forms';
import { DsInputComponent } from '../design-system/primitives/ds-input/ds-input.component';

export interface AdvancedFiltersDialogData {
  filterType: string;
  fields: FilterField[];
  initialFilter?: AdvancedFilter;
}

@Component({
    selector: 'app-advanced-filters-dialog',
    templateUrl: './advanced-filters-dialog.component.html',
    styleUrls: ['./advanced-filters-dialog.component.css'],
    imports: [MatDialogTitle, CdkScrollable, MatDialogContent, DsButtonComponent, DsIconComponent, AdvancedFiltersComponent, MatDialogActions, FormsModule, DsInputComponent]
})
export class AdvancedFiltersDialogComponent implements OnInit {
  predefinedPresets: FilterPreset[] = [];
  userPresets: FilterPreset[] = [];
  currentFilter?: AdvancedFilter;
  resultCount: number | null = null;
  countLoading = false;
  showSaveDialog = false;
  presetName = '';
  presetDescription = '';
  sharePreset = false;

  constructor(
    public dialogRef: MatDialogRef<AdvancedFiltersDialogComponent>,
    @Inject(MAT_DIALOG_DATA) public data: AdvancedFiltersDialogData,
    private filterPresetService: FilterPresetService,
    private dossierFilterApi: DossierFilterApiService,
    private snackBar: MatSnackBar,
    private dialog: MatDialog
  ) {}

  ngOnInit(): void {
    this.loadPresets();
    if (this.data.initialFilter) {
      this.currentFilter = this.data.initialFilter;
    }
  }

  loadPresets(): void {
    this.filterPresetService.getPredefinedPresets(this.data.filterType).subscribe({
      next: (presets) => {
        this.predefinedPresets = presets;
      },
      error: (err) => {
        console.error('Error loading predefined presets:', err);
      }
    });

    this.filterPresetService.getUserPresets(this.data.filterType).subscribe({
      next: (presets) => {
        this.userPresets = presets;
      },
      error: (err) => {
        console.error('Error loading user presets:', err);
      }
    });
  }

  onFilterChange(filter: AdvancedFilter): void {
    this.currentFilter = filter;
  }

  onCountRequest(filter: AdvancedFilter): void {
    this.countLoading = true;
    const request: DossierFilterRequest = {
      conditions: filter.conditions,
      logicOperator: filter.logicOperator
    };

    this.dossierFilterApi.countAdvancedFilter(request).subscribe({
      next: (count) => {
        this.resultCount = count;
        this.countLoading = false;
      },
      error: (err) => {
        console.error('Error counting dossiers:', err);
        this.countLoading = false;
        this.snackBar.open('Erreur lors du comptage des résultats', 'Fermer', { duration: 3000 });
      }
    });
  }

  onFilterApplied(filter: AdvancedFilter): void {
    this.dialogRef.close({ filter });
  }

  loadPreset(preset: FilterPreset): void {
    if (preset.filterConfig && preset.filterConfig['conditions']) {
      this.currentFilter = {
        conditions: preset.filterConfig['conditions'] as any[],
        logicOperator: (preset.filterConfig['logicOperator'] as 'AND' | 'OR') || 'AND'
      };
    }
  }

  openSaveDialog(): void {
    this.showSaveDialog = true;
    this.presetName = '';
    this.presetDescription = '';
    this.sharePreset = false;
  }

  closeSaveDialog(): void {
    this.showSaveDialog = false;
  }

  savePreset(): void {
    if (!this.presetName.trim() || !this.currentFilter) {
      this.snackBar.open('Veuillez entrer un nom pour le preset', 'Fermer', { duration: 3000 });
      return;
    }

    const request: FilterPresetRequest = {
      name: this.presetName,
      filterType: this.data.filterType,
      description: this.presetDescription || undefined,
      filterConfig: {
        conditions: this.currentFilter.conditions,
        logicOperator: this.currentFilter.logicOperator
      },
      isShared: this.sharePreset
    };

    this.filterPresetService.create(request).subscribe({
      next: () => {
        this.snackBar.open('Preset sauvegardé avec succès', 'Fermer', { duration: 3000 });
        this.closeSaveDialog();
        this.loadPresets();
      },
      error: (err) => {
        console.error('Error saving preset:', err);
        this.snackBar.open('Erreur lors de la sauvegarde du preset', 'Fermer', { duration: 3000 });
      }
    });
  }

  deletePreset(preset: FilterPreset): void {
    if (!preset.id) return;

    if (confirm(`Supprimer le preset "${preset.name}" ?`)) {
      this.filterPresetService.delete(preset.id).subscribe({
        next: () => {
          this.snackBar.open('Preset supprimé avec succès', 'Fermer', { duration: 3000 });
          this.loadPresets();
        },
        error: (err) => {
          console.error('Error deleting preset:', err);
          this.snackBar.open('Erreur lors de la suppression du preset', 'Fermer', { duration: 3000 });
        }
      });
    }
  }

  cancel(): void {
    this.dialogRef.close();
  }
}

import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

// ─── Intent Types ────────────────────────────────────────────
export type AgentIntentType =
    | 'SEARCH'
    | 'CREATE'
    | 'STATUS_CHANGE'
    | 'SEND_MESSAGE'
    | 'NAVIGATE'
    | 'UNKNOWN';

export interface AgentIntent {
    type: AgentIntentType;
    confidence: number;       // 0–1
    query: string;            // original query
    params: Record<string, string>;
    /** Human-readable description of what the agent will do */
    description: string;
    /** Quick-action chips for the UI */
    suggestedActions?: AgentAction[];
}

export interface AgentAction {
    label: string;
    icon: string;
    handler: () => void;
}

export interface AgentMessage {
    id: string;
    role: 'user' | 'agent';
    content: string;
    timestamp: Date;
    intent?: AgentIntent;
    actions?: AgentAction[];
    isTyping?: boolean;
}

// ─── Keyword maps ─────────────────────────────────────────────
interface IntentPattern {
    type: AgentIntentType;
    verbs: string[];
    weight: number;
}

const INTENT_PATTERNS: IntentPattern[] = [
    {
        type: 'SEARCH',
        verbs: ['trouve', 'trouv', 'cherche', 'montre', 'affiche', 'liste', 'show', 'find', 'search', 'voir tous', 'quels'],
        weight: 3
    },
    {
        type: 'CREATE',
        verbs: ['crée', 'créer', 'nouveau', 'nouvelle', 'ajoute', 'ajouter', 'nouveau lead', 'new', 'créer un', 'ouvrir un'],
        weight: 3
    },
    {
        type: 'STATUS_CHANGE',
        verbs: ['statut', 'status', 'marque', 'marquer', 'archive', 'archiver', 'clôture', 'ferme', 'gagne', 'perdu', 'qualifie', 'changer statut'],
        weight: 2
    },
    {
        type: 'SEND_MESSAGE',
        verbs: ['envoie', 'envoyer', 'message', 'whatsapp', 'sms', 'contacte', 'contacter', 'appelle', 'appeler', 'écris', 'écrire'],
        weight: 2
    },
    {
        type: 'NAVIGATE',
        verbs: ['va', 'aller', 'ouvre', 'ouvrir', 'navigue', 'page', 'go to', 'tableau de bord', 'dashboard', 'calendrier', 'dossiers', 'annonces', 'rapports'],
        weight: 1
    }
];

// ─── Entity extraction helpers ────────────────────────────────
const PROPERTY_TYPES = ['t1', 't2', 't3', 't4', 't5', 'studio', 'villa', 'appartement', 'maison', 'bureau', 'local', 'terrain'];
const CITIES = ['casablanca', 'rabat', 'marrakech', 'fes', 'agadir', 'tanger', 'meknes', 'oujda', 'tetouan'];
const STATUS_MAP: Record<string, string> = {
    'nouveau': 'NEW', 'qualifié': 'QUALIFIED', 'qualification': 'QUALIFYING',
    'rendez-vous': 'APPOINTMENT', 'rdv': 'APPOINTMENT',
    'gagné': 'WON', 'perdu': 'LOST', 'archivé': 'LOST'
};

/**
 * AiAgentService — Atlas 2026 Phase 2 Frontend Layer
 *
 * Provides:
 * 1. Local intent parsing (no backend required) — instant, offline-capable
 * 2. Backend stub (POST /api/ai/agent) — for future LLM integration
 * 3. Conversation state management (BehaviorSubject)
 * 4. Action dispatch to Angular Router and API services
 */
@Injectable({ providedIn: 'root' })
export class AiAgentService {

    private readonly API_URL = '/api/ai/agent';

    /** Whether the AI panel is open */
    private _panelOpen$ = new BehaviorSubject<boolean>(false);
    panelOpen$ = this._panelOpen$.asObservable();

    /** Conversational history for the session */
    private _messages$ = new BehaviorSubject<AgentMessage[]>([]);
    messages$ = this._messages$.asObservable();

    /** Pre-filled query when opening from CMD+K */
    private _pendingQuery$ = new BehaviorSubject<string>('');
    pendingQuery$ = this._pendingQuery$.asObservable();

    constructor(private router: Router, private http: HttpClient) { }

    // ─── Panel lifecycle ────────────────────────────────────────
    openPanel(query = ''): void {
        this._pendingQuery$.next(query);
        this._panelOpen$.next(true);
    }

    closePanel(): void {
        this._panelOpen$.next(false);
        this._pendingQuery$.next('');
    }

    togglePanel(): void {
        if (this._panelOpen$.value) {
            this.closePanel();
        } else {
            this.openPanel();
        }
    }

    clearConversation(): void {
        this._messages$.next([]);
    }

    // ─── Main entry point ───────────────────────────────────────
    /**
     * Process a natural-language query:
     * 1. Parse intent locally
     * 2. If intent is clear (confidence ≥ 0.7) and not UNKNOWN → dispatch immediately
     * 3. Otherwise → add to conversation, try backend, return conversational response
     */
    processQuery(rawQuery: string): Observable<AgentIntent> {
        const query = rawQuery.trim();
        const intent = this.parseIntent(query);

        // Add user message to conversation
        this.addMessage({ role: 'user', content: query });

        if (intent.type !== 'UNKNOWN' && intent.confidence >= 0.65) {
            // High-confidence → dispatch and return immediately
            this.addTypingIndicator();
            this.dispatchIntent(intent);
            return of(intent);
        }

        // Low-confidence or UNKNOWN → call backend, fallback to local response
        this.addTypingIndicator();
        return this.callBackend(query).pipe(
            map(serverIntent => {
                const finalIntent = serverIntent ?? intent;
                this.dispatchIntent(finalIntent);
                return finalIntent;
            }),
            catchError(() => {
                this.dispatchIntent(intent);
                return of(intent);
            })
        );
    }

    // ─── Local intent parser ────────────────────────────────────
    parseIntent(query: string): AgentIntent {
        const q = query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

        let bestType: AgentIntentType = 'UNKNOWN';
        let bestScore = 0;

        for (const pattern of INTENT_PATTERNS) {
            for (const verb of pattern.verbs) {
                if (q.includes(verb)) {
                    const score = pattern.weight + (q.startsWith(verb) ? 2 : 0);
                    if (score > bestScore) {
                        bestScore = score;
                        bestType = pattern.type;
                    }
                }
            }
        }

        const confidence = bestScore > 0 ? Math.min(0.5 + (bestScore * 0.1), 1) : 0.2;
        const params = this.extractEntities(q, query);

        return {
            type: bestType,
            confidence,
            query,
            params,
            description: this.describeIntent(bestType, params, query),
            suggestedActions: this.buildSuggestedActions(bestType, params)
        };
    }

    // ─── Entity extraction ──────────────────────────────────────
    private extractEntities(qNorm: string, qOrig: string): Record<string, string> {
        const params: Record<string, string> = {};

        // Property type
        for (const type of PROPERTY_TYPES) {
            if (qNorm.includes(type)) {
                params['propertyType'] = type.toUpperCase();
                break;
            }
        }

        // City
        for (const city of CITIES) {
            if (qNorm.includes(city)) {
                params['city'] = city.charAt(0).toUpperCase() + city.slice(1);
                break;
            }
        }

        // Budget extraction (e.g. "2M MAD", "500000", "1.5 million")
        const budgetMatch = qOrig.match(/(\d[\d\s.,]*)(?:\s*M(?:AD)?|\s*million)?/i);
        if (budgetMatch) {
            let val = parseFloat(budgetMatch[1].replace(/[\s,]/g, '').replace('.', '.'));
            if (qOrig.toLowerCase().includes('million') || qOrig.toLowerCase().match(/\d+m\b/i)) {
                val *= 1_000_000;
            }
            if (val > 1000) {
                params['budget'] = String(Math.round(val));
            }
        }

        // Person name (capitalised words after "pour", "de", "à")
        const nameMatch = qOrig.match(/(?:pour|de|à|monsieur|madame|mr|mme)\s+([A-ZÀ-Ü][a-zà-ü]+(?:\s+[A-ZÀ-Ü][a-zà-ü]+)?)/);
        if (nameMatch) {
            params['personName'] = nameMatch[1];
        }

        // Status
        for (const [fr, en] of Object.entries(STATUS_MAP)) {
            if (qNorm.includes(fr)) {
                params['status'] = en;
                break;
            }
        }

        // Search terms: everything after the main verb
        const searchTermMatch = qOrig.match(/(?:trouve|cherche|montre|affiche|liste)\s+(.+)/i);
        if (searchTermMatch) {
            params['searchQuery'] = searchTermMatch[1].trim();
        }

        return params;
    }

    // ─── Intent description (for UI display) ───────────────────
    private describeIntent(type: AgentIntentType, params: Record<string, string>, query: string): string {
        switch (type) {
            case 'SEARCH': {
                const parts: string[] = [];
                if (params['propertyType']) parts.push(params['propertyType']);
                if (params['city']) parts.push(`à ${params['city']}`);
                if (params['budget']) parts.push(`< ${Number(params['budget']).toLocaleString('fr-MA')} MAD`);
                return parts.length > 0
                    ? `Rechercher : ${parts.join(', ')}`
                    : `Rechercher "${params['searchQuery'] || query}"`;
            }
            case 'CREATE':
                return params['personName']
                    ? `Créer un dossier pour ${params['personName']}`
                    : 'Créer un nouveau dossier / lead';
            case 'STATUS_CHANGE':
                return params['status']
                    ? `Changer le statut en "${params['status']}"`
                    : 'Modifier le statut d\'un dossier';
            case 'SEND_MESSAGE':
                return params['personName']
                    ? `Envoyer un message à ${params['personName']}`
                    : 'Ouvrir la messagerie WhatsApp';
            case 'NAVIGATE':
                return `Naviguer vers une section`;
            default:
                return 'Je vais analyser votre demande…';
        }
    }

    // ─── Action dispatch ────────────────────────────────────────
    dispatchIntent(intent: AgentIntent): void {
        const { type, params } = intent;

        switch (type) {
            case 'SEARCH': {
                const q = [
                    params['propertyType'],
                    params['city'],
                    params['searchQuery']
                ].filter(Boolean).join(' ').trim() || intent.query;

                this.router.navigate(['/search'], { queryParams: { q } });

                this.addAgentMessage(
                    `🔍 Je recherche "${q}" dans les annonces et dossiers.`,
                    intent
                );
                break;
            }

            case 'CREATE':
                this.router.navigate(['/dossiers'], { queryParams: { action: 'create' } });
                this.addAgentMessage(
                    params['personName']
                        ? `✅ J'ouvre le formulaire de création pour **${params['personName']}**.`
                        : `✅ J'ouvre le formulaire de création de dossier.`,
                    intent
                );
                break;

            case 'STATUS_CHANGE':
                this.addAgentMessage(
                    `🔄 Pour changer un statut, ouvrez d'abord le dossier concerné. Voulez-vous que je cherche un dossier spécifique ?`,
                    intent
                );
                break;

            case 'SEND_MESSAGE':
                this.router.navigate(['/dossiers'], { queryParams: { action: 'message' } });
                this.addAgentMessage(
                    params['personName']
                        ? `💬 Recherche du dossier de **${params['personName']}** pour ouvrir la messagerie…`
                        : `💬 Ouvrez un dossier et utilisez l'onglet Messagerie pour envoyer un WhatsApp.`,
                    intent
                );
                break;

            case 'NAVIGATE':
                this.handleNavigation(intent.query);
                this.addAgentMessage(`🧭 Navigation en cours…`, intent);
                break;

            default:
                this.addAgentMessage(
                    `Je n'ai pas compris votre demande. Essayez : *"Trouve des T3 à Casablanca"*, *"Crée un dossier"*, ou *"Envoie un message à M. Alami"*.`,
                    intent
                );
        }
    }

    private handleNavigation(query: string): void {
        const q = query.toLowerCase();
        if (q.includes('dashboard') || q.includes('tableau de bord')) {
            this.router.navigate(['/dashboard']);
        } else if (q.includes('dossier') || q.includes('lead')) {
            this.router.navigate(['/dossiers']);
        } else if (q.includes('annonce')) {
            this.router.navigate(['/annonces']);
        } else if (q.includes('calendrier') || q.includes('rdv')) {
            this.router.navigate(['/calendar']);
        } else if (q.includes('rapport') || q.includes('kpi')) {
            this.router.navigate(['/reports']);
        } else if (q.includes('tâche') || q.includes('task')) {
            this.router.navigate(['/tasks']);
        }
    }

    // ─── Suggested chips ────────────────────────────────────────
    private buildSuggestedActions(type: AgentIntentType, _params: Record<string, string>): AgentAction[] {
        switch (type) {
            case 'SEARCH':
                return [
                    { label: 'Voir les annonces', icon: 'campaign', handler: () => this.router.navigate(['/annonces']) },
                    { label: 'Voir les dossiers', icon: 'folder', handler: () => this.router.navigate(['/dossiers']) }
                ];
            case 'CREATE':
                return [
                    { label: 'Créer un dossier', icon: 'person_add', handler: () => this.router.navigate(['/dossiers'], { queryParams: { action: 'create' } }) },
                    { label: 'Créer une annonce', icon: 'add_circle', handler: () => this.router.navigate(['/annonces/new']) }
                ];
            case 'SEND_MESSAGE':
                return [
                    { label: 'Aller aux dossiers', icon: 'folder', handler: () => this.router.navigate(['/dossiers']) }
                ];
            default:
                return [
                    { label: 'Voir le tableau de bord', icon: 'dashboard', handler: () => this.router.navigate(['/dashboard']) },
