@Component({
    selector: 'app-appointment-form-dialog',
    templateUrl: './appointment-form-dialog.component.html',
    styleUrls: ['./appointment-form-dialog.component.css'],
    animations: [
        trigger('slideIn', [
            transition(':enter', [
                style({ transform: 'translateX(100%)', opacity: 0 }),
                animate('300ms ease-out', style({ transform: 'translateX(0)', opacity: 1 }))
            ])
        ])
    ],
    imports: [FocusTrapDirective, MatDialogTitle, MatIcon, CdkScrollable, MatDialogContent, FormsModule, ReactiveFormsModule, DatetimePickerComponent, NgClass, MatDialogActions, MatButton, DsSkeletonComponent]
})
export class AppointmentFormDialogComponent implements OnInit {
  appointmentForm!: FormGroup;
  isEditMode = false;
  isSubmitting = false;
  AppointmentStatus = AppointmentStatus;

  statusOptions = [
    { value: AppointmentStatus.SCHEDULED, label: 'Planifié' },
    { value: AppointmentStatus.COMPLETED, label: 'Terminé' },
    { value: AppointmentStatus.CANCELLED, label: 'Annulé' }
  ];

  localeOptions = [
    { value: 'fr_FR', label: 'Français (France)' },
    { value: 'en_US', label: 'English (US)' },
    { value: 'ar_MA', label: 'العربية (المغرب)' },
    { value: 'es_ES', label: 'Español (España)' },
    { value: 'de_DE', label: 'Deutsch (Deutschland)' }
  ];

  constructor(
    private fb: FormBuilder,
    private dialogRef: MatDialogRef<AppointmentFormDialogComponent>,
    @Inject(MAT_DIALOG_DATA) public data: AppointmentFormData
  ) {}

  ngOnInit(): void {
    this.isEditMode = !!(this.data?.id);
    
    this.appointmentForm = this.fb.group({
      startTime: [this.data?.startTime || '', Validators.required],
      endTime: [this.data?.endTime || '', Validators.required],
      location: [this.data?.location || ''],
      assignedTo: [this.data?.assignedTo || ''],
      notes: [this.data?.notes || ''],
      status: [this.data?.status || AppointmentStatus.SCHEDULED, Validators.required],
      locale: [this.data?.locale || 'fr_FR']
    }, { validators: this.timeRangeValidator });
  }

  timeRangeValidator(group: FormGroup): { [key: string]: boolean } | null {
    const startTime = group.get('startTime')?.value;
    const endTime = group.get('endTime')?.value;
    
    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      
      if (start >= end) {
        return { invalidTimeRange: true };
      }
    }
    
    return null;
  }

  onCancel(): void {
    this.dialogRef.close();
  }

  onSubmit(): void {
    if (this.appointmentForm.valid && !this.isSubmitting) {
      this.isSubmitting = true;
      const formValue = this.appointmentForm.value;
      this.dialogRef.close({
        id: this.data?.id,
        dossierId: this.data.dossierId,
        ...formValue
      });
    }
  }

  getErrorMessage(fieldName: string): string {
    const field = this.appointmentForm.get(fieldName);
    if (field?.hasError('required')) {
      return 'Ce champ est requis';
    }
    return '';
  }

  getFormErrorMessage(): string {
    if (this.appointmentForm.hasError('invalidTimeRange')) {
      return 'L\'heure de début doit être antérieure à l\'heure de fin';
    }
    return '';
  }
}

import { Component, OnInit, OnDestroy, input, output } from '@angular/core';
import { AppointmentApiService, AppointmentResponse, AppointmentStatus } from '../services/appointment-api.service';
import { Subject, takeUntil } from 'rxjs';
import { ToastNotificationService } from '../services/toast-notification.service';
import { MatDialog } from '@angular/material/dialog';
import { AppointmentFormDialogComponent, AppointmentFormData } from './appointment-form-dialog.component';
import { BreakpointObserver, Breakpoints } from '@angular/cdk/layout';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';
import { DsEmptyStateComponent } from '../design-system/primitives/ds-empty-state/ds-empty-state.component';
import { DsBadgeComponent, DsBadgeStatus } from '../design-system/primitives/ds-badge/ds-badge.component';
import { DsButtonComponent } from '../design-system/primitives/ds-button/ds-button.component';
import { DsIconComponent } from '../design-system/icons/ds-icon.component';

interface AppointmentGroup {
  date: Date;
  dateLabel: string;
  appointments: AppointmentResponse[];
}

@Component({
    selector: 'app-calendar-list-view',
    templateUrl: './calendar-list-view.component.html',
    styleUrls: ['./calendar-list-view.component.css'],
    imports: [
      DsSkeletonComponent,
      DsEmptyStateComponent,
      DsBadgeComponent,
      DsButtonComponent,
      DsIconComponent,
    ],
})
export class CalendarListViewComponent implements OnInit, OnDestroy {
  readonly filterByAssignedTo = input<string | null>(null);
  readonly filterByStatus = input<AppointmentStatus | null>(null);
  readonly startDate = input<Date>();
  readonly endDate = input<Date>();
  
  readonly appointmentClick = output<AppointmentResponse>();
  readonly appointmentUpdated = output<AppointmentResponse>();
  readonly appointmentDeleted = output<number>();

  private destroy$ = new Subject<void>();
  
  appointments: AppointmentResponse[] = [];
  groupedAppointments: AppointmentGroup[] = [];
  isLoading = false;
  isMobile = false;
  expandedGroups = new Set<string>();

  readonly statusLabels = {
    [AppointmentStatus.SCHEDULED]: 'Planifié',
    [AppointmentStatus.COMPLETED]: 'Terminé',
    [AppointmentStatus.CANCELLED]: 'Annulé'
  };

  constructor(
    private appointmentService: AppointmentApiService,
    private toastService: ToastNotificationService,
    private dialog: MatDialog,
    private breakpointObserver: BreakpointObserver
  ) {}

  ngOnInit(): void {
    this.breakpointObserver
      .observe([Breakpoints.Handset])
      .pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        this.isMobile = result.matches;
      });

    this.loadAppointments();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  loadAppointments(): void {
    this.isLoading = true;
    const params: any = { 
      size: 1000,
      sort: 'startTime,asc'
    };
    
    const filterByStatus = this.filterByStatus();
    if (filterByStatus) {
      params.status = filterByStatus;
    }

    const filterByAssignedTo = this.filterByAssignedTo();
    if (filterByAssignedTo) {
      params.assignedTo = filterByAssignedTo;
    }

    const startDate = this.startDate();
    if (startDate) {
      params.startTimeFrom = startDate.toISOString();
    }

    const endDate = this.endDate();
    if (endDate) {
      params.startTimeTo = endDate.toISOString();
    }

    this.appointmentService.list(params)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (response) => {
          this.appointments = response.content;
          this.groupAppointmentsByDate();
          this.isLoading = false;
        },
        error: (error) => {
          console.error('Error loading appointments:', error);
          this.toastService.error('Erreur lors du chargement des rendez-vous');
          this.isLoading = false;
        }
      });
  }

  private groupAppointmentsByDate(): void {
    const groups = new Map<string, AppointmentResponse[]>();

    this.appointments.forEach(apt => {
      const date = new Date(apt.startTime);
      date.setHours(0, 0, 0, 0);
      const dateKey = date.toISOString();

      if (!groups.has(dateKey)) {
        groups.set(dateKey, []);
      }
      groups.get(dateKey)!.push(apt);
    });

    this.groupedAppointments = Array.from(groups.entries())
      .map(([dateKey, appointments]) => {
        const date = new Date(dateKey);
        return {
          date,
          dateLabel: this.formatDateLabel(date),
          appointments: appointments.sort((a, b) => 
            new Date(a.startTime).getTime() - new Date(b.startTime).getTime()
          )
        };
      })
      .sort((a, b) => a.date.getTime() - b.date.getTime());

    this.groupedAppointments.forEach(group => {
      this.expandedGroups.add(group.dateLabel);
    });
  }

  private formatDateLabel(date: Date): string {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    const dateOnly = new Date(date);
    dateOnly.setHours(0, 0, 0, 0);

    if (dateOnly.getTime() === today.getTime()) {
      return "Aujourd'hui";
    } else if (dateOnly.getTime() === tomorrow.getTime()) {
      return 'Demain';
    } else if (dateOnly.getTime() === yesterday.getTime()) {
      return 'Hier';
    } else {
      return date.toLocaleDateString('fr-FR', { 
        weekday: 'long', 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
      });
    }
  }

  formatTime(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleTimeString('fr-FR', { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  }

  getDuration(start: string, end: string): string {
    const startDate = new Date(start);
    const endDate = new Date(end);
    const durationMs = endDate.getTime() - startDate.getTime();
    const durationMinutes = Math.floor(durationMs / 60000);
    
    if (durationMinutes < 60) {
      return `${durationMinutes} min`;
    } else {
      const hours = Math.floor(durationMinutes / 60);
      const minutes = durationMinutes % 60;
      return minutes > 0 ? `${hours}h ${minutes}min` : `${hours}h`;
    }
  }

  getStatusLabel(status: AppointmentStatus): string {
    return this.statusLabels[status] || status;
  }

  getAppointmentBadgeStatus(status: AppointmentStatus): DsBadgeStatus {
    switch (status) {
      case AppointmentStatus.COMPLETED:
        return 'success';
      case AppointmentStatus.CANCELLED:
        return 'archived';
      case AppointmentStatus.SCHEDULED:
      default:
        return 'rdv';
    }
  }

  appointmentStatusClass(status: AppointmentStatus): string {
    return String(status).toLowerCase();
  }

  toggleGroup(dateLabel: string): void {
    if (this.expandedGroups.has(dateLabel)) {
      this.expandedGroups.delete(dateLabel);
    } else {
      this.expandedGroups.add(dateLabel);
    }
  }

  isGroupExpanded(dateLabel: string): boolean {
    return this.expandedGroups.has(dateLabel);
  }

  onAppointmentClick(appointment: AppointmentResponse): void {
    this.appointmentClick.emit(appointment);
    
    if (this.isMobile) {
      this.openAppointmentDetails(appointment);
    }
  }

  openAppointmentDetails(appointment: AppointmentResponse): void {
    const dialogRef = this.dialog.open(AppointmentFormDialogComponent, {
      width: this.isMobile ? '95vw' : '600px',
      maxWidth: this.isMobile ? '95vw' : '600px',
      data: {
        id: appointment.id,
        dossierId: appointment.dossierId,
        startTime: appointment.startTime,
        endTime: appointment.endTime,
        location: appointment.location,
        assignedTo: appointment.assignedTo,
        notes: appointment.notes,
        status: appointment.status
      } as AppointmentFormData
    });

    dialogRef.afterClosed()
      .pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        if (result) {
          this.appointmentUpdated.emit(result);
          this.loadAppointments();
        }
      });
  }

  getAppointmentTitle(appointment: AppointmentResponse): string {
    let title = `RDV #${appointment.id}`;
    if (appointment.assignedTo) {
      title += ` - ${appointment.assignedTo}`;
    }
    return title;
  }

  refresh(): void {
    this.loadAppointments();
  }

  get totalAppointments(): number {
    return this.appointments.length;
  }

  get upcomingAppointments(): number {
    const now = new Date();
    return this.appointments.filter(apt => 
      new Date(apt.startTime) > now && 
      apt.status === AppointmentStatus.SCHEDULED
    ).length;
  }

  trackByGroup(index: number, group: AppointmentGroup): string {
    return group.dateLabel;
  }

  trackByAppointment(index: number, appointment: AppointmentResponse): number {
    return appointment.id;
  }
}

