@Component({
    selector: 'app-calendar-view',
    standalone: true,
    templateUrl: './calendar-view.component.html',
    styleUrls: ['./calendar-view.component.css'],
    imports: [
      DsCardComponent,
      DsSkeletonComponent,
      DsButtonComponent,
      DsIconComponent,
      MatFormField,
      MatLabel,
      MatSelect,
      MatOption,
      FullCalendarModule,
      CalendarListViewComponent,
    ],
})
export class CalendarViewComponent implements OnInit, OnDestroy {
  readonly calendarComponent = viewChild<any>('calendar');

  private destroy$ = new Subject<void>();
  isMobile = false;
  currentView = 'timeGridWeek';
  showListView = false;
  calendarLoaded = false;
  calendarLoading = false;

  calendarOptions: any = {
    plugins: [],
    initialView: 'timeGridWeek',
    headerToolbar: {
      left: 'prev,next today',
      center: 'title',
      right: 'dayGridMonth,timeGridWeek,timeGridDay,listWeek'
    },
    locale: 'fr',
    firstDay: 1,
    slotMinTime: '07:00:00',
    slotMaxTime: '21:00:00',
    slotDuration: '00:30:00',
    snapDuration: '00:15:00',
    allDaySlot: false,
    height: 'auto',
    editable: true,
    selectable: true,
    selectMirror: true,
    dayMaxEvents: true,
    weekends: true,
    nowIndicator: true,
    selectOverlap: false,
    eventOverlap: false,
    businessHours: {
      daysOfWeek: [1, 2, 3, 4, 5],
      startTime: '09:00',
      endTime: '18:00'
    },
    eventClick: this.handleEventClick.bind(this),
    eventDrop: this.handleEventDrop.bind(this),
    eventResize: this.handleEventResize.bind(this),
    select: this.handleDateSelect.bind(this),
    events: [],
    eventTimeFormat: {
      hour: '2-digit',
      minute: '2-digit',
      meridiem: false
    },
    slotLabelFormat: {
      hour: '2-digit',
      minute: '2-digit',
      meridiem: false
    },
    eventClassNames: (arg: any) => {
      const classes = ['fc-event-custom'];
      if (arg.event.extendedProps && arg.event.extendedProps['status'] === AppointmentStatus.CANCELLED) {
        classes.push('fc-event-cancelled');
      } else if (arg.event.extendedProps && arg.event.extendedProps['status'] === AppointmentStatus.COMPLETED) {
        classes.push('fc-event-completed');
      }
      return classes;
    }
  };

  appointments: AppointmentResponse[] = [];
  isLoading = false;
  filterByAssignedTo: string | null = null;
  filterByStatus: AppointmentStatus | null = null;
  availableAssignees: string[] = [];

  readonly statusOptions = [
    { value: null, label: 'Tous les statuts' },
    { value: AppointmentStatus.SCHEDULED, label: 'Planifié' },
    { value: AppointmentStatus.COMPLETED, label: 'Terminé' },
    { value: AppointmentStatus.CANCELLED, label: 'Annulé' }
  ];

  constructor(
    private appointmentService: AppointmentApiService,
    private calendarSyncService: CalendarSyncService,
    private dialog: MatDialog,
    private toastService: ToastNotificationService,
    private breakpointObserver: BreakpointObserver
  ) { }

  async ngOnInit(): Promise<void> {
    this.breakpointObserver
      .observe([Breakpoints.Handset])
      .pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        this.isMobile = result.matches;
        if (this.isMobile && this.currentView !== 'listWeek') {
          this.changeView('listWeek');
        }
      });

    await this.loadCalendarPlugins();
    this.loadAppointments();
  }

  private async loadCalendarPlugins(): Promise<void> {
    if (this.calendarLoaded) {
      return;
    }

    if (this.calendarLoading) {
      return;
    }

    this.calendarLoading = true;

    try {
      const [
        { default: dayGridPlugin },
        { default: timeGridPlugin },
        { default: listPlugin },
        { default: interactionPlugin },
        { default: iCalendarPlugin }
      ] = await Promise.all([
        import('@fullcalendar/daygrid'),
        import('@fullcalendar/timegrid'),
        import('@fullcalendar/list'),
        import('@fullcalendar/interaction'),
        import('@fullcalendar/icalendar')
      ]);

      this.calendarOptions.plugins = [
        dayGridPlugin,
        timeGridPlugin,
        listPlugin,
        interactionPlugin,
        iCalendarPlugin
      ];

      this.calendarLoaded = true;
      this.calendarLoading = false;
    } catch (error) {
      console.error('Failed to load FullCalendar plugins:', error);
      this.calendarLoading = false;
    }
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  loadAppointments(): void {
    this.isLoading = true;
    const params: any = { size: 1000 };

    if (this.filterByStatus) {
      params.status = this.filterByStatus;
    }

    this.appointmentService.list(params)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (response) => {
          this.appointments = response.content;
          this.extractAvailableAssignees();
          this.updateCalendarEvents();
          this.isLoading = false;
        },
        error: (error) => {
          console.error('Error loading appointments:', error);
          this.toastService.error('Erreur lors du chargement des rendez-vous');
          this.isLoading = false;
        }
      });
  }

  private extractAvailableAssignees(): void {
    const assignees = new Set<string>();
    this.appointments.forEach(apt => {
      if (apt.assignedTo) {
        assignees.add(apt.assignedTo);
      }
    });
    this.availableAssignees = Array.from(assignees).sort();
  }

  private updateCalendarEvents(): void {
    let filteredAppointments = this.appointments;

    if (this.filterByAssignedTo) {
      filteredAppointments = filteredAppointments.filter(
        apt => apt.assignedTo === this.filterByAssignedTo
      );
    }

    const events: CalendarEvent[] = filteredAppointments.map(apt => ({
      id: apt.id.toString(),
      title: this.getEventTitle(apt),
      start: apt.startTime,
      end: apt.endTime,
      backgroundColor: this.getStatusColor(apt.status),
      borderColor: this.getStatusColor(apt.status),
      extendedProps: {
        appointmentId: apt.id,
        dossierId: apt.dossierId,
        location: apt.location,
        assignedTo: apt.assignedTo,
        notes: apt.notes,
        status: apt.status
      }
    }));

    this.calendarOptions.events = events;
  }

  private getEventTitle(appointment: AppointmentResponse): string {
    let title = `RDV #${appointment.id}`;
    if (appointment.assignedTo) {
      title += ` - ${appointment.assignedTo}`;
    }
    if (appointment.location) {
      title += ` (${appointment.location})`;
    }
    return title;
  }

  private getStatusColor(status: AppointmentStatus): string {
    switch (status) {
      case AppointmentStatus.SCHEDULED:
        return resolveDsToken('--ds-marine-light');
      case AppointmentStatus.COMPLETED:
        return resolveDsToken('--ds-success');
      case AppointmentStatus.CANCELLED:
        return resolveDsToken('--ds-text-faint');
      default:
        return resolveDsToken('--ds-text-muted');
    }
  }

  handleDateSelect(selectInfo: any): void {
    const calendarApi = selectInfo.view.calendar;

    const dialogRef = this.dialog.open(AppointmentFormDialogComponent, {
      width: '600px',
      data: {
        dossierId: 0,
        startTime: selectInfo.startStr,
        endTime: selectInfo.endStr,
        status: AppointmentStatus.SCHEDULED
      } as AppointmentFormData
    });

    dialogRef.afterClosed()
      .pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        if (result) {
          if (result.dossierId === 0) {
            this.toastService.warning('Veuillez sélectionner un dossier pour créer le rendez-vous');
            calendarApi.unselect();
            return;
          }

          this.createAppointment(result);
        }
        calendarApi.unselect();
      });
  }

  handleEventClick(clickInfo: any): void {
    const appointmentId = parseInt(clickInfo.event.id);
    const appointment = this.appointments.find(apt => apt.id === appointmentId);

    if (!appointment) {
      return;
    }

    const dialogRef = this.dialog.open(AppointmentFormDialogComponent, {
      width: '600px',
      data: {
        id: appointment.id,
        dossierId: appointment.dossierId,
        startTime: appointment.startTime,
        endTime: appointment.endTime,
        location: appointment.location,
        assignedTo: appointment.assignedTo,
        notes: appointment.notes,
        status: appointment.status
      } as AppointmentFormData
    });

    dialogRef.afterClosed()
      .pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        if (result) {
          this.updateAppointment(result);
        }
      });
  }

  handleEventDrop(dropInfo: any): void {
    const appointmentId = parseInt(dropInfo.event.id);
    const appointment = this.appointments.find(apt => apt.id === appointmentId);

    if (!appointment) {
      dropInfo.revert();
      return;
    }

    const newStart = dropInfo.event.start;
    const newEnd = dropInfo.event.end;

    if (!newStart || !newEnd) {
      dropInfo.revert();
      return;
    }

    const conflicts = this.detectConflicts(appointmentId, newStart, newEnd, appointment.assignedTo);

    if (conflicts.length > 0) {
      const conflictMessages = conflicts.map(c =>
        `RDV #${c.id} (${this.formatTime(c.startTime)} - ${this.formatTime(c.endTime)})`
      ).join(', ');

      this.toastService.warning(`Conflit détecté avec: ${conflictMessages}`);
      dropInfo.revert();
      return;
    }

    const oldStartTime = appointment.startTime;
    const oldEndTime = appointment.endTime;

    const optimisticUpdate = {
      ...appointment,
      startTime: newStart.toISOString(),
      endTime: newEnd.toISOString()
    };

    const index = this.appointments.findIndex(apt => apt.id === appointmentId);
    if (index !== -1) {
      this.appointments[index] = optimisticUpdate;
    }

    const updateRequest: AppointmentUpdateRequest = {
      startTime: newStart.toISOString(),
      endTime: newEnd.toISOString(),
      location: appointment.location,
      assignedTo: appointment.assignedTo,
      notes: appointment.notes,
      status: appointment.status
    };

    this.appointmentService.update(appointmentId, updateRequest)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (updated) => {
          const idx = this.appointments.findIndex(apt => apt.id === appointmentId);
          if (idx !== -1) {
            this.appointments[idx] = updated;
          }
          this.updateCalendarEvents();
          this.toastService.success('Rendez-vous déplacé avec succès');
        },
        error: (error) => {
          console.error('Error updating appointment:', error);

          if (index !== -1) {
            this.appointments[index] = {
              ...appointment,
              startTime: oldStartTime,
              endTime: oldEndTime
            };
          }

          this.updateCalendarEvents();
          this.toastService.error('Erreur lors du déplacement du rendez-vous');
          dropInfo.revert();
        }
      });
  }


  handleEventResize(resizeInfo: EventChangeArg): void {

    const appointmentId = parseInt(resizeInfo.event.id);
    const appointment = this.appointments.find(apt => apt.id === appointmentId);

    if (!appointment) {
      resizeInfo.revert();
      return;
    }

    const newStart = resizeInfo.event.start;
    const newEnd = resizeInfo.event.end;

    if (!newStart || !newEnd) {
      resizeInfo.revert();
      return;
    }

    const conflicts = this.detectConflicts(appointmentId, newStart, newEnd, appointment.assignedTo);

    if (conflicts.length > 0) {
      this.toastService.warning('Conflit détecté : redimensionnement impossible');
      resizeInfo.revert();
      return;
    }

    const oldStartTime = appointment.startTime;
    const oldEndTime = appointment.endTime;

    const optimisticUpdate = {
      ...appointment,
      startTime: newStart.toISOString(),
      endTime: newEnd.toISOString()
    };

    const index = this.appointments.findIndex(apt => apt.id === appointmentId);
    if (index !== -1) {
      this.appointments[index] = optimisticUpdate;
    }

    const updateRequest: AppointmentUpdateRequest = {
      startTime: newStart.toISOString(),
      endTime: newEnd.toISOString(),
      location: appointment.location,
      assignedTo: appointment.assignedTo,
      notes: appointment.notes,
      status: appointment.status
    };

    this.appointmentService.update(appointmentId, updateRequest)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (updated) => {
          const idx = this.appointments.findIndex(apt => apt.id === appointmentId);
          if (idx !== -1) {
            this.appointments[idx] = updated;
          }
          this.updateCalendarEvents();
          this.toastService.success('Rendez-vous modifié avec succès');
        },
        error: (error) => {
          console.error('Error resizing appointment:', error);

          if (index !== -1) {
            this.appointments[index] = {
              ...appointment,
              startTime: oldStartTime,
              endTime: oldEndTime
            };
          }

          this.updateCalendarEvents();
          this.toastService.error('Erreur lors de la modification du rendez-vous');
          resizeInfo.revert();
        }
      });
  }

  private checkConflict(appointmentId: number, start: Date, end: Date, assignedTo?: string): boolean {
    return this.detectConflicts(appointmentId, start, end, assignedTo).length > 0;
  }

  private detectConflicts(appointmentId: number, start: Date, end: Date, assignedTo?: string): AppointmentResponse[] {
    if (!assignedTo) {
      return [];
    }

    return this.appointments.filter(apt => {
      if (apt.id === appointmentId) {
        return false;
      }

      if (apt.assignedTo !== assignedTo) {
        return false;
      }

      if (apt.status === AppointmentStatus.CANCELLED) {
        return false;
      }

      const aptStart = new Date(apt.startTime);
      const aptEnd = new Date(apt.endTime);

      return (start < aptEnd && end > aptStart);
    });
  }

  private formatTime(dateString: string): string {
    return new Date(dateString).toLocaleTimeString('fr-FR', {
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  createAppointment(data: AppointmentFormData): void {
    const request: AppointmentCreateRequest = {
      dossierId: data.dossierId,
      startTime: data.startTime!,
      endTime: data.endTime!,
      location: data.location,
      assignedTo: data.assignedTo,
      notes: data.notes,
      status: data.status || AppointmentStatus.SCHEDULED
    };

    this.appointmentService.create(request)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (created) => {
          this.appointments.push(created);
          this.extractAvailableAssignees();
          this.updateCalendarEvents();
          this.toastService.success('Rendez-vous créé avec succès');
        },
        error: (error) => {
          console.error('Error creating appointment:', error);
          this.toastService.error('Erreur lors de la création du rendez-vous');
        }
      });
  }

  updateAppointment(data: AppointmentFormData): void {
    if (!data.id) {
      return;
    }

    const request: AppointmentUpdateRequest = {
      startTime: data.startTime!,
      endTime: data.endTime!,
      location: data.location,
      assignedTo: data.assignedTo,
      notes: data.notes,
      status: data.status || AppointmentStatus.SCHEDULED
    };

    this.appointmentService.update(data.id, request)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (updated) => {
          const index = this.appointments.findIndex(apt => apt.id === data.id);
          if (index !== -1) {
            this.appointments[index] = updated;
          }
          this.extractAvailableAssignees();
          this.updateCalendarEvents();
          this.toastService.success('Rendez-vous mis à jour avec succès');
        },
        error: (error) => {
          console.error('Error updating appointment:', error);
          this.toastService.error('Erreur lors de la mise à jour du rendez-vous');
        }
      });
  }

  deleteAppointment(appointmentId: number): void {
    const dialogRef = this.dialog.open(ConfirmDeleteDialogComponent, {
      width: '400px',
      data: {
        title: 'Supprimer le rendez-vous',
        message: 'Êtes-vous sûr de vouloir supprimer ce rendez-vous ?'
      }
    });

    dialogRef.afterClosed()
      .pipe(takeUntil(this.destroy$))
      .subscribe(confirmed => {
        if (confirmed) {
          this.appointmentService.delete(appointmentId)
            .pipe(takeUntil(this.destroy$))
            .subscribe({
              next: () => {
                this.appointments = this.appointments.filter(apt => apt.id !== appointmentId);
                this.extractAvailableAssignees();
                this.updateCalendarEvents();
                this.toastService.success('Rendez-vous supprimé avec succès');
              },
              error: (error) => {
                console.error('Error deleting appointment:', error);
                this.toastService.error('Erreur lors de la suppression du rendez-vous');
              }
            });
        }
      });
  }

  onFilterByAssignedToChange(assignedTo: string | null): void {
    this.filterByAssignedTo = assignedTo;
    this.updateCalendarEvents();
  }

  onFilterByStatusChange(status: AppointmentStatus | null): void {
    this.filterByStatus = status;
    this.loadAppointments();
  }

  exportToICal(): void {
    let filteredAppointments = this.appointments;

    if (this.filterByAssignedTo) {
      filteredAppointments = filteredAppointments.filter(
        apt => apt.assignedTo === this.filterByAssignedTo
      );
    }

    if (this.filterByStatus) {
      filteredAppointments = filteredAppointments.filter(
        apt => apt.status === this.filterByStatus
      );
    }

    this.calendarSyncService.downloadICalendar(
      filteredAppointments,
      `appointments_${new Date().toISOString().split('T')[0]}.ics`
    );

    this.toastService.success('Calendrier exporté avec succès');
  }

  refreshCalendar(): void {
    this.loadAppointments();
  }

  changeView(viewType: string): void {
    this.currentView = viewType;
    const calendarApi = this.calendarComponent()?.getApi();
    if (calendarApi) {
      calendarApi.changeView(viewType);
    }
  }

  toggleListView(): void {
    this.showListView = !this.showListView;
  }

  goToToday(): void {
    const calendarApi = this.calendarComponent()?.getApi();
    if (calendarApi) {
      calendarApi.today();
    }
  }

  goToPrev(): void {
    const calendarApi = this.calendarComponent()?.getApi();
    if (calendarApi) {
      calendarApi.prev();
    }
  }

  goToNext(): void {
    const calendarApi = this.calendarComponent()?.getApi();
    if (calendarApi) {
      calendarApi.next();
    }
  }
}

import { Injectable } from '@angular/core';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';
import { Capacitor } from '@capacitor/core';
import { Calendar, CalendarEvent } from '@capacitor/calendar';
import { from, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface CalendarSyncResult {
  success: boolean;
  eventId?: string;
  error?: string;
}

export interface CalendarPermissionResult {
  granted: boolean;
  message?: string;
}

/**
 * Service for native calendar integration
 * Supports creating, updating, and deleting calendar events
 */
@Injectable({
  providedIn: 'root'
})
export class NativeCalendarService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();
  private readonly defaultCalendarTitle = 'Atlas Immobilier';

  constructor() { /* no-op */ }

  /**
   * Request calendar permissions
   */
  requestPermissions(): Observable<CalendarPermissionResult> {
    if (!this.isNativePlatform) {
      return of({ granted: false, message: 'Calendar not available on web' });
    }

    return from(Calendar.requestPermissions()).pipe(
      map((result: any) => ({
        granted: result.readWrite,
        message: result.readWrite ? 'Permissions granted' : 'Permissions denied'
      })),
      catchError((error) => {
        console.error('Error requesting calendar permissions:', error);
        return of({ granted: false, message: error.message || 'Permission request failed' });
      })
    );
  }

  /**
   * Check calendar permissions
   */
  checkPermissions(): Observable<CalendarPermissionResult> {
    if (!this.isNativePlatform) {
      return of({ granted: false });
    }

    return from(Calendar.checkPermissions()).pipe(
      map((result: any) => ({ granted: result.readWrite })),
      catchError(() => of({ granted: false }))
    );
  }

  /**
   * Create a calendar event
   */
  createEvent(event: {
    title: string;
    location?: string;
    notes?: string;
    startDate: Date;
    endDate: Date;
    isAllDay?: boolean;
    alertOffsetInMinutes?: number[];
    calendarName?: string;
  }): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    const calendarEvent: CalendarEvent = {
      title: event.title,
      location: event.location,
      notes: event.notes,
      startDate: event.startDate.toISOString(),
      endDate: event.endDate.toISOString(),
      isAllDay: event.isAllDay || false,
      alertOffsetInMinutes: event.alertOffsetInMinutes || [15], // Default 15min reminder
      calendarName: event.calendarName || this.defaultCalendarTitle
    };

    return from(Calendar.createEvent(calendarEvent)).pipe(
      map((result: any) => ({
        success: true,
        eventId: result.id
      })),
      catchError((error) => {
        console.error('Error creating calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to create calendar event'
        });
      })
    );
  }

  /**
   * Update an existing calendar event
   */
  updateEvent(eventId: string, updates: Partial<CalendarEvent>): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.modifyEvent({
      id: eventId,
      ...updates
    })).pipe(
      map(() => ({
        success: true,
        eventId
      })),
      catchError((error) => {
        console.error('Error updating calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to update calendar event'
        });
      })
    );
  }

  /**
   * Delete a calendar event
   */
  deleteEvent(eventId: string): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.deleteEvent({ id: eventId })).pipe(
      map(() => ({
        success: true,
        eventId
      })),
      catchError((error) => {
        console.error('Error deleting calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to delete calendar event'
        });
      })
    );
  }

  /**
   * Get calendar events within a date range
   */
  getEvents(startDate: Date, endDate: Date): Observable<CalendarEvent[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(Calendar.listEventsInRange({
      startDate: startDate.toISOString(),
      endDate: endDate.toISOString()
    })).pipe(
      map((result: any) => result.events || []),
      catchError((error) => {
        console.error('Error fetching calendar events:', error);
        return of([]);
      })
    );
  }

  /**
   * List all available calendars
   */
  listCalendars(): Observable<any[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(Calendar.listCalendars()).pipe(
      map((result: any) => result.calendars || []),
      catchError((error) => {
        console.error('Error listing calendars:', error);
        return of([]);
      })
    );
  }

  /**
   * Create a calendar for the app if it doesn't exist
   */
  createAppCalendar(): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.createCalendar({
      title: this.defaultCalendarTitle,
      color: DS_CHART_FALLBACK_HEX['--ds-marine'],
      isVisible: true
    })).pipe(
      map((result: any) => ({
        success: true,
        eventId: result.id
      })),
      catchError((error) => {
        console.error('Error creating app calendar:', error);
        return of({
          success: false,
          error: error.message || 'Failed to create calendar'
        });
      })
    );
  }

  /**
   * Convert application event to calendar event
   */
  convertToCalendarEvent(
    title: string,
    startDate: Date,
    endDate: Date,
    location?: string,
    notes?: string
  ): CalendarEvent {
    return {
      title,
      startDate: startDate.toISOString(),
      endDate: endDate.toISOString(),
      location,
      notes,
      isAllDay: false,
      alertOffsetInMinutes: [15, 60], // 15min and 1hour before
      calendarName: this.defaultCalendarTitle
    };
  }

  /**
   * Sync a visit/appointment to the calendar
   */
  syncVisitToCalendar(visit: {
    id: string;
    title: string;
    startDate: Date;
    endDate: Date;
    address?: string;
    notes?: string;
  }): Observable<CalendarSyncResult> {
    const event = this.convertToCalendarEvent(
      visit.title,
      visit.startDate,
      visit.endDate,
      visit.address,
      visit.notes
    );

    return this.createEvent({
      title: event.title,
      startDate: new Date(event.startDate),
      endDate: new Date(event.endDate),
      location: event.location,
      notes: event.notes,
      alertOffsetInMinutes: event.alertOffsetInMinutes
    });
  }
}

import { Injectable } from '@angular/core';
import { AppointmentResponse } from './appointment-api.service';
import { Observable } from 'rxjs';
import { HttpClient } from '@angular/common/http';

export interface CalendarSyncConfig {
  provider: 'google' | 'outlook' | 'ical';
  autoSync?: boolean;
  syncInterval?: number;
}

export interface ICalEvent {
  uid: string;
  summary: string;
  description?: string;
  location?: string;
  start: Date;
  end: Date;
  status: 'CONFIRMED' | 'TENTATIVE' | 'CANCELLED';
  organizer?: string;
  attendees?: string[];
}

export interface CalendarSyncStatus {
  provider: string;
  lastSync?: Date;
  syncEnabled: boolean;
  nextSync?: Date;
}

@Injectable({
  providedIn: 'root'
})
export class CalendarSyncService {
  private readonly apiUrl = '/api/v1/calendar-sync';

  constructor(private http: HttpClient) {}

  generateICalendar(appointments: AppointmentResponse[]): string {
    const lines: string[] = [];
    
    lines.push('BEGIN:VCALENDAR');
    lines.push('VERSION:2.0');
    lines.push('PRODID:-//Real Estate CRM//Appointments Calendar//FR');
    lines.push('CALSCALE:GREGORIAN');
    lines.push('METHOD:PUBLISH');
    lines.push('X-WR-CALNAME:Rendez-vous CRM');
    lines.push('X-WR-TIMEZONE:Europe/Paris');
    lines.push('X-WR-CALDESC:Calendrier des rendez-vous du CRM immobilier');

    appointments.forEach(apt => {
      lines.push(...this.generateVEvent(apt));
    });

    lines.push('END:VCALENDAR');
    
    return lines.join('\r\n');
  }

  private generateVEvent(appointment: AppointmentResponse): string[] {
    const lines: string[] = [];
    const startDate = new Date(appointment.startTime);
    const endDate = new Date(appointment.endTime);
    const now = new Date();
    
    lines.push('BEGIN:VEVENT');
    lines.push(`UID:appointment-${appointment.id}@realestate-crm.com`);
    lines.push(`DTSTAMP:${this.formatICalDateTime(now)}`);
    lines.push(`DTSTART:${this.formatICalDateTime(startDate)}`);
    lines.push(`DTEND:${this.formatICalDateTime(endDate)}`);
    
    const summary = `RDV #${appointment.id}${appointment.assignedTo ? ' - ' + appointment.assignedTo : ''}`;
    lines.push(`SUMMARY:${this.escapeICalText(summary)}`);
    
    if (appointment.location) {
      lines.push(`LOCATION:${this.escapeICalText(appointment.location)}`);
    }
    
    if (appointment.notes) {
      const description = `Dossier: #${appointment.dossierId}\\n${appointment.notes}`;
      lines.push(`DESCRIPTION:${this.escapeICalText(description)}`);
    }
    
    const status = appointment.status === 'CANCELLED' ? 'CANCELLED' : 'CONFIRMED';
    lines.push(`STATUS:${status}`);
    
    if (appointment.assignedTo) {
      lines.push(`ORGANIZER;CN=${this.escapeICalText(appointment.assignedTo)}:mailto:${appointment.assignedTo.toLowerCase().replace(/\s+/g, '.')}@company.com`);
    }
    
    lines.push(`CREATED:${this.formatICalDateTime(new Date(appointment.createdAt))}`);
    lines.push(`LAST-MODIFIED:${this.formatICalDateTime(new Date(appointment.updatedAt))}`);
    lines.push(`SEQUENCE:0`);
    lines.push(`TRANSP:OPAQUE`);
    
    lines.push('END:VEVENT');
    
    return lines;
  }

  private formatICalDateTime(date: Date): string {
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const day = String(date.getUTCDate()).padStart(2, '0');
    const hours = String(date.getUTCHours()).padStart(2, '0');
    const minutes = String(date.getUTCMinutes()).padStart(2, '0');
    const seconds = String(date.getUTCSeconds()).padStart(2, '0');
    return `${year}${month}${day}T${hours}${minutes}${seconds}Z`;
  }

  private escapeICalText(text: string): string {
    return text
      .replace(/\\/g, '\\\\')
      .replace(/;/g, '\\;')
      .replace(/,/g, '\\,')
      .replace(/\n/g, '\\n')
      .replace(/\r/g, '');
  }

  downloadICalendar(appointments: AppointmentResponse[], filename?: string): void {
    const icsContent = this.generateICalendar(appointments);
    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename || `appointments_${new Date().toISOString().split('T')[0]}.ics`;
    link.click();
    URL.revokeObjectURL(link.href);
  }

  async importFromICalendar(file: File): Promise<ICalEvent[]> {
    const text = await file.text();
    return this.parseICalendar(text);
  }

  private parseICalendar(icalText: string): ICalEvent[] {
    const events: ICalEvent[] = [];
    const lines = icalText.split(/\r?\n/);
    let currentEvent: Partial<ICalEvent> | null = null;

    for (const line of lines) {
      if (line.startsWith('BEGIN:VEVENT')) {
        currentEvent = {};
      } else if (line.startsWith('END:VEVENT') && currentEvent) {
        if (currentEvent.uid && currentEvent.summary && currentEvent.start && currentEvent.end) {
          events.push(currentEvent as ICalEvent);
        }
        currentEvent = null;
      } else if (currentEvent) {
        const colonIndex = line.indexOf(':');
        if (colonIndex > 0) {
          const key = line.substring(0, colonIndex).split(';')[0];
          const value = line.substring(colonIndex + 1);

          switch (key) {
            case 'UID':
              currentEvent.uid = value;
              break;
            case 'SUMMARY':
              currentEvent.summary = this.unescapeICalText(value);
              break;
            case 'DESCRIPTION':
              currentEvent.description = this.unescapeICalText(value);
              break;
            case 'LOCATION':
              currentEvent.location = this.unescapeICalText(value);
              break;
            case 'DTSTART':
              currentEvent.start = this.parseICalDateTime(value);
              break;
            case 'DTEND':
              currentEvent.end = this.parseICalDateTime(value);
              break;
            case 'STATUS':
              currentEvent.status = value as 'CONFIRMED' | 'TENTATIVE' | 'CANCELLED';
              break;
          }
        }
      }
    }

    return events;
  }

  private parseICalDateTime(value: string): Date {
    const year = parseInt(value.substring(0, 4), 10);
    const month = parseInt(value.substring(4, 6), 10) - 1;
    const day = parseInt(value.substring(6, 8), 10);
    const hours = parseInt(value.substring(9, 11), 10);
    const minutes = parseInt(value.substring(11, 13), 10);
    const seconds = parseInt(value.substring(13, 15), 10);
    
    return new Date(Date.UTC(year, month, day, hours, minutes, seconds));
  }

  private unescapeICalText(text: string): string {
    return text
      .replace(/\\n/g, '\n')
      .replace(/\\,/g, ',')
      .replace(/\\;/g, ';')
