import { Injectable } from '@angular/core';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';
import { Capacitor } from '@capacitor/core';
import { Calendar, CalendarEvent } from '@capacitor/calendar';
import { from, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface CalendarSyncResult {
  success: boolean;
  eventId?: string;
  error?: string;
}

export interface CalendarPermissionResult {
  granted: boolean;
  message?: string;
}

/**
 * Service for native calendar integration
 * Supports creating, updating, and deleting calendar events
 */
@Injectable({
  providedIn: 'root'
})
export class NativeCalendarService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();
  private readonly defaultCalendarTitle = 'Atlas Immobilier';

  constructor() { /* no-op */ }

  /**
   * Request calendar permissions
   */
  requestPermissions(): Observable<CalendarPermissionResult> {
    if (!this.isNativePlatform) {
      return of({ granted: false, message: 'Calendar not available on web' });
    }

    return from(Calendar.requestPermissions()).pipe(
      map((result: any) => ({
        granted: result.readWrite,
        message: result.readWrite ? 'Permissions granted' : 'Permissions denied'
      })),
      catchError((error) => {
        console.error('Error requesting calendar permissions:', error);
        return of({ granted: false, message: error.message || 'Permission request failed' });
      })
    );
  }

  /**
   * Check calendar permissions
   */
  checkPermissions(): Observable<CalendarPermissionResult> {
    if (!this.isNativePlatform) {
      return of({ granted: false });
    }

    return from(Calendar.checkPermissions()).pipe(
      map((result: any) => ({ granted: result.readWrite })),
      catchError(() => of({ granted: false }))
    );
  }

  /**
   * Create a calendar event
   */
  createEvent(event: {
    title: string;
    location?: string;
    notes?: string;
    startDate: Date;
    endDate: Date;
    isAllDay?: boolean;
    alertOffsetInMinutes?: number[];
    calendarName?: string;
  }): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    const calendarEvent: CalendarEvent = {
      title: event.title,
      location: event.location,
      notes: event.notes,
      startDate: event.startDate.toISOString(),
      endDate: event.endDate.toISOString(),
      isAllDay: event.isAllDay || false,
      alertOffsetInMinutes: event.alertOffsetInMinutes || [15], // Default 15min reminder
      calendarName: event.calendarName || this.defaultCalendarTitle
    };

    return from(Calendar.createEvent(calendarEvent)).pipe(
      map((result: any) => ({
        success: true,
        eventId: result.id
      })),
      catchError((error) => {
        console.error('Error creating calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to create calendar event'
        });
      })
    );
  }

  /**
   * Update an existing calendar event
   */
  updateEvent(eventId: string, updates: Partial<CalendarEvent>): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.modifyEvent({
      id: eventId,
      ...updates
    })).pipe(
      map(() => ({
        success: true,
        eventId
      })),
      catchError((error) => {
        console.error('Error updating calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to update calendar event'
        });
      })
    );
  }

  /**
   * Delete a calendar event
   */
  deleteEvent(eventId: string): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.deleteEvent({ id: eventId })).pipe(
      map(() => ({
        success: true,
        eventId
      })),
      catchError((error) => {
        console.error('Error deleting calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to delete calendar event'
        });
      })
    );
  }

  /**
   * Get calendar events within a date range
   */
  getEvents(startDate: Date, endDate: Date): Observable<CalendarEvent[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(Calendar.listEventsInRange({
      startDate: startDate.toISOString(),
      endDate: endDate.toISOString()
    })).pipe(
      map((result: any) => result.events || []),
      catchError((error) => {
        console.error('Error fetching calendar events:', error);
        return of([]);
      })
    );
  }

  /**
   * List all available calendars
   */
  listCalendars(): Observable<any[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(Calendar.listCalendars()).pipe(
      map((result: any) => result.calendars || []),
      catchError((error) => {
        console.error('Error listing calendars:', error);
        return of([]);
      })
    );
  }

  /**
   * Create a calendar for the app if it doesn't exist
   */
  createAppCalendar(): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.createCalendar({
      title: this.defaultCalendarTitle,
      color: DS_CHART_FALLBACK_HEX['--ds-marine'],
      isVisible: true
    })).pipe(
      map((result: any) => ({
        success: true,
        eventId: result.id
      })),
      catchError((error) => {
        console.error('Error creating app calendar:', error);
        return of({
          success: false,
          error: error.message || 'Failed to create calendar'
        });
      })
    );
  }

  /**
   * Convert application event to calendar event
   */
  convertToCalendarEvent(
    title: string,
    startDate: Date,
    endDate: Date,
    location?: string,
    notes?: string
  ): CalendarEvent {
    return {
      title,
      startDate: startDate.toISOString(),
      endDate: endDate.toISOString(),
      location,
      notes,
      isAllDay: false,
      alertOffsetInMinutes: [15, 60], // 15min and 1hour before
      calendarName: this.defaultCalendarTitle
    };
  }

  /**
   * Sync a visit/appointment to the calendar
   */
  syncVisitToCalendar(visit: {
    id: string;
    title: string;
    startDate: Date;
    endDate: Date;
    address?: string;
    notes?: string;
  }): Observable<CalendarSyncResult> {
    const event = this.convertToCalendarEvent(
      visit.title,
      visit.startDate,
      visit.endDate,
      visit.address,
      visit.notes
    );

    return this.createEvent({
      title: event.title,
      startDate: new Date(event.startDate),
      endDate: new Date(event.endDate),
      location: event.location,
      notes: event.notes,
      alertOffsetInMinutes: event.alertOffsetInMinutes
    });
  }
}

import { Injectable } from '@angular/core';
import { AppointmentResponse } from './appointment-api.service';
import { Observable } from 'rxjs';
import { HttpClient } from '@angular/common/http';

export interface CalendarSyncConfig {
  provider: 'google' | 'outlook' | 'ical';
  autoSync?: boolean;
  syncInterval?: number;
}

export interface ICalEvent {
  uid: string;
  summary: string;
  description?: string;
  location?: string;
  start: Date;
  end: Date;
  status: 'CONFIRMED' | 'TENTATIVE' | 'CANCELLED';
  organizer?: string;
  attendees?: string[];
}

export interface CalendarSyncStatus {
  provider: string;
  lastSync?: Date;
  syncEnabled: boolean;
  nextSync?: Date;
}

@Injectable({
  providedIn: 'root'
})
export class CalendarSyncService {
  private readonly apiUrl = '/api/v1/calendar-sync';

  constructor(private http: HttpClient) {}

  generateICalendar(appointments: AppointmentResponse[]): string {
    const lines: string[] = [];
    
    lines.push('BEGIN:VCALENDAR');
    lines.push('VERSION:2.0');
    lines.push('PRODID:-//Real Estate CRM//Appointments Calendar//FR');
    lines.push('CALSCALE:GREGORIAN');
    lines.push('METHOD:PUBLISH');
    lines.push('X-WR-CALNAME:Rendez-vous CRM');
    lines.push('X-WR-TIMEZONE:Europe/Paris');
    lines.push('X-WR-CALDESC:Calendrier des rendez-vous du CRM immobilier');

    appointments.forEach(apt => {
      lines.push(...this.generateVEvent(apt));
    });

    lines.push('END:VCALENDAR');
    
    return lines.join('\r\n');
  }

  private generateVEvent(appointment: AppointmentResponse): string[] {
    const lines: string[] = [];
    const startDate = new Date(appointment.startTime);
    const endDate = new Date(appointment.endTime);
    const now = new Date();
    
    lines.push('BEGIN:VEVENT');
    lines.push(`UID:appointment-${appointment.id}@realestate-crm.com`);
    lines.push(`DTSTAMP:${this.formatICalDateTime(now)}`);
    lines.push(`DTSTART:${this.formatICalDateTime(startDate)}`);
    lines.push(`DTEND:${this.formatICalDateTime(endDate)}`);
    
    const summary = `RDV #${appointment.id}${appointment.assignedTo ? ' - ' + appointment.assignedTo : ''}`;
    lines.push(`SUMMARY:${this.escapeICalText(summary)}`);
    
    if (appointment.location) {
      lines.push(`LOCATION:${this.escapeICalText(appointment.location)}`);
    }
    
    if (appointment.notes) {
      const description = `Dossier: #${appointment.dossierId}\\n${appointment.notes}`;
      lines.push(`DESCRIPTION:${this.escapeICalText(description)}`);
    }
    
    const status = appointment.status === 'CANCELLED' ? 'CANCELLED' : 'CONFIRMED';
    lines.push(`STATUS:${status}`);
    
    if (appointment.assignedTo) {
      lines.push(`ORGANIZER;CN=${this.escapeICalText(appointment.assignedTo)}:mailto:${appointment.assignedTo.toLowerCase().replace(/\s+/g, '.')}@company.com`);
    }
    
    lines.push(`CREATED:${this.formatICalDateTime(new Date(appointment.createdAt))}`);
    lines.push(`LAST-MODIFIED:${this.formatICalDateTime(new Date(appointment.updatedAt))}`);
    lines.push(`SEQUENCE:0`);
    lines.push(`TRANSP:OPAQUE`);
    
    lines.push('END:VEVENT');
    
    return lines;
  }

  private formatICalDateTime(date: Date): string {
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const day = String(date.getUTCDate()).padStart(2, '0');
    const hours = String(date.getUTCHours()).padStart(2, '0');
    const minutes = String(date.getUTCMinutes()).padStart(2, '0');
    const seconds = String(date.getUTCSeconds()).padStart(2, '0');
    return `${year}${month}${day}T${hours}${minutes}${seconds}Z`;
  }

  private escapeICalText(text: string): string {
    return text
      .replace(/\\/g, '\\\\')
      .replace(/;/g, '\\;')
      .replace(/,/g, '\\,')
      .replace(/\n/g, '\\n')
      .replace(/\r/g, '');
  }

  downloadICalendar(appointments: AppointmentResponse[], filename?: string): void {
    const icsContent = this.generateICalendar(appointments);
    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename || `appointments_${new Date().toISOString().split('T')[0]}.ics`;
    link.click();
    URL.revokeObjectURL(link.href);
  }

  async importFromICalendar(file: File): Promise<ICalEvent[]> {
    const text = await file.text();
    return this.parseICalendar(text);
  }

  private parseICalendar(icalText: string): ICalEvent[] {
    const events: ICalEvent[] = [];
    const lines = icalText.split(/\r?\n/);
    let currentEvent: Partial<ICalEvent> | null = null;

    for (const line of lines) {
      if (line.startsWith('BEGIN:VEVENT')) {
        currentEvent = {};
      } else if (line.startsWith('END:VEVENT') && currentEvent) {
        if (currentEvent.uid && currentEvent.summary && currentEvent.start && currentEvent.end) {
          events.push(currentEvent as ICalEvent);
        }
        currentEvent = null;
      } else if (currentEvent) {
        const colonIndex = line.indexOf(':');
        if (colonIndex > 0) {
          const key = line.substring(0, colonIndex).split(';')[0];
          const value = line.substring(colonIndex + 1);

          switch (key) {
            case 'UID':
              currentEvent.uid = value;
              break;
            case 'SUMMARY':
              currentEvent.summary = this.unescapeICalText(value);
              break;
            case 'DESCRIPTION':
              currentEvent.description = this.unescapeICalText(value);
              break;
            case 'LOCATION':
              currentEvent.location = this.unescapeICalText(value);
              break;
            case 'DTSTART':
              currentEvent.start = this.parseICalDateTime(value);
              break;
            case 'DTEND':
              currentEvent.end = this.parseICalDateTime(value);
              break;
            case 'STATUS':
              currentEvent.status = value as 'CONFIRMED' | 'TENTATIVE' | 'CANCELLED';
              break;
          }
        }
      }
    }

    return events;
  }

  private parseICalDateTime(value: string): Date {
    const year = parseInt(value.substring(0, 4), 10);
    const month = parseInt(value.substring(4, 6), 10) - 1;
    const day = parseInt(value.substring(6, 8), 10);
    const hours = parseInt(value.substring(9, 11), 10);
    const minutes = parseInt(value.substring(11, 13), 10);
    const seconds = parseInt(value.substring(13, 15), 10);
    
    return new Date(Date.UTC(year, month, day, hours, minutes, seconds));
  }

  private unescapeICalText(text: string): string {
    return text
      .replace(/\\n/g, '\n')
      .replace(/\\,/g, ',')
      .replace(/\\;/g, ';')
      .replace(/\\\\/g, '\\');
  }

  getGoogleCalendarAuthUrl(): Observable<{ authUrl: string }> {
    return this.http.get<{ authUrl: string }>(`${this.apiUrl}/google/auth-url`);
  }

  getOutlookAuthUrl(): Observable<{ authUrl: string }> {
    return this.http.get<{ authUrl: string }>(`${this.apiUrl}/outlook/auth-url`);
  }

  handleOAuthCallback(provider: 'google' | 'outlook', code: string): Observable<{ success: boolean }> {
    return this.http.post<{ success: boolean }>(`${this.apiUrl}/${provider}/callback`, { code });
  }

  getSyncStatus(): Observable<CalendarSyncStatus[]> {
    return this.http.get<CalendarSyncStatus[]>(`${this.apiUrl}/status`);
  }

  enableSync(provider: 'google' | 'outlook', config: CalendarSyncConfig): Observable<{ success: boolean }> {
    return this.http.post<{ success: boolean }>(`${this.apiUrl}/${provider}/enable`, config);
  }

  disableSync(provider: 'google' | 'outlook'): Observable<{ success: boolean }> {
    return this.http.post<{ success: boolean }>(`${this.apiUrl}/${provider}/disable`, {});
  }

  triggerManualSync(provider: 'google' | 'outlook'): Observable<{ success: boolean; syncedCount: number }> {
    return this.http.post<{ success: boolean; syncedCount: number }>(`${this.apiUrl}/${provider}/sync`, {});
  }

  getICalendarFeedUrl(): Observable<{ feedUrl: string; token: string }> {
    return this.http.get<{ feedUrl: string; token: string }>(`${this.apiUrl}/ical/feed-url`);
  }

  regenerateICalendarToken(): Observable<{ feedUrl: string; token: string }> {
    return this.http.post<{ feedUrl: string; token: string }>(`${this.apiUrl}/ical/regenerate-token`, {});
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

export interface VoipConfiguration {
  enabled: boolean;
  provider: 'twilio' | 'asterisk' | 'custom' | null;
  clickToCallUrl?: string;
  apiKey?: string;
  phoneNumberFormat?: string;
}

export interface CallSession {
  callId: string;
  phoneNumber: string;
  contactName: string;
  status: 'initiating' | 'ringing' | 'connected' | 'ended' | 'failed';
  startTime: Date;
  endTime?: Date;
  duration?: number;
}

@Injectable({
  providedIn: 'root'
})
export class VoipService {
  private readonly VOIP_CONFIG_KEY = 'voip_configuration';
  
  private configSubject = new BehaviorSubject<VoipConfiguration | null>(null);
  public config$ = this.configSubject.asObservable();
  
  private activeCallSubject = new BehaviorSubject<CallSession | null>(null);
  public activeCall$ = this.activeCallSubject.asObservable();
  
  private callHistorySubject = new BehaviorSubject<CallSession[]>([]);
  public callHistory$ = this.callHistorySubject.asObservable();

  constructor() {
    this.loadConfiguration();
  }

  private loadConfiguration(): void {
    const stored = localStorage.getItem(this.VOIP_CONFIG_KEY);
    if (stored) {
      try {
        const config = JSON.parse(stored) as VoipConfiguration;
        this.configSubject.next(config);
      } catch (e) {
        console.error('Failed to load VoIP configuration', e);
      }
    } else {
      const defaultConfig: VoipConfiguration = {
        enabled: false,
        provider: null
      };
      this.configSubject.next(defaultConfig);
    }
  }

  isConfigured(): boolean {
    const config = this.configSubject.value;
    return config !== null && config.enabled && config.provider !== null;
  }

  getConfiguration(): VoipConfiguration | null {
    return this.configSubject.value;
  }

  setConfiguration(config: VoipConfiguration): void {
    this.configSubject.next(config);
    localStorage.setItem(this.VOIP_CONFIG_KEY, JSON.stringify(config));
  }

  initiateCall(phoneNumber: string, contactName: string): void {
    const config = this.configSubject.value;
    
    if (!this.isConfigured() || !config) {
      console.error('VoIP is not configured');
      return;
    }

    const callSession: CallSession = {
      callId: this.generateCallId(),
      phoneNumber,
      contactName,
      status: 'initiating',
      startTime: new Date()
    };

    this.activeCallSubject.next(callSession);

    switch (config.provider) {
      case 'twilio':
        this.initiateTwilioCall(phoneNumber);
        break;
      case 'asterisk':
        this.initiateAsteriskCall(phoneNumber);
        break;
      case 'custom':
        this.initiateCustomCall(phoneNumber, config.clickToCallUrl);
        break;
      default:
        this.initiateClickToCall(phoneNumber, config.clickToCallUrl);
    }

    setTimeout(() => {
      this.updateCallStatus('ringing');
    }, 1000);

    setTimeout(() => {
      this.updateCallStatus('connected');
    }, 3000);
  }

  private initiateTwilioCall(phoneNumber: string): void {
    console.log('Initiating Twilio call to:', phoneNumber);
  }

  private initiateAsteriskCall(phoneNumber: string): void {
    console.log('Initiating Asterisk call to:', phoneNumber);
  }

  private initiateCustomCall(phoneNumber: string, clickToCallUrl?: string): void {
    if (clickToCallUrl) {
      const url = clickToCallUrl.replace('{phone}', encodeURIComponent(phoneNumber));
      window.open(url, '_blank', 'noopener,noreferrer');
    } else {
      console.warn('No click-to-call URL configured');
    }
  }

  private initiateClickToCall(phoneNumber: string, clickToCallUrl?: string): void {
    if (clickToCallUrl) {
      const url = clickToCallUrl.replace('{phone}', encodeURIComponent(phoneNumber));
      window.location.href = url;
    } else {
      window.location.href = `tel:${phoneNumber}`;
    }
  }

  updateCallStatus(status: CallSession['status']): void {
    const activeCall = this.activeCallSubject.value;
    if (!activeCall) {
      return;
    }

    const updatedCall: CallSession = {
      ...activeCall,
      status
    };

    if (status === 'ended' || status === 'failed') {
      updatedCall.endTime = new Date();
      updatedCall.duration = Math.floor(
        (updatedCall.endTime.getTime() - updatedCall.startTime.getTime()) / 1000
      );
      
      this.addToCallHistory(updatedCall);
      this.activeCallSubject.next(null);
    } else {
      this.activeCallSubject.next(updatedCall);
    }
  }

  endCall(): void {
    this.updateCallStatus('ended');
  }

  private addToCallHistory(call: CallSession): void {
    const history = this.callHistorySubject.value;
    const updatedHistory = [call, ...history].slice(0, 50);
    this.callHistorySubject.next(updatedHistory);
  }

  getCallHistory(): CallSession[] {
    return this.callHistorySubject.value;
  }

  clearCallHistory(): void {
    this.callHistorySubject.next([]);
  }

  private generateCallId(): string {
    return `call_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  formatPhoneNumber(phoneNumber: string): string {
    const config = this.configSubject.value;
    if (!config || !config.phoneNumberFormat) {
      return phoneNumber;
    }

    const cleaned = phoneNumber.replace(/\D/g, '');
    
    if (config.phoneNumberFormat === 'international' && cleaned.length === 10) {
      return `+33${cleaned.substring(1)}`;
    }
    
    return phoneNumber;
  }
}

