export type ChartAnimationType = 'none' | 'fade' | 'slide' | 'stagger' | 'progressive';

export type ChartLegendPosition = 'top' | 'bottom' | 'left' | 'right';

export type ChartLegendAlign = 'start' | 'center' | 'end';

export type ChartTooltipMode = 'index' | 'nearest' | 'point' | 'dataset' | 'x' | 'y';

export type ChartAxisType = 'linear' | 'logarithmic' | 'category' | 'time';

export interface ChartDataPoint {
  x: number | string | Date;
  y: number;
  label?: string;
  metadata?: Record<string, any>;
}

export interface ChartDataset {
  label: string;
  data: number[] | ChartDataPoint[];
  backgroundColor?: string | string[];
  borderColor?: string | string[];
  borderWidth?: number;
  fill?: boolean;
  tension?: number;
  pointRadius?: number;
  pointHoverRadius?: number;
  pointStyle?: 'circle' | 'cross' | 'crossRot' | 'dash' | 'line' | 'rect' | 'rectRounded' | 'rectRot' | 'star' | 'triangle';
  borderDash?: number[];
  hidden?: boolean;
  stack?: string;
  order?: number;
}

export interface ChartLegendConfig {
  display: boolean;
  position: ChartLegendPosition;
  align: ChartLegendAlign;
  labels?: {
    color?: string;
    font?: ChartFontConfig;
    padding?: number;
    usePointStyle?: boolean;
    pointStyle?: string;
    boxWidth?: number;
    boxHeight?: number;
  };
}

export interface ChartTooltipConfig {
  enabled: boolean;
  mode?: ChartTooltipMode;
  backgroundColor?: string;
  titleColor?: string;
  bodyColor?: string;
  borderColor?: string;
  borderWidth?: number;
  padding?: number;
  cornerRadius?: number;
  displayColors?: boolean;
  titleFont?: ChartFontConfig;
  bodyFont?: ChartFontConfig;
  callbacks?: {
    title?: (context: any) => string | string[];
    label?: (context: any) => string | string[];
    footer?: (context: any) => string | string[];
  };
}

export interface ChartFontConfig {
  family?: string;
  size?: number;
  weight?: number | string;
  style?: 'normal' | 'italic' | 'oblique';
  lineHeight?: number | string;
}

export interface ChartGridConfig {
  display: boolean;
  color?: string;
  drawBorder?: boolean;
  drawTicks?: boolean;
  tickLength?: number;
  offset?: boolean;
  lineWidth?: number;
  borderDash?: number[];
}

export interface ChartTickConfig {
  color?: string;
  font?: ChartFontConfig;
  padding?: number;
  callback?: (value: any, index: number, ticks: any[]) => string;
  display?: boolean;
  autoSkip?: boolean;
  maxRotation?: number;
  minRotation?: number;
}

export interface ChartScaleConfig {
  type?: ChartAxisType;
  display?: boolean;
  position?: 'left' | 'right' | 'top' | 'bottom';
  grid?: ChartGridConfig;
  ticks?: ChartTickConfig;
  title?: {
    display?: boolean;
    text?: string;
    color?: string;
    font?: ChartFontConfig;
    padding?: number;
  };
  border?: {
    display?: boolean;
    color?: string;
    width?: number;
  };
  stacked?: boolean;
  beginAtZero?: boolean;
  min?: number;
  max?: number;
  suggestedMin?: number;
  suggestedMax?: number;
}

export interface ChartAnimationConfig {
  duration?: number;
  easing?: 'linear' | 'easeInQuad' | 'easeOutQuad' | 'easeInOutQuad' | 'easeInCubic' | 'easeOutCubic' | 'easeInOutCubic' | 'easeInQuart' | 'easeOutQuart' | 'easeInOutQuart';
  delay?: number;
  loop?: boolean;
  onComplete?: () => void;
  onProgress?: (animation: any) => void;
}

export interface ChartInteractionConfig {
  mode?: ChartTooltipMode;
  intersect?: boolean;
  axis?: 'x' | 'y' | 'xy' | 'r';
}

export interface ChartPluginConfig {
  legend?: ChartLegendConfig;
  tooltip?: ChartTooltipConfig;
  title?: {
    display?: boolean;
    text?: string | string[];
    color?: string;
    font?: ChartFontConfig;
    padding?: number;
    align?: 'start' | 'center' | 'end';
  };
  subtitle?: {
    display?: boolean;
    text?: string | string[];
    color?: string;
    font?: ChartFontConfig;
    padding?: number;
    align?: 'start' | 'center' | 'end';
  };
}

export interface ChartOptions {
  responsive?: boolean;
  maintainAspectRatio?: boolean;
  aspectRatio?: number;
  resizeDelay?: number;
  devicePixelRatio?: number;
  plugins?: ChartPluginConfig;
  scales?: {
    x?: ChartScaleConfig;
    y?: ChartScaleConfig;
    [key: string]: ChartScaleConfig | undefined;
  };
  animation?: ChartAnimationConfig | boolean;
  interaction?: ChartInteractionConfig;
  onClick?: (event: any, elements: any[]) => void;
  onHover?: (event: any, elements: any[]) => void;
  locale?: string;
}

export interface ChartConfig {
  type: ChartType;
  labels: string[];
  datasets: ChartDataset[];
  options?: ChartOptions;
}

export interface ChartExportOptions {
  filename?: string;
  format?: 'svg' | 'png' | 'jpeg' | 'webp';
  quality?: number;
  width?: number;
  height?: number;
  backgroundColor?: string;
}

