}

export interface ChartFilterConfig {
  startDate?: Date;
  endDate?: Date;
  categories?: string[];
  minValue?: number;
  maxValue?: number;
  aggregation?: 'sum' | 'average' | 'count' | 'min' | 'max';
  groupBy?: 'day' | 'week' | 'month' | 'quarter' | 'year';
}

export interface ChartDataTransform {
  filter?: (data: any[]) => any[];
  map?: (data: any[]) => any[];
  reduce?: (data: any[], initial: any) => any;
  sort?: (a: any, b: any) => number;
  aggregate?: (data: any[], key: string) => any;
}

export interface ChartMetadata {
  title?: string;
  subtitle?: string;
  description?: string;
  source?: string;
  lastUpdated?: Date;
  author?: string;
  tags?: string[];
}

export interface ChartEventData {
  event: MouseEvent | TouchEvent;
  elements: any[];
  dataset?: ChartDataset;
  dataIndex?: number;
  value?: number;
  label?: string;
}

export interface ChartColorScheme {
  name: string;
  colors: string[];
  alphaColors?: string[];
  accessible: boolean;
  wcagLevel: 'AA' | 'AAA';
  darkMode?: boolean;
}

export interface ChartSeriesConfig {
  name: string;
  type?: ChartType;
  data: number[] | ChartDataPoint[];
  color?: string;
  visible?: boolean;
  yAxisID?: string;
  stack?: string;
}

export interface ChartAxisFormatter {
  format: (value: any) => string;
  parse?: (value: string) => any;
}

export interface ChartAnnotation {
  type: 'line' | 'box' | 'point' | 'label';
  xMin?: number | string;
  xMax?: number | string;
  yMin?: number;
  yMax?: number;
  borderColor?: string;
  backgroundColor?: string;
  borderWidth?: number;
  label?: {
    content?: string;
    enabled?: boolean;
    position?: 'start' | 'center' | 'end';
  };
}

export interface ChartLoadingState {
  loading: boolean;
  progress?: number;
  message?: string;
}

export interface ChartErrorState {
  error: boolean;
  message?: string;
  code?: string;
  retryable?: boolean;
}

export interface ChartEmptyState {
  title?: string;
  message?: string;
  icon?: string;
  actionLabel?: string;
  onAction?: () => void;
}

