import { Component, OnInit, OnChanges, SimpleChanges, OnDestroy, input, output } from '@angular/core';
import { MatTableDataSource } from '@angular/material/table';
import { BreakpointObserver, Breakpoints } from '@angular/cdk/layout';
import { SelectionModel } from '@angular/cdk/collections';
import { Subject, takeUntil } from 'rxjs';
import { listStaggerAnimation } from '../animations/list-animations';
import { MatIconButton } from '@angular/material/button';
import { MatIcon } from '@angular/material/icon';
import { MatCheckbox } from '@angular/material/checkbox';
import { CdkVirtualScrollViewport, CdkFixedSizeVirtualScroll, CdkVirtualForOf } from '@angular/cdk/scrolling';
import { DsCardComponent } from '../design-system';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';
import { DsTableComponent, DsColumn, DsRowAction, DsSortEvent } from '../design-system/primitives/ds-table/ds-table.component';

export interface ColumnConfig {
  key: string;
  header: string;
  sortable?: boolean;
  type?: 'text' | 'number' | 'date' | 'boolean' | 'custom';
  format?: (value: unknown, row: unknown) => string;
  resizable?: boolean;
  width?: string;
  minWidth?: string;
}

export interface RowAction {
  icon: string;
  tooltip: string;
  action: 'view' | 'edit' | 'delete' | string;
  color?: string;
  show?: (row: unknown) => boolean;
}

export interface PaginationData {
  number: number;
  totalPages: number;
  first: boolean;
  last: boolean;
}

@Component({
    selector: 'app-generic-table',
    templateUrl: './generic-table.component.html',
    styleUrls: ['./generic-table.component.scss'],
    animations: [listStaggerAnimation],
    imports: [MatIconButton, MatIcon, MatCheckbox, CdkVirtualScrollViewport, CdkFixedSizeVirtualScroll, CdkVirtualForOf, DsCardComponent, DsTableComponent]
})
export class GenericTableComponent implements OnInit, OnChanges, OnDestroy {
  readonly columns = input<ColumnConfig[]>([]);
  readonly data = input<unknown[]>([]);
  readonly showActions = input(true);
  readonly actions = input<RowAction[]>([
    { icon: 'visibility', tooltip: 'Voir', action: 'view', color: 'primary' },
    { icon: 'edit', tooltip: 'Modifier', action: 'edit', color: 'accent' },
    { icon: 'delete', tooltip: 'Supprimer', action: 'delete', color: 'warn' }
  ]);
  readonly pageSize = input(10);
  readonly pageSizeOptions = input<number[]>([5, 10, 25, 50, 100]);
  readonly showPagination = input(true);
  readonly enableSort = input(true);
  readonly rowClickable = input(false);
  readonly enableRowSelection = input(false);
  readonly stickyHeader = input(true);
  readonly enableVirtualScroll = input(false);
  readonly virtualScrollItemSize = input(48);
  readonly useKebabMenu = input(false);
  readonly showTableHeader = input(false);
  readonly showInlinePagination = input(false);
  readonly loading = input(false);
  readonly paginationData = input<PaginationData>();
  readonly counterSingular = input('élément');
  readonly counterPlural = input('éléments');
  readonly enableExport = input(false);
  readonly exportConfig = input<{
    title?: string;
    filename?: string;
    logo?: string;
    primaryColor?: string;
    secondaryColor?: string;
  }>();

  readonly rowAction = output<{
    action: string;
    row: unknown;
  }>();
  readonly rowClick = output<unknown>();
  readonly selectionChange = output<unknown[]>();
  readonly paginationChange = output<'previous' | 'next'>();
  readonly exportRequest = output<{
    format: 'pdf' | 'excel' | 'print';
    data: unknown[];
  }>();

  dataSource = new MatTableDataSource<unknown>([]);
  selection = new SelectionModel<unknown>(true, []);
  isMobile = false;
  currentClientPage = 0;

  private destroy$ = new Subject<void>();

  get dsColumns(): DsColumn<Record<string, unknown>>[] {
    return this.columns().map((column) => ({
      key: column.key,
      header: column.header,
      sortable: column.sortable !== false && this.enableSort(),
      width: column.width,
      cell: (row: Record<string, unknown>) => this.formatValue(row[column.key], column, row),
    }));
  }

  get dsRows(): Record<string, unknown>[] {
    if (!this.showPagination() || this.showInlinePagination()) {
      return this.dataSource.data as Record<string, unknown>[];
    }
    const pageSize = this.pageSize();
    const start = this.currentClientPage * pageSize;
    return this.dataSource.data.slice(start, start + pageSize) as Record<string, unknown>[];
  }

  get dsSelectedRows(): Record<string, unknown>[] {
    return this.selection.selected as Record<string, unknown>[];
  }

  get dsClientTotalPages(): number {
    if (!this.showPagination() || this.showInlinePagination()) {
      return 1;
    }
    return Math.max(1, Math.ceil(this.dataSource.data.length / this.pageSize()));
  }

  get dsClientPageNumber(): number {
    return this.currentClientPage + 1;
  }

  get dsRowActions(): DsRowAction<Record<string, unknown>>[] {
    if (!this.showActions()) {
      return [];
    }
    return this.actions().map((action) => ({
      action: action.action,
      label: action.tooltip,
      ariaLabel: action.tooltip || action.action,
      icon: this.mapMaterialIconToDs(action.icon),
      show: action.show as ((row: Record<string, unknown>) => boolean) | undefined,
    }));
  }

  constructor(private breakpointObserver: BreakpointObserver) {}

  ngOnInit(): void {
    this.dataSource.data = this.data();
    this.observeBreakpoints();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['data']) {
      this.dataSource.data = this.data();
      this.selection.clear();
      this.currentClientPage = 0;
    }
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  observeBreakpoints(): void {
    this.breakpointObserver
      .observe([Breakpoints.XSmall, Breakpoints.Small])
      .pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        this.isMobile = result.matches;
      });
  }

  onAction(action: string, row: unknown): void {
    this.rowAction.emit({ action, row });
  }

  shouldShowAction(action: RowAction, row: unknown): boolean {
    if (action.show) {
      return action.show(row);
    }
    return true;
  }

  formatValue(value: unknown, column: ColumnConfig, row: unknown): string {
    if (column.format) {
      return column.format(value, row);
    }

    if (value === null || value === undefined) {
      return '';
    }

    switch (column.type) {
      case 'date':
        return new Date(value as string | number | Date).toLocaleDateString();
      case 'boolean':
        return value ? 'Oui' : 'Non';
      case 'number':
        return value.toString();
      default:
        return value.toString();
    }
  }

  onRowClick(row: unknown): void {
    if (this.rowClickable()) {
      this.rowClick.emit(row);
    }
  }

  isAllSelected(): boolean {
    const numSelected = this.selection.selected.length;
    const numRows = this.dataSource.data.length;
    return numSelected === numRows && numRows > 0;
  }

  toggleAllRows(): void {
    if (this.isAllSelected()) {
      this.selection.clear();
    } else {
      this.selection.select(...this.dataSource.data);
    }
    this.emitSelectionChange();
  }

  toggleRow(row: unknown): void {
    this.selection.toggle(row);
    this.emitSelectionChange();
  }

  emitSelectionChange(): void {
    this.selectionChange.emit(this.selection.selected);
  }

  getRowValue(row: unknown, columnKey: string): unknown {
    return (row as any)[columnKey];
  }

  trackByColumnKey(index: number, column: ColumnConfig): string {
    return column.key;
  }

  trackByAction(index: number, action: RowAction): string {
    return action.action;
  }

  trackByRowId(index: number, row: unknown): number | string {
    return (row as any)['id'] ?? index;
  }

  onPaginationChange(direction: 'previous' | 'next'): void {
    if (this.showInlinePagination()) {
      this.paginationChange.emit(direction);
      return;
    }
    const totalPages = this.dsClientTotalPages;
    if (direction === 'previous') {
      this.currentClientPage = Math.max(0, this.currentClientPage - 1);
    } else {
      this.currentClientPage = Math.min(totalPages - 1, this.currentClientPage + 1);
    }
  }

  onDsSort(event: DsSortEvent): void {
    const direction = event.direction === 'asc' ? 1 : -1;
    const sorted = [...this.dataSource.data].sort((a, b) => {
      const aValue = (a as Record<string, unknown>)[event.column];
      const bValue = (b as Record<string, unknown>)[event.column];
      if (aValue == null && bValue == null) return 0;
      if (aValue == null) return -1 * direction;
      if (bValue == null) return 1 * direction;
      return String(aValue).localeCompare(String(bValue), undefined, { numeric: true }) * direction;
    });
    this.dataSource.data = sorted;
  }

  onDsSelectionChange(rows: Record<string, unknown>[]): void {
    this.selection.clear();
    this.selection.select(...(rows as unknown[]));
    this.emitSelectionChange();
  }

  private mapMaterialIconToDs(icon: string): string {
    const iconMap: Record<string, string> = {
      visibility: 'eye',
      edit: 'edit',
      delete: 'trash-2',
      more_vert: 'more-horizontal',
      picture_as_pdf: 'file-text',
      table_chart: 'table',
      print: 'printer',
    };
    return iconMap[icon] || 'more-horizontal';
  }

  getActionColor(color?: string): string {
    const colorMap: { [key: string]: string } = {
      primary: DS_CHART_FALLBACK_HEX['--ds-marine'],
      accent: DS_CHART_FALLBACK_HEX['--ds-primary'],
      warn: DS_CHART_FALLBACK_HEX['--ds-error'],
      success: DS_CHART_FALLBACK_HEX['--ds-success'],
      error: DS_CHART_FALLBACK_HEX['--ds-error'],
      warning: DS_CHART_FALLBACK_HEX['--ds-warning'],
    };
    return color ? (colorMap[color] || color) : colorMap['primary'];
  }

  hasSelection(): boolean {
    return this.selection.hasValue() && this.selection.selected.length > 0;
  }

  getSelectedCount(): number {
    return this.selection.selected.length;
  }

  exportToPDF(): void {
    const dataToExport = this.hasSelection() ? this.selection.selected : this.dataSource.data;
    this.exportRequest.emit({ format: 'pdf', data: dataToExport });
  }

  exportToExcel(): void {
    const dataToExport = this.hasSelection() ? this.selection.selected : this.dataSource.data;
    this.exportRequest.emit({ format: 'excel', data: dataToExport });
  }

  printTable(): void {
    const dataToExport = this.hasSelection() ? this.selection.selected : this.dataSource.data;
    this.exportRequest.emit({ format: 'print', data: dataToExport });
  }
}

import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';

const DS_MARINE = DS_CHART_FALLBACK_HEX['--ds-marine'];
const DS_PRIMARY = DS_CHART_FALLBACK_HEX['--ds-primary'];
const DS_BG = DS_CHART_FALLBACK_HEX['--ds-bg'];
const DS_TEXT_MUTED = DS_CHART_FALLBACK_HEX['--ds-text-muted'];
const DS_DIVIDER = DS_CHART_FALLBACK_HEX['--ds-divider'];

export interface ExportProgress {
  stage: 'preparing' | 'generating' | 'complete' | 'error';
  progress: number;
  message: string;
  error?: string;
}

export interface ExportConfig {
  title: string;
  filename: string;
  orientation?: 'portrait' | 'landscape';
  logo?: string;
  primaryColor?: string;
  secondaryColor?: string;
  includeDate?: boolean;
  includePageNumbers?: boolean;
}

export interface ColumnDef {
  key: string;
  header: string;
  width?: number;
}

@Injectable({
  providedIn: 'root'
})
export class ExportService {
  private progressSubject = new Subject<ExportProgress>();
  public progress$ = this.progressSubject.asObservable();

  private defaultConfig: ExportConfig = {
    title: 'Export',
    filename: 'export',
    orientation: 'portrait',
    primaryColor: DS_MARINE,
    secondaryColor: DS_PRIMARY,
    includeDate: true,
    includePageNumbers: true
  };

  constructor() {
    // Injectable service - no initialization required
  }

  async exportToPDF<T>(
    data: T[],
    columns: ColumnDef[],
    config: Partial<ExportConfig> = {}
  ): Promise<void> {
    const finalConfig = { ...this.defaultConfig, ...config };
    
    this.emitProgress('preparing', 0, 'Préparation de l\'export PDF...');

    try {
      const { default: jsPDF } = await import('jspdf');
      const { default: autoTable } = await import('jspdf-autotable');

      this.emitProgress('generating', 30, 'Génération du document PDF...');

      const doc = new jsPDF({
        orientation: finalConfig.orientation,
        unit: 'mm',
        format: 'a4'
      });

      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      let yPosition = 20;

      if (finalConfig.logo) {
        try {
          doc.addImage(finalConfig.logo, 'PNG', 15, 10, 30, 15);
          yPosition = 30;
        } catch (e) {
          console.warn('Could not add logo to PDF', e);
        }
      }

      doc.setFontSize(18);
      doc.setTextColor(finalConfig.primaryColor || DS_MARINE);
      doc.text(finalConfig.title, pageWidth / 2, yPosition, { align: 'center' });
      yPosition += 10;

      if (finalConfig.includeDate) {
        doc.setFontSize(10);
        doc.setTextColor(100, 100, 100);
        doc.text(
          `Date: ${new Date().toLocaleDateString('fr-FR')}`,
          pageWidth / 2,
          yPosition,
          { align: 'center' }
        );
        yPosition += 10;
      }

      this.emitProgress('generating', 60, 'Formatage des données...');

      const tableColumns = columns.map(col => ({
        header: col.header,
        dataKey: col.key
      }));

      const tableRows = data.map(item => {
        const row: { [key: string]: unknown } = {};
        columns.forEach(col => {
          const value = (item as { [key: string]: unknown })[col.key];
          
          if (value === null || value === undefined) {
            row[col.key] = '';
          } else if (typeof value === 'object' && value !== null) {
            row[col.key] = JSON.stringify(value);
          } else if (typeof value === 'string' && value.includes('<')) {
            const temp = document.createElement('div');
            temp.innerHTML = value;
            row[col.key] = temp.textContent || temp.innerText || '';
          } else {
            row[col.key] = value;
          }
        });
        return row;
      });

      autoTable(doc, {
        startY: yPosition,
        head: [tableColumns.map(col => col.header)],
        body: tableRows.map(row => columns.map(col => row[col.key] as string)),
        theme: 'striped',
        headStyles: {
          fillColor: finalConfig.primaryColor || DS_MARINE,
          textColor: '#ffffff',
          fontStyle: 'bold',
          halign: 'left'
        },
        styles: {
          fontSize: 9,
          cellPadding: 3,
          overflow: 'linebreak',
          cellWidth: 'auto'
        },
        columnStyles: columns.reduce((acc, col, index) => {
          if (col.width) {
            acc[index] = { cellWidth: col.width };
          }
          return acc;
        }, {} as { [key: number]: { cellWidth: number } }),
        margin: { left: 15, right: 15 },
        didDrawPage: () => {
          if (finalConfig.includePageNumbers) {
            doc.setFontSize(8);
            doc.setTextColor(150);
            const pageNumber = (doc as any).internal.getCurrentPageInfo().pageNumber;
            doc.text(
              `Page ${pageNumber}`,
              pageWidth / 2,
              pageHeight - 10,
              { align: 'center' }
            );
          }
        }
      });

      this.emitProgress('generating', 90, 'Finalisation du PDF...');

      const filename = `${finalConfig.filename}_${new Date().getTime()}.pdf`;
      doc.save(filename);

      this.emitProgress('complete', 100, 'Export PDF terminé avec succès');
    } catch (error) {
      console.error('PDF export error:', error);
      this.emitProgress('error', 0, 'Erreur lors de l\'export PDF', (error as Error).message);
      throw error;
    }
  }

  async exportToExcel<T>(
    data: T[],
    columns: ColumnDef[],
    config: Partial<ExportConfig> = {}
  ): Promise<void> {
    const finalConfig = { ...this.defaultConfig, ...config };
    
    this.emitProgress('preparing', 0, 'Préparation de l\'export Excel...');

    try {
      this.emitProgress('generating', 30, 'Génération du fichier Excel...');

      const headers = columns.map(col => col.header);
      
      const rows = data.map(item => {
        return columns.map(col => {
          const value = (item as { [key: string]: unknown })[col.key];
          
          if (value === null || value === undefined) {
            return '';
          } else if (typeof value === 'string' && value.includes('<')) {
            const temp = document.createElement('div');
            temp.innerHTML = value;
            return temp.textContent || temp.innerText || '';
          } else if (typeof value === 'object') {
            return JSON.stringify(value);
          }
          return value;
        });
      });

      this.emitProgress('generating', 60, 'Formatage des données...');

      let csvContent = '';
      
      if (finalConfig.title) {
        csvContent += `${finalConfig.title}\n`;
      }
      
      if (finalConfig.includeDate) {
        csvContent += `Date: ${new Date().toLocaleDateString('fr-FR')}\n\n`;
      }

      csvContent += headers.map(h => this.escapeCSV(h)).join(',') + '\n';
      
      rows.forEach(row => {
        csvContent += row.map(cell => this.escapeCSV(String(cell))).join(',') + '\n';
      });

      this.emitProgress('generating', 90, 'Téléchargement du fichier...');

      const BOM = '\uFEFF';
      const blob = new Blob([BOM + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      const url = URL.createObjectURL(blob);
      
      const filename = `${finalConfig.filename}_${new Date().getTime()}.csv`;
      link.setAttribute('href', url);
      link.setAttribute('download', filename);
      link.style.visibility = 'hidden';
      
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      
      URL.revokeObjectURL(url);

      this.emitProgress('complete', 100, 'Export Excel terminé avec succès');
    } catch (error) {
      console.error('Excel export error:', error);
      this.emitProgress('error', 0, 'Erreur lors de l\'export Excel', (error as Error).message);
      throw error;
    }
  }

  async printTable<T>(
    data: T[],
    columns: ColumnDef[],
    config: Partial<ExportConfig> = {}
  ): Promise<void> {
    const finalConfig = { ...this.defaultConfig, ...config };
    
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      throw new Error('Impossible d\'ouvrir la fenêtre d\'impression. Vérifiez que les popups ne sont pas bloquées.');
    }

    const tableHtml = this.generatePrintHTML(data, columns, finalConfig);
    
    printWindow.document.write(tableHtml);
    printWindow.document.close();
    
    printWindow.onload = () => {
      printWindow.focus();
      setTimeout(() => {
        printWindow.print();
      }, 250);
    };
  }

  private generatePrintHTML<T>(
    data: T[],
    columns: ColumnDef[],
    config: ExportConfig
  ): string {
    let html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>${config.title}</title>
  <style>
    @media print {
      * {
        box-shadow: none !important;
        text-shadow: none !important;
      }
      
      body {
        font-family: Arial, sans-serif;
        margin: 0;
        padding: 20px;
        color: #000;
      }
      
      .header {
        text-align: center;
        margin-bottom: 30px;
        border-bottom: 2px solid ${config.primaryColor};
        padding-bottom: 15px;
      }
      
      .header h1 {
        color: ${config.primaryColor};
        margin: 0 0 10px 0;
        font-size: 24px;
      }
      
      .header .date {
        color: ${DS_TEXT_MUTED};
        font-size: 12px;
      }
      
      table {
        width: 100%;
        border-collapse: collapse;
        font-size: 10pt;
        page-break-inside: auto;
      }
      
      thead {
        display: table-header-group;
      }
      
      tr {
        page-break-inside: avoid;
        page-break-after: auto;
      }
      
      th {
        background-color: ${config.primaryColor};
        color: white;
        padding: 10px;
        text-align: left;
        font-weight: bold;
        border: 1px solid ${DS_DIVIDER};
      }
      
      td {
        padding: 8px;
        border: 1px solid ${DS_DIVIDER};
        text-align: left;
      }
      
      tbody tr:nth-child(even) {
        background-color: ${DS_BG};
      }
      
      .footer {
        margin-top: 20px;
        text-align: center;
        font-size: 10px;
        color: ${DS_TEXT_MUTED};
      }
    }
  </style>
</head>
<body>
  <div class="header">`;
    
    if (config.logo) {
      html += `<img src="${config.logo}" alt="Logo" style="max-height: 60px; margin-bottom: 10px;">`;
    }
    
    html += `
    <h1>${config.title}</h1>`;
    
    if (config.includeDate) {
      html += `<div class="date">Date: ${new Date().toLocaleDateString('fr-FR')}</div>`;
    }
    
    html += `
  </div>
  
  <table>
    <thead>
      <tr>`;
    
    columns.forEach(col => {
      html += `<th>${col.header}</th>`;
    });
    
    html += `
      </tr>
    </thead>
    <tbody>`;
    
    data.forEach(item => {
      html += '<tr>';
      columns.forEach(col => {
        let value = (item as { [key: string]: unknown })[col.key];
        
        if (value === null || value === undefined) {
          value = '';
        } else if (typeof value === 'string' && value.includes('<')) {
          const temp = document.createElement('div');
          temp.innerHTML = value;
          value = temp.textContent || temp.innerText || '';
        } else if (typeof value === 'object') {
          value = JSON.stringify(value);
        }
        
        html += `<td>${this.escapeHtml(String(value))}</td>`;
      });
      html += '</tr>';
    });
    
    html += `
    </tbody>
  </table>
  
  <div class="footer">
    Généré le ${new Date().toLocaleString('fr-FR')}
  </div>
</body>
</html>`;
    
    return html;
  }

  private escapeCSV(value: string): string {
    if (value.includes(',') || value.includes('"') || value.includes('\n')) {
      return `"${value.replace(/"/g, '""')}"`;
    }
    return value;
  }

  private escapeHtml(value: string): string {
    const div = document.createElement('div');
    div.textContent = value;
    return div.innerHTML;
  }

  private emitProgress(
    stage: ExportProgress['stage'],
    progress: number,
    message: string,
    error?: string
  ): void {
    this.progressSubject.next({ stage, progress, message, error });
  }
}

import { Component } from '@angular/core';
import { MatDialogRef, MatDialogTitle, MatDialogContent, MatDialogActions } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { LeadApiService, LeadExportRequest } from '../services/lead-api.service';
import { DossierStatus } from '../services/dossier-api.service';
import { MatIcon } from '@angular/material/icon';
import { CdkScrollable } from '@angular/cdk/scrolling';
import { MatButton } from '@angular/material/button';
import { MatCheckbox } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
import { MatDivider } from '@angular/material/list';
import { MatFormField, MatLabel, MatSuffix } from '@angular/material/form-field';
import { MatSelect } from '@angular/material/select';
import { MatOption } from '@angular/material/autocomplete';
import { MatInput } from '@angular/material/input';
import { MatProgressBar } from '@angular/material/progress-bar';

interface ColumnOption {
  value: string;
  label: string;
  selected: boolean;
}

@Component({
    selector: 'app-lead-export-dialog',
    templateUrl: './lead-export-dialog.component.html',
    styleUrls: ['./lead-export-dialog.component.css'],
    imports: [MatDialogTitle, MatIcon, CdkScrollable, MatDialogContent, MatButton, MatCheckbox, FormsModule, MatDivider, MatFormField, MatLabel, MatSelect, MatOption, MatSuffix, MatInput, MatProgressBar, MatDialogActions]
})
export class LeadExportDialogComponent {
  columns: ColumnOption[] = [
    { value: 'id', label: 'ID', selected: true },
    { value: 'name', label: 'Nom du prospect', selected: true },
    { value: 'phone', label: 'Téléphone', selected: true },
    { value: 'email', label: 'Email', selected: true },
    { value: 'source', label: 'Source', selected: true },
    { value: 'lead_source', label: 'Source détaillée', selected: false },
    { value: 'status', label: 'Statut', selected: true },
    { value: 'score', label: 'Score', selected: false },
    { value: 'notes', label: 'Notes', selected: false },
    { value: 'annonce_id', label: 'ID Annonce', selected: false },
    { value: 'case_type', label: 'Type de dossier', selected: false },
    { value: 'status_code', label: 'Code statut', selected: false },
    { value: 'loss_reason', label: 'Raison perte', selected: false },
    { value: 'won_reason', label: 'Raison gain', selected: false },
    { value: 'created_at', label: 'Date de création', selected: true },
    { value: 'updated_at', label: 'Date de modification', selected: false },
    { value: 'created_by', label: 'Créé par', selected: false },
    { value: 'updated_by', label: 'Modifié par', selected: false }
  ];

  statusFilter = '';
  startDate = '';
  endDate = '';
  sourceFilter = '';
  
  isExporting = false;

  statusOptions = [
    { value: '', label: 'Tous les statuts' },
    { value: DossierStatus.NEW, label: 'Nouveau' },
    { value: DossierStatus.QUALIFYING, label: 'En qualification' },
    { value: DossierStatus.QUALIFIED, label: 'Qualifié' },
    { value: DossierStatus.APPOINTMENT, label: 'Rendez-vous' },
    { value: DossierStatus.WON, label: 'Gagné' },
    { value: DossierStatus.LOST, label: 'Perdu' }
  ];

  sourceOptions = [
    { value: '', label: 'Toutes les sources' },
    { value: 'WEB', label: 'Web' },
    { value: 'MOBILE', label: 'Mobile' },
    { value: 'PHONE', label: 'Téléphone' },
    { value: 'EMAIL', label: 'Email' },
    { value: 'REFERRAL', label: 'Référence' },
    { value: 'WALK_IN', label: 'En personne' },
    { value: 'SOCIAL_MEDIA', label: 'Réseaux sociaux' }
  ];

  constructor(
    public dialogRef: MatDialogRef<LeadExportDialogComponent>,
    private leadApiService: LeadApiService,
    private snackBar: MatSnackBar
  ) {}

  selectAllColumns(): void {
    this.columns.forEach(col => col.selected = true);
  }

  deselectAllColumns(): void {
    this.columns.forEach(col => col.selected = false);
  }

  getSelectedColumnsCount(): number {
    return this.columns.filter(col => col.selected).length;
  }

  canExport(): boolean {
    return this.getSelectedColumnsCount() > 0 && !this.isExporting;
  }

  exportLeads(): void {
    if (!this.canExport()) {
      this.snackBar.open('Veuillez sélectionner au moins une colonne', 'Fermer', { duration: 3000 });
      return;
    }

    this.isExporting = true;

    const selectedColumns = this.columns
      .filter(col => col.selected)
      .map(col => col.value);

    const request: LeadExportRequest = {
      columns: selectedColumns
    };

    if (this.statusFilter) {
      request.status = this.statusFilter;
    }
    if (this.startDate) {
      request.startDate = this.startDate + 'T00:00:00';
    }
    if (this.endDate) {
      request.endDate = this.endDate + 'T23:59:59';
    }
    if (this.sourceFilter) {
      request.source = this.sourceFilter;
    }

    this.leadApiService.exportLeads(request)
      .subscribe({
        next: (blob) => {
          this.downloadFile(blob);
          this.snackBar.open('Export réussi', 'Fermer', {
            duration: 3000,
            panelClass: ['success-snackbar']
          });
          this.isExporting = false;
          this.dialogRef.close(true);
        },
        error: (err) => {
          this.isExporting = false;
          const message = err.error?.message || 'Échec de l\'export';
          this.snackBar.open(message, 'Fermer', {
            duration: 5000,
            panelClass: ['error-snackbar']
          });
        }
      });
  }

  private downloadFile(blob: Blob): void {
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-').substring(0, 19);
    link.download = `leads_export_${timestamp}.csv`;
    
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    
    window.URL.revokeObjectURL(url);
  }

  close(): void {
    if (!this.isExporting) {
      this.dialogRef.close(false);
    }
  }
}

