    this.initializeGlobalCommands();
    this.initializeSearch();
    this.watchRoute();

    this.visible$.pipe(takeUntil(this.destroy$)).subscribe(visible => {
      const input = this.commandInput();
      if (visible && input) {
        setTimeout(() => {
          input.nativeElement.focus();
          this.updateFilteredItems();
        }, 100);
      } else if (!visible) {
