import { Injectable } from '@angular/core';
import { QueuedAction, QueuedActionType } from './offline-queue.service';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';

export enum ConflictResolutionStrategy {
  SERVER_WINS = 'SERVER_WINS',
  CLIENT_WINS = 'CLIENT_WINS',
  MERGE = 'MERGE',
  MANUAL = 'MANUAL'
}

export interface ConflictInfo {
  action: QueuedAction;
  serverData: any;
  clientData: any;
  conflictFields: string[];
}

export interface MergeResult {
  resolved: boolean;
  mergedData: any;
  conflicts?: ConflictInfo[];
}

@Injectable({
  providedIn: 'root'
})
export class OfflineConflictResolverService {
  private defaultStrategy: ConflictResolutionStrategy = ConflictResolutionStrategy.SERVER_WINS;

  constructor(private http: HttpClient) {}

  setDefaultStrategy(strategy: ConflictResolutionStrategy): void {
    this.defaultStrategy = strategy;
  }

  async detectConflict(action: QueuedAction): Promise<ConflictInfo | null> {
    try {
      const serverData = await this.fetchServerData(action);
      if (!serverData) {
        return null;
      }

      const conflictFields = this.compareData(action.payload, serverData);
      
      if (conflictFields.length === 0) {
        return null;
      }

      return {
        action,
        serverData,
        clientData: action.payload,
        conflictFields
      };
    } catch (error) {
      return null;
    }
  }

  async resolveConflict(
    conflict: ConflictInfo,
    strategy?: ConflictResolutionStrategy
  ): Promise<MergeResult> {
    const resolutionStrategy = strategy || this.defaultStrategy;

    switch (resolutionStrategy) {
      case ConflictResolutionStrategy.SERVER_WINS:
        return this.resolveServerWins(conflict);
      
      case ConflictResolutionStrategy.CLIENT_WINS:
        return this.resolveClientWins(conflict);
      
      case ConflictResolutionStrategy.MERGE:
        return this.resolveAutoMerge(conflict);
      
      case ConflictResolutionStrategy.MANUAL:
        return {
          resolved: false,
          mergedData: null,
          conflicts: [conflict]
        };
      
      default:
        return this.resolveServerWins(conflict);
    }
  }

  private resolveServerWins(conflict: ConflictInfo): MergeResult {
    return {
      resolved: true,
      mergedData: conflict.serverData
    };
  }

  private resolveClientWins(conflict: ConflictInfo): MergeResult {
    return {
      resolved: true,
      mergedData: conflict.clientData
    };
  }

  private resolveAutoMerge(conflict: ConflictInfo): MergeResult {
    const merged = { ...conflict.serverData };
    const unresolvedConflicts: string[] = [];

    for (const field of conflict.conflictFields) {
      const serverValue = conflict.serverData[field];
      const clientValue = conflict.clientData[field];

      if (this.canAutoMerge(field, serverValue, clientValue)) {
        merged[field] = this.mergeValues(field, serverValue, clientValue);
      } else {
        unresolvedConflicts.push(field);
        merged[field] = serverValue;
      }
    }

    return {
      resolved: unresolvedConflicts.length === 0,
      mergedData: merged,
      conflicts: unresolvedConflicts.length > 0 ? [conflict] : undefined
    };
  }

  private compareData(clientData: any, serverData: any): string[] {
    const conflicts: string[] = [];
    const clientKeys = Object.keys(clientData);
    const serverKeys = Object.keys(serverData);
    const allKeys = [...new Set([...clientKeys, ...serverKeys])];

    for (let i = 0; i < allKeys.length; i++) {
      const key = allKeys[i];
      if (this.isSystemField(key)) {
        continue;
      }

      const clientValue = clientData[key];
      const serverValue = serverData[key];

      if (!this.valuesEqual(clientValue, serverValue)) {
        conflicts.push(key);
      }
    }

    return conflicts;
  }

  private isSystemField(field: string): boolean {
    const systemFields = ['id', 'createdAt', 'updatedAt', 'version', 'orgId', 'createdBy', 'updatedBy'];
    return systemFields.includes(field);
  }

  private valuesEqual(value1: any, value2: any): boolean {
    if (value1 === value2) {
      return true;
    }

    if (value1 == null || value2 == null) {
      return value1 === value2;
    }

    if (typeof value1 !== typeof value2) {
      return false;
    }

    if (typeof value1 === 'object') {
      return JSON.stringify(value1) === JSON.stringify(value2);
    }

    return false;
  }

  private canAutoMerge(field: string, serverValue: any, clientValue: any): boolean {
    if (typeof serverValue === 'number' && typeof clientValue === 'number') {
      return false;
    }

    if (typeof serverValue === 'string' && typeof clientValue === 'string') {
      if (serverValue.includes(clientValue) || clientValue.includes(serverValue)) {
        return true;
      }
    }

    if (Array.isArray(serverValue) && Array.isArray(clientValue)) {
      return true;
    }

    return false;
  }

  private mergeValues(field: string, serverValue: any, clientValue: any): any {
    if (Array.isArray(serverValue) && Array.isArray(clientValue)) {
      const merged = [...serverValue];
      for (const item of clientValue) {
        if (!merged.some(m => JSON.stringify(m) === JSON.stringify(item))) {
          merged.push(item);
        }
      }
      return merged;
    }

    if (typeof serverValue === 'string' && typeof clientValue === 'string') {
      if (clientValue.length > serverValue.length) {
        return clientValue;
      }
      return serverValue;
    }

    return serverValue;
  }

  private async fetchServerData(action: QueuedAction): Promise<any> {
    let url: string;

    switch (action.type) {
      case QueuedActionType.UPDATE_DOSSIER_STATUS:
        url = `/api/v1/dossiers/${action.payload.id}`;
        break;

      case QueuedActionType.UPDATE_APPOINTMENT:
        url = `/api/v1/appointments/${action.payload.id}`;
        break;

      case QueuedActionType.CREATE_MESSAGE:
      case QueuedActionType.CREATE_APPOINTMENT:
      case QueuedActionType.CREATE_NOTE:
        return null;

      default:
        return null;
    }

    try {
      return await firstValueFrom(this.http.get(url));
    } catch (error) {
      console.error('Failed to fetch server data for conflict detection:', error);
      return null;
    }
  }

  async resolveBatch(
    conflicts: ConflictInfo[],
    strategy: ConflictResolutionStrategy
  ): Promise<MergeResult[]> {
    const results: MergeResult[] = [];

    for (const conflict of conflicts) {
      const result = await this.resolveConflict(conflict, strategy);
      results.push(result);
    }

    return results;
  }
}

import { Injectable, OnDestroy } from '@angular/core';
import { Observable, Subject, BehaviorSubject } from 'rxjs';
import { WebSocketService } from './websocket.service';
import { HttpClient } from '@angular/common/http';

export interface CollaborationPresence {
  userId: string;
  username: string;
  dossierId: number;
  action: 'joined' | 'left';
  timestamp: Date;
}

export interface CollaborationCursor {
  userId: string;
  username: string;
  dossierId: number;
  fieldName: string;
  cursorPosition: number;
  color: string;
  timestamp: Date;
}

export interface CollaborationEdit {
  userId: string;
  username: string;
  dossierId: number;
  fieldName: string;
  newValue: any;
  oldValue: any;
  version: number;
  editId: string;
  timestamp: Date;
  metadata?: any;
}

export interface CollaborationActivity {
  userId: string;
  username: string;
  dossierId: number;
  activityType: string;
  description: string;
  data: any;
  timestamp: Date;
}

export interface SharedFilterPreset {
  id: number;
  name: string;
  description: string;
  filters: any;
  sharedBy: string;
  sharedByUsername: string;
  sharedAt: Date;
  sharedWithUserIds?: string[];
}

export interface ConflictResolution {
  fieldName: string;
  resolvedValue: any;
  resolvedBy: string;
  version: number;
}

@Injectable({
  providedIn: 'root'
})
export class CollaborationService implements OnDestroy {
  private currentDossierId: number | null = null;
  private currentUserId: string | null = null;
  private currentUsername: string | null = null;

  private viewers$ = new BehaviorSubject<Set<string>>(new Set());
  private presence$ = new Subject<CollaborationPresence>();
  private cursor$ = new Subject<CollaborationCursor>();
  private edit$ = new Subject<CollaborationEdit>();
  private activity$ = new Subject<CollaborationActivity>();
  private conflict$ = new Subject<ConflictResolution>();
  private filterPreset$ = new Subject<SharedFilterPreset>();

  private pendingEdits: Map<string, CollaborationEdit> = new Map();
  private fieldVersions: Map<string, number> = new Map();

  constructor(
    private webSocketService: WebSocketService,
    private http: HttpClient
  ) {}

  async initializeForDossier(dossierId: number, userId: string, username: string): Promise<void> {
    this.currentDossierId = dossierId;
    this.currentUserId = userId;
    this.currentUsername = username;

    await this.webSocketService.connect(userId, username);

    this.subscribeToChannels(dossierId);
    this.joinDossier(dossierId, userId, username);
  }

  private subscribeToChannels(dossierId: number): void {
    this.webSocketService.subscribe<CollaborationPresence>(`/topic/dossier/${dossierId}/presence`)
      .subscribe(presence => {
        this.presence$.next(presence);
      });

    this.webSocketService.subscribe<Set<string>>(`/topic/dossier/${dossierId}/viewers`)
      .subscribe(viewers => {
        this.viewers$.next(new Set(viewers));
      });

    this.webSocketService.subscribe<CollaborationCursor>(`/topic/dossier/${dossierId}/cursor`)
      .subscribe(cursor => {
        if (cursor.userId !== this.currentUserId) {
          this.cursor$.next(cursor);
        }
      });

    this.webSocketService.subscribe<CollaborationEdit>(`/topic/dossier/${dossierId}/edit`)
      .subscribe(edit => {
        if (edit.userId !== this.currentUserId) {
          this.handleRemoteEdit(edit);
        }
      });

    this.webSocketService.subscribe<CollaborationActivity>(`/topic/dossier/${dossierId}/activity`)
      .subscribe(activity => {
        this.activity$.next(activity);
      });

    this.webSocketService.subscribe<ConflictResolution>(`/topic/dossier/${dossierId}/conflict`)
      .subscribe(conflict => {
        this.conflict$.next(conflict);
      });

    this.webSocketService.subscribe<SharedFilterPreset>(`/topic/filter-presets`)
      .subscribe(filterPreset => {
        this.filterPreset$.next(filterPreset);
      });

    this.webSocketService.subscribe<SharedFilterPreset>(`/user/${this.currentUserId}/queue/filter-presets`)
      .subscribe(filterPreset => {
        this.filterPreset$.next(filterPreset);
      });
  }

  private joinDossier(dossierId: number, userId: string, username: string): void {
    this.webSocketService.send(`/app/dossier/${dossierId}/join`, {
      userId,
      username
    });
  }

  leaveDossier(): void {
    if (this.currentDossierId && this.currentUserId && this.currentUsername) {
      this.webSocketService.send(`/app/dossier/${this.currentDossierId}/leave`, {
        userId: this.currentUserId,
        username: this.currentUsername
      });
      this.currentDossierId = null;
    }
  }

  updateCursor(fieldName: string, cursorPosition: number): void {
    if (!this.currentDossierId || !this.currentUserId || !this.currentUsername) return;

    const cursor: CollaborationCursor = {
      userId: this.currentUserId,
      username: this.currentUsername,
      dossierId: this.currentDossierId,
      fieldName,
      cursorPosition,
      color: '',
      timestamp: new Date()
    };

    this.webSocketService.send(`/app/dossier/${this.currentDossierId}/cursor`, cursor);
  }

  broadcastEdit(fieldName: string, newValue: any, oldValue: any): CollaborationEdit {
    if (!this.currentDossierId || !this.currentUserId || !this.currentUsername) {
      throw new Error('Collaboration not initialized');
    }

    const version = (this.fieldVersions.get(fieldName) || 0) + 1;
    this.fieldVersions.set(fieldName, version);

    const edit: CollaborationEdit = {
      userId: this.currentUserId,
      username: this.currentUsername,
      dossierId: this.currentDossierId,
      fieldName,
      newValue,
      oldValue,
      version,
      editId: this.generateEditId(),
      timestamp: new Date()
    };

    this.pendingEdits.set(edit.editId, edit);
    this.webSocketService.send(`/app/dossier/${this.currentDossierId}/edit`, edit);

    return edit;
  }

  confirmEdit(editId: string): void {
    this.pendingEdits.delete(editId);
  }

  private handleRemoteEdit(edit: CollaborationEdit): void {
    const localVersion = this.fieldVersions.get(edit.fieldName) || 0;
    
    if (edit.version > localVersion) {
      this.fieldVersions.set(edit.fieldName, edit.version);
      this.edit$.next(edit);
    } else {
      console.warn('Conflict detected for field:', edit.fieldName);
    }
  }

  broadcastActivity(activityType: string, description: string, data: any): void {
    if (!this.currentDossierId || !this.currentUserId || !this.currentUsername) return;

    const activity: CollaborationActivity = {
      userId: this.currentUserId,
      username: this.currentUsername,
      dossierId: this.currentDossierId,
      activityType,
      description,
      data,
      timestamp: new Date()
    };

    this.webSocketService.send(`/app/dossier/${this.currentDossierId}/activity`, activity);
  }

  shareFilterPreset(filterPreset: SharedFilterPreset): void {
    this.webSocketService.send('/app/filter-preset/share', filterPreset);
  }

  resolveConflict(fieldName: string, resolvedValue: any): Observable<void> {
    if (!this.currentDossierId || !this.currentUserId) {
      throw new Error('Collaboration not initialized');
    }

    return this.http.post<void>(
      `/api/collaboration/dossier/${this.currentDossierId}/conflict/resolve`,
      {
        fieldName,
        resolvedValue,
        resolvedBy: this.currentUserId
      }
    );
  }

  getViewers(): Observable<Set<string>> {
    return this.viewers$.asObservable();
  }

  getPresenceUpdates(): Observable<CollaborationPresence> {
    return this.presence$.asObservable();
  }

  getCursorUpdates(): Observable<CollaborationCursor> {
    return this.cursor$.asObservable();
  }

  getEditUpdates(): Observable<CollaborationEdit> {
    return this.edit$.asObservable();
  }

  getActivityUpdates(): Observable<CollaborationActivity> {
    return this.activity$.asObservable();
  }

  getConflictUpdates(): Observable<ConflictResolution> {
    return this.conflict$.asObservable();
  }

  getFilterPresetUpdates(): Observable<SharedFilterPreset> {
    return this.filterPreset$.asObservable();
  }

  getCurrentViewers(dossierId: number): Observable<Set<string>> {
    return this.http.get<Set<string>>(`/api/collaboration/dossier/${dossierId}/viewers`);
  }

  getCurrentVersion(dossierId: number): Observable<{ dossierId: number; version: number }> {
    return this.http.get<{ dossierId: number; version: number }>(
      `/api/collaboration/dossier/${dossierId}/version`
    );
  }

  getUserColor(userId: string): Observable<{ userId: string; color: string }> {
    return this.http.get<{ userId: string; color: string }>(
      `/api/collaboration/user/${userId}/color`
    );
  }

  private generateEditId(): string {
    return `${this.currentUserId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  ngOnDestroy(): void {
    this.leaveDossier();
    this.webSocketService.disconnect();
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, fromEvent, merge } from 'rxjs';
import { map, debounceTime } from 'rxjs/operators';

export enum ConnectionStatus {
  ONLINE = 'ONLINE',
  OFFLINE = 'OFFLINE',
  SLOW = 'SLOW'
}

export interface ConnectivityState {
  status: ConnectionStatus;
  lastOnline: Date | null;
  effectiveType?: string;
  downlink?: number;
  rtt?: number;
}

@Injectable({
  providedIn: 'root'
})
export class OfflineService {
  private connectivitySubject = new BehaviorSubject<ConnectivityState>({
    status: ConnectionStatus.ONLINE,
    lastOnline: new Date()
  });

  public connectivity$: Observable<ConnectivityState> = this.connectivitySubject.asObservable();

  constructor() {
    this.initializeConnectivityMonitoring();
  }

  private initializeConnectivityMonitoring(): void {
    const online$ = fromEvent(window, 'online').pipe(map(() => true));
    const offline$ = fromEvent(window, 'offline').pipe(map(() => false));

    merge(online$, offline$)
      .pipe(debounceTime(100))
      .subscribe(isOnline => {
        this.updateConnectivityStatus(isOnline);
      });

    this.updateConnectivityStatus(navigator.onLine);

    if ('connection' in navigator) {
      const connection = (navigator as any).connection || (navigator as any).mozConnection || (navigator as any).webkitConnection;
      if (connection) {
        connection.addEventListener('change', () => {
          this.checkConnectionQuality();
        });
      }
    }
  }

  private updateConnectivityStatus(isOnline: boolean): void {
    const currentState = this.connectivitySubject.value;
    
    if (isOnline) {
      this.checkConnectionQuality();
    } else {
      this.connectivitySubject.next({
        status: ConnectionStatus.OFFLINE,
        lastOnline: currentState.status !== ConnectionStatus.OFFLINE ? new Date() : currentState.lastOnline
      });
    }
  }

  private checkConnectionQuality(): void {
    const connection = (navigator as any).connection || (navigator as any).mozConnection || (navigator as any).webkitConnection;
    
    if (connection) {
      const effectiveType = connection.effectiveType;
      const downlink = connection.downlink;
      const rtt = connection.rtt;

      let status = ConnectionStatus.ONLINE;
      
      if (effectiveType === 'slow-2g' || effectiveType === '2g' || rtt > 2000) {
        status = ConnectionStatus.SLOW;
      }

      this.connectivitySubject.next({
        status,
        lastOnline: new Date(),
        effectiveType,
        downlink,
        rtt
      });
    } else {
      this.connectivitySubject.next({
        status: ConnectionStatus.ONLINE,
        lastOnline: new Date()
      });
    }
  }

  isOnline(): boolean {
    return this.connectivitySubject.value.status !== ConnectionStatus.OFFLINE;
  }

  isSlow(): boolean {
    return this.connectivitySubject.value.status === ConnectionStatus.SLOW;
  }

  getStatus(): ConnectionStatus {
    return this.connectivitySubject.value.status;
  }

  getLastOnlineTime(): Date | null {
    return this.connectivitySubject.value.lastOnline;
  }

  async checkConnectivity(): Promise<boolean> {
    if (!navigator.onLine) {
      return false;
    }

    try {
      const response = await fetch('/api/v1/ping', {
        method: 'HEAD',
        cache: 'no-cache'
      });
      return response.ok;
    } catch {
      return false;
    }
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

export enum ConsentementChannel {
  EMAIL = 'EMAIL',
  SMS = 'SMS',
  PHONE = 'PHONE',
  WHATSAPP = 'WHATSAPP',
  POSTAL_MAIL = 'POSTAL_MAIL',
  IN_PERSON = 'IN_PERSON'
}

export enum ConsentementStatus {
  GRANTED = 'GRANTED',
  DENIED = 'DENIED',
  PENDING = 'PENDING',
  REVOKED = 'REVOKED',
  EXPIRED = 'EXPIRED'
}

export interface ConsentementCreateRequest {
  dossierId: number;
  channel: ConsentementChannel;
  status: ConsentementStatus;
  meta?: Record<string, any>;
}

export interface ConsentementUpdateRequest {
  channel: ConsentementChannel;
  status: ConsentementStatus;
  meta?: Record<string, any>;
}

export interface ConsentementResponse {
  id: number;
  orgId: string;
  dossierId: number;
  channel: ConsentementChannel;
  status: ConsentementStatus;
  meta?: Record<string, any>;
  createdAt: string;
  updatedAt: string;
}

export interface Page<T> {
  content: T[];
  pageable: {
    sort: {
      empty: boolean;
      sorted: boolean;
      unsorted: boolean;
    };
    offset: number;
    pageNumber: number;
    pageSize: number;
    paged: boolean;
    unpaged: boolean;
  };
  last: boolean;
  totalPages: number;
  totalElements: number;
  size: number;
  number: number;
  sort: {
    empty: boolean;
    sorted: boolean;
    unsorted: boolean;
  };
  first: boolean;
  numberOfElements: number;
  empty: boolean;
}

export interface ConsentementListParams {
  dossierId?: number;
  channel?: ConsentementChannel;
  status?: ConsentementStatus;
  page?: number;
  size?: number;
  sort?: string;
}

@Injectable({
  providedIn: 'root'
})
export class ConsentementApiService {

  private readonly apiUrl = '/api/v1/consentements';

  constructor(private http: HttpClient) { }

  list(params: ConsentementListParams = {}): Observable<Page<ConsentementResponse>> {
    let httpParams = new HttpParams();

    if (params.dossierId !== undefined) {
      httpParams = httpParams.set('dossierId', params.dossierId.toString());
    }
    if (params.channel !== undefined) {
      httpParams = httpParams.set('channel', params.channel);
    }
    if (params.status !== undefined) {
      httpParams = httpParams.set('status', params.status);
    }
    if (params.page !== undefined) {
      httpParams = httpParams.set('page', params.page.toString());
    }
    if (params.size !== undefined) {
      httpParams = httpParams.set('size', params.size.toString());
    }
    if (params.sort !== undefined) {
      httpParams = httpParams.set('sort', params.sort);
    }

    return this.http.get<Page<ConsentementResponse>>(this.apiUrl, { params: httpParams });
  }

  getById(id: number): Observable<ConsentementResponse> {
    return this.http.get<ConsentementResponse>(`${this.apiUrl}/${id}`);
  }

  create(request: ConsentementCreateRequest): Observable<ConsentementResponse> {
    return this.http.post<ConsentementResponse>(this.apiUrl, request);
  }

  update(id: number, request: ConsentementUpdateRequest): Observable<ConsentementResponse> {
    return this.http.put<ConsentementResponse>(`${this.apiUrl}/${id}`, request);
  }

  delete(id: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/${id}`);
  }
}

