          DossierStatus.NEW,
          DossierStatus.QUALIFYING,
          DossierStatus.LOST
        ];

      case DossierStatus.QUALIFYING:
        return [
          DossierStatus.QUALIFYING,
          DossierStatus.QUALIFIED,
          DossierStatus.LOST
        ];

      case DossierStatus.QUALIFIED:
        return [
          DossierStatus.QUALIFIED,
          DossierStatus.APPOINTMENT,
          DossierStatus.LOST
        ];

      case DossierStatus.APPOINTMENT:
        return [
          DossierStatus.APPOINTMENT,
          DossierStatus.WON,
          DossierStatus.LOST
        ];

      default:
        return this.statusOptions;
    }
