  };
}

export interface ObservabilityMetrics {
  queueMetrics: QueueMetrics;
  latencyMetrics: LatencyMetrics;
  failureMetrics: FailureMetrics;
  dlqMetrics: DlqMetrics;
  quotaMetrics: QuotaMetrics;
