    let params = new HttpParams();
    if (from) {
      params = params.set('from', from);
    }
    if (to) {
      params = params.set('to', to);
    }
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.get<ObservabilityMetrics>(`${this.apiUrl}/observability/metrics`, { params });
  }

