import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface ReportColumn {
  field: string;
  header: string;
  format?: 'text' | 'number' | 'currency' | 'date' | 'percentage';
  width?: number;
}

export interface ReportExportOptions {
  format: 'csv' | 'excel' | 'pdf';
  columns?: ReportColumn[];
  title?: string;
  subtitle?: string;
  includeHeaders?: boolean;
  includeFooter?: boolean;
  branding?: {
    logoUrl?: string;
    companyName?: string;
    primaryColor?: string;
  };
}

export interface CustomReportDefinition {
  dimensions: string[];
  metrics: string[];
  filters?: Record<string, any>;
  groupBy?: string[];
  orderBy?: { field: string; direction: 'asc' | 'desc' }[];
  limit?: number;
}

@Injectable({
  providedIn: 'root'
})
export class ReportApiService {
  private readonly apiUrl = '/api/v1/reports';

  constructor(private http: HttpClient) {}

  generateCustomReport(definition: CustomReportDefinition, orgId?: string): Observable<any> {
    let params = new HttpParams();
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.post<any>(`${this.apiUrl}/custom`, definition, { params });
  }

  exportReport(reportId: string, options: ReportExportOptions, orgId?: string): Observable<Blob> {
    let params = new HttpParams();
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.post(`${this.apiUrl}/${reportId}/export`, options, {
      params,
      responseType: 'blob'
    });
  }

  exportCustomReport(definition: CustomReportDefinition, options: ReportExportOptions, orgId?: string): Observable<Blob> {
    let params = new HttpParams();
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.post(`${this.apiUrl}/custom/export`, { definition, options }, {
      params,
      responseType: 'blob'
    });
  }

  getAvailableDimensions(): Observable<string[]> {
    return this.http.get<string[]>(`${this.apiUrl}/dimensions`);
  }

  getAvailableMetrics(): Observable<string[]> {
    return this.http.get<string[]>(`${this.apiUrl}/metrics`);
  }

  private downloadFile(blob: Blob, filename: string): void {
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  async exportToCSV(data: any[], columns: ReportColumn[], filename = 'report.csv'): Promise<void> {
    const Papa = await import('papaparse');
    
    const csvData = data.map(row => {
      const csvRow: any = {};
      columns.forEach(col => {
        csvRow[col.header] = this.formatValue(row[col.field], col.format);
      });
      return csvRow;
    });

    const csv = Papa.unparse(csvData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }

  async exportToExcel(data: any[], columns: ReportColumn[], filename = 'report.xlsx'): Promise<void> {
    const XLSX = await import('xlsx');
    
    const worksheetData = [
      columns.map(col => col.header),
      ...data.map(row => columns.map(col => this.formatValue(row[col.field], col.format)))
    ];

    const ws = XLSX.utils.aoa_to_sheet(worksheetData);
    
    columns.forEach((col, idx) => {
      if (col.width) {
        if (!ws['!cols']) ws['!cols'] = [];
        ws['!cols'][idx] = { wch: col.width };
      }
    });

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Report');
    XLSX.writeFile(wb, filename);
  }

  async exportToPDF(
    data: any[], 
    columns: ReportColumn[], 
    options: { title?: string; subtitle?: string; branding?: any } = {},
    filename = 'report.pdf'
  ): Promise<void> {
    const [jsPDFModule] = await Promise.all([
      import('jspdf'),
      import('jspdf-autotable')
    ]);

    const { jsPDF: JsPDFClass } = jsPDFModule;
    const doc = new JsPDFClass();

    let yPosition = 20;

    if (options.branding?.logoUrl) {
      const img = new Image();
      img.src = options.branding.logoUrl;
      doc.addImage(img, 'PNG', 14, 10, 30, 15);
      yPosition = 35;
    }

    if (options.branding?.companyName) {
      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(options.branding.companyName, 200, 15, { align: 'right' });
    }

    if (options.title) {
      doc.setFontSize(18);
      doc.setTextColor(0);
      doc.text(options.title, 14, yPosition);
      yPosition += 10;
    }

    if (options.subtitle) {
      doc.setFontSize(11);
      doc.setTextColor(100);
      doc.text(options.subtitle, 14, yPosition);
      yPosition += 10;
    }

    (doc as any).autoTable({
      startY: yPosition,
      head: [columns.map(col => col.header)],
      body: data.map(row => columns.map(col => this.formatValue(row[col.field], col.format))),
      theme: 'grid',
      styles: { fontSize: 10 },
      headStyles: { 
        fillColor: options.branding?.primaryColor ? this.hexToRgb(options.branding.primaryColor) : [66, 139, 202] 
      }
    });

    doc.save(filename);
  }

  private formatValue(value: any, format?: string): string {
    if (value == null) return '';
    
    switch (format) {
      case 'currency':
        return new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR' }).format(value);
      case 'number':
        return new Intl.NumberFormat('fr-FR').format(value);
      case 'percentage':
        return `${(value * 100).toFixed(2)}%`;
      case 'date':
        return new Date(value).toLocaleDateString('fr-FR');
      default:
        return String(value);
    }
  }

  private hexToRgb(hex: string): [number, number, number] {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? [
      parseInt(result[1], 16),
      parseInt(result[2], 16),
      parseInt(result[3], 16)
    ] : [66, 139, 202];
  }
}

import { Component, ViewChild, ElementRef, AfterViewInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import * as d3 from 'd3';
import { WorkflowApiService, WorkflowDefinition, WorkflowState, WorkflowTransition } from '../services/workflow-api.service';
import { resolveDsToken } from '../design-system/chart-ds-colors';
import { MatSnackBar } from '@angular/material/snack-bar';
import { DsCardComponent } from '../design-system';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { MatTabsModule } from '@angular/material/tabs';
import { MatListModule } from '@angular/material/list';

interface D3Node extends d3.SimulationNodeDatum {
  id: string;
  label: string;
  type: 'initial' | 'intermediate' | 'final';
  color: string;
  state: WorkflowState;
}

interface D3Link extends d3.SimulationLinkDatum<D3Node> {
  id: string;
  label: string;
  transition: WorkflowTransition;
}

@Component({
  selector: 'app-workflow-builder',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    DsCardComponent,
    MatButtonModule,
    MatIconModule,
    MatFormFieldModule,
    MatInputModule,
    MatSelectModule,
    MatTabsModule,
    MatListModule,
  ],
  templateUrl: './workflow-builder.component.html',
  styleUrls: ['./workflow-builder.component.css']
})
export class WorkflowBuilderComponent implements AfterViewInit {
  @ViewChild('svgCanvas', { static: false }) svgCanvas!: ElementRef<SVGElement>;

  workflowForm: FormGroup;
  stateForm: FormGroup;
  transitionForm: FormGroup;

  workflow: WorkflowDefinition | null = null;
  states: WorkflowState[] = [];
  transitions: WorkflowTransition[] = [];

  selectedState: WorkflowState | null = null;
  selectedTransition: WorkflowTransition | null = null;

  isAddingState = false;
  isAddingTransition = false;
  transitionSourceState: string | null = null;

  private svg: any;
  private simulation: any;
  private nodes: D3Node[] = [];
  private links: D3Link[] = [];

  caseTypes = ['SALE', 'RENTAL', 'MANDATE', 'CONSTRUCTION'];
  stateTypes = ['initial', 'intermediate', 'final'];
  stateColors: string[] = [];

  constructor(
    private fb: FormBuilder,
    private workflowApi: WorkflowApiService,
    private snackBar: MatSnackBar
  ) {
    this.stateColors = [
      resolveDsToken('--ds-marine'),
      resolveDsToken('--ds-success'),
      resolveDsToken('--ds-warning'),
      resolveDsToken('--ds-primary'),
      resolveDsToken('--ds-error'),
      resolveDsToken('--ds-marine-light'),
    ];
    this.workflowForm = this.fb.group({
      name: ['', Validators.required],
      description: [''],
      caseType: ['', Validators.required],
      initialState: [''],
      finalStates: ['']
    });

    this.stateForm = this.fb.group({
      stateCode: ['', Validators.required],
      stateName: ['', Validators.required],
      stateType: ['intermediate', Validators.required],
      color: ['#3B82F6', Validators.required],
      description: ['']
    });

    this.transitionForm = this.fb.group({
      fromState: ['', Validators.required],
      toState: ['', Validators.required],
      label: ['', Validators.required],
      requiredFields: [''],
      allowedRoles: ['ADMIN,AGENT,MANAGER']
    });
  }

  ngAfterViewInit(): void {
    this.initializeSvg();
  }

  private initializeSvg(): void {
    const element = this.svgCanvas.nativeElement;
    const width = element.clientWidth;
    const height = element.clientHeight;

    this.svg = d3.select(element);
    this.svg.selectAll('*').remove();

    const defs = this.svg.append('defs');
    defs.append('marker')
      .attr('id', 'arrowhead')
      .attr('viewBox', '-0 -5 10 10')
      .attr('refX', 25)
      .attr('refY', 0)
      .attr('orient', 'auto')
      .attr('markerWidth', 8)
      .attr('markerHeight', 8)
      .append('svg:path')
      .attr('d', 'M 0,-5 L 10 ,0 L 0,5')
      .attr('fill', '#999');

    this.simulation = d3.forceSimulation<D3Node>(this.nodes)
      .force('link', d3.forceLink<D3Node, D3Link>(this.links).id((d: any) => d.id).distance(150))
      .force('charge', d3.forceManyBody().strength(-300))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(50));

    this.renderGraph();
  }

  private renderGraph(): void {
    if (!this.svg) return;

    this.svg.selectAll('.link').remove();
    this.svg.selectAll('.node').remove();
    this.svg.selectAll('.label').remove();

    const link = this.svg.selectAll('.link')
      .data(this.links)
      .enter()
      .append('line')
      .attr('class', 'link')
      .attr('stroke', resolveDsToken('--ds-text-faint'))
      .attr('stroke-width', 2)
      .attr('marker-end', 'url(#arrowhead)');

    const linkLabel = this.svg.selectAll('.link-label')
      .data(this.links)
      .enter()
      .append('text')
      .attr('class', 'link-label')
      .attr('font-size', '10px')
      .attr('fill', resolveDsToken('--ds-text-muted'))
      .attr('text-anchor', 'middle')
      .text((d: D3Link) => d.label);

    const node = this.svg.selectAll('.node')
      .data(this.nodes)
      .enter()
      .append('g')
      .attr('class', 'node')
      .call(this.drag() as any);

    node.append('circle')
      .attr('r', 30)
      .attr('fill', (d: D3Node) => d.color)
      .attr('stroke', '#fff')
      .attr('stroke-width', 3)
      .on('click', (event: any, d: D3Node) => this.onStateClick(d));

    node.append('text')
      .attr('class', 'label')
      .attr('text-anchor', 'middle')
      .attr('dy', 4)
      .attr('font-size', '10px')
      .attr('fill', resolveDsToken('--ds-text-inverse'))
      .text((d: D3Node) => d.label);

    this.simulation.nodes(this.nodes);
    (this.simulation.force('link') as any).links(this.links);

    this.simulation.on('tick', () => {
      link
        .attr('x1', (d: any) => d.source.x)
        .attr('y1', (d: any) => d.source.y)
        .attr('x2', (d: any) => d.target.x)
        .attr('y2', (d: any) => d.target.y);

      linkLabel
        .attr('x', (d: any) => (d.source.x + d.target.x) / 2)
        .attr('y', (d: any) => (d.source.y + d.target.y) / 2);

      node.attr('transform', (d: any) => `translate(${d.x},${d.y})`);
    });

    this.simulation.alpha(1).restart();
  }

  private drag(): any {
    return d3.drag<SVGGElement, D3Node>()
      .on('start', (event: any, d: D3Node) => {
        if (!event.active) this.simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
      })
      .on('drag', (event: any, d: D3Node) => {
        d.fx = event.x;
        d.fy = event.y;
      })
      .on('end', (event: any, d: D3Node) => {
        if (!event.active) this.simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
      });
  }

  addState(): void {
    if (this.stateForm.valid) {
      const formValue = this.stateForm.value;
      const newState: WorkflowState = {
        stateCode: formValue.stateCode,
        stateName: formValue.stateName,
        stateType: formValue.stateType,
        color: formValue.color,
        positionX: 0,
        positionY: 0,
        isInitial: formValue.stateType === 'initial',
        isFinal: formValue.stateType === 'final',
        description: formValue.description
      };

      this.states.push(newState);
      this.updateGraph();
      this.stateForm.reset({ stateType: 'intermediate', color: resolveDsToken('--ds-marine') });
      this.isAddingState = false;
      this.snackBar.open('State added successfully', 'Close', { duration: 3000 });
    }
  }

  addTransition(): void {
    if (this.transitionForm.valid) {
      const formValue = this.transitionForm.value;
      const newTransition: WorkflowTransition = {
        fromState: formValue.fromState,
        toState: formValue.toState,
        label: formValue.label,
        requiredFields: formValue.requiredFields ? formValue.requiredFields.split(',').map((f: string) => f.trim()) : [],
        allowedRoles: formValue.allowedRoles ? formValue.allowedRoles.split(',').map((r: string) => r.trim()) : [],
        isActive: true
      };

      this.transitions.push(newTransition);
      this.updateGraph();
      this.transitionForm.reset({ allowedRoles: 'ADMIN,AGENT,MANAGER' });
      this.isAddingTransition = false;
      this.transitionSourceState = null;
      this.snackBar.open('Transition added successfully', 'Close', { duration: 3000 });
    }
  }

  private updateGraph(): void {
    this.nodes = this.states.map(state => ({
      id: state.stateCode,
      label: state.stateName,
      type: state.stateType,
      color: state.color,
      state: state
    }));

    this.links = this.transitions.map((transition, _idx) => ({
      id: `${transition.fromState}-${transition.toState}`,
      source: transition.fromState,
      target: transition.toState,
      label: transition.label,
      transition: transition
    }));

    this.renderGraph();
  }

  onStateClick(node: D3Node): void {
    this.selectedState = node.state;
    this.selectedTransition = null;
  }

  deleteState(stateCode: string): void {
    this.states = this.states.filter(s => s.stateCode !== stateCode);
    this.transitions = this.transitions.filter(t => t.fromState !== stateCode && t.toState !== stateCode);
    this.selectedState = null;
    this.updateGraph();
    this.snackBar.open('State deleted', 'Close', { duration: 3000 });
  }

  deleteTransition(fromState: string, toState: string): void {
    this.transitions = this.transitions.filter(t => !(t.fromState === fromState && t.toState === toState));
    this.selectedTransition = null;
    this.updateGraph();
    this.snackBar.open('Transition deleted', 'Close', { duration: 3000 });
  }

  saveWorkflow(): void {
    if (this.workflowForm.valid && this.states.length > 0) {
      const formValue = this.workflowForm.value;
      const workflow: WorkflowDefinition = {
        name: formValue.name,
        description: formValue.description,
        caseType: formValue.caseType,
