  getAppointmentStatusBadgeClass(status: AppointmentStatus): string {
    switch (status) {
      case AppointmentStatus.SCHEDULED: return 'status-badge status-scheduled';
      case AppointmentStatus.COMPLETED: return 'status-badge status-completed';
      case AppointmentStatus.CANCELLED: return 'status-badge status-cancelled';
      default: return 'status-badge';
    }
  }

  getAppointmentStatusLabel(status: AppointmentStatus): string {
    switch (status) {
      case AppointmentStatus.SCHEDULED: return 'Planifié';
      case AppointmentStatus.COMPLETED: return 'Terminé';
      case AppointmentStatus.CANCELLED: return 'Annulé';
      default: return status;
    }
  }

  formatAppointmentDateTime(dateTime: string): string {
    if (!dateTime) {
      return '—';
    }
    const date = new Date(dateTime);
    return date.toLocaleString('fr-FR', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  getConsentementStatusLabel(status: ConsentementStatus): string {
    switch (status) {
      case ConsentementStatus.GRANTED: return 'Accordé';
      case ConsentementStatus.DENIED: return 'Refusé';
      case ConsentementStatus.REVOKED: return 'Révoqué';
      case ConsentementStatus.PENDING: return 'En attente';
      case ConsentementStatus.EXPIRED: return 'Expiré';
      default: return status;
    }
  }

  getConsentementStatusBadgeClass(status: ConsentementStatus): string {
    switch (status) {
      case ConsentementStatus.GRANTED: return 'consent-badge consent-granted';
      case ConsentementStatus.DENIED: return 'consent-badge consent-denied';
      case ConsentementStatus.REVOKED: return 'consent-badge consent-revoked';
      case ConsentementStatus.PENDING: return 'consent-badge consent-pending';
      case ConsentementStatus.EXPIRED: return 'consent-badge consent-expired';
      default: return 'consent-badge';
    }
  }

  getChannelLabel(channel: ConsentementChannel): string {
    switch (channel) {
      case ConsentementChannel.EMAIL: return 'Email';
      case ConsentementChannel.SMS: return 'SMS';
      case ConsentementChannel.PHONE: return 'Téléphone';
      case ConsentementChannel.WHATSAPP: return 'WhatsApp';
      case ConsentementChannel.POSTAL_MAIL: return 'Courrier postal';
      case ConsentementChannel.IN_PERSON: return 'En personne';
      default: return channel;
    }
  }

  getConsentementsHistory(): ConsentementResponse[] {
    return this.consentements.slice().sort((a, b) => {
      const dateA = new Date(a.updatedAt).getTime();
      const dateB = new Date(b.updatedAt).getTime();
      return dateB - dateA;
    });
  }

  getUserFromMeta(consent: ConsentementResponse): string {
    if (consent.meta && consent.meta['user']) {
      return consent.meta['user'];
    }
    return '—';
  }

  getConsentDate(consent: ConsentementResponse): string {
    if (consent.status === ConsentementStatus.GRANTED && consent.createdAt) {
      return this.formatDate(consent.createdAt);
    }
    if (consent.status === ConsentementStatus.REVOKED && consent.updatedAt) {
      return this.formatDate(consent.updatedAt);
    }
    return this.formatDate(consent.updatedAt);
  }

  getScoreDisplay(): string {
    if (!this.dossier) {
      return '—';
    }
    if (this.dossier.score !== undefined && this.dossier.score !== null) {
      return String(this.dossier.score);
    }
    return '—';
  }

  hasEmptyFields(): boolean {
    if (!this.dossier) {
      return false;
    }
    const emptyFields = [];

    if (!this.dossier.leadName) {
      emptyFields.push('leadName');
    }
    if (!this.dossier.leadSource) {
      emptyFields.push('leadSource');
    }

    return emptyFields.length > 0;
  }

  getEmptyFieldsList(): string {
    if (!this.dossier) {
      return '';
    }
    const emptyFields = [];

    if (!this.dossier.leadName) {
      emptyFields.push('Nom du prospect');
    }
    if (!this.dossier.leadSource) {
      emptyFields.push('Source du prospect');
    }

    return emptyFields.join(', ');
  }

  loadWhatsAppMessages(): void {
    const id = this.route.snapshot.paramMap.get('id');
    if (!id) {
      return;
    }

    const dossierId = parseInt(id, 10);
    if (isNaN(dossierId)) {
      return;
    }

    this.loadingWhatsAppMessages = true;
    this.messageApiService.list({
      dossierId,
      channel: MessageChannel.WHATSAPP,
      size: 100,
      sort: 'timestamp,asc'
    }).subscribe({
      next: (response) => {
        this.whatsappMessages = response.content;
        this.loadingWhatsAppMessages = false;
      },
      error: (err) => {
        console.error('Error loading WhatsApp messages:', err);
        this.loadingWhatsAppMessages = false;
      }
    });
  }

  onTemplateSelect(): void {
    if (this.selectedTemplate) {
      this.initializeTemplateVariables();
      this.updateWhatsAppPreview();
    } else {
      this.templateVariables = {};
      this.whatsappMessageContent = '';
    }
  }

  initializeTemplateVariables(): void {
    if (!this.selectedTemplate) {
      return;
    }

    this.templateVariables = {};
    this.selectedTemplate.variables.forEach(variable => {
      if (variable === 'name' && this.dossier?.leadName) {
        this.templateVariables[variable] = this.dossier.leadName;
      } else {
        this.templateVariables[variable] = '';
      }
    });
  }

  updateWhatsAppPreview(): void {
    if (!this.selectedTemplate) {
      this.whatsappMessageContent = '';
      return;
    }

    let preview = this.selectedTemplate.content;
    this.selectedTemplate.variables.forEach(variable => {
      const value = this.templateVariables[variable] || `{{${variable}}}`;
      preview = preview.replace(`{{${variable}}}`, value);
    });
    this.whatsappMessageContent = preview;
  }

  onVariableChange(): void {
    this.updateWhatsAppPreview();
  }

  canSendWhatsAppMessage(): boolean {
    if (!this.whatsappMessageContent || this.whatsappMessageContent.trim() === '') {
      return false;
    }

    if (this.selectedTemplate) {
      const hasEmptyVariables = this.selectedTemplate.variables.some(
        variable => !this.templateVariables[variable] || this.templateVariables[variable].trim() === ''
      );
      if (hasEmptyVariables) {
        return false;
      }
    }

    return true;
  }

  getWhatsAppConsentStatus(): ConsentementStatus | null {
    const whatsappConsent = this.consentements.find(
      c => c.channel === ConsentementChannel.WHATSAPP
    );
    return whatsappConsent?.status || null;
  }

  isWhatsAppConsentGranted(): boolean {
    return this.getWhatsAppConsentStatus() === ConsentementStatus.GRANTED;
  }

  sendWhatsAppMessage(): void {
    if (!this.dossier || !this.canSendWhatsAppMessage()) {
      return;
    }

    if (!this.isWhatsAppConsentGranted()) {
      this.snackBar.open(
        '⚠️ Le consentement WhatsApp n\'est pas accordé. Veuillez obtenir le consentement avant d\'envoyer un message.',
        'Fermer',
        {
          duration: 5000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['warning-snackbar']
        }
      );
      return;
    }

    this.sendingWhatsAppMessage = true;

    const request: MessageCreateRequest = {
      dossierId: this.dossier.id,
      channel: MessageChannel.WHATSAPP,
      direction: MessageDirection.OUTBOUND,
      content: this.whatsappMessageContent,
      timestamp: new Date().toISOString(),
      templateId: this.selectedTemplate?.id,
      templateVariables: this.selectedTemplate ? this.templateVariables : undefined
    };

    this.messageApiService.create(request).subscribe({
      next: (newMessage) => {
        this.snackBar.open('Message WhatsApp envoyé avec succès', 'Fermer', {
          duration: 3000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['success-snackbar']
        });
        this.whatsappMessages.push(newMessage);
        this.resetWhatsAppForm();
        this.sendingWhatsAppMessage = false;
      },
      error: (err) => {
        const errorMessage = err.error?.message || 'Échec de l\'envoi du message WhatsApp';
        this.snackBar.open(errorMessage, 'Fermer', {
          duration: 5000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['error-snackbar']
        });
        console.error('Error sending WhatsApp message:', err);
        this.sendingWhatsAppMessage = false;
      }
    });
  }

  resetWhatsAppForm(): void {
    this.selectedTemplate = null;
    this.templateVariables = {};
    this.whatsappMessageContent = '';
  }

  retryWhatsAppMessage(message: MessageResponse): void {
    if (message.deliveryStatus !== MessageDeliveryStatus.FAILED) {
      return;
    }

    this.messageApiService.retry(message.id).subscribe({
      next: (updatedMessage) => {
        this.snackBar.open('Message en cours de renvoi...', 'Fermer', {
          duration: 3000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['success-snackbar']
        });
        const index = this.whatsappMessages.findIndex(m => m.id === message.id);
        if (index !== -1) {
          this.whatsappMessages[index] = updatedMessage;
        }
      },
      error: (err) => {
        const errorMessage = err.error?.message || 'Échec du renvoi du message';
        this.snackBar.open(errorMessage, 'Fermer', {
          duration: 5000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['error-snackbar']
        });
        console.error('Error retrying message:', err);
      }
    });
  }

  getDeliveryStatusLabel(status: MessageDeliveryStatus): string {
    switch (status) {
      case MessageDeliveryStatus.PENDING: return 'En attente';
      case MessageDeliveryStatus.SENT: return 'Envoyé';
      case MessageDeliveryStatus.DELIVERED: return 'Délivré';
      case MessageDeliveryStatus.FAILED: return 'Échec';
      case MessageDeliveryStatus.READ: return 'Lu';
      default: return 'Inconnu';
    }
  }

  getDeliveryStatusClass(status: MessageDeliveryStatus): string {
    switch (status) {
      case MessageDeliveryStatus.PENDING: return 'delivery-status-pending';
      case MessageDeliveryStatus.SENT: return 'delivery-status-sent';
      case MessageDeliveryStatus.DELIVERED: return 'delivery-status-delivered';
      case MessageDeliveryStatus.FAILED: return 'delivery-status-failed';
      case MessageDeliveryStatus.READ: return 'delivery-status-read';
      default: return '';
    }
  }

  getDeliveryStatusIcon(status: MessageDeliveryStatus): string {
    switch (status) {
      case MessageDeliveryStatus.PENDING: return '⏳';
      case MessageDeliveryStatus.SENT: return '✓';
      case MessageDeliveryStatus.DELIVERED: return '✓✓';
      case MessageDeliveryStatus.FAILED: return '✗';
      case MessageDeliveryStatus.READ: return '✓✓';
      default: return '';
    }
  }

  formatWhatsAppTimestamp(timestamp: string): string {
    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) {
      return 'À l\'instant';
    } else if (diffMins < 60) {
      return `Il y a ${diffMins} min`;
    } else if (diffHours < 24) {
      return `Il y a ${diffHours}h`;
    } else if (diffDays < 7) {
      return `Il y a ${diffDays}j`;
    } else {
      return date.toLocaleDateString('fr-FR', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      });
    }
  }
}

import { Component, OnInit, OnDestroy } from '@angular/core';
import { FormBuilder, FormGroup, Validators, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { trigger, style, transition, animate } from '@angular/animations';
import { Subject } from 'rxjs';
import { takeUntil, debounceTime, distinctUntilChanged } from 'rxjs/operators';
import { UserPreferencesService } from '../services/user-preferences.service';
import { NotificationService } from '../services/notification.service';
import { MatProgressBar } from '@angular/material/progress-bar';
import { DsCardComponent } from '../design-system';
import { MatIcon } from '@angular/material/icon';
import { MatSlideToggle } from '@angular/material/slide-toggle';
import { MatSlider, MatSliderThumb } from '@angular/material/slider';
import { MatHint } from '@angular/material/form-field';
import { MatRadioGroup, MatRadioButton } from '@angular/material/radio';
import { MatDivider } from '@angular/material/list';
import { MatButton } from '@angular/material/button';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';

interface NotificationChannel {
  id: string;
  label: string;
  description: string;
  icon: string;
  enabled: boolean;
}

interface NotificationType {
  id: string;
  label: string;
  description: string;
  icon: string;
  enabled: boolean;
}

interface DigestFrequency {
  value: string;
  label: string;
  description: string;
  icon: string;
}

interface NotificationExample {
  title: string;
  message: string;
  timestamp: Date;
  type: string;
  icon: string;
}

@Component({
    selector: 'app-notification-preferences-form',
    standalone: true,
    templateUrl: './notification-preferences-form.component.html',
    styleUrls: ['./notification-preferences-form.component.css'],
    animations: [
        trigger('slideDown', [
            transition(':enter', [
                style({ height: '0', opacity: '0', overflow: 'hidden' }),
                animate('300ms ease-out', style({ height: '*', opacity: '1' }))
            ]),
            transition(':leave', [
                style({ height: '*', opacity: '1', overflow: 'hidden' }),
                animate('300ms ease-in', style({ height: '0', opacity: '0' }))
            ])
        ])
    ],
    imports: [FormsModule, ReactiveFormsModule, MatProgressBar, DsCardComponent, DsSkeletonComponent, MatIcon, MatSlideToggle, MatSlider, MatSliderThumb, MatHint, MatRadioGroup, MatRadioButton, MatDivider, MatButton]
})
export class NotificationPreferencesFormComponent implements OnInit, OnDestroy {
  private destroy$ = new Subject<void>();

  preferencesForm!: FormGroup;
  loading = false;
  saving = false;

  // Original values for dirty check
  originalValues: Record<string, unknown> = {};

  // Notification channels
  channels: NotificationChannel[] = [
    {
      id: 'email',
      label: 'Email',
      description: 'Recevez des notifications par email',
      icon: 'email',
      enabled: true
    },
    {
      id: 'sms',
      label: 'SMS',
      description: 'Recevez des alertes par SMS',
      icon: 'sms',
      enabled: false
    },
    {
      id: 'inApp',
      label: 'Dans l\'application',
      description: 'Notifications dans l\'interface',
      icon: 'notifications',
      enabled: true
    },
    {
      id: 'push',
      label: 'Push',
      description: 'Notifications push dans le navigateur',
      icon: 'notifications_active',
      enabled: true
    }
  ];

  // Notification types
  notificationTypes: NotificationType[] = [
    {
      id: 'newDossier',
      label: 'Nouveau dossier',
      description: 'Notification lors de la création d\'un nouveau dossier',
      icon: 'folder',
      enabled: true
    },
    {
      id: 'newMessage',
      label: 'Nouveau message',
      description: 'Notification lors de la réception d\'un message',
      icon: 'message',
      enabled: true
    },
    {
      id: 'appointment',
      label: 'Rendez-vous',
      description: 'Rappels de rendez-vous à venir',
      icon: 'event',
      enabled: true
    },
    {
      id: 'statusChange',
      label: 'Changement de statut',
      description: 'Notification lors du changement de statut d\'un dossier',
      icon: 'update',
      enabled: true
    }
  ];

  // Digest frequencies
  digestFrequencies: DigestFrequency[] = [
    {
      value: 'instant',
      label: 'Instantané',
      description: 'Recevoir les notifications immédiatement',
      icon: 'flash_on'
    },
    {
      value: 'hourly',
      label: 'Horaire',
      description: 'Grouper les notifications par heure',
      icon: 'schedule'
    },
    {
      value: 'daily',
      label: 'Quotidien',
      description: 'Recevoir un résumé quotidien',
      icon: 'today'
    }
  ];

  // Preview examples
  exampleNotifications: NotificationExample[] = [];

  // Quiet hours range (default: 22h-8h)
  quietHoursStart = 22;
  quietHoursEnd = 8;
  quietHoursEnabled = false;

  constructor(
    private fb: FormBuilder,
    private userPreferencesService: UserPreferencesService,
    private notificationService: NotificationService
  ) { }

  ngOnInit(): void {
    this.initializeForm();
    this.loadPreferences();
    this.setupFormListeners();
    this.updateExampleNotifications();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private initializeForm(): void {
    this.preferencesForm = this.fb.group({
      // Channels
      emailEnabled: [true],
      smsEnabled: [false],
      inAppEnabled: [true],
      pushEnabled: [true],

      // Notification types
      newDossierEnabled: [true],
      newMessageEnabled: [true],
      appointmentEnabled: [true],
      statusChangeEnabled: [true],

      // Quiet hours
      quietHoursEnabled: [false],
      quietHoursStart: [22, [Validators.min(0), Validators.max(23)]],
      quietHoursEnd: [8, [Validators.min(0), Validators.max(23)]],

      // Digest frequency
      digestFrequency: ['instant', Validators.required]
    });
  }

  private loadPreferences(): void {
    this.loading = true;

    this.userPreferencesService.getPreferences()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (preferences) => {
          if (preferences.notifications) {
            const notifPrefs = preferences.notifications;
            const notifPrefsExtended = notifPrefs as any;

            this.preferencesForm.patchValue({
              emailEnabled: notifPrefs.emailEnabled !== false,
              smsEnabled: notifPrefs.smsEnabled || false,
              inAppEnabled: notifPrefs.inAppEnabled !== false,
              pushEnabled: notifPrefs.pushEnabled !== false,

              newDossierEnabled: (notifPrefsExtended.newDossierEnabled as boolean) !== false,
              newMessageEnabled: (notifPrefsExtended.newMessageEnabled as boolean) !== false,
              appointmentEnabled: (notifPrefsExtended.appointmentEnabled as boolean) !== false,
              statusChangeEnabled: (notifPrefsExtended.statusChangeEnabled as boolean) !== false,

              quietHoursEnabled: (notifPrefsExtended.quietHoursEnabled as boolean) || false,
              quietHoursStart: (notifPrefsExtended.quietHoursStart as number) || 22,
              quietHoursEnd: (notifPrefsExtended.quietHoursEnd as number) || 8,

              digestFrequency: (notifPrefsExtended.digestFrequency as string) || 'instant'
            });

            this.updateChannelsFromForm();
            this.updateTypesFromForm();
            this.updateQuietHoursFromForm();
          }
          this.originalValues = this.preferencesForm.value as Record<string, unknown>;
          this.loading = false;
        },
        error: (error) => {
          console.error('Error loading notification preferences:', error);
          this.notificationService.error('Erreur lors du chargement des préférences de notification');
          this.loading = false;
        }
      });
  }

  private setupFormListeners(): void {
    // Update preview on form changes
    this.preferencesForm.valueChanges
      .pipe(debounceTime(300), distinctUntilChanged(), takeUntil(this.destroy$))
      .subscribe(() => {
        this.updateChannelsFromForm();
        this.updateTypesFromForm();
        this.updateQuietHoursFromForm();
        this.updateExampleNotifications();
      });
  }

  private updateChannelsFromForm(): void {
    const formValue = this.preferencesForm.value;
    this.channels.forEach(channel => {
      channel.enabled = formValue[`${channel.id}Enabled`] || false;
    });
  }

  private updateTypesFromForm(): void {
    const formValue = this.preferencesForm.value;
    this.notificationTypes.forEach(type => {
      type.enabled = formValue[`${type.id}Enabled`] || false;
    });
  }

  private updateQuietHoursFromForm(): void {
    const formValue = this.preferencesForm.value;
    this.quietHoursEnabled = formValue.quietHoursEnabled || false;
    this.quietHoursStart = formValue.quietHoursStart || 22;
    this.quietHoursEnd = formValue.quietHoursEnd || 8;
  }

  private updateExampleNotifications(): void {
    const formValue = this.preferencesForm.value;
    const now = new Date();

    this.exampleNotifications = [];

    if (formValue.newDossierEnabled) {
      this.exampleNotifications.push({
        title: 'Nouveau dossier',
        message: 'Le dossier "Appartement 3 pièces Paris 15e" a été créé',
        timestamp: new Date(now.getTime() - 5 * 60000),
        type: 'newDossier',
        icon: 'folder'
      });
    }

    if (formValue.newMessageEnabled) {
      this.exampleNotifications.push({
        title: 'Nouveau message',
        message: 'Jean Dupont vous a envoyé un message',
        timestamp: new Date(now.getTime() - 15 * 60000),
        type: 'newMessage',
        icon: 'message'
      });
    }

    if (formValue.appointmentEnabled) {
      this.exampleNotifications.push({
        title: 'Rendez-vous à venir',
        message: 'Visite prévue dans 1 heure - 25 Rue de la Paix',
        timestamp: new Date(now.getTime() + 60 * 60000),
        type: 'appointment',
        icon: 'event'
      });
    }

    if (formValue.statusChangeEnabled) {
      this.exampleNotifications.push({
        title: 'Changement de statut',
        message: 'Le dossier "Villa Nice" est passé en "En cours"',
        timestamp: new Date(now.getTime() - 30 * 60000),
        type: 'statusChange',
        icon: 'update'
      });
    }
  }

  onSave(): void {
    if (!this.preferencesForm.valid) {
      this.notificationService.warning('Veuillez corriger les erreurs dans le formulaire');
      return;
    }

    this.saving = true;
    const formValue = this.preferencesForm.value;

    const notificationPreferences = {
      emailEnabled: formValue.emailEnabled,
      smsEnabled: formValue.smsEnabled,
      inAppEnabled: formValue.inAppEnabled,
      pushEnabled: formValue.pushEnabled,

      newDossierEnabled: formValue.newDossierEnabled,
      newMessageEnabled: formValue.newMessageEnabled,
      appointmentEnabled: formValue.appointmentEnabled,
      statusChangeEnabled: formValue.statusChangeEnabled,

      quietHoursEnabled: formValue.quietHoursEnabled,
      quietHoursStart: formValue.quietHoursStart,
      quietHoursEnd: formValue.quietHoursEnd,

      digestFrequency: formValue.digestFrequency
    };

    this.userPreferencesService.updatePreferences('notifications', notificationPreferences)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          this.originalValues = this.preferencesForm.value as Record<string, unknown>;
          this.saving = false;
          this.notificationService.success('Préférences de notification enregistrées avec succès');
        },
        error: (error) => {
          console.error('Error saving notification preferences:', error);
          this.saving = false;
          this.notificationService.error('Erreur lors de l\'enregistrement des préférences');
        }
      });
  }

  onCancel(): void {
    if (this.hasUnsavedChanges()) {
      this.preferencesForm.patchValue(this.originalValues);
      this.updateChannelsFromForm();
      this.updateTypesFromForm();
      this.updateQuietHoursFromForm();
      this.updateExampleNotifications();
      this.notificationService.info('Modifications annulées');
    }
  }

  hasUnsavedChanges(): boolean {
    return JSON.stringify(this.preferencesForm.value) !== JSON.stringify(this.originalValues);
  }

  formatQuietHoursLabel(value: number): string {
    return `${value.toString().padStart(2, '0')}:00`;
  }

  getQuietHoursDisplay(): string {
    return `${this.formatQuietHoursLabel(this.quietHoursStart)} - ${this.formatQuietHoursLabel(this.quietHoursEnd)}`;
  }

  getDigestFrequencyLabel(): string {
    const freq = this.digestFrequencies.find(f => f.value === this.preferencesForm.get('digestFrequency')?.value);
    return freq ? freq.label : '';
  }

  getDigestFrequencyDescription(): string {
    const freq = this.digestFrequencies.find(f => f.value === this.preferencesForm.get('digestFrequency')?.value);
    return freq ? freq.description : '';
  }

  getEnabledChannelsCount(): number {
    return this.channels.filter(c => c.enabled).length;
  }

  getEnabledTypesCount(): number {
    return this.notificationTypes.filter(t => t.enabled).length;
  }

  getRelativeTime(date: Date): string {
    const now = new Date();
    const diffMs = date.getTime() - now.getTime();
    const diffMins = Math.floor(diffMs / 60000);

    if (diffMins < 0) {
      const absMins = Math.abs(diffMins);
      if (absMins < 60) {
        return `Il y a ${absMins} min`;
      }
      const hours = Math.floor(absMins / 60);
      return `Il y a ${hours}h`;
    } else {
      if (diffMins < 60) {
        return `Dans ${diffMins} min`;
      }
      const hours = Math.floor(diffMins / 60);
      return `Dans ${hours}h`;
    }
  }

  isQuietHoursActive(): boolean {
    if (!this.quietHoursEnabled) {
      return false;
    }

    const now = new Date();
    const currentHour = now.getHours();

    if (this.quietHoursStart < this.quietHoursEnd) {
      // Normal range (e.g., 1h-5h)
      return currentHour >= this.quietHoursStart && currentHour < this.quietHoursEnd;
    } else {
      // Overnight range (e.g., 22h-8h)
      return currentHour >= this.quietHoursStart || currentHour < this.quietHoursEnd;
    }
  }

  getActiveChannelIcons(): string[] {
    return this.channels.filter(c => c.enabled).map(c => c.icon);
  }

  getDigestFrequencyIcon(): string {
    const freq = this.digestFrequencies.find(f => f.value === this.preferencesForm.get('digestFrequency')?.value);
    return freq ? freq.icon : '';
  }
}

import { Component } from '@angular/core';
import { CdkDragDrop, moveItemInArray, transferArrayItem, CdkDropList, CdkDrag } from '@angular/cdk/drag-drop';
import { ReportApiService, CustomReportDefinition, ReportColumn } from '../services/report-api.service';
import { MatSnackBar } from '@angular/material/snack-bar';
import { DsCardComponent } from '../design-system';
import { MatIcon } from '@angular/material/icon';
import { MatIconButton, MatButton } from '@angular/material/button';
import { MatFormField, MatLabel } from '@angular/material/form-field';
import { MatInput } from '@angular/material/input';
import { FormsModule } from '@angular/forms';
import { MatSelect } from '@angular/material/select';
import { MatOption } from '@angular/material/autocomplete';
import { MatTable, MatColumnDef, MatHeaderCellDef, MatHeaderCell, MatCellDef, MatCell, MatHeaderRowDef, MatHeaderRow, MatRowDef, MatRow } from '@angular/material/table';
import { DecimalPipe, CurrencyPipe } from '@angular/common';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';

interface DimensionOption {
  id: string;
  label: string;
  description: string;
}

interface MetricOption {
  id: string;
  label: string;
  description: string;
  aggregation: 'sum' | 'avg' | 'count' | 'min' | 'max';
}

@Component({
    selector: 'app-report-builder',
    templateUrl: './report-builder.component.html',
    styleUrls: ['./report-builder.component.scss'],
    imports: [DsCardComponent, DsSkeletonComponent, CdkDropList, CdkDrag, MatIcon, MatIconButton, MatButton, MatFormField, MatLabel, MatInput, FormsModule, MatSelect, MatOption, MatTable, MatColumnDef, MatHeaderCellDef, MatHeaderCell, MatCellDef, MatCell, MatHeaderRowDef, MatHeaderRow, MatRowDef, MatRow, DecimalPipe, CurrencyPipe]
})
export class ReportBuilderComponent {
  availableDimensions: DimensionOption[] = [
    { id: 'date', label: 'Date', description: 'Group by date' },
    { id: 'status', label: 'Status', description: 'Group by dossier status' },
    { id: 'source', label: 'Lead Source', description: 'Group by lead source' },
    { id: 'agent', label: 'Agent', description: 'Group by assigned agent' },
    { id: 'city', label: 'City', description: 'Group by property city' },
    { id: 'propertyType', label: 'Property Type', description: 'Group by property type' }
  ];

  availableMetrics: MetricOption[] = [
    { id: 'dossierCount', label: 'Dossier Count', description: 'Total number of dossiers', aggregation: 'count' },
    { id: 'conversionRate', label: 'Conversion Rate', description: 'Won/Total ratio', aggregation: 'avg' },
    { id: 'totalValue', label: 'Total Value', description: 'Sum of property values', aggregation: 'sum' },
    { id: 'avgResponseTime', label: 'Avg Response Time', description: 'Average response time in hours', aggregation: 'avg' },
    { id: 'appointmentCount', label: 'Appointment Count', description: 'Total appointments scheduled', aggregation: 'count' },
    { id: 'messageCount', label: 'Message Count', description: 'Total messages sent', aggregation: 'count' }
  ];

  selectedDimensions: DimensionOption[] = [];
  selectedMetrics: MetricOption[] = [];

  reportData: any[] = [];
  loading = false;
  reportGenerated = false;

  exportFormat: 'csv' | 'excel' | 'pdf' = 'pdf';
  reportTitle = 'Custom Report';
  reportSubtitle = '';

  constructor(
    private reportApiService: ReportApiService,
    private snackBar: MatSnackBar
  ) {}

  dropDimension(event: CdkDragDrop<DimensionOption[]>): void {
    if (event.previousContainer === event.container) {
      moveItemInArray(event.container.data, event.previousIndex, event.currentIndex);
    } else {
      transferArrayItem(
        event.previousContainer.data,
        event.container.data,
        event.previousIndex,
        event.currentIndex
      );
    }
  }

  dropMetric(event: CdkDragDrop<MetricOption[]>): void {
    if (event.previousContainer === event.container) {
      moveItemInArray(event.container.data, event.previousIndex, event.currentIndex);
    } else {
      transferArrayItem(
        event.previousContainer.data,
        event.container.data,
        event.previousIndex,
        event.currentIndex
      );
    }
  }

  removeDimension(dimension: DimensionOption): void {
    const index = this.selectedDimensions.indexOf(dimension);
    if (index >= 0) {
      this.selectedDimensions.splice(index, 1);
      this.availableDimensions.push(dimension);
    }
  }

  removeMetric(metric: MetricOption): void {
    const index = this.selectedMetrics.indexOf(metric);
    if (index >= 0) {
      this.selectedMetrics.splice(index, 1);
      this.availableMetrics.push(metric);
    }
  }

  generateReport(): void {
    if (this.selectedDimensions.length === 0 || this.selectedMetrics.length === 0) {
      this.snackBar.open('Please select at least one dimension and one metric', 'Close', { duration: 3000 });
      return;
    }

    this.loading = true;
    const definition: CustomReportDefinition = {
      dimensions: this.selectedDimensions.map(d => d.id),
      metrics: this.selectedMetrics.map(m => m.id),
      groupBy: this.selectedDimensions.map(d => d.id)
    };

    this.reportApiService.generateCustomReport(definition).subscribe({
      next: (data) => {
        this.reportData = data.results || [];
        this.reportGenerated = true;
        this.loading = false;
        this.snackBar.open('Report generated successfully', 'Close', { duration: 3000 });
      },
      error: (error) => {
        console.error('Error generating report', error);
        this.loading = false;
        this.snackBar.open('Error generating report', 'Close', { duration: 3000 });
        this.generateMockData();
      }
    });
  }

  async exportReport(): Promise<void> {
    if (!this.reportGenerated || this.reportData.length === 0) {
      this.snackBar.open('Please generate a report first', 'Close', { duration: 3000 });
      return;
    }

    const columns: ReportColumn[] = [
      ...this.selectedDimensions.map(d => ({
        field: d.id,
        header: d.label,
        format: 'text' as const
      })),
      ...this.selectedMetrics.map(m => ({
        field: m.id,
        header: m.label,
        format: m.id.includes('Rate') ? 'percentage' as const : 
                m.id.includes('Value') ? 'currency' as const : 'number' as const
      }))
    ];

    try {
      switch (this.exportFormat) {
        case 'csv':
          await this.reportApiService.exportToCSV(
            this.reportData, 
            columns, 
            `${this.reportTitle.replace(/\s+/g, '_')}.csv`
          );
          break;
        case 'excel':
          await this.reportApiService.exportToExcel(
            this.reportData, 
            columns, 
            `${this.reportTitle.replace(/\s+/g, '_')}.xlsx`
          );
          break;
        case 'pdf':
          await this.reportApiService.exportToPDF(
            this.reportData,
            columns,
            {
              title: this.reportTitle,
              subtitle: this.reportSubtitle || `Generated on ${new Date().toLocaleDateString('fr-FR')}`,
              branding: {
                companyName: 'CRM System',
                primaryColor: DS_CHART_FALLBACK_HEX['--ds-marine'],
              }
            },
            `${this.reportTitle.replace(/\s+/g, '_')}.pdf`
          );
          break;
      }
      this.snackBar.open('Report exported successfully', 'Close', { duration: 3000 });
    } catch (error) {
      console.error('Error exporting report', error);
      this.snackBar.open('Error exporting report', 'Close', { duration: 3000 });
    }
  }

  private generateMockData(): void {
    const mockData = [];
    for (let i = 0; i < 10; i++) {
      const row: any = {};
      this.selectedDimensions.forEach(dim => {
        switch (dim.id) {
          case 'date':
            row[dim.id] = new Date(2024, 0, i + 1).toISOString().split('T')[0];
            break;
          case 'status':
            row[dim.id] = ['NEW', 'QUALIFIED', 'APPOINTMENT', 'WON'][i % 4];
            break;
          case 'source':
            row[dim.id] = ['WEBSITE', 'REFERRAL', 'PHONE'][i % 3];
            break;
          case 'agent':
            row[dim.id] = `Agent ${i % 3 + 1}`;
            break;
          default:
            row[dim.id] = `Value ${i}`;
        }
      });
      this.selectedMetrics.forEach(metric => {
        switch (metric.id) {
          case 'dossierCount':
            row[metric.id] = Math.floor(Math.random() * 50) + 10;
            break;
          case 'conversionRate':
            row[metric.id] = Math.random() * 0.5 + 0.2;
            break;
          case 'totalValue':
            row[metric.id] = Math.floor(Math.random() * 500000) + 100000;
            break;
          case 'avgResponseTime':
            row[metric.id] = Math.random() * 24 + 1;
            break;
          default:
            row[metric.id] = Math.floor(Math.random() * 100);
        }
      });
      mockData.push(row);
    }
    this.reportData = mockData;
    this.reportGenerated = true;
  }

  resetReport(): void {
    this.selectedDimensions.forEach(d => this.availableDimensions.push(d));
    this.selectedMetrics.forEach(m => this.availableMetrics.push(m));
    this.selectedDimensions = [];
    this.selectedMetrics = [];
    this.reportData = [];
    this.reportGenerated = false;
  }

  getDisplayedColumns(): string[] {
    return [
      ...this.selectedDimensions.map(d => d.id),
      ...this.selectedMetrics.map(m => m.id)
    ];
  }
}

import { Injectable } from '@angular/core';
