import { Component, Inject, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { DocumentApiService, DocumentResponse } from '../services/document-api.service';
import { MatIconButton, MatButton } from '@angular/material/button';
import { MatIcon } from '@angular/material/icon';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';

export interface DocumentPreviewDialogData {
  document: DocumentResponse;
}

@Component({
    selector: 'app-document-preview-dialog',
    templateUrl: './document-preview-dialog.component.html',
    styleUrls: ['./document-preview-dialog.component.css'],
    imports: [MatIconButton, MatIcon, MatButton, DsSkeletonComponent]
})
export class DocumentPreviewDialogComponent implements OnInit {
  previewUrl: SafeResourceUrl | null = null;
  loading = true;
  error: string | null = null;
  isImage = false;
  isPdf = false;

  constructor(
    public dialogRef: MatDialogRef<DocumentPreviewDialogComponent>,
    @Inject(MAT_DIALOG_DATA) public data: DocumentPreviewDialogData,
    private documentApiService: DocumentApiService,
    private sanitizer: DomSanitizer
  ) {}

  ngOnInit(): void {
    this.loadPreview();
  }

  loadPreview(): void {
    this.loading = true;
    this.error = null;

    const contentType = this.data.document.contentType;
    this.isImage = contentType.startsWith('image/');
    this.isPdf = contentType === 'application/pdf';

    this.documentApiService.download(this.data.document.id)
      .subscribe({
        next: (blob) => {
          const url = window.URL.createObjectURL(blob);
          this.previewUrl = this.sanitizer.bypassSecurityTrustResourceUrl(url);
          this.loading = false;
        },
        error: (err) => {
          this.error = 'Échec du chargement de l\'aperçu';
          this.loading = false;
          console.error('Error loading preview:', err);
        }
      });
  }

  close(): void {
    this.dialogRef.close();
  }

  download(): void {
    this.documentApiService.download(this.data.document.id)
      .subscribe({
        next: (blob) => {
          const url = window.URL.createObjectURL(blob);
          const link = window.document.createElement('a');
          link.href = url;
          link.download = this.data.document.fileName;
          link.click();
          window.URL.revokeObjectURL(url);
        },
        error: (err) => {
          console.error('Error downloading document:', err);
        }
      });
  }

  formatFileSize(bytes: number): string {
    return this.documentApiService.formatFileSize(bytes);
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpEvent, HttpRequest } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface DocumentResponse {
  id: number;
  orgId: string;
  dossierId: number;
  fileName: string;
  fileType: string;
  fileSize: number;
  storagePath: string;
  uploadedBy: string;
  contentType: string;
  category?: string;
  createdAt: string;
  updatedAt: string;
}

export interface Page<T> {
  content: T[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
}

export enum DocumentCategory {
  CONTRACT = 'Contract',
  INVOICE = 'Invoice',
  ID = 'ID',
  PHOTO = 'Photo',
  OTHER = 'Other'
}

@Injectable({
  providedIn: 'root'
})
export class DocumentApiService {
  private baseUrl = '/api/v1/documents';

  constructor(private http: HttpClient) {}

  upload(dossierId: number, file: File, category?: string): Observable<HttpEvent<DocumentResponse>> {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('dossierId', dossierId.toString());
    if (category) {
      formData.append('category', category);
    }

    const req = new HttpRequest('POST', `${this.baseUrl}/upload`, formData, {
      reportProgress: true
    });

    return this.http.request<DocumentResponse>(req);
  }

  listByDossier(dossierId: number, page = 0, size = 20, sort = 'createdAt,desc'): Observable<Page<DocumentResponse>> {
    const params: any = { page: page.toString(), size: size.toString(), sort };
    return this.http.get<Page<DocumentResponse>>(`${this.baseUrl}/dossier/${dossierId}`, { params });
  }

  getById(documentId: number): Observable<DocumentResponse> {
    return this.http.get<DocumentResponse>(`${this.baseUrl}/${documentId}`);
  }

  download(documentId: number): Observable<Blob> {
    return this.http.get(`${this.baseUrl}/${documentId}/download`, {
      responseType: 'blob'
    });
  }

  delete(documentId: number): Observable<void> {
    return this.http.delete<void>(`${this.baseUrl}/${documentId}`);
  }

  getFileIcon(fileName: string, contentType?: string): string {
    const extension = fileName.split('.').pop()?.toLowerCase();
    
    if (contentType?.startsWith('image/') || ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp'].includes(extension || '')) {
      return 'image';
    }
    
    if (contentType === 'application/pdf' || extension === 'pdf') {
      return 'picture_as_pdf';
    }
    
    if (['doc', 'docx'].includes(extension || '') || contentType?.includes('word')) {
      return 'description';
    }
    
    if (['xls', 'xlsx'].includes(extension || '') || contentType?.includes('spreadsheet') || contentType?.includes('excel')) {
      return 'table_chart';
    }
    
    return 'insert_drive_file';
  }

  formatFileSize(bytes: number): string {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
  }

  isPreviewable(contentType: string): boolean {
    return contentType?.startsWith('image/') || contentType === 'application/pdf';
  }
}

