        change: 8.3,
        trend: 'up',
        icon: 'trending_up',
        color: '#2196f3'
      },
      {
        label: 'Win Rate',
        value: '32.5%',
        change: -2.1,
        trend: 'down',
        icon: 'flag',
        color: '#ff9800'
      },
      {
        label: 'Active Leads',
        value: 245,
        change: 5.7,
        trend: 'up',
