      Filesystem.deleteFile({
        path: fullPath,
        directory
      })
    ).pipe(
      map(() => ({
        success: true,
        path: fullPath
      })),
      catchError((error) => {
        console.error('Error deleting file:', error);
        return of({
          success: false,
          error: error.message || 'Failed to delete file'
        });
      })
    );
  }

  /**
   * Check if a file exists
   */
  fileExists(
    path: string,
    directory: Directory = this.documentsDir
  ): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    const fullPath = `${this.appFolder}/${path}`;

    return from(
      Filesystem.stat({
        path: fullPath,
        directory
      })
    ).pipe(
      map(() => true),
      catchError(() => of(false))
    );
  }

  /**
   * Get file metadata
   */
  getFileMetadata(
    path: string,
    directory: Directory = this.documentsDir
  ): Observable<FileMetadata | null> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    const fullPath = `${this.appFolder}/${path}`;

    return from(
      Filesystem.stat({
        path: fullPath,
        directory
      })
    ).pipe(
      map((result: StatResult) => ({
        name: path.split('/').pop() || path,
        size: result.size,
        mtime: result.mtime,
        ctime: result.ctime || 0,
        type: result.type,
        uri: result.uri
      })),
      catchError((error) => {
        console.error('Error getting file metadata:', error);
        return of(null);
      })
    );
  }

  /**
   * List files in a directory
   */
  listFiles(
    path = '',
    directory: Directory = this.documentsDir
  ): Observable<string[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    const fullPath = path ? `${this.appFolder}/${path}` : this.appFolder;

    return from(
      Filesystem.readdir({
        path: fullPath,
        directory
      })
    ).pipe(
      map((result) => result.files.map(f => f.name)),
      catchError((error) => {
        console.error('Error listing files:', error);
        return of([]);
      })
    );
  }

  /**
   * Copy a file
   */
