        shortcut: '?',
        action: () => {
          this.close();
          this.keyboardShortcutService.toggleShortcutHelp();
        }
      }
    ];
  }

  private initializeSearch(): void {
    this.searchSubject.pipe(
      debounceTime(300),
      distinctUntilChanged(),
      switchMap(query => {
        if (!query || query.length < 2) {
          return of(null);
        }
        this.isSearching = true;
        return this.searchApiService.autocomplete(query);
      }),
      takeUntil(this.destroy$)
    ).subscribe(response => {
      this.isSearching = false;
      this.updateFilteredItems(response?.results || []);
    });
  }

  onSearchChange(): void {
    this.searchSubject.next(this.searchQuery);

    // Immediate local filtering for responsiveness
    if (!this.searchQuery || this.searchQuery.length < 2) {
      this.updateFilteredItems();
    }
  }

  private updateFilteredItems(searchResults: SearchResult[] = []): void {
    const query = this.searchQuery.toLowerCase().trim();
    this.highlightMap.clear();

    let items: PaletteItem[] = [];

    if (!query) {
      // No query: contextual first, then recent, then global commands
      const recentItems = this.recentNavigationService.getRecentItems();
      items = [...this.contextualCommands, ...recentItems, ...this.globalCommands];
    } else {
      // Score + filter contextual commands
      const scoredContextual = this.scoreAndFilter(this.contextualCommands, query);
      // Score + filter global commands
      const scoredGlobal = this.scoreAndFilter(this.globalCommands, query);

      // Build highlight map for all matched commands
      [...scoredContextual, ...scoredGlobal].forEach(cmd => {
        const result = this.fuzzyScore(query, cmd.label);
        if (result.score > 0) {
          this.highlightMap.set(cmd.id, result.segments);
        }
      });

      items = [...scoredContextual, ...scoredGlobal, ...searchResults];

      // ── Agent mode: inject "Ask the agent" when query looks like NL ──
      const isNaturalLanguage = this.looksLikeNaturalLanguage(this.searchQuery.trim());
      const hasResults = items.length > 0;
      if (isNaturalLanguage || !hasResults) {
        const agentCommand: CommandItem = {
          id: 'ask-agent',
          label: `Demander à Atlas IA : « ${this.searchQuery.trim()} »`,
          description: 'Analyse en langage naturel — recherche, création, navigation…',
          icon: 'auto_awesome',
          category: 'Agent IA',
          keywords: [],
          action: () => {
            this.close();
            this.agentService.openPanel(this.searchQuery.trim());
          }
        };
        // Always show agent option first
        items = [agentCommand, ...items];
      }
    }

    this.filteredItems = items;
    this.selectedIndex = 0;
  }

  /**
   * Detects if the query is likely natural language rather than a command keyword.
   * Heuristics: ≥3 words, OR starts with a known agent verb, OR contains proper nouns.
   */
  private looksLikeNaturalLanguage(query: string): boolean {
    const wordCount = query.split(/\s+/).length;
    if (wordCount >= 3) return true;
    const agentVerbs = ['trouve', 'crée', 'envoie', 'cherche', 'montre', 'affiche', 'contacte', 'appelle'];
    const qLower = query.toLowerCase();
    return agentVerbs.some(v => qLower.startsWith(v));
  }

  /**
   * Scores all commands against the query and returns them sorted by relevance desc.
   * Commands scoring 0 are excluded.
   */
  private scoreAndFilter(commands: CommandItem[], query: string): CommandItem[] {
    return commands
      .map(cmd => {
        const scores = [
          this.fuzzyScore(query, cmd.label).score * 3,          // label weighted ×3
          this.fuzzyScore(query, cmd.description).score * 1.5,  // description ×1.5
          this.fuzzyScore(query, cmd.category).score,
          ...(cmd.keywords || []).map(k => this.fuzzyScore(query, k).score * 2)
        ];
        const best = Math.max(...scores);
        return { cmd, score: best };
      })
      .filter(({ score }) => score > 0)
      .sort((a, b) => b.score - a.score)
      .map(({ cmd }) => cmd);
  }

  /**
   * Returns a relevance score (0 = no match) plus highlight segments.
   * Scoring:
   *  - Exact start match  = 100
   *  - Substring match    = 70 + (proximity to start)
   *  - Fuzzy char match   = 10 + ratio of chars matched
   */
  private fuzzyScore(query: string, text: string): FuzzyResult {
    if (text == null || typeof text !== 'string') text = '';
    if (!text || !query) return { score: 0, segments: [{ text: String(text), match: false }] };

    const textLower = text.toLowerCase();
    const queryLower = query.toLowerCase();

    // ── Exact start match ────────────────────────────────────
    if (textLower.startsWith(queryLower)) {
      return {
        score: 100,
        segments: [
          { text: text.slice(0, query.length), match: true },
          { text: text.slice(query.length), match: false }
        ]
      };
    }

    // ── Substring match ──────────────────────────────────────
    const idx = textLower.indexOf(queryLower);
    if (idx !== -1) {
      const proximity = Math.max(0, 50 - idx); // higher score if closer to start
      return {
        score: 70 + proximity,
        segments: [
          { text: text.slice(0, idx), match: false },
          { text: text.slice(idx, idx + query.length), match: true },
          { text: text.slice(idx + query.length), match: false }
        ]
      };
    }

    // ── Fuzzy char match ─────────────────────────────────────
    let qi = 0;
    const segments: Array<{ text: string; match: boolean }> = [];
    let buf = '';
    let lastMatch = false;

    for (let i = 0; i < text.length && qi < queryLower.length; i++) {
      const isMatch = text[i].toLowerCase() === queryLower[qi];
      if (isMatch !== lastMatch) {
        if (buf) segments.push({ text: buf, match: lastMatch });
        buf = '';
        lastMatch = isMatch;
      }
      buf += text[i];
      if (isMatch) qi++;
    }
    // remaining text after last match char
    if (buf) segments.push({ text: buf, match: lastMatch });
    if (qi < text.length) {
      segments.push({ text: text.slice(qi), match: false });
    }

    if (qi === queryLower.length) {
      const ratio = queryLower.length / textLower.length;
      return { score: 10 + Math.round(ratio * 30), segments };
    }

    return { score: 0, segments: [{ text, match: false }] };
  }

  /** Get highlight segments for a given command id (populated after updateFilteredItems) */
  getHighlightSegments(item: PaletteItem): Array<{ text: string; match: boolean }> | null {
    if (!this.searchQuery || !this.isCommandItem(item)) return null;
    return this.highlightMap.get(item.id) || null;
  }

  onKeyDown(event: KeyboardEvent): void {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        this.selectedIndex = Math.min(this.selectedIndex + 1, this.filteredItems.length - 1);
        this.scrollToSelected();
        break;
      case 'ArrowUp':
        event.preventDefault();
        this.selectedIndex = Math.max(this.selectedIndex - 1, 0);
        this.scrollToSelected();
        break;
      case 'Enter':
        event.preventDefault();
        if (this.filteredItems[this.selectedIndex]) {
          this.executeItem(this.filteredItems[this.selectedIndex]);
        }
        break;
      case 'Escape':
        event.preventDefault();
        this.close();
        break;
    }
  }

  scrollToSelected(): void {
    setTimeout(() => {
      const selectedElement = document.querySelector('.command-item.selected');
      if (selectedElement) {
        selectedElement.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      }
    }, 0);
  }

  executeItem(item: PaletteItem): void {
    if (this.isCommandItem(item)) {
      item.action();
    } else if (this.isSearchResult(item)) {
      this.navigateToSearchResult(item);
    } else if (this.isRecentItem(item)) {
      this.navigateTo(item.route);
    }
    this.close();
  }

  selectItem(index: number): void {
    this.selectedIndex = index;
  }

  close(): void {
    this.keyboardShortcutService.closeCommandPalette();
  }

  private resetState(): void {
    this.searchQuery = '';
    this.filteredItems = [];
    this.selectedIndex = 0;
    this.isSearching = false;
    this.highlightMap.clear();
  }

  private navigateTo(path: string): void {
    this.router.navigate([path]);
  }

  private navigateToSearchResult(result: SearchResult): void {
    if (result.type === 'ANNONCE') {
      this.navigateTo(`/annonces/${result.id}`);
    } else if (result.type === 'DOSSIER') {
      this.navigateTo(`/dossiers/${result.id}`);
    }
  }

  private openCreateDossierDialog(): void {
    this.dialog.open(DossierCreateDialogComponent, {
      width: '600px',
      maxWidth: '95vw'
    });
  }

  getGroupedItems(): GroupedItems[] {
    const groups = new Map<string, PaletteItem[]>();

    // Fixed category order for clarity
    const ORDER = ['Actions contextuelles', 'Récents', 'Actions', 'Système', 'Navigation', 'Aide', 'Annonces trouvées', 'Dossiers trouvés', 'Autres'];

    this.filteredItems.forEach(item => {
      let category = 'Autres';

      if (this.isCommandItem(item)) {
        category = item.category;
      } else if (this.isSearchResult(item)) {
        category = item.type === 'ANNONCE' ? 'Annonces trouvées' : 'Dossiers trouvés';
      } else if (this.isRecentItem(item)) {
        category = 'Récents';
      }

      if (!groups.has(category)) {
        groups.set(category, []);
      }
      groups.get(category)?.push(item);
    });

    // Sort categories by predefined order
    return ORDER
      .filter(cat => groups.has(cat))
      .map(cat => ({ category: cat, items: groups.get(cat)! }));
  }

  getItemLabel(item: PaletteItem): string {
    if (this.isCommandItem(item)) return item.label;
    if (this.isSearchResult(item)) return item.title;
    if (this.isRecentItem(item)) return item.title;
    return '';
  }

  getItemDescription(item: PaletteItem): string {
    if (this.isCommandItem(item)) {
      // Support dynamic descriptions (functions)
      return typeof (item as any)._descFn === 'function'
        ? (item as any)._descFn()
        : item.description;
    }
    if (this.isSearchResult(item)) return item.description || '';
    if (this.isRecentItem(item)) return item.subtitle || '';
    return '';
  }

  getItemIcon(item: PaletteItem): string {
    if (this.isCommandItem(item)) {
      // Support dynamic icons (functions)
      return typeof (item as any)._iconFn === 'function'
        ? (item as any)._iconFn()
        : item.icon;
    }
    if (this.isSearchResult(item)) return item.type === 'ANNONCE' ? 'campaign' : 'folder';
    if (this.isRecentItem(item)) return item.type === 'annonce' ? 'campaign' : 'folder';
    return 'help';
  }

  getItemShortcut(item: PaletteItem): string | undefined {
    if (this.isCommandItem(item)) return item.shortcut;
    return undefined;
  }

  private isCommandItem(item: PaletteItem): item is CommandItem {
    return 'action' in item && typeof item.action === 'function';
  }

  private isSearchResult(item: PaletteItem): item is SearchResult {
    return 'relevanceScore' in item;
  }

  private isRecentItem(item: PaletteItem): item is RecentItem {
    return 'route' in item && 'timestamp' in item;
  }
}

import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { NotificationApiService, NotificationResponse } from '../services/notification-api.service';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { MatIcon } from '@angular/material/icon';
import { MatButtonToggleGroup, MatButtonToggle } from '@angular/material/button-toggle';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';
import { DsCardComponent } from '../design-system/primitives/ds-card/ds-card.component';
import { DsBadgeComponent } from '../design-system/primitives/ds-badge/ds-badge.component';
import { DsButtonComponent } from '../design-system/primitives/ds-button/ds-button.component';
import { DsIconComponent } from '../design-system/icons/ds-icon.component';

interface GroupedNotifications {
  date: string;
  displayDate: string;
  notifications: NotificationResponse[];
}

@Component({
    selector: 'app-notification-center',
    standalone: true,
    templateUrl: './notification-center.component.html',
    styleUrls: ['./notification-center.component.scss'],
    imports: [
      MatIcon,
      MatButtonToggleGroup,
      MatButtonToggle,
      DsSkeletonComponent,
      DsCardComponent,
      DsBadgeComponent,
      DsButtonComponent,
      DsIconComponent,
    ],
})
export class NotificationCenterComponent implements OnInit, OnDestroy {
  notifications: NotificationResponse[] = [];
  groupedNotifications: GroupedNotifications[] = [];
  loading = false;
  unreadCount = 0;
  selectedType = 'ALL';
  page = 0;
  size = 20;
  hasMore = true;
  
  private destroy$ = new Subject<void>();

  notificationTypes = [
    { value: 'ALL', label: 'Toutes' },
    { value: 'IN_APP', label: 'In-App' },
    { value: 'EMAIL', label: 'Email' },
    { value: 'SMS', label: 'SMS' },
    { value: 'WHATSAPP', label: 'WhatsApp' }
  ];

  constructor(
    private notificationApiService: NotificationApiService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.loadNotifications();
    this.notificationApiService.unreadCount$
      .pipe(takeUntil(this.destroy$))
      .subscribe(count => this.unreadCount = count);
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  loadNotifications(append = false): void {
    this.loading = true;
    const type = this.selectedType === 'ALL' ? undefined : this.selectedType;
    
    this.notificationApiService.list(undefined, type, undefined, this.page, this.size)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (response) => {
          const items = response.content ?? [];
          if (append) {
            this.notifications = [...this.notifications, ...items];
          } else {
            this.notifications = items;
          }
          const totalPages = response.totalPages ?? 0;
          this.hasMore =
            totalPages > 0 ? this.page < totalPages - 1 : items.length >= this.size;
          this.groupNotificationsByDate();
          this.loading = false;
        },
        error: (err) => {
          console.error('Error loading notifications:', err);
          this.loading = false;
        }
      });
  }

  groupNotificationsByDate(): void {
    const groups = new Map<string, NotificationResponse[]>();
    
    this.notifications.forEach(notification => {
      const date = new Date(notification.createdAt);
      const dateKey = this.getDateKey(date);
      
      if (!groups.has(dateKey)) {
        groups.set(dateKey, []);
      }
      const group = groups.get(dateKey);
      if (group) {
        group.push(notification);
      }
    });

    this.groupedNotifications = Array.from(groups.entries()).map(([date, notifications]) => ({
      date,
      displayDate: this.getDisplayDate(date),
      notifications
    }));
  }

  getDateKey(date: Date): string {
    return date.toISOString().split('T')[0];
  }

  getDisplayDate(dateKey: string): string {
    const date = new Date(dateKey);
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    const dateString = date.toISOString().split('T')[0];
    const todayString = today.toISOString().split('T')[0];
    const yesterdayString = yesterday.toISOString().split('T')[0];

    if (dateString === todayString) {
      return "Aujourd'hui";
    } else if (dateString === yesterdayString) {
      return 'Hier';
    } else {
      return date.toLocaleDateString('fr-FR', { 
        weekday: 'long', 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
      });
    }
  }

  onFilterChange(type: string): void {
    this.selectedType = type;
    this.page = 0;
    this.notifications = [];
    this.loadNotifications();
  }

  loadMore(): void {
    if (!this.loading && this.hasMore) {
      this.page++;
      this.loadNotifications(true);
    }
  }

  markAsRead(notification: NotificationResponse, event?: Event): void {
    if (event) {
      event.stopPropagation();
    }
    
    if (notification.readAt) {
      return;
    }

    this.notificationApiService.markAsRead(notification.id)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (updatedNotification) => {
          const index = this.notifications.findIndex(n => n.id === notification.id);
          if (index !== -1) {
            this.notifications[index] = updatedNotification;
            this.groupNotificationsByDate();
          }
        },
        error: (err) => console.error('Error marking notification as read:', err)
      });
  }

  markAsUnread(notification: NotificationResponse, event: Event): void {
    event.stopPropagation();
    
    if (!notification.readAt) {
      return;
    }

    this.notificationApiService.markAsUnread(notification.id)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (updatedNotification) => {
          const index = this.notifications.findIndex(n => n.id === notification.id);
          if (index !== -1) {
            this.notifications[index] = updatedNotification;
            this.groupNotificationsByDate();
          }
        },
        error: (err) => console.error('Error marking notification as unread:', err)
      });
  }

  onNotificationClick(notification: NotificationResponse): void {
    this.markAsRead(notification);

    if (notification.actionUrl) {
      this.router.navigateByUrl(notification.actionUrl);
    } else if (notification.dossierId) {
      this.router.navigate(['/dossiers', notification.dossierId]);
    }
  }

  getNotificationIcon(type: string): string {
    switch (type) {
      case 'EMAIL':
        return 'mail';
      case 'SMS':
        return 'phone';
      case 'WHATSAPP':
        return 'whatsapp';
      case 'IN_APP':
        return 'tasks';
      default:
        return 'info';
    }
  }

  getNotificationTitle(notification: NotificationResponse): string {
    return notification.subject || notification.message || 'Notification';
  }

  getNotificationMessage(notification: NotificationResponse): string {
    if (notification.message) {
      return notification.message.length > 100 
        ? notification.message.substring(0, 100) + '...' 
        : notification.message;
    }
    return notification.subject || '';
  }

  getTimeAgo(dateString: string): string {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) {
      return "À l'instant";
    } else if (diffMins < 60) {
      return `Il y a ${diffMins} min`;
    } else if (diffHours < 24) {
      return `Il y a ${diffHours}h`;
    } else if (diffDays < 7) {
      return `Il y a ${diffDays}j`;
    } else {
      return date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
    }
  }

  isUnread(notification: NotificationResponse): boolean {
    return !notification.readAt;
  }

  refresh(): void {
    this.page = 0;
    this.notifications = [];
    this.loadNotifications();
    this.notificationApiService.refreshUnreadCount();
  }
}

import { Component, OnInit, OnDestroy, HostListener, viewChild } from '@angular/core';
import { Router } from '@angular/router';
import { SearchApiService, SearchResult } from '../services/search-api.service';
import { debounceTime, distinctUntilChanged, switchMap, catchError } from 'rxjs/operators';
import { Subject, of, Subscription } from 'rxjs';
import { FormsModule } from '@angular/forms';
import { UpperCasePipe } from '@angular/common';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';
import { DsInputComponent } from '../design-system/primitives/ds-input/ds-input.component';

interface GroupedResults {
  annonces: EnhancedSearchResult[];
  dossiers: EnhancedSearchResult[];
  contacts: EnhancedSearchResult[];
}

interface EnhancedSearchResult extends SearchResult {
  highlightedTitle?: string;
  highlightedDescription?: string;
  preview?: any;
}

interface RecentSearch {
  query: string;
  timestamp: number;
}

@Component({
    selector: 'app-global-search-bar',
    templateUrl: './global-search-bar.component.html',
    styleUrls: ['./global-search-bar.component.scss'],
    imports: [FormsModule, UpperCasePipe, DsSkeletonComponent, DsInputComponent]
})
export class GlobalSearchBarComponent implements OnInit, OnDestroy {
  readonly searchInput = viewChild.required(DsInputComponent);

  /** Icône loupe (alignée sur le pattern filter-bar). */
  readonly searchPrefixIcon =
    '<svg width="15" height="15" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><circle cx="7" cy="7" r="5" stroke="currentColor" stroke-width="1.5"/><path d="M14 14l-2.5-2.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>';

  searchQuery = '';
  groupedResults: GroupedResults = {
    annonces: [],
    dossiers: [],
    contacts: []
  };
  recentSearches: RecentSearch[] = [];
  totalHits = 0;
  elasticsearchAvailable = false;
  showDropdown = false;
  isLoading = false;
  error = '';
  hoveredResult: EnhancedSearchResult | null = null;
  selectedIndex = -1;
  flatResults: EnhancedSearchResult[] = [];

  private searchSubject = new Subject<string>();
  private subscriptions = new Subscription();
  private readonly RECENT_SEARCHES_KEY = 'globalSearchRecent';
  private readonly MAX_RECENT_SEARCHES = 5;

  constructor(
    private searchService: SearchApiService,
    private router: Router
  ) {}

  ngOnInit() {
    this.loadRecentSearches();
    
    const searchSub = this.searchSubject
      .pipe(
        debounceTime(300),
        distinctUntilChanged(),
        switchMap(query => {
          if (!query || query.trim().length < 2) {
            return of({ results: [], totalHits: 0, elasticsearchAvailable: false });
          }
          this.isLoading = true;
          this.error = '';
          return this.searchService.autocomplete(query).pipe(
            catchError(() => {
              this.error = 'Échec de la recherche. Veuillez réessayer.';
              return of({ results: [], totalHits: 0, elasticsearchAvailable: false });
            })
          );
        })
      )
      .subscribe(response => {
        const enhancedResults = this.enhanceResults(response.results, this.searchQuery);
        this.groupResults(enhancedResults);
        this.totalHits = response.totalHits;
        this.elasticsearchAvailable = response.elasticsearchAvailable;
        this.isLoading = false;
        this.selectedIndex = -1;
      });

    this.subscriptions.add(searchSub);
  }

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
  }

  onSearchQueryChange(query: string): void {
    this.searchSubject.next(query);
  }

  onFocus() {
    this.showDropdown = true;
  }

  onBlur() {
    setTimeout(() => {
      this.showDropdown = false;
      this.hoveredResult = null;
    }, 200);
  }

  clearSearch() {
    this.searchQuery = '';
    this.groupedResults = { annonces: [], dossiers: [], contacts: [] };
    this.flatResults = [];
    this.totalHits = 0;
    this.showDropdown = false;
    this.selectedIndex = -1;
    this.hoveredResult = null;
  }

  navigateToResult(result: EnhancedSearchResult) {
    this.saveRecentSearch(this.searchQuery);
    
    if (result.type === 'annonce') {
      this.router.navigate(['/annonces', result.id]);
    } else if (result.type === 'dossier') {
      this.router.navigate(['/dossiers', result.id]);
    } else if (result.type === 'contact') {
      this.router.navigate(['/parties-prenantes', result.id]);
    }
    this.clearSearch();
  }

  viewAllResults() {
    this.saveRecentSearch(this.searchQuery);
    this.router.navigate(['/search'], { queryParams: { q: this.searchQuery } });
    this.clearSearch();
  }

  selectRecentSearch(search: RecentSearch) {
    this.searchQuery = search.query;
    this.searchSubject.next(search.query);
    this.searchInput().focus();
  }

  removeRecentSearch(search: RecentSearch, event: Event) {
    event.stopPropagation();
    this.recentSearches = this.recentSearches.filter(s => s.timestamp !== search.timestamp);
    this.saveRecentSearchesToStorage();
  }

  onResultHover(result: EnhancedSearchResult) {
    this.hoveredResult = result;
  }

  onResultLeave() {
    this.hoveredResult = null;
  }

  @HostListener('window:keydown', ['$event'])
  handleKeyboardShortcut(event: KeyboardEvent) {
    if (event.key === '/' && document.activeElement?.tagName !== 'INPUT' && document.activeElement?.tagName !== 'TEXTAREA') {
      event.preventDefault();
      this.searchInput().focus();
      return;
    }

    if (!this.showDropdown || this.flatResults.length === 0) {
      return;
    }

    switch (event.key) {
      case 'Tab':
        event.preventDefault();
        if (event.shiftKey) {
          this.navigatePrevious();
        } else {
          this.navigateNext();
        }
        break;
      case 'ArrowDown':
        event.preventDefault();
        this.navigateNext();
        break;
      case 'ArrowUp':
        event.preventDefault();
        this.navigatePrevious();
        break;
      case 'Enter':
        event.preventDefault();
        if (this.selectedIndex >= 0 && this.selectedIndex < this.flatResults.length) {
          this.navigateToResult(this.flatResults[this.selectedIndex]);
        }
        break;
      case 'Escape':
        event.preventDefault();
        this.clearSearch();
        this.searchInput()?.blur();
        break;
    }
  }

  private navigateNext() {
    this.selectedIndex = (this.selectedIndex + 1) % this.flatResults.length;
    this.scrollToSelected();
  }

  private navigatePrevious() {
    this.selectedIndex = this.selectedIndex <= 0 ? this.flatResults.length - 1 : this.selectedIndex - 1;
    this.scrollToSelected();
  }

  private scrollToSelected() {
    setTimeout(() => {
      const element = document.getElementById(`search-result-${this.selectedIndex}`);
      if (element) {
        element.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      }
    }, 0);
  }

  private enhanceResults(results: SearchResult[], query: string): EnhancedSearchResult[] {
    const fuzzyResults = this.fuzzyFilter(results, query);
    return fuzzyResults.map(result => ({
      ...result,
      highlightedTitle: this.highlightText(result.title, query),
      highlightedDescription: result.description ? this.highlightText(result.description, query) : undefined,
      preview: this.generatePreview(result)
    }));
  }

  private fuzzyFilter(results: SearchResult[], query: string): SearchResult[] {
    if (!query) return results;
    
    const lowerQuery = query.toLowerCase();
    
    return results
      .map(result => {
        const titleScore = this.fuzzyScore(result.title.toLowerCase(), lowerQuery);
        const descScore = result.description ? this.fuzzyScore(result.description.toLowerCase(), lowerQuery) : 0;
        const maxScore = Math.max(titleScore, descScore);
        
        return { result, score: maxScore };
      })
      .filter(item => item.score > 0)
      .sort((a, b) => b.score - a.score)
      .map(item => item.result);
  }

  private fuzzyScore(text: string, query: string): number {
    let score = 0;
    let queryIndex = 0;
    let textIndex = 0;
    let consecutiveMatches = 0;

    while (textIndex < text.length && queryIndex < query.length) {
      if (text[textIndex] === query[queryIndex]) {
        score += 1 + consecutiveMatches;
        consecutiveMatches++;
        queryIndex++;
      } else {
        consecutiveMatches = 0;
      }
      textIndex++;
    }

    if (queryIndex === query.length) {
      score += 10;
    }

    return score;
  }

  private highlightText(text: string, query: string): string {
    if (!query || !text) return text;
    
    const regex = new RegExp(`(${this.escapeRegex(query)})`, 'gi');
    return text.replace(regex, '<mark>$1</mark>');
  }

  private escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  private generatePreview(result: SearchResult): any {
    const preview: any = {
      id: result.id,
      type: result.type
    };

    if (result.type === 'annonce') {
      preview.details = [
        { label: 'Type', value: result.description || 'N/A' },
        { label: 'Créé', value: this.formatDate(result.createdAt) },
        { label: 'Modifié', value: this.formatDate(result.updatedAt) }
      ];
    } else if (result.type === 'dossier') {
      preview.details = [
        { label: 'Description', value: result.description || 'N/A' },
        { label: 'Créé', value: this.formatDate(result.createdAt) },
        { label: 'Score', value: result.relevanceScore?.toFixed(2) || 'N/A' }
      ];
    } else if (result.type === 'contact') {
      preview.details = [
        { label: 'Info', value: result.description || 'N/A' },
        { label: 'Créé', value: this.formatDate(result.createdAt) }
      ];
    }

    return preview;
  }

  private formatDate(dateString: string): string {
    if (!dateString) return 'N/A';
    const date = new Date(dateString);
    return date.toLocaleDateString('fr-FR', { 
      year: 'numeric', 
      month: 'short', 
      day: 'numeric' 
    });
  }

  private groupResults(results: EnhancedSearchResult[]) {
    this.groupedResults = {
      annonces: results.filter(r => r.type === 'annonce'),
      dossiers: results.filter(r => r.type === 'dossier'),
      contacts: results.filter(r => r.type === 'contact')
    };

    this.flatResults = [
      ...this.groupedResults.annonces,
      ...this.groupedResults.dossiers,
      ...this.groupedResults.contacts
    ];
  }

  private loadRecentSearches() {
    try {
      const stored = localStorage.getItem(this.RECENT_SEARCHES_KEY);
      if (stored) {
        this.recentSearches = JSON.parse(stored);
      }
    } catch (e) {
      console.error('Failed to load recent searches', e);
      this.recentSearches = [];
    }
  }

  private saveRecentSearch(query: string) {
    if (!query || query.trim().length < 2) return;

    this.recentSearches = this.recentSearches.filter(s => s.query !== query);
    
    this.recentSearches.unshift({
      query: query.trim(),
      timestamp: Date.now()
    });

    if (this.recentSearches.length > this.MAX_RECENT_SEARCHES) {
      this.recentSearches = this.recentSearches.slice(0, this.MAX_RECENT_SEARCHES);
    }

    this.saveRecentSearchesToStorage();
  }

  private saveRecentSearchesToStorage() {
    try {
      localStorage.setItem(this.RECENT_SEARCHES_KEY, JSON.stringify(this.recentSearches));
    } catch (e) {
      console.error('Failed to save recent searches', e);
    }
  }

  get hasResults(): boolean {
    return this.flatResults.length > 0;
  }

  get showRecentSearches(): boolean {
    return !this.searchQuery && this.recentSearches.length > 0;
  }

  isSelected(index: number): boolean {
    return this.selectedIndex === index;
  }

  getResultIndex(group: string, groupIndex: number): number {
    let index = groupIndex;
    if (group === 'dossiers') {
      index += this.groupedResults.annonces.length;
    } else if (group === 'contacts') {
      index += this.groupedResults.annonces.length + this.groupedResults.dossiers.length;
    }
    return index;
  }

  truncate(text: string, length: number): string {
    if (!text) return '';
    return text.length > length ? text.substring(0, length) + '...' : text;
  }
}

