export interface LeadImportRequest {
  file: File;
  duplicateStrategy: 'SKIP' | 'OVERWRITE' | 'CREATE_NEW';
}

export interface LeadImportError {
  row: number;
  field: string;
  message: string;
}

export interface LeadImportResponse {
  importJobId: number;
  totalRows: number;
  successCount: number;
  errorCount: number;
  skippedCount: number;
  validationErrors: LeadImportError[];
}

export interface ImportJobResponse {
  id: number;
  filename: string;
  status: 'IN_PROGRESS' | 'COMPLETED' | 'FAILED';
  totalRows: number;
  successCount: number;
  errorCount: number;
  skippedCount: number;
  errorReport: string;
  createdAt: string;
  createdBy: string;
}

export interface LeadExportRequest {
  columns: string[];
  status?: string;
  startDate?: string;
  endDate?: string;
  source?: string;
}

@Injectable({
  providedIn: 'root'
})
export class LeadApiService {
  private readonly apiUrl = '/api/v1/leads';

  constructor(private http: HttpClient) {}

  importLeads(file: File, duplicateStrategy: string): Observable<LeadImportResponse> {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('mergeStrategy', duplicateStrategy);

    return this.http.post<LeadImportResponse>(`${this.apiUrl}/import`, formData);
  }

  getImportHistory(): Observable<ImportJobResponse[]> {
    return this.http.get<ImportJobResponse[]>(`${this.apiUrl}/import/history`);
  }

  getImportJobById(id: number): Observable<ImportJobResponse> {
    return this.http.get<ImportJobResponse>(`${this.apiUrl}/import/history/${id}`);
  }

  exportLeads(request: LeadExportRequest): Observable<Blob> {
    let params = new HttpParams();
    
    if (request.columns && request.columns.length > 0) {
      params = params.set('columns', request.columns.join(','));
    }
    
    if (request.status) {
      params = params.set('status', request.status);
    }
    if (request.startDate) {
      params = params.set('startDate', request.startDate);
    }
    if (request.endDate) {
      params = params.set('endDate', request.endDate);
    }
    if (request.source) {
      params = params.set('source', request.source);
    }

    return this.http.get(`${this.apiUrl}/export`, {
      params,
      responseType: 'blob',
      observe: 'response'
    }).pipe(
      map((response: HttpResponse<Blob>) => response.body as Blob)
    );
  }
}

import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

// ─── Intent Types ────────────────────────────────────────────
export type AgentIntentType =
    | 'SEARCH'
    | 'CREATE'
    | 'STATUS_CHANGE'
    | 'SEND_MESSAGE'
    | 'NAVIGATE'
    | 'UNKNOWN';

export interface AgentIntent {
    type: AgentIntentType;
    confidence: number;       // 0–1
    query: string;            // original query
    params: Record<string, string>;
    /** Human-readable description of what the agent will do */
    description: string;
    /** Quick-action chips for the UI */
    suggestedActions?: AgentAction[];
}

export interface AgentAction {
    label: string;
    icon: string;
    handler: () => void;
}

export interface AgentMessage {
    id: string;
    role: 'user' | 'agent';
    content: string;
    timestamp: Date;
    intent?: AgentIntent;
    actions?: AgentAction[];
    isTyping?: boolean;
}

// ─── Keyword maps ─────────────────────────────────────────────
interface IntentPattern {
    type: AgentIntentType;
    verbs: string[];
    weight: number;
}

const INTENT_PATTERNS: IntentPattern[] = [
    {
        type: 'SEARCH',
        verbs: ['trouve', 'trouv', 'cherche', 'montre', 'affiche', 'liste', 'show', 'find', 'search', 'voir tous', 'quels'],
        weight: 3
    },
    {
        type: 'CREATE',
        verbs: ['crée', 'créer', 'nouveau', 'nouvelle', 'ajoute', 'ajouter', 'nouveau lead', 'new', 'créer un', 'ouvrir un'],
        weight: 3
    },
    {
        type: 'STATUS_CHANGE',
        verbs: ['statut', 'status', 'marque', 'marquer', 'archive', 'archiver', 'clôture', 'ferme', 'gagne', 'perdu', 'qualifie', 'changer statut'],
        weight: 2
    },
    {
        type: 'SEND_MESSAGE',
        verbs: ['envoie', 'envoyer', 'message', 'whatsapp', 'sms', 'contacte', 'contacter', 'appelle', 'appeler', 'écris', 'écrire'],
        weight: 2
    },
    {
        type: 'NAVIGATE',
        verbs: ['va', 'aller', 'ouvre', 'ouvrir', 'navigue', 'page', 'go to', 'tableau de bord', 'dashboard', 'calendrier', 'dossiers', 'annonces', 'rapports'],
        weight: 1
    }
];

// ─── Entity extraction helpers ────────────────────────────────
const PROPERTY_TYPES = ['t1', 't2', 't3', 't4', 't5', 'studio', 'villa', 'appartement', 'maison', 'bureau', 'local', 'terrain'];
const CITIES = ['casablanca', 'rabat', 'marrakech', 'fes', 'agadir', 'tanger', 'meknes', 'oujda', 'tetouan'];
const STATUS_MAP: Record<string, string> = {
    'nouveau': 'NEW', 'qualifié': 'QUALIFIED', 'qualification': 'QUALIFYING',
    'rendez-vous': 'APPOINTMENT', 'rdv': 'APPOINTMENT',
    'gagné': 'WON', 'perdu': 'LOST', 'archivé': 'LOST'
};

/**
 * AiAgentService — Atlas 2026 Phase 2 Frontend Layer
 *
 * Provides:
 * 1. Local intent parsing (no backend required) — instant, offline-capable
 * 2. Backend stub (POST /api/ai/agent) — for future LLM integration
 * 3. Conversation state management (BehaviorSubject)
 * 4. Action dispatch to Angular Router and API services
 */
@Injectable({ providedIn: 'root' })
export class AiAgentService {

    private readonly API_URL = '/api/ai/agent';

    /** Whether the AI panel is open */
    private _panelOpen$ = new BehaviorSubject<boolean>(false);
    panelOpen$ = this._panelOpen$.asObservable();

    /** Conversational history for the session */
    private _messages$ = new BehaviorSubject<AgentMessage[]>([]);
    messages$ = this._messages$.asObservable();

    /** Pre-filled query when opening from CMD+K */
    private _pendingQuery$ = new BehaviorSubject<string>('');
    pendingQuery$ = this._pendingQuery$.asObservable();

    constructor(private router: Router, private http: HttpClient) { }

    // ─── Panel lifecycle ────────────────────────────────────────
    openPanel(query = ''): void {
        this._pendingQuery$.next(query);
        this._panelOpen$.next(true);
    }

    closePanel(): void {
        this._panelOpen$.next(false);
        this._pendingQuery$.next('');
    }

    togglePanel(): void {
        if (this._panelOpen$.value) {
            this.closePanel();
        } else {
            this.openPanel();
        }
    }

    clearConversation(): void {
        this._messages$.next([]);
    }

    // ─── Main entry point ───────────────────────────────────────
    /**
     * Process a natural-language query:
     * 1. Parse intent locally
     * 2. If intent is clear (confidence ≥ 0.7) and not UNKNOWN → dispatch immediately
     * 3. Otherwise → add to conversation, try backend, return conversational response
     */
    processQuery(rawQuery: string): Observable<AgentIntent> {
        const query = rawQuery.trim();
        const intent = this.parseIntent(query);

        // Add user message to conversation
        this.addMessage({ role: 'user', content: query });

        if (intent.type !== 'UNKNOWN' && intent.confidence >= 0.65) {
            // High-confidence → dispatch and return immediately
            this.addTypingIndicator();
            this.dispatchIntent(intent);
            return of(intent);
        }

        // Low-confidence or UNKNOWN → call backend, fallback to local response
        this.addTypingIndicator();
        return this.callBackend(query).pipe(
            map(serverIntent => {
                const finalIntent = serverIntent ?? intent;
                this.dispatchIntent(finalIntent);
                return finalIntent;
            }),
            catchError(() => {
                this.dispatchIntent(intent);
                return of(intent);
            })
        );
    }

    // ─── Local intent parser ────────────────────────────────────
    parseIntent(query: string): AgentIntent {
        const q = query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

        let bestType: AgentIntentType = 'UNKNOWN';
        let bestScore = 0;

        for (const pattern of INTENT_PATTERNS) {
            for (const verb of pattern.verbs) {
                if (q.includes(verb)) {
                    const score = pattern.weight + (q.startsWith(verb) ? 2 : 0);
                    if (score > bestScore) {
                        bestScore = score;
                        bestType = pattern.type;
                    }
                }
            }
        }

        const confidence = bestScore > 0 ? Math.min(0.5 + (bestScore * 0.1), 1) : 0.2;
        const params = this.extractEntities(q, query);

        return {
            type: bestType,
            confidence,
            query,
            params,
            description: this.describeIntent(bestType, params, query),
            suggestedActions: this.buildSuggestedActions(bestType, params)
        };
    }

    // ─── Entity extraction ──────────────────────────────────────
    private extractEntities(qNorm: string, qOrig: string): Record<string, string> {
        const params: Record<string, string> = {};

        // Property type
        for (const type of PROPERTY_TYPES) {
            if (qNorm.includes(type)) {
                params['propertyType'] = type.toUpperCase();
                break;
            }
        }

        // City
        for (const city of CITIES) {
            if (qNorm.includes(city)) {
                params['city'] = city.charAt(0).toUpperCase() + city.slice(1);
                break;
            }
        }

        // Budget extraction (e.g. "2M MAD", "500000", "1.5 million")
        const budgetMatch = qOrig.match(/(\d[\d\s.,]*)(?:\s*M(?:AD)?|\s*million)?/i);
        if (budgetMatch) {
            let val = parseFloat(budgetMatch[1].replace(/[\s,]/g, '').replace('.', '.'));
            if (qOrig.toLowerCase().includes('million') || qOrig.toLowerCase().match(/\d+m\b/i)) {
                val *= 1_000_000;
            }
            if (val > 1000) {
                params['budget'] = String(Math.round(val));
            }
        }

        // Person name (capitalised words after "pour", "de", "à")
        const nameMatch = qOrig.match(/(?:pour|de|à|monsieur|madame|mr|mme)\s+([A-ZÀ-Ü][a-zà-ü]+(?:\s+[A-ZÀ-Ü][a-zà-ü]+)?)/);
        if (nameMatch) {
            params['personName'] = nameMatch[1];
        }

        // Status
        for (const [fr, en] of Object.entries(STATUS_MAP)) {
            if (qNorm.includes(fr)) {
                params['status'] = en;
                break;
            }
        }

        // Search terms: everything after the main verb
        const searchTermMatch = qOrig.match(/(?:trouve|cherche|montre|affiche|liste)\s+(.+)/i);
        if (searchTermMatch) {
            params['searchQuery'] = searchTermMatch[1].trim();
        }

        return params;
    }

    // ─── Intent description (for UI display) ───────────────────
    private describeIntent(type: AgentIntentType, params: Record<string, string>, query: string): string {
        switch (type) {
            case 'SEARCH': {
                const parts: string[] = [];
                if (params['propertyType']) parts.push(params['propertyType']);
                if (params['city']) parts.push(`à ${params['city']}`);
                if (params['budget']) parts.push(`< ${Number(params['budget']).toLocaleString('fr-MA')} MAD`);
                return parts.length > 0
                    ? `Rechercher : ${parts.join(', ')}`
                    : `Rechercher "${params['searchQuery'] || query}"`;
            }
            case 'CREATE':
                return params['personName']
                    ? `Créer un dossier pour ${params['personName']}`
                    : 'Créer un nouveau dossier / lead';
            case 'STATUS_CHANGE':
                return params['status']
                    ? `Changer le statut en "${params['status']}"`
                    : 'Modifier le statut d\'un dossier';
            case 'SEND_MESSAGE':
                return params['personName']
                    ? `Envoyer un message à ${params['personName']}`
                    : 'Ouvrir la messagerie WhatsApp';
            case 'NAVIGATE':
                return `Naviguer vers une section`;
            default:
                return 'Je vais analyser votre demande…';
        }
    }

    // ─── Action dispatch ────────────────────────────────────────
    dispatchIntent(intent: AgentIntent): void {
        const { type, params } = intent;

        switch (type) {
            case 'SEARCH': {
                const q = [
                    params['propertyType'],
                    params['city'],
                    params['searchQuery']
                ].filter(Boolean).join(' ').trim() || intent.query;

                this.router.navigate(['/search'], { queryParams: { q } });

                this.addAgentMessage(
                    `🔍 Je recherche "${q}" dans les annonces et dossiers.`,
                    intent
                );
                break;
            }

            case 'CREATE':
                this.router.navigate(['/dossiers'], { queryParams: { action: 'create' } });
                this.addAgentMessage(
                    params['personName']
                        ? `✅ J'ouvre le formulaire de création pour **${params['personName']}**.`
                        : `✅ J'ouvre le formulaire de création de dossier.`,
                    intent
                );
                break;

            case 'STATUS_CHANGE':
                this.addAgentMessage(
                    `🔄 Pour changer un statut, ouvrez d'abord le dossier concerné. Voulez-vous que je cherche un dossier spécifique ?`,
                    intent
                );
                break;

            case 'SEND_MESSAGE':
                this.router.navigate(['/dossiers'], { queryParams: { action: 'message' } });
                this.addAgentMessage(
                    params['personName']
                        ? `💬 Recherche du dossier de **${params['personName']}** pour ouvrir la messagerie…`
                        : `💬 Ouvrez un dossier et utilisez l'onglet Messagerie pour envoyer un WhatsApp.`,
                    intent
                );
                break;

            case 'NAVIGATE':
                this.handleNavigation(intent.query);
                this.addAgentMessage(`🧭 Navigation en cours…`, intent);
                break;

            default:
                this.addAgentMessage(
                    `Je n'ai pas compris votre demande. Essayez : *"Trouve des T3 à Casablanca"*, *"Crée un dossier"*, ou *"Envoie un message à M. Alami"*.`,
                    intent
                );
        }
    }

    private handleNavigation(query: string): void {
        const q = query.toLowerCase();
        if (q.includes('dashboard') || q.includes('tableau de bord')) {
            this.router.navigate(['/dashboard']);
        } else if (q.includes('dossier') || q.includes('lead')) {
            this.router.navigate(['/dossiers']);
        } else if (q.includes('annonce')) {
            this.router.navigate(['/annonces']);
        } else if (q.includes('calendrier') || q.includes('rdv')) {
            this.router.navigate(['/calendar']);
        } else if (q.includes('rapport') || q.includes('kpi')) {
            this.router.navigate(['/reports']);
        } else if (q.includes('tâche') || q.includes('task')) {
            this.router.navigate(['/tasks']);
        }
    }

    // ─── Suggested chips ────────────────────────────────────────
    private buildSuggestedActions(type: AgentIntentType, _params: Record<string, string>): AgentAction[] {
        switch (type) {
            case 'SEARCH':
                return [
                    { label: 'Voir les annonces', icon: 'campaign', handler: () => this.router.navigate(['/annonces']) },
                    { label: 'Voir les dossiers', icon: 'folder', handler: () => this.router.navigate(['/dossiers']) }
                ];
            case 'CREATE':
                return [
                    { label: 'Créer un dossier', icon: 'person_add', handler: () => this.router.navigate(['/dossiers'], { queryParams: { action: 'create' } }) },
                    { label: 'Créer une annonce', icon: 'add_circle', handler: () => this.router.navigate(['/annonces/new']) }
                ];
            case 'SEND_MESSAGE':
                return [
                    { label: 'Aller aux dossiers', icon: 'folder', handler: () => this.router.navigate(['/dossiers']) }
                ];
            default:
                return [
                    { label: 'Voir le tableau de bord', icon: 'dashboard', handler: () => this.router.navigate(['/dashboard']) },
                    { label: 'Recherche globale', icon: 'search', handler: () => this.router.navigate(['/search']) }
                ];
        }
    }

    // ─── Backend stub ────────────────────────────────────────────
    /**
     * Calls the backend AI agent endpoint.
     * Returns null if backend is unavailable — falls back to local intent.
     */
    private callBackend(query: string): Observable<AgentIntent | null> {
        return this.http.post<{ intent: AgentIntent }>(this.API_URL, { query }).pipe(
            map(res => res?.intent ?? null),
            catchError((err) => {
                console.error("AI Backend Error/Timeout:", err);
                return of(null);
            })
        );
    }

    // ─── Message helpers ─────────────────────────────────────────
    private generateId(): string {
        return `msg_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
    }

    addMessage(partial: Partial<AgentMessage>): void {
        const msg: AgentMessage = {
            id: this.generateId(),
            role: 'user',
            content: '',
            timestamp: new Date(),
            ...partial
        };
        const current = this._messages$.value;
        this._messages$.next([...current, msg]);
    }

    private addTypingIndicator(): void {
        const typing: AgentMessage = {
            id: `typing_${Date.now()}`,
            role: 'agent',
            content: '',
            timestamp: new Date(),
            isTyping: true
        };
        const current = this._messages$.value;
        this._messages$.next([...current, typing]);
    }

    addAgentMessage(content: string, intent?: AgentIntent): void {
        // Remove any typing indicator
        const withoutTyping = this._messages$.value.filter(m => !m.isTyping);

        const msg: AgentMessage = {
            id: this.generateId(),
            role: 'agent',
            content,
            timestamp: new Date(),
            intent,
            actions: intent?.suggestedActions
        };

        this._messages$.next([...withoutTyping, msg]);
    }

    removeTypingIndicators(): void {
        const msgs = this._messages$.value.filter(m => !m.isTyping);
        this._messages$.next(msgs);
    }
}

import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DsIconComponent } from '../../icons/ds-icon.component';

export interface IosTabItem {
  value: string;
  label: string;
  icon: string;
  badge?: number;
}

/**
 * Tab bar iOS — Glass effect, Safe Area bottom, Cupertino style.
 * Utilisé via Capacitor sur iOS uniquement.
 */
@Component({
  selector: 'ds-ios-tabbar',
  standalone: true,
  imports: [CommonModule, DsIconComponent],
  template: `
    <nav class="ds-ios-tabbar" role="tablist" [attr.aria-label]="label">
      <div class="ds-ios-tabbar__blur"></div>
      <div class="ds-ios-tabbar__items">
        @for (tab of tabs; track tab.value) {
          <button
            class="ds-ios-tabbar__item"
            [class.ds-ios-tabbar__item--active]="tab.value === activeTab"
            role="tab"
            [attr.aria-selected]="tab.value === activeTab"
            [attr.aria-label]="tab.label"
            (click)="select(tab)">
            <div class="ds-ios-tabbar__icon">
              <ds-icon [name]="tab.icon" [size]="24"></ds-icon>
              @if (tab.badge) {
                <span class="ds-ios-tabbar__badge" aria-live="polite">{{ tab.badge > 99 ? '99+' : tab.badge }}</span>
              }
            </div>
            <span class="ds-ios-tabbar__label">{{ tab.label }}</span>
          </button>
        }
      </div>
      <!-- Safe Area iOS -->
      <div class="ds-ios-tabbar__safe-area"></div>
    </nav>
  `,
  styles: [`
    .ds-ios-tabbar {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      z-index: 100;
    }
    .ds-ios-tabbar__blur {
      position: absolute;
      inset: 0;
      background: rgba(var(--ds-surface-rgb, 255,255,255), 0.72);
      backdrop-filter: blur(20px) saturate(180%);
      -webkit-backdrop-filter: blur(20px) saturate(180%);
      border-top: 0.5px solid var(--ds-divider);
    }
    .ds-ios-tabbar__items {
      position: relative;
      display: flex;
      justify-content: space-around;
      padding: 4px 0 0;
    }
    .ds-ios-tabbar__item {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 2px;
      padding: 6px 4px 2px;
      background: transparent;
      border: none;
      cursor: pointer;
      color: var(--ds-text-faint);
      transition: color 120ms ease;
      min-width: 44px;
      -webkit-tap-highlight-color: transparent;
    }
    .ds-ios-tabbar__item--active {
      color: var(--ds-marine);
    }
    .ds-ios-tabbar__icon { position: relative; }
    .ds-ios-tabbar__badge {
      position: absolute;
      top: -4px;
      right: -8px;
      min-width: 16px;
      height: 16px;
      padding: 0 4px;
      border-radius: 8px;
      background: var(--ds-error);
      color: #fff;
      font-size: 10px;
      font-weight: 700;
      display: flex;
      align-items: center;
      justify-content: center;
      border: 1.5px solid var(--ds-surface);
    }
    .ds-ios-tabbar__label {
      font-size: 10px;
      font-weight: 500;
      letter-spacing: 0.1px;
      line-height: 1.2;
    }
    .ds-ios-tabbar__safe-area {
      height: env(safe-area-inset-bottom, 0px);
    }
  `],
})
export class GlassTabbarComponent {
  @Input() tabs: IosTabItem[] = [];
  @Input() activeTab = '';
  @Input() label = 'Navigation principale';
  @Output() tabChange = new EventEmitter<string>();

  select(tab: IosTabItem): void {
    this.activeTab = tab.value;
    this.tabChange.emit(tab.value);
  }
}

import { Injectable } from '@angular/core';
import { OAuthService, AuthConfig } from 'angular-oauth2-oidc';
import { Router } from '@angular/router';
import { environment } from '../../environments/environment';

interface JwtPayload {
  sub?: string;
  roles?: string[];
  realm_access?: { roles?: string[] };
  resource_access?: Record<string, { roles?: string[] }>;
  exp?: number;
  [key: string]: unknown;
}

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  private readonly TOKEN_KEY = 'auth_token';
  private readonly AUTH_MODE_KEY = 'auth_mode'; // 'manual' | 'oidc'
  private readonly DEFAULT_ORG_ID = 'ORG-001';

  /**
   * Prevents navigation ping-pong when multiple concurrent API calls return 401.
   */
  private handlingSessionExpired = false;

  private readonly authConfig: AuthConfig = {
    issuer: environment.oidc.issuer,
    redirectUri: environment.oidc.redirectUri,
    clientId: environment.oidc.clientId,
    responseType: 'code',
    scope: environment.oidc.scope,
    requireHttps: environment.oidc.requireHttps,
    showDebugInformation: true,
    strictDiscoveryDocumentValidation: false,
    useSilentRefresh: false,
    sessionChecksEnabled: false,
    clearHashAfterLogin: true,
    skipIssuerCheck: false,
    oidc: true
  };

  constructor(
    private readonly oauthService: OAuthService,
    private readonly router: Router
  ) {
    // Configure OAuthService once at startup.
    this.oauthService.configure(this.authConfig);
    this.oauthService.setStorage(localStorage);
  }

  /**
   * App initializer: loads the discovery document and tries to finalize a code-flow login.
   * Never throws (to avoid blocking bootstrap).
   */
  async init(): Promise<void> {
    if (!environment.oidc.enabled) {
      return;
    }

    try {
      // Race the discovery call against a timeout so the app still boots
      // when Keycloak is unreachable (e.g. local dev without the IdP).
      const OIDC_TIMEOUT_MS = 5_000;
      const timeout = new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error(`OIDC discovery timed out after ${OIDC_TIMEOUT_MS}ms`)), OIDC_TIMEOUT_MS)
      );

      await Promise.race([
        this.oauthService.loadDiscoveryDocumentAndTryLogin(),
        timeout
      ]);

      if (this.oauthService.hasValidAccessToken()) {
        localStorage.setItem(this.AUTH_MODE_KEY, 'oidc');

        // If we just handled the OIDC callback, navigate away from /auth/callback.
        if (typeof window !== 'undefined' && window.location.pathname.includes('/auth/callback')) {
          const returnUrl = sessionStorage.getItem('returnUrl') || '/dashboard';
          sessionStorage.removeItem('returnUrl');
          this.router.navigate([returnUrl], { replaceUrl: true });
        }
      } else if (typeof window !== 'undefined' && window.location.pathname.includes('/auth/callback')) {
        // tryLogin ran on /auth/callback but no token — something went wrong.
        console.error('[AuthService] OIDC callback reached but no valid access token after tryLogin.');
        this.router.navigate(['/login'], { replaceUrl: true });
      }
    } catch (err) {
      console.warn('[AuthService] OIDC init failed (app will continue without SSO):', err);
    }
  }

  /** Manual / mock token login (kept for development). */
  login(token: string): void {
    localStorage.setItem(this.TOKEN_KEY, token);
    localStorage.setItem(this.AUTH_MODE_KEY, 'manual');

    // Ensure an org id exists to avoid 400 Bad Request from the API.
    if (!localStorage.getItem('org_id')) {
      localStorage.setItem('org_id', this.DEFAULT_ORG_ID);
    }
  }

  /**
   * Start Keycloak login using Authorization Code Flow (PKCE).
   * Note: org id is not part of the OIDC protocol; we keep a local default.
   */
  loginWithKeycloak(): void {
    if (!environment.oidc.enabled) {
      return;
    }

    // Ensure org id exists before the user lands on authenticated pages.
    if (!localStorage.getItem('org_id')) {
      localStorage.setItem('org_id', this.DEFAULT_ORG_ID);
    }

    // Clear any manual token to avoid mixing modes.
    localStorage.removeItem(this.TOKEN_KEY);
    localStorage.setItem(this.AUTH_MODE_KEY, 'oidc');

    this.oauthService.initCodeFlow();
  }

  /**
   * Logout of both modes.
   * - Removes manual token
   * - Clears OIDC tokens
   */
  logout(): void {
    this.logoutLocal();
    this.router.navigate(['/login'], { replaceUrl: true });
  }

  /**
   * Local logout only (no redirect to Keycloak).
   * This is the safest option to break infinite redirect loops on 401.
   */
  logoutLocal(): void {
    localStorage.removeItem(this.TOKEN_KEY);
    localStorage.removeItem(this.AUTH_MODE_KEY);

    try {
      // "true" = noRedirectToLogoutUrl (avoids Keycloak end_session redirect issues)
      this.oauthService.logOut(true);
    } catch {
      // ignore
    }
  }

  /**
   * Called by HTTP interceptor on 401.
   * Clears tokens and performs a single navigation to /login.
   */
  handleSessionExpired(): void {
    if (this.handlingSessionExpired) {
      return;
    }
    this.handlingSessionExpired = true;

    this.logoutLocal();

    // replaceUrl prevents the browser history from replaying protected routes.
    this.router.navigate(['/login'], { replaceUrl: true }).finally(() => {
      // Release lock after navigation tick.
      setTimeout(() => (this.handlingSessionExpired = false), 0);
    });
  }

  /**
   * Prefer Keycloak access token if present, otherwise fall back to manual/mock token.
   */
  getToken(): string | null {
    if (this.oauthService.hasValidAccessToken()) {
      const t = this.oauthService.getAccessToken();
      return t || null;
    }

    return localStorage.getItem(this.TOKEN_KEY);
  }

  isAuthenticated(): boolean {
    if (this.oauthService.hasValidAccessToken()) {
      return true;
    }

    const token = localStorage.getItem(this.TOKEN_KEY);
    if (!token) {
      return false;
    }

    try {
      const payload = this.decodeToken(token);
      if (payload.exp) {
        const currentTime = Math.floor(Date.now() / 1000);
        return payload.exp > currentTime;
      }
      return true;
    } catch {
      return false;
    }
  }

  getUserRoles(): string[] {
    const token = this.getToken();
    if (!token) {
      return [];
    }

    try {
      const payload = this.decodeToken(token);
      const direct = Array.isArray(payload.roles) ? payload.roles : [];
      const realm = Array.isArray(payload.realm_access?.roles) ? payload.realm_access?.roles : [];

      const clientId = environment.oidc.clientId;
      const clientRoles = payload.resource_access?.[clientId]?.roles || [];

      // Merge and unique
      return Array.from(new Set([...(direct || []), ...(realm || []), ...(clientRoles || [])]));
    } catch {
      return [];
    }
  }

  hasRole(role: string): boolean {
    return this.getUserRoles().includes(role);
  }

  getUserId(): string | null {
    const token = this.getToken();
    if (!token) {
      return null;
    }

    try {
      const payload = this.decodeToken(token);
      return payload.sub || null;
    } catch {
      return null;
    }
  }

  private decodeToken(token: string): JwtPayload {
    const parts = token.split('.');
    if (parts.length !== 3) {
      throw new Error('Invalid token format');
    }

    const payload = parts[1];
    // base64url -> base64
    const normalized = payload.replace(/-/g, '+').replace(/_/g, '/');
    const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4);
    const decoded = atob(padded);
    return JSON.parse(decoded);
  }
}

import { Component, OnInit, OnChanges, SimpleChanges, input, output } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { DossierResponse, DossierStatus, DossierApiService } from '../services/dossier-api.service';
import { ToastNotificationService } from '../services/toast-notification.service';
import {
  KanbanColumnComponent,
  type DsBadgeStatus,
  type DsKanbanCard,
  type DsKanbanColumn,
  type DsKanbanDropEvent,
} from '../design-system';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';

interface KanbanColumn {
  id: DossierStatus;
  title: string;
  dossiers: DossierResponse[];
  allowedTransitions: DossierStatus[];
}

@Component({
  selector: 'app-kanban-board',
  standalone: true,
  templateUrl: './kanban-board.component.html',
  styleUrls: ['./kanban-board.component.css'],
  imports: [KanbanColumnComponent, DsSkeletonComponent],
})
export class KanbanBoardComponent implements OnInit, OnChanges {
  readonly dossiers = input<DossierResponse[]>([]);
  readonly loading = input(false);
  readonly quickFilter = input('');
  readonly dossierClick = output<DossierResponse>();
  readonly dossierUpdated = output<void>();

  columns: KanbanColumn[] = [];
  filteredColumns: KanbanColumn[] = [];
  /** Colonnes branchées sur `ds-kanban-column` (cartes dérivées des dossiers filtrés). */
  dsKanbanColumns: DsKanbanColumn[] = [];

  private readonly workflowTransitions: Record<DossierStatus, DossierStatus[]> = {
    [DossierStatus.NEW]: [DossierStatus.QUALIFYING, DossierStatus.LOST],
    [DossierStatus.QUALIFYING]: [DossierStatus.NEW, DossierStatus.QUALIFIED, DossierStatus.LOST],
    [DossierStatus.QUALIFIED]: [DossierStatus.QUALIFYING, DossierStatus.APPOINTMENT, DossierStatus.LOST],
    [DossierStatus.APPOINTMENT]: [DossierStatus.QUALIFIED, DossierStatus.WON, DossierStatus.LOST],
    [DossierStatus.WON]: [],
    [DossierStatus.LOST]: [DossierStatus.NEW, DossierStatus.QUALIFYING],
  };

  constructor(
    private dossierApiService: DossierApiService,
    private toastService: ToastNotificationService,
  ) {}

  ngOnInit(): void {
    this.initializeColumns();
    this.distributeDosiersToColumns();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['dossiers'] && !changes['dossiers'].firstChange) {
      this.distributeDosiersToColumns();
    }
    if (changes['quickFilter']) {
      this.applyQuickFilter();
    }
  }

  private initializeColumns(): void {
    this.columns = [
      {
        id: DossierStatus.NEW,
        title: 'Nouveau',
        dossiers: [],
        allowedTransitions: this.workflowTransitions[DossierStatus.NEW],
      },
      {
        id: DossierStatus.QUALIFYING,
        title: 'Qualification',
        dossiers: [],
        allowedTransitions: this.workflowTransitions[DossierStatus.QUALIFYING],
      },
      {
        id: DossierStatus.QUALIFIED,
        title: 'Qualifié',
        dossiers: [],
        allowedTransitions: this.workflowTransitions[DossierStatus.QUALIFIED],
      },
      {
        id: DossierStatus.APPOINTMENT,
        title: 'Rendez-vous',
        dossiers: [],
        allowedTransitions: this.workflowTransitions[DossierStatus.APPOINTMENT],
      },
      {
        id: DossierStatus.WON,
        title: 'Gagné',
        dossiers: [],
        allowedTransitions: this.workflowTransitions[DossierStatus.WON],
      },
      {
        id: DossierStatus.LOST,
        title: 'Perdu',
        dossiers: [],
        allowedTransitions: this.workflowTransitions[DossierStatus.LOST],
      },
    ];
  }

  private distributeDosiersToColumns(): void {
    this.columns.forEach((column) => {
      column.dossiers = this.dossiers().filter((d) => d.status === column.id);
    });
    this.applyQuickFilter();
  }

  private applyQuickFilter(): void {
    const quickFilter = this.quickFilter();
    if (!quickFilter || quickFilter.trim() === '') {
      this.filteredColumns = this.columns;
    } else {
      const filter = quickFilter.toLowerCase().trim();
      this.filteredColumns = this.columns.map((column) => ({
        ...column,
        dossiers: column.dossiers.filter(
          (dossier) =>
            dossier.leadName?.toLowerCase().includes(filter) ||
            dossier.leadPhone?.toLowerCase().includes(filter) ||
            dossier.annonceTitle?.toLowerCase().includes(filter) ||
            dossier.id.toString().includes(filter),
        ),
      }));
    }
    this.syncDsKanbanColumns();
  }

  private syncDsKanbanColumns(): void {
    this.dsKanbanColumns = this.filteredColumns.map((fc) => ({
      id: fc.id,
      label: fc.title,
      color: this.columnDsColor(fc.id),
      cards: fc.dossiers.map((d) => this.dossierToKanbanCard(d)),
    }));
  }

  private columnDsColor(
    id: DossierStatus,
  ): NonNullable<DsKanbanColumn['color']> {
    switch (id) {
      case DossierStatus.NEW:
        return 'warning';
      case DossierStatus.QUALIFYING:
      case DossierStatus.APPOINTMENT:
        return 'marine';
      case DossierStatus.QUALIFIED:
        return 'success';
      case DossierStatus.WON:
        return 'success';
      case DossierStatus.LOST:
        return 'error';
      default:
        return 'neutral';
    }
  }

  private dossierBadgeStatus(status: DossierStatus): DsBadgeStatus {
    switch (status) {
      case DossierStatus.NEW:
        return 'new';
      case DossierStatus.QUALIFYING:
        return 'qualification';
      case DossierStatus.QUALIFIED:
        return 'info';
      case DossierStatus.APPOINTMENT:
        return 'rdv';
      case DossierStatus.WON:
        return 'won';
      case DossierStatus.LOST:
        return 'lost';
      default:
        return 'neutral';
    }
  }

  private dossierToKanbanCard(d: DossierResponse): DsKanbanCard {
    const subtitleParts = [d.leadPhone, d.annonceTitle].filter(Boolean) as string[];
    const tags: string[] = [];
    if (d.score !== null && d.score !== undefined) {
      tags.push(`Score ${d.score}`);
    }
    const src = d.leadSource || d.source;
    if (src) {
      tags.push(String(src));
    }
    const updated = d.updatedAt ? new Date(d.updatedAt) : null;
    return {
      id: d.id,
      title: d.leadName?.trim() || `Dossier #${d.id}`,
      subtitle: subtitleParts.length ? subtitleParts.join(' · ') : undefined,
      status: d.status,
      badge: `#${d.id}`,
      badgeStatus: this.dossierBadgeStatus(d.status),
      dueDate: updated
        ? updated.toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' })
        : undefined,
      tags: tags.length ? tags : undefined,
      meta: { dossierId: String(d.id) },
    };
  }

  get kanbanConnectedLists(): string[] {
    return this.dsKanbanColumns.map((c) => 'dsk-' + c.id);
  }

  async onKanbanCardDropped(ev: DsKanbanDropEvent): Promise<void> {
    if (ev.fromColumn === ev.toColumn) {
      return;
    }

    const from = ev.fromColumn as DossierStatus;
    const to = ev.toColumn as DossierStatus;
    const dossier = this.dossiers().find((d) => d.id === Number(ev.card.id));
    if (!dossier) {
      this.syncDsKanbanColumns();
      return;
    }

    if (!this.isTransitionAllowed(from, to)) {
      this.toastService.warning(
        `Transition non autorisée : de « ${this.columnTitle(from)} » vers « ${this.columnTitle(to)} »`,
      );
      this.syncDsKanbanColumns();
      return;
    }

    const previousStatus = dossier.status;
    dossier.status = to;
    this.distributeDosiersToColumns();

    try {
      await firstValueFrom(this.dossierApiService.patchStatus(dossier.id, to));
      this.toastService.success(`Dossier #${dossier.id} déplacé vers « ${this.columnTitle(to)} »`);
      this.dossierUpdated.emit();
    } catch (error) {
      console.error('Failed to update dossier status:', error);
      dossier.status = previousStatus;
      this.distributeDosiersToColumns();
      this.toastService.error('Échec de la mise à jour du statut. Veuillez réessayer.');
    }
  }

  private columnTitle(status: DossierStatus): string {
    return this.columns.find((c) => c.id === status)?.title ?? status;
  }

  private isTransitionAllowed(from: DossierStatus, to: DossierStatus): boolean {
    return this.workflowTransitions[from]?.includes(to) || false;
  }

  onKanbanCardClick(card: DsKanbanCard): void {
    const dossier = this.dossiers().find((d) => d.id === Number(card.id));
    if (dossier) {
      this.dossierClick.emit(dossier);
    }
  }

  trackByColumnId(index: number, column: DsKanbanColumn): DossierStatus {
    return column.id as DossierStatus;
  }
}

import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { BehaviorSubject, Observable } from 'rxjs';

export interface KeyboardShortcut {
  key: string;
  description: string;
  action: () => void;
  category: 'navigation' | 'actions' | 'lists';
  sequence?: boolean;
}

export interface UserPreferences {
  keyboardShortcutsEnabled: boolean;
  showShortcutHints: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class KeyboardShortcutService {
  private readonly PREFERENCES_KEY = 'keyboard-shortcuts-preferences';
  private preferencesSubject: BehaviorSubject<UserPreferences>;
  public preferences$: Observable<UserPreferences>;
  
  private shortcuts: Map<string, KeyboardShortcut> = new Map();
  private sequenceBuffer: string[] = [];
  private sequenceTimeout: any;
  
  private commandPaletteVisibleSubject = new BehaviorSubject<boolean>(false);
  public commandPaletteVisible$ = this.commandPaletteVisibleSubject.asObservable();
  
  private shortcutHelpVisibleSubject = new BehaviorSubject<boolean>(false);
  public shortcutHelpVisible$ = this.shortcutHelpVisibleSubject.asObservable();
  
  private activeListItemSubject = new BehaviorSubject<number>(-1);
  public activeListItem$ = this.activeListItemSubject.asObservable();

  constructor(private router: Router) {
    const savedPrefs = this.loadPreferences();
    this.preferencesSubject = new BehaviorSubject<UserPreferences>(savedPrefs);
    this.preferences$ = this.preferencesSubject.asObservable();
    this.registerDefaultShortcuts();
  }

  private loadPreferences(): UserPreferences {
    const saved = localStorage.getItem(this.PREFERENCES_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch {
        return this.getDefaultPreferences();
      }
    }
    return this.getDefaultPreferences();
  }

  private getDefaultPreferences(): UserPreferences {
    return {
      keyboardShortcutsEnabled: true,
      showShortcutHints: true
    };
  }

  savePreferences(preferences: UserPreferences): void {
    localStorage.setItem(this.PREFERENCES_KEY, JSON.stringify(preferences));
    this.preferencesSubject.next(preferences);
  }

  getPreferences(): UserPreferences {
    return this.preferencesSubject.value;
  }

  private registerDefaultShortcuts(): void {
    this.registerShortcut({
      key: '/',
      description: 'Focus recherche',
      category: 'navigation',
      action: () => this.focusSearch()
    });

    this.registerShortcut({
      key: 'Ctrl+K',
      description: 'Ouvrir la palette de commandes',
      category: 'actions',
      action: () => this.toggleCommandPalette()
    });

    this.registerShortcut({
      key: 'g+a',
      description: 'Aller aux annonces',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToAnnonces()
    });

    this.registerShortcut({
      key: 'g+d',
      description: 'Aller aux dossiers',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToDossiers()
    });

    this.registerShortcut({
      key: 'g+h',
      description: 'Aller au tableau de bord',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToDashboard()
    });

    this.registerShortcut({
      key: 'g+t',
      description: 'Aller aux tâches',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToTasks()
    });

    this.registerShortcut({
      key: 'g+c',
      description: 'Aller au calendrier',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToCalendar()
    });

    this.registerShortcut({
      key: 'Escape',
      description: 'Fermer les modales',
      category: 'actions',
      action: () => this.closeModals()
    });

    this.registerShortcut({
      key: '?',
      description: 'Afficher les raccourcis clavier',
      category: 'actions',
      action: () => this.toggleShortcutHelp()
    });

    this.registerShortcut({
      key: 'j',
      description: 'Élément suivant dans la liste',
      category: 'lists',
      action: () => this.navigateListDown()
    });

    this.registerShortcut({
      key: 'k',
      description: 'Élément précédent dans la liste',
      category: 'lists',
      action: () => this.navigateListUp()
    });

    this.registerShortcut({
      key: 'Enter',
      description: 'Ouvrir l\'élément sélectionné',
      category: 'lists',
      action: () => this.openSelectedListItem()
    });
  }

  registerShortcut(shortcut: KeyboardShortcut): void {
    this.shortcuts.set(shortcut.key, shortcut);
  }

  handleKeyDown(event: KeyboardEvent): boolean {
    const preferences = this.getPreferences();
    if (!preferences.keyboardShortcutsEnabled) {
      return false;
    }

    const target = event.target as HTMLElement;
    const isInputField = target.tagName === 'INPUT' || 
                        target.tagName === 'TEXTAREA' || 
                        target.isContentEditable;

    if (event.key === 'Escape') {
      this.closeModals();
      return true;
    }

    if (event.key === '?' && !isInputField) {
      event.preventDefault();
      this.toggleShortcutHelp();
      return true;
    }

    if (isInputField && event.key !== 'Escape') {
      return false;
    }

    const key = this.getKeyString(event);
    
    if (this.shortcuts.has(key) && !this.shortcuts.get(key)?.sequence) {
      event.preventDefault();
      this.shortcuts.get(key)?.action();
      return true;
    }

    if (!event.ctrlKey && !event.altKey && !event.metaKey && event.key.length === 1) {
      this.sequenceBuffer.push(event.key.toLowerCase());
      
      if (this.sequenceTimeout) {
        clearTimeout(this.sequenceTimeout);
      }
      
      this.sequenceTimeout = setTimeout(() => {
        this.sequenceBuffer = [];
      }, 1000);

      const sequence = this.sequenceBuffer.join('+');
      if (this.shortcuts.has(sequence)) {
        event.preventDefault();
        this.shortcuts.get(sequence)?.action();
        this.sequenceBuffer = [];
        return true;
      }
    }

    return false;
  }

  private getKeyString(event: KeyboardEvent): string {
    const parts: string[] = [];
    
    if (event.ctrlKey) parts.push('Ctrl');
    if (event.altKey) parts.push('Alt');
    if (event.metaKey) parts.push('Meta');
    if (event.shiftKey && event.key.length > 1) parts.push('Shift');
    
    parts.push(event.key);
    
    return parts.join('+');
  }

  getAllShortcuts(): KeyboardShortcut[] {
    return Array.from(this.shortcuts.values());
  }

  getShortcutsByCategory(category: string): KeyboardShortcut[] {
    return Array.from(this.shortcuts.values()).filter(s => s.category === category);
  }

  private focusSearch(): void {
    const searchInput = document.getElementById('global-search-input');
    if (searchInput) {
      searchInput.focus();
    }
  }

  toggleCommandPalette(): void {
    const currentState = this.commandPaletteVisibleSubject.value;
    this.commandPaletteVisibleSubject.next(!currentState);
  }

  closeCommandPalette(): void {
    this.commandPaletteVisibleSubject.next(false);
  }

  toggleShortcutHelp(): void {
    const currentState = this.shortcutHelpVisibleSubject.value;
    this.shortcutHelpVisibleSubject.next(!currentState);
  }

  closeShortcutHelp(): void {
    this.shortcutHelpVisibleSubject.next(false);
  }

  private navigateToAnnonces(): void {
    this.router.navigate(['/annonces']);
  }

  private navigateToDossiers(): void {
    this.router.navigate(['/dossiers']);
  }

  private navigateToDashboard(): void {
    this.router.navigate(['/dashboard']);
  }

  private navigateToTasks(): void {
    this.router.navigate(['/tasks']);
  }

  private navigateToCalendar(): void {
    this.router.navigate(['/calendar']);
  }

  private closeModals(): void {
    if (this.commandPaletteVisibleSubject.value) {
      this.closeCommandPalette();
      return;
    }
    
    if (this.shortcutHelpVisibleSubject.value) {
      this.closeShortcutHelp();
      return;
    }
    
    const escEvent = new KeyboardEvent('keydown', {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
      bubbles: true
    });
    document.dispatchEvent(escEvent);
  }

  private navigateListDown(): void {
    const current = this.activeListItemSubject.value;
    this.activeListItemSubject.next(current + 1);
  }

  private navigateListUp(): void {
    const current = this.activeListItemSubject.value;
    if (current > 0) {
      this.activeListItemSubject.next(current - 1);
    }
  }

  private openSelectedListItem(): void {
    const activeIndex = this.activeListItemSubject.value;
    if (activeIndex >= 0) {
      const event = new CustomEvent('list-item-selected', {
        detail: { index: activeIndex },
        bubbles: true
      });
      document.dispatchEvent(event);
    }
  }

  resetListNavigation(): void {
    this.activeListItemSubject.next(-1);
  }

  setActiveListItem(index: number): void {
    this.activeListItemSubject.next(index);
  }
}

import { Component, OnInit, OnDestroy, AfterViewInit } from '@angular/core';
import { Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { BreakpointObserver, Breakpoints } from '@angular/cdk/layout';
