    yPosition += 15;

    if (data.conversionRateBySource && data.conversionRateBySource.length > 0) {
      doc.setFontSize(12);
      doc.text('Conversion Rate by Source', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Source', 'Total Dossiers', 'Won Dossiers', 'Conversion Rate']],
        body: data.conversionRateBySource.map(item => [
          item.source,
          item.totalDossiers.toString(),
          item.wonDossiers.toString(),
          `${(item.conversionRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });
    }

    doc.save(filename);
  }

  /**
   * Export KPI report data to CSV using lazy-loaded PapaParse library.
   *
   * @param data - KPI report data to export
   * @param filename - Name of the CSV file (default: 'kpi-report.csv')
   * @returns Promise that resolves when the CSV is downloaded
   */
  async exportKpiReportToCSV(data: KpiReportResponse, filename = 'kpi-report.csv'): Promise<void> {
    const Papa = await import('papaparse');

    const csvSections: string[] = [];

    csvSections.push('KPI Report\n');
    csvSections.push(`Average Response Time (hours),${data.averageResponseTimeHours.toFixed(2)}`);
    csvSections.push(`Appointment Show Rate,${(data.appointmentShowRate * 100).toFixed(2)}%`);
    csvSections.push(`Pipeline Velocity (days),${data.pipelineVelocityDays.toFixed(2)}`);

    if (data.conversionRateBySource && data.conversionRateBySource.length > 0) {
      csvSections.push('\n\nConversion Rate by Source');
      const conversionData = data.conversionRateBySource.map(item => ({
        'Source': item.source,
        'Total Dossiers': item.totalDossiers,
        'Won Dossiers': item.wonDossiers,
        'Conversion Rate': `${(item.conversionRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(conversionData));
    }

    if (data.dossierCreationTimeSeries && data.dossierCreationTimeSeries.length > 0) {
      csvSections.push('\n\nDossier Creation Time Series');
      csvSections.push(Papa.unparse(data.dossierCreationTimeSeries));
    }

    if (data.conversionTimeSeries && data.conversionTimeSeries.length > 0) {
      csvSections.push('\n\nConversion Time Series');
      csvSections.push(Papa.unparse(data.conversionTimeSeries));
    }

    const csvContent = csvSections.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }
}

import { Injectable } from '@angular/core';

export interface LinearRegressionResult {
  slope: number;
  intercept: number;
  rSquared: number;
  predictions: number[];
}

export interface PipelineForecast {
  date: string;
  predictedValue: number;
  confidence: number;
  upperBound: number;
  lowerBound: number;
}

export interface CloseProbability {
  dossierId: number;
  probability: number;
  factors: {
    responseTime: number;
    stageProgression: number;
    engagement: number;
    source: number;
  };
  recommendation: string;
}

@Injectable({
  providedIn: 'root'
})
export class PredictiveAnalyticsService {

  constructor() { /* no-op */ }

  performLinearRegression(xValues: number[], yValues: number[]): LinearRegressionResult {
    if (xValues.length !== yValues.length || xValues.length === 0) {
      throw new Error('Invalid input data for regression');
    }

    const n = xValues.length;
    const sumX = xValues.reduce((a, b) => a + b, 0);
    const sumY = yValues.reduce((a, b) => a + b, 0);
    const sumXY = xValues.reduce((sum, x, i) => sum + x * yValues[i], 0);
    const sumXX = xValues.reduce((sum, x) => sum + x * x, 0);

    const slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    const predictions = xValues.map(x => slope * x + intercept);
    const meanY = sumY / n;
    const ssTotal = yValues.reduce((sum, y) => sum + Math.pow(y - meanY, 2), 0);
    const ssResidual = yValues.reduce((sum, y, i) => sum + Math.pow(y - predictions[i], 2), 0);
    const rSquared = 1 - (ssResidual / ssTotal);

    return { slope, intercept, rSquared, predictions };
  }

  forecastPipelineValue(historicalData: { date: string; value: number }[], daysAhead: number): PipelineForecast[] {
    if (historicalData.length < 2) {
      return [];
    }

    const xValues = historicalData.map((_, i) => i);
    const yValues = historicalData.map(d => d.value);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const stdDev = this.calculateStdDev(yValues, regression.predictions.slice(0, yValues.length));
    
    const forecasts: PipelineForecast[] = [];
    const lastDate = new Date(historicalData[historicalData.length - 1].date);

    for (let i = 1; i <= daysAhead; i++) {
      const xValue = historicalData.length + i - 1;
      const predictedValue = regression.slope * xValue + regression.intercept;
      
      const confidence = Math.max(0, Math.min(100, regression.rSquared * 100));
      
      const forecastDate = new Date(lastDate);
      forecastDate.setDate(lastDate.getDate() + i);

      const uncertaintyFactor = Math.sqrt(i);
      forecasts.push({
        date: forecastDate.toISOString().split('T')[0],
        predictedValue: Math.max(0, predictedValue),
        confidence,
        upperBound: Math.max(0, predictedValue + stdDev * uncertaintyFactor),
        lowerBound: Math.max(0, predictedValue - stdDev * uncertaintyFactor)
      });
    }

    return forecasts;
  }

  calculateCloseProbability(dossier: {
    id: number;
    averageResponseTimeHours: number;
    daysInCurrentStage: number;
    messageCount: number;
    appointmentCount: number;
    source: string;
    status: string;
  }): CloseProbability {
    let probability = 50;

    const responseTimeFactor = this.scoreResponseTime(dossier.averageResponseTimeHours);
    const stageProgressionFactor = this.scoreStageProgression(dossier.status, dossier.daysInCurrentStage);
    const engagementFactor = this.scoreEngagement(dossier.messageCount, dossier.appointmentCount);
    const sourceFactor = this.scoreSource(dossier.source);

    probability += responseTimeFactor * 0.25;
    probability += stageProgressionFactor * 0.30;
    probability += engagementFactor * 0.30;
    probability += sourceFactor * 0.15;

    probability = Math.max(0, Math.min(100, probability));

    const recommendation = this.generateRecommendation(probability, {
      responseTimeFactor,
      stageProgressionFactor,
      engagementFactor,
      sourceFactor
    });

    return {
      dossierId: dossier.id,
      probability,
      factors: {
        responseTime: responseTimeFactor,
        stageProgression: stageProgressionFactor,
        engagement: engagementFactor,
        source: sourceFactor
      },
      recommendation
    };
  }

  private calculateStdDev(actual: number[], predicted: number[]): number {
    const residuals = actual.map((y, i) => y - predicted[i]);
    const sumSquaredResiduals = residuals.reduce((sum, r) => sum + r * r, 0);
    return Math.sqrt(sumSquaredResiduals / actual.length);
  }

  private scoreResponseTime(avgResponseTimeHours: number): number {
    if (avgResponseTimeHours <= 1) return 20;
    if (avgResponseTimeHours <= 4) return 10;
    if (avgResponseTimeHours <= 24) return 0;
    if (avgResponseTimeHours <= 48) return -10;
    return -20;
  }

  private scoreStageProgression(status: string, daysInStage: number): number {
    const stageWeights: Record<string, number> = {
      'NEW': 0,
      'QUALIFYING': 10,
      'QUALIFIED': 20,
      'APPOINTMENT': 30,
      'PROPOSAL': 35,
      'NEGOTIATION': 40,
      'WON': 50,
      'LOST': -50
    };

    let score = stageWeights[status] || 0;

    if (daysInStage > 30) {
      score -= 15;
    } else if (daysInStage > 14) {
      score -= 10;
    } else if (daysInStage > 7) {
      score -= 5;
    }

    return score;
  }

  private scoreEngagement(messageCount: number, appointmentCount: number): number {
    let score = 0;

    if (messageCount > 10) {
      score += 20;
    } else if (messageCount > 5) {
      score += 15;
    } else if (messageCount > 2) {
      score += 10;
    } else if (messageCount > 0) {
      score += 5;
    }

    if (appointmentCount > 2) {
      score += 15;
    } else if (appointmentCount > 1) {
      score += 10;
    } else if (appointmentCount > 0) {
      score += 5;
    }

    return score;
  }

  private scoreSource(source: string): number {
    const sourceWeights: Record<string, number> = {
      'REFERRAL': 15,
      'WEBSITE': 10,
      'SOCIAL_MEDIA': 5,
      'PHONE': 5,
      'EMAIL': 3,
      'WALK_IN': 0,
      'OTHER': 0
    };

    return sourceWeights[source] || 0;
  }

  private generateRecommendation(probability: number, factors: any): string {
    if (probability >= 80) {
      return 'High probability - Schedule final negotiation';
    } else if (probability >= 60) {
      return 'Good probability - Continue nurturing with regular follow-ups';
    } else if (probability >= 40) {
      if (factors.responseTimeFactor < 0) {
        return 'Medium probability - Improve response time to increase chances';
      } else if (factors.engagementFactor < 5) {
        return 'Medium probability - Increase engagement through appointments';
      } else {
        return 'Medium probability - Address any concerns and provide additional value';
      }
    } else if (probability >= 20) {
      return 'Low probability - Re-qualify lead and adjust strategy';
    } else {
      return 'Very low probability - Consider reassigning or archiving';
    }
  }

  calculateTeamPerformanceTrend(
    performanceData: { date: string; metric: number }[],
    _metricName: string
  ): { trend: 'improving' | 'declining' | 'stable'; changeRate: number } {
    if (performanceData.length < 2) {
      return { trend: 'stable', changeRate: 0 };
    }

    const xValues = performanceData.map((_, i) => i);
    const yValues = performanceData.map(d => d.metric);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const avgMetric = yValues.reduce((a, b) => a + b, 0) / yValues.length;
    const changeRate = avgMetric !== 0 ? (regression.slope / avgMetric) * 100 : 0;

    let trend: 'improving' | 'declining' | 'stable';
    if (changeRate > 5) {
      trend = 'improving';
    } else if (changeRate < -5) {
      trend = 'declining';
    } else {
      trend = 'stable';
    }

    return { trend, changeRate };
  }

  predictMarketTrend(
    historicalPrices: { date: string; avgPrice: number }[],
    forecastMonths: number
  ): { date: string; predictedPrice: number; confidence: number }[] {
    if (historicalPrices.length < 3) {
      return [];
    }

    const xValues = historicalPrices.map((_, i) => i);
    const yValues = historicalPrices.map(d => d.avgPrice);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const predictions: { date: string; predictedPrice: number; confidence: number }[] = [];
    const lastDate = new Date(historicalPrices[historicalPrices.length - 1].date);

    for (let i = 1; i <= forecastMonths; i++) {
      const xValue = historicalPrices.length + i - 1;
      const predictedPrice = regression.slope * xValue + regression.intercept;
      
      const forecastDate = new Date(lastDate);
      forecastDate.setMonth(lastDate.getMonth() + i);

      const confidence = Math.max(0, Math.min(100, regression.rSquared * 100 * (1 - i * 0.05)));

      predictions.push({
        date: forecastDate.toISOString().split('T')[0],
        predictedPrice: Math.max(0, predictedPrice),
        confidence
      });
    }

    return predictions;
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { BehaviorSubject, Observable, map } from 'rxjs';

export interface Listing {
  id: string;
  slug: string;
  title: string;
  tx: 'vente' | 'location';
  price: number;
  city: string;
  zone: string;
  surface: number;
  pieces: number;
  desc: string;
  agent: { name: string; agency: string; initials: string };
  verified: boolean;
  date: string;
  imgs: string[];
}

export interface City {
  name: string;
  count: number;
  icon: string;
}

export interface FilterState {
  tx: string;
  ville: string;
  prixMin: number | null;
  prixMax: number | null;
  surfMin: number | null;
  surfMax: number | null;
  pieces: number;
  sort: 'recent' | 'prix-asc' | 'prix-desc' | 'surface-desc';
  page: number;
}

@Injectable({ providedIn: 'root' })
export class PortailService {
  readonly PAGE_SIZE = 9;

  readonly CITIES: City[] = [
    { name: 'Casablanca', count: 342, icon: '🏙️' },
    { name: 'Rabat',      count: 187, icon: '🏛️' },
    { name: 'Tanger',     count: 156, icon: '🌊' },
    { name: 'Marrakech',  count: 203, icon: '🌴' },
    { name: 'Fès',        count: 98,  icon: '🕌' },
    { name: 'Agadir',     count: 112, icon: '☀️' },
    { name: 'Meknès',     count: 67,  icon: '🏰' },
    { name: 'Tétouan',    count: 54,  icon: '🏔️' },
  ];

  private filterState$ = new BehaviorSubject<FilterState>({
    tx: '', ville: '', prixMin: null, prixMax: null,
    surfMin: null, surfMax: null, pieces: 0, sort: 'recent', page: 1
  });

  constructor(private http: HttpClient) {}

  getFilters() { return this.filterState$.asObservable(); }
  getFiltersSnapshot() { return this.filterState$.value; }

  updateFilters(partial: Partial<FilterState>): void {
    this.filterState$.next({ ...this.filterState$.value, ...partial, page: 1 });
  }

  setPage(page: number): void {
    this.filterState$.next({ ...this.filterState$.value, page });
  }

  // Maps Backend AnnonceResponse to Frontend Listing interface
  private mapToListing(annonce: any): Listing {
    return {
      id: annonce.id.toString(),
      slug: annonce.meta?.slug || `annonce-${annonce.id}`,
      title: annonce.title,
      tx: annonce.type === 'SALE' ? 'vente' : 'location',
      price: annonce.price || 0,
      city: annonce.city || '',
      zone: annonce.address || '',
      surface: annonce.surface || 0,
      pieces: annonce.meta?.pieces || 0,
      desc: annonce.description || '',
      agent: annonce.meta?.agent || { name: 'Agent', agency: 'Agence', initials: 'AG' },
      verified: annonce.meta?.verified || false,
      date: annonce.createdAt || new Date().toISOString(),
      imgs: annonce.photos && annonce.photos.length > 0 
        ? annonce.photos 
        : ['https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=800&q=80']
    };
  }

  searchAnnonces(state: FilterState): Observable<{ content: Listing[], totalElements: number }> {
    let params = new HttpParams()
      .set('page', (state.page - 1).toString())
      .set('size', this.PAGE_SIZE.toString());

    if (state.tx) {
      params = params.set('type', state.tx === 'vente' ? 'SALE' : 'RENT');
    }
    if (state.ville) {
      params = params.set('city', state.ville);
    }
    
    // Sort mapping
    let sortStr = 'id,desc';
    if (state.sort === 'prix-asc') sortStr = 'price,asc';
    if (state.sort === 'prix-desc') sortStr = 'price,desc';
    if (state.sort === 'surface-desc') sortStr = 'surface,desc';
    params = params.set('sort', sortStr);

    return this.http.get<any>('/api/v1/portal/annonces', { params }).pipe(
      map((res: any) => {
        const content = res.content ? res.content.map((item: any) => this.mapToListing(item)) : [];
        // Optional client-side filtering if API misses some filters (like pieces or surface)
        // Since the current controller search endpoint in MVP is limited, we might filter further here
        let filtered = content;
        if (state.prixMin) filtered = filtered.filter((l: Listing) => l.price >= state.prixMin!);
        if (state.prixMax) filtered = filtered.filter((l: Listing) => l.price <= state.prixMax!);
        if (state.surfMin) filtered = filtered.filter((l: Listing) => l.surface >= state.surfMin!);
        if (state.surfMax) filtered = filtered.filter((l: Listing) => l.surface <= state.surfMax!);
        if (state.pieces)  filtered = filtered.filter((l: Listing) => state.pieces >= 4 ? l.pieces >= 4 : l.pieces === state.pieces);

        return { content: filtered, totalElements: res.totalElements || filtered.length };
      })
    );
  }

  getListingById(id: string): Observable<Listing> {
    // Technically should call /api/v1/annonces/{id} but since Portal is public, 
    // it's easier to just search and find it. Or add a getById endpoint to PortalPublicController.
    // For now, doing a basic authenticated fetch bypass or we just add it later.
    return this.http.get<any>(`/api/v1/annonces/${id}`).pipe(
      map(res => this.mapToListing(res))
    );
  }

  formatPrice(price: number, tx: 'vente' | 'location'): string {
    if (tx === 'location') return price.toLocaleString('fr-MA') + ' MAD/mois';
    if (price >= 1000000)  return (price / 1000000).toFixed(price % 1000000 === 0 ? 0 : 2) + ' M MAD';
    return price.toLocaleString('fr-MA') + ' MAD';
  }
}

import { Injectable } from '@angular/core';
import { QueuedAction, QueuedActionStatus } from './offline-queue.service';

export interface CachedData {
  key: string;
  data: any;
  timestamp: number;
  expiresAt?: number;
}

export interface LocalIdMapping {
  localId: string;
  serverId: number;
  entityType: string;
  timestamp: number;
}

@Injectable({
  providedIn: 'root'
})
export class OfflineStorageService {
  private readonly DB_NAME = 'offline-db';
  private readonly DB_VERSION = 1;
  private readonly QUEUE_STORE = 'queue';
  private readonly CACHE_STORE = 'cache';
  private readonly MAPPING_STORE = 'id-mapping';

  private db: IDBDatabase | null = null;

  constructor() {
    this.initializeDatabase();
  }

  private async initializeDatabase(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.DB_NAME, this.DB_VERSION);

      request.onerror = () => {
        console.error('Failed to open IndexedDB:', request.error);
        reject(request.error);
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event: IDBVersionChangeEvent) => {
        const db = (event.target as IDBOpenDBRequest).result;

        if (!db.objectStoreNames.contains(this.QUEUE_STORE)) {
          const queueStore = db.createObjectStore(this.QUEUE_STORE, { keyPath: 'id' });
          queueStore.createIndex('status', 'status', { unique: false });
          queueStore.createIndex('timestamp', 'timestamp', { unique: false });
        }

        if (!db.objectStoreNames.contains(this.CACHE_STORE)) {
          const cacheStore = db.createObjectStore(this.CACHE_STORE, { keyPath: 'key' });
          cacheStore.createIndex('timestamp', 'timestamp', { unique: false });
          cacheStore.createIndex('expiresAt', 'expiresAt', { unique: false });
        }

        if (!db.objectStoreNames.contains(this.MAPPING_STORE)) {
          const mappingStore = db.createObjectStore(this.MAPPING_STORE, { keyPath: 'localId' });
          mappingStore.createIndex('serverId', 'serverId', { unique: false });
          mappingStore.createIndex('entityType', 'entityType', { unique: false });
        }
      };
    });
  }

  private async ensureDatabase(): Promise<IDBDatabase> {
    if (this.db) {
      return this.db;
    }

    await this.initializeDatabase();
    if (!this.db) {
      throw new Error('Failed to initialize database');
    }
    return this.db;
  }

  async addQueuedAction(action: QueuedAction): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readwrite');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.add(action);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async updateQueuedAction(action: QueuedAction): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readwrite');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.put(action);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getQueuedAction(id: string): Promise<QueuedAction | null> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readonly');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.get(id);

      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error);
    });
  }

  async getPendingActions(): Promise<QueuedAction[]> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readonly');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const index = store.index('status');
      const request = index.getAll(QueuedActionStatus.PENDING);

      request.onsuccess = () => {
        const actions = request.result || [];
        actions.sort((a, b) => a.timestamp - b.timestamp);
        resolve(actions);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async getFailedActions(): Promise<QueuedAction[]> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readonly');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const index = store.index('status');
      const request = index.getAll(QueuedActionStatus.FAILED);

      request.onsuccess = () => resolve(request.result || []);
      request.onerror = () => reject(request.error);
    });
  }

  async deleteQueuedAction(id: string): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readwrite');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async clearQueue(): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readwrite');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.clear();

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async cacheData(key: string, data: any, ttlMinutes?: number): Promise<void> {
    const db = await this.ensureDatabase();
    const cachedData: CachedData = {
      key,
      data,
      timestamp: Date.now(),
      expiresAt: ttlMinutes ? Date.now() + (ttlMinutes * 60 * 1000) : undefined
    };

    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.CACHE_STORE], 'readwrite');
      const store = transaction.objectStore(this.CACHE_STORE);
      const request = store.put(cachedData);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getCachedData(key: string): Promise<any | null> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.CACHE_STORE], 'readonly');
      const store = transaction.objectStore(this.CACHE_STORE);
      const request = store.get(key);

      request.onsuccess = () => {
        const result: CachedData | undefined = request.result;
        if (!result) {
          resolve(null);
          return;
        }

        if (result.expiresAt && result.expiresAt < Date.now()) {
          this.deleteCachedData(key);
          resolve(null);
          return;
        }

        resolve(result.data);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async deleteCachedData(key: string): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.CACHE_STORE], 'readwrite');
      const store = transaction.objectStore(this.CACHE_STORE);
      const request = store.delete(key);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async clearExpiredCache(): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.CACHE_STORE], 'readwrite');
      const store = transaction.objectStore(this.CACHE_STORE);
      const index = store.index('expiresAt');
      const now = Date.now();
      const range = IDBKeyRange.upperBound(now);
      const request = index.openCursor(range);

      request.onsuccess = (event) => {
        const cursor = (event.target as IDBRequest).result;
        if (cursor) {
          cursor.delete();
          cursor.continue();
        } else {
          resolve();
        }
      };

      request.onerror = () => reject(request.error);
    });
  }

  async mapLocalToServerId(localId: string, serverId: number, entityType = 'default'): Promise<void> {
    const db = await this.ensureDatabase();
    const mapping: LocalIdMapping = {
      localId,
      serverId,
      entityType,
      timestamp: Date.now()
    };

    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.MAPPING_STORE], 'readwrite');
      const store = transaction.objectStore(this.MAPPING_STORE);
      const request = store.put(mapping);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getServerId(localId: string): Promise<number | null> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.MAPPING_STORE], 'readonly');
      const store = transaction.objectStore(this.MAPPING_STORE);
      const request = store.get(localId);

      request.onsuccess = () => {
        const result: LocalIdMapping | undefined = request.result;
        resolve(result?.serverId || null);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async getLocalId(serverId: number): Promise<string | null> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.MAPPING_STORE], 'readonly');
      const store = transaction.objectStore(this.MAPPING_STORE);
      const index = store.index('serverId');
      const request = index.get(serverId);

      request.onsuccess = () => {
        const result: LocalIdMapping | undefined = request.result;
        resolve(result?.localId || null);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async getCachedDossiers(): Promise<any[]> {
    const data = await this.getCachedData('recent-dossiers');
    return data ? JSON.parse(data) : [];
  }

  async cacheDossier(dossier: any): Promise<void> {
    const cached = await this.getCachedDossiers();
    const filtered = cached.filter((d: any) => d.id !== dossier.id);
    filtered.unshift(dossier);
    const limited = filtered.slice(0, 50);
    await this.cacheData('recent-dossiers', JSON.stringify(limited), 60 * 60 * 1000);
  }

  async clearDossierCache(): Promise<void> {
    await this.deleteCachedData('recent-dossiers');
  }

  async clearMessageCache(): Promise<void> {
    await this.deleteCachedData('recent-messages');
  }
}

import {
  Component,
  ElementRef,
  OnInit,
  OnDestroy,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  input,
  output,
  viewChild
} from '@angular/core';
import { MatIcon } from '@angular/material/icon';

export type LottieAnimationType = 'search-empty' | 'success' | 'error' | 'upload' | 'maintenance';

export interface LottieOptions {
  loop?: boolean;
  autoplay?: boolean;
  speed?: number;
}

@Component({
    selector: 'app-lottie-animation',
    templateUrl: './lottie-animation.component.html',
    styleUrls: ['./lottie-animation.component.css'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [MatIcon]
})
export class LottieAnimationComponent implements OnInit, OnDestroy {
  readonly animationType = input.required<LottieAnimationType>();
  readonly width = input(200);
  readonly height = input(200);
  readonly loop = input(true);
  readonly autoplay = input(true);
  readonly speed = input(1);
  readonly showControls = input(false);
  
  readonly animationCreated = output<any>();
  readonly animationComplete = output<void>();
  readonly loopComplete = output<void>();
  readonly animationError = output<Error>();
  
  readonly lottieContainer = viewChild.required<ElementRef>('lottieContainer');
  
  isPlaying = true;
  isPaused = false;
  useFallback = false;
  lottieInstance: any = null;
  private destroyed = false;

  constructor(private cdr: ChangeDetectorRef) {}

  ngOnInit(): void {
    this.loadAnimation();
  }

  ngOnDestroy(): void {
    this.destroyed = true;
    this.destroyAnimation();
  }

  private async loadAnimation(): Promise<void> {
    try {
      // Dynamically import lottie-web only when needed
      const lottie = await import('lottie-web/build/player/lottie_light');
      
      if (this.destroyed) return;
      
      const animationData = await this.loadAnimationData();
      
      if (this.destroyed) return;
      
      this.lottieInstance = lottie.default.loadAnimation({
        container: this.lottieContainer().nativeElement,
        renderer: 'svg',
        loop: this.loop(),
        autoplay: this.autoplay(),
        animationData: animationData,
        rendererSettings: {
          preserveAspectRatio: 'xMidYMid meet',
          progressiveLoad: true,
          hideOnTransparent: true
        }
      });

      this.lottieInstance.setSpeed(this.speed());
      
      this.lottieInstance.addEventListener('complete', () => {
        if (!this.destroyed) {
          // TODO: The 'emit' function requires a mandatory void argument
          this.animationComplete.emit();
        }
      });
      
      this.lottieInstance.addEventListener('loopComplete', () => {
        if (!this.destroyed) {
          // TODO: The 'emit' function requires a mandatory void argument
          this.loopComplete.emit();
        }
      });
      
      this.lottieInstance.addEventListener('DOMLoaded', () => {
        if (!this.destroyed) {
          this.animationCreated.emit(this.lottieInstance);
        }
      });
      
      this.useFallback = false;
      this.cdr.markForCheck();
      
    } catch (err) {
      console.error('Failed to load Lottie animation:', err);
      this.useFallback = true;
      this.animationError.emit(err as Error);
      this.cdr.markForCheck();
    }
  }

  private async loadAnimationData(): Promise<any> {
    // Import animation JSON files dynamically
    const animationType = this.animationType();
    switch (animationType) {
      case 'search-empty':
        return (await import('../../assets/search-empty.animation.json')).default;
      case 'success':
        return (await import('../../assets/success.animation.json')).default;
      case 'error':
        return (await import('../../assets/error.animation.json')).default;
      case 'upload':
        return (await import('../../assets/upload.animation.json')).default;
      case 'maintenance':
        return (await import('../../assets/maintenance.animation.json')).default;
      default:
        throw new Error(`Unknown animation type: ${animationType}`);
    }
  }

  play(): void {
    if (this.lottieInstance && !this.useFallback) {
      this.lottieInstance.play();
      this.isPlaying = true;
      this.isPaused = false;
      this.cdr.markForCheck();
    }
  }

  pause(): void {
    if (this.lottieInstance && !this.useFallback) {
      this.lottieInstance.pause();
      this.isPlaying = false;
      this.isPaused = true;
      this.cdr.markForCheck();
    }
  }

  stop(): void {
    if (this.lottieInstance && !this.useFallback) {
      this.lottieInstance.stop();
      this.isPlaying = false;
      this.isPaused = false;
      this.cdr.markForCheck();
    }
  }

  toggle(): void {
    if (this.isPaused || !this.isPlaying) {
      this.play();
    } else {
      this.pause();
    }
  }

  setSpeed(speed: number): void {
    if (this.lottieInstance && !this.useFallback) {
      this.lottieInstance.setSpeed(speed);
      
      this.cdr.markForCheck();
    }
  }

  goToAndPlay(frame: number): void {
    if (this.lottieInstance && !this.useFallback) {
      this.lottieInstance.goToAndPlay(frame, true);
      this.isPlaying = true;
      this.isPaused = false;
      this.cdr.markForCheck();
    }
  }

  goToAndStop(frame: number): void {
    if (this.lottieInstance && !this.useFallback) {
      this.lottieInstance.goToAndStop(frame, true);
      this.isPlaying = false;
      this.isPaused = true;
      this.cdr.markForCheck();
    }
  }

  private destroyAnimation(): void {
    if (this.lottieInstance) {
      this.lottieInstance.destroy();
      this.lottieInstance = null;
    }
  }

  getFallbackIcon(): string {
    const icons: Record<LottieAnimationType, string> = {
      'search-empty': 'search',
      'success': 'check_circle',
      'error': 'error',
      'upload': 'cloud_upload',
      'maintenance': 'build'
    };
    return icons[this.animationType()] || 'help_outline';
  }

  getFallbackColor(): string {
    const colors: Record<LottieAnimationType, string> = {
      'search-empty': '#667eea',
      'success': '#2bbb72',
      'error': '#f24545',
      'upload': '#667eea',
      'maintenance': '#9ca3af'
    };
    return colors[this.animationType()] || '#6b7280';
  }
}

import { Injectable } from '@angular/core';
import { QueuedAction, QueuedActionType } from './offline-queue.service';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';

export enum ConflictResolutionStrategy {
  SERVER_WINS = 'SERVER_WINS',
  CLIENT_WINS = 'CLIENT_WINS',
  MERGE = 'MERGE',
  MANUAL = 'MANUAL'
}

export interface ConflictInfo {
  action: QueuedAction;
  serverData: any;
  clientData: any;
  conflictFields: string[];
}

export interface MergeResult {
  resolved: boolean;
  mergedData: any;
  conflicts?: ConflictInfo[];
}

@Injectable({
  providedIn: 'root'
})
export class OfflineConflictResolverService {
  private defaultStrategy: ConflictResolutionStrategy = ConflictResolutionStrategy.SERVER_WINS;

  constructor(private http: HttpClient) {}

  setDefaultStrategy(strategy: ConflictResolutionStrategy): void {
    this.defaultStrategy = strategy;
  }

  async detectConflict(action: QueuedAction): Promise<ConflictInfo | null> {
    try {
      const serverData = await this.fetchServerData(action);
      if (!serverData) {
        return null;
      }

      const conflictFields = this.compareData(action.payload, serverData);
      
      if (conflictFields.length === 0) {
        return null;
      }

      return {
        action,
        serverData,
        clientData: action.payload,
        conflictFields
      };
    } catch (error) {
      return null;
    }
  }

  async resolveConflict(
    conflict: ConflictInfo,
    strategy?: ConflictResolutionStrategy
  ): Promise<MergeResult> {
    const resolutionStrategy = strategy || this.defaultStrategy;

    switch (resolutionStrategy) {
      case ConflictResolutionStrategy.SERVER_WINS:
        return this.resolveServerWins(conflict);
      
      case ConflictResolutionStrategy.CLIENT_WINS:
        return this.resolveClientWins(conflict);
      
      case ConflictResolutionStrategy.MERGE:
        return this.resolveAutoMerge(conflict);
      
      case ConflictResolutionStrategy.MANUAL:
        return {
          resolved: false,
          mergedData: null,
          conflicts: [conflict]
        };
      
      default:
        return this.resolveServerWins(conflict);
    }
  }

  private resolveServerWins(conflict: ConflictInfo): MergeResult {
    return {
      resolved: true,
      mergedData: conflict.serverData
    };
  }

  private resolveClientWins(conflict: ConflictInfo): MergeResult {
    return {
      resolved: true,
      mergedData: conflict.clientData
    };
  }

  private resolveAutoMerge(conflict: ConflictInfo): MergeResult {
    const merged = { ...conflict.serverData };
    const unresolvedConflicts: string[] = [];

    for (const field of conflict.conflictFields) {
      const serverValue = conflict.serverData[field];
      const clientValue = conflict.clientData[field];

      if (this.canAutoMerge(field, serverValue, clientValue)) {
        merged[field] = this.mergeValues(field, serverValue, clientValue);
      } else {
        unresolvedConflicts.push(field);
        merged[field] = serverValue;
      }
    }

    return {
      resolved: unresolvedConflicts.length === 0,
      mergedData: merged,
      conflicts: unresolvedConflicts.length > 0 ? [conflict] : undefined
    };
  }

  private compareData(clientData: any, serverData: any): string[] {
    const conflicts: string[] = [];
    const clientKeys = Object.keys(clientData);
    const serverKeys = Object.keys(serverData);
    const allKeys = [...new Set([...clientKeys, ...serverKeys])];

    for (let i = 0; i < allKeys.length; i++) {
      const key = allKeys[i];
      if (this.isSystemField(key)) {
        continue;
      }

      const clientValue = clientData[key];
      const serverValue = serverData[key];

      if (!this.valuesEqual(clientValue, serverValue)) {
        conflicts.push(key);
      }
    }

    return conflicts;
  }

  private isSystemField(field: string): boolean {
    const systemFields = ['id', 'createdAt', 'updatedAt', 'version', 'orgId', 'createdBy', 'updatedBy'];
    return systemFields.includes(field);
  }

  private valuesEqual(value1: any, value2: any): boolean {
    if (value1 === value2) {
      return true;
    }

    if (value1 == null || value2 == null) {
      return value1 === value2;
    }

    if (typeof value1 !== typeof value2) {
      return false;
    }

    if (typeof value1 === 'object') {
      return JSON.stringify(value1) === JSON.stringify(value2);
    }

    return false;
  }

  private canAutoMerge(field: string, serverValue: any, clientValue: any): boolean {
    if (typeof serverValue === 'number' && typeof clientValue === 'number') {
      return false;
    }

    if (typeof serverValue === 'string' && typeof clientValue === 'string') {
      if (serverValue.includes(clientValue) || clientValue.includes(serverValue)) {
        return true;
      }
    }

    if (Array.isArray(serverValue) && Array.isArray(clientValue)) {
      return true;
    }

    return false;
  }

  private mergeValues(field: string, serverValue: any, clientValue: any): any {
    if (Array.isArray(serverValue) && Array.isArray(clientValue)) {
      const merged = [...serverValue];
      for (const item of clientValue) {
        if (!merged.some(m => JSON.stringify(m) === JSON.stringify(item))) {
          merged.push(item);
        }
      }
      return merged;
    }

    if (typeof serverValue === 'string' && typeof clientValue === 'string') {
      if (clientValue.length > serverValue.length) {
        return clientValue;
      }
      return serverValue;
    }

    return serverValue;
  }

  private async fetchServerData(action: QueuedAction): Promise<any> {
    let url: string;

    switch (action.type) {
      case QueuedActionType.UPDATE_DOSSIER_STATUS:
        url = `/api/v1/dossiers/${action.payload.id}`;
        break;

      case QueuedActionType.UPDATE_APPOINTMENT:
        url = `/api/v1/appointments/${action.payload.id}`;
        break;

      case QueuedActionType.CREATE_MESSAGE:
      case QueuedActionType.CREATE_APPOINTMENT:
      case QueuedActionType.CREATE_NOTE:
        return null;

      default:
        return null;
    }

    try {
      return await firstValueFrom(this.http.get(url));
    } catch (error) {
      console.error('Failed to fetch server data for conflict detection:', error);
      return null;
    }
  }

  async resolveBatch(
    conflicts: ConflictInfo[],
    strategy: ConflictResolutionStrategy
  ): Promise<MergeResult[]> {
    const results: MergeResult[] = [];

    for (const conflict of conflicts) {
      const result = await this.resolveConflict(conflict, strategy);
      results.push(result);
    }

    return results;
  }
}

import { Component, OnInit, OnDestroy, AfterViewChecked, ChangeDetectorRef, input, output, viewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MessageResponse, MessageDirection, MessageDeliveryStatus } from '../services/message-api.service';
import { CdkVirtualScrollViewport, CdkFixedSizeVirtualScroll, CdkVirtualForOf } from '@angular/cdk/scrolling';
import { Subject } from 'rxjs';
import { MatIcon } from '@angular/material/icon';
import { MatIconButton } from '@angular/material/button';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';

export interface MessageAction {
  type: 'retry' | 'delete' | 'forward' | 'copy';
  message: MessageResponse;
}

@Component({
    selector: 'app-whatsapp-thread',
    standalone: true,
    templateUrl: './whatsapp-thread.component.html',
    styleUrls: ['./whatsapp-thread.component.scss'],
    imports: [
      CommonModule,
      MatIcon,
      DsSkeletonComponent,
      CdkVirtualScrollViewport,
      CdkFixedSizeVirtualScroll,
      CdkVirtualForOf,
      MatIconButton,
    ],
})
export class WhatsappThreadComponent implements OnInit, OnDestroy, AfterViewChecked {
  readonly messages = input<MessageResponse[]>([]);
  readonly loading = input(false);
  readonly isOnline = input(true);
  readonly messageAction = output<MessageAction>();

  readonly viewport = viewChild(CdkVirtualScrollViewport);

  MessageDirection = MessageDirection;
  MessageDeliveryStatus = MessageDeliveryStatus;
  Math = Math;

  private destroy$ = new Subject<void>();
  private shouldScrollToBottom = false;

  swipedMessageId: number | null = null;
  swipeOffset = 0;
  isSwiping = false;
  startX = 0;

  constructor(private cdr: ChangeDetectorRef) {}

  ngOnInit(): void {
    this.shouldScrollToBottom = true;
  }

  ngAfterViewChecked(): void {
    if (this.shouldScrollToBottom && this.viewport()) {
      this.scrollToBottom();
      this.shouldScrollToBottom = false;
    }
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  scrollToBottom(): void {
    const viewport = this.viewport();
    if (viewport) {
      viewport.scrollToIndex(this.messages().length - 1, 'smooth');
    }
  }

  onTouchStart(event: TouchEvent, message: MessageResponse): void {
    if (message.direction !== MessageDirection.OUTBOUND) {
      return;
    }

    this.isSwiping = true;
    this.startX = event.touches[0].clientX;
    this.swipedMessageId = message.id;
  }

  onTouchMove(event: TouchEvent, message: MessageResponse): void {
    if (!this.isSwiping || this.swipedMessageId !== message.id) {
      return;
    }

    const currentX = event.touches[0].clientX;
    const diffX = currentX - this.startX;

    if (diffX < 0 && diffX > -150) {
      this.swipeOffset = diffX;
      event.preventDefault();
    }
  }

  onTouchEnd(event: TouchEvent, message: MessageResponse): void {
    if (!this.isSwiping || this.swipedMessageId !== message.id) {
      return;
    }

    this.isSwiping = false;

    if (Math.abs(this.swipeOffset) > 75) {
      // Actions are shown via CSS when swiped
    }

    this.swipeOffset = 0;
    this.swipedMessageId = null;
  }

  onMouseDown(event: MouseEvent, message: MessageResponse): void {
    if (message.direction !== MessageDirection.OUTBOUND) {
      return;
    }

    this.isSwiping = true;
    this.startX = event.clientX;
    this.swipedMessageId = message.id;
  }

  onMouseMove(event: MouseEvent, message: MessageResponse): void {
    if (!this.isSwiping || this.swipedMessageId !== message.id) {
      return;
    }

    const currentX = event.clientX;
    const diffX = currentX - this.startX;

    if (diffX < 0 && diffX > -150) {
      this.swipeOffset = diffX;
      event.preventDefault();
    }
  }

  onMouseUp(event: MouseEvent, message: MessageResponse): void {
    if (!this.isSwiping || this.swipedMessageId !== message.id) {
      return;
    }

    this.isSwiping = false;

    if (Math.abs(this.swipeOffset) > 75) {
      // Actions are shown via CSS when swiped
    }

    this.swipeOffset = 0;
    this.swipedMessageId = null;
  }

  retryMessage(message: MessageResponse, event?: Event): void {
    if (event) {
      event.stopPropagation();
    }
    this.messageAction.emit({ type: 'retry', message });
  }

  deleteMessage(message: MessageResponse, event?: Event): void {
    if (event) {
      event.stopPropagation();
    }
    this.messageAction.emit({ type: 'delete', message });
  }

  copyMessage(message: MessageResponse, event?: Event): void {
    if (event) {
      event.stopPropagation();
    }
    navigator.clipboard.writeText(message.content);
    this.messageAction.emit({ type: 'copy', message });
  }

  formatTimestamp(timestamp: string): string {
    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) {
      return 'À l\'instant';
    } else if (diffMins < 60) {
      return `${diffMins} min`;
    } else if (diffHours < 24) {
      return date.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
    } else if (diffDays < 7) {
      return date.toLocaleDateString('fr-FR', { weekday: 'short', hour: '2-digit', minute: '2-digit' });
    } else {
      return date.toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });
    }
  }

  getDeliveryStatusIcon(status?: MessageDeliveryStatus): string {
    switch (status) {
      case MessageDeliveryStatus.PENDING: return '⏳';
      case MessageDeliveryStatus.SENT: return '✓';
      case MessageDeliveryStatus.DELIVERED: return '✓✓';
      case MessageDeliveryStatus.FAILED: return '✗';
      case MessageDeliveryStatus.READ: return '✓✓';
      default: return '';
    }
  }

  getDeliveryStatusClass(status?: MessageDeliveryStatus): string {
    switch (status) {
      case MessageDeliveryStatus.PENDING: return 'status-pending';
      case MessageDeliveryStatus.SENT: return 'status-sent';
      case MessageDeliveryStatus.DELIVERED: return 'status-delivered';
      case MessageDeliveryStatus.FAILED: return 'status-failed';
      case MessageDeliveryStatus.READ: return 'status-read';
      default: return '';
    }
  }

  showDateDivider(index: number): boolean {
    if (index === 0) {
      return true;
    }

    const currentDate = new Date(this.messages()[index].timestamp);
    const previousDate = new Date(this.messages()[index - 1].timestamp);

    return currentDate.toDateString() !== previousDate.toDateString();
  }

  getDateDividerText(timestamp: string): string {
    const date = new Date(timestamp);
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    if (date.toDateString() === today.toDateString()) {
      return 'Aujourd\'hui';
    } else if (date.toDateString() === yesterday.toDateString()) {
      return 'Hier';
    } else {
      return date.toLocaleDateString('fr-FR', { 
        weekday: 'long', 
        day: 'numeric', 
        month: 'long',
        year: date.getFullYear() !== today.getFullYear() ? 'numeric' : undefined
      });
    }
  }

  getSwipeTransform(messageId: number): string {
    if (this.swipedMessageId === messageId && this.isSwiping) {
      return `translateX(${this.swipeOffset}px)`;
    }
    return 'translateX(0)';
  }

  trackByMessageId(index: number, message: MessageResponse): number {
    return message.id;
  }
}

