      margin: 0 0 var(--spacing-1) 0;
      font-size: var(--font-size-lg);
      font-weight: var(--font-weight-semibold);
      color: var(--ds-text);
      text-align: center;
    }

    .action-sheet-subtitle {
      margin: 0;
      font-size: var(--font-size-sm);
      color: var(--ds-text-muted);
      text-align: center;
    }

    .action-sheet-content {
      flex: 1;
      overflow-y: auto;
      padding: var(--spacing-2) 0;
      -webkit-overflow-scrolling: touch;
    }

    .action-sheet-item {
      display: flex;
      align-items: center;
      gap: var(--spacing-4);
      width: 100%;
      padding: var(--spacing-4) var(--spacing-6);
      border: none;
      background: var(--ds-surface);
      color: var(--ds-text);
      font-size: var(--font-size-base);
      font-weight: var(--font-weight-medium);
      text-align: left;
      cursor: pointer;
      transition: background-color var(--duration-fast) var(--ease-out);
      min-height: 56px;
    }

    .action-sheet-item:hover:not(:disabled) {
      background: var(--ds-surface-2);
    }

    .action-sheet-item:active:not(:disabled) {
      background: var(--ds-bg);
    }

    .action-sheet-item:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    .action-icon {
      width: 24px;
      height: 24px;
      font-size: 24px;
      flex-shrink: 0;
    }

    .action-label {
      flex: 1;
      line-height: 1.5;
    }

    .action-primary {
      color: var(--ds-marine);
    }

    .action-primary .action-icon {
      color: var(--ds-marine);
    }

    .action-accent {
      color: var(--ds-primary-hover);
    }

    .action-accent .action-icon {
      color: var(--ds-primary-hover);
    }

    .action-warn {
      color: var(--ds-error);
    }

    .action-warn .action-icon {
      color: var(--ds-error);
    }

    .action-success {
      color: var(--ds-success);
    }

    .action-success .action-icon {
      color: var(--ds-success);
    }

    .action-sheet-footer {
      padding: var(--spacing-3) var(--spacing-4);
      border-top: var(--border-width-1) solid var(--ds-divider);
      background: var(--ds-surface-2);
    }

    .action-sheet-cancel {
      width: 100%;
      padding: var(--spacing-4);
      border: none;
      background: var(--ds-surface);
      color: var(--ds-text-muted);
      font-size: var(--font-size-base);
      font-weight: var(--font-weight-semibold);
      border-radius: var(--radius-lg);
      cursor: pointer;
      transition: background-color var(--duration-fast) var(--ease-out);
      min-height: 48px;
    }

    .action-sheet-cancel:hover {
      background: var(--ds-bg);
    }

    .action-sheet-cancel:active {
      background: var(--ds-divider);
    }

    ::ng-deep .mat-divider {
      margin: 0 var(--spacing-6);
    }
  `],
    imports: [MatIcon, MatDivider]
})
export class MobileActionSheetComponent {
  constructor(
    @Inject(MAT_BOTTOM_SHEET_DATA) public data: MobileActionSheetData,
    private bottomSheetRef: MatBottomSheetRef<MobileActionSheetComponent>
  ) {}

  onActionClick(action: MobileAction): void {
    if (!action.disabled) {
      this.bottomSheetRef.dismiss(action.action);
    }
  }

  onCancel(): void {
    this.bottomSheetRef.dismiss(null);
  }
}

