import { Component, Inject } from '@angular/core';
import { MAT_BOTTOM_SHEET_DATA, MatBottomSheetRef } from '@angular/material/bottom-sheet';
import { MatIconButton, MatButton } from '@angular/material/button';
import { MatIcon } from '@angular/material/icon';
import { MatFormField, MatLabel } from '@angular/material/form-field';
import { MatInput } from '@angular/material/input';
import { FormsModule } from '@angular/forms';
import { MatSelect } from '@angular/material/select';
import { MatOption } from '@angular/material/autocomplete';

export interface MobileFilterData {
  filters: Record<string, unknown>;
  config: FilterConfig[];
}

export interface FilterConfig {
  key: string;
  label: string;
  type: 'text' | 'select' | 'autocomplete';
  options?: { value: string; label: string }[];
  placeholder?: string;
}

@Component({
    selector: 'app-mobile-filter-sheet',
    template: `
    <div class="mobile-filter-sheet">
      <div class="sheet-header">
        <h3>Filtres</h3>
        <button mat-icon-button (click)="close()">
          <mat-icon>close</mat-icon>
        </button>
      </div>
    
      <div class="sheet-content">
        @for (filter of config; track filter) {
          <div class="filter-group">
            <mat-form-field appearance="outline" class="full-width">
              <mat-label>{{ filter.label }}</mat-label>
              @if (filter.type === 'text') {
                <input
                  matInput
                  [placeholder]="filter.placeholder || ''"
                  [(ngModel)]="filters[filter.key]"
                  />
              }
              @if (filter.type === 'select') {
                <mat-select
                  [(ngModel)]="filters[filter.key]"
                  >
                  <mat-option [value]="''">Tous</mat-option>
                  @for (option of filter.options; track option) {
                    <mat-option
                      [value]="option.value"
                      >
                      {{ option.label }}
                    </mat-option>
                  }
                </mat-select>
              }
            </mat-form-field>
          </div>
        }
      </div>
    
      <div class="sheet-actions">
        <button mat-button (click)="reset()">Réinitialiser</button>
        <button mat-raised-button color="primary" (click)="apply()">
          Appliquer
        </button>
      </div>
    </div>
    `,
    styles: [`
    .mobile-filter-sheet {
      padding: var(--spacing-4);
      min-height: 60vh;
      display: flex;
      flex-direction: column;
    }
    
    .sheet-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: var(--spacing-4);
    }
    
    .sheet-header h3 {
      margin: 0;
      font-size: var(--font-size-lg);
      font-weight: var(--font-weight-semibold);
    }
    
    .sheet-content {
      flex: 1;
      overflow-y: auto;
    }
    
    .filter-group {
      margin-bottom: var(--spacing-3);
    }
    
    .full-width {
      width: 100%;
    }
    
    .sheet-actions {
      display: flex;
      gap: var(--spacing-3);
      margin-top: var(--spacing-4);
      padding-top: var(--spacing-4);
      border-top: 1px solid var(--ds-divider);
    }
    
    .sheet-actions button {
      flex: 1;
    }
  `],
    imports: [MatIconButton, MatIcon, MatFormField, MatLabel, MatInput, FormsModule, MatSelect, MatOption, MatButton]
})
export class MobileFilterSheetComponent {
  filters: Record<string, unknown>;
  config: FilterConfig[];

  constructor(
    @Inject(MAT_BOTTOM_SHEET_DATA) public data: MobileFilterData,
    private bottomSheetRef: MatBottomSheetRef<MobileFilterSheetComponent>
  ) {
    this.filters = { ...data.filters };
    this.config = data.config;
  }

  apply(): void {
    this.bottomSheetRef.dismiss({ action: 'apply', filters: this.filters });
  }

  reset(): void {
    this.bottomSheetRef.dismiss({ action: 'reset' });
  }

  close(): void {
    this.bottomSheetRef.dismiss({ action: 'cancel' });
  }
}

import { Injectable } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';

interface NavigationHistoryEntry {
  url: string;
  scrollPosition: [number, number];
}

@Injectable({
  providedIn: 'root'
})
export class NavigationService {
  private navigationHistory: NavigationHistoryEntry[] = [];
  private currentIndex = -1;
  private scrollPositions = new Map<string, [number, number]>();
  private isBackNavigation = false;
  private isForwardNavigation = false;

  constructor(private router: Router) {
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd)
    ).subscribe((event) => {
      this.updateNavigationHistory(event.urlAfterRedirects);
    });

    window.addEventListener('popstate', () => {
      this.isBackNavigation = true;
      setTimeout(() => {
        this.isBackNavigation = false;
      }, 500);
    });
  }

  private updateNavigationHistory(url: string): void {
    if (this.currentIndex >= 0 && this.navigationHistory[this.currentIndex]) {
      const scrollPos = this.getScrollPosition();
      this.scrollPositions.set(this.navigationHistory[this.currentIndex].url, scrollPos);
    }

    if (this.currentIndex < this.navigationHistory.length - 1) {
      this.navigationHistory = this.navigationHistory.slice(0, this.currentIndex + 1);
    }

    this.navigationHistory.push({
      url,
      scrollPosition: [0, 0]
    });
    this.currentIndex = this.navigationHistory.length - 1;
  }

  getRouteAnimation(): string {
    if (this.isBackNavigation) {
      return 'slideRight';
    } else if (this.isForwardNavigation) {
      return 'slideLeft';
    }
    return 'fadeIn';
  }

  saveScrollPosition(url?: string): void {
    const currentUrl = url || this.router.url;
    const scrollPos = this.getScrollPosition();
    this.scrollPositions.set(currentUrl, scrollPos);
  }

  restoreScrollPosition(url?: string): void {
    const currentUrl = url || this.router.url;
    const scrollPos = this.scrollPositions.get(currentUrl);
    
    if (scrollPos) {
      setTimeout(() => {
        window.scrollTo(scrollPos[0], scrollPos[1]);
      }, 0);
    } else {
      setTimeout(() => {
        window.scrollTo(0, 0);
      }, 0);
    }
  }

  private getScrollPosition(): [number, number] {
    return [window.pageXOffset || document.documentElement.scrollLeft || 0,
            window.pageYOffset || document.documentElement.scrollTop || 0];
  }

  navigateBack(): void {
    if (this.currentIndex > 0) {
      this.isBackNavigation = true;
      this.currentIndex--;
      const entry = this.navigationHistory[this.currentIndex];
      this.router.navigateByUrl(entry.url).then(() => {
        this.restoreScrollPosition(entry.url);
        setTimeout(() => {
          this.isBackNavigation = false;
        }, 500);
      });
    }
  }

  navigateForward(): void {
    if (this.currentIndex < this.navigationHistory.length - 1) {
      this.isForwardNavigation = true;
      this.currentIndex++;
      const entry = this.navigationHistory[this.currentIndex];
      this.router.navigateByUrl(entry.url).then(() => {
        this.restoreScrollPosition(entry.url);
        setTimeout(() => {
          this.isForwardNavigation = false;
        }, 500);
      });
    }
  }

  canGoBack(): boolean {
    return this.currentIndex > 0;
  }

  canGoForward(): boolean {
    return this.currentIndex < this.navigationHistory.length - 1;
  }
}

import { Component, OnInit } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { DsIconComponent } from '../design-system';

interface NavItem {
  label: string;
  /** Clé `ds-icon` */
  icon: string;
  route: string;
  badge?: number;
}

@Component({
    selector: 'app-mobile-bottom-navigation',
    template: `
    @if (shouldShowNav) {
      <nav class="mobile-bottom-nav" role="navigation" aria-label="Navigation principale mobile">
        @for (item of navItems; track item) {
          <button
            class="nav-item"
            [class.active]="isActive(item.route)"
            (click)="navigate(item.route)"
            [attr.aria-label]="item.label"
            [attr.aria-current]="isActive(item.route) ? 'page' : null"
            type="button">
            <div class="nav-icon-wrapper">
              <ds-icon [name]="item.icon" [size]="24" [attr.aria-hidden]="true"></ds-icon>
              @if (item.badge && item.badge > 0) {
                <span class="badge" [attr.aria-label]="item.badge + ' notifications'">
                  {{ item.badge > 99 ? '99+' : item.badge }}
                </span>
              }
            </div>
            <span class="nav-label">{{ item.label }}</span>
          </button>
        }
      </nav>
    }
    `,
    styles: [`
    .mobile-bottom-nav {
      display: none;
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--ds-surface);
      border-top: 1px solid var(--ds-divider);
      box-shadow: 0 -4px 16px color-mix(in srgb, var(--ds-text) 8%, transparent);
      z-index: 1000;
      height: 64px;
      padding-bottom: env(safe-area-inset-bottom);
    }

    @media (max-width: 767px) {
      .mobile-bottom-nav {
        display: flex;
        justify-content: space-around;
        align-items: stretch;
      }
    }

    .nav-item {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: var(--ds-space-2) var(--ds-space-1);
      border: none;
      background: transparent;
      color: var(--ds-text-muted);
      cursor: pointer;
      transition: all 0.2s ease;
      position: relative;
      min-width: 48px;
      min-height: 48px;
      touch-action: manipulation;
      -webkit-tap-highlight-color: transparent;
    }

    .nav-item:active {
      transform: scale(0.95);
    }

    .nav-item.active {
      color: var(--ds-marine);
    }

    .nav-item.active::before {
      content: '';
      position: absolute;
      top: 0;
      left: 50%;
      transform: translateX(-50%);
      width: 32px;
      height: 3px;
      background: var(--ds-marine);
      border-radius: 0 0 var(--ds-radius-sm) var(--ds-radius-sm);
    }

    .nav-icon-wrapper {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .nav-item ds-icon {
      display: flex;
    }

    .nav-label {
      font-size: 11px;
      font-weight: 500;
      margin-top: 4px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      max-width: 100%;
    }

    .badge {
      position: absolute;
      top: -4px;
      right: -8px;
      background: var(--ds-error);
      color: var(--ds-text-inverse);
      font-size: 10px;
      font-weight: 600;
      padding: 2px 5px;
      border-radius: 10px;
      min-width: 18px;
      text-align: center;
      line-height: 1.2;
    }

    /* Dark theme — tokens */
    .dark-theme .mobile-bottom-nav {
      background: var(--ds-surface);
      border-top-color: var(--ds-border);
    }

    .dark-theme .nav-item {
      color: var(--ds-text-muted);
    }

    .dark-theme .nav-item.active {
      color: var(--ds-marine-light);
    }

    .dark-theme .nav-item.active::before {
      background: var(--ds-marine-light);
    }

    /* Safe area support for notched devices */
    @supports (padding: env(safe-area-inset-bottom)) {
      .mobile-bottom-nav {
        padding-bottom: calc(8px + env(safe-area-inset-bottom));
      }
    }
  `],
    imports: [DsIconComponent]
})
export class MobileBottomNavigationComponent implements OnInit {
  currentRoute = '';
  shouldShowNav = true;

  navItems: NavItem[] = [
    { label: 'Tableau de bord', icon: 'chart', route: '/dashboard' },
    { label: 'Dossiers', icon: 'folder', route: '/dossiers' },
    { label: 'Annonces', icon: 'megaphone', route: '/annonces' },
    { label: 'Plus', icon: 'bars-asc', route: '/menu' }
  ];

  constructor(private router: Router) {}

  ngOnInit(): void {
    this.currentRoute = this.router.url;
    
    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: any) => {
        this.currentRoute = event.url;
        this.updateVisibility();
      });

    this.updateVisibility();
  }

  navigate(route: string): void {
    this.router.navigate([route]);
  }

  isActive(route: string): boolean {
    return this.currentRoute.startsWith(route);
  }

  private updateVisibility(): void {
    // Hide bottom nav on login and full-screen pages
    const hideRoutes = ['/login', '/access-denied', '/session-expired'];
    this.shouldShowNav = !hideRoutes.some(route => this.currentRoute.startsWith(route));
  }
}

