interface NotificationChannel {
  id: string;
  label: string;
  description: string;
  icon: string;
  enabled: boolean;
}

interface NotificationType {
  id: string;
  label: string;
  description: string;
  icon: string;
  enabled: boolean;
}

interface DigestFrequency {
  value: string;
  label: string;
