    styleUrls: ['./notification-preferences-form.component.css'],
    animations: [
        trigger('slideDown', [
            transition(':enter', [
                style({ height: '0', opacity: '0', overflow: 'hidden' }),
                animate('300ms ease-out', style({ height: '*', opacity: '1' }))
            ]),
            transition(':leave', [
                style({ height: '*', opacity: '1', overflow: 'hidden' }),
                animate('300ms ease-in', style({ height: '0', opacity: '0' }))
            ])
        ])
    ],
    imports: [FormsModule, ReactiveFormsModule, MatProgressBar, DsCardComponent, DsSkeletonComponent, MatIcon, MatSlideToggle, MatSlider, MatSliderThumb, MatHint, MatRadioGroup, MatRadioButton, MatDivider, MatButton]
})
export class NotificationPreferencesFormComponent implements OnInit, OnDestroy {
  private destroy$ = new Subject<void>();

  preferencesForm!: FormGroup;
  loading = false;
  saving = false;

  // Original values for dirty check
  originalValues: Record<string, unknown> = {};

  // Notification channels
  channels: NotificationChannel[] = [
    {
      id: 'email',
      label: 'Email',
      description: 'Recevez des notifications par email',
      icon: 'email',
      enabled: true
    },
    {
      id: 'sms',
      label: 'SMS',
      description: 'Recevez des alertes par SMS',
      icon: 'sms',
      enabled: false
    },
    {
      id: 'inApp',
      label: 'Dans l\'application',
      description: 'Notifications dans l\'interface',
      icon: 'notifications',
      enabled: true
    },
    {
      id: 'push',
      label: 'Push',
      description: 'Notifications push dans le navigateur',
      icon: 'notifications_active',
      enabled: true
    }
  ];

  // Notification types
  notificationTypes: NotificationType[] = [
    {
      id: 'newDossier',
      label: 'Nouveau dossier',
      description: 'Notification lors de la création d\'un nouveau dossier',
      icon: 'folder',
      enabled: true
    },
    {
      id: 'newMessage',
      label: 'Nouveau message',
      description: 'Notification lors de la réception d\'un message',
      icon: 'message',
      enabled: true
    },
    {
      id: 'appointment',
      label: 'Rendez-vous',
      description: 'Rappels de rendez-vous à venir',
      icon: 'event',
      enabled: true
    },
    {
      id: 'statusChange',
      label: 'Changement de statut',
      description: 'Notification lors du changement de statut d\'un dossier',
      icon: 'update',
      enabled: true
    }
  ];

  // Digest frequencies
  digestFrequencies: DigestFrequency[] = [
    {
      value: 'instant',
      label: 'Instantané',
      description: 'Recevoir les notifications immédiatement',
      icon: 'flash_on'
    },
    {
      value: 'hourly',
      label: 'Horaire',
      description: 'Grouper les notifications par heure',
      icon: 'schedule'
    },
    {
      value: 'daily',
      label: 'Quotidien',
      description: 'Recevoir un résumé quotidien',
      icon: 'today'
    }
  ];

  // Preview examples
  exampleNotifications: NotificationExample[] = [];

  // Quiet hours range (default: 22h-8h)
  quietHoursStart = 22;
  quietHoursEnd = 8;
  quietHoursEnabled = false;

  constructor(
    private fb: FormBuilder,
    private userPreferencesService: UserPreferencesService,
    private notificationService: NotificationService
  ) { }

  ngOnInit(): void {
    this.initializeForm();
    this.loadPreferences();
    this.setupFormListeners();
    this.updateExampleNotifications();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private initializeForm(): void {
    this.preferencesForm = this.fb.group({
      // Channels
      emailEnabled: [true],
      smsEnabled: [false],
      inAppEnabled: [true],
      pushEnabled: [true],

      // Notification types
      newDossierEnabled: [true],
      newMessageEnabled: [true],
      appointmentEnabled: [true],
      statusChangeEnabled: [true],

      // Quiet hours
      quietHoursEnabled: [false],
      quietHoursStart: [22, [Validators.min(0), Validators.max(23)]],
      quietHoursEnd: [8, [Validators.min(0), Validators.max(23)]],

      // Digest frequency
      digestFrequency: ['instant', Validators.required]
    });
  }

  private loadPreferences(): void {
    this.loading = true;

    this.userPreferencesService.getPreferences()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (preferences) => {
          if (preferences.notifications) {
            const notifPrefs = preferences.notifications;
            const notifPrefsExtended = notifPrefs as any;

            this.preferencesForm.patchValue({
              emailEnabled: notifPrefs.emailEnabled !== false,
              smsEnabled: notifPrefs.smsEnabled || false,
              inAppEnabled: notifPrefs.inAppEnabled !== false,
              pushEnabled: notifPrefs.pushEnabled !== false,

              newDossierEnabled: (notifPrefsExtended.newDossierEnabled as boolean) !== false,
              newMessageEnabled: (notifPrefsExtended.newMessageEnabled as boolean) !== false,
              appointmentEnabled: (notifPrefsExtended.appointmentEnabled as boolean) !== false,
              statusChangeEnabled: (notifPrefsExtended.statusChangeEnabled as boolean) !== false,

              quietHoursEnabled: (notifPrefsExtended.quietHoursEnabled as boolean) || false,
              quietHoursStart: (notifPrefsExtended.quietHoursStart as number) || 22,
              quietHoursEnd: (notifPrefsExtended.quietHoursEnd as number) || 8,

              digestFrequency: (notifPrefsExtended.digestFrequency as string) || 'instant'
            });

            this.updateChannelsFromForm();
            this.updateTypesFromForm();
            this.updateQuietHoursFromForm();
          }
          this.originalValues = this.preferencesForm.value as Record<string, unknown>;
          this.loading = false;
        },
        error: (error) => {
          console.error('Error loading notification preferences:', error);
          this.notificationService.error('Erreur lors du chargement des préférences de notification');
          this.loading = false;
        }
      });
  }

  private setupFormListeners(): void {
    // Update preview on form changes
    this.preferencesForm.valueChanges
      .pipe(debounceTime(300), distinctUntilChanged(), takeUntil(this.destroy$))
      .subscribe(() => {
        this.updateChannelsFromForm();
        this.updateTypesFromForm();
        this.updateQuietHoursFromForm();
        this.updateExampleNotifications();
      });
  }

  private updateChannelsFromForm(): void {
    const formValue = this.preferencesForm.value;
    this.channels.forEach(channel => {
      channel.enabled = formValue[`${channel.id}Enabled`] || false;
    });
  }

  private updateTypesFromForm(): void {
    const formValue = this.preferencesForm.value;
    this.notificationTypes.forEach(type => {
      type.enabled = formValue[`${type.id}Enabled`] || false;
    });
  }

  private updateQuietHoursFromForm(): void {
    const formValue = this.preferencesForm.value;
    this.quietHoursEnabled = formValue.quietHoursEnabled || false;
    this.quietHoursStart = formValue.quietHoursStart || 22;
    this.quietHoursEnd = formValue.quietHoursEnd || 8;
  }

  private updateExampleNotifications(): void {
    const formValue = this.preferencesForm.value;
    const now = new Date();

    this.exampleNotifications = [];

    if (formValue.newDossierEnabled) {
      this.exampleNotifications.push({
        title: 'Nouveau dossier',
        message: 'Le dossier "Appartement 3 pièces Paris 15e" a été créé',
        timestamp: new Date(now.getTime() - 5 * 60000),
        type: 'newDossier',
        icon: 'folder'
      });
    }

    if (formValue.newMessageEnabled) {
      this.exampleNotifications.push({
        title: 'Nouveau message',
        message: 'Jean Dupont vous a envoyé un message',
        timestamp: new Date(now.getTime() - 15 * 60000),
        type: 'newMessage',
        icon: 'message'
      });
    }

    if (formValue.appointmentEnabled) {
      this.exampleNotifications.push({
        title: 'Rendez-vous à venir',
        message: 'Visite prévue dans 1 heure - 25 Rue de la Paix',
        timestamp: new Date(now.getTime() + 60 * 60000),
        type: 'appointment',
        icon: 'event'
      });
    }

    if (formValue.statusChangeEnabled) {
      this.exampleNotifications.push({
        title: 'Changement de statut',
        message: 'Le dossier "Villa Nice" est passé en "En cours"',
        timestamp: new Date(now.getTime() - 30 * 60000),
        type: 'statusChange',
        icon: 'update'
      });
    }
  }

  onSave(): void {
    if (!this.preferencesForm.valid) {
      this.notificationService.warning('Veuillez corriger les erreurs dans le formulaire');
      return;
    }

    this.saving = true;
    const formValue = this.preferencesForm.value;

    const notificationPreferences = {
      emailEnabled: formValue.emailEnabled,
      smsEnabled: formValue.smsEnabled,
      inAppEnabled: formValue.inAppEnabled,
      pushEnabled: formValue.pushEnabled,

      newDossierEnabled: formValue.newDossierEnabled,
      newMessageEnabled: formValue.newMessageEnabled,
      appointmentEnabled: formValue.appointmentEnabled,
      statusChangeEnabled: formValue.statusChangeEnabled,

      quietHoursEnabled: formValue.quietHoursEnabled,
      quietHoursStart: formValue.quietHoursStart,
      quietHoursEnd: formValue.quietHoursEnd,

      digestFrequency: formValue.digestFrequency
    };

    this.userPreferencesService.updatePreferences('notifications', notificationPreferences)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          this.originalValues = this.preferencesForm.value as Record<string, unknown>;
          this.saving = false;
          this.notificationService.success('Préférences de notification enregistrées avec succès');
        },
        error: (error) => {
          console.error('Error saving notification preferences:', error);
          this.saving = false;
          this.notificationService.error('Erreur lors de l\'enregistrement des préférences');
        }
      });
  }

  onCancel(): void {
    if (this.hasUnsavedChanges()) {
      this.preferencesForm.patchValue(this.originalValues);
      this.updateChannelsFromForm();
      this.updateTypesFromForm();
      this.updateQuietHoursFromForm();
      this.updateExampleNotifications();
      this.notificationService.info('Modifications annulées');
    }
  }

  hasUnsavedChanges(): boolean {
    return JSON.stringify(this.preferencesForm.value) !== JSON.stringify(this.originalValues);
  }

  formatQuietHoursLabel(value: number): string {
    return `${value.toString().padStart(2, '0')}:00`;
  }

  getQuietHoursDisplay(): string {
    return `${this.formatQuietHoursLabel(this.quietHoursStart)} - ${this.formatQuietHoursLabel(this.quietHoursEnd)}`;
  }

  getDigestFrequencyLabel(): string {
    const freq = this.digestFrequencies.find(f => f.value === this.preferencesForm.get('digestFrequency')?.value);
    return freq ? freq.label : '';
  }

  getDigestFrequencyDescription(): string {
    const freq = this.digestFrequencies.find(f => f.value === this.preferencesForm.get('digestFrequency')?.value);
    return freq ? freq.description : '';
  }

  getEnabledChannelsCount(): number {
    return this.channels.filter(c => c.enabled).length;
  }

  getEnabledTypesCount(): number {
    return this.notificationTypes.filter(t => t.enabled).length;
  }

  getRelativeTime(date: Date): string {
    const now = new Date();
    const diffMs = date.getTime() - now.getTime();
    const diffMins = Math.floor(diffMs / 60000);

    if (diffMins < 0) {
      const absMins = Math.abs(diffMins);
      if (absMins < 60) {
        return `Il y a ${absMins} min`;
      }
      const hours = Math.floor(absMins / 60);
      return `Il y a ${hours}h`;
    } else {
      if (diffMins < 60) {
        return `Dans ${diffMins} min`;
      }
      const hours = Math.floor(diffMins / 60);
      return `Dans ${hours}h`;
    }
  }

  isQuietHoursActive(): boolean {
    if (!this.quietHoursEnabled) {
      return false;
    }

    const now = new Date();
    const currentHour = now.getHours();

    if (this.quietHoursStart < this.quietHoursEnd) {
      // Normal range (e.g., 1h-5h)
      return currentHour >= this.quietHoursStart && currentHour < this.quietHoursEnd;
    } else {
      // Overnight range (e.g., 22h-8h)
      return currentHour >= this.quietHoursStart || currentHour < this.quietHoursEnd;
    }
  }

  getActiveChannelIcons(): string[] {
    return this.channels.filter(c => c.enabled).map(c => c.icon);
  }

  getDigestFrequencyIcon(): string {
    const freq = this.digestFrequencies.find(f => f.value === this.preferencesForm.get('digestFrequency')?.value);
    return freq ? freq.icon : '';
  }
}

import { Injectable, OnDestroy } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, BehaviorSubject, timer, Subject } from 'rxjs';
import { switchMap, tap, takeUntil } from 'rxjs/operators';
import { environment } from '../../environments/environment';

export interface NotificationResponse {
  id: number;
  orgId: string;
  dossierId?: number;
  type: 'EMAIL' | 'SMS' | 'WHATSAPP' | 'IN_APP';
  status: 'PENDING' | 'SENT' | 'FAILED';
  templateId: string;
  variables?: { [key: string]: any };
  recipient: string;
  subject?: string;
  message?: string;
  actionUrl?: string;
  errorMessage?: string;
  retryCount: number;
  maxRetries: number;
  sentAt?: string;
  readAt?: string;
  createdAt: string;
  updatedAt: string;
}

export interface NotificationPage {
  content: NotificationResponse[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
}

@Injectable({
  providedIn: 'root'
})
export class NotificationApiService implements OnDestroy {
  private apiUrl = `${environment.apiBaseUrl}/v1/notifications`;
  private pollingInterval = 30000;
  private unreadCountSubject = new BehaviorSubject<number>(0);
  public unreadCount$ = this.unreadCountSubject.asObservable();
  private destroy$ = new Subject<void>();

  constructor(private http: HttpClient) {
    this.startPolling();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private startPolling(): void {
    timer(0, this.pollingInterval)
      .pipe(
        takeUntil(this.destroy$),
        switchMap(() => this.fetchUnreadCount())
      )
      .subscribe({
        next: (count) => this.unreadCountSubject.next(count),
        error: (err) => console.error('Error polling unread count:', err)
      });
  }

  private fetchUnreadCount(): Observable<number> {
    return this.http.get<number>(`${this.apiUrl}/unread-count`);
  }

  list(
    dossierId?: number,
    type?: string,
    status?: string,
    page = 0,
    size = 20,
    sort = 'createdAt,desc'
  ): Observable<NotificationPage> {
    let params = new HttpParams()
      .set('page', page.toString())
      .set('size', size.toString())
      .set('sort', sort);

    if (dossierId) {
      params = params.set('dossierId', dossierId.toString());
    }
    if (type) {
      params = params.set('type', type);
    }
    if (status) {
      params = params.set('status', status);
    }

    return this.http.get<NotificationPage>(this.apiUrl, { params });
  }

  getById(id: number): Observable<NotificationResponse> {
    return this.http.get<NotificationResponse>(`${this.apiUrl}/${id}`);
  }

  markAsRead(id: number): Observable<NotificationResponse> {
    return this.http.patch<NotificationResponse>(`${this.apiUrl}/${id}/read`, {}).pipe(
      tap(() => {
        const currentCount = this.unreadCountSubject.value;
        if (currentCount > 0) {
          this.unreadCountSubject.next(currentCount - 1);
        }
      })
    );
  }

  markAsUnread(id: number): Observable<NotificationResponse> {
    return this.http.patch<NotificationResponse>(`${this.apiUrl}/${id}/unread`, {}).pipe(
      tap(() => {
        const currentCount = this.unreadCountSubject.value;
        this.unreadCountSubject.next(currentCount + 1);
      })
    );
  }

  getUnreadCount(): Observable<number> {
    return this.unreadCount$;
  }

  refreshUnreadCount(): void {
    this.fetchUnreadCount().subscribe({
      next: (count) => this.unreadCountSubject.next(count),
      error: (err) => console.error('Error refreshing unread count:', err)
    });
  }
}

import { Injectable } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import {
  PushNotifications,
  PushNotificationSchema,
  ActionPerformed,
  Token
} from '@capacitor/push-notifications';
import { BehaviorSubject, from, Observable, of, Subject } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface PushNotificationPermission {
  granted: boolean;
  denied: boolean;
}

export interface NotificationPayload {
  title: string;
  body: string;
  data?: any;
  badge?: number;
  sound?: string;
  channelId?: string;
}

/**
 * Service for native push notifications
 * Handles FCM (Android) and APNs (iOS) push notifications
 */
@Injectable({
  providedIn: 'root'
})
export class NativePushNotificationsService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();

  private readonly tokenSubject = new BehaviorSubject<string | null>(null);
  private readonly notificationReceivedSubject = new Subject<PushNotificationSchema>();
  private readonly notificationActionSubject = new Subject<ActionPerformed>();

  public readonly token$ = this.tokenSubject.asObservable();
  public readonly notificationReceived$ = this.notificationReceivedSubject.asObservable();
  public readonly notificationAction$ = this.notificationActionSubject.asObservable();

  constructor() {
    if (this.isNativePlatform) {
      this.initializePushNotifications();
    }
  }

  /**
   * Initialize push notification listeners
   */
  private initializePushNotifications(): void {
    // Registration success
    PushNotifications.addListener('registration', (token: Token) => {
      console.log('Push registration success, token:', token.value);
      this.tokenSubject.next(token.value);
    });

    // Registration error
    PushNotifications.addListener('registrationError', (error: any) => {
      console.error('Push registration error:', error);
      this.tokenSubject.next(null);
    });

    // Notification received (app in foreground)
    PushNotifications.addListener('pushNotificationReceived',
      (notification: PushNotificationSchema) => {
        console.log('Push notification received:', notification);
        this.notificationReceivedSubject.next(notification);
      }
    );

    // Notification action performed (user tapped)
    PushNotifications.addListener('pushNotificationActionPerformed',
      (notification: ActionPerformed) => {
        console.log('Push notification action performed:', notification);
        this.notificationActionSubject.next(notification);
      }
    );
  }

  /**
   * Request push notification permissions
   */
  requestPermissions(): Observable<PushNotificationPermission> {
    if (!this.isNativePlatform) {
      return of({ granted: false, denied: true });
    }

    return from(PushNotifications.requestPermissions()).pipe(
      map((result) => ({
        granted: result.receive === 'granted',
        denied: result.receive === 'denied'
      })),
      catchError((error) => {
        console.error('Error requesting push notification permissions:', error);
        return of({ granted: false, denied: true });
      })
    );
  }

  /**
   * Check current push notification permissions
   */
  checkPermissions(): Observable<PushNotificationPermission> {
    if (!this.isNativePlatform) {
      return of({ granted: false, denied: true });
    }

    return from(PushNotifications.checkPermissions()).pipe(
      map((result) => ({
        granted: result.receive === 'granted',
        denied: result.receive === 'denied'
      })),
      catchError(() => of({ granted: false, denied: true }))
    );
  }

  /**
   * Register for push notifications
   */
  register(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.register()).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error registering for push notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Get the current push notification token
   */
  getToken(): string | null {
    return this.tokenSubject.value;
  }

  /**
   * Get delivered notifications (iOS only)
   */
  getDeliveredNotifications(): Observable<PushNotificationSchema[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(PushNotifications.getDeliveredNotifications()).pipe(
      map((result) => result.notifications),
      catchError(() => of([]))
    );
  }

  /**
   * Remove delivered notifications
   */
  removeDeliveredNotifications(notificationIds: string[]): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.removeDeliveredNotifications({
      notifications: notificationIds.map(id => ({ id } as any))
    })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error removing delivered notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Remove all delivered notifications
   */
  removeAllDeliveredNotifications(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.removeAllDeliveredNotifications()).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error removing all delivered notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Create notification channel (Android only)
   */
  createChannel(
    id: string,
    name: string,
    importance: 1 | 2 | 3 | 4 | 5 = 3,
    description?: string,
    sound?: string,
    vibration = true,
    lights = true
  ): Observable<boolean> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of(false);
    }

    return from(PushNotifications.createChannel({
      id,
      name,
      importance,
      description,
      sound,
      vibration,
      lights
    })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error creating notification channel:', error);
        return of(false);
      })
    );
  }

  /**
   * Delete notification channel (Android only)
   */
  deleteChannel(channelId: string): Observable<boolean> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of(false);
    }

    return from(PushNotifications.deleteChannel({ id: channelId })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error deleting notification channel:', error);
        return of(false);
      })
    );
  }

  /**
   * List notification channels (Android only)
   */
  listChannels(): Observable<any[]> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of([]);
    }

    return from(PushNotifications.listChannels()).pipe(
      map((result) => result.channels),
      catchError(() => of([]))
    );
  }

  /**
   * Initialize default notification channels (Android)
   */
  initializeDefaultChannels(): void {
    if (Capacitor.getPlatform() === 'android') {
      this.createChannel(
        'messages',
        'Messages',
        5,
        'Notifications pour les nouveaux messages',
        'default',
        true,
        true
      ).subscribe();

      this.createChannel(
        'appointments',
        'Rendez-vous',
        4,
        'Rappels de rendez-vous',
        'default',
        true,
        false
      ).subscribe();

      this.createChannel(
        'updates',
        'Mises à jour',
        3,
        'Mises à jour de dossiers',
        undefined,
        false,
        false
      ).subscribe();

      this.createChannel(
        'general',
        'Général',
        2,
        'Notifications générales',
        undefined,
        false,
        false
      ).subscribe();
    }
  }

  /**
   * Handle notification routing based on action
   */
  handleNotificationAction(action: ActionPerformed): { route: string; params?: any } | null {
    const data = action.notification.data;

    if (!data) {
      return { route: '/' };
    }

    // Route based on notification type
    switch (data.type) {
      case 'message':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'messages' }
        };

      case 'appointment':
        return {
          route: `/calendar`,
          params: { eventId: data.eventId }
        };

      case 'task':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'tasks', taskId: data.taskId }
        };

      case 'dossier_update':
        return {
          route: `/dossiers/${data.dossierId}`
        };

      case 'whatsapp':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'whatsapp' }
        };

      default:
        return { route: '/' };
    }
  }

  /**
   * Clean up listeners
   */
  removeAllListeners(): void {
    if (this.isNativePlatform) {
      PushNotifications.removeAllListeners();
    }
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, BehaviorSubject } from 'rxjs';
import { environment } from '../../environments/environment';

export interface PushSubscriptionData {
  endpoint: string;
  keys: {
    p256dh: string;
    auth: string;
  };
}

export interface NotificationPayload {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  data?: any;
  actions?: Array<{
    action: string;
    title: string;
    icon?: string;
  }>;
  tag?: string;
  requireInteraction?: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class PushNotificationService {
  private subscription$ = new BehaviorSubject<PushSubscription | null>(null);
  private permission$ = new BehaviorSubject<NotificationPermission>('default');
  private vapidPublicKey = environment.vapidPublicKey || '';

  constructor(private http: HttpClient) {
    this.checkPermission();
  }

  /**
   * Check current notification permission
   */
  private checkPermission(): void {
    if ('Notification' in window) {
      this.permission$.next(Notification.permission);
    }
  }

  /**
   * Request notification permission from user
   */
  async requestPermission(): Promise<NotificationPermission> {
    if (!('Notification' in window)) {
      console.warn('This browser does not support notifications');
      return 'denied';
    }

    try {
      const permission = await Notification.requestPermission();
      this.permission$.next(permission);
      
      if (permission === 'granted') {
        await this.subscribeToPush();
      }
      
      return permission;
    } catch (error) {
      console.error('Error requesting notification permission:', error);
      return 'denied';
    }
  }

  /**
   * Subscribe to push notifications
   */
  async subscribeToPush(): Promise<PushSubscription | null> {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      console.warn('Push notifications not supported');
      return null;
    }

    try {
      const registration = await navigator.serviceWorker.ready;
      
      // Check if already subscribed
      let subscription = await registration.pushManager.getSubscription();
      
      if (!subscription) {
        // Subscribe to push
        const applicationServerKey = this.urlBase64ToUint8Array(this.vapidPublicKey);
        
        subscription = await registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: applicationServerKey as BufferSource
        });
      }

      // Send subscription to backend
      await this.sendSubscriptionToBackend(subscription);
      
      this.subscription$.next(subscription);
      return subscription;
    } catch (error) {
      console.error('Error subscribing to push:', error);
      return null;
    }
  }

  /**
   * Unsubscribe from push notifications
   */
  async unsubscribeFromPush(): Promise<boolean> {
    const subscription = this.subscription$.value;
    
    if (!subscription) {
      return false;
    }

    try {
      // Remove subscription from backend
      await this.removeSubscriptionFromBackend(subscription);
      
      // Unsubscribe from browser
      await subscription.unsubscribe();
      
      this.subscription$.next(null);
      return true;
    } catch (error) {
      console.error('Error unsubscribing from push:', error);
      return false;
    }
  }

  /**
   * Show local notification (doesn't require push)
   */
  async showNotification(payload: NotificationPayload): Promise<void> {
    if (!('Notification' in window)) {
      console.warn('Notifications not supported');
      return;
    }

    if (Notification.permission !== 'granted') {
      const permission = await this.requestPermission();
      if (permission !== 'granted') {
        return;
      }
    }

    try {
      const registration = await navigator.serviceWorker.ready;
      
      await registration.showNotification(payload.title, {
        body: payload.body,
        icon: payload.icon || '/assets/icons/icon-192x192.png',
        badge: payload.badge || '/assets/icons/icon-96x96.png',
        data: payload.data,
        actions: payload.actions,
        tag: payload.tag,
        requireInteraction: payload.requireInteraction || false,
        vibrate: [200, 100, 200],
        timestamp: Date.now()
      } as any);
    } catch (error) {
      console.error('Error showing notification:', error);
    }
  }

  /**
   * Get current subscription
   */
  getSubscription(): Observable<PushSubscription | null> {
    return this.subscription$.asObservable();
  }

  /**
   * Get current permission status
   */
  getPermission(): Observable<NotificationPermission> {
    return this.permission$.asObservable();
  }

  /**
   * Check if push notifications are supported
   */
  isSupported(): boolean {
    return 'Notification' in window && 
           'serviceWorker' in navigator && 
           'PushManager' in window;
  }

  /**
   * Send subscription to backend
   */
  private async sendSubscriptionToBackend(subscription: PushSubscription): Promise<void> {
    const subscriptionData = this.subscriptionToData(subscription);
    
    try {
      await this.http.post('/api/v1/push/subscribe', subscriptionData).toPromise();
    } catch (error) {
      console.error('Error sending subscription to backend:', error);
    }
  }

  /**
   * Remove subscription from backend
   */
  private async removeSubscriptionFromBackend(subscription: PushSubscription): Promise<void> {
    const subscriptionData = this.subscriptionToData(subscription);
    
    try {
      await this.http.post('/api/v1/push/unsubscribe', subscriptionData).toPromise();
    } catch (error) {
      console.error('Error removing subscription from backend:', error);
    }
  }

  /**
   * Convert subscription to data format for backend
   */
  private subscriptionToData(subscription: PushSubscription): PushSubscriptionData {
    const key = subscription.getKey('p256dh');
    const auth = subscription.getKey('auth');
    
    return {
      endpoint: subscription.endpoint,
      keys: {
        p256dh: key ? this.arrayBufferToBase64(key) : '',
        auth: auth ? this.arrayBufferToBase64(auth) : ''
      }
    };
  }

  /**
   * Convert URL-safe base64 to Uint8Array
   */
  private urlBase64ToUint8Array(base64String: string): Uint8Array {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding)
      .replace(/-/g, '+')
      .replace(/_/g, '/');

    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);

    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }

  /**
   * Convert ArrayBuffer to base64
   */
  private arrayBufferToBase64(buffer: ArrayBuffer): string {
    const bytes = new Uint8Array(buffer);
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return window.btoa(binary);
  }

  /**
   * Test notification (for debugging)
   */
  async testNotification(): Promise<void> {
    await this.showNotification({
      title: 'Test Notification',
      body: 'This is a test notification from CRM Immobilier',
      icon: '/assets/icons/icon-192x192.png',
      data: { test: true },
      actions: [
        {
          action: 'view',
          title: 'View'
        },
        {
          action: 'dismiss',
          title: 'Dismiss'
        }
      ]
    });
  }
}

