import { Injectable } from '@angular/core';

export interface PerformanceMetrics {
  // Core Web Vitals
  lcp?: number; // Largest Contentful Paint
  fid?: number; // First Input Delay
  cls?: number; // Cumulative Layout Shift
  
  // Additional metrics
  fcp?: number; // First Contentful Paint
  ttfb?: number; // Time to First Byte
  tti?: number; // Time to Interactive
  
  // Custom metrics
  bundleLoadTime?: number;
  apiResponseTime?: number;
  cacheHitRate?: number;
}

@Injectable({
  providedIn: 'root'
})
export class PerformanceMonitorService {
  private metrics: PerformanceMetrics = {};
  private cacheHits = 0;
  private cacheMisses = 0;

  constructor() {
    if ('PerformanceObserver' in window) {
      this.observeWebVitals();
    }
    
    this.measureNavigationTiming();
  }

  private observeWebVitals(): void {
    // Observe Largest Contentful Paint
    try {
      const lcpObserver = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        const lastEntry = entries[entries.length - 1];
        this.metrics.lcp = lastEntry.startTime;
        this.reportMetric('LCP', lastEntry.startTime);
      });
      lcpObserver.observe({ entryTypes: ['largest-contentful-paint'] });
    } catch (e) {
      console.warn('LCP observation not supported');
    }

    // Observe First Input Delay
    try {
      const fidObserver = new PerformanceObserver((list) => {
        const entries = list.getEntries() as any[];
        entries.forEach((entry) => {
          this.metrics.fid = entry.processingStart - entry.startTime;
          this.reportMetric('FID', this.metrics.fid);
        });
      });
      fidObserver.observe({ entryTypes: ['first-input'] });
    } catch (e) {
      console.warn('FID observation not supported');
    }

    // Observe Cumulative Layout Shift
    try {
      let clsValue = 0;
      const clsObserver = new PerformanceObserver((list) => {
        const entries = list.getEntries() as any[];
        entries.forEach((entry) => {
          if (!entry.hadRecentInput) {
            clsValue += entry.value;
          }
        });
        this.metrics.cls = clsValue;
        this.reportMetric('CLS', clsValue);
      });
      clsObserver.observe({ entryTypes: ['layout-shift'] });
    } catch (e) {
      console.warn('CLS observation not supported');
    }

    // Observe First Contentful Paint
    try {
      const fcpObserver = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        const fcpEntry = entries.find((entry) => entry.name === 'first-contentful-paint');
        if (fcpEntry) {
          this.metrics.fcp = fcpEntry.startTime;
          this.reportMetric('FCP', fcpEntry.startTime);
        }
      });
      fcpObserver.observe({ entryTypes: ['paint'] });
    } catch (e) {
      console.warn('FCP observation not supported');
    }
  }

  private measureNavigationTiming(): void {
    if (!('performance' in window) || !performance.timing) {
      return;
    }

    window.addEventListener('load', () => {
      setTimeout(() => {
        const timing = performance.timing;
        
        // Time to First Byte
        this.metrics.ttfb = timing.responseStart - timing.requestStart;
        this.reportMetric('TTFB', this.metrics.ttfb);
        
        // Page Load Time
        const pageLoadTime = timing.loadEventEnd - timing.navigationStart;
        this.reportMetric('PageLoad', pageLoadTime);
        
        // DOM Content Loaded
        const domContentLoaded = timing.domContentLoadedEventEnd - timing.navigationStart;
        this.reportMetric('DOMContentLoaded', domContentLoaded);
      }, 0);
    });
  }

  /**
   * Measure API response time
   */
  measureApiCall(url: string, startTime: number): void {
    const duration = performance.now() - startTime;
    
    if (!this.metrics.apiResponseTime) {
      this.metrics.apiResponseTime = duration;
    } else {
      // Running average
      this.metrics.apiResponseTime = (this.metrics.apiResponseTime + duration) / 2;
    }
    
    this.reportMetric('API', duration, { url });
  }

  /**
   * Track cache performance
   */
  recordCacheHit(): void {
    this.cacheHits++;
    this.updateCacheHitRate();
  }

  recordCacheMiss(): void {
    this.cacheMisses++;
    this.updateCacheHitRate();
  }

  private updateCacheHitRate(): void {
    const total = this.cacheHits + this.cacheMisses;
    if (total > 0) {
      this.metrics.cacheHitRate = (this.cacheHits / total) * 100;
      this.reportMetric('CacheHitRate', this.metrics.cacheHitRate);
    }
  }

  /**
   * Mark timing for custom metrics
   */
  mark(name: string): void {
    if ('performance' in window && performance.mark) {
      performance.mark(name);
    }
  }

  /**
   * Measure time between two marks
   */
  measure(name: string, startMark: string, endMark: string): number | null {
    if (!('performance' in window) || !performance.measure) {
      return null;
    }

    try {
      performance.measure(name, startMark, endMark);
      const measure = performance.getEntriesByName(name)[0];
      this.reportMetric(name, measure.duration);
      return measure.duration;
    } catch (e) {
      console.warn('Performance measurement failed:', e);
      return null;
    }
  }

  /**
   * Get all collected metrics
   */
  getMetrics(): PerformanceMetrics {
    return { ...this.metrics };
  }

  /**
   * Report metric to analytics
   */
  private reportMetric(name: string, value: number, metadata?: any): void {
    console.log(`[Performance] ${name}:`, value.toFixed(2), 'ms', metadata || '');
    
    // Send to analytics (Google Analytics, custom endpoint, etc.)
    if (window.gtag) {
      window.gtag('event', 'performance_metric', {
        event_category: 'Performance',
        event_label: name,
        value: Math.round(value),
        ...metadata
      });
    }

    // Send to custom analytics endpoint
    this.sendToAnalyticsEndpoint(name, value, metadata);
  }

  private sendToAnalyticsEndpoint(name: string, value: number, metadata?: any): void {
    // Optional: Send to custom backend analytics
    // Debounce and batch for efficiency
    const _payload = {
      metric: name,
      value,
      timestamp: Date.now(),
      url: window.location.href,
      userAgent: navigator.userAgent,
      ...metadata
    };

    // Example: send to backend
    // fetch('/api/v1/analytics/performance', {
    //   method: 'POST',
    //   headers: { 'Content-Type': 'application/json' },
    //   body: JSON.stringify(payload)
    // }).catch(() => {
    //   // Silent fail for analytics
    // });
  }

  /**
   * Get performance grade based on Core Web Vitals
   */
  getPerformanceGrade(): 'good' | 'needs-improvement' | 'poor' | 'unknown' {
    const { lcp, fid, cls } = this.metrics;

    if (!lcp || !fid || cls === undefined) {
      return 'unknown';
    }

    const lcpGood = lcp <= 2500;
    const fidGood = fid <= 100;
    const clsGood = cls <= 0.1;

    const lcpPoor = lcp > 4000;
    const fidPoor = fid > 300;
    const clsPoor = cls > 0.25;

    if (lcpGood && fidGood && clsGood) {
      return 'good';
    } else if (lcpPoor || fidPoor || clsPoor) {
      return 'poor';
    } else {
      return 'needs-improvement';
    }
  }

  /**
   * Get resource timing for lazy-loaded chunks
   */
  getChunkLoadTimes(): Array<{ name: string; duration: number }> {
    if (!('performance' in window) || !performance.getEntriesByType) {
      return [];
    }

    const resources = performance.getEntriesByType('resource') as PerformanceResourceTiming[];
    
    return resources
      .filter((resource) => resource.name.includes('.js') && resource.name.includes('chunk'))
      .map((resource) => ({
        name: resource.name.split('/').pop() || 'unknown',
        duration: resource.duration
      }));
  }

  /**
   * Monitor long tasks (> 50ms) that block the main thread
   */
  observeLongTasks(): void {
    if (!('PerformanceLongTaskTiming' in window)) {
      console.warn('Long Task API not supported');
      return;
    }

    try {
      const observer = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        entries.forEach((entry) => {
          console.warn('[Performance] Long task detected:', {
            duration: entry.duration,
            startTime: entry.startTime
          });
          
          this.reportMetric('LongTask', entry.duration);
        });
      });
      
      observer.observe({ entryTypes: ['longtask'] });
    } catch (e) {
      console.warn('Long task observation failed:', e);
    }
  }
}

import { Component, OnInit, OnDestroy, HostListener, ElementRef, input, output, viewChildren, computed } from '@angular/core';
import { CdkDragDrop, moveItemInArray, CdkDropList, CdkDrag, CdkDragHandle } from '@angular/cdk/drag-drop';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { ConfirmDeleteDialogComponent } from './confirm-delete-dialog.component';
import { MatIcon } from '@angular/material/icon';
import { MatIconButton } from '@angular/material/button';

export interface Photo {
  id: string | number;
  url: string;
  thumbnailUrl?: string;
  alt?: string;
  title?: string;
  width?: number;
  height?: number;
  blurDataUrl?: string;
}

@Component({
    selector: 'app-photo-gallery',
    templateUrl: './photo-gallery.component.html',
    styleUrls: ['./photo-gallery.component.css'],
    imports: [MatIcon, CdkDropList, CdkDrag, MatIconButton, CdkDragHandle]
})
export class PhotoGalleryComponent implements OnInit, OnDestroy {
  readonly photos = input<Photo[]>([]);
  readonly editable = input(false);
  readonly columns = input(3);
  
  readonly masonryColumns = computed(() => {
    const photos = this.photos();
    if (!photos || photos.length === 0) {
      return [];
    }

    const columnCount = this.getColumnCount();
    const columns: Photo[][] = Array.from({ length: columnCount }, () => []);

    photos.forEach((photo, index) => {
      const columnIndex = index % columnCount;
      columns[columnIndex].push(photo);
    });

    return columns;
  });

  readonly photosReordered = output<Photo[]>();
  readonly photoDeleted = output<Photo>();

  readonly photoImages = viewChildren<ElementRef<HTMLImageElement>>('photoImage');

  lightboxOpen = false;
  currentPhotoIndex = 0;
  lightboxZoom = 1;
  lightboxTranslateX = 0;
  lightboxTranslateY = 0;
  isDragging = false;
  dragStartX = 0;
  dragStartY = 0;
  dragStartTranslateX = 0;
  dragStartTranslateY = 0;

  private intersectionObserver?: IntersectionObserver;
  private keyboardListener?: (e: KeyboardEvent) => void;

  constructor(
    private dialog: MatDialog,
    private snackBar: MatSnackBar
  ) {}

  ngOnInit(): void {
    this.setupIntersectionObserver();
  }

  ngOnDestroy(): void {
    if (this.intersectionObserver) {
      this.intersectionObserver.disconnect();
    }
    this.removeLightboxKeyboardListener();
  }

  setupIntersectionObserver(): void {
    if (!('IntersectionObserver' in window)) {
      return;
    }

    this.intersectionObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const img = entry.target as HTMLImageElement;
            const dataSrc = img.getAttribute('data-src');
            if (dataSrc && !img.src) {
              img.src = dataSrc;
              img.classList.add('loading');
              img.onload = () => {
                img.classList.remove('loading');
                img.classList.add('loaded');
              };
              img.onerror = () => {
                img.classList.remove('loading');
                img.classList.add('error');
              };
            }
          }
        });
      },
      {
        rootMargin: '50px',
        threshold: 0.01
      }
    );

    setTimeout(() => {
      this.photoImages()?.forEach(imgRef => {
        this.intersectionObserver?.observe(imgRef.nativeElement);
      });
    }, 100);
  }



  getColumnCount(): number {
    if (window.innerWidth < 768) {
      return 2;
    } else if (window.innerWidth < 1024) {
      return Math.min(this.columns(), 3);
    }
    return this.columns();
  }

  openLightbox(index: number): void {
    this.currentPhotoIndex = index;
    this.lightboxOpen = true;
    this.lightboxZoom = 1;
    this.lightboxTranslateX = 0;
    this.lightboxTranslateY = 0;
    document.body.style.overflow = 'hidden';
    this.setupLightboxKeyboardListener();
  }

  closeLightbox(): void {
    this.lightboxOpen = false;
    this.lightboxZoom = 1;
    this.lightboxTranslateX = 0;
    this.lightboxTranslateY = 0;
    document.body.style.overflow = '';
    this.removeLightboxKeyboardListener();
  }

  previousPhoto(): void {
    if (this.currentPhotoIndex > 0) {
      this.currentPhotoIndex--;
      this.resetLightboxTransform();
    }
  }

  nextPhoto(): void {
    if (this.currentPhotoIndex < this.photos().length - 1) {
      this.currentPhotoIndex++;
      this.resetLightboxTransform();
    }
  }

  resetLightboxTransform(): void {
    this.lightboxZoom = 1;
    this.lightboxTranslateX = 0;
    this.lightboxTranslateY = 0;
  }

  zoomIn(): void {
    if (this.lightboxZoom < 3) {
      this.lightboxZoom += 0.25;
    }
  }

  zoomOut(): void {
    if (this.lightboxZoom > 0.5) {
      this.lightboxZoom -= 0.25;
      if (this.lightboxZoom === 1) {
        this.lightboxTranslateX = 0;
        this.lightboxTranslateY = 0;
      }
    }
  }

  resetZoom(): void {
    this.lightboxZoom = 1;
    this.lightboxTranslateX = 0;
    this.lightboxTranslateY = 0;
  }

  onLightboxImageMouseDown(event: MouseEvent): void {
    if (this.lightboxZoom > 1) {
      event.preventDefault();
      this.isDragging = true;
      this.dragStartX = event.clientX;
      this.dragStartY = event.clientY;
      this.dragStartTranslateX = this.lightboxTranslateX;
      this.dragStartTranslateY = this.lightboxTranslateY;
    }
  }

  @HostListener('document:mousemove', ['$event'])
  onMouseMove(event: MouseEvent): void {
    if (this.isDragging && this.lightboxZoom > 1) {
      const deltaX = event.clientX - this.dragStartX;
      const deltaY = event.clientY - this.dragStartY;
      this.lightboxTranslateX = this.dragStartTranslateX + deltaX;
      this.lightboxTranslateY = this.dragStartTranslateY + deltaY;
    }
  }

  @HostListener('document:mouseup')
  onMouseUp(): void {
    this.isDragging = false;
  }

  @HostListener('window:resize')
  onResize(): void {
    // Force re-render of masonry layout on window resize
  }

  setupLightboxKeyboardListener(): void {
    this.keyboardListener = (e: KeyboardEvent) => {
      switch (e.key) {
        case 'Escape':
          this.closeLightbox();
          break;
        case 'ArrowLeft':
          this.previousPhoto();
          break;
        case 'ArrowRight':
          this.nextPhoto();
          break;
        case '+':
        case '=':
          this.zoomIn();
          break;
        case '-':
        case '_':
          this.zoomOut();
          break;
        case '0':
          this.resetZoom();
          break;
      }
    };
    document.addEventListener('keydown', this.keyboardListener);
  }

  removeLightboxKeyboardListener(): void {
    if (this.keyboardListener) {
      document.removeEventListener('keydown', this.keyboardListener);
      this.keyboardListener = undefined;
    }
  }

  onDrop(event: CdkDragDrop<Photo[]>): void {
    if (!this.editable()) {
      return;
    }

    const photosCopy = [...this.photos()];
    moveItemInArray(photosCopy, event.previousIndex, event.currentIndex);
    
    this.photosReordered.emit(photosCopy);

    this.snackBar.open('Ordre des photos mis à jour', 'Fermer', {
      duration: 2000,
      panelClass: ['success-snackbar']
    });
  }

  deletePhoto(photo: Photo, event: Event): void {
    event.stopPropagation();

    const dialogRef = this.dialog.open(ConfirmDeleteDialogComponent, {
      width: '400px',
      data: {
        title: 'Supprimer la photo',
        message: photo.title 
          ? `Êtes-vous sûr de vouloir supprimer "${photo.title}" ?`
          : 'Êtes-vous sûr de vouloir supprimer cette photo ?'
      }
    });

    dialogRef.afterClosed().subscribe((confirmed: boolean) => {
      if (confirmed) {
        this.photoDeleted.emit(photo);
        this.snackBar.open('Photo supprimée avec succès', 'Fermer', {
          duration: 2000,
          panelClass: ['success-snackbar']
        });
      }
    });
  }

  goToThumbnail(index: number): void {
    this.currentPhotoIndex = index;
    this.resetLightboxTransform();
  }

  getCurrentPhoto(): Photo | null {
    return this.photos()[this.currentPhotoIndex] || null;
  }

  getSrcset(photo: Photo): string {
    if (!photo.width || !photo.height) {
      return '';
    }

    const baseUrl = photo.url;
    const sizes = [320, 640, 960, 1280, 1920];
    
    return sizes
      .filter(size => size <= (photo.width || 0))
      .map(size => {
        const scaledUrl = this.getScaledImageUrl(baseUrl, size);
        return `${scaledUrl} ${size}w`;
      })
      .join(', ');
  }

  getSizes(): string {
    return '(max-width: 768px) 50vw, (max-width: 1024px) 33vw, 25vw';
  }

  private getScaledImageUrl(url: string, width: number): string {
    if (url.includes('?')) {
      return `${url}&w=${width}`;
    }
    return `${url}?w=${width}`;
  }

  getThumbnailUrl(photo: Photo): string {
    return photo.thumbnailUrl || photo.url;
  }

  getBlurDataUrl(photo: Photo): string {
    return photo.blurDataUrl || this.generateDefaultBlurDataUrl();
  }

  private generateDefaultBlurDataUrl(): string {
    return 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"%3E%3Crect fill="%23e0e0e0" width="1" height="1"/%3E%3C/svg%3E';
  }

  trackByPhotoId(index: number, photo: Photo): string | number {
    return photo.id;
  }
}

import { Directive, ElementRef, EventEmitter, HostListener, Input, Output, OnDestroy } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import { Haptics, ImpactStyle } from '@capacitor/haptics';

export interface SwipeEvent {
  direction: 'left' | 'right' | 'up' | 'down';
  distance: number;
  velocity: number;
}

export interface PinchEvent {
  scale: number;
  centerX: number;
  centerY: number;
}

/**
 * Directive for mobile gesture handling
 * Provides swipe, long-press, pinch-zoom, and double-tap gestures
 */
@Directive({
  selector: '[appMobileGestures]',
  standalone: true
})
export class MobileGesturesDirective implements OnDestroy {
  @Input() swipeThreshold = 50; // pixels
  @Input() longPressDelay = 500; // ms
  @Input() doubleTapDelay = 300; // ms
  @Input() enableHaptics = true;
  @Input() preventContextMenu = true;

  @Output() swipe = new EventEmitter<SwipeEvent>();
  @Output() swipeLeft = new EventEmitter<SwipeEvent>();
  @Output() swipeRight = new EventEmitter<SwipeEvent>();
  @Output() swipeUp = new EventEmitter<SwipeEvent>();
  @Output() swipeDown = new EventEmitter<SwipeEvent>();
  @Output() longPress = new EventEmitter<TouchEvent>();
  @Output() doubleTap = new EventEmitter<TouchEvent>();
  @Output() pinch = new EventEmitter<PinchEvent>();

  private touchStartX = 0;
  private touchStartY = 0;
  private touchStartTime = 0;
  private lastTapTime = 0;
  private longPressTimer: any;
  private initialPinchDistance = 0;
  private isNative = Capacitor.isNativePlatform();

  constructor(private el: ElementRef) {
    if (this.preventContextMenu) {
      this.el.nativeElement.style.webkitTouchCallout = 'none';
      this.el.nativeElement.style.webkitUserSelect = 'none';
      this.el.nativeElement.style.userSelect = 'none';
    }
  }

  @HostListener('touchstart', ['$event'])
  onTouchStart(event: TouchEvent): void {
    if (event.touches.length === 1) {
      this.handleSingleTouchStart(event);
    } else if (event.touches.length === 2) {
      this.handlePinchStart(event);
    }
  }

  @HostListener('touchmove', ['$event'])
  onTouchMove(event: TouchEvent): void {
    if (event.touches.length === 2) {
      this.handlePinchMove(event);
    } else if (this.longPressTimer) {
      // Cancel long press if finger moves
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }
  }

  @HostListener('touchend', ['$event'])
  onTouchEnd(event: TouchEvent): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }

    if (event.changedTouches.length === 1) {
      this.handleSingleTouchEnd(event);
    }

    this.initialPinchDistance = 0;
  }

  @HostListener('touchcancel')
  onTouchCancel(): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }
    this.initialPinchDistance = 0;
  }

  @HostListener('contextmenu', ['$event'])
  onContextMenu(event: Event): void {
    if (this.preventContextMenu) {
      event.preventDefault();
      return;
    }
  }

  private handleSingleTouchStart(event: TouchEvent): void {
    const touch = event.touches[0];
    this.touchStartX = touch.clientX;
    this.touchStartY = touch.clientY;
    this.touchStartTime = Date.now();

    // Setup long press detection
    this.longPressTimer = setTimeout(() => {
      this.handleLongPress(event);
    }, this.longPressDelay);
  }

  private handleSingleTouchEnd(event: TouchEvent): void {
    const touch = event.changedTouches[0];
    const touchEndX = touch.clientX;
    const touchEndY = touch.clientY;
    const touchEndTime = Date.now();

    const deltaX = touchEndX - this.touchStartX;
    const deltaY = touchEndY - this.touchStartY;
    const deltaTime = touchEndTime - this.touchStartTime;
    const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);

    // Check for swipe
    if (distance > this.swipeThreshold && deltaTime < 1000) {
      this.handleSwipe(deltaX, deltaY, distance, deltaTime);
      return;
    }

    // Check for double tap
    const timeSinceLastTap = touchEndTime - this.lastTapTime;
    if (timeSinceLastTap < this.doubleTapDelay && distance < 10) {
      this.handleDoubleTap(event);
      this.lastTapTime = 0;
    } else {
      this.lastTapTime = touchEndTime;
    }
  }

  private handleSwipe(deltaX: number, deltaY: number, distance: number, deltaTime: number): void {
    const velocity = distance / deltaTime;
    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);

    let direction: 'left' | 'right' | 'up' | 'down';

    if (absX > absY) {
      direction = deltaX > 0 ? 'right' : 'left';
    } else {
      direction = deltaY > 0 ? 'down' : 'up';
    }

    const swipeEvent: SwipeEvent = { direction, distance, velocity };

    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Light });
    }

    this.swipe.emit(swipeEvent);

    switch (direction) {
      case 'left':
        this.swipeLeft.emit(swipeEvent);
        break;
      case 'right':
        this.swipeRight.emit(swipeEvent);
        break;
      case 'up':
        this.swipeUp.emit(swipeEvent);
        break;
      case 'down':
        this.swipeDown.emit(swipeEvent);
        break;
    }
  }

  private handleLongPress(event: TouchEvent): void {
    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Medium });
    }

    this.longPress.emit(event);
    this.longPressTimer = null;
  }

  private handleDoubleTap(event: TouchEvent): void {
    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Light });
    }

    this.doubleTap.emit(event);
  }

  private handlePinchStart(event: TouchEvent): void {
    const touch1 = event.touches[0];
    const touch2 = event.touches[1];
    
    this.initialPinchDistance = this.getDistance(
      touch1.clientX, touch1.clientY,
      touch2.clientX, touch2.clientY
    );
  }

  private handlePinchMove(event: TouchEvent): void {
    if (this.initialPinchDistance === 0) {
      return;
    }

    event.preventDefault();

    const touch1 = event.touches[0];
    const touch2 = event.touches[1];
    
    const currentDistance = this.getDistance(
      touch1.clientX, touch1.clientY,
      touch2.clientX, touch2.clientY
    );

    const scale = currentDistance / this.initialPinchDistance;
    const centerX = (touch1.clientX + touch2.clientX) / 2;
    const centerY = (touch1.clientY + touch2.clientY) / 2;

    this.pinch.emit({ scale, centerX, centerY });
  }

  private getDistance(x1: number, y1: number, x2: number, y2: number): number {
    const dx = x2 - x1;
    const dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  ngOnDestroy(): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
    }
  }
}

import { Injectable } from '@angular/core';

export interface LinearRegressionResult {
  slope: number;
  intercept: number;
  rSquared: number;
  predictions: number[];
}

export interface PipelineForecast {
  date: string;
  predictedValue: number;
  confidence: number;
  upperBound: number;
  lowerBound: number;
}

export interface CloseProbability {
  dossierId: number;
  probability: number;
  factors: {
    responseTime: number;
    stageProgression: number;
    engagement: number;
    source: number;
  };
  recommendation: string;
}

@Injectable({
  providedIn: 'root'
})
export class PredictiveAnalyticsService {

  constructor() { /* no-op */ }

  performLinearRegression(xValues: number[], yValues: number[]): LinearRegressionResult {
    if (xValues.length !== yValues.length || xValues.length === 0) {
      throw new Error('Invalid input data for regression');
    }

    const n = xValues.length;
    const sumX = xValues.reduce((a, b) => a + b, 0);
    const sumY = yValues.reduce((a, b) => a + b, 0);
    const sumXY = xValues.reduce((sum, x, i) => sum + x * yValues[i], 0);
    const sumXX = xValues.reduce((sum, x) => sum + x * x, 0);

    const slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    const predictions = xValues.map(x => slope * x + intercept);
    const meanY = sumY / n;
    const ssTotal = yValues.reduce((sum, y) => sum + Math.pow(y - meanY, 2), 0);
    const ssResidual = yValues.reduce((sum, y, i) => sum + Math.pow(y - predictions[i], 2), 0);
    const rSquared = 1 - (ssResidual / ssTotal);

    return { slope, intercept, rSquared, predictions };
  }

  forecastPipelineValue(historicalData: { date: string; value: number }[], daysAhead: number): PipelineForecast[] {
    if (historicalData.length < 2) {
      return [];
    }

    const xValues = historicalData.map((_, i) => i);
    const yValues = historicalData.map(d => d.value);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const stdDev = this.calculateStdDev(yValues, regression.predictions.slice(0, yValues.length));
    
    const forecasts: PipelineForecast[] = [];
    const lastDate = new Date(historicalData[historicalData.length - 1].date);

    for (let i = 1; i <= daysAhead; i++) {
      const xValue = historicalData.length + i - 1;
      const predictedValue = regression.slope * xValue + regression.intercept;
      
      const confidence = Math.max(0, Math.min(100, regression.rSquared * 100));
      
      const forecastDate = new Date(lastDate);
      forecastDate.setDate(lastDate.getDate() + i);

      const uncertaintyFactor = Math.sqrt(i);
      forecasts.push({
        date: forecastDate.toISOString().split('T')[0],
        predictedValue: Math.max(0, predictedValue),
        confidence,
        upperBound: Math.max(0, predictedValue + stdDev * uncertaintyFactor),
        lowerBound: Math.max(0, predictedValue - stdDev * uncertaintyFactor)
      });
    }

    return forecasts;
  }

  calculateCloseProbability(dossier: {
    id: number;
    averageResponseTimeHours: number;
    daysInCurrentStage: number;
    messageCount: number;
    appointmentCount: number;
    source: string;
    status: string;
  }): CloseProbability {
    let probability = 50;

    const responseTimeFactor = this.scoreResponseTime(dossier.averageResponseTimeHours);
    const stageProgressionFactor = this.scoreStageProgression(dossier.status, dossier.daysInCurrentStage);
    const engagementFactor = this.scoreEngagement(dossier.messageCount, dossier.appointmentCount);
    const sourceFactor = this.scoreSource(dossier.source);

    probability += responseTimeFactor * 0.25;
    probability += stageProgressionFactor * 0.30;
    probability += engagementFactor * 0.30;
    probability += sourceFactor * 0.15;

    probability = Math.max(0, Math.min(100, probability));

    const recommendation = this.generateRecommendation(probability, {
      responseTimeFactor,
      stageProgressionFactor,
      engagementFactor,
      sourceFactor
    });

    return {
      dossierId: dossier.id,
      probability,
      factors: {
        responseTime: responseTimeFactor,
        stageProgression: stageProgressionFactor,
        engagement: engagementFactor,
        source: sourceFactor
      },
      recommendation
    };
  }

  private calculateStdDev(actual: number[], predicted: number[]): number {
    const residuals = actual.map((y, i) => y - predicted[i]);
    const sumSquaredResiduals = residuals.reduce((sum, r) => sum + r * r, 0);
    return Math.sqrt(sumSquaredResiduals / actual.length);
  }

  private scoreResponseTime(avgResponseTimeHours: number): number {
    if (avgResponseTimeHours <= 1) return 20;
    if (avgResponseTimeHours <= 4) return 10;
    if (avgResponseTimeHours <= 24) return 0;
    if (avgResponseTimeHours <= 48) return -10;
    return -20;
  }

  private scoreStageProgression(status: string, daysInStage: number): number {
    const stageWeights: Record<string, number> = {
      'NEW': 0,
      'QUALIFYING': 10,
      'QUALIFIED': 20,
      'APPOINTMENT': 30,
      'PROPOSAL': 35,
      'NEGOTIATION': 40,
      'WON': 50,
      'LOST': -50
    };

    let score = stageWeights[status] || 0;

    if (daysInStage > 30) {
      score -= 15;
    } else if (daysInStage > 14) {
      score -= 10;
    } else if (daysInStage > 7) {
      score -= 5;
    }

    return score;
  }

  private scoreEngagement(messageCount: number, appointmentCount: number): number {
    let score = 0;

    if (messageCount > 10) {
      score += 20;
    } else if (messageCount > 5) {
      score += 15;
    } else if (messageCount > 2) {
      score += 10;
    } else if (messageCount > 0) {
      score += 5;
    }

    if (appointmentCount > 2) {
      score += 15;
    } else if (appointmentCount > 1) {
      score += 10;
    } else if (appointmentCount > 0) {
      score += 5;
    }

    return score;
  }

  private scoreSource(source: string): number {
    const sourceWeights: Record<string, number> = {
      'REFERRAL': 15,
      'WEBSITE': 10,
      'SOCIAL_MEDIA': 5,
      'PHONE': 5,
      'EMAIL': 3,
      'WALK_IN': 0,
      'OTHER': 0
    };

    return sourceWeights[source] || 0;
  }

  private generateRecommendation(probability: number, factors: any): string {
    if (probability >= 80) {
      return 'High probability - Schedule final negotiation';
    } else if (probability >= 60) {
      return 'Good probability - Continue nurturing with regular follow-ups';
    } else if (probability >= 40) {
      if (factors.responseTimeFactor < 0) {
        return 'Medium probability - Improve response time to increase chances';
      } else if (factors.engagementFactor < 5) {
        return 'Medium probability - Increase engagement through appointments';
      } else {
        return 'Medium probability - Address any concerns and provide additional value';
      }
    } else if (probability >= 20) {
      return 'Low probability - Re-qualify lead and adjust strategy';
    } else {
      return 'Very low probability - Consider reassigning or archiving';
    }
  }

  calculateTeamPerformanceTrend(
    performanceData: { date: string; metric: number }[],
    _metricName: string
  ): { trend: 'improving' | 'declining' | 'stable'; changeRate: number } {
    if (performanceData.length < 2) {
      return { trend: 'stable', changeRate: 0 };
    }

    const xValues = performanceData.map((_, i) => i);
    const yValues = performanceData.map(d => d.metric);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const avgMetric = yValues.reduce((a, b) => a + b, 0) / yValues.length;
    const changeRate = avgMetric !== 0 ? (regression.slope / avgMetric) * 100 : 0;

    let trend: 'improving' | 'declining' | 'stable';
    if (changeRate > 5) {
      trend = 'improving';
    } else if (changeRate < -5) {
      trend = 'declining';
    } else {
      trend = 'stable';
    }

    return { trend, changeRate };
  }

  predictMarketTrend(
    historicalPrices: { date: string; avgPrice: number }[],
    forecastMonths: number
  ): { date: string; predictedPrice: number; confidence: number }[] {
    if (historicalPrices.length < 3) {
      return [];
    }

    const xValues = historicalPrices.map((_, i) => i);
    const yValues = historicalPrices.map(d => d.avgPrice);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const predictions: { date: string; predictedPrice: number; confidence: number }[] = [];
    const lastDate = new Date(historicalPrices[historicalPrices.length - 1].date);

    for (let i = 1; i <= forecastMonths; i++) {
      const xValue = historicalPrices.length + i - 1;
      const predictedPrice = regression.slope * xValue + regression.intercept;
      
      const forecastDate = new Date(lastDate);
      forecastDate.setMonth(lastDate.getMonth() + i);

      const confidence = Math.max(0, Math.min(100, regression.rSquared * 100 * (1 - i * 0.05)));

      predictions.push({
        date: forecastDate.toISOString().split('T')[0],
        predictedPrice: Math.max(0, predictedPrice),
        confidence
      });
    }

    return predictions;
  }
}

