          agent.closedDossiers.toString(),
          `${(agent.conversionRate * 100).toFixed(2)}%`,
          agent.averageResponseTimeHours.toFixed(2)
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });

      yPosition = (doc as any).lastAutoTable.finalY + 15;
    }

    if (data.leadSources && data.leadSources.length > 0) {
      if (yPosition > 250) {
        doc.addPage();
        yPosition = 20;
      }

      doc.setFontSize(14);
      doc.text('Lead Sources', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Source', 'Count', 'Percentage', 'Conversion Rate']],
        body: data.leadSources.map(source => [
          source.source,
          source.count.toString(),
          `${source.percentage.toFixed(2)}%`,
          `${(source.conversionRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });

      yPosition = (doc as any).lastAutoTable.finalY + 15;
    }

    if (data.conversionFunnel && data.conversionFunnel.length > 0) {
      if (yPosition > 250) {
        doc.addPage();
        yPosition = 20;
      }

      doc.setFontSize(14);
      doc.text('Conversion Funnel', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Stage', 'Count', 'Conversion Rate', 'Drop-off Rate']],
        body: data.conversionFunnel.map(stage => [
          stage.stage,
          stage.count.toString(),
          `${(stage.conversionRate * 100).toFixed(2)}%`,
          `${(stage.dropOffRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });
    }

    doc.save(filename);
  }

  /**
   * Export analytics data to CSV using lazy-loaded PapaParse library.
   *
   * The PapaParse library (~100KB) is loaded on-demand to avoid bloating
   * the initial bundle.
   *
   * @param data - Analytics data to export
   * @param filename - Name of the CSV file (default: 'analytics-report.csv')
   * @returns Promise that resolves when the CSV is downloaded
   *
   * @example
   * ```typescript
   * const data = await this.reportingService.getAnalyticsData().toPromise();
   * await this.reportingService.exportAnalyticsToCSV(data, 'my-report.csv');
   * ```
   */
  async exportAnalyticsToCSV(data: AnalyticsData, filename = 'analytics-report.csv'): Promise<void> {
    const Papa = await import('papaparse');

    const csvSections: string[] = [];

    csvSections.push(`Analytics Report - Date Range: ${data.dateRange.from} to ${data.dateRange.to}\n`);

    if (data.agentPerformance && data.agentPerformance.length > 0) {
      csvSections.push('\nAgent Performance');
      const agentData = data.agentPerformance.map(agent => ({
        'Agent Name': agent.agentName,
        'Total Dossiers': agent.totalDossiers,
        'Closed Dossiers': agent.closedDossiers,
        'Conversion Rate': `${(agent.conversionRate * 100).toFixed(2)}%`,
        'Avg Response Time (hrs)': agent.averageResponseTimeHours.toFixed(2)
      }));
      csvSections.push(Papa.unparse(agentData));
    }

    if (data.leadSources && data.leadSources.length > 0) {
      csvSections.push('\n\nLead Sources');
      const leadSourceData = data.leadSources.map(source => ({
        'Source': source.source,
        'Count': source.count,
        'Percentage': `${source.percentage.toFixed(2)}%`,
        'Conversion Rate': `${(source.conversionRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(leadSourceData));
    }

    if (data.conversionFunnel && data.conversionFunnel.length > 0) {
      csvSections.push('\n\nConversion Funnel');
      const funnelData = data.conversionFunnel.map(stage => ({
        'Stage': stage.stage,
        'Count': stage.count,
        'Conversion Rate': `${(stage.conversionRate * 100).toFixed(2)}%`,
        'Drop-off Rate': `${(stage.dropOffRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(funnelData));
    }

    if (data.revenueForecast && data.revenueForecast.length > 0) {
      csvSections.push('\n\nRevenue Forecast');
      const forecastData = data.revenueForecast.map(forecast => ({
        'Date': forecast.date,
        'Estimated Revenue': forecast.estimatedRevenue,
        'Actual Revenue': forecast.actualRevenue,
        'Pipeline Value': forecast.pipelineValue
      }));
      csvSections.push(Papa.unparse(forecastData));
    }

    const csvContent = csvSections.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }

  /**
   * Export KPI report data to PDF using lazy-loaded jsPDF library.
   *
   * @param data - KPI report data to export
   * @param filename - Name of the PDF file (default: 'kpi-report.pdf')
   * @returns Promise that resolves when the PDF is downloaded
   */
  async exportKpiReportToPDF(data: KpiReportResponse, filename = 'kpi-report.pdf'): Promise<void> {
    const [jsPDFModule] = await Promise.all([
      import('jspdf'),
      import('jspdf-autotable')
    ]);

    const { jsPDF: JsPDFClass } = jsPDFModule;
    const doc = new JsPDFClass();

    doc.setFontSize(18);
    doc.text('KPI Report', 14, 20);

    let yPosition = 35;

    doc.setFontSize(12);
    doc.text('Key Metrics', 14, yPosition);
    yPosition += 8;

    doc.setFontSize(10);
    doc.text(`Average Response Time: ${data.averageResponseTimeHours.toFixed(2)} hours`, 14, yPosition);
    yPosition += 6;
    doc.text(`Appointment Show Rate: ${(data.appointmentShowRate * 100).toFixed(2)}%`, 14, yPosition);
    yPosition += 6;
    doc.text(`Pipeline Velocity: ${data.pipelineVelocityDays.toFixed(2)} days`, 14, yPosition);
    yPosition += 15;

    if (data.conversionRateBySource && data.conversionRateBySource.length > 0) {
      doc.setFontSize(12);
      doc.text('Conversion Rate by Source', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Source', 'Total Dossiers', 'Won Dossiers', 'Conversion Rate']],
        body: data.conversionRateBySource.map(item => [
          item.source,
          item.totalDossiers.toString(),
          item.wonDossiers.toString(),
          `${(item.conversionRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });
    }

    doc.save(filename);
  }

  /**
   * Export KPI report data to CSV using lazy-loaded PapaParse library.
   *
   * @param data - KPI report data to export
   * @param filename - Name of the CSV file (default: 'kpi-report.csv')
   * @returns Promise that resolves when the CSV is downloaded
   */
  async exportKpiReportToCSV(data: KpiReportResponse, filename = 'kpi-report.csv'): Promise<void> {
    const Papa = await import('papaparse');

    const csvSections: string[] = [];

    csvSections.push('KPI Report\n');
    csvSections.push(`Average Response Time (hours),${data.averageResponseTimeHours.toFixed(2)}`);
    csvSections.push(`Appointment Show Rate,${(data.appointmentShowRate * 100).toFixed(2)}%`);
    csvSections.push(`Pipeline Velocity (days),${data.pipelineVelocityDays.toFixed(2)}`);

    if (data.conversionRateBySource && data.conversionRateBySource.length > 0) {
      csvSections.push('\n\nConversion Rate by Source');
      const conversionData = data.conversionRateBySource.map(item => ({
        'Source': item.source,
        'Total Dossiers': item.totalDossiers,
        'Won Dossiers': item.wonDossiers,
        'Conversion Rate': `${(item.conversionRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(conversionData));
    }

    if (data.dossierCreationTimeSeries && data.dossierCreationTimeSeries.length > 0) {
      csvSections.push('\n\nDossier Creation Time Series');
      csvSections.push(Papa.unparse(data.dossierCreationTimeSeries));
    }

    if (data.conversionTimeSeries && data.conversionTimeSeries.length > 0) {
      csvSections.push('\n\nConversion Time Series');
      csvSections.push(Papa.unparse(data.conversionTimeSeries));
    }

    const csvContent = csvSections.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }
}

import { Injectable } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import { App, AppState } from '@capacitor/app';
import { Device, DeviceInfo } from '@capacitor/device';
import { Network, ConnectionStatus } from '@capacitor/network';
import { StatusBar, Style } from '@capacitor/status-bar';
import { SplashScreen } from '@capacitor/splash-screen';
import { Keyboard, KeyboardInfo } from '@capacitor/keyboard';
import { Haptics, ImpactStyle } from '@capacitor/haptics';
import { ScreenReader } from '@capacitor/screen-reader';
import { Share, ShareOptions } from '@capacitor/share';
import { Browser } from '@capacitor/browser';
import { BehaviorSubject, from, Observable, of, Subject } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface PlatformInfo {
  isNative: boolean;
  platform: 'ios' | 'android' | 'web';
  deviceInfo: DeviceInfo | null;
}

/**
 * Service for native platform capabilities
 * Provides unified interface for device features
 */
@Injectable({
  providedIn: 'root'
})
export class NativePlatformService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();
  private readonly platform = Capacitor.getPlatform();

  private readonly networkStatusSubject = new BehaviorSubject<ConnectionStatus | null>(null);
  private readonly appStateSubject = new BehaviorSubject<AppState | null>(null);
  private readonly keyboardSubject = new Subject<KeyboardInfo>();
  private readonly backButtonSubject = new Subject<void>();

  public readonly networkStatus$ = this.networkStatusSubject.asObservable();
  public readonly appState$ = this.appStateSubject.asObservable();
  public readonly keyboard$ = this.keyboardSubject.asObservable();
  public readonly backButton$ = this.backButtonSubject.asObservable();

  constructor() {
    if (this.isNativePlatform) {
      this.initializePlatformListeners();
    }
  }

  /**
   * Initialize platform event listeners
   */
  private async initializePlatformListeners(): Promise<void> {
    // Network status
    Network.addListener('networkStatusChange', (status) => {
      this.networkStatusSubject.next(status);
    });

    const initialNetwork = await Network.getStatus();
    this.networkStatusSubject.next(initialNetwork);

    // App state changes
    App.addListener('appStateChange', (state) => {
      this.appStateSubject.next(state);
    });

    // Keyboard events
    Keyboard.addListener('keyboardWillShow', (info) => {
      this.keyboardSubject.next(info);
    });

    Keyboard.addListener('keyboardDidShow', (info) => {
      this.keyboardSubject.next(info);
    });

    // Hardware back button (Android)
    App.addListener('backButton', () => {
      this.backButtonSubject.next();
    });

    // Deep link handling
    App.addListener('appUrlOpen', (event) => {
      this.handleDeepLink(event.url);
    });
  }

  /**
   * Get platform information
   */
  getPlatformInfo(): Observable<PlatformInfo> {
    if (!this.isNativePlatform) {
      return of({
        isNative: false,
        platform: 'web',
        deviceInfo: null
      });
    }

    return from(Device.getInfo()).pipe(
      map((deviceInfo) => ({
        isNative: true,
        platform: this.platform as 'ios' | 'android',
        deviceInfo
      })),
      catchError(() => of({
        isNative: true,
        platform: this.platform as 'ios' | 'android',
        deviceInfo: null
      }))
    );
  }

  /**
   * Get device info
   */
  getDeviceInfo(): Observable<DeviceInfo | null> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    return from(Device.getInfo()).pipe(
      catchError(() => of(null))
    );
  }

  /**
   * Get device ID
   */
  getDeviceId(): Observable<string | null> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    return from(Device.getId()).pipe(
      map((result) => result.identifier),
      catchError(() => of(null))
    );
  }

  /**
   * Get battery info
   */
  getBatteryInfo(): Observable<any> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    return from(Device.getBatteryInfo()).pipe(
      catchError(() => of(null))
    );
  }

  /**
   * Check if device is online
   */
  isOnline(): boolean {
    return this.networkStatusSubject.value?.connected ?? true;
  }

  /**
   * Get network status
   */
  getNetworkStatus(): Observable<ConnectionStatus> {
    if (!this.isNativePlatform) {
      return of({ connected: true, connectionType: 'wifi' });
    }

    return from(Network.getStatus());
  }

  /**
   * Hide splash screen
   */
  hideSplashScreen(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(SplashScreen.hide()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Show splash screen
   */
  showSplashScreen(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(SplashScreen.show()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Set status bar style
   */
  setStatusBarStyle(style: Style, backgroundColor?: string): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(
      Promise.all([
        StatusBar.setStyle({ style }),
        backgroundColor ? StatusBar.setBackgroundColor({ color: backgroundColor }) : Promise.resolve()
      ])
    ).pipe(
      map(() => undefined),
      catchError(() => of(undefined))
    );
  }

  /**
   * Hide status bar
   */
  hideStatusBar(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(StatusBar.hide()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Show status bar
   */
  showStatusBar(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(StatusBar.show()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Hide keyboard
   */
  hideKeyboard(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Keyboard.hide()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Show keyboard
   */
  showKeyboard(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Keyboard.show()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Trigger haptic feedback
   */
  hapticImpact(style: ImpactStyle = ImpactStyle.Medium): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Haptics.impact({ style })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Trigger haptic notification
   */
  hapticNotification(type: 'SUCCESS' | 'WARNING' | 'ERROR'): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Haptics.notification({ type: type as any })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Trigger haptic vibration
   */
  hapticVibrate(duration = 300): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Haptics.vibrate({ duration })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Check if screen reader is enabled
   */
  isScreenReaderEnabled(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(ScreenReader.isEnabled()).pipe(
      map((result) => result.value),
      catchError(() => of(false))
    );
  }

  /**
   * Speak text using screen reader
   */
  speak(text: string): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(ScreenReader.speak({ value: text })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Share content
   */
  share(options: ShareOptions): Observable<boolean> {
    if (!this.isNativePlatform) {
      // Fallback to Web Share API
      if (navigator.share) {
        return from(navigator.share({
          title: options.title,
          text: options.text,
          url: options.url
        })).pipe(
          map(() => true),
          catchError(() => of(false))
        );
      }
      return of(false);
    }

    return from(Share.share(options)).pipe(
      map(() => true),
      catchError(() => of(false))
    );
  }

  /**
   * Open URL in browser
   */
  openUrl(url: string): Observable<void> {
    if (!this.isNativePlatform) {
      window.open(url, '_blank');
      return of(undefined);
    }

    return from(Browser.open({ url })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Close browser
   */
  closeBrowser(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Browser.close()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Exit app (Android only)
   */
  exitApp(): void {
    if (this.isNativePlatform) {
      App.exitApp();
    }
  }

  /**
   * Get app info
   */
  getAppInfo(): Observable<any> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    return from(App.getInfo()).pipe(
      catchError(() => of(null))
    );
  }

  /**
   * Handle deep links
   */
  private handleDeepLink(url: string): void {
    console.log('Deep link opened:', url);

    // Parse WhatsApp callback URLs
    if (url.includes('atlasimmo://whatsapp/callback')) {
      const urlParams = new URLSearchParams(url.split('?')[1]);
      const code = urlParams.get('code');
      const state = urlParams.get('state');

      // Dispatch event for WhatsApp callback handling
      window.dispatchEvent(new CustomEvent('whatsapp-callback', {
        detail: { code, state }
      }));
    }

    // Handle other deep link patterns
    if (url.includes('atlasimmo://dossiers/')) {
      const dossierId = url.split('dossiers/')[1]?.split('?')[0];
      if (dossierId) {
        window.location.href = `/dossiers/${dossierId}`;
      }
    }
  }

  /**
   * Check if running on iOS
   */
  isIOS(): boolean {
    return this.platform === 'ios';
  }

  /**
   * Check if running on Android
   */
  isAndroid(): boolean {
    return this.platform === 'android';
  }

  /**
   * Check if running on web
   */
  isWeb(): boolean {
    return this.platform === 'web';
  }

  /**
   * Clean up listeners
   */
  removeAllListeners(): void {
    if (this.isNativePlatform) {
      Network.removeAllListeners();
      App.removeAllListeners();
      Keyboard.removeAllListeners();
    }
  }
}

