import { Injectable } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import {
  PushNotifications,
  PushNotificationSchema,
  ActionPerformed,
  Token
} from '@capacitor/push-notifications';
import { BehaviorSubject, from, Observable, of, Subject } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface PushNotificationPermission {
  granted: boolean;
  denied: boolean;
}

export interface NotificationPayload {
  title: string;
  body: string;
  data?: any;
  badge?: number;
  sound?: string;
  channelId?: string;
}

/**
 * Service for native push notifications
 * Handles FCM (Android) and APNs (iOS) push notifications
 */
@Injectable({
  providedIn: 'root'
})
export class NativePushNotificationsService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();

  private readonly tokenSubject = new BehaviorSubject<string | null>(null);
  private readonly notificationReceivedSubject = new Subject<PushNotificationSchema>();
  private readonly notificationActionSubject = new Subject<ActionPerformed>();

  public readonly token$ = this.tokenSubject.asObservable();
  public readonly notificationReceived$ = this.notificationReceivedSubject.asObservable();
  public readonly notificationAction$ = this.notificationActionSubject.asObservable();

  constructor() {
    if (this.isNativePlatform) {
      this.initializePushNotifications();
    }
  }

  /**
   * Initialize push notification listeners
   */
  private initializePushNotifications(): void {
    // Registration success
    PushNotifications.addListener('registration', (token: Token) => {
      console.log('Push registration success, token:', token.value);
      this.tokenSubject.next(token.value);
    });

    // Registration error
    PushNotifications.addListener('registrationError', (error: any) => {
      console.error('Push registration error:', error);
      this.tokenSubject.next(null);
    });

    // Notification received (app in foreground)
    PushNotifications.addListener('pushNotificationReceived',
      (notification: PushNotificationSchema) => {
        console.log('Push notification received:', notification);
        this.notificationReceivedSubject.next(notification);
      }
    );

    // Notification action performed (user tapped)
    PushNotifications.addListener('pushNotificationActionPerformed',
      (notification: ActionPerformed) => {
        console.log('Push notification action performed:', notification);
        this.notificationActionSubject.next(notification);
      }
    );
  }

  /**
   * Request push notification permissions
   */
  requestPermissions(): Observable<PushNotificationPermission> {
    if (!this.isNativePlatform) {
      return of({ granted: false, denied: true });
    }

    return from(PushNotifications.requestPermissions()).pipe(
      map((result) => ({
        granted: result.receive === 'granted',
        denied: result.receive === 'denied'
      })),
      catchError((error) => {
        console.error('Error requesting push notification permissions:', error);
        return of({ granted: false, denied: true });
      })
    );
  }

  /**
   * Check current push notification permissions
   */
  checkPermissions(): Observable<PushNotificationPermission> {
    if (!this.isNativePlatform) {
      return of({ granted: false, denied: true });
    }

    return from(PushNotifications.checkPermissions()).pipe(
      map((result) => ({
        granted: result.receive === 'granted',
        denied: result.receive === 'denied'
      })),
      catchError(() => of({ granted: false, denied: true }))
    );
  }

  /**
   * Register for push notifications
   */
  register(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.register()).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error registering for push notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Get the current push notification token
   */
  getToken(): string | null {
    return this.tokenSubject.value;
  }

  /**
   * Get delivered notifications (iOS only)
   */
  getDeliveredNotifications(): Observable<PushNotificationSchema[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(PushNotifications.getDeliveredNotifications()).pipe(
      map((result) => result.notifications),
      catchError(() => of([]))
    );
  }

  /**
   * Remove delivered notifications
   */
  removeDeliveredNotifications(notificationIds: string[]): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.removeDeliveredNotifications({
      notifications: notificationIds.map(id => ({ id } as any))
    })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error removing delivered notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Remove all delivered notifications
   */
  removeAllDeliveredNotifications(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.removeAllDeliveredNotifications()).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error removing all delivered notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Create notification channel (Android only)
   */
  createChannel(
    id: string,
    name: string,
    importance: 1 | 2 | 3 | 4 | 5 = 3,
    description?: string,
    sound?: string,
    vibration = true,
    lights = true
  ): Observable<boolean> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of(false);
    }

    return from(PushNotifications.createChannel({
      id,
      name,
      importance,
      description,
      sound,
      vibration,
      lights
    })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error creating notification channel:', error);
        return of(false);
      })
    );
  }

  /**
   * Delete notification channel (Android only)
   */
  deleteChannel(channelId: string): Observable<boolean> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of(false);
    }

    return from(PushNotifications.deleteChannel({ id: channelId })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error deleting notification channel:', error);
        return of(false);
      })
    );
  }

  /**
   * List notification channels (Android only)
   */
  listChannels(): Observable<any[]> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of([]);
    }

    return from(PushNotifications.listChannels()).pipe(
      map((result) => result.channels),
      catchError(() => of([]))
    );
  }

  /**
   * Initialize default notification channels (Android)
   */
  initializeDefaultChannels(): void {
    if (Capacitor.getPlatform() === 'android') {
      this.createChannel(
        'messages',
        'Messages',
        5,
        'Notifications pour les nouveaux messages',
        'default',
        true,
        true
      ).subscribe();

      this.createChannel(
        'appointments',
        'Rendez-vous',
        4,
        'Rappels de rendez-vous',
        'default',
        true,
        false
      ).subscribe();

      this.createChannel(
        'updates',
        'Mises à jour',
        3,
        'Mises à jour de dossiers',
        undefined,
        false,
        false
      ).subscribe();

      this.createChannel(
        'general',
        'Général',
        2,
        'Notifications générales',
        undefined,
        false,
        false
      ).subscribe();
    }
  }

  /**
   * Handle notification routing based on action
   */
  handleNotificationAction(action: ActionPerformed): { route: string; params?: any } | null {
    const data = action.notification.data;

    if (!data) {
      return { route: '/' };
    }

    // Route based on notification type
    switch (data.type) {
      case 'message':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'messages' }
        };

      case 'appointment':
        return {
          route: `/calendar`,
          params: { eventId: data.eventId }
        };

      case 'task':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'tasks', taskId: data.taskId }
        };

      case 'dossier_update':
        return {
          route: `/dossiers/${data.dossierId}`
        };

      case 'whatsapp':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'whatsapp' }
        };

      default:
        return { route: '/' };
    }
  }

  /**
   * Clean up listeners
   */
  removeAllListeners(): void {
    if (this.isNativePlatform) {
      PushNotifications.removeAllListeners();
    }
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, BehaviorSubject } from 'rxjs';
import { environment } from '../../environments/environment';

export interface PushSubscriptionData {
  endpoint: string;
  keys: {
    p256dh: string;
    auth: string;
  };
}

export interface NotificationPayload {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  data?: any;
  actions?: Array<{
    action: string;
    title: string;
    icon?: string;
  }>;
  tag?: string;
  requireInteraction?: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class PushNotificationService {
  private subscription$ = new BehaviorSubject<PushSubscription | null>(null);
  private permission$ = new BehaviorSubject<NotificationPermission>('default');
  private vapidPublicKey = environment.vapidPublicKey || '';

  constructor(private http: HttpClient) {
    this.checkPermission();
  }

  /**
   * Check current notification permission
   */
  private checkPermission(): void {
    if ('Notification' in window) {
      this.permission$.next(Notification.permission);
    }
  }

  /**
   * Request notification permission from user
   */
  async requestPermission(): Promise<NotificationPermission> {
    if (!('Notification' in window)) {
      console.warn('This browser does not support notifications');
      return 'denied';
    }

    try {
      const permission = await Notification.requestPermission();
      this.permission$.next(permission);
      
      if (permission === 'granted') {
        await this.subscribeToPush();
      }
      
      return permission;
    } catch (error) {
      console.error('Error requesting notification permission:', error);
      return 'denied';
    }
  }

  /**
   * Subscribe to push notifications
   */
  async subscribeToPush(): Promise<PushSubscription | null> {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      console.warn('Push notifications not supported');
      return null;
    }

    try {
      const registration = await navigator.serviceWorker.ready;
      
      // Check if already subscribed
      let subscription = await registration.pushManager.getSubscription();
      
      if (!subscription) {
        // Subscribe to push
        const applicationServerKey = this.urlBase64ToUint8Array(this.vapidPublicKey);
        
        subscription = await registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: applicationServerKey as BufferSource
        });
      }

      // Send subscription to backend
      await this.sendSubscriptionToBackend(subscription);
      
      this.subscription$.next(subscription);
      return subscription;
    } catch (error) {
      console.error('Error subscribing to push:', error);
      return null;
    }
  }

  /**
   * Unsubscribe from push notifications
   */
  async unsubscribeFromPush(): Promise<boolean> {
    const subscription = this.subscription$.value;
    
    if (!subscription) {
      return false;
    }

    try {
      // Remove subscription from backend
      await this.removeSubscriptionFromBackend(subscription);
      
      // Unsubscribe from browser
      await subscription.unsubscribe();
      
      this.subscription$.next(null);
      return true;
    } catch (error) {
      console.error('Error unsubscribing from push:', error);
      return false;
    }
  }

  /**
   * Show local notification (doesn't require push)
   */
  async showNotification(payload: NotificationPayload): Promise<void> {
    if (!('Notification' in window)) {
      console.warn('Notifications not supported');
      return;
    }

    if (Notification.permission !== 'granted') {
      const permission = await this.requestPermission();
      if (permission !== 'granted') {
        return;
      }
    }

    try {
      const registration = await navigator.serviceWorker.ready;
      
      await registration.showNotification(payload.title, {
        body: payload.body,
        icon: payload.icon || '/assets/icons/icon-192x192.png',
        badge: payload.badge || '/assets/icons/icon-96x96.png',
        data: payload.data,
        actions: payload.actions,
        tag: payload.tag,
        requireInteraction: payload.requireInteraction || false,
        vibrate: [200, 100, 200],
        timestamp: Date.now()
      } as any);
    } catch (error) {
      console.error('Error showing notification:', error);
    }
  }

  /**
   * Get current subscription
   */
  getSubscription(): Observable<PushSubscription | null> {
    return this.subscription$.asObservable();
  }

  /**
   * Get current permission status
   */
  getPermission(): Observable<NotificationPermission> {
    return this.permission$.asObservable();
  }

  /**
   * Check if push notifications are supported
   */
  isSupported(): boolean {
    return 'Notification' in window && 
           'serviceWorker' in navigator && 
           'PushManager' in window;
  }

  /**
   * Send subscription to backend
   */
  private async sendSubscriptionToBackend(subscription: PushSubscription): Promise<void> {
    const subscriptionData = this.subscriptionToData(subscription);
    
    try {
      await this.http.post('/api/v1/push/subscribe', subscriptionData).toPromise();
    } catch (error) {
      console.error('Error sending subscription to backend:', error);
    }
  }

  /**
   * Remove subscription from backend
   */
  private async removeSubscriptionFromBackend(subscription: PushSubscription): Promise<void> {
    const subscriptionData = this.subscriptionToData(subscription);
    
    try {
      await this.http.post('/api/v1/push/unsubscribe', subscriptionData).toPromise();
    } catch (error) {
      console.error('Error removing subscription from backend:', error);
    }
  }

  /**
   * Convert subscription to data format for backend
   */
  private subscriptionToData(subscription: PushSubscription): PushSubscriptionData {
    const key = subscription.getKey('p256dh');
    const auth = subscription.getKey('auth');
    
    return {
      endpoint: subscription.endpoint,
      keys: {
        p256dh: key ? this.arrayBufferToBase64(key) : '',
        auth: auth ? this.arrayBufferToBase64(auth) : ''
      }
    };
  }

  /**
   * Convert URL-safe base64 to Uint8Array
   */
  private urlBase64ToUint8Array(base64String: string): Uint8Array {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding)
      .replace(/-/g, '+')
      .replace(/_/g, '/');

    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);

    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }

  /**
   * Convert ArrayBuffer to base64
   */
  private arrayBufferToBase64(buffer: ArrayBuffer): string {
    const bytes = new Uint8Array(buffer);
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return window.btoa(binary);
  }

  /**
   * Test notification (for debugging)
   */
  async testNotification(): Promise<void> {
    await this.showNotification({
      title: 'Test Notification',
      body: 'This is a test notification from CRM Immobilier',
      icon: '/assets/icons/icon-192x192.png',
      data: { test: true },
      actions: [
        {
          action: 'view',
          title: 'View'
        },
        {
          action: 'dismiss',
          title: 'Dismiss'
        }
      ]
    });
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, interval } from 'rxjs';
import { filter } from 'rxjs/operators';
import { OfflineService } from './offline.service';
import { OfflineStorageService } from './offline-storage.service';
import { HttpClient } from '@angular/common/http';
import { NotificationService } from './notification.service';

export enum QueuedActionType {
  CREATE_MESSAGE = 'CREATE_MESSAGE',
  UPDATE_DOSSIER_STATUS = 'UPDATE_DOSSIER_STATUS',
  CREATE_APPOINTMENT = 'CREATE_APPOINTMENT',
  UPDATE_APPOINTMENT = 'UPDATE_APPOINTMENT',
  CREATE_NOTE = 'CREATE_NOTE'
}

export enum QueuedActionStatus {
  PENDING = 'PENDING',
  SYNCING = 'SYNCING',
  SUCCESS = 'SUCCESS',
  FAILED = 'FAILED',
  CONFLICT = 'CONFLICT'
}

export interface QueuedAction {
  id: string;
  type: QueuedActionType;
  payload: any;
  timestamp: number;
  status: QueuedActionStatus;
  retryCount: number;
  error?: string;
  localId?: string;
  serverId?: number;
}

export interface SyncProgress {
  total: number;
  completed: number;
  failed: number;
  inProgress: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class OfflineQueueService {
  private syncProgressSubject = new BehaviorSubject<SyncProgress>({
    total: 0,
    completed: 0,
    failed: 0,
    inProgress: false
  });

  public syncProgress$: Observable<SyncProgress> = this.syncProgressSubject.asObservable();

  private readonly SYNC_INTERVAL = 30000; // 30 seconds
  private readonly MAX_RETRY_COUNT = 3;
  private isSyncing = false;

  constructor(
    private offlineService: OfflineService,
    private storageService: OfflineStorageService,
    private http: HttpClient,
    private notificationService: NotificationService
  ) {
    this.initializeBackgroundSync();
  }

  private initializeBackgroundSync(): void {
    this.offlineService.connectivity$
      .pipe(
        filter(state => state.status !== 'OFFLINE')
      )
      .subscribe(() => {
        this.syncQueue();
      });

    interval(this.SYNC_INTERVAL)
      .pipe(
        filter(() => this.offlineService.isOnline() && !this.isSyncing)
      )
      .subscribe(() => {
        this.syncQueue();
      });

    if ('serviceWorker' in navigator && (self as any).registration && 'sync' in (self as any).registration) {
      navigator.serviceWorker.ready.then(registration => {
        return (registration as any).sync.register('offline-queue-sync');
      }).catch(err => {
        console.warn('Background sync not supported:', err);
      });
    }
  }

  async queueAction(action: Omit<QueuedAction, 'id' | 'timestamp' | 'status' | 'retryCount'>): Promise<string> {
    const queuedAction: QueuedAction = {
      ...action,
      id: this.generateId(),
      timestamp: Date.now(),
      status: QueuedActionStatus.PENDING,
      retryCount: 0
    };

    await this.storageService.addQueuedAction(queuedAction);
    
    this.notificationService.info('Action mise en file d\'attente', 'Voir');

    if (this.offlineService.isOnline()) {
      setTimeout(() => this.syncQueue(), 100);
    }

    return queuedAction.id;
  }

  async syncQueue(): Promise<void> {
    if (this.isSyncing || !this.offlineService.isOnline()) {
      return;
    }

    this.isSyncing = true;
    const pendingActions = await this.storageService.getPendingActions();

    if (pendingActions.length === 0) {
      this.isSyncing = false;
      return;
    }

    this.syncProgressSubject.next({
      total: pendingActions.length,
      completed: 0,
      failed: 0,
      inProgress: true
    });

    let completed = 0;
    let failed = 0;

    for (const action of pendingActions) {
      try {
        await this.syncAction(action);
        completed++;
        this.notificationService.success(`Action synchronisée: ${this.getActionLabel(action.type)}`);
      } catch (error: any) {
        failed++;
        action.retryCount++;
        action.error = error.message || 'Unknown error';

        if (action.retryCount >= this.MAX_RETRY_COUNT) {
          action.status = QueuedActionStatus.FAILED;
          this.notificationService.error(
            `Échec de synchronisation: ${this.getActionLabel(action.type)}`,
            'Réessayer',
            () => this.retryAction(action.id)
          );
        } else {
          action.status = QueuedActionStatus.PENDING;
        }

        await this.storageService.updateQueuedAction(action);
      }

      this.syncProgressSubject.next({
        total: pendingActions.length,
        completed,
        failed,
        inProgress: true
      });
    }

    this.syncProgressSubject.next({
      total: pendingActions.length,
      completed,
      failed,
      inProgress: false
    });

    this.isSyncing = false;

    if (completed > 0) {
      this.notificationService.success(`${completed} action(s) synchronisée(s) avec succès`);
    }
  }

  private async syncAction(action: QueuedAction): Promise<void> {
    action.status = QueuedActionStatus.SYNCING;
    await this.storageService.updateQueuedAction(action);

    let response: any;

    switch (action.type) {
      case QueuedActionType.CREATE_MESSAGE:
        response = await this.http.post('/api/v1/messages', action.payload).toPromise();
        break;

      case QueuedActionType.UPDATE_DOSSIER_STATUS:
        response = await this.http.patch(
          `/api/v1/dossiers/${action.payload.id}/status`,
          { status: action.payload.status }
        ).toPromise();
        break;

      case QueuedActionType.CREATE_APPOINTMENT:
        response = await this.http.post('/api/v1/appointments', action.payload).toPromise();
        break;

      case QueuedActionType.UPDATE_APPOINTMENT:
        response = await this.http.put(
          `/api/v1/appointments/${action.payload.id}`,
          action.payload
        ).toPromise();
        break;

      case QueuedActionType.CREATE_NOTE:
        response = await this.http.post('/api/v1/notes', action.payload).toPromise();
        break;

      default:
        throw new Error(`Unknown action type: ${action.type}`);
    }

    action.status = QueuedActionStatus.SUCCESS;
    action.serverId = response?.id;
    await this.storageService.updateQueuedAction(action);

    if (action.localId && response?.id) {
      await this.storageService.mapLocalToServerId(action.localId, response.id);
    }
  }

  async retryAction(actionId: string): Promise<void> {
    const action = await this.storageService.getQueuedAction(actionId);
    if (action) {
      action.status = QueuedActionStatus.PENDING;
      action.retryCount = 0;
      action.error = undefined;
      await this.storageService.updateQueuedAction(action);
      
      if (this.offlineService.isOnline()) {
        await this.syncQueue();
      }
    }
  }

  async clearQueue(): Promise<void> {
    await this.storageService.clearQueue();
    this.syncProgressSubject.next({
      total: 0,
      completed: 0,
      failed: 0,
      inProgress: false
    });
  }

  async getPendingActionsCount(): Promise<number> {
    const actions = await this.storageService.getPendingActions();
    return actions.length;
  }

  async getFailedActions(): Promise<QueuedAction[]> {
    return this.storageService.getFailedActions();
  }

  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  private getActionLabel(type: QueuedActionType): string {
    const labels: Record<QueuedActionType, string> = {
      [QueuedActionType.CREATE_MESSAGE]: 'Création de message',
      [QueuedActionType.UPDATE_DOSSIER_STATUS]: 'Changement de statut',
      [QueuedActionType.CREATE_APPOINTMENT]: 'Création de rendez-vous',
      [QueuedActionType.UPDATE_APPOINTMENT]: 'Mise à jour de rendez-vous',
      [QueuedActionType.CREATE_NOTE]: 'Création de note'
    };
    return labels[type] || type;
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, fromEvent, merge, of } from 'rxjs';
import { map, startWith, debounceTime } from 'rxjs/operators';
import { MessageApiService, MessageCreateRequest, MessageResponse } from './message-api.service';

export interface QueuedMessage {
  id: string;
  request: MessageCreateRequest;
  timestamp: number;
  retries: number;
}

const STORAGE_KEY = 'whatsapp_message_queue';
const MAX_RETRIES = 3;

@Injectable({
  providedIn: 'root'
})
export class OfflineMessageQueueService {
  private queueSubject = new BehaviorSubject<QueuedMessage[]>([]);
  private isOnlineSubject = new BehaviorSubject<boolean>(navigator.onLine);
  private isSyncingSubject = new BehaviorSubject<boolean>(false);

  queue$ = this.queueSubject.asObservable();
  isOnline$ = this.isOnlineSubject.asObservable();
  isSyncing$ = this.isSyncingSubject.asObservable();

  queueCount$ = this.queue$.pipe(
    map(queue => queue.length)
  );

  constructor(private messageApiService: MessageApiService) {
    this.loadQueue();
    this.setupOnlineListener();
  }

  private setupOnlineListener(): void {
    const online$ = fromEvent(window, 'online').pipe(map(() => true));
    const offline$ = fromEvent(window, 'offline').pipe(map(() => false));

    merge(online$, offline$)
      .pipe(
        startWith(navigator.onLine),
        debounceTime(500)
      )
      .subscribe(isOnline => {
        this.isOnlineSubject.next(isOnline);
        if (isOnline) {
          this.syncQueue();
        }
      });
  }

  private loadQueue(): void {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const queue = JSON.parse(stored) as QueuedMessage[];
        this.queueSubject.next(queue);
      }
    } catch (error) {
      console.error('Error loading message queue:', error);
      this.queueSubject.next([]);
    }
  }

  private saveQueue(): void {
    try {
      const queue = this.queueSubject.value;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(queue));
    } catch (error) {
      console.error('Error saving message queue:', error);
    }
  }

  enqueue(request: MessageCreateRequest): Observable<MessageResponse | null> {
    if (this.isOnlineSubject.value) {
      return this.messageApiService.create(request);
    }

    const queuedMessage: QueuedMessage = {
      id: this.generateId(),
      request,
      timestamp: Date.now(),
      retries: 0
    };

    const currentQueue = this.queueSubject.value;
    this.queueSubject.next([...currentQueue, queuedMessage]);
    this.saveQueue();

    return of(null);
  }

  async syncQueue(): Promise<void> {
    if (this.isSyncingSubject.value || !this.isOnlineSubject.value) {
      return;
    }

    const queue = this.queueSubject.value;
    if (queue.length === 0) {
      return;
    }

    this.isSyncingSubject.next(true);

    const remainingMessages: QueuedMessage[] = [];

    for (const queuedMessage of queue) {
      try {
        await this.sendQueuedMessage(queuedMessage);
      } catch (error) {
        console.error('Error sending queued message:', error);
        
        if (queuedMessage.retries < MAX_RETRIES) {
          remainingMessages.push({
            ...queuedMessage,
            retries: queuedMessage.retries + 1
          });
        }
      }
    }

    this.queueSubject.next(remainingMessages);
    this.saveQueue();
    this.isSyncingSubject.next(false);
  }

  private sendQueuedMessage(queuedMessage: QueuedMessage): Promise<MessageResponse> {
    return new Promise((resolve, reject) => {
      this.messageApiService.create(queuedMessage.request).subscribe({
        next: (response) => resolve(response),
        error: (error) => reject(error)
      });
    });
  }

  clearQueue(): void {
    this.queueSubject.next([]);
    this.saveQueue();
  }

  removeFromQueue(messageId: string): void {
    const currentQueue = this.queueSubject.value;
    const updatedQueue = currentQueue.filter(m => m.id !== messageId);
    this.queueSubject.next(updatedQueue);
    this.saveQueue();
  }

  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  getQueueSize(): number {
    return this.queueSubject.value.length;
  }

  isOnline(): boolean {
    return this.isOnlineSubject.value;
  }

  isSyncing(): boolean {
    return this.isSyncingSubject.value;
  }
}

