export interface RecentItem {
  id: string;
  type: 'dossier' | 'annonce';
  title: string;
  subtitle?: string;
  route: string;
  timestamp: number;
}

@Injectable({
  providedIn: 'root'
})
export class RecentNavigationService {
  private readonly STORAGE_KEY = 'recent_navigation';
  private readonly MAX_ITEMS = 10;
  
  private recentItemsSubject: BehaviorSubject<RecentItem[]>;
  public recentItems$: Observable<RecentItem[]>;

  constructor(private router: Router) {
    const stored = this.loadFromStorage();
    this.recentItemsSubject = new BehaviorSubject<RecentItem[]>(stored);
    this.recentItems$ = this.recentItemsSubject.asObservable();
    
    this.initializeRouterTracking();
  }

  private initializeRouterTracking(): void {
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd)
    ).subscribe((event) => {
      this.trackNavigation(event.url);
    });
  }

  private trackNavigation(url: string): void {
    // Parse dossier/annonce routes
    const dossierMatch = url.match(/\/dossiers\/(\d+)/);
    const annonceMatch = url.match(/\/annonces\/(\d+)/);
    
    if (dossierMatch) {
      const _id = dossierMatch[1];
      // Don't add immediately - wait for title to be set via addRecentItem
      return;
    } else if (annonceMatch) {
      const _id = annonceMatch[1];
      // Don't add immediately - wait for title to be set via addRecentItem
      return;
    }
  }

  addRecentItem(item: Omit<RecentItem, 'timestamp'>): void {
    const items = this.recentItemsSubject.value;
    const timestamp = Date.now();
    
    // Remove existing entry with same id
    const filtered = items.filter(i => i.id !== item.id);
    
    // Add new item at the beginning
    const newItems = [{ ...item, timestamp }, ...filtered].slice(0, this.MAX_ITEMS);
    
    this.recentItemsSubject.next(newItems);
    this.saveToStorage(newItems);
  }

  getRecentItems(): RecentItem[] {
    return this.recentItemsSubject.value;
  }

  clearRecentItems(): void {
    this.recentItemsSubject.next([]);
    localStorage.removeItem(this.STORAGE_KEY);
  }

  private loadFromStorage(): RecentItem[] {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch (e) {
      console.error('Failed to load recent navigation', e);
    }
    return [];
  }

  private saveToStorage(items: RecentItem[]): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(items));
    } catch (e) {
      console.error('Failed to save recent navigation', e);
    }
  }
}

import { Component, OnInit, OnDestroy, HostListener, viewChild } from '@angular/core';
import { Router } from '@angular/router';
import { SearchApiService, SearchResult } from '../services/search-api.service';
import { debounceTime, distinctUntilChanged, switchMap, catchError } from 'rxjs/operators';
import { Subject, of, Subscription } from 'rxjs';
import { FormsModule } from '@angular/forms';
import { UpperCasePipe } from '@angular/common';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';
import { DsInputComponent } from '../design-system/primitives/ds-input/ds-input.component';

interface GroupedResults {
  annonces: EnhancedSearchResult[];
  dossiers: EnhancedSearchResult[];
  contacts: EnhancedSearchResult[];
}

interface EnhancedSearchResult extends SearchResult {
  highlightedTitle?: string;
  highlightedDescription?: string;
  preview?: any;
}

interface RecentSearch {
  query: string;
  timestamp: number;
}

@Component({
    selector: 'app-global-search-bar',
    templateUrl: './global-search-bar.component.html',
    styleUrls: ['./global-search-bar.component.scss'],
    imports: [FormsModule, UpperCasePipe, DsSkeletonComponent, DsInputComponent]
})
export class GlobalSearchBarComponent implements OnInit, OnDestroy {
  readonly searchInput = viewChild.required(DsInputComponent);

  /** Icône loupe (alignée sur le pattern filter-bar). */
  readonly searchPrefixIcon =
    '<svg width="15" height="15" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><circle cx="7" cy="7" r="5" stroke="currentColor" stroke-width="1.5"/><path d="M14 14l-2.5-2.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>';

  searchQuery = '';
  groupedResults: GroupedResults = {
    annonces: [],
    dossiers: [],
    contacts: []
  };
  recentSearches: RecentSearch[] = [];
  totalHits = 0;
  elasticsearchAvailable = false;
  showDropdown = false;
  isLoading = false;
  error = '';
  hoveredResult: EnhancedSearchResult | null = null;
  selectedIndex = -1;
  flatResults: EnhancedSearchResult[] = [];

  private searchSubject = new Subject<string>();
  private subscriptions = new Subscription();
  private readonly RECENT_SEARCHES_KEY = 'globalSearchRecent';
  private readonly MAX_RECENT_SEARCHES = 5;

  constructor(
    private searchService: SearchApiService,
    private router: Router
  ) {}

  ngOnInit() {
    this.loadRecentSearches();
    
    const searchSub = this.searchSubject
      .pipe(
        debounceTime(300),
        distinctUntilChanged(),
        switchMap(query => {
          if (!query || query.trim().length < 2) {
            return of({ results: [], totalHits: 0, elasticsearchAvailable: false });
          }
          this.isLoading = true;
          this.error = '';
          return this.searchService.autocomplete(query).pipe(
            catchError(() => {
              this.error = 'Échec de la recherche. Veuillez réessayer.';
              return of({ results: [], totalHits: 0, elasticsearchAvailable: false });
            })
          );
        })
      )
      .subscribe(response => {
        const enhancedResults = this.enhanceResults(response.results, this.searchQuery);
        this.groupResults(enhancedResults);
        this.totalHits = response.totalHits;
        this.elasticsearchAvailable = response.elasticsearchAvailable;
        this.isLoading = false;
        this.selectedIndex = -1;
      });

    this.subscriptions.add(searchSub);
  }

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
  }

  onSearchQueryChange(query: string): void {
    this.searchSubject.next(query);
  }

  onFocus() {
    this.showDropdown = true;
  }

  onBlur() {
    setTimeout(() => {
      this.showDropdown = false;
      this.hoveredResult = null;
    }, 200);
  }

  clearSearch() {
    this.searchQuery = '';
    this.groupedResults = { annonces: [], dossiers: [], contacts: [] };
    this.flatResults = [];
    this.totalHits = 0;
    this.showDropdown = false;
    this.selectedIndex = -1;
    this.hoveredResult = null;
  }

  navigateToResult(result: EnhancedSearchResult) {
    this.saveRecentSearch(this.searchQuery);
    
    if (result.type === 'annonce') {
      this.router.navigate(['/annonces', result.id]);
    } else if (result.type === 'dossier') {
      this.router.navigate(['/dossiers', result.id]);
    } else if (result.type === 'contact') {
      this.router.navigate(['/parties-prenantes', result.id]);
    }
    this.clearSearch();
  }

  viewAllResults() {
    this.saveRecentSearch(this.searchQuery);
    this.router.navigate(['/search'], { queryParams: { q: this.searchQuery } });
    this.clearSearch();
  }

  selectRecentSearch(search: RecentSearch) {
    this.searchQuery = search.query;
    this.searchSubject.next(search.query);
    this.searchInput().focus();
  }

  removeRecentSearch(search: RecentSearch, event: Event) {
    event.stopPropagation();
    this.recentSearches = this.recentSearches.filter(s => s.timestamp !== search.timestamp);
    this.saveRecentSearchesToStorage();
  }

  onResultHover(result: EnhancedSearchResult) {
    this.hoveredResult = result;
  }

  onResultLeave() {
    this.hoveredResult = null;
  }

  @HostListener('window:keydown', ['$event'])
  handleKeyboardShortcut(event: KeyboardEvent) {
    if (event.key === '/' && document.activeElement?.tagName !== 'INPUT' && document.activeElement?.tagName !== 'TEXTAREA') {
      event.preventDefault();
      this.searchInput().focus();
      return;
    }

    if (!this.showDropdown || this.flatResults.length === 0) {
      return;
    }

    switch (event.key) {
      case 'Tab':
        event.preventDefault();
        if (event.shiftKey) {
          this.navigatePrevious();
        } else {
          this.navigateNext();
        }
        break;
      case 'ArrowDown':
        event.preventDefault();
        this.navigateNext();
        break;
      case 'ArrowUp':
        event.preventDefault();
        this.navigatePrevious();
        break;
      case 'Enter':
        event.preventDefault();
        if (this.selectedIndex >= 0 && this.selectedIndex < this.flatResults.length) {
          this.navigateToResult(this.flatResults[this.selectedIndex]);
        }
        break;
      case 'Escape':
        event.preventDefault();
        this.clearSearch();
        this.searchInput()?.blur();
        break;
    }
  }

  private navigateNext() {
    this.selectedIndex = (this.selectedIndex + 1) % this.flatResults.length;
    this.scrollToSelected();
  }

  private navigatePrevious() {
    this.selectedIndex = this.selectedIndex <= 0 ? this.flatResults.length - 1 : this.selectedIndex - 1;
    this.scrollToSelected();
  }

  private scrollToSelected() {
    setTimeout(() => {
      const element = document.getElementById(`search-result-${this.selectedIndex}`);
      if (element) {
        element.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      }
    }, 0);
  }

  private enhanceResults(results: SearchResult[], query: string): EnhancedSearchResult[] {
    const fuzzyResults = this.fuzzyFilter(results, query);
    return fuzzyResults.map(result => ({
      ...result,
      highlightedTitle: this.highlightText(result.title, query),
      highlightedDescription: result.description ? this.highlightText(result.description, query) : undefined,
      preview: this.generatePreview(result)
    }));
  }

  private fuzzyFilter(results: SearchResult[], query: string): SearchResult[] {
    if (!query) return results;
    
    const lowerQuery = query.toLowerCase();
    
    return results
      .map(result => {
        const titleScore = this.fuzzyScore(result.title.toLowerCase(), lowerQuery);
        const descScore = result.description ? this.fuzzyScore(result.description.toLowerCase(), lowerQuery) : 0;
        const maxScore = Math.max(titleScore, descScore);
        
        return { result, score: maxScore };
      })
      .filter(item => item.score > 0)
      .sort((a, b) => b.score - a.score)
      .map(item => item.result);
  }

  private fuzzyScore(text: string, query: string): number {
    let score = 0;
    let queryIndex = 0;
    let textIndex = 0;
    let consecutiveMatches = 0;

    while (textIndex < text.length && queryIndex < query.length) {
      if (text[textIndex] === query[queryIndex]) {
        score += 1 + consecutiveMatches;
        consecutiveMatches++;
        queryIndex++;
      } else {
        consecutiveMatches = 0;
      }
      textIndex++;
    }

    if (queryIndex === query.length) {
      score += 10;
    }

    return score;
  }

  private highlightText(text: string, query: string): string {
    if (!query || !text) return text;
    
    const regex = new RegExp(`(${this.escapeRegex(query)})`, 'gi');
    return text.replace(regex, '<mark>$1</mark>');
  }

  private escapeRegex(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  private generatePreview(result: SearchResult): any {
    const preview: any = {
      id: result.id,
      type: result.type
    };

    if (result.type === 'annonce') {
      preview.details = [
        { label: 'Type', value: result.description || 'N/A' },
        { label: 'Créé', value: this.formatDate(result.createdAt) },
        { label: 'Modifié', value: this.formatDate(result.updatedAt) }
      ];
    } else if (result.type === 'dossier') {
      preview.details = [
        { label: 'Description', value: result.description || 'N/A' },
        { label: 'Créé', value: this.formatDate(result.createdAt) },
        { label: 'Score', value: result.relevanceScore?.toFixed(2) || 'N/A' }
      ];
    } else if (result.type === 'contact') {
      preview.details = [
        { label: 'Info', value: result.description || 'N/A' },
        { label: 'Créé', value: this.formatDate(result.createdAt) }
      ];
    }

    return preview;
  }

  private formatDate(dateString: string): string {
    if (!dateString) return 'N/A';
    const date = new Date(dateString);
    return date.toLocaleDateString('fr-FR', { 
      year: 'numeric', 
      month: 'short', 
      day: 'numeric' 
    });
  }

  private groupResults(results: EnhancedSearchResult[]) {
    this.groupedResults = {
      annonces: results.filter(r => r.type === 'annonce'),
      dossiers: results.filter(r => r.type === 'dossier'),
      contacts: results.filter(r => r.type === 'contact')
    };

    this.flatResults = [
      ...this.groupedResults.annonces,
      ...this.groupedResults.dossiers,
      ...this.groupedResults.contacts
    ];
  }

  private loadRecentSearches() {
    try {
      const stored = localStorage.getItem(this.RECENT_SEARCHES_KEY);
      if (stored) {
        this.recentSearches = JSON.parse(stored);
      }
    } catch (e) {
      console.error('Failed to load recent searches', e);
      this.recentSearches = [];
    }
  }

  private saveRecentSearch(query: string) {
    if (!query || query.trim().length < 2) return;

    this.recentSearches = this.recentSearches.filter(s => s.query !== query);
    
    this.recentSearches.unshift({
      query: query.trim(),
      timestamp: Date.now()
    });

    if (this.recentSearches.length > this.MAX_RECENT_SEARCHES) {
      this.recentSearches = this.recentSearches.slice(0, this.MAX_RECENT_SEARCHES);
    }

    this.saveRecentSearchesToStorage();
  }

  private saveRecentSearchesToStorage() {
    try {
      localStorage.setItem(this.RECENT_SEARCHES_KEY, JSON.stringify(this.recentSearches));
    } catch (e) {
      console.error('Failed to save recent searches', e);
    }
  }

  get hasResults(): boolean {
    return this.flatResults.length > 0;
  }

  get showRecentSearches(): boolean {
    return !this.searchQuery && this.recentSearches.length > 0;
  }

  isSelected(index: number): boolean {
    return this.selectedIndex === index;
  }

  getResultIndex(group: string, groupIndex: number): number {
    let index = groupIndex;
    if (group === 'dossiers') {
      index += this.groupedResults.annonces.length;
    } else if (group === 'contacts') {
      index += this.groupedResults.annonces.length + this.groupedResults.dossiers.length;
    }
    return index;
  }

  truncate(text: string, length: number): string {
    if (!text) return '';
    return text.length > length ? text.substring(0, length) + '...' : text;
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, of } from 'rxjs';
import { catchError, retry, timeout } from 'rxjs/operators';

export interface RegionConfig {
  name: string;
  displayName: string;
  endpoint: string;
  continent: string;
  isPrimary: boolean;
  priority: number;
  healthCheckUrl: string;
}

export interface GeoLocationData {
  country: string;
  continent: string;
  city: string;
  latitude: number;
  longitude: number;
  timezone: string;
}

export interface RegionHealth {
  region: string;
  healthy: boolean;
  latency: number;
  lastChecked: Date;
}

@Injectable({
  providedIn: 'root'
})
export class RegionRoutingService {
  private readonly REGIONS: RegionConfig[] = [
    {
      name: 'eu-west-1',
      displayName: 'Europe (Paris)',
      endpoint: 'https://eu-west-1.atlas-crm.com',
      continent: 'EU',
      isPrimary: true,
      priority: 1,
      healthCheckUrl: '/actuator/health'
    },
    {
      name: 'us-east-1',
      displayName: 'North America (Virginia)',
      endpoint: 'https://us-east-1.atlas-crm.com',
      continent: 'NA',
      isPrimary: false,
      priority: 2,
      healthCheckUrl: '/actuator/health'
    },
    {
      name: 'ap-southeast-1',
      displayName: 'Asia Pacific (Singapore)',
      endpoint: 'https://ap-southeast-1.atlas-crm.com',
      continent: 'AS',
      isPrimary: false,
      priority: 3,
      healthCheckUrl: '/actuator/health'
    }
  ];

  private selectedRegionSubject = new BehaviorSubject<RegionConfig | null>(null);
  public selectedRegion$ = this.selectedRegionSubject.asObservable();

  private regionHealthSubject = new BehaviorSubject<Map<string, RegionHealth>>(new Map());
  public regionHealth$ = this.regionHealthSubject.asObservable();

  private failoverInProgressSubject = new BehaviorSubject<boolean>(false);
  public failoverInProgress$ = this.failoverInProgressSubject.asObservable();

  private readonly LATENCY_THRESHOLD_MS = 200;
  private readonly HEALTH_CHECK_INTERVAL_MS = 30000;
  private readonly STORAGE_KEY = 'atlas_selected_region';

  constructor(private http: HttpClient) {
    this.initializeRegionSelection();
    this.startHealthMonitoring();
  }

  private async initializeRegionSelection(): Promise<void> {
    const savedRegion = localStorage.getItem(this.STORAGE_KEY);
    
    if (savedRegion) {
      const region = this.REGIONS.find(r => r.name === savedRegion);
      if (region && await this.checkRegionHealth(region)) {
        this.selectRegion(region);
        return;
      }
    }

    try {
      const geoLocation = await this.detectGeoLocation();
      const optimalRegion = await this.findOptimalRegion(geoLocation);
      this.selectRegion(optimalRegion);
    } catch (error) {
      console.error('Failed to detect optimal region, using primary', error);
      const primaryRegion = this.REGIONS.find(r => r.isPrimary) || this.REGIONS[0];
      this.selectRegion(primaryRegion);
    }
  }

  private detectGeoLocation(): Promise<GeoLocationData> {
    return this.http.get<GeoLocationData>('https://ipapi.co/json/')
      .pipe(
        timeout(5000),
        retry(2),
        catchError(error => {
          console.error('Geolocation detection failed', error);
          return of({
            country: 'US',
            continent: 'NA',
            city: 'Unknown',
            latitude: 0,
            longitude: 0,
            timezone: 'UTC'
          });
        })
      )
      .toPromise() as Promise<GeoLocationData>;
  }

  private async findOptimalRegion(geoLocation: GeoLocationData): Promise<RegionConfig> {
    const continentMap: { [key: string]: string } = {
      'EU': 'EU',
      'NA': 'NA',
      'SA': 'NA',
      'AS': 'AS',
      'OC': 'AS',
      'AF': 'EU'
    };

    const targetContinent = continentMap[geoLocation.continent] || 'EU';
    
    const continentRegions = this.REGIONS.filter(r => r.continent === targetContinent);
    
    if (continentRegions.length > 0) {
      const latencies = await Promise.all(
        continentRegions.map(async region => ({
          region,
          latency: await this.measureLatency(region)
        }))
      );

      latencies.sort((a, b) => a.latency - b.latency);
      
      const fastestHealthyRegion = latencies.find(l => l.latency < this.LATENCY_THRESHOLD_MS);
      if (fastestHealthyRegion) {
        return fastestHealthyRegion.region;
      }
    }

    const allLatencies = await Promise.all(
      this.REGIONS.map(async region => ({
        region,
        latency: await this.measureLatency(region)
      }))
    );

    allLatencies.sort((a, b) => a.latency - b.latency);
    return allLatencies[0].region;
  }

  private async measureLatency(region: RegionConfig): Promise<number> {
    const startTime = performance.now();
    
    try {
      await this.http.get(region.endpoint + region.healthCheckUrl, {
        observe: 'response'
      }).pipe(
        timeout(5000)
      ).toPromise();
      
      const endTime = performance.now();
      return endTime - startTime;
    } catch (error) {
      return Infinity;
    }
  }

  private async checkRegionHealth(region: RegionConfig): Promise<boolean> {
    try {
      const response = await this.http.get<any>(region.endpoint + region.healthCheckUrl)
        .pipe(
          timeout(5000),
          retry(1)
        )
        .toPromise();
      
      return response?.status === 'UP';
    } catch (error) {
      return false;
    }
  }

  private selectRegion(region: RegionConfig): void {
    this.selectedRegionSubject.next(region);
    localStorage.setItem(this.STORAGE_KEY, region.name);
    console.log(`Selected region: ${region.displayName} (${region.name})`);
  }

  public getApiEndpoint(): string {
    const region = this.selectedRegionSubject.value;
    return region ? region.endpoint : this.REGIONS[0].endpoint;
  }

  public getCurrentRegion(): RegionConfig | null {
    return this.selectedRegionSubject.value;
  }

  public getAllRegions(): RegionConfig[] {
    return [...this.REGIONS];
  }

  public async switchRegion(regionName: string): Promise<boolean> {
    const region = this.REGIONS.find(r => r.name === regionName);
    
    if (!region) {
      console.error(`Region ${regionName} not found`);
      return false;
    }

    const isHealthy = await this.checkRegionHealth(region);
    
    if (!isHealthy) {
      console.error(`Region ${regionName} is unhealthy`);
      return false;
    }

    this.selectRegion(region);
    return true;
  }

  private startHealthMonitoring(): void {
    setInterval(async () => {
      const healthMap = new Map<string, RegionHealth>();

      for (const region of this.REGIONS) {
        const latency = await this.measureLatency(region);
        const healthy = latency < this.LATENCY_THRESHOLD_MS && latency !== Infinity;

        healthMap.set(region.name, {
          region: region.name,
          healthy,
          latency,
          lastChecked: new Date()
        });

        if (latency > this.LATENCY_THRESHOLD_MS && latency !== Infinity) {
          console.warn(`High latency detected for region ${region.name}: ${latency.toFixed(2)}ms`);
          this.reportLatencyMetric(region.name, latency);
        }
      }

      this.regionHealthSubject.next(healthMap);

      const currentRegion = this.selectedRegionSubject.value;
      if (currentRegion) {
        const currentHealth = healthMap.get(currentRegion.name);
        if (currentHealth && !currentHealth.healthy) {
          await this.performFailover();
        }
      }
    }, this.HEALTH_CHECK_INTERVAL_MS);
  }

  private async performFailover(): Promise<void> {
    if (this.failoverInProgressSubject.value) {
      return;
    }

    this.failoverInProgressSubject.next(true);
    console.warn('Performing automatic failover due to unhealthy region');

    try {
      const healthyRegions = this.REGIONS.filter(async r => {
        const health = await this.checkRegionHealth(r);
        return health;
      });

      healthyRegions.sort((a, b) => a.priority - b.priority);

      if (healthyRegions.length > 0) {
        const targetRegion = healthyRegions[0];
        console.log(`Failing over to region: ${targetRegion.displayName}`);
        this.selectRegion(targetRegion);
      } else {
        console.error('No healthy regions available for failover');
      }
    } finally {
      this.failoverInProgressSubject.next(false);
    }
  }

  private reportLatencyMetric(region: string, latency: number): void {
    if (typeof navigator !== 'undefined' && 'sendBeacon' in navigator) {
      const data = JSON.stringify({
        metric: 'cross_region_latency',
        region,
        latency,
        timestamp: new Date().toISOString()
      });
      
      navigator.sendBeacon('/api/metrics/latency', data);
    }
  }

  public async testAllRegions(): Promise<Map<string, number>> {
    const latencies = new Map<string, number>();

    for (const region of this.REGIONS) {
      const latency = await this.measureLatency(region);
      latencies.set(region.name, latency);
    }

    return latencies;
  }

  public getRegionByName(name: string): RegionConfig | undefined {
    return this.REGIONS.find(r => r.name === name);
  }

  public isRegionHealthy(regionName: string): boolean {
    const healthMap = this.regionHealthSubject.value;
    const health = healthMap.get(regionName);
    return health?.healthy ?? false;
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, of } from 'rxjs';
import { catchError, retry, timeout } from 'rxjs/operators';

export interface RegionConfig {
  name: string;
  displayName: string;
  endpoint: string;
  continent: string;
  isPrimary: boolean;
  priority: number;
  healthCheckUrl: string;
}

export interface GeoLocationData {
  country: string;
  continent: string;
  city: string;
  latitude: number;
  longitude: number;
  timezone: string;
}

export interface RegionHealth {
  region: string;
  healthy: boolean;
  latency: number;
  lastChecked: Date;
}

@Injectable({
  providedIn: 'root'
})
export class RegionRoutingService {
  private readonly REGIONS: RegionConfig[] = [
    {
      name: 'eu-west-1',
      displayName: 'Europe (Paris)',
      endpoint: 'https://eu-west-1.atlas-crm.com',
      continent: 'EU',
      isPrimary: true,
      priority: 1,
      healthCheckUrl: '/actuator/health'
    },
    {
      name: 'us-east-1',
      displayName: 'North America (Virginia)',
      endpoint: 'https://us-east-1.atlas-crm.com',
      continent: 'NA',
      isPrimary: false,
      priority: 2,
      healthCheckUrl: '/actuator/health'
    },
    {
      name: 'ap-southeast-1',
      displayName: 'Asia Pacific (Singapore)',
      endpoint: 'https://ap-southeast-1.atlas-crm.com',
      continent: 'AS',
      isPrimary: false,
      priority: 3,
      healthCheckUrl: '/actuator/health'
    }
  ];

  private selectedRegionSubject = new BehaviorSubject<RegionConfig | null>(null);
  public selectedRegion$ = this.selectedRegionSubject.asObservable();

  private regionHealthSubject = new BehaviorSubject<Map<string, RegionHealth>>(new Map());
  public regionHealth$ = this.regionHealthSubject.asObservable();

  private failoverInProgressSubject = new BehaviorSubject<boolean>(false);
  public failoverInProgress$ = this.failoverInProgressSubject.asObservable();

  private readonly LATENCY_THRESHOLD_MS = 200;
  private readonly HEALTH_CHECK_INTERVAL_MS = 30000;
  private readonly STORAGE_KEY = 'atlas_selected_region';

  constructor(private http: HttpClient) {
    this.initializeRegionSelection();
    this.startHealthMonitoring();
  }

  private async initializeRegionSelection(): Promise<void> {
    const savedRegion = localStorage.getItem(this.STORAGE_KEY);
    
    if (savedRegion) {
      const region = this.REGIONS.find(r => r.name === savedRegion);
      if (region && await this.checkRegionHealth(region)) {
        this.selectRegion(region);
        return;
      }
    }

    try {
      const geoLocation = await this.detectGeoLocation();
      const optimalRegion = await this.findOptimalRegion(geoLocation);
      this.selectRegion(optimalRegion);
    } catch (error) {
      console.error('Failed to detect optimal region, using primary', error);
      const primaryRegion = this.REGIONS.find(r => r.isPrimary) || this.REGIONS[0];
      this.selectRegion(primaryRegion);
    }
  }

  private detectGeoLocation(): Promise<GeoLocationData> {
    return this.http.get<GeoLocationData>('https://ipapi.co/json/')
      .pipe(
        timeout(5000),
        retry(2),
        catchError(error => {
          console.error('Geolocation detection failed', error);
          return of({
            country: 'US',
            continent: 'NA',
            city: 'Unknown',
            latitude: 0,
            longitude: 0,
            timezone: 'UTC'
          });
        })
      )
      .toPromise() as Promise<GeoLocationData>;
  }

  private async findOptimalRegion(geoLocation: GeoLocationData): Promise<RegionConfig> {
    const continentMap: { [key: string]: string } = {
      'EU': 'EU',
      'NA': 'NA',
      'SA': 'NA',
      'AS': 'AS',
      'OC': 'AS',
      'AF': 'EU'
    };

    const targetContinent = continentMap[geoLocation.continent] || 'EU';
    
    const continentRegions = this.REGIONS.filter(r => r.continent === targetContinent);
    
    if (continentRegions.length > 0) {
      const latencies = await Promise.all(
        continentRegions.map(async region => ({
          region,
          latency: await this.measureLatency(region)
        }))
      );

      latencies.sort((a, b) => a.latency - b.latency);
      
      const fastestHealthyRegion = latencies.find(l => l.latency < this.LATENCY_THRESHOLD_MS);
      if (fastestHealthyRegion) {
        return fastestHealthyRegion.region;
      }
    }

    const allLatencies = await Promise.all(
      this.REGIONS.map(async region => ({
        region,
        latency: await this.measureLatency(region)
      }))
    );

    allLatencies.sort((a, b) => a.latency - b.latency);
    return allLatencies[0].region;
  }

  private async measureLatency(region: RegionConfig): Promise<number> {
    const startTime = performance.now();
    
    try {
      await this.http.get(region.endpoint + region.healthCheckUrl, {
        observe: 'response'
      }).pipe(
        timeout(5000)
      ).toPromise();
      
      const endTime = performance.now();
      return endTime - startTime;
    } catch (error) {
      return Infinity;
    }
  }

  private async checkRegionHealth(region: RegionConfig): Promise<boolean> {
    try {
      const response = await this.http.get<any>(region.endpoint + region.healthCheckUrl)
        .pipe(
          timeout(5000),
          retry(1)
        )
        .toPromise();
      
      return response?.status === 'UP';
    } catch (error) {
      return false;
    }
  }

  private selectRegion(region: RegionConfig): void {
    this.selectedRegionSubject.next(region);
    localStorage.setItem(this.STORAGE_KEY, region.name);
    console.log(`Selected region: ${region.displayName} (${region.name})`);
  }

  public getApiEndpoint(): string {
    const region = this.selectedRegionSubject.value;
    return region ? region.endpoint : this.REGIONS[0].endpoint;
  }

  public getCurrentRegion(): RegionConfig | null {
    return this.selectedRegionSubject.value;
  }

  public getAllRegions(): RegionConfig[] {
    return [...this.REGIONS];
  }

  public async switchRegion(regionName: string): Promise<boolean> {
    const region = this.REGIONS.find(r => r.name === regionName);
    
    if (!region) {
      console.error(`Region ${regionName} not found`);
      return false;
    }

    const isHealthy = await this.checkRegionHealth(region);
    
    if (!isHealthy) {
      console.error(`Region ${regionName} is unhealthy`);
      return false;
    }

    this.selectRegion(region);
    return true;
  }

  private startHealthMonitoring(): void {
    setInterval(async () => {
      const healthMap = new Map<string, RegionHealth>();

      for (const region of this.REGIONS) {
        const latency = await this.measureLatency(region);
        const healthy = latency < this.LATENCY_THRESHOLD_MS && latency !== Infinity;

        healthMap.set(region.name, {
          region: region.name,
          healthy,
          latency,
          lastChecked: new Date()
        });

        if (latency > this.LATENCY_THRESHOLD_MS && latency !== Infinity) {
          console.warn(`High latency detected for region ${region.name}: ${latency.toFixed(2)}ms`);
          this.reportLatencyMetric(region.name, latency);
        }
      }

      this.regionHealthSubject.next(healthMap);

      const currentRegion = this.selectedRegionSubject.value;
      if (currentRegion) {
        const currentHealth = healthMap.get(currentRegion.name);
        if (currentHealth && !currentHealth.healthy) {
          await this.performFailover();
        }
      }
    }, this.HEALTH_CHECK_INTERVAL_MS);
  }

  private async performFailover(): Promise<void> {
    if (this.failoverInProgressSubject.value) {
      return;
    }

    this.failoverInProgressSubject.next(true);
    console.warn('Performing automatic failover due to unhealthy region');

    try {
      const healthyRegions = this.REGIONS.filter(async r => {
        const health = await this.checkRegionHealth(r);
        return health;
      });

      healthyRegions.sort((a, b) => a.priority - b.priority);

      if (healthyRegions.length > 0) {
        const targetRegion = healthyRegions[0];
        console.log(`Failing over to region: ${targetRegion.displayName}`);
        this.selectRegion(targetRegion);
      } else {
        console.error('No healthy regions available for failover');
      }
    } finally {
      this.failoverInProgressSubject.next(false);
    }
  }

  private reportLatencyMetric(region: string, latency: number): void {
    if (typeof navigator !== 'undefined' && 'sendBeacon' in navigator) {
      const data = JSON.stringify({
        metric: 'cross_region_latency',
        region,
        latency,
        timestamp: new Date().toISOString()
      });
      
      navigator.sendBeacon('/api/metrics/latency', data);
    }
  }

  public async testAllRegions(): Promise<Map<string, number>> {
    const latencies = new Map<string, number>();

    for (const region of this.REGIONS) {
      const latency = await this.measureLatency(region);
      latencies.set(region.name, latency);
    }

    return latencies;
  }

  public getRegionByName(name: string): RegionConfig | undefined {
    return this.REGIONS.find(r => r.name === name);
  }

  public isRegionHealthy(regionName: string): boolean {
    const healthMap = this.regionHealthSubject.value;
    const health = healthMap.get(regionName);
    return health?.healthy ?? false;
  }
}

