    });
  }

  getConsentementStatusLabel(status: ConsentementStatus): string {
    switch (status) {
      case ConsentementStatus.GRANTED: return 'Accordé';
      case ConsentementStatus.DENIED: return 'Refusé';
      case ConsentementStatus.REVOKED: return 'Révoqué';
