  getConsentementStatusBadgeClass(status: ConsentementStatus): string {
    switch (status) {
      case ConsentementStatus.GRANTED: return 'consent-badge consent-granted';
      case ConsentementStatus.DENIED: return 'consent-badge consent-denied';
