  enabled: boolean;
  nextRunDate?: string;
  lastRunDate?: string;
  branding?: {
    logoUrl?: string;
    companyName?: string;
    primaryColor?: string;
  };
  dayOfWeek?: number;
  dayOfMonth?: number;
  time?: string;
}

