        startY: yPosition,
        head: [['Source', 'Count', 'Percentage', 'Conversion Rate']],
        body: data.leadSources.map(source => [
          source.source,
          source.count.toString(),
          `${source.percentage.toFixed(2)}%`,
          `${(source.conversionRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });

      yPosition = (doc as any).lastAutoTable.finalY + 15;
    }

    if (data.conversionFunnel && data.conversionFunnel.length > 0) {
      if (yPosition > 250) {
        doc.addPage();
        yPosition = 20;
      }

      doc.setFontSize(14);
      doc.text('Conversion Funnel', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Stage', 'Count', 'Conversion Rate', 'Drop-off Rate']],
        body: data.conversionFunnel.map(stage => [
          stage.stage,
          stage.count.toString(),
          `${(stage.conversionRate * 100).toFixed(2)}%`,
          `${(stage.dropOffRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });
    }

    doc.save(filename);
  }

  /**
   * Export analytics data to CSV using lazy-loaded PapaParse library.
   *
   * The PapaParse library (~100KB) is loaded on-demand to avoid bloating
   * the initial bundle.
   *
   * @param data - Analytics data to export
   * @param filename - Name of the CSV file (default: 'analytics-report.csv')
   * @returns Promise that resolves when the CSV is downloaded
   *
   * @example
   * ```typescript
   * const data = await this.reportingService.getAnalyticsData().toPromise();
   * await this.reportingService.exportAnalyticsToCSV(data, 'my-report.csv');
   * ```
   */
  async exportAnalyticsToCSV(data: AnalyticsData, filename = 'analytics-report.csv'): Promise<void> {
    const Papa = await import('papaparse');

    const csvSections: string[] = [];

    csvSections.push(`Analytics Report - Date Range: ${data.dateRange.from} to ${data.dateRange.to}\n`);

    if (data.agentPerformance && data.agentPerformance.length > 0) {
      csvSections.push('\nAgent Performance');
      const agentData = data.agentPerformance.map(agent => ({
        'Agent Name': agent.agentName,
        'Total Dossiers': agent.totalDossiers,
        'Closed Dossiers': agent.closedDossiers,
        'Conversion Rate': `${(agent.conversionRate * 100).toFixed(2)}%`,
        'Avg Response Time (hrs)': agent.averageResponseTimeHours.toFixed(2)
      }));
      csvSections.push(Papa.unparse(agentData));
    }

    if (data.leadSources && data.leadSources.length > 0) {
      csvSections.push('\n\nLead Sources');
      const leadSourceData = data.leadSources.map(source => ({
        'Source': source.source,
        'Count': source.count,
        'Percentage': `${source.percentage.toFixed(2)}%`,
        'Conversion Rate': `${(source.conversionRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(leadSourceData));
    }

    if (data.conversionFunnel && data.conversionFunnel.length > 0) {
      csvSections.push('\n\nConversion Funnel');
      const funnelData = data.conversionFunnel.map(stage => ({
        'Stage': stage.stage,
        'Count': stage.count,
        'Conversion Rate': `${(stage.conversionRate * 100).toFixed(2)}%`,
        'Drop-off Rate': `${(stage.dropOffRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(funnelData));
    }

    if (data.revenueForecast && data.revenueForecast.length > 0) {
      csvSections.push('\n\nRevenue Forecast');
      const forecastData = data.revenueForecast.map(forecast => ({
        'Date': forecast.date,
        'Estimated Revenue': forecast.estimatedRevenue,
        'Actual Revenue': forecast.actualRevenue,
        'Pipeline Value': forecast.pipelineValue
      }));
      csvSections.push(Papa.unparse(forecastData));
    }

    const csvContent = csvSections.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }

  /**
   * Export KPI report data to PDF using lazy-loaded jsPDF library.
   *
   * @param data - KPI report data to export
   * @param filename - Name of the PDF file (default: 'kpi-report.pdf')
   * @returns Promise that resolves when the PDF is downloaded
   */
  async exportKpiReportToPDF(data: KpiReportResponse, filename = 'kpi-report.pdf'): Promise<void> {
    const [jsPDFModule] = await Promise.all([
      import('jspdf'),
      import('jspdf-autotable')
    ]);

    const { jsPDF: JsPDFClass } = jsPDFModule;
    const doc = new JsPDFClass();

    doc.setFontSize(18);
    doc.text('KPI Report', 14, 20);

    let yPosition = 35;

    doc.setFontSize(12);
    doc.text('Key Metrics', 14, yPosition);
    yPosition += 8;

    doc.setFontSize(10);
    doc.text(`Average Response Time: ${data.averageResponseTimeHours.toFixed(2)} hours`, 14, yPosition);
    yPosition += 6;
    doc.text(`Appointment Show Rate: ${(data.appointmentShowRate * 100).toFixed(2)}%`, 14, yPosition);
    yPosition += 6;
    doc.text(`Pipeline Velocity: ${data.pipelineVelocityDays.toFixed(2)} days`, 14, yPosition);
    yPosition += 15;

    if (data.conversionRateBySource && data.conversionRateBySource.length > 0) {
      doc.setFontSize(12);
      doc.text('Conversion Rate by Source', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Source', 'Total Dossiers', 'Won Dossiers', 'Conversion Rate']],
        body: data.conversionRateBySource.map(item => [
          item.source,
          item.totalDossiers.toString(),
          item.wonDossiers.toString(),
          `${(item.conversionRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });
    }

    doc.save(filename);
  }

  /**
   * Export KPI report data to CSV using lazy-loaded PapaParse library.
   *
   * @param data - KPI report data to export
   * @param filename - Name of the CSV file (default: 'kpi-report.csv')
   * @returns Promise that resolves when the CSV is downloaded
   */
  async exportKpiReportToCSV(data: KpiReportResponse, filename = 'kpi-report.csv'): Promise<void> {
    const Papa = await import('papaparse');

    const csvSections: string[] = [];

    csvSections.push('KPI Report\n');
    csvSections.push(`Average Response Time (hours),${data.averageResponseTimeHours.toFixed(2)}`);
    csvSections.push(`Appointment Show Rate,${(data.appointmentShowRate * 100).toFixed(2)}%`);
    csvSections.push(`Pipeline Velocity (days),${data.pipelineVelocityDays.toFixed(2)}`);

    if (data.conversionRateBySource && data.conversionRateBySource.length > 0) {
      csvSections.push('\n\nConversion Rate by Source');
      const conversionData = data.conversionRateBySource.map(item => ({
        'Source': item.source,
        'Total Dossiers': item.totalDossiers,
        'Won Dossiers': item.wonDossiers,
        'Conversion Rate': `${(item.conversionRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(conversionData));
    }

    if (data.dossierCreationTimeSeries && data.dossierCreationTimeSeries.length > 0) {
      csvSections.push('\n\nDossier Creation Time Series');
      csvSections.push(Papa.unparse(data.dossierCreationTimeSeries));
    }

    if (data.conversionTimeSeries && data.conversionTimeSeries.length > 0) {
      csvSections.push('\n\nConversion Time Series');
      csvSections.push(Papa.unparse(data.conversionTimeSeries));
    }

    const csvContent = csvSections.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }
}

import { Component, OnInit, OnDestroy } from '@angular/core';
import { FormBuilder, FormGroup, Validators, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { Subject } from 'rxjs';
import { takeUntil, debounceTime, distinctUntilChanged } from 'rxjs/operators';
import { UserPreferencesService } from '../services/user-preferences.service';
import { ThemeService } from '../services/theme.service';
import { NotificationService } from '../services/notification.service';
import { DsCardComponent } from '../design-system';
import { MatIcon } from '@angular/material/icon';
import { MatProgressBar } from '@angular/material/progress-bar';
import { MatRadioGroup, MatRadioButton } from '@angular/material/radio';
import { MatHint, MatFormField, MatLabel, MatPrefix } from '@angular/material/form-field';
import { MatDivider } from '@angular/material/list';
import { MatSelect } from '@angular/material/select';
import { MatOption, MatAutocompleteTrigger, MatAutocomplete } from '@angular/material/autocomplete';
import { MatButtonToggleGroup, MatButtonToggle } from '@angular/material/button-toggle';
import { MatInput } from '@angular/material/input';
import { MatCheckbox } from '@angular/material/checkbox';
import { MatButton } from '@angular/material/button';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';

interface Route {
  path: string;
  label: string;
  icon: string;
}

@Component({
    selector: 'app-ui-preferences-form',
    standalone: true,
    templateUrl: './ui-preferences-form.component.html',
    styleUrls: ['./ui-preferences-form.component.css'],
    imports: [DsCardComponent, DsSkeletonComponent, MatIcon, MatProgressBar, FormsModule, ReactiveFormsModule, MatRadioGroup, MatRadioButton, MatHint, MatDivider, MatFormField, MatLabel, MatSelect, MatOption, MatPrefix, MatButtonToggleGroup, MatButtonToggle, MatInput, MatAutocompleteTrigger, MatAutocomplete, MatCheckbox, MatButton]
})
export class UiPreferencesFormComponent implements OnInit, OnDestroy {
  private destroy$ = new Subject<void>();
  
  preferencesForm!: FormGroup;
  loading = false;
  saving = false;
  
  // Preview state
  previewTheme: 'light' | 'dark' | 'auto' = 'light';
  previewLanguage = 'fr';
  previewDensity: 'compact' | 'comfortable' | 'spacious' = 'comfortable';
  previewDefaultRoute = '/dashboard';
  syncDevices = true;
  
  // Original values for dirty check
  private originalValues: any = {};
  
  // Available options
  themes = [
    { value: 'light', label: 'Clair', icon: 'light_mode' },
    { value: 'dark', label: 'Sombre', icon: 'dark_mode' },
    { value: 'auto', label: 'Auto', icon: 'brightness_auto' }
  ];
  
  languages = [
    { value: 'fr', label: 'Français', flag: '🇫🇷' },
    { value: 'en', label: 'English', flag: '🇬🇧' },
    { value: 'es', label: 'Español', flag: '🇪🇸' }
  ];
  
  densities = [
    { 
      value: 'compact', 
      label: 'Compact', 
      description: 'Maximum de contenu sur l\'écran',
      icon: 'view_compact'
    },
    { 
      value: 'comfortable', 
      label: 'Confortable', 
      description: 'Équilibre entre contenu et espacement',
      icon: 'view_comfortable'
    },
    { 
      value: 'spacious', 
      label: 'Spacieux', 
      description: 'Plus d\'espace, moins de contenu',
      icon: 'view_cozy'
    }
  ];
  
  availableRoutes: Route[] = [
    { path: '/dashboard', label: 'Tableau de bord', icon: 'dashboard' },
    { path: '/dossiers', label: 'Dossiers', icon: 'folder' },
    { path: '/annonces', label: 'Annonces', icon: 'home' },
    { path: '/tasks', label: 'Tâches', icon: 'task' },
    { path: '/calendar', label: 'Calendrier', icon: 'calendar_today' },
    { path: '/search', label: 'Recherche', icon: 'search' },
    { path: '/reports', label: 'Rapports', icon: 'assessment' }
  ];
  
  filteredRoutes: Route[] = [];

  constructor(
    private fb: FormBuilder,
    private userPreferencesService: UserPreferencesService,
    private themeService: ThemeService,
    private notificationService: NotificationService
  ) {}

  ngOnInit(): void {
    this.initializeForm();
    this.loadPreferences();
    this.setupFormListeners();
    this.filteredRoutes = [...this.availableRoutes];
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private initializeForm(): void {
    this.preferencesForm = this.fb.group({
      theme: ['light', Validators.required],
      language: ['fr', Validators.required],
      density: ['comfortable', Validators.required],
      defaultRoute: ['/dashboard', Validators.required],
      syncDevices: [true],
      defaultRouteInput: ['']
    });
  }

  private loadPreferences(): void {
    this.loading = true;
    
    this.userPreferencesService.getPreferences()
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (preferences) => {
          if (preferences.ui) {
            this.preferencesForm.patchValue({
              theme: preferences.ui.theme || 'light',
              language: preferences.ui.language || 'fr',
              density: preferences.ui.density || 'comfortable',
              defaultRoute: preferences.ui.defaultRoute || '/dashboard',
              syncDevices: preferences.ui.syncDevices !== false
            });
            
            this.updatePreviewValues();
          }
          this.originalValues = this.preferencesForm.value;
          this.loading = false;
        },
        error: (error) => {
          console.error('Error loading UI preferences:', error);
          this.notificationService.error('Erreur lors du chargement des préférences');
          this.loading = false;
        }
      });
  }

  private setupFormListeners(): void {
    // Update preview on form changes
    this.preferencesForm.valueChanges
      .pipe(debounceTime(100), distinctUntilChanged(), takeUntil(this.destroy$))
      .subscribe(() => {
        this.updatePreviewValues();
      });
    
    // Autocomplete filter for routes
    this.preferencesForm.get('defaultRouteInput')?.valueChanges
      .pipe(debounceTime(200), distinctUntilChanged(), takeUntil(this.destroy$))
      .subscribe(value => {
        this.filterRoutes(value);
      });
  }

  private updatePreviewValues(): void {
    const formValue = this.preferencesForm.value;
    this.previewTheme = formValue.theme;
    this.previewLanguage = formValue.language;
    this.previewDensity = formValue.density;
    this.previewDefaultRoute = formValue.defaultRoute;
    this.syncDevices = formValue.syncDevices;
  }

  private filterRoutes(searchValue: string): void {
    if (!searchValue) {
      this.filteredRoutes = [...this.availableRoutes];
      return;
    }
    
    const filterValue = searchValue.toLowerCase();
    this.filteredRoutes = this.availableRoutes.filter(route =>
      route.label.toLowerCase().includes(filterValue) ||
      route.path.toLowerCase().includes(filterValue)
    );
  }

  onRouteSelected(route: Route): void {
    this.preferencesForm.patchValue({
      defaultRoute: route.path,
      defaultRouteInput: route.label
    });
  }

  displayRouteFn(path: string): string {
    const route = this.availableRoutes.find(r => r.path === path);
    return route ? route.label : path;
  }

  onSave(): void {
    if (!this.preferencesForm.valid) {
      this.notificationService.warning('Veuillez corriger les erreurs dans le formulaire');
      return;
    }

    this.saving = true;
    const formValue = this.preferencesForm.value;

    const uiPreferences = {
      theme: formValue.theme,
      language: formValue.language,
      density: formValue.density,
      defaultRoute: formValue.defaultRoute,
      syncDevices: formValue.syncDevices
    };

    this.userPreferencesService.updatePreferences('ui', uiPreferences)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          this.themeService.setTheme(formValue.theme);
          this.originalValues = this.preferencesForm.value;
          this.saving = false;
          
          if (formValue.syncDevices) {
            this.notificationService.success('Préférences enregistrées et synchronisées sur tous vos appareils');
          } else {
            this.notificationService.success('Préférences enregistrées avec succès');
          }
        },
        error: (error) => {
          console.error('Error saving UI preferences:', error);
          this.saving = false;
          this.notificationService.error('Erreur lors de l\'enregistrement des préférences');
        }
      });
  }

  onCancel(): void {
    if (this.hasUnsavedChanges()) {
      this.preferencesForm.patchValue(this.originalValues);
      this.updatePreviewValues();
      this.notificationService.info('Modifications annulées');
    }
  }

  hasUnsavedChanges(): boolean {
    return JSON.stringify(this.preferencesForm.value) !== JSON.stringify(this.originalValues);
  }

  getPreviewClasses(): string {
    const classes = ['preview-zone'];
    classes.push(`theme-${this.previewTheme}`);
    classes.push(`density-${this.previewDensity}`);
    classes.push(`lang-${this.previewLanguage}`);
    return classes.join(' ');
  }

  getSelectedRoute(): Route | undefined {
    return this.availableRoutes.find(r => r.path === this.previewDefaultRoute);
  }

  getThemeLabel(): string {
    const theme = this.themes.find(t => t.value === this.previewTheme);
    return theme ? theme.label : '';
  }

  getLanguageLabel(): string {
    const language = this.languages.find(l => l.value === this.previewLanguage);
    return language ? language.label : '';
  }

  getDensityLabel(): string {
    const density = this.densities.find(d => d.value === this.previewDensity);
    return density ? density.label : '';
  }

  getPreviewText(): { welcome: string; description: string; button: string } {
    const texts = {
      fr: {
        welcome: 'Bienvenue',
        description: 'Ceci est un aperçu de vos préférences d\'interface',
        button: 'Action d\'exemple'
      },
      en: {
        welcome: 'Welcome',
        description: 'This is a preview of your interface preferences',
        button: 'Example action'
      },
      es: {
        welcome: 'Bienvenido',
        description: 'Esta es una vista previa de sus preferencias de interfaz',
        button: 'Acción de ejemplo'
      }
    };
    
    return texts[this.previewLanguage as keyof typeof texts] || texts.fr;
  }
}

import { Component, OnInit, OnChanges, SimpleChanges, OnDestroy, input, output } from '@angular/core';
import { MatTableDataSource } from '@angular/material/table';
import { BreakpointObserver, Breakpoints } from '@angular/cdk/layout';
import { SelectionModel } from '@angular/cdk/collections';
import { Subject, takeUntil } from 'rxjs';
import { listStaggerAnimation } from '../animations/list-animations';
import { MatIconButton } from '@angular/material/button';
import { MatIcon } from '@angular/material/icon';
import { MatCheckbox } from '@angular/material/checkbox';
import { CdkVirtualScrollViewport, CdkFixedSizeVirtualScroll, CdkVirtualForOf } from '@angular/cdk/scrolling';
import { DsCardComponent } from '../design-system';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';
import { DsTableComponent, DsColumn, DsRowAction, DsSortEvent } from '../design-system/primitives/ds-table/ds-table.component';

export interface ColumnConfig {
  key: string;
  header: string;
  sortable?: boolean;
  type?: 'text' | 'number' | 'date' | 'boolean' | 'custom';
  format?: (value: unknown, row: unknown) => string;
  resizable?: boolean;
  width?: string;
  minWidth?: string;
}

export interface RowAction {
  icon: string;
  tooltip: string;
  action: 'view' | 'edit' | 'delete' | string;
  color?: string;
  show?: (row: unknown) => boolean;
}

export interface PaginationData {
  number: number;
  totalPages: number;
  first: boolean;
  last: boolean;
}

@Component({
    selector: 'app-generic-table',
    templateUrl: './generic-table.component.html',
    styleUrls: ['./generic-table.component.scss'],
    animations: [listStaggerAnimation],
    imports: [MatIconButton, MatIcon, MatCheckbox, CdkVirtualScrollViewport, CdkFixedSizeVirtualScroll, CdkVirtualForOf, DsCardComponent, DsTableComponent]
})
export class GenericTableComponent implements OnInit, OnChanges, OnDestroy {
  readonly columns = input<ColumnConfig[]>([]);
  readonly data = input<unknown[]>([]);
  readonly showActions = input(true);
  readonly actions = input<RowAction[]>([
    { icon: 'visibility', tooltip: 'Voir', action: 'view', color: 'primary' },
    { icon: 'edit', tooltip: 'Modifier', action: 'edit', color: 'accent' },
    { icon: 'delete', tooltip: 'Supprimer', action: 'delete', color: 'warn' }
  ]);
  readonly pageSize = input(10);
  readonly pageSizeOptions = input<number[]>([5, 10, 25, 50, 100]);
  readonly showPagination = input(true);
  readonly enableSort = input(true);
  readonly rowClickable = input(false);
  readonly enableRowSelection = input(false);
  readonly stickyHeader = input(true);
  readonly enableVirtualScroll = input(false);
  readonly virtualScrollItemSize = input(48);
  readonly useKebabMenu = input(false);
  readonly showTableHeader = input(false);
  readonly showInlinePagination = input(false);
  readonly loading = input(false);
  readonly paginationData = input<PaginationData>();
  readonly counterSingular = input('élément');
  readonly counterPlural = input('éléments');
  readonly enableExport = input(false);
  readonly exportConfig = input<{
    title?: string;
    filename?: string;
    logo?: string;
    primaryColor?: string;
    secondaryColor?: string;
  }>();

  readonly rowAction = output<{
    action: string;
    row: unknown;
  }>();
  readonly rowClick = output<unknown>();
  readonly selectionChange = output<unknown[]>();
  readonly paginationChange = output<'previous' | 'next'>();
  readonly exportRequest = output<{
    format: 'pdf' | 'excel' | 'print';
    data: unknown[];
  }>();

  dataSource = new MatTableDataSource<unknown>([]);
  selection = new SelectionModel<unknown>(true, []);
  isMobile = false;
  currentClientPage = 0;

  private destroy$ = new Subject<void>();

  get dsColumns(): DsColumn<Record<string, unknown>>[] {
    return this.columns().map((column) => ({
      key: column.key,
      header: column.header,
      sortable: column.sortable !== false && this.enableSort(),
      width: column.width,
      cell: (row: Record<string, unknown>) => this.formatValue(row[column.key], column, row),
    }));
  }

  get dsRows(): Record<string, unknown>[] {
    if (!this.showPagination() || this.showInlinePagination()) {
      return this.dataSource.data as Record<string, unknown>[];
    }
    const pageSize = this.pageSize();
    const start = this.currentClientPage * pageSize;
    return this.dataSource.data.slice(start, start + pageSize) as Record<string, unknown>[];
  }

  get dsSelectedRows(): Record<string, unknown>[] {
    return this.selection.selected as Record<string, unknown>[];
  }

  get dsClientTotalPages(): number {
    if (!this.showPagination() || this.showInlinePagination()) {
      return 1;
    }
    return Math.max(1, Math.ceil(this.dataSource.data.length / this.pageSize()));
  }

  get dsClientPageNumber(): number {
    return this.currentClientPage + 1;
  }

  get dsRowActions(): DsRowAction<Record<string, unknown>>[] {
    if (!this.showActions()) {
      return [];
    }
    return this.actions().map((action) => ({
      action: action.action,
      label: action.tooltip,
      ariaLabel: action.tooltip || action.action,
      icon: this.mapMaterialIconToDs(action.icon),
      show: action.show as ((row: Record<string, unknown>) => boolean) | undefined,
    }));
  }

  constructor(private breakpointObserver: BreakpointObserver) {}

  ngOnInit(): void {
    this.dataSource.data = this.data();
    this.observeBreakpoints();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['data']) {
      this.dataSource.data = this.data();
      this.selection.clear();
      this.currentClientPage = 0;
    }
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  observeBreakpoints(): void {
    this.breakpointObserver
      .observe([Breakpoints.XSmall, Breakpoints.Small])
      .pipe(takeUntil(this.destroy$))
      .subscribe(result => {
        this.isMobile = result.matches;
      });
  }

  onAction(action: string, row: unknown): void {
    this.rowAction.emit({ action, row });
  }

  shouldShowAction(action: RowAction, row: unknown): boolean {
    if (action.show) {
      return action.show(row);
    }
    return true;
  }

  formatValue(value: unknown, column: ColumnConfig, row: unknown): string {
    if (column.format) {
      return column.format(value, row);
    }

    if (value === null || value === undefined) {
      return '';
    }

    switch (column.type) {
      case 'date':
        return new Date(value as string | number | Date).toLocaleDateString();
      case 'boolean':
        return value ? 'Oui' : 'Non';
      case 'number':
        return value.toString();
      default:
        return value.toString();
    }
  }

  onRowClick(row: unknown): void {
    if (this.rowClickable()) {
      this.rowClick.emit(row);
    }
  }

  isAllSelected(): boolean {
    const numSelected = this.selection.selected.length;
    const numRows = this.dataSource.data.length;
    return numSelected === numRows && numRows > 0;
  }

  toggleAllRows(): void {
    if (this.isAllSelected()) {
      this.selection.clear();
    } else {
      this.selection.select(...this.dataSource.data);
    }
    this.emitSelectionChange();
  }

  toggleRow(row: unknown): void {
    this.selection.toggle(row);
    this.emitSelectionChange();
  }

  emitSelectionChange(): void {
    this.selectionChange.emit(this.selection.selected);
  }

  getRowValue(row: unknown, columnKey: string): unknown {
    return (row as any)[columnKey];
  }

  trackByColumnKey(index: number, column: ColumnConfig): string {
    return column.key;
  }

  trackByAction(index: number, action: RowAction): string {
    return action.action;
  }

  trackByRowId(index: number, row: unknown): number | string {
    return (row as any)['id'] ?? index;
  }

  onPaginationChange(direction: 'previous' | 'next'): void {
    if (this.showInlinePagination()) {
      this.paginationChange.emit(direction);
      return;
    }
    const totalPages = this.dsClientTotalPages;
    if (direction === 'previous') {
      this.currentClientPage = Math.max(0, this.currentClientPage - 1);
    } else {
      this.currentClientPage = Math.min(totalPages - 1, this.currentClientPage + 1);
    }
  }

  onDsSort(event: DsSortEvent): void {
    const direction = event.direction === 'asc' ? 1 : -1;
    const sorted = [...this.dataSource.data].sort((a, b) => {
      const aValue = (a as Record<string, unknown>)[event.column];
      const bValue = (b as Record<string, unknown>)[event.column];
      if (aValue == null && bValue == null) return 0;
      if (aValue == null) return -1 * direction;
      if (bValue == null) return 1 * direction;
      return String(aValue).localeCompare(String(bValue), undefined, { numeric: true }) * direction;
    });
    this.dataSource.data = sorted;
  }

  onDsSelectionChange(rows: Record<string, unknown>[]): void {
    this.selection.clear();
    this.selection.select(...(rows as unknown[]));
    this.emitSelectionChange();
  }

  private mapMaterialIconToDs(icon: string): string {
    const iconMap: Record<string, string> = {
      visibility: 'eye',
      edit: 'edit',
      delete: 'trash-2',
      more_vert: 'more-horizontal',
      picture_as_pdf: 'file-text',
      table_chart: 'table',
      print: 'printer',
    };
    return iconMap[icon] || 'more-horizontal';
  }

  getActionColor(color?: string): string {
    const colorMap: { [key: string]: string } = {
      primary: DS_CHART_FALLBACK_HEX['--ds-marine'],
      accent: DS_CHART_FALLBACK_HEX['--ds-primary'],
      warn: DS_CHART_FALLBACK_HEX['--ds-error'],
      success: DS_CHART_FALLBACK_HEX['--ds-success'],
      error: DS_CHART_FALLBACK_HEX['--ds-error'],
      warning: DS_CHART_FALLBACK_HEX['--ds-warning'],
    };
    return color ? (colorMap[color] || color) : colorMap['primary'];
  }

  hasSelection(): boolean {
    return this.selection.hasValue() && this.selection.selected.length > 0;
  }

  getSelectedCount(): number {
    return this.selection.selected.length;
  }

  exportToPDF(): void {
    const dataToExport = this.hasSelection() ? this.selection.selected : this.dataSource.data;
    this.exportRequest.emit({ format: 'pdf', data: dataToExport });
  }

  exportToExcel(): void {
    const dataToExport = this.hasSelection() ? this.selection.selected : this.dataSource.data;
    this.exportRequest.emit({ format: 'excel', data: dataToExport });
  }

  printTable(): void {
    const dataToExport = this.hasSelection() ? this.selection.selected : this.dataSource.data;
    this.exportRequest.emit({ format: 'print', data: dataToExport });
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export type ScheduleFrequency = 'daily' | 'weekly' | 'monthly';

export interface ReportSchedule {
  id?: number;
  name: string;
  reportType: string;
  frequency: ScheduleFrequency;
  recipients: string[];
  format: 'pdf' | 'csv' | 'excel';
  parameters?: Record<string, any>;
  enabled: boolean;
  nextRunDate?: string;
  lastRunDate?: string;
  branding?: {
    logoUrl?: string;
    companyName?: string;
    primaryColor?: string;
  };
  dayOfWeek?: number;
  dayOfMonth?: number;
  time?: string;
}

export interface ScheduledReportExecution {
  id: number;
  scheduleId: number;
  executionDate: string;
  status: 'pending' | 'running' | 'completed' | 'failed';
  errorMessage?: string;
  recipientCount?: number;
}

@Injectable({
  providedIn: 'root'
})
export class ReportSchedulingService {
  private readonly apiUrl = '/api/v1/report-schedules';

  constructor(private http: HttpClient) {}

  createSchedule(schedule: ReportSchedule): Observable<ReportSchedule> {
    return this.http.post<ReportSchedule>(this.apiUrl, schedule);
  }

  updateSchedule(id: number, schedule: ReportSchedule): Observable<ReportSchedule> {
    return this.http.put<ReportSchedule>(`${this.apiUrl}/${id}`, schedule);
  }

  deleteSchedule(id: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/${id}`);
  }

  getSchedule(id: number): Observable<ReportSchedule> {
    return this.http.get<ReportSchedule>(`${this.apiUrl}/${id}`);
  }

  listSchedules(): Observable<ReportSchedule[]> {
    return this.http.get<ReportSchedule[]>(this.apiUrl);
  }

  enableSchedule(id: number): Observable<void> {
    return this.http.post<void>(`${this.apiUrl}/${id}/enable`, {});
  }

  disableSchedule(id: number): Observable<void> {
    return this.http.post<void>(`${this.apiUrl}/${id}/disable`, {});
  }

  executeNow(id: number): Observable<ScheduledReportExecution> {
    return this.http.post<ScheduledReportExecution>(`${this.apiUrl}/${id}/execute`, {});
  }

  getExecutionHistory(scheduleId: number): Observable<ScheduledReportExecution[]> {
    return this.http.get<ScheduledReportExecution[]>(`${this.apiUrl}/${scheduleId}/executions`);
  }

  async generateScheduledPdfReport(
    reportData: any,
    schedule: ReportSchedule
  ): Promise<Blob> {
    const [jsPDFModule] = await Promise.all([
      import('jspdf'),
      import('jspdf-autotable')
    ]);

    const { jsPDF: JsPDFClass } = jsPDFModule;
    const doc = new JsPDFClass();

    let yPosition = 20;

    if (schedule.branding?.logoUrl) {
      try {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.src = schedule.branding.logoUrl;
        await new Promise((resolve, reject) => {
          img.onload = resolve;
          img.onerror = reject;
        });
        doc.addImage(img, 'PNG', 14, 10, 30, 15);
        yPosition = 35;
      } catch (error) {
        console.warn('Failed to load logo image', error);
      }
    }

    if (schedule.branding?.companyName) {
      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(schedule.branding.companyName, 200, 15, { align: 'right' });
    }

    doc.setFontSize(18);
    doc.setTextColor(0);
    doc.text(schedule.name, 14, yPosition);
    yPosition += 10;

    doc.setFontSize(11);
    doc.setTextColor(100);
    const reportDate = new Date().toLocaleDateString('fr-FR');
    doc.text(`Generated on: ${reportDate}`, 14, yPosition);
    yPosition += 15;

    if (reportData.summary) {
      doc.setFontSize(12);
      doc.setTextColor(0);
      doc.text('Summary', 14, yPosition);
      yPosition += 8;
      
      doc.setFontSize(10);
      doc.setTextColor(60);
      doc.text(reportData.summary, 14, yPosition, { maxWidth: 180 });
      yPosition += 20;
    }

    if (reportData.tables && reportData.tables.length > 0) {
      reportData.tables.forEach((table: any) => {
        if (yPosition > 250) {
          doc.addPage();
          yPosition = 20;
        }

        doc.setFontSize(14);
        doc.setTextColor(0);
        doc.text(table.title, 14, yPosition);
        yPosition += 10;

        (doc as any).autoTable({
          startY: yPosition,
          head: [table.headers],
          body: table.rows,
          theme: 'grid',
          styles: { fontSize: 10 },
          headStyles: {
            fillColor: schedule.branding?.primaryColor 
              ? this.hexToRgb(schedule.branding.primaryColor) 
              : [66, 139, 202]
          }
        });

        yPosition = (doc as any).lastAutoTable.finalY + 15;
      });
    }

    if (schedule.branding?.companyName) {
      const pageCount = (doc as any).internal.getNumberOfPages();
      for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150);
        doc.text(
          `${schedule.branding.companyName} - Page ${i} of ${pageCount}`,
          doc.internal.pageSize.width / 2,
          doc.internal.pageSize.height - 10,
          { align: 'center' }
        );
      }
    }

    return doc.output('blob');
  }

  private hexToRgb(hex: string): [number, number, number] {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? [
      parseInt(result[1], 16),
      parseInt(result[2], 16),
      parseInt(result[3], 16)
    ] : [66, 139, 202];
  }

  calculateNextRunDate(frequency: ScheduleFrequency, dayOfWeek?: number, dayOfMonth?: number, time?: string): Date {
    const now = new Date();
    const nextRun = new Date(now);

    const [hours, minutes] = time ? time.split(':').map(Number) : [9, 0];
    nextRun.setHours(hours, minutes, 0, 0);

    switch (frequency) {
      case 'daily':
        if (nextRun <= now) {
          nextRun.setDate(nextRun.getDate() + 1);
        }
        break;

      case 'weekly': {
        const targetDay = dayOfWeek ?? 1;
        const currentDay = nextRun.getDay();
        let daysToAdd = targetDay - currentDay;
        if (daysToAdd <= 0 || (daysToAdd === 0 && nextRun <= now)) {
          daysToAdd += 7;
        }
        nextRun.setDate(nextRun.getDate() + daysToAdd);
        break;
      }

      case 'monthly': {
        const targetDate = dayOfMonth ?? 1;
        nextRun.setDate(targetDate);
        if (nextRun <= now) {
          nextRun.setMonth(nextRun.getMonth() + 1);
        }
        break;
      }
    }

    return nextRun;
  }
}

