export class SwipeableCardComponent {
  @Input() leftAction?: SwipeAction;
  @Input() rightAction?: SwipeAction;
  @Input() swipeThreshold = 100;
  
  @Output() swipeLeft = new EventEmitter<void>();
  @Output() swipeRight = new EventEmitter<void>();

  isSwiping = false;
  swipeDistance = 0;
  startX = 0;
  startY = 0;
  currentX = 0;

  constructor(private elementRef: ElementRef) {}

  onTouchStart(event: TouchEvent): void {
    if (event.touches.length !== 1) return;
    
    this.isSwiping = true;
    this.startX = event.touches[0].clientX;
    this.startY = event.touches[0].clientY;
  }

  onTouchMove(event: TouchEvent): void {
    if (!this.isSwiping || event.touches.length !== 1) return;

    const touch = event.touches[0];
    const deltaX = touch.clientX - this.startX;
    const deltaY = touch.clientY - this.startY;

    // Only swipe horizontally if horizontal movement is greater
    if (Math.abs(deltaX) > Math.abs(deltaY)) {
      event.preventDefault();
      this.currentX = deltaX;
      this.updateSwipeDistance();
    }
  }

  onTouchEnd(): void {
    if (!this.isSwiping) return;

    this.isSwiping = false;
    this.handleSwipeEnd();
  }

  onMouseDown(event: MouseEvent): void {
    this.isSwiping = true;
    this.startX = event.clientX;
    this.startY = event.clientY;

    const onMouseMove = (e: MouseEvent) => {
      if (!this.isSwiping) return;
      
      const deltaX = e.clientX - this.startX;
      const deltaY = e.clientY - this.startY;

      if (Math.abs(deltaX) > Math.abs(deltaY)) {
        e.preventDefault();
        this.currentX = deltaX;
        this.updateSwipeDistance();
      }
    };

    const onMouseUp = () => {
      this.isSwiping = false;
      this.handleSwipeEnd();
      document.removeEventListener('mousemove', onMouseMove);
      document.removeEventListener('mouseup', onMouseUp);
    };

    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
  }

  private updateSwipeDistance(): void {
    const maxDistance = 150;
    
    // Limit swipe distance
    if (this.currentX > 0 && this.rightAction) {
      this.swipeDistance = Math.min(this.currentX, maxDistance);
    } else if (this.currentX < 0 && this.leftAction) {
      this.swipeDistance = Math.max(this.currentX, -maxDistance);
    } else {
      this.swipeDistance = 0;
    }
  }

  private handleSwipeEnd(): void {
    if (Math.abs(this.swipeDistance) > this.swipeThreshold) {
      // Trigger action
      if (this.swipeDistance > 0) {
        this.swipeRight.emit();
      } else {
        this.swipeLeft.emit();
      }
    }

    // Reset
    this.swipeDistance = 0;
    this.currentX = 0;
  }

  getTransform(): string {
    return '';
  }

  getContentTransform(): string {
    if (this.swipeDistance !== 0) {
      return `translateX(${this.swipeDistance}px)`;
    }
    return '';
  }
}

import { Directive, ElementRef, EventEmitter, HostListener, Input, Output, OnDestroy } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import { Haptics, ImpactStyle } from '@capacitor/haptics';

export interface SwipeEvent {
  direction: 'left' | 'right' | 'up' | 'down';
  distance: number;
  velocity: number;
}

export interface PinchEvent {
  scale: number;
  centerX: number;
  centerY: number;
}

/**
 * Directive for mobile gesture handling
 * Provides swipe, long-press, pinch-zoom, and double-tap gestures
 */
@Directive({
  selector: '[appMobileGestures]',
  standalone: true
})
export class MobileGesturesDirective implements OnDestroy {
  @Input() swipeThreshold = 50; // pixels
  @Input() longPressDelay = 500; // ms
  @Input() doubleTapDelay = 300; // ms
  @Input() enableHaptics = true;
  @Input() preventContextMenu = true;

  @Output() swipe = new EventEmitter<SwipeEvent>();
  @Output() swipeLeft = new EventEmitter<SwipeEvent>();
  @Output() swipeRight = new EventEmitter<SwipeEvent>();
  @Output() swipeUp = new EventEmitter<SwipeEvent>();
  @Output() swipeDown = new EventEmitter<SwipeEvent>();
  @Output() longPress = new EventEmitter<TouchEvent>();
  @Output() doubleTap = new EventEmitter<TouchEvent>();
  @Output() pinch = new EventEmitter<PinchEvent>();

  private touchStartX = 0;
  private touchStartY = 0;
  private touchStartTime = 0;
  private lastTapTime = 0;
  private longPressTimer: any;
  private initialPinchDistance = 0;
  private isNative = Capacitor.isNativePlatform();

  constructor(private el: ElementRef) {
    if (this.preventContextMenu) {
      this.el.nativeElement.style.webkitTouchCallout = 'none';
      this.el.nativeElement.style.webkitUserSelect = 'none';
      this.el.nativeElement.style.userSelect = 'none';
    }
  }

  @HostListener('touchstart', ['$event'])
  onTouchStart(event: TouchEvent): void {
    if (event.touches.length === 1) {
      this.handleSingleTouchStart(event);
    } else if (event.touches.length === 2) {
      this.handlePinchStart(event);
    }
  }

  @HostListener('touchmove', ['$event'])
  onTouchMove(event: TouchEvent): void {
    if (event.touches.length === 2) {
      this.handlePinchMove(event);
    } else if (this.longPressTimer) {
      // Cancel long press if finger moves
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }
  }

  @HostListener('touchend', ['$event'])
  onTouchEnd(event: TouchEvent): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }

    if (event.changedTouches.length === 1) {
      this.handleSingleTouchEnd(event);
    }

    this.initialPinchDistance = 0;
  }

  @HostListener('touchcancel')
  onTouchCancel(): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }
    this.initialPinchDistance = 0;
  }

  @HostListener('contextmenu', ['$event'])
  onContextMenu(event: Event): void {
    if (this.preventContextMenu) {
      event.preventDefault();
      return;
    }
  }

  private handleSingleTouchStart(event: TouchEvent): void {
    const touch = event.touches[0];
    this.touchStartX = touch.clientX;
    this.touchStartY = touch.clientY;
    this.touchStartTime = Date.now();

    // Setup long press detection
    this.longPressTimer = setTimeout(() => {
      this.handleLongPress(event);
    }, this.longPressDelay);
  }

  private handleSingleTouchEnd(event: TouchEvent): void {
    const touch = event.changedTouches[0];
    const touchEndX = touch.clientX;
    const touchEndY = touch.clientY;
    const touchEndTime = Date.now();

    const deltaX = touchEndX - this.touchStartX;
    const deltaY = touchEndY - this.touchStartY;
    const deltaTime = touchEndTime - this.touchStartTime;
    const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);

    // Check for swipe
    if (distance > this.swipeThreshold && deltaTime < 1000) {
      this.handleSwipe(deltaX, deltaY, distance, deltaTime);
      return;
    }

    // Check for double tap
    const timeSinceLastTap = touchEndTime - this.lastTapTime;
    if (timeSinceLastTap < this.doubleTapDelay && distance < 10) {
      this.handleDoubleTap(event);
      this.lastTapTime = 0;
    } else {
      this.lastTapTime = touchEndTime;
    }
  }

  private handleSwipe(deltaX: number, deltaY: number, distance: number, deltaTime: number): void {
    const velocity = distance / deltaTime;
    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);

    let direction: 'left' | 'right' | 'up' | 'down';

    if (absX > absY) {
      direction = deltaX > 0 ? 'right' : 'left';
    } else {
      direction = deltaY > 0 ? 'down' : 'up';
    }

    const swipeEvent: SwipeEvent = { direction, distance, velocity };

    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Light });
    }

    this.swipe.emit(swipeEvent);

    switch (direction) {
      case 'left':
        this.swipeLeft.emit(swipeEvent);
        break;
      case 'right':
        this.swipeRight.emit(swipeEvent);
        break;
      case 'up':
        this.swipeUp.emit(swipeEvent);
        break;
      case 'down':
        this.swipeDown.emit(swipeEvent);
        break;
    }
  }

  private handleLongPress(event: TouchEvent): void {
    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Medium });
    }

    this.longPress.emit(event);
    this.longPressTimer = null;
  }

  private handleDoubleTap(event: TouchEvent): void {
    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Light });
    }

    this.doubleTap.emit(event);
  }

  private handlePinchStart(event: TouchEvent): void {
    const touch1 = event.touches[0];
    const touch2 = event.touches[1];
    
    this.initialPinchDistance = this.getDistance(
      touch1.clientX, touch1.clientY,
      touch2.clientX, touch2.clientY
    );
  }

  private handlePinchMove(event: TouchEvent): void {
    if (this.initialPinchDistance === 0) {
      return;
    }

    event.preventDefault();

    const touch1 = event.touches[0];
    const touch2 = event.touches[1];
    
    const currentDistance = this.getDistance(
      touch1.clientX, touch1.clientY,
      touch2.clientX, touch2.clientY
    );

    const scale = currentDistance / this.initialPinchDistance;
    const centerX = (touch1.clientX + touch2.clientX) / 2;
    const centerY = (touch1.clientY + touch2.clientY) / 2;

    this.pinch.emit({ scale, centerX, centerY });
  }

  private getDistance(x1: number, y1: number, x2: number, y2: number): number {
    const dx = x2 - x1;
    const dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  ngOnDestroy(): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
    }
  }
}

import { Directive, ElementRef, HostListener, input, output } from '@angular/core';

export interface SwipeEvent {
  direction: 'left' | 'right' | 'up' | 'down';
  deltaX: number;
  deltaY: number;
  target: HTMLElement;
}

@Directive({ selector: '[appSwipeGesture]' })
export class SwipeGestureDirective {
  readonly swipeThreshold = input(50);
  readonly swipeVelocityThreshold = input(0.3);
  readonly enableSwipeLeft = input(true);
  readonly enableSwipeRight = input(true);
  readonly enableSwipeUp = input(false);
  readonly enableSwipeDown = input(false);
  
  readonly swipe = output<SwipeEvent>();
  readonly swipeLeft = output<SwipeEvent>();
  readonly swipeRight = output<SwipeEvent>();
  readonly swipeUp = output<SwipeEvent>();
  readonly swipeDown = output<SwipeEvent>();
  readonly swipeStart = output<TouchEvent>();
  readonly swipeMove = output<{
    progress: number;
    direction: string;
}>();
  readonly swipeCancel = output<void>();

  private startX = 0;
  private startY = 0;
  private startTime = 0;
  private isSwiping = false;
  private currentDirection: 'left' | 'right' | 'up' | 'down' | null = null;

  constructor(private el: ElementRef<HTMLElement>) {}

  @HostListener('touchstart', ['$event'])
  onTouchStart(event: TouchEvent): void {
    this.startX = event.touches[0].clientX;
    this.startY = event.touches[0].clientY;
    this.startTime = Date.now();
    this.isSwiping = true;
    this.currentDirection = null;
    this.swipeStart.emit(event);
  }

  @HostListener('touchmove', ['$event'])
  onTouchMove(event: TouchEvent): void {
    if (!this.isSwiping) return;

    const currentX = event.touches[0].clientX;
    const currentY = event.touches[0].clientY;
    const deltaX = currentX - this.startX;
    const deltaY = currentY - this.startY;

    const absDeltaX = Math.abs(deltaX);
    const absDeltaY = Math.abs(deltaY);

    // Determine direction
    if (absDeltaX > absDeltaY) {
      this.currentDirection = deltaX > 0 ? 'right' : 'left';
      const progress = Math.min(Math.abs(deltaX) / this.swipeThreshold(), 1);
      this.swipeMove.emit({ progress, direction: this.currentDirection });
    } else {
      this.currentDirection = deltaY > 0 ? 'down' : 'up';
      const progress = Math.min(Math.abs(deltaY) / this.swipeThreshold(), 1);
      this.swipeMove.emit({ progress, direction: this.currentDirection });
    }
  }

  @HostListener('touchend', ['$event'])
  onTouchEnd(event: TouchEvent): void {
    if (!this.isSwiping) return;

    const endX = event.changedTouches[0].clientX;
    const endY = event.changedTouches[0].clientY;
    const deltaX = endX - this.startX;
    const deltaY = endY - this.startY;
    const deltaTime = Date.now() - this.startTime;

    const absDeltaX = Math.abs(deltaX);
    const absDeltaY = Math.abs(deltaY);
    const velocity = Math.max(absDeltaX, absDeltaY) / deltaTime;

    // Determine if it's a valid swipe
    if (velocity >= this.swipeVelocityThreshold() || absDeltaX >= this.swipeThreshold() || absDeltaY >= this.swipeThreshold()) {
      if (absDeltaX > absDeltaY) {
        // Horizontal swipe
        if (deltaX > 0 && this.enableSwipeRight()) {
          this.emitSwipe('right', deltaX, deltaY);
        } else if (deltaX < 0 && this.enableSwipeLeft()) {
          this.emitSwipe('left', deltaX, deltaY);
        }
      } else {
        // Vertical swipe
        if (deltaY > 0 && this.enableSwipeDown()) {
          this.emitSwipe('down', deltaX, deltaY);
        } else if (deltaY < 0 && this.enableSwipeUp()) {
          this.emitSwipe('up', deltaX, deltaY);
        }
      }
    } else {
      // TODO: The 'emit' function requires a mandatory void argument
      this.swipeCancel.emit();
    }

    this.isSwiping = false;
    this.currentDirection = null;
  }

  @HostListener('touchcancel')
  onTouchCancel(): void {
    this.isSwiping = false;
    this.currentDirection = null;
    // TODO: The 'emit' function requires a mandatory void argument
    this.swipeCancel.emit();
  }

  private emitSwipe(direction: 'left' | 'right' | 'up' | 'down', deltaX: number, deltaY: number): void {
    const swipeEvent: SwipeEvent = {
      direction,
      deltaX,
      deltaY,
      target: this.el.nativeElement
    };

    this.swipe.emit(swipeEvent);

    switch (direction) {
      case 'left':
        this.swipeLeft.emit(swipeEvent);
        break;
      case 'right':
        this.swipeRight.emit(swipeEvent);
        break;
      case 'up':
        this.swipeUp.emit(swipeEvent);
        break;
      case 'down':
        this.swipeDown.emit(swipeEvent);
        break;
    }
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, interval } from 'rxjs';
import { filter } from 'rxjs/operators';
import { OfflineService } from './offline.service';
import { OfflineStorageService } from './offline-storage.service';
import { HttpClient } from '@angular/common/http';
import { NotificationService } from './notification.service';

export enum QueuedActionType {
  CREATE_MESSAGE = 'CREATE_MESSAGE',
  UPDATE_DOSSIER_STATUS = 'UPDATE_DOSSIER_STATUS',
  CREATE_APPOINTMENT = 'CREATE_APPOINTMENT',
  UPDATE_APPOINTMENT = 'UPDATE_APPOINTMENT',
  CREATE_NOTE = 'CREATE_NOTE'
}

export enum QueuedActionStatus {
  PENDING = 'PENDING',
  SYNCING = 'SYNCING',
  SUCCESS = 'SUCCESS',
  FAILED = 'FAILED',
  CONFLICT = 'CONFLICT'
}

export interface QueuedAction {
  id: string;
  type: QueuedActionType;
  payload: any;
  timestamp: number;
  status: QueuedActionStatus;
  retryCount: number;
  error?: string;
  localId?: string;
  serverId?: number;
}

export interface SyncProgress {
  total: number;
  completed: number;
  failed: number;
  inProgress: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class OfflineQueueService {
  private syncProgressSubject = new BehaviorSubject<SyncProgress>({
    total: 0,
    completed: 0,
    failed: 0,
    inProgress: false
  });

  public syncProgress$: Observable<SyncProgress> = this.syncProgressSubject.asObservable();

  private readonly SYNC_INTERVAL = 30000; // 30 seconds
  private readonly MAX_RETRY_COUNT = 3;
  private isSyncing = false;

  constructor(
    private offlineService: OfflineService,
    private storageService: OfflineStorageService,
    private http: HttpClient,
    private notificationService: NotificationService
  ) {
    this.initializeBackgroundSync();
  }

  private initializeBackgroundSync(): void {
    this.offlineService.connectivity$
      .pipe(
        filter(state => state.status !== 'OFFLINE')
      )
      .subscribe(() => {
        this.syncQueue();
      });

    interval(this.SYNC_INTERVAL)
      .pipe(
        filter(() => this.offlineService.isOnline() && !this.isSyncing)
      )
      .subscribe(() => {
        this.syncQueue();
      });

    if ('serviceWorker' in navigator && (self as any).registration && 'sync' in (self as any).registration) {
      navigator.serviceWorker.ready.then(registration => {
        return (registration as any).sync.register('offline-queue-sync');
      }).catch(err => {
        console.warn('Background sync not supported:', err);
      });
    }
  }

  async queueAction(action: Omit<QueuedAction, 'id' | 'timestamp' | 'status' | 'retryCount'>): Promise<string> {
    const queuedAction: QueuedAction = {
      ...action,
      id: this.generateId(),
      timestamp: Date.now(),
      status: QueuedActionStatus.PENDING,
      retryCount: 0
    };

    await this.storageService.addQueuedAction(queuedAction);
    
    this.notificationService.info('Action mise en file d\'attente', 'Voir');

    if (this.offlineService.isOnline()) {
      setTimeout(() => this.syncQueue(), 100);
    }

    return queuedAction.id;
  }

  async syncQueue(): Promise<void> {
    if (this.isSyncing || !this.offlineService.isOnline()) {
      return;
    }

    this.isSyncing = true;
    const pendingActions = await this.storageService.getPendingActions();

    if (pendingActions.length === 0) {
      this.isSyncing = false;
      return;
    }

    this.syncProgressSubject.next({
      total: pendingActions.length,
      completed: 0,
      failed: 0,
      inProgress: true
    });

    let completed = 0;
    let failed = 0;

    for (const action of pendingActions) {
      try {
        await this.syncAction(action);
        completed++;
        this.notificationService.success(`Action synchronisée: ${this.getActionLabel(action.type)}`);
      } catch (error: any) {
        failed++;
        action.retryCount++;
        action.error = error.message || 'Unknown error';

        if (action.retryCount >= this.MAX_RETRY_COUNT) {
          action.status = QueuedActionStatus.FAILED;
          this.notificationService.error(
            `Échec de synchronisation: ${this.getActionLabel(action.type)}`,
            'Réessayer',
            () => this.retryAction(action.id)
          );
        } else {
          action.status = QueuedActionStatus.PENDING;
        }

        await this.storageService.updateQueuedAction(action);
      }

      this.syncProgressSubject.next({
        total: pendingActions.length,
        completed,
        failed,
        inProgress: true
      });
    }

    this.syncProgressSubject.next({
      total: pendingActions.length,
      completed,
      failed,
      inProgress: false
    });

    this.isSyncing = false;

    if (completed > 0) {
      this.notificationService.success(`${completed} action(s) synchronisée(s) avec succès`);
    }
  }

  private async syncAction(action: QueuedAction): Promise<void> {
    action.status = QueuedActionStatus.SYNCING;
    await this.storageService.updateQueuedAction(action);

    let response: any;

    switch (action.type) {
      case QueuedActionType.CREATE_MESSAGE:
        response = await this.http.post('/api/v1/messages', action.payload).toPromise();
        break;

      case QueuedActionType.UPDATE_DOSSIER_STATUS:
        response = await this.http.patch(
          `/api/v1/dossiers/${action.payload.id}/status`,
          { status: action.payload.status }
        ).toPromise();
        break;

      case QueuedActionType.CREATE_APPOINTMENT:
        response = await this.http.post('/api/v1/appointments', action.payload).toPromise();
        break;

      case QueuedActionType.UPDATE_APPOINTMENT:
        response = await this.http.put(
          `/api/v1/appointments/${action.payload.id}`,
          action.payload
        ).toPromise();
        break;

      case QueuedActionType.CREATE_NOTE:
        response = await this.http.post('/api/v1/notes', action.payload).toPromise();
        break;

      default:
        throw new Error(`Unknown action type: ${action.type}`);
    }

    action.status = QueuedActionStatus.SUCCESS;
    action.serverId = response?.id;
    await this.storageService.updateQueuedAction(action);

    if (action.localId && response?.id) {
      await this.storageService.mapLocalToServerId(action.localId, response.id);
    }
  }

  async retryAction(actionId: string): Promise<void> {
    const action = await this.storageService.getQueuedAction(actionId);
    if (action) {
      action.status = QueuedActionStatus.PENDING;
      action.retryCount = 0;
      action.error = undefined;
      await this.storageService.updateQueuedAction(action);
      
      if (this.offlineService.isOnline()) {
        await this.syncQueue();
      }
    }
  }

  async clearQueue(): Promise<void> {
    await this.storageService.clearQueue();
    this.syncProgressSubject.next({
      total: 0,
      completed: 0,
      failed: 0,
      inProgress: false
    });
  }

  async getPendingActionsCount(): Promise<number> {
    const actions = await this.storageService.getPendingActions();
    return actions.length;
  }

  async getFailedActions(): Promise<QueuedAction[]> {
    return this.storageService.getFailedActions();
  }

  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  private getActionLabel(type: QueuedActionType): string {
    const labels: Record<QueuedActionType, string> = {
      [QueuedActionType.CREATE_MESSAGE]: 'Création de message',
      [QueuedActionType.UPDATE_DOSSIER_STATUS]: 'Changement de statut',
      [QueuedActionType.CREATE_APPOINTMENT]: 'Création de rendez-vous',
      [QueuedActionType.UPDATE_APPOINTMENT]: 'Mise à jour de rendez-vous',
      [QueuedActionType.CREATE_NOTE]: 'Création de note'
    };
    return labels[type] || type;
  }
}

import { Component, OnInit, OnDestroy } from '@angular/core';
import { FormBuilder, FormGroup, Validators, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { Subject } from 'rxjs';
import { takeUntil, debounceTime, distinctUntilChanged } from 'rxjs/operators';
import { UserPreferencesService } from '../services/user-preferences.service';
import { ThemeService } from '../services/theme.service';
import { NotificationService } from '../services/notification.service';
import { AuthService } from '../services/auth.service';
import { DEFAULT_PREFERENCES } from '../models/user-preferences.model';
import { MatIcon } from '@angular/material/icon';
import { MatProgressBar } from '@angular/material/progress-bar';
import { MatTabGroup, MatTab, MatTabLabel } from '@angular/material/tabs';
import { DsCardComponent, DsButtonComponent, DsIconComponent } from '../design-system';
import { MatFormField, MatLabel, MatPrefix, MatHint } from '@angular/material/form-field';
import { MatSelect } from '@angular/material/select';
import { MatOption } from '@angular/material/autocomplete';
import { MatCheckbox } from '@angular/material/checkbox';
import { MatSlideToggle } from '@angular/material/slide-toggle';
import { MatDivider } from '@angular/material/list';
import { MatButtonToggleGroup, MatButtonToggle } from '@angular/material/button-toggle';
import { MatInput } from '@angular/material/input';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';

interface TabConfig {
