@Injectable({
  providedIn: 'root'
})
export class ReportingApiService {
  private readonly apiUrl = '/api/v1/reports';

  constructor(private http: HttpClient) { }

  private downloadFile(blob: Blob, filename: string): void {
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);

    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  getKpiReport(from?: string, to?: string, orgId?: string): Observable<KpiReportResponse> {
    let params = new HttpParams();
    if (from) {
      params = params.set('from', from);
    }
    if (to) {
      params = params.set('to', to);
    }
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.get<KpiReportResponse>(`${this.apiUrl}/kpi`, { params });
  }

  getPipelineSummary(orgId?: string): Observable<PipelineSummaryResponse> {
    let params = new HttpParams();
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.get<PipelineSummaryResponse>(`${this.apiUrl}/pipeline-summary`, { params });
  }

  getAnalyticsData(from?: string, to?: string, orgId?: string): Observable<AnalyticsData> {
    let params = new HttpParams();
    if (from) {
      params = params.set('from', from);
    }
    if (to) {
      params = params.set('to', to);
    }
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.get<AnalyticsData>(`${this.apiUrl}/analytics`, { params });
  }

  getObservabilityMetrics(from?: string, to?: string, orgId?: string): Observable<ObservabilityMetrics> {
    let params = new HttpParams();
    if (from) {
      params = params.set('from', from);
    }
    if (to) {
      params = params.set('to', to);
    }
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.get<ObservabilityMetrics>(`${this.apiUrl}/observability/metrics`, { params });
  }

  exportObservabilityMetrics(format: 'csv' | 'json', from?: string, to?: string, orgId?: string): Observable<Blob> {
    let params = new HttpParams().set('format', format);
    if (from) {
      params = params.set('from', from);
    }
    if (to) {
      params = params.set('to', to);
    }
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.get(`${this.apiUrl}/observability/metrics/export`, {
      params,
      responseType: 'blob'
    });
  }

  /**
   * Export analytics data to PDF using lazy-loaded jsPDF library.
   *
   * The jsPDF and jspdf-autotable libraries (~500KB total) are loaded on-demand
   * to avoid bloating the initial bundle.
   *
   * @param data - Analytics data to export
   * @param filename - Name of the PDF file (default: 'analytics-report.pdf')
   * @returns Promise that resolves when the PDF is downloaded
   *
   * @example
   * ```typescript
   * const data = await this.reportingService.getAnalyticsData().toPromise();
   * await this.reportingService.exportAnalyticsToPDF(data, 'my-report.pdf');
   * ```
   */
  async exportAnalyticsToPDF(data: AnalyticsData, filename = 'analytics-report.pdf'): Promise<void> {
    const [jsPDFModule] = await Promise.all([
      import('jspdf'),
      import('jspdf-autotable')
    ]);

    const { jsPDF: JsPDFClass } = jsPDFModule;
    const doc = new JsPDFClass();

    doc.setFontSize(18);
    doc.text('Analytics Report', 14, 20);

    doc.setFontSize(11);
    doc.text(`Date Range: ${data.dateRange.from} to ${data.dateRange.to}`, 14, 30);

    let yPosition = 40;

    if (data.agentPerformance && data.agentPerformance.length > 0) {
      doc.setFontSize(14);
      doc.text('Agent Performance', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Agent Name', 'Total Dossiers', 'Closed Dossiers', 'Conversion Rate', 'Avg Response Time (hrs)']],
        body: data.agentPerformance.map(agent => [
          agent.agentName,
          agent.totalDossiers.toString(),
          agent.closedDossiers.toString(),
          `${(agent.conversionRate * 100).toFixed(2)}%`,
          agent.averageResponseTimeHours.toFixed(2)
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });

      yPosition = (doc as any).lastAutoTable.finalY + 15;
    }

    if (data.leadSources && data.leadSources.length > 0) {
      if (yPosition > 250) {
        doc.addPage();
        yPosition = 20;
      }

      doc.setFontSize(14);
      doc.text('Lead Sources', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Source', 'Count', 'Percentage', 'Conversion Rate']],
        body: data.leadSources.map(source => [
          source.source,
          source.count.toString(),
          `${source.percentage.toFixed(2)}%`,
          `${(source.conversionRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });

      yPosition = (doc as any).lastAutoTable.finalY + 15;
    }

    if (data.conversionFunnel && data.conversionFunnel.length > 0) {
      if (yPosition > 250) {
        doc.addPage();
        yPosition = 20;
      }

      doc.setFontSize(14);
      doc.text('Conversion Funnel', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Stage', 'Count', 'Conversion Rate', 'Drop-off Rate']],
        body: data.conversionFunnel.map(stage => [
          stage.stage,
          stage.count.toString(),
          `${(stage.conversionRate * 100).toFixed(2)}%`,
          `${(stage.dropOffRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });
    }

    doc.save(filename);
  }

  /**
   * Export analytics data to CSV using lazy-loaded PapaParse library.
   *
   * The PapaParse library (~100KB) is loaded on-demand to avoid bloating
   * the initial bundle.
   *
   * @param data - Analytics data to export
   * @param filename - Name of the CSV file (default: 'analytics-report.csv')
   * @returns Promise that resolves when the CSV is downloaded
   *
   * @example
   * ```typescript
   * const data = await this.reportingService.getAnalyticsData().toPromise();
   * await this.reportingService.exportAnalyticsToCSV(data, 'my-report.csv');
   * ```
   */
  async exportAnalyticsToCSV(data: AnalyticsData, filename = 'analytics-report.csv'): Promise<void> {
    const Papa = await import('papaparse');

    const csvSections: string[] = [];

    csvSections.push(`Analytics Report - Date Range: ${data.dateRange.from} to ${data.dateRange.to}\n`);

    if (data.agentPerformance && data.agentPerformance.length > 0) {
      csvSections.push('\nAgent Performance');
      const agentData = data.agentPerformance.map(agent => ({
        'Agent Name': agent.agentName,
        'Total Dossiers': agent.totalDossiers,
        'Closed Dossiers': agent.closedDossiers,
        'Conversion Rate': `${(agent.conversionRate * 100).toFixed(2)}%`,
        'Avg Response Time (hrs)': agent.averageResponseTimeHours.toFixed(2)
      }));
      csvSections.push(Papa.unparse(agentData));
    }

    if (data.leadSources && data.leadSources.length > 0) {
      csvSections.push('\n\nLead Sources');
      const leadSourceData = data.leadSources.map(source => ({
        'Source': source.source,
        'Count': source.count,
        'Percentage': `${source.percentage.toFixed(2)}%`,
        'Conversion Rate': `${(source.conversionRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(leadSourceData));
    }

    if (data.conversionFunnel && data.conversionFunnel.length > 0) {
      csvSections.push('\n\nConversion Funnel');
      const funnelData = data.conversionFunnel.map(stage => ({
        'Stage': stage.stage,
        'Count': stage.count,
        'Conversion Rate': `${(stage.conversionRate * 100).toFixed(2)}%`,
        'Drop-off Rate': `${(stage.dropOffRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(funnelData));
    }

    if (data.revenueForecast && data.revenueForecast.length > 0) {
      csvSections.push('\n\nRevenue Forecast');
      const forecastData = data.revenueForecast.map(forecast => ({
        'Date': forecast.date,
        'Estimated Revenue': forecast.estimatedRevenue,
        'Actual Revenue': forecast.actualRevenue,
        'Pipeline Value': forecast.pipelineValue
      }));
      csvSections.push(Papa.unparse(forecastData));
    }

    const csvContent = csvSections.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }

  /**
   * Export KPI report data to PDF using lazy-loaded jsPDF library.
   *
   * @param data - KPI report data to export
   * @param filename - Name of the PDF file (default: 'kpi-report.pdf')
   * @returns Promise that resolves when the PDF is downloaded
   */
  async exportKpiReportToPDF(data: KpiReportResponse, filename = 'kpi-report.pdf'): Promise<void> {
    const [jsPDFModule] = await Promise.all([
      import('jspdf'),
      import('jspdf-autotable')
    ]);

    const { jsPDF: JsPDFClass } = jsPDFModule;
    const doc = new JsPDFClass();

    doc.setFontSize(18);
    doc.text('KPI Report', 14, 20);

    let yPosition = 35;

    doc.setFontSize(12);
    doc.text('Key Metrics', 14, yPosition);
    yPosition += 8;

    doc.setFontSize(10);
    doc.text(`Average Response Time: ${data.averageResponseTimeHours.toFixed(2)} hours`, 14, yPosition);
    yPosition += 6;
    doc.text(`Appointment Show Rate: ${(data.appointmentShowRate * 100).toFixed(2)}%`, 14, yPosition);
    yPosition += 6;
    doc.text(`Pipeline Velocity: ${data.pipelineVelocityDays.toFixed(2)} days`, 14, yPosition);
    yPosition += 15;

    if (data.conversionRateBySource && data.conversionRateBySource.length > 0) {
      doc.setFontSize(12);
      doc.text('Conversion Rate by Source', 14, yPosition);
      yPosition += 10;

      (doc as any).autoTable({
        startY: yPosition,
        head: [['Source', 'Total Dossiers', 'Won Dossiers', 'Conversion Rate']],
        body: data.conversionRateBySource.map(item => [
          item.source,
          item.totalDossiers.toString(),
          item.wonDossiers.toString(),
          `${(item.conversionRate * 100).toFixed(2)}%`
        ]),
        theme: 'grid',
        styles: { fontSize: 10 },
        headStyles: { fillColor: [66, 139, 202] }
      });
    }

    doc.save(filename);
  }

  /**
   * Export KPI report data to CSV using lazy-loaded PapaParse library.
   *
   * @param data - KPI report data to export
   * @param filename - Name of the CSV file (default: 'kpi-report.csv')
   * @returns Promise that resolves when the CSV is downloaded
   */
  async exportKpiReportToCSV(data: KpiReportResponse, filename = 'kpi-report.csv'): Promise<void> {
    const Papa = await import('papaparse');

    const csvSections: string[] = [];

    csvSections.push('KPI Report\n');
    csvSections.push(`Average Response Time (hours),${data.averageResponseTimeHours.toFixed(2)}`);
    csvSections.push(`Appointment Show Rate,${(data.appointmentShowRate * 100).toFixed(2)}%`);
    csvSections.push(`Pipeline Velocity (days),${data.pipelineVelocityDays.toFixed(2)}`);

    if (data.conversionRateBySource && data.conversionRateBySource.length > 0) {
      csvSections.push('\n\nConversion Rate by Source');
      const conversionData = data.conversionRateBySource.map(item => ({
        'Source': item.source,
        'Total Dossiers': item.totalDossiers,
        'Won Dossiers': item.wonDossiers,
        'Conversion Rate': `${(item.conversionRate * 100).toFixed(2)}%`
      }));
      csvSections.push(Papa.unparse(conversionData));
    }

    if (data.dossierCreationTimeSeries && data.dossierCreationTimeSeries.length > 0) {
      csvSections.push('\n\nDossier Creation Time Series');
      csvSections.push(Papa.unparse(data.dossierCreationTimeSeries));
    }

    if (data.conversionTimeSeries && data.conversionTimeSeries.length > 0) {
      csvSections.push('\n\nConversion Time Series');
      csvSections.push(Papa.unparse(data.conversionTimeSeries));
    }

    const csvContent = csvSections.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }
}

import { Component, OnInit, OnDestroy, AfterViewInit, NgZone, inject } from '@angular/core';
import { CdkConnectedOverlay, CdkOverlayOrigin, ConnectedPosition, Overlay } from '@angular/cdk/overlay';
import { ReportingApiService, ObservabilityMetrics } from '../services/reporting-api.service';
import { interval, Subject, EMPTY } from 'rxjs';
import { takeUntil, switchMap, startWith, catchError } from 'rxjs/operators';
import { FormsModule } from '@angular/forms';
import { DatePipe, DecimalPipe, KeyValuePipe } from '@angular/common';
import {
  PageHeaderComponent,
  DsButtonComponent,
  DsCardComponent,
  DsBadgeComponent,
  DsEmptyStateComponent,
  DsSkeletonComponent,
  DsTableComponent,
  DsIconComponent,
  type DsColumn,
} from '../design-system';
import { dsChartSeriesRgba, dsRgba } from '../design-system/chart-ds-colors';

interface TimeSeriesPoint {
  timestamp: Date;
  values: { [channel: string]: number };
}

@Component({
  selector: 'app-observability-dashboard',
  templateUrl: './observability-dashboard.component.html',
  styleUrls: ['./observability-dashboard.component.css'],
  imports: [
    FormsModule,
    CdkConnectedOverlay,
    CdkOverlayOrigin,
    DatePipe,
    DecimalPipe,
    KeyValuePipe,
    PageHeaderComponent,
    DsButtonComponent,
    DsCardComponent,
    DsBadgeComponent,
    DsEmptyStateComponent,
    DsSkeletonComponent,
    DsTableComponent,
    DsIconComponent,
  ],
})
export class ObservabilityDashboardComponent implements OnInit, OnDestroy, AfterViewInit {
  private readonly overlay = inject(Overlay);

  /** Menu export CSV/JSON (remplace `mat-menu`). */
  exportMenuOpen = false;
  readonly exportMenuScrollStrategy = this.overlay.scrollStrategies.reposition();
  readonly exportMenuPositions: ConnectedPosition[] = [
    { originX: 'end', originY: 'bottom', overlayX: 'end', overlayY: 'top', offsetY: 6 },
    { originX: 'end', originY: 'top', overlayX: 'end', overlayY: 'bottom', offsetY: -6 },
  ];

  metrics: ObservabilityMetrics | null = null;
  channelNames: string[] = [];
  loading = false;
  error: string | null = null;
  autoRefresh = true;
  refreshInterval = 30000; // 30 seconds
  lastUpdated: Date | null = null;

  dateFrom = '';
  dateTo = '';

  latencyColumns: DsColumn<Record<string, unknown>>[] = [];
  dlqColumns: DsColumn<Record<string, unknown>>[] = [];

  readonly trackByLatencyChannel = (_i: number, row: Record<string, unknown>) =>
    String(row['channel'] ?? _i);
  readonly trackByDlqMessage = (_i: number, row: Record<string, unknown>) =>
    row['messageId'] ?? _i;

  // Historical data for time-series charts (1-minute intervals)
  private queueDepthHistory: TimeSeriesPoint[] = [];
  private readonly maxHistoryPoints = 60; // Keep last 60 data points (1 hour if refresh is 1 min)

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private ChartClass: any = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private queueTimeSeriesChart: any = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private latencyHistogramChart: any = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private failureStackedChart: any = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private errorCodeChart: any = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private dlqChart: any = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private quotaChart: any = null;
  private chartsInitialized = false;

  private destroy$ = new Subject<void>();

  constructor(private reportingService: ReportingApiService, private ngZone: NgZone) {
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    
    this.dateTo = this.formatDate(today);
    this.dateFrom = this.formatDate(yesterday);
  }

  ngOnInit(): void {
    this.initDetailTables();
    this.startAutoRefresh();
  }

  get latencyTableRows(): Record<string, unknown>[] {
    return this.channelNames.map((ch) => ({ channel: ch })) as Record<string, unknown>[];
  }

  get dlqTableRows(): Record<string, unknown>[] {
    const rows = this.metrics?.dlqMetrics?.recentDlqMessages ?? [];
    return rows as unknown as Record<string, unknown>[];
  }

  private initDetailTables(): void {
    this.latencyColumns = [
      {
        key: 'channel',
        header: 'Canal',
        cell: (row) => {
          const ch = String(row['channel'] ?? '');
          return `<span class="ds-badge ds-badge--info ds-badge--sm ds-badge--no-dot">${this.escapeHtml(ch)}</span>`;
        },
      },
      {
        key: 'p50',
        header: 'P50 (ms)',
        align: 'right',
        cell: (row) => this.formatLatencyMetricCell(String(row['channel'] ?? ''), 'p50'),
      },
      {
        key: 'p95',
        header: 'P95 (ms)',
        align: 'right',
        cell: (row) => this.formatLatencyMetricCell(String(row['channel'] ?? ''), 'p95'),
      },
      {
        key: 'p99',
        header: 'P99 (ms)',
        align: 'right',
        cell: (row) => this.formatLatencyMetricCell(String(row['channel'] ?? ''), 'p99'),
      },
      {
        key: 'average',
        header: 'Moyenne (ms)',
        align: 'right',
        cell: (row) => this.formatLatencyMetricCell(String(row['channel'] ?? ''), 'average'),
      },
    ];

    this.dlqColumns = [
      {
        key: 'messageId',
        header: 'ID Message',
        cell: (row) =>
          `<span class="obs-mono">${this.escapeHtml(String(row['messageId'] ?? ''))}</span>`,
      },
      {
        key: 'channel',
        header: 'Canal',
        cell: (row) => {
          const ch = String(row['channel'] ?? '');
          return `<span class="ds-badge ds-badge--info ds-badge--sm ds-badge--no-dot">${this.escapeHtml(ch)}</span>`;
        },
      },
      {
        key: 'errorCode',
        header: 'Code',
        cell: (row) => {
          const c = String(row['errorCode'] ?? '');
          return `<span class="ds-badge ds-badge--error ds-badge--sm ds-badge--no-dot">${this.escapeHtml(c)}</span>`;
        },
      },
      {
        key: 'errorMessage',
        header: 'Message',
        cell: (row) => {
          const raw = String(row['errorMessage'] ?? '');
          const esc = this.escapeHtml(raw);
          const truncated =
            raw.length > 100 ? `${this.escapeHtml(raw.slice(0, 97))}…` : esc;
          const title = this.escapeAttr(raw);
          return `<span class="obs-truncate-inline" title="${title}">${truncated}</span>`;
        },
      },
      {
        key: 'attemptCount',
        header: 'Tentatives',
        align: 'right',
        cell: (row) => this.escapeHtml(String(row['attemptCount'] ?? '')),
      },
      {
        key: 'lastAttemptAt',
        header: 'Dernière tentative',
        cell: (row) => {
          const s = String(row['lastAttemptAt'] ?? '');
          return s ? this.escapeHtml(this.formatTimestamp(s)) : '—';
        },
      },
    ];
  }

  private formatLatencyMetricCell(
    channel: string,
    field: 'p50' | 'p95' | 'p99' | 'average'
  ): string {
    const lat = this.getLatency(channel);
    if (!lat) {
      return '—';
    }
    return this.formatLatencyNum(lat[field]);
  }

  private formatLatencyNum(n: unknown): string {
    if (n == null || typeof n !== 'number' || Number.isNaN(n)) {
      return '—';
    }
    return n.toLocaleString('fr-FR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  }

  private escapeHtml(value: string): string {
    return value
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  private escapeAttr(value: string): string {
    return value
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  ngAfterViewInit(): void {
    this.ngZone.runOutsideAngular(() => {
      setTimeout(async () => {
        await this.loadChartJs();
        this.chartsInitialized = true;
        if (this.metrics) {
          this.updateAllCharts();
        }
      }, 100);
    });
  }

  private async loadChartJs(): Promise<void> {
    try {
      const module = await import('chart.js/auto');
      // chart.js/auto exports Chart as a named export in ESM — store it so we
      // don't rely on an undeclared global variable.
      this.ChartClass = (module as any).Chart ?? module.default ?? module;
    } catch (error) {
      console.error('Failed to load Chart.js:', error);
    }
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
    this.destroyAllCharts();
  }

  private destroyAllCharts(): void {
    if (this.queueTimeSeriesChart) this.queueTimeSeriesChart.destroy();
    if (this.latencyHistogramChart) this.latencyHistogramChart.destroy();
    if (this.failureStackedChart) this.failureStackedChart.destroy();
    if (this.errorCodeChart) this.errorCodeChart.destroy();
    if (this.dlqChart) this.dlqChart.destroy();
    if (this.quotaChart) this.quotaChart.destroy();
  }

  private startAutoRefresh(): void {
    interval(this.refreshInterval)
      .pipe(
        takeUntil(this.destroy$),
        startWith(0),
        switchMap(() => {
          if (!this.autoRefresh) {
            return EMPTY;
          }
          return this.reportingService.getObservabilityMetrics(this.dateFrom, this.dateTo).pipe(
            // Absorb per-tick errors so the interval keeps running on the next tick.
            catchError(err => {
              this.error = 'Erreur de chargement: ' + (err.message || err.status || 'inconnue');
              return EMPTY;
            })
          );
        })
      )
      .subscribe({
        next: (metrics) => {
          if (metrics) {
            this.metrics = metrics;
            this.channelNames = Object.keys(metrics.queueMetrics.queueDepthByChannel);
            this.lastUpdated = new Date();
            this.addToHistory(metrics);
            this.updateAllCharts();
            this.error = null;
          }
        }
      });
  }

  private addToHistory(metrics: ObservabilityMetrics): void {
    const point: TimeSeriesPoint = {
      timestamp: new Date(),
      values: metrics.queueMetrics.queueDepthByChannel
    };
    
    this.queueDepthHistory.push(point);
    
    // Keep only the last maxHistoryPoints
    if (this.queueDepthHistory.length > this.maxHistoryPoints) {
      this.queueDepthHistory.shift();
    }
  }

  loadMetrics(): void {
    this.loading = true;
    this.error = null;

    this.reportingService.getObservabilityMetrics(this.dateFrom, this.dateTo)
      .subscribe({
        next: (metrics) => {
          this.metrics = metrics;
          this.channelNames = Object.keys(metrics.queueMetrics.queueDepthByChannel);
          this.lastUpdated = new Date();
          this.addToHistory(metrics);
          this.updateAllCharts();
          this.loading = false;
        },
        error: (err) => {
          this.error = 'Failed to load metrics: ' + err.message;
          this.loading = false;
        }
      });
  }

  toggleAutoRefresh(): void {
    this.autoRefresh = !this.autoRefresh;
    if (this.autoRefresh) {
      this.loadMetrics();
    }
  }

  onDateChange(): void {
    this.queueDepthHistory = []; // Reset history when date range changes
    this.loadMetrics();
  }

  toggleExportMenu(): void {
    this.exportMenuOpen = !this.exportMenuOpen;
  }

  closeExportMenu(): void {
    this.exportMenuOpen = false;
  }

  exportMetrics(format: 'csv' | 'json'): void {
    this.closeExportMenu();
    this.reportingService.exportObservabilityMetrics(format, this.dateFrom, this.dateTo)
      .subscribe({
        next: (blob) => {
          const url = window.URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `observability-metrics-${new Date().getTime()}.${format}`;
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          window.URL.revokeObjectURL(url);
        },
        error: (err) => {
          this.error = 'Failed to export metrics: ' + err.message;
        }
      });
  }

  private updateAllCharts(): void {
    if (!this.metrics || !this.chartsInitialized || !this.ChartClass) return;

    this.ngZone.runOutsideAngular(() => {
      this.updateQueueTimeSeriesChart();
      this.updateLatencyHistogramChart();
      this.updateFailureStackedChart();
      this.updateErrorCodeChart();
      this.updateDlqChart();
      this.updateQuotaChart();
    });
  }

  private updateQueueTimeSeriesChart(): void {
    if (!this.metrics || this.queueDepthHistory.length === 0) return;

    const ctx = document.getElementById('queueTimeSeriesChart') as HTMLCanvasElement;
    if (!ctx) return;

    const channels = Object.keys(this.metrics.queueMetrics.queueDepthByChannel);
    const labels = this.queueDepthHistory.map(point => 
      point.timestamp.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })
    );

    const datasets = channels.map((channel, idx) => ({
      label: channel,
      data: this.queueDepthHistory.map(point => point.values[channel] || 0),
      borderColor: this.getChannelColor(idx),
      backgroundColor: this.getChannelColor(idx, 0.1),
      fill: true,
      tension: 0.4,
      pointRadius: 2,
      pointHoverRadius: 5
    }));

    const config = {
      type: 'line',
      data: { labels, datasets },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: {
          mode: 'index',
          intersect: false
        },
        scales: {
          x: {
            display: true,
            title: {
              display: true,
              text: 'Time (1-min intervals)'
            }
          },
          y: {
            display: true,
            title: {
              display: true,
              text: 'Queue Depth'
            },
            beginAtZero: true
          }
        },
        plugins: {
          legend: {
            display: true,
            position: 'top'
          },
          tooltip: {
            callbacks: {
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              title: (tooltipItems: any) => {
                const index = tooltipItems[0].dataIndex;
                const point = this.queueDepthHistory[index];
                return point.timestamp.toLocaleString('fr-FR');
              }
            }
          }
        }
      }
    };

    if (this.queueTimeSeriesChart) {
      this.queueTimeSeriesChart.destroy();
    }
    this.queueTimeSeriesChart = new this.ChartClass(ctx, config);
  }

  private updateLatencyHistogramChart(): void {
    const data = this.metrics?.latencyMetrics;
    if (!data) return;

    const ctx = document.getElementById('latencyHistogramChart') as HTMLCanvasElement;
    if (!ctx) return;

    const channels = Object.keys(data.latencyByChannel);
    
    const config = {
      type: 'bar',
      data: {
        labels: channels,
        datasets: [
          {
            label: 'P50 (ms)',
            data: channels.map(ch => data.latencyByChannel[ch].p50),
            backgroundColor: dsRgba('--ds-success', 0.72),
            borderColor: dsRgba('--ds-success', 1),
            borderWidth: 1
          },
          {
            label: 'P95 (ms)',
            data: channels.map(ch => data.latencyByChannel[ch].p95),
            backgroundColor: dsRgba('--ds-warning', 0.72),
            borderColor: dsRgba('--ds-warning', 1),
            borderWidth: 1
          },
          {
            label: 'P99 (ms)',
            data: channels.map(ch => data.latencyByChannel[ch].p99),
            backgroundColor: dsRgba('--ds-error', 0.72),
            borderColor: dsRgba('--ds-error', 1),
            borderWidth: 1
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: {
            title: {
              display: true,
              text: 'Channel'
            }
          },
          y: {
            beginAtZero: true,
            title: {
              display: true,
              text: 'Latency (ms)'
            }
          }
        },
        plugins: {
          legend: {
            display: true,
            position: 'top'
          },
          title: {
            display: true,
            text: 'Message Delivery Latency Distribution'
          }
        }
      }
    };

    if (this.latencyHistogramChart) {
      this.latencyHistogramChart.destroy();
    }
    this.latencyHistogramChart = new this.ChartClass(ctx, config);
  }

  private updateFailureStackedChart(): void {
    const data = this.metrics?.failureMetrics;
    if (!data || !data.failureTrend) return;

    const ctx = document.getElementById('failureStackedChart') as HTMLCanvasElement;
    if (!ctx) return;

    // Group error codes
    const errorCodes = Object.keys(data.failuresByErrorCode);
    const labels = data.failureTrend.map(d => d.date);
    
    // Create stacked dataset for each error code
    const datasets = errorCodes.map((errorCode, idx) => ({
      label: errorCode,
      data: data.failureTrend.map(() => {
        // Simulate distribution across time periods
        // In real implementation, this would come from the API
        return Math.round((data.failuresByErrorCode[errorCode] / data.failureTrend.length) * (0.8 + Math.random() * 0.4));
      }),
      backgroundColor: this.getChannelColor(idx, 0.7),
      borderColor: this.getChannelColor(idx, 1),
      borderWidth: 1
    }));

    const config = {
      type: 'bar',
      data: { labels, datasets },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: {
            stacked: true,
            title: {
              display: true,
              text: 'Date'
            }
          },
          y: {
            stacked: true,
            beginAtZero: true,
            title: {
              display: true,
              text: 'Failure Count'
            }
          }
        },
        plugins: {
          legend: {
            display: true,
            position: 'top'
          },
          title: {
            display: true,
            text: 'Failure Rate Trends by Error Code'
          }
        }
      }
    };

    if (this.failureStackedChart) {
      this.failureStackedChart.destroy();
    }
    this.failureStackedChart = new this.ChartClass(ctx, config);
  }

  private updateErrorCodeChart(): void {
    const data = this.metrics?.failureMetrics;
    if (!data) return;

    const ctx = document.getElementById('errorCodeChart') as HTMLCanvasElement;
    if (!ctx) return;

    const errorCodes = Object.keys(data.failuresByErrorCode);
    const values = Object.values(data.failuresByErrorCode);

    const config = {
      type: 'doughnut',
      data: {
        labels: errorCodes,
        datasets: [{
          data: values,
          backgroundColor: errorCodes.map((_, idx) => this.getChannelColor(idx, 0.7)),
          borderColor: errorCodes.map((_, idx) => this.getChannelColor(idx, 1)),
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: true,
            position: 'right'
          },
          title: {
            display: true,
            text: 'Error Code Distribution'
          },
          tooltip: {
            callbacks: {
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              label: (context: any) => {
                const label = context.label || '';
                const value = context.parsed as number;
                const total = (context.dataset.data as number[]).reduce((a, b) => a + b, 0);
                const percentage = ((value / total) * 100).toFixed(1);
                return `${label}: ${value} (${percentage}%)`;
              }
            }
          }
        }
      }
    };

    if (this.errorCodeChart) {
      this.errorCodeChart.destroy();
    }
    this.errorCodeChart = new this.ChartClass(ctx, config);
  }

  private updateDlqChart(): void {
    const data = this.metrics?.dlqMetrics;
    if (!data) return;

    const ctx = document.getElementById('dlqChart') as HTMLCanvasElement;
    if (!ctx) return;

    const channels = Object.keys(data.dlqSizeByChannel);
    const values = Object.values(data.dlqSizeByChannel);
    
    // Color code based on warning/critical thresholds
    const warningThreshold = data.alertThreshold * 0.75;
    const criticalThreshold = data.alertThreshold;

    const config = {
      type: 'bar',
      data: {
        labels: channels,
        datasets: [{
          label: 'DLQ Size',
          data: values,
          backgroundColor: values.map(v => 
            v >= criticalThreshold ? dsRgba('--ds-error', 0.72) :
            v >= warningThreshold ? dsRgba('--ds-warning', 0.72) :
            dsRgba('--ds-success', 0.72)
          ),
          borderColor: values.map(v => 
            v >= criticalThreshold ? dsRgba('--ds-error', 1) :
            v >= warningThreshold ? dsRgba('--ds-warning', 1) :
            dsRgba('--ds-success', 1)
          ),
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            title: {
              display: true,
              text: 'Message Count'
            }
          }
        },
        plugins: {
          legend: {
            display: false
          },
          title: {
            display: true,
            text: `DLQ Size by Channel (Warning: ${warningThreshold}, Critical: ${criticalThreshold})`
          },
          annotation: {
            annotations: {
              warningLine: {
                type: 'line',
                yMin: warningThreshold,
                yMax: warningThreshold,
                borderColor: dsRgba('--ds-warning', 0.85),
                borderWidth: 2,
                borderDash: [5, 5],
                label: {
                  display: true,
                  content: 'Warning',
                  position: 'end'
                }
              },
              criticalLine: {
                type: 'line',
                yMin: criticalThreshold,
                yMax: criticalThreshold,
                borderColor: dsRgba('--ds-error', 0.85),
                borderWidth: 2,
                borderDash: [5, 5],
                label: {
                  display: true,
                  content: 'Critical',
                  position: 'end'
                }
              }
            }
          }
        }
      }
    };

    if (this.dlqChart) {
      this.dlqChart.destroy();
    }
    this.dlqChart = new this.ChartClass(ctx, config);
  }

  private updateQuotaChart(): void {
    const data = this.metrics?.quotaMetrics;
    if (!data) return;

    const ctx = document.getElementById('quotaChart') as HTMLCanvasElement;
    if (!ctx) return;

    const channels = Object.keys(data.quotaByChannel);
    const usagePercentages = channels.map(ch => data.quotaByChannel[ch].usagePercentage);

    const config = {
      type: 'bar',
      data: {
        labels: channels,
        datasets: [{
          label: 'Quota Usage (%)',
          data: usagePercentages,
          backgroundColor: usagePercentages.map(p => 
            p >= 90 ? dsRgba('--ds-error', 0.72) :
            p >= 75 ? dsRgba('--ds-warning', 0.72) :
            dsRgba('--ds-success', 0.72)
          ),
          borderColor: usagePercentages.map(p => 
            p >= 90 ? dsRgba('--ds-error', 1) :
            p >= 75 ? dsRgba('--ds-warning', 1) :
            dsRgba('--ds-success', 1)
          ),
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            max: 100,
            title: {
              display: true,
              text: 'Usage (%)'
            },
            ticks: {
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              callback: (value: any) => `${value}%`
            }
          }
        },
        plugins: {
          legend: {
            display: false
          },
          title: {
            display: true,
            text: 'Provider Quota Consumption'
          },
          annotation: {
            annotations: {
              warningLine: {
                type: 'line',
                yMin: 75,
                yMax: 75,
                borderColor: dsRgba('--ds-warning', 0.85),
                borderWidth: 2,
                borderDash: [5, 5],
                label: {
                  display: true,
                  content: 'Warning (75%)',
                  position: 'start'
                }
              },
              criticalLine: {
                type: 'line',
                yMin: 90,
                yMax: 90,
                borderColor: dsRgba('--ds-error', 0.85),
                borderWidth: 2,
                borderDash: [5, 5],
                label: {
                  display: true,
                  content: 'Critical (90%)',
                  position: 'start'
                }
              }
            }
          }
        }
      }
    };

    if (this.quotaChart) {
      this.quotaChart.destroy();
    }
    this.quotaChart = new this.ChartClass(ctx, config);
  }

  private getChannelColor(index: number, alpha = 1): string {
    return dsChartSeriesRgba(index, alpha);
  }

  private formatDate(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  // Template helper methods
  getChannelNames(): string[] {
    return this.metrics?.queueMetrics 
      ? Object.keys(this.metrics.queueMetrics.queueDepthByChannel)
      : [];
  }

  getQueueDepth(channel: string): number {
    return this.metrics?.queueMetrics?.queueDepthByChannel[channel] || 0;
  }

  getLatency(channel: string): any {
    return this.metrics?.latencyMetrics?.latencyByChannel[channel] || null;
  }

  getFailureCount(channel: string): number {
    return this.metrics?.failureMetrics?.failuresByChannel[channel] || 0;
  }

  getDlqSize(channel: string): number {
    return this.metrics?.dlqMetrics?.dlqSizeByChannel[channel] || 0;
  }

  getDlqStatus(channel: string): 'normal' | 'warning' | 'critical' {
    const size = this.getDlqSize(channel);
    const threshold = this.metrics?.dlqMetrics?.alertThreshold || 1000;
    const warningThreshold = threshold * 0.75;
    
    if (size >= threshold) return 'critical';
    if (size >= warningThreshold) return 'warning';
    return 'normal';
  }

  getQuotaUsage(channel: string): any {
    return this.metrics?.quotaMetrics?.quotaByChannel[channel] || null;
  }

  getQuotaStatusClass(percentage: number): string {
    if (percentage >= 90) return 'quota-critical';
    if (percentage >= 75) return 'quota-warning';
    return 'quota-normal';
  }

  formatTimestamp(timestamp: string): string {
    return new Date(timestamp).toLocaleString('fr-FR');
  }
}

import { Injectable } from '@angular/core';
import { MatSnackBar, MatSnackBarRef } from '@angular/material/snack-bar';
import { BehaviorSubject, Observable } from 'rxjs';
import { AriaLiveAnnouncerService } from './aria-live-announcer.service';

export type ToastPosition = 
  | 'top-right' 
  | 'top-left' 
  | 'top-center' 
  | 'bottom-right' 
  | 'bottom-left' 
  | 'bottom-center';

export type ToastType = 'success' | 'error' | 'warning' | 'info';

export interface ToastAction {
  label: string;
  handler: () => void;
}

export interface ToastNotification {
  id?: string;
  message: string;
  type: ToastType;
  action?: ToastAction;
  duration?: number;
  dismissible?: boolean;
  position?: ToastPosition;
  showProgress?: boolean;
}

export interface ActiveToast extends ToastNotification {
  id: string;
  startTime: number;
  timeoutId?: any;
}

@Injectable({
  providedIn: 'root'
})
export class ToastNotificationService {
  private readonly maxSimultaneous = 3;
  private activeToasts$ = new BehaviorSubject<ActiveToast[]>([]);
  private queue: ToastNotification[] = [];
  
  // Legacy support
  private currentSnackBarRef: MatSnackBarRef<any> | null = null;
  private legacyMode = false;

  constructor(
    private snackBar: MatSnackBar,
    private ariaLiveAnnouncer: AriaLiveAnnouncerService
  ) {}

  get activeToasts(): Observable<ActiveToast[]> {
    return this.activeToasts$.asObservable();
  }

  success(
    message: string, 
    action?: string | ToastAction, 
    duration = 5000,
    position: ToastPosition = 'top-right'
  ): string {
    return this.show({
      message,
      type: 'success',
      action: this.normalizeAction(action),
      duration,
      dismissible: true,
      position,
      showProgress: true
    });
  }

  error(
    message: string, 
    action?: string | ToastAction, 
    duration = 7000,
    position: ToastPosition = 'top-right'
  ): string {
    return this.show({
      message,
      type: 'error',
      action: this.normalizeAction(action),
      duration,
      dismissible: true,
      position,
      showProgress: true
    });
  }

  warning(
    message: string, 
    action?: string | ToastAction, 
    duration = 6000,
    position: ToastPosition = 'top-right'
  ): string {
    return this.show({
      message,
      type: 'warning',
      action: this.normalizeAction(action),
      duration,
      dismissible: true,
      position,
      showProgress: true
    });
  }

  info(
    message: string, 
    action?: string | ToastAction, 
    duration = 5000,
    position: ToastPosition = 'top-right'
  ): string {
    return this.show({
      message,
      type: 'info',
      action: this.normalizeAction(action),
      duration,
      dismissible: true,
      position,
      showProgress: true
    });
  }

  show(notification: ToastNotification): string {
    const id = notification.id || this.generateId();
    const toast: ActiveToast = {
      ...notification,
      id,
      startTime: Date.now(),
      position: notification.position || 'top-right',
      showProgress: notification.showProgress !== false,
      dismissible: notification.dismissible !== false
    };

    // Announce to screen readers
    const announcement = `${this.getTypeLabel(toast.type)}: ${toast.message}`;
    this.ariaLiveAnnouncer.announce(
      announcement, 
      toast.type === 'error' ? 'assertive' : 'polite'
    );

    const active = this.activeToasts$.value;
    
    if (active.length >= this.maxSimultaneous) {
      this.queue.push(toast);
    } else {
      this.addToActive(toast);
    }

    return id;
  }

  dismiss(id: string): void {
    const active = this.activeToasts$.value;
    const toast = active.find(t => t.id === id);
    
    if (toast?.timeoutId) {
      clearTimeout(toast.timeoutId);
    }

    const updated = active.filter(t => t.id !== id);
    this.activeToasts$.next(updated);

    // Process queue
    this.processQueue();
  }

  dismissAll(): void {
    const active = this.activeToasts$.value;
    active.forEach(toast => {
      if (toast.timeoutId) {
        clearTimeout(toast.timeoutId);
      }
    });
    this.activeToasts$.next([]);
    this.queue = [];
  }

  clearQueue(): void {
    this.queue = [];
  }

  private addToActive(toast: ActiveToast): void {
    const active = this.activeToasts$.value;
    this.activeToasts$.next([...active, toast]);

    if (toast.duration && toast.duration > 0) {
      toast.timeoutId = setTimeout(() => {
        this.dismiss(toast.id);
      }, toast.duration);
    }
  }

  private processQueue(): void {
    const active = this.activeToasts$.value;
    
    while (this.queue.length > 0 && active.length < this.maxSimultaneous) {
      const next = this.queue.shift();
      if (next) {
        this.addToActive({
          ...next,
          startTime: Date.now()
        } as ActiveToast);
      }
    }
  }

  private normalizeAction(action?: string | ToastAction): ToastAction | undefined {
    if (!action) return undefined;
    
    if (typeof action === 'string') {
      return {
        label: action,
        handler: () => { return; }
      };
    }
    
    return action;
  }

  private getTypeLabel(type: ToastType): string {
    const labels: Record<ToastType, string> = {
      success: 'Succès',
      error: 'Erreur',
      warning: 'Avertissement',
      info: 'Information'
    };
    return labels[type];
  }

  private generateId(): string {
    return `toast-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  // Legacy support methods
  private showLegacy(notification: ToastNotification): void {
    this.legacyMode = true;
    const actionLabel = notification.action?.label ?? 'Fermer';
    this.currentSnackBarRef = this.snackBar.open(notification.message, actionLabel, {
      duration: notification.duration,
      horizontalPosition: 'center',
      verticalPosition: 'top',
      panelClass: [`${notification.type}-snackbar`]
    });

    this.currentSnackBarRef.onAction().subscribe(() => {
      try {
        notification.action?.handler();
      } catch {
        // no-op
      }
    });

    this.currentSnackBarRef.afterDismissed().subscribe(() => {
      this.currentSnackBarRef = null;
    });
  }

  dismissLegacy(): void {
    if (this.currentSnackBarRef) {
      this.currentSnackBarRef.dismiss();
    }
  }
}

