        this.startDossierCreationTour();
        break;
      case 'dossier-detail':
        this.startDossierDetailTour();
        break;
      case 'message-creation':
        this.startMessageCreationTour();
        break;
      case 'workflow-status':
        this.startWorkflowStatusTour();
        break;
    }
  }

  cancelCurrentTour(): void {
    if (this.currentTour) {
      this.currentTour.cancel();
    }
  }
