import { Injectable } from '@angular/core';

export interface TourStep {
  id: string;
  title: string;
  text: string;
  attachTo?: {
    element: string;
    on: 'auto' | 'auto-start' | 'auto-end' | 'top' | 'top-start' | 'top-end' | 'bottom' | 'bottom-start' | 'bottom-end' | 'right' | 'right-start' | 'right-end' | 'left' | 'left-start' | 'left-end';
  };
  buttons?: any[]; // Use any[] to avoid strict type checking
  when?: {
    show?: () => void;
    hide?: () => void;
  };
  classes?: string;
  scrollTo?: boolean | { behavior?: 'smooth' | 'auto'; block?: 'start' | 'center' | 'end' | 'nearest' };
}

export interface TourDefinition {
  id: string;
  name: string;
  description: string;
  steps: TourStep[];
  category: 'core' | 'feature' | 'advanced';
  estimatedTime: number; // in minutes
  requiredRoute?: string;
}

