  }

  uncomplete(id: number): Observable<TaskResponse> {
    return this.http.post<TaskResponse>(`${this.apiUrl}/${id}/uncomplete`, {});
  }

  getUsers(): Observable<User[]> {
    return this.http.get<User[]>('/api/v1/users');
  }
}

