import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { BehaviorSubject, Observable } from 'rxjs';

export interface KeyboardShortcut {
  key: string;
  description: string;
  action: () => void;
  category: 'navigation' | 'actions' | 'lists';
  sequence?: boolean;
}

export interface UserPreferences {
  keyboardShortcutsEnabled: boolean;
  showShortcutHints: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class KeyboardShortcutService {
  private readonly PREFERENCES_KEY = 'keyboard-shortcuts-preferences';
  private preferencesSubject: BehaviorSubject<UserPreferences>;
  public preferences$: Observable<UserPreferences>;
  
  private shortcuts: Map<string, KeyboardShortcut> = new Map();
  private sequenceBuffer: string[] = [];
  private sequenceTimeout: any;
  
  private commandPaletteVisibleSubject = new BehaviorSubject<boolean>(false);
  public commandPaletteVisible$ = this.commandPaletteVisibleSubject.asObservable();
  
  private shortcutHelpVisibleSubject = new BehaviorSubject<boolean>(false);
  public shortcutHelpVisible$ = this.shortcutHelpVisibleSubject.asObservable();
  
  private activeListItemSubject = new BehaviorSubject<number>(-1);
  public activeListItem$ = this.activeListItemSubject.asObservable();

  constructor(private router: Router) {
    const savedPrefs = this.loadPreferences();
    this.preferencesSubject = new BehaviorSubject<UserPreferences>(savedPrefs);
    this.preferences$ = this.preferencesSubject.asObservable();
    this.registerDefaultShortcuts();
  }

  private loadPreferences(): UserPreferences {
    const saved = localStorage.getItem(this.PREFERENCES_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch {
        return this.getDefaultPreferences();
      }
    }
    return this.getDefaultPreferences();
  }

  private getDefaultPreferences(): UserPreferences {
    return {
      keyboardShortcutsEnabled: true,
      showShortcutHints: true
    };
  }

  savePreferences(preferences: UserPreferences): void {
    localStorage.setItem(this.PREFERENCES_KEY, JSON.stringify(preferences));
    this.preferencesSubject.next(preferences);
  }

  getPreferences(): UserPreferences {
    return this.preferencesSubject.value;
  }

  private registerDefaultShortcuts(): void {
    this.registerShortcut({
      key: '/',
      description: 'Focus recherche',
      category: 'navigation',
      action: () => this.focusSearch()
    });

    this.registerShortcut({
      key: 'Ctrl+K',
      description: 'Ouvrir la palette de commandes',
      category: 'actions',
      action: () => this.toggleCommandPalette()
    });

    this.registerShortcut({
      key: 'g+a',
      description: 'Aller aux annonces',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToAnnonces()
    });

    this.registerShortcut({
      key: 'g+d',
      description: 'Aller aux dossiers',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToDossiers()
    });

    this.registerShortcut({
      key: 'g+h',
      description: 'Aller au tableau de bord',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToDashboard()
    });

    this.registerShortcut({
      key: 'g+t',
      description: 'Aller aux tâches',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToTasks()
    });

    this.registerShortcut({
      key: 'g+c',
      description: 'Aller au calendrier',
      category: 'navigation',
      sequence: true,
      action: () => this.navigateToCalendar()
    });

    this.registerShortcut({
      key: 'Escape',
      description: 'Fermer les modales',
      category: 'actions',
      action: () => this.closeModals()
    });

    this.registerShortcut({
      key: '?',
      description: 'Afficher les raccourcis clavier',
      category: 'actions',
      action: () => this.toggleShortcutHelp()
    });

    this.registerShortcut({
      key: 'j',
      description: 'Élément suivant dans la liste',
      category: 'lists',
      action: () => this.navigateListDown()
    });

    this.registerShortcut({
      key: 'k',
      description: 'Élément précédent dans la liste',
      category: 'lists',
      action: () => this.navigateListUp()
    });

    this.registerShortcut({
      key: 'Enter',
      description: 'Ouvrir l\'élément sélectionné',
      category: 'lists',
      action: () => this.openSelectedListItem()
    });
  }

  registerShortcut(shortcut: KeyboardShortcut): void {
    this.shortcuts.set(shortcut.key, shortcut);
  }

  handleKeyDown(event: KeyboardEvent): boolean {
    const preferences = this.getPreferences();
    if (!preferences.keyboardShortcutsEnabled) {
      return false;
    }

    const target = event.target as HTMLElement;
    const isInputField = target.tagName === 'INPUT' || 
                        target.tagName === 'TEXTAREA' || 
                        target.isContentEditable;

    if (event.key === 'Escape') {
      this.closeModals();
      return true;
    }

    if (event.key === '?' && !isInputField) {
      event.preventDefault();
      this.toggleShortcutHelp();
      return true;
    }

    if (isInputField && event.key !== 'Escape') {
      return false;
    }

    const key = this.getKeyString(event);
    
    if (this.shortcuts.has(key) && !this.shortcuts.get(key)?.sequence) {
      event.preventDefault();
      this.shortcuts.get(key)?.action();
      return true;
    }

    if (!event.ctrlKey && !event.altKey && !event.metaKey && event.key.length === 1) {
      this.sequenceBuffer.push(event.key.toLowerCase());
      
      if (this.sequenceTimeout) {
        clearTimeout(this.sequenceTimeout);
      }
      
      this.sequenceTimeout = setTimeout(() => {
        this.sequenceBuffer = [];
      }, 1000);

      const sequence = this.sequenceBuffer.join('+');
      if (this.shortcuts.has(sequence)) {
        event.preventDefault();
        this.shortcuts.get(sequence)?.action();
        this.sequenceBuffer = [];
        return true;
      }
    }

    return false;
  }

  private getKeyString(event: KeyboardEvent): string {
    const parts: string[] = [];
    
    if (event.ctrlKey) parts.push('Ctrl');
    if (event.altKey) parts.push('Alt');
    if (event.metaKey) parts.push('Meta');
    if (event.shiftKey && event.key.length > 1) parts.push('Shift');
    
    parts.push(event.key);
    
    return parts.join('+');
  }

  getAllShortcuts(): KeyboardShortcut[] {
    return Array.from(this.shortcuts.values());
  }

  getShortcutsByCategory(category: string): KeyboardShortcut[] {
    return Array.from(this.shortcuts.values()).filter(s => s.category === category);
  }

  private focusSearch(): void {
    const searchInput = document.getElementById('global-search-input');
    if (searchInput) {
      searchInput.focus();
    }
  }

  toggleCommandPalette(): void {
    const currentState = this.commandPaletteVisibleSubject.value;
    this.commandPaletteVisibleSubject.next(!currentState);
  }

  closeCommandPalette(): void {
    this.commandPaletteVisibleSubject.next(false);
  }

  toggleShortcutHelp(): void {
    const currentState = this.shortcutHelpVisibleSubject.value;
    this.shortcutHelpVisibleSubject.next(!currentState);
  }

  closeShortcutHelp(): void {
    this.shortcutHelpVisibleSubject.next(false);
  }

  private navigateToAnnonces(): void {
    this.router.navigate(['/annonces']);
  }

  private navigateToDossiers(): void {
    this.router.navigate(['/dossiers']);
  }

  private navigateToDashboard(): void {
    this.router.navigate(['/dashboard']);
  }

  private navigateToTasks(): void {
    this.router.navigate(['/tasks']);
  }

  private navigateToCalendar(): void {
    this.router.navigate(['/calendar']);
  }

  private closeModals(): void {
    if (this.commandPaletteVisibleSubject.value) {
      this.closeCommandPalette();
      return;
    }
    
    if (this.shortcutHelpVisibleSubject.value) {
      this.closeShortcutHelp();
      return;
    }
    
    const escEvent = new KeyboardEvent('keydown', {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
      bubbles: true
    });
    document.dispatchEvent(escEvent);
  }

  private navigateListDown(): void {
    const current = this.activeListItemSubject.value;
    this.activeListItemSubject.next(current + 1);
  }

  private navigateListUp(): void {
    const current = this.activeListItemSubject.value;
    if (current > 0) {
      this.activeListItemSubject.next(current - 1);
    }
  }

  private openSelectedListItem(): void {
    const activeIndex = this.activeListItemSubject.value;
    if (activeIndex >= 0) {
      const event = new CustomEvent('list-item-selected', {
        detail: { index: activeIndex },
        bubbles: true
      });
      document.dispatchEvent(event);
    }
  }

  resetListNavigation(): void {
    this.activeListItemSubject.next(-1);
  }

  setActiveListItem(index: number): void {
    this.activeListItemSubject.next(index);
  }
}

import { Injectable } from '@angular/core';
import { AbstractControl, ValidationErrors } from '@angular/forms';
import { Observable, of, timer } from 'rxjs';
import { map, switchMap, debounceTime, distinctUntilChanged, catchError } from 'rxjs/operators';
import { HttpClient } from '@angular/common/http';

export interface ValidationSuggestion {
  field: string;
  originalValue: string;
  suggestedValue: string;
  reason: string;
  confidence: 'low' | 'medium' | 'high';
}

export interface AsyncValidationResult {
  valid: boolean;
  errors?: ValidationErrors;
  suggestions?: ValidationSuggestion[];
}

@Injectable({
  providedIn: 'root'
})
export class FormValidationService {
  private readonly API_BASE = '/api/v1';
  private readonly DEFAULT_DEBOUNCE_TIME = 500;

  constructor(private http: HttpClient) {}

  /**
   * Validates email with backend async validation
   */
  validateEmailAsync(debounce = this.DEFAULT_DEBOUNCE_TIME): (control: AbstractControl) => Observable<ValidationErrors | null> {
    return (control: AbstractControl): Observable<ValidationErrors | null> => {
      if (!control.value) {
        return of(null);
      }

      return timer(debounce).pipe(
        switchMap(() => this.http.post<AsyncValidationResult>(
          `${this.API_BASE}/validation/email`,
          { email: control.value }
        )),
        map(result => result.valid ? null : (result.errors || { invalidEmail: true })),
        catchError(() => of(null))
      );
    };
  }

  /**
   * Validates phone number with backend async validation
   */
  validatePhoneAsync(debounce = this.DEFAULT_DEBOUNCE_TIME): (control: AbstractControl) => Observable<ValidationErrors | null> {
    return (control: AbstractControl): Observable<ValidationErrors | null> => {
      if (!control.value) {
        return of(null);
      }

      return timer(debounce).pipe(
        switchMap(() => this.http.post<AsyncValidationResult>(
          `${this.API_BASE}/validation/phone`,
          { phone: control.value }
        )),
        map(result => result.valid ? null : (result.errors || { invalidPhone: true })),
        catchError(() => of(null))
      );
    };
  }

  /**
   * Get email suggestions for typo correction
   */
  getEmailSuggestions(email: string): Observable<ValidationSuggestion[]> {
    if (!email || !email.includes('@')) {
      return of([]);
    }

    const suggestions: ValidationSuggestion[] = [];
    const commonDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'orange.fr', 'free.fr', 'laposte.net', 'wanadoo.fr'];
    const emailParts = email.split('@');
    const domain = emailParts[1]?.toLowerCase();

    if (!domain) {
      return of([]);
    }

    // Check for common typos
    const typoMap: { [key: string]: string } = {
      'gmial.com': 'gmail.com',
      'gmai.com': 'gmail.com',
      'gmil.com': 'gmail.com',
      'yahooo.com': 'yahoo.com',
      'yaho.com': 'yahoo.com',
      'hotmial.com': 'hotmail.com',
      'hotmai.com': 'hotmail.com',
      'outlok.com': 'outlook.com',
      'outloo.com': 'outlook.com'
    };

    if (typoMap[domain]) {
      suggestions.push({
        field: 'email',
        originalValue: email,
        suggestedValue: `${emailParts[0]}@${typoMap[domain]}`,
        reason: 'Correction de faute de frappe détectée',
        confidence: 'high'
      });
    } else {
      // Suggest similar domains using Levenshtein distance
      for (const commonDomain of commonDomains) {
        const distance = this.levenshteinDistance(domain, commonDomain);
        if (distance === 1 || distance === 2) {
          suggestions.push({
            field: 'email',
            originalValue: email,
            suggestedValue: `${emailParts[0]}@${commonDomain}`,
            reason: 'Vouliez-vous dire ce domaine ?',
            confidence: distance === 1 ? 'high' : 'medium'
          });
        }
      }
    }

    return of(suggestions);
  }

  /**
   * Format phone number (French format)
   */
  formatPhoneNumber(phone: string): string {
    if (!phone) return '';

    // Remove all non-digit characters except +
    let cleaned = phone.replace(/[^\d+]/g, '');

    // Handle international format
    if (cleaned.startsWith('+33')) {
      cleaned = cleaned.substring(3);
      const formatted = cleaned.match(/.{1,2}/g)?.join(' ') || cleaned;
      return `+33 ${formatted}`;
    }

    // Handle French mobile format starting with 0
    if (cleaned.startsWith('0') && cleaned.length === 10) {
      return cleaned.match(/.{1,2}/g)?.join(' ') || cleaned;
    }

    return phone;
  }

  /**
   * Get phone formatting suggestion
   */
  getPhoneSuggestions(phone: string): Observable<ValidationSuggestion[]> {
    if (!phone) {
      return of([]);
    }

    const formatted = this.formatPhoneNumber(phone);
    if (formatted !== phone && formatted !== '') {
      return of([{
        field: 'phone',
        originalValue: phone,
        suggestedValue: formatted,
        reason: 'Format de téléphone suggéré',
        confidence: 'high'
      }]);
    }

    return of([]);
  }

  /**
   * Validate field with debounce
   */
  validateFieldWithDebounce<T>(
    valueChanges: Observable<T>,
    validationFn: (value: T) => Observable<AsyncValidationResult>,
    debounce = this.DEFAULT_DEBOUNCE_TIME
  ): Observable<AsyncValidationResult> {
    return valueChanges.pipe(
      debounceTime(debounce),
      distinctUntilChanged(),
      switchMap(value => validationFn(value)),
      catchError(() => of({ valid: true }))
    );
  }

  /**
   * Calculate Levenshtein distance between two strings
   */
  private levenshteinDistance(str1: string, str2: string): number {
    const matrix: number[][] = [];

    for (let i = 0; i <= str2.length; i++) {
      matrix[i] = [i];
    }

    for (let j = 0; j <= str1.length; j++) {
      matrix[0][j] = j;
    }

    for (let i = 1; i <= str2.length; i++) {
      for (let j = 1; j <= str1.length; j++) {
        if (str2.charAt(i - 1) === str1.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1,
            matrix[i][j - 1] + 1,
            matrix[i - 1][j] + 1
          );
        }
      }
    }

    return matrix[str2.length][str1.length];
  }

  /**
   * Check for duplicate entries (generic)
   */
  checkDuplicates(endpoint: string, field: string, value: string): Observable<any[]> {
    return this.http.post<any[]>(
      `${this.API_BASE}${endpoint}/check-duplicates`,
      { [field]: value }
    ).pipe(
      catchError(() => of([]))
    );
  }
}

