    this.loadingMessages = true;
    this.messageApiService.list({ dossierId, size: 100, sort: 'timestamp,desc' }).subscribe({
      next: (response) => {
        this.messages = response.content;
        this.loadingMessages = false;
      },
      error: (err) => {
