      component: KpiWidgetComponent,
      defaultCols: 3,
      defaultRows: 3,
      minCols: 2,
      minRows: 2,
      maxCols: 6,
      maxRows: 4,
      category: 'kpi'
    });

    this.register({
      id: 'kpi-revenue',
      name: 'Chiffre d\'affaires',
      description: 'Chiffre d\'affaires du mois',
