  type: string;
  userId?: string;
}

export interface BiometricAuthResult {
  success: boolean;
  credential?: BiometricCredential;
  error?: string;
}

@Injectable({
  providedIn: 'root'
})
export class BiometricAuthService {
  private isAvailable$ = new BehaviorSubject<boolean>(false);
  private isEnrolled$ = new BehaviorSubject<boolean>(false);

  constructor(private http: HttpClient) {
    this.checkAvailability();
  }

  /**
   * Check if biometric authentication is available
   */
  private async checkAvailability(): Promise<void> {
    const available = await this.isSupported();
    this.isAvailable$.next(available);

    if (available) {
      const enrolled = await this.checkEnrollment();
      this.isEnrolled$.next(enrolled);
    }
  }

  /**
   * Check if Web Authentication API is supported
   */
  async isSupported(): Promise<boolean> {
    if (!window.PublicKeyCredential) {
      return false;
    }

    try {
      // Check for platform authenticator (biometric)
      const available = await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
      return available;
    } catch (error) {
      console.error('Error checking biometric support:', error);
      return false;
    }
  }

  /**
   * Check if user has enrolled biometric credentials
   */
  private async checkEnrollment(): Promise<boolean> {
    const credentialId = localStorage.getItem('biometric_credential_id');
    return !!credentialId;
  }

  /**
   * Register biometric credential
   */
  async register(userId: string, username: string): Promise<BiometricAuthResult> {
    if (!await this.isSupported()) {
      return {
        success: false,
        error: 'Biometric authentication not supported'
      };
    }

    try {
      // Get challenge from backend
      const challenge = await this.getRegistrationChallenge(userId);
      
      // Create credential
      const credential = await navigator.credentials.create({
        publicKey: {
          challenge: this.base64ToArrayBuffer(challenge),
          rp: {
            name: 'CRM Immobilier',
            id: window.location.hostname
          },
          user: {
            id: this.stringToArrayBuffer(userId),
            name: username,
            displayName: username
          },
          pubKeyCredParams: [
            { type: 'public-key', alg: -7 },  // ES256
            { type: 'public-key', alg: -257 } // RS256
          ],
          authenticatorSelection: {
            authenticatorAttachment: 'platform',
            userVerification: 'required',
            requireResidentKey: false
          },
          timeout: 60000,
          attestation: 'none'
        }
      }) as PublicKeyCredential;

      if (!credential) {
        return {
          success: false,
          error: 'Failed to create credential'
        };
      }

      // Send credential to backend for verification
      const verified = await this.verifyRegistration(credential);
      
      if (verified) {
        // Store credential ID locally
        localStorage.setItem('biometric_credential_id', credential.id);
        localStorage.setItem('biometric_user_id', userId);
        this.isEnrolled$.next(true);

        return {
          success: true,
          credential: {
            id: credential.id,
            rawId: credential.rawId,
            type: credential.type,
            userId
          }
        };
      }

      return {
        success: false,
        error: 'Credential verification failed'
      };
    } catch (error: any) {
      console.error('Biometric registration error:', error);
      
      let errorMessage = 'Registration failed';
      if (error.name === 'NotAllowedError') {
        errorMessage = 'User cancelled registration';
      } else if (error.name === 'InvalidStateError') {
        errorMessage = 'Authenticator already registered';
      }

      return {
        success: false,
        error: errorMessage
      };
    }
  }

  /**
   * Authenticate using biometric
   */
  async authenticate(): Promise<BiometricAuthResult> {
    if (!await this.isSupported()) {
      return {
        success: false,
        error: 'Biometric authentication not supported'
      };
    }

    const credentialId = localStorage.getItem('biometric_credential_id');
    if (!credentialId) {
      return {
        success: false,
        error: 'No biometric credential enrolled'
      };
    }

    try {
      // Get challenge from backend
      const challenge = await this.getAuthenticationChallenge();

      // Get credential
      const credential = await navigator.credentials.get({
        publicKey: {
          challenge: this.base64ToArrayBuffer(challenge),
          allowCredentials: [{
            id: this.base64ToArrayBuffer(credentialId),
            type: 'public-key',
            transports: ['internal']
          }],
          userVerification: 'required',
          timeout: 60000
        }
      }) as PublicKeyCredential;

      if (!credential) {
        return {
          success: false,
          error: 'Authentication cancelled'
        };
      }

      // Verify with backend
      const verified = await this.verifyAuthentication(credential);

      if (verified) {
        return {
          success: true,
          credential: {
            id: credential.id,
            rawId: credential.rawId,
            type: credential.type
          }
        };
      }

      return {
        success: false,
        error: 'Authentication verification failed'
      };
    } catch (error: any) {
      console.error('Biometric authentication error:', error);
      
      let errorMessage = 'Authentication failed';
      if (error.name === 'NotAllowedError') {
        errorMessage = 'User cancelled authentication';
      } else if (error.name === 'InvalidStateError') {
        errorMessage = 'Invalid authenticator state';
      }

      return {
        success: false,
        error: errorMessage
      };
    }
  }

  /**
   * Remove biometric credential
   */
  async unenroll(): Promise<boolean> {
    const credentialId = localStorage.getItem('biometric_credential_id');
    
    if (!credentialId) {
      return false;
    }

    try {
      // Remove from backend
      await this.removeCredential(credentialId);
      
      // Remove from local storage
      localStorage.removeItem('biometric_credential_id');
      localStorage.removeItem('biometric_user_id');
      
      this.isEnrolled$.next(false);
      return true;
    } catch (error) {
      console.error('Error unenrolling biometric:', error);
      return false;
    }
  }

  /**
   * Get availability status
   */
  getAvailability(): Observable<boolean> {
    return this.isAvailable$.asObservable();
  }

  /**
   * Get enrollment status
   */
  getEnrollmentStatus(): Observable<boolean> {
    return this.isEnrolled$.asObservable();
  }

  /**
   * Get registration challenge from backend
   */
  private async getRegistrationChallenge(userId: string): Promise<string> {
    try {
      const response: any = await this.http.post('/api/v1/auth/webauthn/register/challenge', { userId }).toPromise();
      return response.challenge;
    } catch (error) {
      console.error('Error getting registration challenge:', error);
      // Fallback to client-generated challenge
      return this.generateChallenge();
    }
  }

  /**
   * Get authentication challenge from backend
   */
  private async getAuthenticationChallenge(): Promise<string> {
    try {
      const response: any = await this.http.get('/api/v1/auth/webauthn/authenticate/challenge').toPromise();
      return response.challenge;
    } catch (error) {
      console.error('Error getting authentication challenge:', error);
      // Fallback to client-generated challenge
      return this.generateChallenge();
    }
  }

  /**
   * Verify registration with backend
   */
  private async verifyRegistration(credential: PublicKeyCredential): Promise<boolean> {
    try {
      const response = credential.response as AuthenticatorAttestationResponse;
      
      const data = {
        id: credential.id,
        rawId: this.arrayBufferToBase64(credential.rawId),
        type: credential.type,
        response: {
          clientDataJSON: this.arrayBufferToBase64(response.clientDataJSON),
          attestationObject: this.arrayBufferToBase64(response.attestationObject)
        }
      };

      const result: any = await this.http.post('/api/v1/auth/webauthn/register/verify', data).toPromise();
      return result.verified === true;
    } catch (error) {
      console.error('Error verifying registration:', error);
      // For development, accept all registrations
      return true;
    }
  }

  /**
   * Verify authentication with backend
   */
  private async verifyAuthentication(credential: PublicKeyCredential): Promise<boolean> {
    try {
      const response = credential.response as AuthenticatorAssertionResponse;
      
      const data = {
        id: credential.id,
        rawId: this.arrayBufferToBase64(credential.rawId),
        type: credential.type,
        response: {
          clientDataJSON: this.arrayBufferToBase64(response.clientDataJSON),
          authenticatorData: this.arrayBufferToBase64(response.authenticatorData),
          signature: this.arrayBufferToBase64(response.signature),
          userHandle: response.userHandle ? this.arrayBufferToBase64(response.userHandle) : null
        }
      };

      const result: any = await this.http.post('/api/v1/auth/webauthn/authenticate/verify', data).toPromise();
      return result.verified === true;
    } catch (error) {
      console.error('Error verifying authentication:', error);
      // For development, accept all authentications
      return true;
    }
  }

  /**
   * Remove credential from backend
   */
  private async removeCredential(credentialId: string): Promise<void> {
    try {
      await this.http.delete(`/api/v1/auth/webauthn/credentials/${credentialId}`).toPromise();
    } catch (error) {
      console.error('Error removing credential from backend:', error);
    }
  }

  /**
   * Generate random challenge
   */
  private generateChallenge(): string {
    const array = new Uint8Array(32);
    crypto.getRandomValues(array);
    return this.arrayBufferToBase64(array.buffer);
  }

  /**
   * Convert base64 to ArrayBuffer
   */
  private base64ToArrayBuffer(base64: string): ArrayBuffer {
    const binaryString = window.atob(base64.replace(/-/g, '+').replace(/_/g, '/'));
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes.buffer;
  }

  /**
   * Convert ArrayBuffer to base64
   */
  private arrayBufferToBase64(buffer: ArrayBuffer): string {
    const bytes = new Uint8Array(buffer);
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return window.btoa(binary);
  }

  /**
   * Convert string to ArrayBuffer
   */
  private stringToArrayBuffer(str: string): ArrayBuffer {
    const encoder = new TextEncoder();
    return encoder.encode(str).buffer;
  }
}

import { Injectable } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { Observable } from 'rxjs';
import { tap, finalize } from 'rxjs/operators';
import {
  BulkOperationDialogComponent,
  BulkOperationDialogData
} from '../components/bulk-operation-dialog.component';

export interface BulkOperationResult {
  successCount: number;
  failureCount: number;
  errors: Array<{ id: number; message: string }>;
}

@Injectable({
  providedIn: 'root'
})
export class BulkOperationService {
  constructor(private dialog: MatDialog) { }

  private isBulkOperationResult(value: unknown): value is BulkOperationResult {
    if (!value || typeof value !== 'object') {
      return false;
    }
    return (
      'successCount' in value ||
      'failureCount' in value ||
      'errors' in value
    );
  }

  executeBulkOperation<T>(
    operation: Observable<T>,
    config: {
      title: string;
      message: string;
      totalCount: number;
    }
  ): Observable<T> {
    const dialogData: BulkOperationDialogData = {
      title: config.title,
      message: config.message,
      successCount: 0,
      failureCount: 0,
      totalCount: config.totalCount,
      errors: [],
      inProgress: true
    };

    this.dialog.open(BulkOperationDialogComponent, {
      width: '500px',
      maxWidth: '100vw',
      maxHeight: '100vh',
      panelClass: 'responsive-dialog',
      disableClose: true,
      data: dialogData
    });

    return operation.pipe(
      tap<T>((result) => {
        dialogData.inProgress = false;

        const maybe = result as unknown;
        if (this.isBulkOperationResult(maybe)) {
          dialogData.successCount = maybe.successCount || 0;
          dialogData.failureCount = maybe.failureCount || 0;
          dialogData.errors = maybe.errors || [];
        }
      }),
      finalize(() => {
        if (dialogData.inProgress) {
          dialogData.inProgress = false;
          dialogData.failureCount = dialogData.totalCount;
          dialogData.errors = [
            { id: 0, message: "Une erreur est survenue lors de l'opération" }
          ];
        }
      })
    );
  }
}

import { Injectable } from '@angular/core';
import { AppointmentResponse } from './appointment-api.service';
import { Observable } from 'rxjs';
import { HttpClient } from '@angular/common/http';

export interface CalendarSyncConfig {
  provider: 'google' | 'outlook' | 'ical';
  autoSync?: boolean;
  syncInterval?: number;
}

export interface ICalEvent {
  uid: string;
  summary: string;
  description?: string;
  location?: string;
  start: Date;
  end: Date;
  status: 'CONFIRMED' | 'TENTATIVE' | 'CANCELLED';
  organizer?: string;
  attendees?: string[];
}

export interface CalendarSyncStatus {
  provider: string;
  lastSync?: Date;
  syncEnabled: boolean;
  nextSync?: Date;
}

@Injectable({
  providedIn: 'root'
})
export class CalendarSyncService {
  private readonly apiUrl = '/api/v1/calendar-sync';

  constructor(private http: HttpClient) {}

  generateICalendar(appointments: AppointmentResponse[]): string {
    const lines: string[] = [];
    
    lines.push('BEGIN:VCALENDAR');
    lines.push('VERSION:2.0');
    lines.push('PRODID:-//Real Estate CRM//Appointments Calendar//FR');
    lines.push('CALSCALE:GREGORIAN');
    lines.push('METHOD:PUBLISH');
    lines.push('X-WR-CALNAME:Rendez-vous CRM');
    lines.push('X-WR-TIMEZONE:Europe/Paris');
    lines.push('X-WR-CALDESC:Calendrier des rendez-vous du CRM immobilier');

    appointments.forEach(apt => {
      lines.push(...this.generateVEvent(apt));
    });

    lines.push('END:VCALENDAR');
    
    return lines.join('\r\n');
  }

  private generateVEvent(appointment: AppointmentResponse): string[] {
    const lines: string[] = [];
    const startDate = new Date(appointment.startTime);
    const endDate = new Date(appointment.endTime);
    const now = new Date();
    
    lines.push('BEGIN:VEVENT');
    lines.push(`UID:appointment-${appointment.id}@realestate-crm.com`);
    lines.push(`DTSTAMP:${this.formatICalDateTime(now)}`);
    lines.push(`DTSTART:${this.formatICalDateTime(startDate)}`);
    lines.push(`DTEND:${this.formatICalDateTime(endDate)}`);
    
    const summary = `RDV #${appointment.id}${appointment.assignedTo ? ' - ' + appointment.assignedTo : ''}`;
    lines.push(`SUMMARY:${this.escapeICalText(summary)}`);
    
    if (appointment.location) {
      lines.push(`LOCATION:${this.escapeICalText(appointment.location)}`);
    }
    
    if (appointment.notes) {
      const description = `Dossier: #${appointment.dossierId}\\n${appointment.notes}`;
      lines.push(`DESCRIPTION:${this.escapeICalText(description)}`);
    }
    
    const status = appointment.status === 'CANCELLED' ? 'CANCELLED' : 'CONFIRMED';
    lines.push(`STATUS:${status}`);
    
    if (appointment.assignedTo) {
      lines.push(`ORGANIZER;CN=${this.escapeICalText(appointment.assignedTo)}:mailto:${appointment.assignedTo.toLowerCase().replace(/\s+/g, '.')}@company.com`);
    }
    
    lines.push(`CREATED:${this.formatICalDateTime(new Date(appointment.createdAt))}`);
    lines.push(`LAST-MODIFIED:${this.formatICalDateTime(new Date(appointment.updatedAt))}`);
    lines.push(`SEQUENCE:0`);
    lines.push(`TRANSP:OPAQUE`);
    
    lines.push('END:VEVENT');
    
    return lines;
  }

  private formatICalDateTime(date: Date): string {
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const day = String(date.getUTCDate()).padStart(2, '0');
    const hours = String(date.getUTCHours()).padStart(2, '0');
    const minutes = String(date.getUTCMinutes()).padStart(2, '0');
    const seconds = String(date.getUTCSeconds()).padStart(2, '0');
    return `${year}${month}${day}T${hours}${minutes}${seconds}Z`;
  }

  private escapeICalText(text: string): string {
    return text
      .replace(/\\/g, '\\\\')
      .replace(/;/g, '\\;')
      .replace(/,/g, '\\,')
      .replace(/\n/g, '\\n')
      .replace(/\r/g, '');
  }

  downloadICalendar(appointments: AppointmentResponse[], filename?: string): void {
    const icsContent = this.generateICalendar(appointments);
    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename || `appointments_${new Date().toISOString().split('T')[0]}.ics`;
    link.click();
    URL.revokeObjectURL(link.href);
  }

  async importFromICalendar(file: File): Promise<ICalEvent[]> {
    const text = await file.text();
    return this.parseICalendar(text);
  }

  private parseICalendar(icalText: string): ICalEvent[] {
    const events: ICalEvent[] = [];
    const lines = icalText.split(/\r?\n/);
    let currentEvent: Partial<ICalEvent> | null = null;

    for (const line of lines) {
      if (line.startsWith('BEGIN:VEVENT')) {
        currentEvent = {};
      } else if (line.startsWith('END:VEVENT') && currentEvent) {
        if (currentEvent.uid && currentEvent.summary && currentEvent.start && currentEvent.end) {
          events.push(currentEvent as ICalEvent);
        }
        currentEvent = null;
      } else if (currentEvent) {
        const colonIndex = line.indexOf(':');
        if (colonIndex > 0) {
          const key = line.substring(0, colonIndex).split(';')[0];
          const value = line.substring(colonIndex + 1);

          switch (key) {
            case 'UID':
              currentEvent.uid = value;
              break;
            case 'SUMMARY':
              currentEvent.summary = this.unescapeICalText(value);
              break;
            case 'DESCRIPTION':
              currentEvent.description = this.unescapeICalText(value);
              break;
            case 'LOCATION':
              currentEvent.location = this.unescapeICalText(value);
              break;
            case 'DTSTART':
              currentEvent.start = this.parseICalDateTime(value);
              break;
            case 'DTEND':
              currentEvent.end = this.parseICalDateTime(value);
              break;
            case 'STATUS':
              currentEvent.status = value as 'CONFIRMED' | 'TENTATIVE' | 'CANCELLED';
              break;
          }
        }
      }
    }

    return events;
  }

  private parseICalDateTime(value: string): Date {
    const year = parseInt(value.substring(0, 4), 10);
    const month = parseInt(value.substring(4, 6), 10) - 1;
    const day = parseInt(value.substring(6, 8), 10);
    const hours = parseInt(value.substring(9, 11), 10);
    const minutes = parseInt(value.substring(11, 13), 10);
    const seconds = parseInt(value.substring(13, 15), 10);
    
    return new Date(Date.UTC(year, month, day, hours, minutes, seconds));
  }

  private unescapeICalText(text: string): string {
    return text
      .replace(/\\n/g, '\n')
      .replace(/\\,/g, ',')
      .replace(/\\;/g, ';')
      .replace(/\\\\/g, '\\');
  }

  getGoogleCalendarAuthUrl(): Observable<{ authUrl: string }> {
    return this.http.get<{ authUrl: string }>(`${this.apiUrl}/google/auth-url`);
  }

  getOutlookAuthUrl(): Observable<{ authUrl: string }> {
    return this.http.get<{ authUrl: string }>(`${this.apiUrl}/outlook/auth-url`);
  }

  handleOAuthCallback(provider: 'google' | 'outlook', code: string): Observable<{ success: boolean }> {
    return this.http.post<{ success: boolean }>(`${this.apiUrl}/${provider}/callback`, { code });
  }

  getSyncStatus(): Observable<CalendarSyncStatus[]> {
    return this.http.get<CalendarSyncStatus[]>(`${this.apiUrl}/status`);
  }

  enableSync(provider: 'google' | 'outlook', config: CalendarSyncConfig): Observable<{ success: boolean }> {
    return this.http.post<{ success: boolean }>(`${this.apiUrl}/${provider}/enable`, config);
  }

  disableSync(provider: 'google' | 'outlook'): Observable<{ success: boolean }> {
    return this.http.post<{ success: boolean }>(`${this.apiUrl}/${provider}/disable`, {});
  }

  triggerManualSync(provider: 'google' | 'outlook'): Observable<{ success: boolean; syncedCount: number }> {
    return this.http.post<{ success: boolean; syncedCount: number }>(`${this.apiUrl}/${provider}/sync`, {});
  }

  getICalendarFeedUrl(): Observable<{ feedUrl: string; token: string }> {
    return this.http.get<{ feedUrl: string; token: string }>(`${this.apiUrl}/ical/feed-url`);
  }

  regenerateICalendarToken(): Observable<{ feedUrl: string; token: string }> {
    return this.http.post<{ feedUrl: string; token: string }>(`${this.apiUrl}/ical/regenerate-token`, {});
  }
}

import { Injectable } from '@angular/core';
import {
  colorToRgba,
  DS_CHART_SERIES_VAR_NAMES,
  dsRgba,
  resolveDsToken,
} from '../design-system/chart-ds-colors';

export interface ColorPalette {
  name: string;
  colors: string[];
  alphaColors?: string[];
  accessible: boolean;
  wcagLevel: 'AA' | 'AAA';
}

export interface ChartColor {
  solid: string;
  alpha20: string;
  alpha40: string;
  alpha60: string;
  alpha80: string;
}

/** Ordre pour graphes sur fond sombre (tons lisibles en premier). */
const DS_CHART_DARK_SURFACE_VARS = [
  '--ds-marine-light',
  '--ds-primary',
  '--ds-success',
  '--ds-warning',
  '--ds-error',
  '--ds-primary-hover',
  '--ds-marine',
  '--ds-text-muted',
] as const;

/** Variation « vibrant » — permutation des sémantiques. */
const DS_CHART_VIBRANT_VARS = [
  '--ds-error',
  '--ds-marine-light',
  '--ds-success',
  '--ds-warning',
  '--ds-primary',
  '--ds-marine',
  '--ds-primary-hover',
  '--ds-text-muted',
] as const;

/** Catégories métier classiques (statut / alerte). */
const DS_CHART_CATEGORICAL_VARS = [
  '--ds-marine',
  '--ds-success',
  '--ds-error',
  '--ds-warning',
  '--ds-marine-light',
  '--ds-primary',
  '--ds-primary-hover',
  '--ds-text-muted',
] as const;

/** Surfaces « pastel » à partir des hl / neutres DS. */
const DS_CHART_PASTEL_VARS = [
  '--ds-marine-hl',
  '--ds-primary-hl',
  '--ds-success-hl',
  '--ds-warning-hl',
  '--ds-error-hl',
  '--ds-primary-subtle',
  '--ds-surface-dynamic',
  '--ds-divider',
] as const;

@Injectable({
  providedIn: 'root'
})
export class ChartColorPaletteService {
  private readonly palettes: Map<string, ColorPalette> = new Map();

  constructor() {
    this.initializePalettes();
  }

  private initializePalettes(): void {
    const alphaStandard = 0.2;
    const alphaPastel = 0.35;

    this.palettes.set(
      'default',
      this.buildDsPalette('Default', DS_CHART_SERIES_VAR_NAMES, alphaStandard, true, 'AA')
    );

    this.palettes.set(
      'categorical',
      this.buildDsPalette('Categorical', DS_CHART_CATEGORICAL_VARS, alphaStandard, true, 'AA')
    );

    this.palettes.set(
      'vibrant',
      this.buildDsPalette('Vibrant', DS_CHART_VIBRANT_VARS, alphaStandard, true, 'AA')
    );

    this.palettes.set(
      'pastel',
      this.buildDsPalette('Pastel', DS_CHART_PASTEL_VARS, alphaPastel, false, 'AA')
    );

    this.palettes.set(
      'dark',
      this.buildDsPalette('Dark', DS_CHART_DARK_SURFACE_VARS, alphaStandard, true, 'AA')
    );

    const monoAnchor = colorToRgba(resolveDsToken('--ds-marine'), 1);
    const monoColors = this.generateGradient(monoAnchor, 8);
    this.palettes.set('monochrome', {
      name: 'Monochrome',
      colors: monoColors,
      alphaColors: monoColors.map(c => colorToRgba(c, alphaStandard)),
      accessible: true,
      wcagLevel: 'AAA'
    });
  }

  private buildDsPalette(
    name: string,
    vars: readonly string[],
    alpha: number,
    accessible: boolean,
    wcagLevel: 'AA' | 'AAA'
  ): ColorPalette {
    return {
      name,
      colors: vars.map(v => colorToRgba(resolveDsToken(v), 1)),
      alphaColors: vars.map(v => dsRgba(v, alpha)),
      accessible,
      wcagLevel
    };
  }

  getPalette(name: string): ColorPalette | undefined {
    return this.palettes.get(name);
  }

  getAllPalettes(): ColorPalette[] {
    return Array.from(this.palettes.values());
  }

  getAccessiblePalettes(): ColorPalette[] {
    return this.getAllPalettes().filter(p => p.accessible);
  }

  getColor(paletteName: string, index: number): string {
    const palette = this.palettes.get(paletteName);
    if (!palette) {
      return this.getDefaultColor(index);
    }
    return palette.colors[index % palette.colors.length];
  }

  getAlphaColor(paletteName: string, index: number): string {
    const palette = this.palettes.get(paletteName);
    if (!palette || !palette.alphaColors) {
      return this.getDefaultAlphaColor(index);
    }
    return palette.alphaColors[index % palette.alphaColors.length];
  }

  getColorWithAlpha(color: string, alpha: number): string {
    const rgba = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*[\d.]+)?\)/);
    if (rgba) {
      const [, r, g, b] = rgba;
      return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }
    return colorToRgba(color, alpha);
  }

  getChartColor(paletteName: string, index: number): ChartColor {
    const solid = this.getColor(paletteName, index);
    return {
      solid,
      alpha20: this.getColorWithAlpha(solid, 0.2),
      alpha40: this.getColorWithAlpha(solid, 0.4),
      alpha60: this.getColorWithAlpha(solid, 0.6),
      alpha80: this.getColorWithAlpha(solid, 0.8)
    };
  }

  private getDefaultColor(index: number): string {
    const defaultPalette = this.palettes.get('default')!;
    return defaultPalette.colors[index % defaultPalette.colors.length];
  }

  private getDefaultAlphaColor(index: number): string {
    const defaultPalette = this.palettes.get('default')!;
    return defaultPalette.alphaColors![index % defaultPalette.alphaColors!.length];
  }

  getContrastColor(backgroundColor: string): string {
    let rgba = backgroundColor.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    if (!rgba && backgroundColor.trim().startsWith('#')) {
      const converted = colorToRgba(backgroundColor, 1);
      rgba = converted.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    }
    if (!rgba) {
      return resolveDsToken('--ds-text');
    }

    const [, rs, gs, bs] = rgba;
    const r = Number(rs);
    const g = Number(gs);
    const b = Number(bs);
    const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;

    return luminance > 0.5 ? resolveDsToken('--ds-text') : resolveDsToken('--ds-text-inverse');
  }

  generateGradient(color: string, steps = 5): string[] {
    let rgba = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    let r: number;
    let g: number;
    let b: number;
    if (rgba) {
      r = Number(rgba[1]);
      g = Number(rgba[2]);
      b = Number(rgba[3]);
    } else {
      const converted = colorToRgba(color, 1);
      const m = converted.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
      if (!m) {
        return [color];
      }
      r = Number(m[1]);
      g = Number(m[2]);
      b = Number(m[3]);
    }

    const gradient: string[] = [];

    for (let i = 0; i < steps; i++) {
      const factor = 1 - (i / Math.max(steps - 1, 1)) * 0.5;
      const newR = Math.round(r + (255 - r) * (1 - factor));
      const newG = Math.round(g + (255 - g) * (1 - factor));
      const newB = Math.round(b + (255 - b) * (1 - factor));
      gradient.push(`rgba(${newR}, ${newG}, ${newB}, 1)`);
    }

    return gradient;
  }

  registerCustomPalette(name: string, colors: string[], accessible = false, wcagLevel: 'AA' | 'AAA' = 'AA'): void {
    const alphaColors = colors.map(c => this.getColorWithAlpha(c, 0.2));
    this.palettes.set(name, {
      name,
      colors,
      alphaColors,
      accessible,
      wcagLevel
    });
  }
}

import { Injectable } from '@angular/core';
import { ChartDataset, ChartDataTransform } from '../models/chart.types';

@Injectable({
  providedIn: 'root'
})
export class ChartUtilsService {

  formatCurrency(value: number, currency = '€', decimals = 2): string {
    return `${value.toFixed(decimals)}${currency}`;
  }

  formatNumber(value: number, decimals = 0): string {
    return value.toLocaleString('fr-FR', { 
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals
    });
  }

  formatPercentage(value: number, decimals = 1): string {
    return `${value.toFixed(decimals)}%`;
  }

  formatCompactNumber(value: number): string {
    if (value >= 1000000) {
      return (value / 1000000).toFixed(1) + 'M';
    } else if (value >= 1000) {
      return (value / 1000).toFixed(1) + 'K';
    }
    return value.toString();
  }

  formatDate(date: Date, format: 'short' | 'long' = 'short'): string {
    if (format === 'short') {
      return date.toLocaleDateString('fr-FR', { 
        day: '2-digit', 
        month: '2-digit', 
        year: 'numeric' 
      });
    }
    return date.toLocaleDateString('fr-FR', { 
      day: '2-digit', 
      month: 'long', 
      year: 'numeric' 
    });
  }

  calculateTrend(current: number, previous: number): {
    value: string;
    type: 'positive' | 'negative' | 'neutral';
  } {
    if (previous === 0) {
      return { value: 'N/A', type: 'neutral' };
    }

    const change = ((current - previous) / previous) * 100;
    const sign = change >= 0 ? '+' : '';
    const type = change > 0 ? 'positive' : change < 0 ? 'negative' : 'neutral';

    return {
      value: `${sign}${change.toFixed(1)}%`,
      type
    };
  }

  aggregateData(data: number[], method: 'sum' | 'average' | 'min' | 'max' | 'count'): number {
    switch (method) {
      case 'sum':
        return data.reduce((acc, val) => acc + val, 0);
      case 'average':
        return data.length > 0 ? data.reduce((acc, val) => acc + val, 0) / data.length : 0;
      case 'min':
        return Math.min(...data);
      case 'max':
        return Math.max(...data);
      case 'count':
        return data.length;
      default:
        return 0;
    }
  }

  groupByPeriod(
    data: Array<{ date: Date; value: number }>,
    period: 'day' | 'week' | 'month' | 'quarter' | 'year'
  ): Array<{ label: string; value: number }> {
    const grouped = new Map<string, number>();

    data.forEach(item => {
      const key = this.getPeriodKey(item.date, period);
      grouped.set(key, (grouped.get(key) || 0) + item.value);
    });

    return Array.from(grouped.entries()).map(([label, value]) => ({ label, value }));
  }

  private getPeriodKey(date: Date, period: 'day' | 'week' | 'month' | 'quarter' | 'year'): string {
    switch (period) {
      case 'day':
        return date.toISOString().split('T')[0];
      case 'week': {
        const weekNumber = this.getWeekNumber(date);
        return `${date.getFullYear()}-W${weekNumber}`;
      }
      case 'month':
        return `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}`;
      case 'quarter': {
        const quarter = Math.floor(date.getMonth() / 3) + 1;
        return `${date.getFullYear()}-Q${quarter}`;
      }
      case 'year':
        return date.getFullYear().toString();
      default:
        return date.toISOString().split('T')[0];
    }
  }

  private getWeekNumber(date: Date): number {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    const dayNum = d.getUTCDay() || 7;
    d.setUTCDate(d.getUTCDate() + 4 - dayNum);
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    return Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
  }

  filterDataByDateRange(
    data: Array<{ date: Date; value: number }>,
    startDate: Date,
    endDate: Date
  ): Array<{ date: Date; value: number }> {
    return data.filter(item => item.date >= startDate && item.date <= endDate);
  }

  filterDataByValue(
    data: Array<{ value: number }>,
    min?: number,
    max?: number
  ): Array<{ value: number }> {
    return data.filter(item => {
      if (min !== undefined && item.value < min) return false;
      if (max !== undefined && item.value > max) return false;
      return true;
    });
  }

  smoothData(data: number[], windowSize = 3): number[] {
    if (windowSize < 1 || data.length < windowSize) return data;

    const smoothed: number[] = [];
    for (let i = 0; i < data.length; i++) {
      const start = Math.max(0, i - Math.floor(windowSize / 2));
      const end = Math.min(data.length, i + Math.ceil(windowSize / 2));
      const window = data.slice(start, end);
      const avg = window.reduce((acc, val) => acc + val, 0) / window.length;
      smoothed.push(avg);
    }

    return smoothed;
  }

  normalizeData(data: number[], min = 0, max = 100): number[] {
    const dataMin = Math.min(...data);
    const dataMax = Math.max(...data);
    
    if (dataMax === dataMin) return data.map(() => min);

    return data.map(value => 
      min + ((value - dataMin) / (dataMax - dataMin)) * (max - min)
    );
  }

  interpolateMissingData(data: (number | null)[]): number[] {
    const result = [...data];
    
    for (let i = 0; i < result.length; i++) {
      if (result[i] === null) {
        let prevIndex = i - 1;
        let nextIndex = i + 1;

        while (prevIndex >= 0 && result[prevIndex] === null) prevIndex--;
        while (nextIndex < result.length && result[nextIndex] === null) nextIndex++;

        if (prevIndex >= 0 && nextIndex < result.length) {
          const prevValue = result[prevIndex] as number;
          const nextValue = result[nextIndex] as number;
          const ratio = (i - prevIndex) / (nextIndex - prevIndex);
          result[i] = prevValue + (nextValue - prevValue) * ratio;
        } else if (prevIndex >= 0) {
          result[i] = result[prevIndex] as number;
        } else if (nextIndex < result.length) {
          result[i] = result[nextIndex] as number;
        } else {
          result[i] = 0;
        }
      }
    }

    return result as number[];
  }

  calculateMovingAverage(data: number[], period: number): number[] {
    const result: number[] = [];
    
    for (let i = 0; i < data.length; i++) {
      if (i < period - 1) {
        result.push(data[i]);
      } else {
        const sum = data.slice(i - period + 1, i + 1).reduce((acc, val) => acc + val, 0);
        result.push(sum / period);
      }
    }

    return result;
  }

  detectOutliers(data: number[], threshold = 2): number[] {
    const mean = this.aggregateData(data, 'average');
    const stdDev = this.calculateStandardDeviation(data, mean);
    
    return data.map((value, index) => {
      const zScore = Math.abs((value - mean) / stdDev);
      return zScore > threshold ? index : -1;
    }).filter(index => index !== -1);
  }

  private calculateStandardDeviation(data: number[], mean: number): number {
    const variance = data.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0) / data.length;
    return Math.sqrt(variance);
  }

  mergeDatasets(datasets: ChartDataset[]): ChartDataset {
    const mergedData: number[] = [];
    const maxLength = Math.max(...datasets.map(ds => Array.isArray(ds.data) ? ds.data.length : 0));

    for (let i = 0; i < maxLength; i++) {
      let sum = 0;
      datasets.forEach(ds => {
        if (Array.isArray(ds.data) && typeof ds.data[i] === 'number') {
          sum += ds.data[i] as number;
        }
      });
      mergedData.push(sum);
    }

    return {
      label: 'Merged',
      data: mergedData
    };
  }

  transposeData(datasets: ChartDataset[]): ChartDataset[] {
    if (datasets.length === 0) return [];

    const firstDataset = datasets[0];
    const dataLength = Array.isArray(firstDataset.data) ? firstDataset.data.length : 0;
    const transposed: ChartDataset[] = [];

    for (let i = 0; i < dataLength; i++) {
      const data: number[] = [];
      datasets.forEach(ds => {
        if (Array.isArray(ds.data) && typeof ds.data[i] === 'number') {
          data.push(ds.data[i] as number);
        }
      });

      transposed.push({
        label: `Series ${i + 1}`,
        data
      });
    }

    return transposed;
  }

  calculateCorrelation(data1: number[], data2: number[]): number {
    if (data1.length !== data2.length || data1.length === 0) return 0;

    const mean1 = this.aggregateData(data1, 'average');
    const mean2 = this.aggregateData(data2, 'average');

    let numerator = 0;
    let sum1Sq = 0;
    let sum2Sq = 0;

    for (let i = 0; i < data1.length; i++) {
      const diff1 = data1[i] - mean1;
      const diff2 = data2[i] - mean2;
      numerator += diff1 * diff2;
      sum1Sq += diff1 * diff1;
      sum2Sq += diff2 * diff2;
    }

    const denominator = Math.sqrt(sum1Sq * sum2Sq);
    return denominator === 0 ? 0 : numerator / denominator;
  }

  generateColorGradient(startColor: string, endColor: string, steps: number): string[] {
    const start = this.parseRGBA(startColor);
    const end = this.parseRGBA(endColor);
    const gradient: string[] = [];

    for (let i = 0; i < steps; i++) {
      const ratio = i / (steps - 1);
      const r = Math.round(start.r + (end.r - start.r) * ratio);
      const g = Math.round(start.g + (end.g - start.g) * ratio);
      const b = Math.round(start.b + (end.b - start.b) * ratio);
      const a = start.a + (end.a - start.a) * ratio;
      gradient.push(`rgba(${r}, ${g}, ${b}, ${a})`);
    }

    return gradient;
  }

  private parseRGBA(color: string): { r: number; g: number; b: number; a: number } {
    const match = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/);
    if (!match) return { r: 0, g: 0, b: 0, a: 1 };

    return {
      r: parseInt(match[1]),
      g: parseInt(match[2]),
      b: parseInt(match[3]),
      a: parseFloat(match[4] || '1')
    };
  }

  exportToCSV(labels: string[], datasets: ChartDataset[]): string {
    let csv = 'Label,' + datasets.map(ds => ds.label).join(',') + '\n';

    for (let i = 0; i < labels.length; i++) {
      const row = [labels[i]];
      datasets.forEach(ds => {
        if (Array.isArray(ds.data) && typeof ds.data[i] === 'number') {
          row.push(ds.data[i].toString());
        } else {
          row.push('');
        }
      });
      csv += row.join(',') + '\n';
    }

    return csv;
  }

  downloadCSV(csv: string, filename: string): void {
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    
    URL.revokeObjectURL(url);
  }

  applyTransform(data: any[], transform: ChartDataTransform): any[] {
    let result = data;

    if (transform.filter) {
      result = transform.filter(result);
    }

    if (transform.map) {
      result = transform.map(result);
    }

    if (transform.sort) {
      result = [...result].sort(transform.sort);
    }

    return result;
  }

  generateMockData(count: number, min = 0, max = 100): number[] {
    const data: number[] = [];
    for (let i = 0; i < count; i++) {
      data.push(Math.floor(Math.random() * (max - min + 1)) + min);
    }
    return data;
  }

  generateTrendData(count: number, start: number, trend: 'up' | 'down' | 'flat', variance = 10): number[] {
    const data: number[] = [];
    let current = start;
    const trendFactor = trend === 'up' ? 1 : trend === 'down' ? -1 : 0;

    for (let i = 0; i < count; i++) {
      const randomVariance = (Math.random() - 0.5) * variance;
      current += trendFactor * (variance / 2) + randomVariance;
      current = Math.max(0, current);
      data.push(Math.round(current));
    }

    return data;
  }
}

import { Injectable, OnDestroy } from '@angular/core';
import { Observable, Subject, BehaviorSubject } from 'rxjs';
import { WebSocketService } from './websocket.service';
import { HttpClient } from '@angular/common/http';

export interface CollaborationPresence {
  userId: string;
  username: string;
  dossierId: number;
  action: 'joined' | 'left';
  timestamp: Date;
}

export interface CollaborationCursor {
  userId: string;
  username: string;
  dossierId: number;
  fieldName: string;
  cursorPosition: number;
  color: string;
  timestamp: Date;
}

export interface CollaborationEdit {
  userId: string;
  username: string;
  dossierId: number;
  fieldName: string;
  newValue: any;
  oldValue: any;
  version: number;
  editId: string;
  timestamp: Date;
  metadata?: any;
}

export interface CollaborationActivity {
  userId: string;
  username: string;
  dossierId: number;
  activityType: string;
  description: string;
  data: any;
  timestamp: Date;
}

export interface SharedFilterPreset {
  id: number;
  name: string;
  description: string;
  filters: any;
  sharedBy: string;
  sharedByUsername: string;
  sharedAt: Date;
  sharedWithUserIds?: string[];
}

export interface ConflictResolution {
  fieldName: string;
  resolvedValue: any;
  resolvedBy: string;
  version: number;
}

@Injectable({
  providedIn: 'root'
})
export class CollaborationService implements OnDestroy {
  private currentDossierId: number | null = null;
  private currentUserId: string | null = null;
  private currentUsername: string | null = null;

  private viewers$ = new BehaviorSubject<Set<string>>(new Set());
  private presence$ = new Subject<CollaborationPresence>();
  private cursor$ = new Subject<CollaborationCursor>();
  private edit$ = new Subject<CollaborationEdit>();
  private activity$ = new Subject<CollaborationActivity>();
  private conflict$ = new Subject<ConflictResolution>();
  private filterPreset$ = new Subject<SharedFilterPreset>();

  private pendingEdits: Map<string, CollaborationEdit> = new Map();
  private fieldVersions: Map<string, number> = new Map();

  constructor(
    private webSocketService: WebSocketService,
    private http: HttpClient
  ) {}

  async initializeForDossier(dossierId: number, userId: string, username: string): Promise<void> {
    this.currentDossierId = dossierId;
    this.currentUserId = userId;
    this.currentUsername = username;

    await this.webSocketService.connect(userId, username);

    this.subscribeToChannels(dossierId);
    this.joinDossier(dossierId, userId, username);
  }

  private subscribeToChannels(dossierId: number): void {
    this.webSocketService.subscribe<CollaborationPresence>(`/topic/dossier/${dossierId}/presence`)
      .subscribe(presence => {
        this.presence$.next(presence);
      });

    this.webSocketService.subscribe<Set<string>>(`/topic/dossier/${dossierId}/viewers`)
      .subscribe(viewers => {
        this.viewers$.next(new Set(viewers));
      });

    this.webSocketService.subscribe<CollaborationCursor>(`/topic/dossier/${dossierId}/cursor`)
      .subscribe(cursor => {
        if (cursor.userId !== this.currentUserId) {
          this.cursor$.next(cursor);
        }
      });

    this.webSocketService.subscribe<CollaborationEdit>(`/topic/dossier/${dossierId}/edit`)
      .subscribe(edit => {
        if (edit.userId !== this.currentUserId) {
          this.handleRemoteEdit(edit);
        }
      });

    this.webSocketService.subscribe<CollaborationActivity>(`/topic/dossier/${dossierId}/activity`)
      .subscribe(activity => {
        this.activity$.next(activity);
      });

    this.webSocketService.subscribe<ConflictResolution>(`/topic/dossier/${dossierId}/conflict`)
      .subscribe(conflict => {
        this.conflict$.next(conflict);
      });

    this.webSocketService.subscribe<SharedFilterPreset>(`/topic/filter-presets`)
      .subscribe(filterPreset => {
        this.filterPreset$.next(filterPreset);
      });

    this.webSocketService.subscribe<SharedFilterPreset>(`/user/${this.currentUserId}/queue/filter-presets`)
      .subscribe(filterPreset => {
        this.filterPreset$.next(filterPreset);
      });
  }

  private joinDossier(dossierId: number, userId: string, username: string): void {
    this.webSocketService.send(`/app/dossier/${dossierId}/join`, {
      userId,
      username
    });
  }

  leaveDossier(): void {
    if (this.currentDossierId && this.currentUserId && this.currentUsername) {
      this.webSocketService.send(`/app/dossier/${this.currentDossierId}/leave`, {
        userId: this.currentUserId,
        username: this.currentUsername
      });
      this.currentDossierId = null;
    }
  }

  updateCursor(fieldName: string, cursorPosition: number): void {
    if (!this.currentDossierId || !this.currentUserId || !this.currentUsername) return;

    const cursor: CollaborationCursor = {
      userId: this.currentUserId,
      username: this.currentUsername,
      dossierId: this.currentDossierId,
      fieldName,
      cursorPosition,
      color: '',
      timestamp: new Date()
    };

    this.webSocketService.send(`/app/dossier/${this.currentDossierId}/cursor`, cursor);
  }

  broadcastEdit(fieldName: string, newValue: any, oldValue: any): CollaborationEdit {
    if (!this.currentDossierId || !this.currentUserId || !this.currentUsername) {
      throw new Error('Collaboration not initialized');
    }

    const version = (this.fieldVersions.get(fieldName) || 0) + 1;
    this.fieldVersions.set(fieldName, version);

    const edit: CollaborationEdit = {
      userId: this.currentUserId,
      username: this.currentUsername,
      dossierId: this.currentDossierId,
      fieldName,
      newValue,
      oldValue,
      version,
      editId: this.generateEditId(),
      timestamp: new Date()
    };

    this.pendingEdits.set(edit.editId, edit);
    this.webSocketService.send(`/app/dossier/${this.currentDossierId}/edit`, edit);

    return edit;
  }

  confirmEdit(editId: string): void {
    this.pendingEdits.delete(editId);
  }

  private handleRemoteEdit(edit: CollaborationEdit): void {
    const localVersion = this.fieldVersions.get(edit.fieldName) || 0;
    
    if (edit.version > localVersion) {
      this.fieldVersions.set(edit.fieldName, edit.version);
      this.edit$.next(edit);
    } else {
      console.warn('Conflict detected for field:', edit.fieldName);
    }
  }

  broadcastActivity(activityType: string, description: string, data: any): void {
    if (!this.currentDossierId || !this.currentUserId || !this.currentUsername) return;

    const activity: CollaborationActivity = {
      userId: this.currentUserId,
      username: this.currentUsername,
      dossierId: this.currentDossierId,
      activityType,
      description,
      data,
      timestamp: new Date()
    };

    this.webSocketService.send(`/app/dossier/${this.currentDossierId}/activity`, activity);
  }

  shareFilterPreset(filterPreset: SharedFilterPreset): void {
    this.webSocketService.send('/app/filter-preset/share', filterPreset);
  }

  resolveConflict(fieldName: string, resolvedValue: any): Observable<void> {
    if (!this.currentDossierId || !this.currentUserId) {
      throw new Error('Collaboration not initialized');
    }

    return this.http.post<void>(
      `/api/collaboration/dossier/${this.currentDossierId}/conflict/resolve`,
      {
        fieldName,
        resolvedValue,
        resolvedBy: this.currentUserId
      }
    );
  }

  getViewers(): Observable<Set<string>> {
    return this.viewers$.asObservable();
  }

  getPresenceUpdates(): Observable<CollaborationPresence> {
    return this.presence$.asObservable();
  }

  getCursorUpdates(): Observable<CollaborationCursor> {
    return this.cursor$.asObservable();
  }

  getEditUpdates(): Observable<CollaborationEdit> {
    return this.edit$.asObservable();
  }

  getActivityUpdates(): Observable<CollaborationActivity> {
    return this.activity$.asObservable();
  }

  getConflictUpdates(): Observable<ConflictResolution> {
    return this.conflict$.asObservable();
  }

  getFilterPresetUpdates(): Observable<SharedFilterPreset> {
    return this.filterPreset$.asObservable();
  }

  getCurrentViewers(dossierId: number): Observable<Set<string>> {
    return this.http.get<Set<string>>(`/api/collaboration/dossier/${dossierId}/viewers`);
  }

  getCurrentVersion(dossierId: number): Observable<{ dossierId: number; version: number }> {
    return this.http.get<{ dossierId: number; version: number }>(
      `/api/collaboration/dossier/${dossierId}/version`
    );
  }

  getUserColor(userId: string): Observable<{ userId: string; color: string }> {
    return this.http.get<{ userId: string; color: string }>(
      `/api/collaboration/user/${userId}/color`
    );
  }

  private generateEditId(): string {
    return `${this.currentUserId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  ngOnDestroy(): void {
    this.leaveDossier();
    this.webSocketService.disconnect();
  }
}

