import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { 
  SignatureRequest, 
  SignatureRequestCreate, 
  ContractTemplate, 
  ContractTemplateCreate 
} from '../models/esignature.models';

@Injectable({
  providedIn: 'root'
})
export class ESignatureApiService {
  private apiUrl = '/api/v1/esignature';

  constructor(private http: HttpClient) {}

  private getHeaders(): HttpHeaders {
    return new HttpHeaders({
      'X-Org-Id': localStorage.getItem('orgId') || 'default',
      'X-User-Id': localStorage.getItem('userId') || 'user'
    });
  }

  createSignatureRequest(request: SignatureRequestCreate): Observable<SignatureRequest> {
    return this.http.post<SignatureRequest>(
      `${this.apiUrl}/signature-requests`,
      request,
      { headers: this.getHeaders() }
    );
  }

  sendSignatureRequest(id: number): Observable<SignatureRequest> {
    return this.http.post<SignatureRequest>(
      `${this.apiUrl}/signature-requests/${id}/send`,
      {},
      { headers: this.getHeaders() }
    );
  }

  getSignatureRequestsByDossier(dossierId: number): Observable<SignatureRequest[]> {
    return this.http.get<SignatureRequest[]>(
      `${this.apiUrl}/signature-requests/dossier/${dossierId}`,
      { headers: this.getHeaders() }
    );
  }

  getSignatureRequest(id: number): Observable<SignatureRequest> {
    return this.http.get<SignatureRequest>(
      `${this.apiUrl}/signature-requests/${id}`,
      { headers: this.getHeaders() }
    );
  }

  uploadTemplate(file: File, template: ContractTemplateCreate): Observable<ContractTemplate> {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('templateName', template.templateName);
    formData.append('templateType', template.templateType);
    
    if (template.description) {
      formData.append('description', template.description);
    }
    
    if (template.signatureFields) {
      formData.append('signatureFields', JSON.stringify(template.signatureFields));
    }

    return this.http.post<ContractTemplate>(
      `${this.apiUrl}/templates`,
      formData,
      { headers: this.getHeaders() }
    );
  }

  getActiveTemplates(): Observable<ContractTemplate[]> {
    return this.http.get<ContractTemplate[]>(
      `${this.apiUrl}/templates`,
      { headers: this.getHeaders() }
    );
  }

  getTemplate(id: number): Observable<ContractTemplate> {
    return this.http.get<ContractTemplate>(
      `${this.apiUrl}/templates/${id}`,
      { headers: this.getHeaders() }
    );
  }

  updateTemplate(id: number, template: ContractTemplateCreate): Observable<ContractTemplate> {
    return this.http.put<ContractTemplate>(
      `${this.apiUrl}/templates/${id}`,
      template,
      { headers: this.getHeaders() }
    );
  }

  deleteTemplate(id: number): Observable<void> {
    return this.http.delete<void>(
      `${this.apiUrl}/templates/${id}`,
      { headers: this.getHeaders() }
    );
  }
}

import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';

const DS_MARINE = DS_CHART_FALLBACK_HEX['--ds-marine'];
const DS_PRIMARY = DS_CHART_FALLBACK_HEX['--ds-primary'];
const DS_BG = DS_CHART_FALLBACK_HEX['--ds-bg'];
const DS_TEXT_MUTED = DS_CHART_FALLBACK_HEX['--ds-text-muted'];
const DS_DIVIDER = DS_CHART_FALLBACK_HEX['--ds-divider'];

export interface ExportProgress {
  stage: 'preparing' | 'generating' | 'complete' | 'error';
  progress: number;
  message: string;
  error?: string;
}

export interface ExportConfig {
  title: string;
  filename: string;
  orientation?: 'portrait' | 'landscape';
  logo?: string;
  primaryColor?: string;
  secondaryColor?: string;
  includeDate?: boolean;
  includePageNumbers?: boolean;
}

export interface ColumnDef {
  key: string;
  header: string;
  width?: number;
}

@Injectable({
  providedIn: 'root'
})
export class ExportService {
  private progressSubject = new Subject<ExportProgress>();
  public progress$ = this.progressSubject.asObservable();

  private defaultConfig: ExportConfig = {
    title: 'Export',
    filename: 'export',
    orientation: 'portrait',
    primaryColor: DS_MARINE,
    secondaryColor: DS_PRIMARY,
    includeDate: true,
    includePageNumbers: true
  };

  constructor() {
    // Injectable service - no initialization required
  }

  async exportToPDF<T>(
    data: T[],
    columns: ColumnDef[],
    config: Partial<ExportConfig> = {}
  ): Promise<void> {
    const finalConfig = { ...this.defaultConfig, ...config };
    
    this.emitProgress('preparing', 0, 'Préparation de l\'export PDF...');

    try {
      const { default: jsPDF } = await import('jspdf');
      const { default: autoTable } = await import('jspdf-autotable');

      this.emitProgress('generating', 30, 'Génération du document PDF...');

      const doc = new jsPDF({
        orientation: finalConfig.orientation,
        unit: 'mm',
        format: 'a4'
      });

      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      let yPosition = 20;

      if (finalConfig.logo) {
        try {
          doc.addImage(finalConfig.logo, 'PNG', 15, 10, 30, 15);
          yPosition = 30;
        } catch (e) {
          console.warn('Could not add logo to PDF', e);
        }
      }

      doc.setFontSize(18);
      doc.setTextColor(finalConfig.primaryColor || DS_MARINE);
      doc.text(finalConfig.title, pageWidth / 2, yPosition, { align: 'center' });
      yPosition += 10;

      if (finalConfig.includeDate) {
        doc.setFontSize(10);
        doc.setTextColor(100, 100, 100);
        doc.text(
          `Date: ${new Date().toLocaleDateString('fr-FR')}`,
          pageWidth / 2,
          yPosition,
          { align: 'center' }
        );
        yPosition += 10;
      }

      this.emitProgress('generating', 60, 'Formatage des données...');

      const tableColumns = columns.map(col => ({
        header: col.header,
        dataKey: col.key
      }));

      const tableRows = data.map(item => {
        const row: { [key: string]: unknown } = {};
        columns.forEach(col => {
          const value = (item as { [key: string]: unknown })[col.key];
          
          if (value === null || value === undefined) {
            row[col.key] = '';
          } else if (typeof value === 'object' && value !== null) {
            row[col.key] = JSON.stringify(value);
          } else if (typeof value === 'string' && value.includes('<')) {
            const temp = document.createElement('div');
            temp.innerHTML = value;
            row[col.key] = temp.textContent || temp.innerText || '';
          } else {
            row[col.key] = value;
          }
        });
        return row;
      });

      autoTable(doc, {
        startY: yPosition,
        head: [tableColumns.map(col => col.header)],
        body: tableRows.map(row => columns.map(col => row[col.key] as string)),
        theme: 'striped',
        headStyles: {
          fillColor: finalConfig.primaryColor || DS_MARINE,
          textColor: '#ffffff',
          fontStyle: 'bold',
          halign: 'left'
        },
        styles: {
          fontSize: 9,
          cellPadding: 3,
          overflow: 'linebreak',
          cellWidth: 'auto'
        },
        columnStyles: columns.reduce((acc, col, index) => {
          if (col.width) {
            acc[index] = { cellWidth: col.width };
          }
          return acc;
        }, {} as { [key: number]: { cellWidth: number } }),
        margin: { left: 15, right: 15 },
        didDrawPage: () => {
          if (finalConfig.includePageNumbers) {
            doc.setFontSize(8);
            doc.setTextColor(150);
            const pageNumber = (doc as any).internal.getCurrentPageInfo().pageNumber;
            doc.text(
              `Page ${pageNumber}`,
              pageWidth / 2,
              pageHeight - 10,
              { align: 'center' }
            );
          }
        }
      });

      this.emitProgress('generating', 90, 'Finalisation du PDF...');

      const filename = `${finalConfig.filename}_${new Date().getTime()}.pdf`;
      doc.save(filename);

      this.emitProgress('complete', 100, 'Export PDF terminé avec succès');
    } catch (error) {
      console.error('PDF export error:', error);
      this.emitProgress('error', 0, 'Erreur lors de l\'export PDF', (error as Error).message);
      throw error;
    }
  }

  async exportToExcel<T>(
    data: T[],
    columns: ColumnDef[],
    config: Partial<ExportConfig> = {}
  ): Promise<void> {
    const finalConfig = { ...this.defaultConfig, ...config };
    
    this.emitProgress('preparing', 0, 'Préparation de l\'export Excel...');

    try {
      this.emitProgress('generating', 30, 'Génération du fichier Excel...');

      const headers = columns.map(col => col.header);
      
      const rows = data.map(item => {
        return columns.map(col => {
          const value = (item as { [key: string]: unknown })[col.key];
          
          if (value === null || value === undefined) {
            return '';
          } else if (typeof value === 'string' && value.includes('<')) {
            const temp = document.createElement('div');
            temp.innerHTML = value;
            return temp.textContent || temp.innerText || '';
          } else if (typeof value === 'object') {
            return JSON.stringify(value);
          }
          return value;
        });
      });

      this.emitProgress('generating', 60, 'Formatage des données...');

      let csvContent = '';
      
      if (finalConfig.title) {
        csvContent += `${finalConfig.title}\n`;
      }
      
      if (finalConfig.includeDate) {
        csvContent += `Date: ${new Date().toLocaleDateString('fr-FR')}\n\n`;
      }

      csvContent += headers.map(h => this.escapeCSV(h)).join(',') + '\n';
      
      rows.forEach(row => {
        csvContent += row.map(cell => this.escapeCSV(String(cell))).join(',') + '\n';
      });

      this.emitProgress('generating', 90, 'Téléchargement du fichier...');

      const BOM = '\uFEFF';
      const blob = new Blob([BOM + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      const url = URL.createObjectURL(blob);
      
      const filename = `${finalConfig.filename}_${new Date().getTime()}.csv`;
      link.setAttribute('href', url);
      link.setAttribute('download', filename);
      link.style.visibility = 'hidden';
      
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      
      URL.revokeObjectURL(url);

      this.emitProgress('complete', 100, 'Export Excel terminé avec succès');
    } catch (error) {
      console.error('Excel export error:', error);
      this.emitProgress('error', 0, 'Erreur lors de l\'export Excel', (error as Error).message);
      throw error;
    }
  }

  async printTable<T>(
    data: T[],
    columns: ColumnDef[],
    config: Partial<ExportConfig> = {}
  ): Promise<void> {
    const finalConfig = { ...this.defaultConfig, ...config };
    
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      throw new Error('Impossible d\'ouvrir la fenêtre d\'impression. Vérifiez que les popups ne sont pas bloquées.');
    }

    const tableHtml = this.generatePrintHTML(data, columns, finalConfig);
    
    printWindow.document.write(tableHtml);
    printWindow.document.close();
    
    printWindow.onload = () => {
      printWindow.focus();
      setTimeout(() => {
        printWindow.print();
      }, 250);
    };
  }

  private generatePrintHTML<T>(
    data: T[],
    columns: ColumnDef[],
    config: ExportConfig
  ): string {
    let html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>${config.title}</title>
  <style>
    @media print {
      * {
        box-shadow: none !important;
        text-shadow: none !important;
      }
      
      body {
        font-family: Arial, sans-serif;
        margin: 0;
        padding: 20px;
        color: #000;
      }
      
      .header {
        text-align: center;
        margin-bottom: 30px;
        border-bottom: 2px solid ${config.primaryColor};
        padding-bottom: 15px;
      }
      
      .header h1 {
        color: ${config.primaryColor};
        margin: 0 0 10px 0;
        font-size: 24px;
      }
      
      .header .date {
        color: ${DS_TEXT_MUTED};
        font-size: 12px;
      }
      
      table {
        width: 100%;
        border-collapse: collapse;
        font-size: 10pt;
        page-break-inside: auto;
      }
      
      thead {
        display: table-header-group;
      }
      
      tr {
        page-break-inside: avoid;
        page-break-after: auto;
      }
      
      th {
        background-color: ${config.primaryColor};
        color: white;
        padding: 10px;
        text-align: left;
        font-weight: bold;
        border: 1px solid ${DS_DIVIDER};
      }
      
      td {
        padding: 8px;
        border: 1px solid ${DS_DIVIDER};
        text-align: left;
      }
      
      tbody tr:nth-child(even) {
        background-color: ${DS_BG};
      }
      
      .footer {
        margin-top: 20px;
        text-align: center;
        font-size: 10px;
        color: ${DS_TEXT_MUTED};
      }
    }
  </style>
</head>
<body>
  <div class="header">`;
    
    if (config.logo) {
      html += `<img src="${config.logo}" alt="Logo" style="max-height: 60px; margin-bottom: 10px;">`;
    }
    
    html += `
    <h1>${config.title}</h1>`;
    
    if (config.includeDate) {
      html += `<div class="date">Date: ${new Date().toLocaleDateString('fr-FR')}</div>`;
    }
    
    html += `
  </div>
  
  <table>
    <thead>
      <tr>`;
    
    columns.forEach(col => {
      html += `<th>${col.header}</th>`;
    });
    
    html += `
      </tr>
    </thead>
    <tbody>`;
    
    data.forEach(item => {
      html += '<tr>';
      columns.forEach(col => {
        let value = (item as { [key: string]: unknown })[col.key];
        
        if (value === null || value === undefined) {
          value = '';
        } else if (typeof value === 'string' && value.includes('<')) {
          const temp = document.createElement('div');
          temp.innerHTML = value;
          value = temp.textContent || temp.innerText || '';
        } else if (typeof value === 'object') {
          value = JSON.stringify(value);
        }
        
        html += `<td>${this.escapeHtml(String(value))}</td>`;
      });
      html += '</tr>';
    });
    
    html += `
    </tbody>
  </table>
  
  <div class="footer">
    Généré le ${new Date().toLocaleString('fr-FR')}
  </div>
</body>
</html>`;
    
    return html;
  }

  private escapeCSV(value: string): string {
    if (value.includes(',') || value.includes('"') || value.includes('\n')) {
      return `"${value.replace(/"/g, '""')}"`;
    }
    return value;
  }

  private escapeHtml(value: string): string {
    const div = document.createElement('div');
    div.textContent = value;
    return div.innerHTML;
  }

  private emitProgress(
    stage: ExportProgress['stage'],
    progress: number,
    message: string,
    error?: string
  ): void {
    this.progressSubject.next({ stage, progress, message, error });
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

export interface FilterPreset {
  id?: number;
  name: string;
  filterType: string;
  description?: string;
  filterConfig: Record<string, unknown>;
  isShared?: boolean;
  isPredefined?: boolean;
  createdBy?: string;
  createdAt?: Date;
  updatedAt?: Date;
}

export interface FilterPresetRequest {
  name: string;
  filterType: string;
  description?: string;
  filterConfig: Record<string, unknown>;
  isShared?: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class FilterPresetService {
  private readonly apiUrl = '/api/v1/filter-presets';
  private readonly STORAGE_KEY_PREFIX = 'filter_preset_';

  constructor(private http: HttpClient) {}

  create(request: FilterPresetRequest): Observable<FilterPreset> {
    return this.http.post<FilterPreset>(this.apiUrl, request).pipe(
      map(preset => this.mapDates(preset))
    );
  }

  getById(id: number): Observable<FilterPreset> {
    return this.http.get<FilterPreset>(`${this.apiUrl}/${id}`).pipe(
      map(preset => this.mapDates(preset))
    );
  }

  getAccessiblePresets(filterType: string): Observable<FilterPreset[]> {
    return this.http.get<FilterPreset[]>(this.apiUrl, {
      params: { filterType }
    }).pipe(
      map(presets => presets.map(p => this.mapDates(p)))
    );
  }

  getPredefinedPresets(filterType: string): Observable<FilterPreset[]> {
    return this.http.get<FilterPreset[]>(`${this.apiUrl}/predefined`, {
      params: { filterType }
    }).pipe(
      map(presets => presets.map(p => this.mapDates(p)))
    );
  }

  getUserPresets(filterType: string): Observable<FilterPreset[]> {
    return this.http.get<FilterPreset[]>(`${this.apiUrl}/user`, {
      params: { filterType }
    }).pipe(
      map(presets => presets.map(p => this.mapDates(p)))
    );
  }

  update(id: number, request: FilterPresetRequest): Observable<FilterPreset> {
    return this.http.put<FilterPreset>(`${this.apiUrl}/${id}`, request).pipe(
      map(preset => this.mapDates(preset))
    );
  }

  delete(id: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/${id}`);
  }

  private mapDates(preset: FilterPreset): FilterPreset {
    return {
      ...preset,
      createdAt: preset.createdAt ? new Date(preset.createdAt) : undefined,
      updatedAt: preset.updatedAt ? new Date(preset.updatedAt) : undefined
    };
  }

  savePresetLocally(context: string, name: string, filters: Record<string, unknown>): void {
    const preset: FilterPreset = {
      name,
      filterType: context,
      filterConfig: filters,
      createdAt: new Date()
    };

    const presets = this.getPresetsLocally(context);
    presets.push(preset);
    
    localStorage.setItem(
      this.getStorageKey(context),
      JSON.stringify(presets)
    );
  }

  getPresetsLocally(context: string): FilterPreset[] {
    const data = localStorage.getItem(this.getStorageKey(context));
    if (!data) return [];

    try {
      const presets = JSON.parse(data);
      return presets.map((p: FilterPreset) => ({
        ...p,
        createdAt: p.createdAt ? new Date(p.createdAt) : undefined
      }));
    } catch {
      return [];
    }
  }

  deletePresetLocally(context: string, name: string): void {
    const presets = this.getPresetsLocally(context).filter(p => p.name !== name);
    localStorage.setItem(
      this.getStorageKey(context),
      JSON.stringify(presets)
    );
  }

  private getStorageKey(context: string): string {
    return `${this.STORAGE_KEY_PREFIX}${context}`;
  }
}

import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

@Injectable({
  providedIn: 'root'
})
export class FocusManagementService {
  private focusStack: HTMLElement[] = [];
  private lastFocusedElement: HTMLElement | null = null;

  constructor(@Inject(PLATFORM_ID) private platformId: object) {}

  saveFocus(): void {
    if (isPlatformBrowser(this.platformId) && document.activeElement instanceof HTMLElement) {
      this.lastFocusedElement = document.activeElement;
      this.focusStack.push(this.lastFocusedElement);
    }
  }

  restoreFocus(): void {
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    const previousElement = this.focusStack.pop();
    if (previousElement && typeof previousElement.focus === 'function') {
      setTimeout(() => {
        previousElement.focus();
      }, 100);
    }
  }

  focusElement(selector: string): boolean {
    if (!isPlatformBrowser(this.platformId)) {
      return false;
    }

    const element = document.querySelector(selector) as HTMLElement;
    if (element && typeof element.focus === 'function') {
      setTimeout(() => {
        element.focus();
      }, 100);
      return true;
    }
    return false;
  }

  focusFirstFocusableElement(container: HTMLElement): boolean {
    if (!isPlatformBrowser(this.platformId)) {
      return false;
    }

    const focusableElements = this.getFocusableElements(container);
    if (focusableElements.length > 0) {
      focusableElements[0].focus();
      return true;
    }
    return false;
  }

  focusLastFocusableElement(container: HTMLElement): boolean {
    if (!isPlatformBrowser(this.platformId)) {
      return false;
    }

    const focusableElements = this.getFocusableElements(container);
    if (focusableElements.length > 0) {
      focusableElements[focusableElements.length - 1].focus();
      return true;
    }
    return false;
  }

  getFocusableElements(container: HTMLElement): HTMLElement[] {
    const focusableSelectors = [
      'a[href]',
      'button:not([disabled])',
      'textarea:not([disabled])',
      'input:not([disabled])',
      'select:not([disabled])',
      '[tabindex]:not([tabindex="-1"])'
    ];

    const elements = container.querySelectorAll(focusableSelectors.join(','));
    return Array.from(elements).filter((element) => {
      return element instanceof HTMLElement && 
             !element.hasAttribute('disabled') &&
             element.offsetParent !== null;
    }) as HTMLElement[];
  }

  trapFocus(container: HTMLElement): () => void {
    if (!isPlatformBrowser(this.platformId)) {
      return () => {
        // No-op cleanup function for non-browser platforms
      };
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') {
        return;
      }

      const focusableElements = this.getFocusableElements(container);
      if (focusableElements.length === 0) {
        return;
      }

      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (event.shiftKey) {
        if (document.activeElement === firstElement) {
          event.preventDefault();
          lastElement.focus();
        }
      } else {
        if (document.activeElement === lastElement) {
          event.preventDefault();
          firstElement.focus();
        }
      }
    };

    container.addEventListener('keydown', handleKeyDown);

    this.focusFirstFocusableElement(container);

    return () => {
      container.removeEventListener('keydown', handleKeyDown);
    };
  }
}

import { Injectable } from '@angular/core';
import { Observable, Subject, interval } from 'rxjs';
import { debounceTime, takeUntil } from 'rxjs/operators';

export interface FormDraft {
  formId: string;
  data: any;
  timestamp: number;
  userId?: string;
}

@Injectable({
  providedIn: 'root'
})
export class FormDraftService {
  private readonly STORAGE_PREFIX = 'form_draft_';
  private readonly AUTO_SAVE_INTERVAL = 30000; // 30 seconds
  private autoSaveSubjects: Map<string, Subject<any>> = new Map();
  private destroySubjects: Map<string, Subject<void>> = new Map();

  /**
   * Save draft to localStorage
   */
  saveDraft(formId: string, data: any, userId?: string): void {
    const draft: FormDraft = {
      formId,
      data,
      timestamp: Date.now(),
      userId
    };

    try {
      localStorage.setItem(
        this.getStorageKey(formId),
        JSON.stringify(draft)
      );
    } catch (error) {
      console.error('Error saving form draft:', error);
    }
  }

  /**
   * Load draft from localStorage
   */
  loadDraft(formId: string, userId?: string): FormDraft | null {
    try {
      const key = this.getStorageKey(formId);
      const stored = localStorage.getItem(key);
      
      if (!stored) {
        return null;
      }

      const draft: FormDraft = JSON.parse(stored);

      // Validate userId if provided
      if (userId && draft.userId && draft.userId !== userId) {
        return null;
      }

      // Check if draft is older than 7 days
      const sevenDaysAgo = Date.now() - (7 * 24 * 60 * 60 * 1000);
      if (draft.timestamp < sevenDaysAgo) {
        this.deleteDraft(formId);
        return null;
      }

      return draft;
    } catch (error) {
      console.error('Error loading form draft:', error);
      return null;
    }
  }

  /**
   * Delete draft from localStorage
   */
  deleteDraft(formId: string): void {
    try {
      localStorage.removeItem(this.getStorageKey(formId));
    } catch (error) {
      console.error('Error deleting form draft:', error);
    }
  }

  /**
   * Check if draft exists
   */
  hasDraft(formId: string): boolean {
    return localStorage.getItem(this.getStorageKey(formId)) !== null;
  }

  /**
   * Setup auto-save for a form
   */
  setupAutoSave(
    formId: string,
    valueChanges: Observable<any>,
    userId?: string,
    debounce = 2000
  ): void {
    // Clean up existing auto-save if any
    this.stopAutoSave(formId);

    const autoSaveSubject = new Subject<any>();
    const destroySubject = new Subject<void>();

    this.autoSaveSubjects.set(formId, autoSaveSubject);
    this.destroySubjects.set(formId, destroySubject);

    // Subscribe to form changes with debounce
    valueChanges
      .pipe(
        debounceTime(debounce),
        takeUntil(destroySubject)
      )
      .subscribe(data => {
        this.saveDraft(formId, data, userId);
        autoSaveSubject.next(data);
      });

    // Periodic auto-save
    interval(this.AUTO_SAVE_INTERVAL)
      .pipe(takeUntil(destroySubject))
      .subscribe(() => {
        // This ensures save even if no changes (heartbeat)
      });
  }

  /**
   * Stop auto-save for a form
   */
  stopAutoSave(formId: string): void {
    const destroySubject = this.destroySubjects.get(formId);
    if (destroySubject) {
      destroySubject.next();
      destroySubject.complete();
      this.destroySubjects.delete(formId);
    }

    const autoSaveSubject = this.autoSaveSubjects.get(formId);
    if (autoSaveSubject) {
      autoSaveSubject.complete();
      this.autoSaveSubjects.delete(formId);
    }
  }

  /**
   * Get auto-save observable for a form
   */
  getAutoSaveObservable(formId: string): Observable<any> | null {
    const subject = this.autoSaveSubjects.get(formId);
    return subject ? subject.asObservable() : null;
  }

  /**
   * List all drafts
   */
  listDrafts(): FormDraft[] {
    const drafts: FormDraft[] = [];
    
    try {
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith(this.STORAGE_PREFIX)) {
          const stored = localStorage.getItem(key);
          if (stored) {
            drafts.push(JSON.parse(stored));
          }
        }
      }
    } catch (error) {
      console.error('Error listing drafts:', error);
    }

    return drafts.sort((a, b) => b.timestamp - a.timestamp);
  }

  /**
   * Clear all drafts
   */
  clearAllDrafts(): void {
    try {
      const keysToRemove: string[] = [];
      
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith(this.STORAGE_PREFIX)) {
          keysToRemove.push(key);
        }
      }

      keysToRemove.forEach(key => localStorage.removeItem(key));
    } catch (error) {
      console.error('Error clearing drafts:', error);
    }
  }

  /**
   * Get storage key for form
   */
  private getStorageKey(formId: string): string {
    return `${this.STORAGE_PREFIX}${formId}`;
  }

  /**
   * Get draft age in minutes
   */
  getDraftAge(draft: FormDraft): number {
    return Math.floor((Date.now() - draft.timestamp) / 60000);
  }
}

import { Injectable } from '@angular/core';
import { AbstractControl, ValidationErrors } from '@angular/forms';
import { Observable, of, timer } from 'rxjs';
import { map, switchMap, debounceTime, distinctUntilChanged, catchError } from 'rxjs/operators';
import { HttpClient } from '@angular/common/http';

export interface ValidationSuggestion {
  field: string;
  originalValue: string;
  suggestedValue: string;
  reason: string;
  confidence: 'low' | 'medium' | 'high';
}

export interface AsyncValidationResult {
  valid: boolean;
  errors?: ValidationErrors;
  suggestions?: ValidationSuggestion[];
}

@Injectable({
  providedIn: 'root'
})
export class FormValidationService {
  private readonly API_BASE = '/api/v1';
  private readonly DEFAULT_DEBOUNCE_TIME = 500;

  constructor(private http: HttpClient) {}

  /**
   * Validates email with backend async validation
   */
  validateEmailAsync(debounce = this.DEFAULT_DEBOUNCE_TIME): (control: AbstractControl) => Observable<ValidationErrors | null> {
    return (control: AbstractControl): Observable<ValidationErrors | null> => {
      if (!control.value) {
        return of(null);
      }

      return timer(debounce).pipe(
        switchMap(() => this.http.post<AsyncValidationResult>(
          `${this.API_BASE}/validation/email`,
          { email: control.value }
        )),
        map(result => result.valid ? null : (result.errors || { invalidEmail: true })),
        catchError(() => of(null))
      );
    };
  }

  /**
   * Validates phone number with backend async validation
   */
  validatePhoneAsync(debounce = this.DEFAULT_DEBOUNCE_TIME): (control: AbstractControl) => Observable<ValidationErrors | null> {
    return (control: AbstractControl): Observable<ValidationErrors | null> => {
      if (!control.value) {
        return of(null);
      }

      return timer(debounce).pipe(
        switchMap(() => this.http.post<AsyncValidationResult>(
          `${this.API_BASE}/validation/phone`,
          { phone: control.value }
        )),
        map(result => result.valid ? null : (result.errors || { invalidPhone: true })),
        catchError(() => of(null))
      );
    };
  }

  /**
   * Get email suggestions for typo correction
   */
  getEmailSuggestions(email: string): Observable<ValidationSuggestion[]> {
    if (!email || !email.includes('@')) {
      return of([]);
    }

    const suggestions: ValidationSuggestion[] = [];
    const commonDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'orange.fr', 'free.fr', 'laposte.net', 'wanadoo.fr'];
    const emailParts = email.split('@');
    const domain = emailParts[1]?.toLowerCase();

    if (!domain) {
      return of([]);
    }

    // Check for common typos
    const typoMap: { [key: string]: string } = {
      'gmial.com': 'gmail.com',
      'gmai.com': 'gmail.com',
      'gmil.com': 'gmail.com',
      'yahooo.com': 'yahoo.com',
      'yaho.com': 'yahoo.com',
      'hotmial.com': 'hotmail.com',
      'hotmai.com': 'hotmail.com',
      'outlok.com': 'outlook.com',
      'outloo.com': 'outlook.com'
    };

    if (typoMap[domain]) {
      suggestions.push({
        field: 'email',
        originalValue: email,
        suggestedValue: `${emailParts[0]}@${typoMap[domain]}`,
        reason: 'Correction de faute de frappe détectée',
        confidence: 'high'
      });
    } else {
      // Suggest similar domains using Levenshtein distance
      for (const commonDomain of commonDomains) {
        const distance = this.levenshteinDistance(domain, commonDomain);
        if (distance === 1 || distance === 2) {
          suggestions.push({
            field: 'email',
            originalValue: email,
            suggestedValue: `${emailParts[0]}@${commonDomain}`,
            reason: 'Vouliez-vous dire ce domaine ?',
            confidence: distance === 1 ? 'high' : 'medium'
          });
        }
      }
    }

    return of(suggestions);
  }

  /**
   * Format phone number (French format)
   */
  formatPhoneNumber(phone: string): string {
    if (!phone) return '';

    // Remove all non-digit characters except +
    let cleaned = phone.replace(/[^\d+]/g, '');

    // Handle international format
    if (cleaned.startsWith('+33')) {
      cleaned = cleaned.substring(3);
      const formatted = cleaned.match(/.{1,2}/g)?.join(' ') || cleaned;
      return `+33 ${formatted}`;
    }

    // Handle French mobile format starting with 0
    if (cleaned.startsWith('0') && cleaned.length === 10) {
      return cleaned.match(/.{1,2}/g)?.join(' ') || cleaned;
    }

    return phone;
  }

  /**
   * Get phone formatting suggestion
   */
  getPhoneSuggestions(phone: string): Observable<ValidationSuggestion[]> {
    if (!phone) {
      return of([]);
    }

    const formatted = this.formatPhoneNumber(phone);
    if (formatted !== phone && formatted !== '') {
      return of([{
        field: 'phone',
        originalValue: phone,
        suggestedValue: formatted,
        reason: 'Format de téléphone suggéré',
        confidence: 'high'
      }]);
    }

    return of([]);
  }

  /**
   * Validate field with debounce
   */
  validateFieldWithDebounce<T>(
    valueChanges: Observable<T>,
    validationFn: (value: T) => Observable<AsyncValidationResult>,
    debounce = this.DEFAULT_DEBOUNCE_TIME
  ): Observable<AsyncValidationResult> {
    return valueChanges.pipe(
      debounceTime(debounce),
      distinctUntilChanged(),
      switchMap(value => validationFn(value)),
      catchError(() => of({ valid: true }))
    );
  }

  /**
   * Calculate Levenshtein distance between two strings
   */
  private levenshteinDistance(str1: string, str2: string): number {
    const matrix: number[][] = [];

    for (let i = 0; i <= str2.length; i++) {
      matrix[i] = [i];
    }

    for (let j = 0; j <= str1.length; j++) {
      matrix[0][j] = j;
    }

    for (let i = 1; i <= str2.length; i++) {
      for (let j = 1; j <= str1.length; j++) {
        if (str2.charAt(i - 1) === str1.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1,
            matrix[i][j - 1] + 1,
            matrix[i - 1][j] + 1
          );
        }
      }
    }

    return matrix[str2.length][str1.length];
  }

  /**
   * Check for duplicate entries (generic)
   */
  checkDuplicates(endpoint: string, field: string, value: string): Observable<any[]> {
    return this.http.post<any[]>(
      `${this.API_BASE}${endpoint}/check-duplicates`,
      { [field]: value }
    ).pipe(
      catchError(() => of([]))
    );
  }
}

import { Injectable } from '@angular/core';

export interface FuzzyMatchResult<T> {
  item: T;
  score: number;
  matches: number[];
}

@Injectable({
  providedIn: 'root'
})
export class FuzzySearchService {
  
  /**
   * Performs fuzzy matching on a collection of items
   * @param items Array of items to search
   * @param query Search query
   * @param getSearchFields Function to extract searchable text from each item
   * @returns Filtered and sorted array of items
   */
  search<T>(
    items: T[],
    query: string,
    getSearchFields: (item: T) => string[]
  ): T[] {
    if (!query || query.trim().length === 0) {
      return items;
    }

    const lowerQuery = query.toLowerCase().trim();
    const results: FuzzyMatchResult<T>[] = [];

    for (const item of items) {
      const fields = getSearchFields(item);
      let maxScore = 0;
      
      for (const field of fields) {
        if (!field) continue;
        const score = this.fuzzyScore(field.toLowerCase(), lowerQuery);
        maxScore = Math.max(maxScore, score);
      }

      if (maxScore > 0) {
        results.push({
          item,
          score: maxScore,
          matches: []
        });
      }
    }

    // Sort by score descending
    results.sort((a, b) => b.score - a.score);

    return results.map(r => r.item);
  }

  /**
   * Calculate fuzzy match score for a text against a query
   * Higher score means better match
   */
  fuzzyScore(text: string, query: string): number {
    if (!text || !query) return 0;
    
    let score = 0;
    let queryIndex = 0;
    let textIndex = 0;
    let consecutiveMatches = 0;
    let wordBoundaryBonus = 0;

    const textWords = text.split(/\s+/);
    const queryWords = query.split(/\s+/);

    // Bonus for word-level matches
    for (const qWord of queryWords) {
      for (const tWord of textWords) {
        if (tWord.startsWith(qWord)) {
          wordBoundaryBonus += 20;
        } else if (tWord.includes(qWord)) {
          wordBoundaryBonus += 10;
        }
      }
    }

    // Character-level fuzzy matching
    while (textIndex < text.length && queryIndex < query.length) {
      if (text[textIndex] === query[queryIndex]) {
        score += 1 + consecutiveMatches * 2;
        consecutiveMatches++;
        queryIndex++;
      } else {
        consecutiveMatches = 0;
      }
      textIndex++;
    }

    // Full match bonus
    if (queryIndex === query.length) {
      score += 50;
    }

    // Exact substring match bonus
    if (text.includes(query)) {
      score += 100;
    }

    // Starts with bonus
    if (text.startsWith(query)) {
      score += 150;
    }

    return score + wordBoundaryBonus;
  }

  /**
   * Highlight matching characters in text
   * Returns HTML string with <mark> tags
   */
  highlight(text: string, query: string): string {
    if (!query || !text) {
      return text;
    }

    const lowerText = text.toLowerCase();
    const lowerQuery = query.toLowerCase();

    // Try exact match first
    const exactIndex = lowerText.indexOf(lowerQuery);
    if (exactIndex !== -1) {
      const before = text.substring(0, exactIndex);
      const match = text.substring(exactIndex, exactIndex + query.length);
      const after = text.substring(exactIndex + query.length);
      return `${before}<mark>${match}</mark>${after}`;
    }

    // Fuzzy highlight
    let result = '';
    let queryIndex = 0;
    
    for (let i = 0; i < text.length && queryIndex < query.length; i++) {
      if (lowerText[i] === lowerQuery[queryIndex]) {
        result += `<mark>${text[i]}</mark>`;
        queryIndex++;
      } else {
        result += text[i];
      }
    }
    
    // Append remaining text
    if (result.length < text.length) {
      result += text.substring(result.length - (queryIndex * 13)); // Adjust for <mark> tags
    }

    return result || text;
  }

  /**
   * Calculate Levenshtein distance between two strings
   * Lower distance means more similar
   */
  levenshteinDistance(str1: string, str2: string): number {
    const m = str1.length;
    const n = str2.length;
    const dp: number[][] = [];

    for (let i = 0; i <= m; i++) {
      dp[i] = [i];
    }

    for (let j = 0; j <= n; j++) {
      dp[0][j] = j;
    }

    for (let i = 1; i <= m; i++) {
      for (let j = 1; j <= n; j++) {
        if (str1[i - 1] === str2[j - 1]) {
          dp[i][j] = dp[i - 1][j - 1];
        } else {
          dp[i][j] = Math.min(
            dp[i - 1][j - 1] + 1, // substitution
            dp[i][j - 1] + 1,     // insertion
            dp[i - 1][j] + 1      // deletion
          );
        }
      }
    }

    return dp[m][n];
  }
}

import { Injectable } from '@angular/core';
import { Router } from '@angular/router';

export type GuidedTourId = 'dashboard-welcome' | 'pipeline-dossiers' | 'messagerie-multicanal';

const STORAGE_KEY = 'atlas_guided_tours_v2';

interface TourState { completed: boolean; skipped?: boolean; completedAt?: string; }
type StateMap = Record<string, TourState>;

@Injectable({ providedIn: 'root' })
export class GuidedTourService {

  /* eslint-disable @typescript-eslint/no-explicit-any */
  shepherd: any = null;
  currentTour: any = null;

  constructor(private router: Router) {}

  /* ── Lazy-load Shepherd ── */
  async loadShepherd(): Promise<any> {
    if (this.shepherd) return this.shepherd;
    try {
      const mod = await import('shepherd.js');
      this.shepherd = mod.default ?? mod;
      return this.shepherd;
    } catch (e) {
      console.warn('[GuidedTour] Shepherd.js unavailable', e);
      return null;
    }
  }

  /* ── Public API ── */

  async autoStartIfNew(): Promise<void> {
    if (!this.isCompleted('dashboard-welcome')) {
      await this.start('dashboard-welcome');
    }
  }

  async start(id: GuidedTourId): Promise<void> {
    const S = await this.loadShepherd();
    if (!S) return;
    this.endCurrent();
    if (id === 'dashboard-welcome')     { await this.runDashboardWelcome(S); return; }
    if (id === 'pipeline-dossiers')     { await this.runPipelineDossiers(S); return; }
    if (id === 'messagerie-multicanal') { await this.runMessagingTour(S);    return; }
  }

  isCompleted(id: GuidedTourId): boolean {
    return this.readState()[id]?.completed ?? false;
  }

  reset(id?: GuidedTourId): void {
    if (id) {
      const all = this.readState();
      delete all[id];
      this.writeState(all);
    } else {
      localStorage.removeItem(STORAGE_KEY);
    }
  }

  endCurrent(): void {
    try { this.currentTour?.cancel(); } catch { /* silent */ }
    this.currentTour = null;
  }

  /* ── Tour builder ── */
  buildTour(S: any, id: GuidedTourId): any {
    const tour = new S.Tour({
      useModalOverlay: true,
      defaultStepOptions: {
        classes: 'atlas-tour-step',
        scrollTo: { behavior: 'smooth', block: 'center' },
        cancelIcon: { enabled: true },
      },
    });
    tour.on('complete', () => this.markTour(id, false));
    tour.on('cancel',   () => this.markTour(id, true));
    return tour;
  }

  makeBtnNext(tour: any, label = 'Suivant') {
    return { text: label, action: () => tour.next(), classes: 'shepherd-btn-primary' };
  }
  makeBtnBack(tour: any) {
    return { text: '← Retour', action: () => tour.back(), classes: 'shepherd-btn-ghost', secondary: true };
  }
  makeBtnSkip(tour: any) {
    return { text: 'Passer', action: () => tour.cancel(), classes: 'shepherd-btn-ghost', secondary: true };
  }
  makeBtnFinish(tour: any) {
    return { text: '✓ Terminer', action: () => tour.complete(), classes: 'shepherd-btn-primary' };
  }

  /* ── Tour 1 : Dashboard Welcome ── */
  async runDashboardWelcome(S: any): Promise<void> {
    const id: GuidedTourId = 'dashboard-welcome';
    const t = this.buildTour(S, id);

    t.addStep({ id: 'welcome', title: '👋 Bienvenue sur Atlasia',
      text: `<p>Votre CRM immobilier est prêt. Ce guide rapide (<strong>3 min</strong>) vous présente les éléments clés.</p>`,
      buttons: [this.makeBtnSkip(t), this.makeBtnNext(t, 'Commencer')],
    });
    t.addStep({ id: 'kpis', title: '📊 Indicateurs clés',
      text: `<p>Ces cartes affichent vos <strong>KPIs en temps réel</strong> : dossiers actifs, relances, RDV et volume signé.</p>`,
      attachTo: { element: '[data-tour="kpis"], .kpi-row', on: 'bottom' as const },
      buttons: [this.makeBtnBack(t), this.makeBtnNext(t)],
    });
    t.addStep({ id: 'kanban', title: '🏗️ Pipeline Kanban',
      text: `<p>Visualisez et faites glisser vos dossiers entre colonnes : <em>Nouveau → Qualification → Qualifié → RDV → Gagné</em>.</p>`,
      attachTo: { element: '[data-tour="kanban"], app-kanban-board', on: 'top' as const },
      buttons: [this.makeBtnBack(t), this.makeBtnNext(t)],
    });
    t.addStep({ id: 'nav', title: '🧭 Navigation',
      text: `<p>Accédez aux <strong>Dossiers</strong>, <strong>Annonces</strong>, <strong>Tâches</strong> et aux outils d'analyse via le menu latéral.</p>`,
      attachTo: { element: '[data-tour="nav"], nav[role="navigation"]', on: 'right' as const },
      buttons: [this.makeBtnBack(t), this.makeBtnNext(t)],
    });
    t.addStep({ id: 'shortcuts', title: '⌨️ Raccourcis clavier',
      text: `<p>Appuyez sur <kbd>?</kbd> pour tous les raccourcis. <kbd>G D</kbd> → Dashboard, <kbd>/</kbd> → Recherche rapide.</p>`,
      buttons: [this.makeBtnBack(t), this.makeBtnFinish(t)],
    });

    this.currentTour = t;
    t.start();
  }

  /* ── Tour 2 : Pipeline & Dossiers ── */
  async runPipelineDossiers(S: any): Promise<void> {
    const id: GuidedTourId = 'pipeline-dossiers';
    const t = this.buildTour(S, id);

    t.addStep({ id: 'intro', title: '📁 Gestion des dossiers',
      text: `<p>Un <strong>dossier</strong> représente un lead ou une transaction. Voici comment les créer et les piloter.</p>`,
      buttons: [this.makeBtnSkip(t), this.makeBtnNext(t, 'Démarrer')],
