        svg: this.getFavoritesSvg()
      },
      {
        name: 'calendar-events',
        context: 'NO_CALENDAR_EVENTS',
        description: 'Empty calendar',
        svg: this.getCalendarEventsSvg()
      }
    ];

    items.forEach(item => {
      this.illustrations.set(item.name, item);
    });
  }

  getIllustration(name: string): SafeHtml | null {
    const item = this.illustrations.get(name);
    return item ? this.sanitizer.bypassSecurityTrustHtml(item.svg) : null;
  }

  getIllustrationByContext(context: string): SafeHtml | null {
    const item = Array.from(this.illustrations.values()).find(i => i.context === context);
    return item ? this.sanitizer.bypassSecurityTrustHtml(item.svg) : null;
  }

  getAllIllustrations(): IllustrationLibraryItem[] {
    return Array.from(this.illustrations.values());
  }

  private getDossierSvg(): string {
    return `
