import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { Capacitor } from '@capacitor/core';
import { NativePlatformService } from './native-platform.service';
import { NativePushNotificationsService } from './native-push-notifications.service';
import { NativeBiometricService } from './native-biometric.service';
import { NativeCalendarService } from './native-calendar.service';
import { NativeFilesystemService } from './native-filesystem.service';
import { Style } from '@capacitor/status-bar';
import { filter, take } from 'rxjs/operators';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';

const DS_STATUS_BAR_HEX = DS_CHART_FALLBACK_HEX['--ds-marine'];

/**
 * Service to initialize native app features on startup
 * Handles platform-specific initialization and deep linking
 */
@Injectable({
  providedIn: 'root'
})
export class NativeAppInitService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();

  constructor(
    private router: Router,
    private platformService: NativePlatformService,
    private pushService: NativePushNotificationsService,
    private biometricService: NativeBiometricService,
    private calendarService: NativeCalendarService,
    private filesystemService: NativeFilesystemService
  ) { }

  /**
   * Initialize native app features
   * Call this in app.component.ts ngOnInit
   */
  async initialize(): Promise<void> {
    if (!this.isNativePlatform) {
      console.log('Running on web platform - native features disabled');
      return;
    }

    console.log('Initializing native app features...');

    try {
      // Initialize platform services
      await this.initializePlatform();

      // Initialize push notifications
      await this.initializePushNotifications();

      // Setup deep link handling
      this.setupDeepLinkHandling();

      // Setup app state monitoring
      this.setupAppStateMonitoring();

      // Setup network monitoring
      this.setupNetworkMonitoring();

      // Setup back button handling (Android)
      this.setupBackButtonHandling();

      // Hide splash screen after initialization
      setTimeout(() => {
        this.platformService.hideSplashScreen().subscribe();
      }, 1000);

      console.log('Native app initialization complete');
    } catch (error) {
      console.error('Error initializing native app:', error);
    }
  }

  /**
   * Initialize platform-specific features
   */
  private async initializePlatform(): Promise<void> {
    const platformInfo = await this.platformService.getPlatformInfo().toPromise();
    console.log('Platform info:', platformInfo);

    // Set status bar style based on platform
    if (platformInfo?.platform === 'ios') {
      this.platformService.setStatusBarStyle(Style.Light, DS_STATUS_BAR_HEX).subscribe();
    } else if (platformInfo?.platform === 'android') {
      this.platformService.setStatusBarStyle(Style.Light, DS_STATUS_BAR_HEX).subscribe();
    }

    // Get device info for analytics
    const deviceInfo = await this.platformService.getDeviceInfo().toPromise();
    console.log('Device info:', deviceInfo);

    // Store device ID for push notifications
    const deviceId = await this.platformService.getDeviceId().toPromise();
    if (deviceId) {
      localStorage.setItem('deviceId', deviceId);
    }
  }

  /**
   * Initialize push notifications
   */
  private async initializePushNotifications(): Promise<void> {
    // Check permissions
    const permission = await this.pushService.checkPermissions().toPromise();

    if (!permission?.granted) {
      // Request permissions on first launch
      const firstLaunch = !localStorage.getItem('appLaunched');
      if (firstLaunch) {
        const result = await this.pushService.requestPermissions().toPromise();
        if (result?.granted) {
          await this.pushService.register().toPromise();
        }
        localStorage.setItem('appLaunched', 'true');
      }
    } else {
      // Already granted, register for notifications
      await this.pushService.register().toPromise();
    }

    // Initialize notification channels (Android)
    this.pushService.initializeDefaultChannels();

    // Listen for push notification token
    this.pushService.token$.pipe(
      filter(token => !!token),
      take(1)
    ).subscribe(token => {
      console.log('Push notification token received:', token);
      // TODO: Send token to backend
      localStorage.setItem('pushToken', token!);
    });

    // Listen for notification actions
    this.pushService.notificationAction$.subscribe(action => {
      console.log('Notification action:', action);
      const route = this.pushService.handleNotificationAction(action);
      if (route) {
        this.router.navigate([route.route], { queryParams: route.params });
      }
    });

    // Listen for foreground notifications
    this.pushService.notificationReceived$.subscribe(notification => {
      console.log('Notification received in foreground:', notification);
      // Show in-app notification or update badge
      this.showInAppNotification(notification);
    });
  }

  /**
   * Setup deep link handling
   */
  private setupDeepLinkHandling(): void {
    // Deep links are handled by NativePlatformService
    // Listen for WhatsApp callback events
    window.addEventListener('whatsapp-callback', (event: any) => {
      const { code, state } = event.detail;
      console.log('WhatsApp callback received:', { code, state });

      // Route to WhatsApp integration page with callback params
      this.router.navigate(['/settings/integrations/whatsapp'], {
        queryParams: { code, state }
      });
    });
  }

  /**
   * Setup app state monitoring
   */
  private setupAppStateMonitoring(): void {
    this.platformService.appState$.subscribe(state => {
      if (state?.isActive) {
        console.log('App became active');
        this.onAppForeground();
      } else {
        console.log('App went to background');
        this.onAppBackground();
      }
    });
  }

  /**
   * Setup network monitoring
   */
  private setupNetworkMonitoring(): void {
    this.platformService.networkStatus$.subscribe(status => {
      if (status) {
        console.log('Network status changed:', status);

        if (!status.connected) {
          this.onOffline();
        } else {
          this.onOnline();
        }
      }
    });
  }

  /**
   * Setup Android back button handling
   */
  private setupBackButtonHandling(): void {
    if (this.platformService.isAndroid()) {
      this.platformService.backButton$.subscribe(() => {
        console.log('Hardware back button pressed');

        // Check if we can navigate back
        const canGoBack = this.router.url !== '/';

        if (canGoBack) {
          this.router.navigate(['..']);
        } else {
          // Confirm exit
          this.confirmExit();
        }
      });
    }
  }

  /**
   * Handle app coming to foreground
   */
  private onAppForeground(): void {
    // Resume biometric authentication if needed
    const biometricPending = sessionStorage.getItem('biometricPending');
    if (biometricPending) {
      this.biometricService.resumeAuthentication().subscribe(result => {
        if (result.success) {
          sessionStorage.removeItem('biometricPending');
        }
      });
    }

    // Sync pending changes
    this.syncPendingChanges();

    // Refresh data if needed
    const lastRefresh = localStorage.getItem('lastDataRefresh');
    const now = Date.now();
    if (!lastRefresh || now - parseInt(lastRefresh) > 5 * 60 * 1000) { // 5 minutes
      this.refreshData();
    }
  }

  /**
   * Handle app going to background
   */
  private onAppBackground(): void {
    // Save any pending changes
    this.savePendingChanges();

    // Clear sensitive data if needed
    const autoLockEnabled = localStorage.getItem('autoLockEnabled') === 'true';
    if (autoLockEnabled) {
      sessionStorage.setItem('biometricPending', 'true');
    }
  }

  /**
   * Handle device going offline
   */
  private onOffline(): void {
    console.log('Device is offline');
    // Show offline indicator
    this.showOfflineMessage();

    // Enable offline mode
    localStorage.setItem('offlineMode', 'true');
  }

  /**
   * Handle device coming online
   */
  private onOnline(): void {
    console.log('Device is online');
    // Hide offline indicator
    this.hideOfflineMessage();

    // Disable offline mode
    localStorage.removeItem('offlineMode');

    // Sync offline changes
    this.syncOfflineChanges();
  }

  /**
   * Sync pending changes with server
   */
  private async syncPendingChanges(): Promise<void> {
    // TODO: Implement sync logic
    console.log('Syncing pending changes...');
  }

  /**
   * Save pending changes locally
   */
  private async savePendingChanges(): Promise<void> {
    // TODO: Implement save logic
    console.log('Saving pending changes...');
  }

  /**
   * Sync offline changes when back online
   */
  private async syncOfflineChanges(): Promise<void> {
    // TODO: Implement offline sync logic
    console.log('Syncing offline changes...');
  }

  /**
   * Refresh app data
   */
  private async refreshData(): Promise<void> {
    // TODO: Implement data refresh logic
    console.log('Refreshing data...');
    localStorage.setItem('lastDataRefresh', Date.now().toString());
  }

  /**
   * Show in-app notification
   */
  private showInAppNotification(notification: any): void {
    // TODO: Show toast or snackbar notification
    console.log('Showing in-app notification:', notification.title);
  }

  /**
   * Show offline message
   */
  private showOfflineMessage(): void {
    // TODO: Show offline indicator in UI
    console.log('Showing offline message');
  }

  /**
   * Hide offline message
   */
  private hideOfflineMessage(): void {
    // TODO: Hide offline indicator in UI
    console.log('Hiding offline message');
  }

  /**
   * Confirm app exit
   */
  private confirmExit(): void {
    // TODO: Show confirmation dialog
    // For now, just exit
    if (confirm('Voulez-vous quitter l\'application ?')) {
      this.platformService.exitApp();
    }
  }

  /**
   * Check and request biometric authentication if enabled
   */
  async checkBiometricAuth(): Promise<boolean> {
    const biometricEnabled = localStorage.getItem('biometricEnabled') === 'true';

    if (!biometricEnabled) {
      return true;
    }

    const availability = await this.biometricService.checkBiometricAvailability().toPromise();

    if (!availability?.available) {
      return true;
    }

    const result = await this.biometricService.authenticate(
      'Authentifiez-vous pour accéder à l\'application'
    ).toPromise();

    return result?.success || false;
  }

  /**
   * Request calendar sync permission
   */
  async requestCalendarPermission(): Promise<boolean> {
    const result = await this.calendarService.requestPermissions().toPromise();
    return result?.granted || false;
  }

  /**
   * Get platform-specific styles
   */
  getPlatformStyles(): { [key: string]: string } {
    if (this.platformService.isIOS()) {
      return {
        '--safe-area-inset-top': 'env(safe-area-inset-top)',
        '--safe-area-inset-bottom': 'env(safe-area-inset-bottom)'
      };
    }
    return {};
  }
}

import { Injectable } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import { BiometricAuth, BiometricAuthOptions } from '@capacitor/biometric';
import { from, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface BiometricAuthResult {
  success: boolean;
  error?: string;
}

export interface BiometricAvailability {
  available: boolean;
  biometryType?: 'fingerprint' | 'face' | 'iris' | 'none';
  strongBiometricAvailable: boolean;
}

/**
 * Service for biometric authentication on mobile devices
 * Supports Face ID, Touch ID, and Android biometrics
 */
@Injectable({
  providedIn: 'root'
})
export class NativeBiometricService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();

  constructor() { /* no-op */ }

  /**
   * Check if biometric authentication is available on the device
   */
  checkBiometricAvailability(): Observable<BiometricAvailability> {
    if (!this.isNativePlatform) {
      return of({
        available: false,
        biometryType: 'none',
        strongBiometricAvailable: false
      } as BiometricAvailability);
    }

    return from(BiometricAuth.checkBiometry()).pipe(
      map((result: any) => ({
        available: !!result.isAvailable,
        biometryType: this.mapBiometryType(result.biometryType),
        strongBiometricAvailable: !!result.strongBiometryIsAvailable
      })),
      catchError((error) => {
        console.error('Error checking biometric availability:', error);
        return of({
          available: false,
          biometryType: 'none',
          strongBiometricAvailable: false
        } as BiometricAvailability);
      })
    );
  }

  /**
   * Authenticate user with biometrics
   * @param reason - The reason for authentication (displayed to user)
   */
  authenticate(reason = 'Veuillez vous authentifier'): Observable<BiometricAuthResult> {
    if (!this.isNativePlatform) {
      return of({
        success: false,
        error: 'Biometric authentication not available on web'
      });
    }

    const options: BiometricAuthOptions = {
      reason,
      cancelTitle: 'Annuler',
      allowDeviceCredential: true,
      iosFallbackTitle: 'Utiliser le code',
      androidTitle: 'Authentification',
      androidSubtitle: 'Atlas Immobilier',
      androidConfirmationRequired: false,
      androidBiometryStrength: 2 // BIOMETRIC_STRONG
    };

    return from(BiometricAuth.authenticate(options)).pipe(
      map(() => ({ success: true })),
      catchError((error) => {
        console.error('Biometric authentication failed:', error);
        return of({
          success: false,
          error: this.mapErrorToMessage(error)
        });
      })
    );
  }

  /**
   * Resume authentication after app was backgrounded during biometric prompt
   */
  resumeAuthentication(): Observable<BiometricAuthResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Not available on web' });
    }

    return from(BiometricAuth.resume()).pipe(
      map(() => ({ success: true })),
      catchError((error) => of({
        success: false,
        error: this.mapErrorToMessage(error)
      }))
    );
  }

  /**
   * Check if biometric authentication is enrolled
   */
  isEnrolled(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(BiometricAuth.checkBiometry()).pipe(
      map((result: any) => result.isAvailable && result.strongBiometryIsAvailable),
      catchError(() => of(false))
    );
  }

  /**
   * Map platform-specific biometry types to common types
   */
  private mapBiometryType(type: number): 'fingerprint' | 'face' | 'iris' | 'none' {
    // iOS: 1 = Touch ID, 2 = Face ID
    // Android: 1 = Fingerprint, 11 = Face, 12 = Iris
    switch (type) {
      case 1:
        return 'fingerprint';
      case 2:
      case 11:
        return 'face';
      case 12:
        return 'iris';
      default:
        return 'none';
    }
  }

  /**
   * Map error codes to user-friendly messages
   */
  private mapErrorToMessage(error: any): string {
    const errorCode = error?.code || error?.message || '';

    if (errorCode.includes('user_cancel') || errorCode.includes('USER_CANCELED')) {
      return 'Authentification annulée par l\'utilisateur';
    }

    if (errorCode.includes('not_available') || errorCode.includes('NOT_AVAILABLE')) {
      return 'L\'authentification biométrique n\'est pas disponible';
    }

    if (errorCode.includes('lockout') || errorCode.includes('LOCKOUT')) {
      return 'Trop de tentatives échouées. Veuillez réessayer plus tard.';
    }

    if (errorCode.includes('no_hardware') || errorCode.includes('NO_HARDWARE')) {
      return 'Aucun capteur biométrique détecté sur cet appareil';
    }

    if (errorCode.includes('not_enrolled') || errorCode.includes('NONE_ENROLLED')) {
      return 'Aucune donnée biométrique enregistrée sur cet appareil';
    }

    return 'Erreur d\'authentification biométrique';
  }

  /**
   * Get human-readable biometry type name
   */
  getBiometryTypeName(type: string): string {
    switch (type) {
      case 'fingerprint':
        return 'Empreinte digitale';
      case 'face':
        return 'Reconnaissance faciale';
      case 'iris':
        return 'Reconnaissance de l\'iris';
      default:
        return 'Biométrie';
    }
  }
}

import { Injectable } from '@angular/core';
import { DS_CHART_FALLBACK_HEX } from '../design-system/chart-ds-colors';
import { Capacitor } from '@capacitor/core';
import { Calendar, CalendarEvent } from '@capacitor/calendar';
import { from, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface CalendarSyncResult {
  success: boolean;
  eventId?: string;
  error?: string;
}

export interface CalendarPermissionResult {
  granted: boolean;
  message?: string;
}

/**
 * Service for native calendar integration
 * Supports creating, updating, and deleting calendar events
 */
@Injectable({
  providedIn: 'root'
})
export class NativeCalendarService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();
  private readonly defaultCalendarTitle = 'Atlas Immobilier';

  constructor() { /* no-op */ }

  /**
   * Request calendar permissions
   */
  requestPermissions(): Observable<CalendarPermissionResult> {
    if (!this.isNativePlatform) {
      return of({ granted: false, message: 'Calendar not available on web' });
    }

    return from(Calendar.requestPermissions()).pipe(
      map((result: any) => ({
        granted: result.readWrite,
        message: result.readWrite ? 'Permissions granted' : 'Permissions denied'
      })),
      catchError((error) => {
        console.error('Error requesting calendar permissions:', error);
        return of({ granted: false, message: error.message || 'Permission request failed' });
      })
    );
  }

  /**
   * Check calendar permissions
   */
  checkPermissions(): Observable<CalendarPermissionResult> {
    if (!this.isNativePlatform) {
      return of({ granted: false });
    }

    return from(Calendar.checkPermissions()).pipe(
      map((result: any) => ({ granted: result.readWrite })),
      catchError(() => of({ granted: false }))
    );
  }

  /**
   * Create a calendar event
   */
  createEvent(event: {
    title: string;
    location?: string;
    notes?: string;
    startDate: Date;
    endDate: Date;
    isAllDay?: boolean;
    alertOffsetInMinutes?: number[];
    calendarName?: string;
  }): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    const calendarEvent: CalendarEvent = {
      title: event.title,
      location: event.location,
      notes: event.notes,
      startDate: event.startDate.toISOString(),
      endDate: event.endDate.toISOString(),
      isAllDay: event.isAllDay || false,
      alertOffsetInMinutes: event.alertOffsetInMinutes || [15], // Default 15min reminder
      calendarName: event.calendarName || this.defaultCalendarTitle
    };

    return from(Calendar.createEvent(calendarEvent)).pipe(
      map((result: any) => ({
        success: true,
        eventId: result.id
      })),
      catchError((error) => {
        console.error('Error creating calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to create calendar event'
        });
      })
    );
  }

  /**
   * Update an existing calendar event
   */
  updateEvent(eventId: string, updates: Partial<CalendarEvent>): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.modifyEvent({
      id: eventId,
      ...updates
    })).pipe(
      map(() => ({
        success: true,
        eventId
      })),
      catchError((error) => {
        console.error('Error updating calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to update calendar event'
        });
      })
    );
  }

  /**
   * Delete a calendar event
   */
  deleteEvent(eventId: string): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.deleteEvent({ id: eventId })).pipe(
      map(() => ({
        success: true,
        eventId
      })),
      catchError((error) => {
        console.error('Error deleting calendar event:', error);
        return of({
          success: false,
          error: error.message || 'Failed to delete calendar event'
        });
      })
    );
  }

  /**
   * Get calendar events within a date range
   */
  getEvents(startDate: Date, endDate: Date): Observable<CalendarEvent[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(Calendar.listEventsInRange({
      startDate: startDate.toISOString(),
      endDate: endDate.toISOString()
    })).pipe(
      map((result: any) => result.events || []),
      catchError((error) => {
        console.error('Error fetching calendar events:', error);
        return of([]);
      })
    );
  }

  /**
   * List all available calendars
   */
  listCalendars(): Observable<any[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(Calendar.listCalendars()).pipe(
      map((result: any) => result.calendars || []),
      catchError((error) => {
        console.error('Error listing calendars:', error);
        return of([]);
      })
    );
  }

  /**
   * Create a calendar for the app if it doesn't exist
   */
  createAppCalendar(): Observable<CalendarSyncResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Calendar not available on web' });
    }

    return from(Calendar.createCalendar({
      title: this.defaultCalendarTitle,
      color: DS_CHART_FALLBACK_HEX['--ds-marine'],
      isVisible: true
    })).pipe(
      map((result: any) => ({
        success: true,
        eventId: result.id
      })),
      catchError((error) => {
        console.error('Error creating app calendar:', error);
        return of({
          success: false,
          error: error.message || 'Failed to create calendar'
        });
      })
    );
  }

  /**
   * Convert application event to calendar event
   */
  convertToCalendarEvent(
    title: string,
    startDate: Date,
    endDate: Date,
    location?: string,
    notes?: string
  ): CalendarEvent {
    return {
      title,
      startDate: startDate.toISOString(),
      endDate: endDate.toISOString(),
      location,
      notes,
      isAllDay: false,
      alertOffsetInMinutes: [15, 60], // 15min and 1hour before
      calendarName: this.defaultCalendarTitle
    };
  }

  /**
   * Sync a visit/appointment to the calendar
   */
  syncVisitToCalendar(visit: {
    id: string;
    title: string;
    startDate: Date;
    endDate: Date;
    address?: string;
    notes?: string;
  }): Observable<CalendarSyncResult> {
    const event = this.convertToCalendarEvent(
      visit.title,
      visit.startDate,
      visit.endDate,
      visit.address,
      visit.notes
    );

    return this.createEvent({
      title: event.title,
      startDate: new Date(event.startDate),
      endDate: new Date(event.endDate),
      location: event.location,
      notes: event.notes,
      alertOffsetInMinutes: event.alertOffsetInMinutes
    });
  }
}

import { Injectable } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import {
  Filesystem,
  Directory,
  Encoding,
  WriteFileResult,
  ReadFileResult,
  StatResult
} from '@capacitor/filesystem';
import { from, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface FileOperationResult {
  success: boolean;
  path?: string;
  uri?: string;
  error?: string;
}

export interface FileMetadata {
  name: string;
  size: number;
  mtime: number;
  ctime: number;
  type: string;
  uri: string;
}

/**
 * Service for native file system operations
 * Handles offline document storage and management
 */
@Injectable({
  providedIn: 'root'
})
export class NativeFilesystemService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();
  private readonly documentsDir = Directory.Documents;
  private readonly dataDir = Directory.Data;
  private readonly appFolder = 'AtlasImmobilier';

  constructor() {
    if (this.isNativePlatform) {
      this.initializeAppFolders();
    }
  }

  /**
   * Initialize application folders
   */
  private async initializeAppFolders(): Promise<void> {
    try {
      await this.createDirectory(this.appFolder, this.documentsDir);
      await this.createDirectory(`${this.appFolder}/documents`, this.documentsDir);
      await this.createDirectory(`${this.appFolder}/images`, this.documentsDir);
      await this.createDirectory(`${this.appFolder}/cache`, this.dataDir);
      await this.createDirectory(`${this.appFolder}/offline`, this.dataDir);
    } catch (error) {
      console.error('Error initializing app folders:', error);
    }
  }

  /**
   * Create a directory
   */
  private async createDirectory(path: string, directory: Directory): Promise<void> {
    try {
      await Filesystem.mkdir({
        path,
        directory,
        recursive: true
      });
    } catch (error: any) {
      if (!error.message?.includes('exists')) {
        throw error;
      }
    }
  }

  /**
   * Write a file
   */
  writeFile(
    path: string,
    data: string | Blob,
    directory: Directory = this.documentsDir,
    encoding: Encoding = Encoding.UTF8
  ): Observable<FileOperationResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Filesystem not available on web' });
    }

    const fullPath = `${this.appFolder}/${path}`;

    return from(
      Filesystem.writeFile({
        path: fullPath,
        data: typeof data === 'string' ? data : data,
        directory,
        encoding: typeof data === 'string' ? encoding : undefined
      })
    ).pipe(
      map((result: WriteFileResult) => ({
        success: true,
        path: fullPath,
        uri: result.uri
      })),
      catchError((error) => {
        console.error('Error writing file:', error);
        return of({
          success: false,
          error: error.message || 'Failed to write file'
        });
      })
    );
  }

  /**
   * Read a file
   */
  readFile(
    path: string,
    directory: Directory = this.documentsDir,
    encoding: Encoding = Encoding.UTF8
  ): Observable<string | null> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    const fullPath = `${this.appFolder}/${path}`;

    return from(
      Filesystem.readFile({
        path: fullPath,
        directory,
        encoding
      })
    ).pipe(
      map((result: ReadFileResult) => result.data as string),
      catchError((error) => {
        console.error('Error reading file:', error);
        return of(null);
      })
    );
  }

  /**
   * Delete a file
   */
  deleteFile(
    path: string,
    directory: Directory = this.documentsDir
  ): Observable<FileOperationResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Filesystem not available on web' });
    }

    const fullPath = `${this.appFolder}/${path}`;

    return from(
      Filesystem.deleteFile({
        path: fullPath,
        directory
      })
    ).pipe(
      map(() => ({
        success: true,
        path: fullPath
      })),
      catchError((error) => {
        console.error('Error deleting file:', error);
        return of({
          success: false,
          error: error.message || 'Failed to delete file'
        });
      })
    );
  }

  /**
   * Check if a file exists
   */
  fileExists(
    path: string,
    directory: Directory = this.documentsDir
  ): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    const fullPath = `${this.appFolder}/${path}`;

    return from(
      Filesystem.stat({
        path: fullPath,
        directory
      })
    ).pipe(
      map(() => true),
      catchError(() => of(false))
    );
  }

  /**
   * Get file metadata
   */
  getFileMetadata(
    path: string,
    directory: Directory = this.documentsDir
  ): Observable<FileMetadata | null> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    const fullPath = `${this.appFolder}/${path}`;

    return from(
      Filesystem.stat({
        path: fullPath,
        directory
      })
    ).pipe(
      map((result: StatResult) => ({
        name: path.split('/').pop() || path,
        size: result.size,
        mtime: result.mtime,
        ctime: result.ctime || 0,
        type: result.type,
        uri: result.uri
      })),
      catchError((error) => {
        console.error('Error getting file metadata:', error);
        return of(null);
      })
    );
  }

  /**
   * List files in a directory
   */
  listFiles(
    path = '',
    directory: Directory = this.documentsDir
  ): Observable<string[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    const fullPath = path ? `${this.appFolder}/${path}` : this.appFolder;

    return from(
      Filesystem.readdir({
        path: fullPath,
        directory
      })
    ).pipe(
      map((result) => result.files.map(f => f.name)),
      catchError((error) => {
        console.error('Error listing files:', error);
        return of([]);
      })
    );
  }

  /**
   * Copy a file
   */
  copyFile(
    fromPathStr: string,
    to: string,
    directory: Directory = this.documentsDir
  ): Observable<FileOperationResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Filesystem not available on web' });
    }

    const fromPath = `${this.appFolder}/${fromPathStr}`;
    const toPath = `${this.appFolder}/${to}`;

    return from(
      Filesystem.copy({
        from: fromPath,
        to: toPath,
        directory
      })
    ).pipe(
      map(() => ({
        success: true,
        path: toPath
      })),
      catchError((error) => {
        console.error('Error copying file:', error);
        return of({
          success: false,
          error: error.message || 'Failed to copy file'
        });
      })
    );
  }

  /**
   * Rename/move a file
   */
  renameFile(
    fromPathStr: string,
    to: string,
    directory: Directory = this.documentsDir
  ): Observable<FileOperationResult> {
    if (!this.isNativePlatform) {
      return of({ success: false, error: 'Filesystem not available on web' });
    }

    const fromPath = `${this.appFolder}/${fromPathStr}`;
    const toPath = `${this.appFolder}/${to}`;

    return from(
      Filesystem.rename({
        from: fromPath,
        to: toPath,
        directory
      })
    ).pipe(
      map(() => ({
        success: true,
        path: toPath
      })),
      catchError((error) => {
        console.error('Error renaming file:', error);
        return of({
          success: false,
          error: error.message || 'Failed to rename file'
        });
      })
    );
  }

  /**
   * Get URI for a file
   */
  getUri(
    path: string,
    directory: Directory = this.documentsDir
  ): Observable<string | null> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    const fullPath = `${this.appFolder}/${path}`;

    return from(
      Filesystem.getUri({
        path: fullPath,
        directory
      })
    ).pipe(
      map((result) => result.uri),
      catchError((error) => {
        console.error('Error getting file URI:', error);
        return of(null);
      })
    );
  }

  /**
   * Save document for offline access
   */
  saveDocumentOffline(
    documentId: string,
    content: string | Blob,
    filename: string
  ): Observable<FileOperationResult> {
    const path = `offline/documents/${documentId}/${filename}`;
    return this.writeFile(path, content, this.dataDir);
  }

  /**
   * Get offline document
   */
  getOfflineDocument(documentId: string, filename: string): Observable<string | null> {
    const path = `offline/documents/${documentId}/${filename}`;
    return this.readFile(path, this.dataDir);
  }

  /**
   * Delete offline document
   */
  deleteOfflineDocument(documentId: string, filename: string): Observable<FileOperationResult> {
    const path = `offline/documents/${documentId}/${filename}`;
    return this.deleteFile(path, this.dataDir);
  }

  /**
   * Cache image locally
   */
  cacheImage(imageUrl: string, imageData: Blob): Observable<FileOperationResult> {
    const filename = this.getFilenameFromUrl(imageUrl);
    const path = `cache/images/${filename}`;
    return this.writeFile(path, imageData, this.dataDir);
  }

  /**
   * Get cached image
   */
  getCachedImage(imageUrl: string): Observable<string | null> {
    const filename = this.getFilenameFromUrl(imageUrl);
    const path = `cache/images/${filename}`;
    return this.getUri(path, this.dataDir);
  }

  /**
   * Clear cache
   */
  clearCache(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(
      Filesystem.rmdir({
        path: `${this.appFolder}/cache`,
        directory: this.dataDir,
        recursive: true
      })
    ).pipe(
      map(() => true),
      catchError(() => of(false))
    );
  }

  /**
   * Get total storage used by app
   */
  getStorageSize(): Observable<number> {
    if (!this.isNativePlatform) {
      return of(0);
    }

    return this.listFiles('', this.documentsDir).pipe(
      map(files => {
        // Simplified - in production, recursively calculate all file sizes
        return files.length * 1024; // Placeholder
      })
    );
  }

  /**
   * Extract filename from URL
   */
  private getFilenameFromUrl(url: string): string {
    const parts = url.split('/');
    const filename = parts[parts.length - 1];
    return filename.split('?')[0] || `file_${Date.now()}`;
  }

  /**
   * Convert base64 to blob
   */
  base64ToBlob(base64: string, contentType = ''): Blob {
    const byteCharacters = atob(base64.split(',')[1] || base64);
    const byteArrays = [];

    for (let offset = 0; offset < byteCharacters.length; offset += 512) {
      const slice = byteCharacters.slice(offset, offset + 512);
      const byteNumbers = new Array(slice.length);

      for (let i = 0; i < slice.length; i++) {
        byteNumbers[i] = slice.charCodeAt(i);
      }

      const byteArray = new Uint8Array(byteNumbers);
      byteArrays.push(byteArray);
    }

    return new Blob(byteArrays, { type: contentType });
  }
}

import { Injectable } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import { App, AppState } from '@capacitor/app';
import { Device, DeviceInfo } from '@capacitor/device';
import { Network, ConnectionStatus } from '@capacitor/network';
import { StatusBar, Style } from '@capacitor/status-bar';
import { SplashScreen } from '@capacitor/splash-screen';
import { Keyboard, KeyboardInfo } from '@capacitor/keyboard';
import { Haptics, ImpactStyle } from '@capacitor/haptics';
import { ScreenReader } from '@capacitor/screen-reader';
import { Share, ShareOptions } from '@capacitor/share';
import { Browser } from '@capacitor/browser';
import { BehaviorSubject, from, Observable, of, Subject } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface PlatformInfo {
  isNative: boolean;
  platform: 'ios' | 'android' | 'web';
  deviceInfo: DeviceInfo | null;
}

/**
 * Service for native platform capabilities
 * Provides unified interface for device features
 */
@Injectable({
  providedIn: 'root'
})
export class NativePlatformService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();
  private readonly platform = Capacitor.getPlatform();

  private readonly networkStatusSubject = new BehaviorSubject<ConnectionStatus | null>(null);
  private readonly appStateSubject = new BehaviorSubject<AppState | null>(null);
  private readonly keyboardSubject = new Subject<KeyboardInfo>();
  private readonly backButtonSubject = new Subject<void>();

  public readonly networkStatus$ = this.networkStatusSubject.asObservable();
  public readonly appState$ = this.appStateSubject.asObservable();
  public readonly keyboard$ = this.keyboardSubject.asObservable();
  public readonly backButton$ = this.backButtonSubject.asObservable();

  constructor() {
    if (this.isNativePlatform) {
      this.initializePlatformListeners();
    }
  }

  /**
   * Initialize platform event listeners
   */
  private async initializePlatformListeners(): Promise<void> {
    // Network status
    Network.addListener('networkStatusChange', (status) => {
      this.networkStatusSubject.next(status);
    });

    const initialNetwork = await Network.getStatus();
    this.networkStatusSubject.next(initialNetwork);

    // App state changes
    App.addListener('appStateChange', (state) => {
      this.appStateSubject.next(state);
    });

    // Keyboard events
    Keyboard.addListener('keyboardWillShow', (info) => {
      this.keyboardSubject.next(info);
    });

    Keyboard.addListener('keyboardDidShow', (info) => {
      this.keyboardSubject.next(info);
    });

    // Hardware back button (Android)
    App.addListener('backButton', () => {
      this.backButtonSubject.next();
    });

    // Deep link handling
    App.addListener('appUrlOpen', (event) => {
      this.handleDeepLink(event.url);
    });
  }

  /**
   * Get platform information
   */
  getPlatformInfo(): Observable<PlatformInfo> {
    if (!this.isNativePlatform) {
      return of({
        isNative: false,
        platform: 'web',
        deviceInfo: null
      });
    }

    return from(Device.getInfo()).pipe(
      map((deviceInfo) => ({
        isNative: true,
        platform: this.platform as 'ios' | 'android',
        deviceInfo
      })),
      catchError(() => of({
        isNative: true,
        platform: this.platform as 'ios' | 'android',
        deviceInfo: null
      }))
    );
  }

  /**
   * Get device info
   */
  getDeviceInfo(): Observable<DeviceInfo | null> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    return from(Device.getInfo()).pipe(
      catchError(() => of(null))
    );
  }

  /**
   * Get device ID
   */
  getDeviceId(): Observable<string | null> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    return from(Device.getId()).pipe(
      map((result) => result.identifier),
      catchError(() => of(null))
    );
  }

  /**
   * Get battery info
   */
  getBatteryInfo(): Observable<any> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    return from(Device.getBatteryInfo()).pipe(
      catchError(() => of(null))
    );
  }

  /**
   * Check if device is online
   */
  isOnline(): boolean {
    return this.networkStatusSubject.value?.connected ?? true;
  }

  /**
   * Get network status
   */
  getNetworkStatus(): Observable<ConnectionStatus> {
    if (!this.isNativePlatform) {
      return of({ connected: true, connectionType: 'wifi' });
    }

    return from(Network.getStatus());
  }

  /**
   * Hide splash screen
   */
  hideSplashScreen(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(SplashScreen.hide()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Show splash screen
   */
  showSplashScreen(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(SplashScreen.show()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Set status bar style
   */
  setStatusBarStyle(style: Style, backgroundColor?: string): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(
      Promise.all([
        StatusBar.setStyle({ style }),
        backgroundColor ? StatusBar.setBackgroundColor({ color: backgroundColor }) : Promise.resolve()
      ])
    ).pipe(
      map(() => undefined),
      catchError(() => of(undefined))
    );
  }

  /**
   * Hide status bar
   */
  hideStatusBar(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(StatusBar.hide()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Show status bar
   */
  showStatusBar(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(StatusBar.show()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Hide keyboard
   */
  hideKeyboard(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Keyboard.hide()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Show keyboard
   */
  showKeyboard(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Keyboard.show()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Trigger haptic feedback
   */
  hapticImpact(style: ImpactStyle = ImpactStyle.Medium): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Haptics.impact({ style })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Trigger haptic notification
   */
  hapticNotification(type: 'SUCCESS' | 'WARNING' | 'ERROR'): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Haptics.notification({ type: type as any })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Trigger haptic vibration
   */
  hapticVibrate(duration = 300): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Haptics.vibrate({ duration })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Check if screen reader is enabled
   */
  isScreenReaderEnabled(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(ScreenReader.isEnabled()).pipe(
      map((result) => result.value),
      catchError(() => of(false))
    );
  }

  /**
   * Speak text using screen reader
   */
  speak(text: string): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(ScreenReader.speak({ value: text })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Share content
   */
  share(options: ShareOptions): Observable<boolean> {
    if (!this.isNativePlatform) {
      // Fallback to Web Share API
      if (navigator.share) {
        return from(navigator.share({
          title: options.title,
          text: options.text,
          url: options.url
        })).pipe(
          map(() => true),
          catchError(() => of(false))
        );
      }
      return of(false);
    }

    return from(Share.share(options)).pipe(
      map(() => true),
      catchError(() => of(false))
    );
  }

  /**
   * Open URL in browser
   */
  openUrl(url: string): Observable<void> {
    if (!this.isNativePlatform) {
      window.open(url, '_blank');
      return of(undefined);
    }

    return from(Browser.open({ url })).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Close browser
   */
  closeBrowser(): Observable<void> {
    if (!this.isNativePlatform) {
      return of(undefined);
    }

    return from(Browser.close()).pipe(
      catchError(() => of(undefined))
    );
  }

  /**
   * Exit app (Android only)
   */
  exitApp(): void {
    if (this.isNativePlatform) {
      App.exitApp();
    }
  }

  /**
   * Get app info
   */
  getAppInfo(): Observable<any> {
    if (!this.isNativePlatform) {
      return of(null);
    }

    return from(App.getInfo()).pipe(
      catchError(() => of(null))
    );
  }

  /**
   * Handle deep links
   */
  private handleDeepLink(url: string): void {
    console.log('Deep link opened:', url);

    // Parse WhatsApp callback URLs
    if (url.includes('atlasimmo://whatsapp/callback')) {
      const urlParams = new URLSearchParams(url.split('?')[1]);
      const code = urlParams.get('code');
      const state = urlParams.get('state');

      // Dispatch event for WhatsApp callback handling
      window.dispatchEvent(new CustomEvent('whatsapp-callback', {
        detail: { code, state }
      }));
    }

    // Handle other deep link patterns
    if (url.includes('atlasimmo://dossiers/')) {
      const dossierId = url.split('dossiers/')[1]?.split('?')[0];
      if (dossierId) {
        window.location.href = `/dossiers/${dossierId}`;
      }
    }
  }

  /**
   * Check if running on iOS
   */
  isIOS(): boolean {
    return this.platform === 'ios';
  }

  /**
   * Check if running on Android
   */
  isAndroid(): boolean {
    return this.platform === 'android';
  }

  /**
   * Check if running on web
   */
  isWeb(): boolean {
    return this.platform === 'web';
  }

  /**
   * Clean up listeners
   */
  removeAllListeners(): void {
    if (this.isNativePlatform) {
      Network.removeAllListeners();
      App.removeAllListeners();
      Keyboard.removeAllListeners();
    }
  }
}

import { Injectable } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import {
  PushNotifications,
  PushNotificationSchema,
  ActionPerformed,
  Token
} from '@capacitor/push-notifications';
import { BehaviorSubject, from, Observable, of, Subject } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

export interface PushNotificationPermission {
  granted: boolean;
  denied: boolean;
}

export interface NotificationPayload {
  title: string;
  body: string;
  data?: any;
  badge?: number;
  sound?: string;
  channelId?: string;
}

/**
 * Service for native push notifications
 * Handles FCM (Android) and APNs (iOS) push notifications
 */
@Injectable({
  providedIn: 'root'
})
export class NativePushNotificationsService {
  private readonly isNativePlatform = Capacitor.isNativePlatform();

  private readonly tokenSubject = new BehaviorSubject<string | null>(null);
  private readonly notificationReceivedSubject = new Subject<PushNotificationSchema>();
  private readonly notificationActionSubject = new Subject<ActionPerformed>();

  public readonly token$ = this.tokenSubject.asObservable();
  public readonly notificationReceived$ = this.notificationReceivedSubject.asObservable();
  public readonly notificationAction$ = this.notificationActionSubject.asObservable();

  constructor() {
    if (this.isNativePlatform) {
      this.initializePushNotifications();
    }
  }

  /**
   * Initialize push notification listeners
   */
  private initializePushNotifications(): void {
    // Registration success
    PushNotifications.addListener('registration', (token: Token) => {
      console.log('Push registration success, token:', token.value);
      this.tokenSubject.next(token.value);
    });

    // Registration error
    PushNotifications.addListener('registrationError', (error: any) => {
      console.error('Push registration error:', error);
      this.tokenSubject.next(null);
    });

    // Notification received (app in foreground)
    PushNotifications.addListener('pushNotificationReceived',
      (notification: PushNotificationSchema) => {
        console.log('Push notification received:', notification);
        this.notificationReceivedSubject.next(notification);
      }
    );

    // Notification action performed (user tapped)
    PushNotifications.addListener('pushNotificationActionPerformed',
      (notification: ActionPerformed) => {
        console.log('Push notification action performed:', notification);
        this.notificationActionSubject.next(notification);
      }
    );
  }

  /**
   * Request push notification permissions
   */
  requestPermissions(): Observable<PushNotificationPermission> {
    if (!this.isNativePlatform) {
      return of({ granted: false, denied: true });
    }

    return from(PushNotifications.requestPermissions()).pipe(
      map((result) => ({
        granted: result.receive === 'granted',
        denied: result.receive === 'denied'
      })),
      catchError((error) => {
        console.error('Error requesting push notification permissions:', error);
        return of({ granted: false, denied: true });
      })
    );
  }

  /**
   * Check current push notification permissions
   */
  checkPermissions(): Observable<PushNotificationPermission> {
    if (!this.isNativePlatform) {
      return of({ granted: false, denied: true });
    }

    return from(PushNotifications.checkPermissions()).pipe(
      map((result) => ({
        granted: result.receive === 'granted',
        denied: result.receive === 'denied'
      })),
      catchError(() => of({ granted: false, denied: true }))
    );
  }

  /**
   * Register for push notifications
   */
  register(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.register()).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error registering for push notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Get the current push notification token
   */
  getToken(): string | null {
    return this.tokenSubject.value;
  }

  /**
   * Get delivered notifications (iOS only)
   */
  getDeliveredNotifications(): Observable<PushNotificationSchema[]> {
    if (!this.isNativePlatform) {
      return of([]);
    }

    return from(PushNotifications.getDeliveredNotifications()).pipe(
      map((result) => result.notifications),
      catchError(() => of([]))
    );
  }

  /**
   * Remove delivered notifications
   */
  removeDeliveredNotifications(notificationIds: string[]): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.removeDeliveredNotifications({
      notifications: notificationIds.map(id => ({ id } as any))
    })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error removing delivered notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Remove all delivered notifications
   */
  removeAllDeliveredNotifications(): Observable<boolean> {
    if (!this.isNativePlatform) {
      return of(false);
    }

    return from(PushNotifications.removeAllDeliveredNotifications()).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error removing all delivered notifications:', error);
        return of(false);
      })
    );
  }

  /**
   * Create notification channel (Android only)
   */
  createChannel(
    id: string,
    name: string,
    importance: 1 | 2 | 3 | 4 | 5 = 3,
    description?: string,
    sound?: string,
    vibration = true,
    lights = true
  ): Observable<boolean> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of(false);
    }

    return from(PushNotifications.createChannel({
      id,
      name,
      importance,
      description,
      sound,
      vibration,
      lights
    })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error creating notification channel:', error);
        return of(false);
      })
    );
  }

  /**
   * Delete notification channel (Android only)
   */
  deleteChannel(channelId: string): Observable<boolean> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of(false);
    }

    return from(PushNotifications.deleteChannel({ id: channelId })).pipe(
      map(() => true),
      catchError((error) => {
        console.error('Error deleting notification channel:', error);
        return of(false);
      })
    );
  }

  /**
   * List notification channels (Android only)
   */
  listChannels(): Observable<any[]> {
    if (!this.isNativePlatform || Capacitor.getPlatform() !== 'android') {
      return of([]);
    }

    return from(PushNotifications.listChannels()).pipe(
      map((result) => result.channels),
      catchError(() => of([]))
    );
  }

  /**
   * Initialize default notification channels (Android)
   */
  initializeDefaultChannels(): void {
    if (Capacitor.getPlatform() === 'android') {
      this.createChannel(
        'messages',
        'Messages',
        5,
        'Notifications pour les nouveaux messages',
        'default',
        true,
        true
      ).subscribe();

      this.createChannel(
        'appointments',
        'Rendez-vous',
        4,
        'Rappels de rendez-vous',
        'default',
        true,
        false
      ).subscribe();

      this.createChannel(
        'updates',
        'Mises à jour',
        3,
        'Mises à jour de dossiers',
        undefined,
        false,
        false
      ).subscribe();

      this.createChannel(
        'general',
        'Général',
        2,
        'Notifications générales',
        undefined,
        false,
        false
      ).subscribe();
    }
  }

  /**
   * Handle notification routing based on action
   */
  handleNotificationAction(action: ActionPerformed): { route: string; params?: any } | null {
    const data = action.notification.data;

    if (!data) {
      return { route: '/' };
    }

    // Route based on notification type
    switch (data.type) {
      case 'message':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'messages' }
        };

      case 'appointment':
        return {
          route: `/calendar`,
          params: { eventId: data.eventId }
        };

      case 'task':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'tasks', taskId: data.taskId }
        };

      case 'dossier_update':
        return {
          route: `/dossiers/${data.dossierId}`
        };

      case 'whatsapp':
        return {
          route: `/dossiers/${data.dossierId}`,
          params: { tab: 'whatsapp' }
        };

      default:
        return { route: '/' };
    }
  }

  /**
   * Clean up listeners
   */
  removeAllListeners(): void {
    if (this.isNativePlatform) {
      PushNotifications.removeAllListeners();
    }
  }
}

import { Injectable } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';

interface NavigationHistoryEntry {
  url: string;
  scrollPosition: [number, number];
}

@Injectable({
  providedIn: 'root'
})
export class NavigationService {
  private navigationHistory: NavigationHistoryEntry[] = [];
  private currentIndex = -1;
  private scrollPositions = new Map<string, [number, number]>();
  private isBackNavigation = false;
  private isForwardNavigation = false;

  constructor(private router: Router) {
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd)
    ).subscribe((event) => {
      this.updateNavigationHistory(event.urlAfterRedirects);
    });

    window.addEventListener('popstate', () => {
      this.isBackNavigation = true;
      setTimeout(() => {
        this.isBackNavigation = false;
      }, 500);
    });
  }

  private updateNavigationHistory(url: string): void {
    if (this.currentIndex >= 0 && this.navigationHistory[this.currentIndex]) {
      const scrollPos = this.getScrollPosition();
      this.scrollPositions.set(this.navigationHistory[this.currentIndex].url, scrollPos);
    }

    if (this.currentIndex < this.navigationHistory.length - 1) {
      this.navigationHistory = this.navigationHistory.slice(0, this.currentIndex + 1);
    }

    this.navigationHistory.push({
      url,
      scrollPosition: [0, 0]
    });
    this.currentIndex = this.navigationHistory.length - 1;
  }

  getRouteAnimation(): string {
    if (this.isBackNavigation) {
      return 'slideRight';
    } else if (this.isForwardNavigation) {
      return 'slideLeft';
    }
    return 'fadeIn';
  }

  saveScrollPosition(url?: string): void {
    const currentUrl = url || this.router.url;
    const scrollPos = this.getScrollPosition();
    this.scrollPositions.set(currentUrl, scrollPos);
  }

  restoreScrollPosition(url?: string): void {
    const currentUrl = url || this.router.url;
    const scrollPos = this.scrollPositions.get(currentUrl);
    
    if (scrollPos) {
      setTimeout(() => {
        window.scrollTo(scrollPos[0], scrollPos[1]);
      }, 0);
    } else {
      setTimeout(() => {
        window.scrollTo(0, 0);
      }, 0);
    }
  }

  private getScrollPosition(): [number, number] {
    return [window.pageXOffset || document.documentElement.scrollLeft || 0,
            window.pageYOffset || document.documentElement.scrollTop || 0];
  }

  navigateBack(): void {
    if (this.currentIndex > 0) {
      this.isBackNavigation = true;
      this.currentIndex--;
      const entry = this.navigationHistory[this.currentIndex];
      this.router.navigateByUrl(entry.url).then(() => {
        this.restoreScrollPosition(entry.url);
        setTimeout(() => {
          this.isBackNavigation = false;
        }, 500);
      });
    }
  }

  navigateForward(): void {
    if (this.currentIndex < this.navigationHistory.length - 1) {
      this.isForwardNavigation = true;
      this.currentIndex++;
      const entry = this.navigationHistory[this.currentIndex];
      this.router.navigateByUrl(entry.url).then(() => {
        this.restoreScrollPosition(entry.url);
        setTimeout(() => {
          this.isForwardNavigation = false;
        }, 500);
      });
    }
  }

  canGoBack(): boolean {
    return this.currentIndex > 0;
  }

  canGoForward(): boolean {
    return this.currentIndex < this.navigationHistory.length - 1;
  }
}

import { Injectable, OnDestroy } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, BehaviorSubject, timer, Subject } from 'rxjs';
import { switchMap, tap, takeUntil } from 'rxjs/operators';
import { environment } from '../../environments/environment';

export interface NotificationResponse {
  id: number;
  orgId: string;
  dossierId?: number;
  type: 'EMAIL' | 'SMS' | 'WHATSAPP' | 'IN_APP';
  status: 'PENDING' | 'SENT' | 'FAILED';
  templateId: string;
  variables?: { [key: string]: any };
  recipient: string;
  subject?: string;
  message?: string;
  actionUrl?: string;
  errorMessage?: string;
  retryCount: number;
  maxRetries: number;
  sentAt?: string;
  readAt?: string;
  createdAt: string;
  updatedAt: string;
}

export interface NotificationPage {
  content: NotificationResponse[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
}

@Injectable({
  providedIn: 'root'
})
export class NotificationApiService implements OnDestroy {
  private apiUrl = `${environment.apiBaseUrl}/v1/notifications`;
  private pollingInterval = 30000;
  private unreadCountSubject = new BehaviorSubject<number>(0);
  public unreadCount$ = this.unreadCountSubject.asObservable();
  private destroy$ = new Subject<void>();

  constructor(private http: HttpClient) {
    this.startPolling();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private startPolling(): void {
    timer(0, this.pollingInterval)
      .pipe(
        takeUntil(this.destroy$),
        switchMap(() => this.fetchUnreadCount())
      )
      .subscribe({
        next: (count) => this.unreadCountSubject.next(count),
        error: (err) => console.error('Error polling unread count:', err)
      });
  }

  private fetchUnreadCount(): Observable<number> {
    return this.http.get<number>(`${this.apiUrl}/unread-count`);
  }

  list(
    dossierId?: number,
    type?: string,
    status?: string,
    page = 0,
    size = 20,
    sort = 'createdAt,desc'
  ): Observable<NotificationPage> {
    let params = new HttpParams()
      .set('page', page.toString())
      .set('size', size.toString())
      .set('sort', sort);

    if (dossierId) {
      params = params.set('dossierId', dossierId.toString());
    }
    if (type) {
      params = params.set('type', type);
    }
    if (status) {
      params = params.set('status', status);
    }

    return this.http.get<NotificationPage>(this.apiUrl, { params });
  }

  getById(id: number): Observable<NotificationResponse> {
    return this.http.get<NotificationResponse>(`${this.apiUrl}/${id}`);
  }

  markAsRead(id: number): Observable<NotificationResponse> {
    return this.http.patch<NotificationResponse>(`${this.apiUrl}/${id}/read`, {}).pipe(
      tap(() => {
        const currentCount = this.unreadCountSubject.value;
        if (currentCount > 0) {
          this.unreadCountSubject.next(currentCount - 1);
        }
      })
    );
  }

  markAsUnread(id: number): Observable<NotificationResponse> {
    return this.http.patch<NotificationResponse>(`${this.apiUrl}/${id}/unread`, {}).pipe(
      tap(() => {
        const currentCount = this.unreadCountSubject.value;
        this.unreadCountSubject.next(currentCount + 1);
      })
    );
  }

  getUnreadCount(): Observable<number> {
    return this.unreadCount$;
  }

  refreshUnreadCount(): void {
    this.fetchUnreadCount().subscribe({
      next: (count) => this.unreadCountSubject.next(count),
      error: (err) => console.error('Error refreshing unread count:', err)
    });
  }
}

