import { Injectable } from '@angular/core';
import { MatSnackBar, MatSnackBarConfig, MatSnackBarHorizontalPosition, MatSnackBarVerticalPosition } from '@angular/material/snack-bar';
import { HttpClient } from '@angular/common/http';
import { ThemeService } from './theme.service';
import { EnhancedSnackbarComponent } from '../components/enhanced-snackbar.component';
import { catchError, of } from 'rxjs';

export type NotificationType = 'success' | 'error' | 'warning' | 'info';

export type NotificationAction = 'Annuler' | 'Réessayer' | 'Voir détails' | 'Fermer';

export interface NotificationConfig {
  message: string;
  type: NotificationType;
  action?: NotificationAction | string;
  onAction?: () => void;
  duration?: number;
  dismissible?: boolean;
  position?: {
    horizontal?: MatSnackBarHorizontalPosition;
    vertical?: MatSnackBarVerticalPosition;
  };
  priority?: 'low' | 'normal' | 'high' | 'critical';
}

export interface ErrorLogPayload {
  message: string;
  level: 'error' | 'warning';
  timestamp: string;
  userAgent: string;
  url: string;
  stackTrace?: string;
  context?: Record<string, any>;
}

@Injectable({
  providedIn: 'root'
})
export class NotificationService {
  private queue: NotificationConfig[] = [];
  private isShowing = false;
  private currentSnackBarRef: any = null;

  private readonly DEFAULT_DURATIONS: Record<NotificationType | 'critical', number> = {
    success: 4000,
    info: 5000,
    warning: 6000,
    error: 8000,
    critical: 10000
  };

  private readonly DEFAULT_POSITIONS = {
    horizontal: 'center' as MatSnackBarHorizontalPosition,
    vertical: 'top' as MatSnackBarVerticalPosition
  };

  constructor(
    private snackBar: MatSnackBar,
    private http: HttpClient,
    private themeService: ThemeService
  ) {}

  success(message: string, action?: string, onAction?: () => void): void {
    this.show({
      message,
      type: 'success',
      action,
      onAction,
      priority: 'normal'
    });
  }

  error(message: string, action?: string, onAction?: () => void, logToBackend = true): void {
    this.show({
      message,
      type: 'error',
      action: action || 'Fermer',
      onAction,
      priority: 'high'
    });

    if (logToBackend) {
      this.logErrorToBackend(message);
    }
  }

  warning(message: string, action?: string, onAction?: () => void, logToBackend = false): void {
    this.show({
      message,
      type: 'warning',
      action,
      onAction,
      priority: 'normal'
    });

    if (logToBackend) {
      this.logWarningToBackend(message);
    }
  }

  info(message: string, action?: string, onAction?: () => void): void {
    this.show({
      message,
      type: 'info',
      action,
      onAction,
      priority: 'low'
    });
  }

  critical(message: string, action?: string, onAction?: () => void): void {
    this.show({
      message,
      type: 'error',
      action: action || 'Fermer',
      onAction,
      priority: 'critical',
      dismissible: true
    });

    this.logErrorToBackend(message, { severity: 'critical' });
  }

  show(config: NotificationConfig): void {
    const priority = config.priority || 'normal';
    
    if (priority === 'critical') {
      this.queue.unshift(config);
      if (this.isShowing && this.currentSnackBarRef) {
        this.currentSnackBarRef.dismiss();
      }
    } else if (priority === 'high') {
      const criticalIndex = this.queue.findIndex(n => n.priority === 'critical');
      if (criticalIndex >= 0) {
        this.queue.splice(criticalIndex + 1, 0, config);
      } else {
        this.queue.unshift(config);
      }
    } else {
      this.queue.push(config);
    }

    if (!this.isShowing) {
      this.showNext();
    }
  }

  private showNext(): void {
    if (this.queue.length === 0) {
      this.isShowing = false;
      return;
    }

    this.isShowing = true;
    const notification = this.queue.shift();
    if (!notification) {
      return;
    }

    const duration = notification.duration !== undefined 
      ? notification.duration 
      : this.getDuration(notification.type, notification.priority);

    const position = notification.position || this.DEFAULT_POSITIONS;

    const snackBarConfig: MatSnackBarConfig = {
      duration,
      horizontalPosition: position.horizontal,
      verticalPosition: position.vertical,
      panelClass: this.getPanelClasses(notification.type),
      data: {
        ...notification,
        dismissible: notification.dismissible !== false
      }
    };

    this.currentSnackBarRef = this.snackBar.openFromComponent(
      EnhancedSnackbarComponent,
      snackBarConfig
    );

    this.currentSnackBarRef.afterDismissed().subscribe(() => {
      this.currentSnackBarRef = null;
      setTimeout(() => this.showNext(), 300);
    });
  }

  private getDuration(type: NotificationType, priority?: string): number {
    if (priority === 'critical') {
      return this.DEFAULT_DURATIONS.critical;
    }
    return this.DEFAULT_DURATIONS[type];
  }

  private getPanelClasses(type: NotificationType): string[] {
    const classes = [`notification-${type}`];
    
    if (this.themeService.isDarkTheme()) {
      classes.push('dark-theme-snackbar');
    }

    return classes;
  }

  dismiss(): void {
    if (this.currentSnackBarRef) {
      this.currentSnackBarRef.dismiss();
    }
  }

  clearQueue(): void {
    this.queue = [];
    this.dismiss();
  }

  getQueueLength(): number {
    return this.queue.length;
  }

  private logErrorToBackend(message: string, context?: Record<string, any>): void {
    const payload: ErrorLogPayload = {
      message,
      level: 'error',
      timestamp: new Date().toISOString(),
      userAgent: navigator.userAgent,
      url: window.location.href,
      context
    };

    this.http.post('/api/v1/observability/client-errors', payload)
      .pipe(
        catchError(err => {
          console.error('Failed to log error to backend:', err);
          return of(null);
        })
      )
      .subscribe();
  }

  private logWarningToBackend(message: string, context?: Record<string, any>): void {
    const payload: ErrorLogPayload = {
      message,
      level: 'warning',
      timestamp: new Date().toISOString(),
      userAgent: navigator.userAgent,
      url: window.location.href,
      context
    };

    this.http.post('/api/v1/observability/client-errors', payload)
      .pipe(
        catchError(err => {
          console.error('Failed to log warning to backend:', err);
          return of(null);
        })
      )
      .subscribe();
  }

  successWithRetry(message: string, retryAction: () => void): void {
    this.success(message, 'Réessayer', retryAction);
  }

  errorWithRetry(message: string, retryAction: () => void): void {
    this.error(message, 'Réessayer', retryAction);
  }

  errorWithDetails(message: string, detailsAction: () => void): void {
    this.error(message, 'Voir détails', detailsAction);
  }

  successWithUndo(message: string, undoAction: () => void): void {
    this.success(message, 'Annuler', undoAction);
  }
}

import { Injectable } from '@angular/core';
import { QueuedAction, QueuedActionType } from './offline-queue.service';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';

export enum ConflictResolutionStrategy {
  SERVER_WINS = 'SERVER_WINS',
  CLIENT_WINS = 'CLIENT_WINS',
  MERGE = 'MERGE',
  MANUAL = 'MANUAL'
}

export interface ConflictInfo {
  action: QueuedAction;
  serverData: any;
  clientData: any;
  conflictFields: string[];
}

export interface MergeResult {
  resolved: boolean;
  mergedData: any;
  conflicts?: ConflictInfo[];
}

@Injectable({
  providedIn: 'root'
})
export class OfflineConflictResolverService {
  private defaultStrategy: ConflictResolutionStrategy = ConflictResolutionStrategy.SERVER_WINS;

  constructor(private http: HttpClient) {}

  setDefaultStrategy(strategy: ConflictResolutionStrategy): void {
    this.defaultStrategy = strategy;
  }

  async detectConflict(action: QueuedAction): Promise<ConflictInfo | null> {
    try {
      const serverData = await this.fetchServerData(action);
      if (!serverData) {
        return null;
      }

      const conflictFields = this.compareData(action.payload, serverData);
      
      if (conflictFields.length === 0) {
        return null;
      }

      return {
        action,
        serverData,
        clientData: action.payload,
        conflictFields
      };
    } catch (error) {
      return null;
    }
  }

  async resolveConflict(
    conflict: ConflictInfo,
    strategy?: ConflictResolutionStrategy
  ): Promise<MergeResult> {
    const resolutionStrategy = strategy || this.defaultStrategy;

    switch (resolutionStrategy) {
      case ConflictResolutionStrategy.SERVER_WINS:
        return this.resolveServerWins(conflict);
      
      case ConflictResolutionStrategy.CLIENT_WINS:
        return this.resolveClientWins(conflict);
      
      case ConflictResolutionStrategy.MERGE:
        return this.resolveAutoMerge(conflict);
      
      case ConflictResolutionStrategy.MANUAL:
        return {
          resolved: false,
          mergedData: null,
          conflicts: [conflict]
        };
      
      default:
        return this.resolveServerWins(conflict);
    }
  }

  private resolveServerWins(conflict: ConflictInfo): MergeResult {
    return {
      resolved: true,
      mergedData: conflict.serverData
    };
  }

  private resolveClientWins(conflict: ConflictInfo): MergeResult {
    return {
      resolved: true,
      mergedData: conflict.clientData
    };
  }

  private resolveAutoMerge(conflict: ConflictInfo): MergeResult {
    const merged = { ...conflict.serverData };
    const unresolvedConflicts: string[] = [];

    for (const field of conflict.conflictFields) {
      const serverValue = conflict.serverData[field];
      const clientValue = conflict.clientData[field];

      if (this.canAutoMerge(field, serverValue, clientValue)) {
        merged[field] = this.mergeValues(field, serverValue, clientValue);
      } else {
        unresolvedConflicts.push(field);
        merged[field] = serverValue;
      }
    }

    return {
      resolved: unresolvedConflicts.length === 0,
      mergedData: merged,
      conflicts: unresolvedConflicts.length > 0 ? [conflict] : undefined
    };
  }

  private compareData(clientData: any, serverData: any): string[] {
    const conflicts: string[] = [];
    const clientKeys = Object.keys(clientData);
    const serverKeys = Object.keys(serverData);
    const allKeys = [...new Set([...clientKeys, ...serverKeys])];

    for (let i = 0; i < allKeys.length; i++) {
      const key = allKeys[i];
      if (this.isSystemField(key)) {
        continue;
      }

      const clientValue = clientData[key];
      const serverValue = serverData[key];

      if (!this.valuesEqual(clientValue, serverValue)) {
        conflicts.push(key);
      }
    }

    return conflicts;
  }

  private isSystemField(field: string): boolean {
    const systemFields = ['id', 'createdAt', 'updatedAt', 'version', 'orgId', 'createdBy', 'updatedBy'];
    return systemFields.includes(field);
  }

  private valuesEqual(value1: any, value2: any): boolean {
    if (value1 === value2) {
      return true;
    }

    if (value1 == null || value2 == null) {
      return value1 === value2;
    }

    if (typeof value1 !== typeof value2) {
      return false;
    }

    if (typeof value1 === 'object') {
      return JSON.stringify(value1) === JSON.stringify(value2);
    }

    return false;
  }

  private canAutoMerge(field: string, serverValue: any, clientValue: any): boolean {
    if (typeof serverValue === 'number' && typeof clientValue === 'number') {
      return false;
    }

    if (typeof serverValue === 'string' && typeof clientValue === 'string') {
      if (serverValue.includes(clientValue) || clientValue.includes(serverValue)) {
        return true;
      }
    }

    if (Array.isArray(serverValue) && Array.isArray(clientValue)) {
      return true;
    }

    return false;
  }

  private mergeValues(field: string, serverValue: any, clientValue: any): any {
    if (Array.isArray(serverValue) && Array.isArray(clientValue)) {
      const merged = [...serverValue];
      for (const item of clientValue) {
        if (!merged.some(m => JSON.stringify(m) === JSON.stringify(item))) {
          merged.push(item);
        }
      }
      return merged;
    }

    if (typeof serverValue === 'string' && typeof clientValue === 'string') {
      if (clientValue.length > serverValue.length) {
        return clientValue;
      }
      return serverValue;
    }

    return serverValue;
  }

  private async fetchServerData(action: QueuedAction): Promise<any> {
    let url: string;

    switch (action.type) {
      case QueuedActionType.UPDATE_DOSSIER_STATUS:
        url = `/api/v1/dossiers/${action.payload.id}`;
        break;

      case QueuedActionType.UPDATE_APPOINTMENT:
        url = `/api/v1/appointments/${action.payload.id}`;
        break;

      case QueuedActionType.CREATE_MESSAGE:
      case QueuedActionType.CREATE_APPOINTMENT:
      case QueuedActionType.CREATE_NOTE:
        return null;

      default:
        return null;
    }

    try {
      return await firstValueFrom(this.http.get(url));
    } catch (error) {
      console.error('Failed to fetch server data for conflict detection:', error);
      return null;
    }
  }

  async resolveBatch(
    conflicts: ConflictInfo[],
    strategy: ConflictResolutionStrategy
  ): Promise<MergeResult[]> {
    const results: MergeResult[] = [];

    for (const conflict of conflicts) {
      const result = await this.resolveConflict(conflict, strategy);
      results.push(result);
    }

    return results;
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, fromEvent, merge, of } from 'rxjs';
import { map, startWith, debounceTime } from 'rxjs/operators';
import { MessageApiService, MessageCreateRequest, MessageResponse } from './message-api.service';

export interface QueuedMessage {
  id: string;
  request: MessageCreateRequest;
  timestamp: number;
  retries: number;
}

const STORAGE_KEY = 'whatsapp_message_queue';
const MAX_RETRIES = 3;

@Injectable({
  providedIn: 'root'
})
export class OfflineMessageQueueService {
  private queueSubject = new BehaviorSubject<QueuedMessage[]>([]);
  private isOnlineSubject = new BehaviorSubject<boolean>(navigator.onLine);
  private isSyncingSubject = new BehaviorSubject<boolean>(false);

  queue$ = this.queueSubject.asObservable();
  isOnline$ = this.isOnlineSubject.asObservable();
  isSyncing$ = this.isSyncingSubject.asObservable();

  queueCount$ = this.queue$.pipe(
    map(queue => queue.length)
  );

  constructor(private messageApiService: MessageApiService) {
    this.loadQueue();
    this.setupOnlineListener();
  }

  private setupOnlineListener(): void {
    const online$ = fromEvent(window, 'online').pipe(map(() => true));
    const offline$ = fromEvent(window, 'offline').pipe(map(() => false));

    merge(online$, offline$)
      .pipe(
        startWith(navigator.onLine),
        debounceTime(500)
      )
      .subscribe(isOnline => {
        this.isOnlineSubject.next(isOnline);
        if (isOnline) {
          this.syncQueue();
        }
      });
  }

  private loadQueue(): void {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const queue = JSON.parse(stored) as QueuedMessage[];
        this.queueSubject.next(queue);
      }
    } catch (error) {
      console.error('Error loading message queue:', error);
      this.queueSubject.next([]);
    }
  }

  private saveQueue(): void {
    try {
      const queue = this.queueSubject.value;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(queue));
    } catch (error) {
      console.error('Error saving message queue:', error);
    }
  }

  enqueue(request: MessageCreateRequest): Observable<MessageResponse | null> {
    if (this.isOnlineSubject.value) {
      return this.messageApiService.create(request);
    }

    const queuedMessage: QueuedMessage = {
      id: this.generateId(),
      request,
      timestamp: Date.now(),
      retries: 0
    };

    const currentQueue = this.queueSubject.value;
    this.queueSubject.next([...currentQueue, queuedMessage]);
    this.saveQueue();

    return of(null);
  }

  async syncQueue(): Promise<void> {
    if (this.isSyncingSubject.value || !this.isOnlineSubject.value) {
      return;
    }

    const queue = this.queueSubject.value;
    if (queue.length === 0) {
      return;
    }

    this.isSyncingSubject.next(true);

    const remainingMessages: QueuedMessage[] = [];

    for (const queuedMessage of queue) {
      try {
        await this.sendQueuedMessage(queuedMessage);
      } catch (error) {
        console.error('Error sending queued message:', error);
        
        if (queuedMessage.retries < MAX_RETRIES) {
          remainingMessages.push({
            ...queuedMessage,
            retries: queuedMessage.retries + 1
          });
        }
      }
    }

    this.queueSubject.next(remainingMessages);
    this.saveQueue();
    this.isSyncingSubject.next(false);
  }

  private sendQueuedMessage(queuedMessage: QueuedMessage): Promise<MessageResponse> {
    return new Promise((resolve, reject) => {
      this.messageApiService.create(queuedMessage.request).subscribe({
        next: (response) => resolve(response),
        error: (error) => reject(error)
      });
    });
  }

  clearQueue(): void {
    this.queueSubject.next([]);
    this.saveQueue();
  }

  removeFromQueue(messageId: string): void {
    const currentQueue = this.queueSubject.value;
    const updatedQueue = currentQueue.filter(m => m.id !== messageId);
    this.queueSubject.next(updatedQueue);
    this.saveQueue();
  }

  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  getQueueSize(): number {
    return this.queueSubject.value.length;
  }

  isOnline(): boolean {
    return this.isOnlineSubject.value;
  }

  isSyncing(): boolean {
    return this.isSyncingSubject.value;
  }
}

