import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, fromEvent, merge } from 'rxjs';
import { map, debounceTime } from 'rxjs/operators';

export enum ConnectionStatus {
  ONLINE = 'ONLINE',
  OFFLINE = 'OFFLINE',
  SLOW = 'SLOW'
}

export interface ConnectivityState {
  status: ConnectionStatus;
  lastOnline: Date | null;
  effectiveType?: string;
  downlink?: number;
  rtt?: number;
}

@Injectable({
  providedIn: 'root'
})
export class OfflineService {
  private connectivitySubject = new BehaviorSubject<ConnectivityState>({
    status: ConnectionStatus.ONLINE,
    lastOnline: new Date()
  });

  public connectivity$: Observable<ConnectivityState> = this.connectivitySubject.asObservable();

  constructor() {
    this.initializeConnectivityMonitoring();
  }

  private initializeConnectivityMonitoring(): void {
    const online$ = fromEvent(window, 'online').pipe(map(() => true));
    const offline$ = fromEvent(window, 'offline').pipe(map(() => false));

    merge(online$, offline$)
      .pipe(debounceTime(100))
      .subscribe(isOnline => {
        this.updateConnectivityStatus(isOnline);
      });

    this.updateConnectivityStatus(navigator.onLine);

    if ('connection' in navigator) {
      const connection = (navigator as any).connection || (navigator as any).mozConnection || (navigator as any).webkitConnection;
      if (connection) {
        connection.addEventListener('change', () => {
          this.checkConnectionQuality();
        });
      }
    }
  }

  private updateConnectivityStatus(isOnline: boolean): void {
    const currentState = this.connectivitySubject.value;
    
    if (isOnline) {
      this.checkConnectionQuality();
    } else {
      this.connectivitySubject.next({
        status: ConnectionStatus.OFFLINE,
        lastOnline: currentState.status !== ConnectionStatus.OFFLINE ? new Date() : currentState.lastOnline
      });
    }
  }

  private checkConnectionQuality(): void {
    const connection = (navigator as any).connection || (navigator as any).mozConnection || (navigator as any).webkitConnection;
    
    if (connection) {
      const effectiveType = connection.effectiveType;
      const downlink = connection.downlink;
      const rtt = connection.rtt;

      let status = ConnectionStatus.ONLINE;
      
      if (effectiveType === 'slow-2g' || effectiveType === '2g' || rtt > 2000) {
        status = ConnectionStatus.SLOW;
      }

      this.connectivitySubject.next({
        status,
        lastOnline: new Date(),
        effectiveType,
        downlink,
        rtt
      });
    } else {
      this.connectivitySubject.next({
        status: ConnectionStatus.ONLINE,
        lastOnline: new Date()
      });
    }
  }

  isOnline(): boolean {
    return this.connectivitySubject.value.status !== ConnectionStatus.OFFLINE;
  }

  isSlow(): boolean {
    return this.connectivitySubject.value.status === ConnectionStatus.SLOW;
  }

  getStatus(): ConnectionStatus {
    return this.connectivitySubject.value.status;
  }

  getLastOnlineTime(): Date | null {
    return this.connectivitySubject.value.lastOnline;
  }

  async checkConnectivity(): Promise<boolean> {
    if (!navigator.onLine) {
      return false;
    }

    try {
      const response = await fetch('/api/v1/ping', {
        method: 'HEAD',
        cache: 'no-cache'
      });
      return response.ok;
    } catch {
      return false;
    }
  }
}

import { Injectable } from '@angular/core';
import { QueuedAction, QueuedActionStatus } from './offline-queue.service';

export interface CachedData {
  key: string;
  data: any;
  timestamp: number;
  expiresAt?: number;
}

export interface LocalIdMapping {
  localId: string;
  serverId: number;
  entityType: string;
  timestamp: number;
}

@Injectable({
  providedIn: 'root'
})
export class OfflineStorageService {
  private readonly DB_NAME = 'offline-db';
  private readonly DB_VERSION = 1;
  private readonly QUEUE_STORE = 'queue';
  private readonly CACHE_STORE = 'cache';
  private readonly MAPPING_STORE = 'id-mapping';

  private db: IDBDatabase | null = null;

  constructor() {
    this.initializeDatabase();
  }

  private async initializeDatabase(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.DB_NAME, this.DB_VERSION);

      request.onerror = () => {
        console.error('Failed to open IndexedDB:', request.error);
        reject(request.error);
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event: IDBVersionChangeEvent) => {
        const db = (event.target as IDBOpenDBRequest).result;

        if (!db.objectStoreNames.contains(this.QUEUE_STORE)) {
          const queueStore = db.createObjectStore(this.QUEUE_STORE, { keyPath: 'id' });
          queueStore.createIndex('status', 'status', { unique: false });
          queueStore.createIndex('timestamp', 'timestamp', { unique: false });
        }

        if (!db.objectStoreNames.contains(this.CACHE_STORE)) {
          const cacheStore = db.createObjectStore(this.CACHE_STORE, { keyPath: 'key' });
          cacheStore.createIndex('timestamp', 'timestamp', { unique: false });
          cacheStore.createIndex('expiresAt', 'expiresAt', { unique: false });
        }

        if (!db.objectStoreNames.contains(this.MAPPING_STORE)) {
          const mappingStore = db.createObjectStore(this.MAPPING_STORE, { keyPath: 'localId' });
          mappingStore.createIndex('serverId', 'serverId', { unique: false });
          mappingStore.createIndex('entityType', 'entityType', { unique: false });
        }
      };
    });
  }

  private async ensureDatabase(): Promise<IDBDatabase> {
    if (this.db) {
      return this.db;
    }

    await this.initializeDatabase();
    if (!this.db) {
      throw new Error('Failed to initialize database');
    }
    return this.db;
  }

  async addQueuedAction(action: QueuedAction): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readwrite');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.add(action);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async updateQueuedAction(action: QueuedAction): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readwrite');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.put(action);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getQueuedAction(id: string): Promise<QueuedAction | null> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readonly');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.get(id);

      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error);
    });
  }

  async getPendingActions(): Promise<QueuedAction[]> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readonly');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const index = store.index('status');
      const request = index.getAll(QueuedActionStatus.PENDING);

      request.onsuccess = () => {
        const actions = request.result || [];
        actions.sort((a, b) => a.timestamp - b.timestamp);
        resolve(actions);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async getFailedActions(): Promise<QueuedAction[]> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readonly');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const index = store.index('status');
      const request = index.getAll(QueuedActionStatus.FAILED);

      request.onsuccess = () => resolve(request.result || []);
      request.onerror = () => reject(request.error);
    });
  }

  async deleteQueuedAction(id: string): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readwrite');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async clearQueue(): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.QUEUE_STORE], 'readwrite');
      const store = transaction.objectStore(this.QUEUE_STORE);
      const request = store.clear();

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async cacheData(key: string, data: any, ttlMinutes?: number): Promise<void> {
    const db = await this.ensureDatabase();
    const cachedData: CachedData = {
      key,
      data,
      timestamp: Date.now(),
      expiresAt: ttlMinutes ? Date.now() + (ttlMinutes * 60 * 1000) : undefined
    };

    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.CACHE_STORE], 'readwrite');
      const store = transaction.objectStore(this.CACHE_STORE);
      const request = store.put(cachedData);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getCachedData(key: string): Promise<any | null> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.CACHE_STORE], 'readonly');
      const store = transaction.objectStore(this.CACHE_STORE);
      const request = store.get(key);

      request.onsuccess = () => {
        const result: CachedData | undefined = request.result;
        if (!result) {
          resolve(null);
          return;
        }

        if (result.expiresAt && result.expiresAt < Date.now()) {
          this.deleteCachedData(key);
          resolve(null);
          return;
        }

        resolve(result.data);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async deleteCachedData(key: string): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.CACHE_STORE], 'readwrite');
      const store = transaction.objectStore(this.CACHE_STORE);
      const request = store.delete(key);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async clearExpiredCache(): Promise<void> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.CACHE_STORE], 'readwrite');
      const store = transaction.objectStore(this.CACHE_STORE);
      const index = store.index('expiresAt');
      const now = Date.now();
      const range = IDBKeyRange.upperBound(now);
      const request = index.openCursor(range);

      request.onsuccess = (event) => {
        const cursor = (event.target as IDBRequest).result;
        if (cursor) {
          cursor.delete();
          cursor.continue();
        } else {
          resolve();
        }
      };

      request.onerror = () => reject(request.error);
    });
  }

  async mapLocalToServerId(localId: string, serverId: number, entityType = 'default'): Promise<void> {
    const db = await this.ensureDatabase();
    const mapping: LocalIdMapping = {
      localId,
      serverId,
      entityType,
      timestamp: Date.now()
    };

    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.MAPPING_STORE], 'readwrite');
      const store = transaction.objectStore(this.MAPPING_STORE);
      const request = store.put(mapping);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getServerId(localId: string): Promise<number | null> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.MAPPING_STORE], 'readonly');
      const store = transaction.objectStore(this.MAPPING_STORE);
      const request = store.get(localId);

      request.onsuccess = () => {
        const result: LocalIdMapping | undefined = request.result;
        resolve(result?.serverId || null);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async getLocalId(serverId: number): Promise<string | null> {
    const db = await this.ensureDatabase();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([this.MAPPING_STORE], 'readonly');
      const store = transaction.objectStore(this.MAPPING_STORE);
      const index = store.index('serverId');
      const request = index.get(serverId);

      request.onsuccess = () => {
        const result: LocalIdMapping | undefined = request.result;
        resolve(result?.localId || null);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async getCachedDossiers(): Promise<any[]> {
    const data = await this.getCachedData('recent-dossiers');
    return data ? JSON.parse(data) : [];
  }

  async cacheDossier(dossier: any): Promise<void> {
    const cached = await this.getCachedDossiers();
    const filtered = cached.filter((d: any) => d.id !== dossier.id);
    filtered.unshift(dossier);
    const limited = filtered.slice(0, 50);
    await this.cacheData('recent-dossiers', JSON.stringify(limited), 60 * 60 * 1000);
  }

  async clearDossierCache(): Promise<void> {
    await this.deleteCachedData('recent-dossiers');
  }

  async clearMessageCache(): Promise<void> {
    await this.deleteCachedData('recent-messages');
  }
}

import { Injectable } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { filter, catchError } from 'rxjs/operators';
import { of } from 'rxjs';
import { TourDefinitionService } from './tour-definition.service';
import { AuthService } from './auth.service';

// Type definitions for Shepherd.js (lazy-loaded)
type ShepherdTour = any;

export interface TourProgress {
  [tourId: string]: {
    completed: boolean;
    completedAt?: string;
    currentStep?: number;
    skipped?: boolean;
    abandonedAt?: string;
    stepAbandonment?: { [stepIndex: number]: number };
  };
}

export interface TourAnalytics {
  tourId: string;
  action: 'started' | 'completed' | 'skipped' | 'abandoned' | 'step_completed' | 'step_abandoned';
  step?: number;
  stepName?: string;
  timestamp: string;
  duration?: number;
  userId?: string;
}

@Injectable({
  providedIn: 'root'
})
export class OnboardingTourService {
  private readonly STORAGE_KEY = 'onboarding_tour_progress';
  private readonly ANALYTICS_KEY = 'onboarding_tour_analytics';
  private readonly API_BASE = '/api/v1/user-preferences';
  
  private currentTour: ShepherdTour | null = null;
  private tourProgress: TourProgress = {};
  private tourStartTime: number | null = null;
  private syncInProgress = false;
  private shepherdLoaded = false;
  private shepherdModule: any = null;

  constructor(
    private router: Router,
    private http: HttpClient,
    private tourDefinitionService: TourDefinitionService,
    private authService: AuthService
  ) {
    this.loadProgress();
    this.setupRouteListener();
    this.syncWithBackend();
  }

  private loadProgress(): void {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        this.tourProgress = JSON.parse(stored);
      }
    } catch (error) {
      console.error('Failed to load tour progress:', error);
      this.tourProgress = {};
    }
  }

  private saveProgress(): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.tourProgress));
      this.syncWithBackend();
    } catch (error) {
      console.error('Failed to save tour progress:', error);
    }
  }

  private syncWithBackend(): void {
    if (this.syncInProgress) {
      return;
    }

    const userId = this.getUserId();
    if (!userId) {
      return;
    }

    this.syncInProgress = true;
    this.http.put(`${this.API_BASE}/${userId}/tour-progress`, this.tourProgress)
      .pipe(
        catchError(error => {
          console.warn('Failed to sync tour progress with backend:', error);
          return of(null);
        })
      )
      .subscribe(() => {
        this.syncInProgress = false;
      });
  }

  private loadProgressFromBackend(): void {
    const userId = this.getUserId();
    if (!userId) {
      return;
    }

    this.http.get<TourProgress>(`${this.API_BASE}/${userId}/tour-progress`)
      .pipe(
        catchError(error => {
          console.warn('Failed to load tour progress from backend:', error);
          return of({});
        })
      )
      .subscribe(progress => {
        if (progress && Object.keys(progress).length > 0) {
          this.tourProgress = progress;
          this.saveProgressLocally();
        }
      });
  }

  private saveProgressLocally(): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.tourProgress));
    } catch (error) {
      console.error('Failed to save tour progress locally:', error);
    }
  }

  private getUserId(): string | null {
    // Get user ID from auth service or use a default for demo
    try {
      return (this.authService as { getCurrentUserId?: () => string }).getCurrentUserId?.() || 'demo-user';
    } catch {
      return 'demo-user';
    }
  }

  private trackAnalytics(analytics: TourAnalytics): void {
    try {
      // Add user ID to analytics
      analytics.userId = this.getUserId() || undefined;
      
      // Store locally
      const stored = localStorage.getItem(this.ANALYTICS_KEY);
      const events: TourAnalytics[] = stored ? JSON.parse(stored) : [];
      events.push(analytics);
      
      if (events.length > 100) {
        events.splice(0, events.length - 100);
      }
      
      localStorage.setItem(this.ANALYTICS_KEY, JSON.stringify(events));
      
      // Log to console for debugging
      console.log('[Tour Analytics]', analytics);
      
      // Send to analytics endpoint (could integrate with GA4, Mixpanel, etc.)
      this.sendAnalyticsToBackend(analytics);
    } catch (error) {
      console.error('Failed to track analytics:', error);
    }
  }

  private sendAnalyticsToBackend(analytics: TourAnalytics): void {
    // Optional: Send analytics to backend for aggregation
    // This could be implemented as a separate endpoint
    // For now, we just log it
    if (window.gtag) {
      // Google Analytics 4 integration
      window.gtag('event', analytics.action, {
        event_category: 'Tour',
        event_label: analytics.tourId,
        tour_step: analytics.stepName || analytics.step,
        tour_duration: analytics.duration,
        user_id: analytics.userId
      });
    }
  }

  getAbandonmentRate(tourId: string): number {
    const progress = this.tourProgress[tourId];
    if (!progress || !progress.stepAbandonment) {
      return 0;
    }

    const tour = this.tourDefinitionService.getTour(tourId);
    if (!tour) {
      return 0;
    }

    const totalSteps = tour.steps.length;
    const abandonments = Object.values(progress.stepAbandonment).reduce((sum, count) => sum + count, 0);
    const starts = this.getAnalytics().filter(a => a.tourId === tourId && a.action === 'started').length;

    return starts > 0 ? (abandonments / (starts * totalSteps)) * 100 : 0;
  }

  getStepAbandonmentRates(tourId: string): { [stepIndex: number]: number } {
    const analytics = this.getAnalytics().filter(a => a.tourId === tourId);
    const starts = analytics.filter(a => a.action === 'started').length;
    
    if (starts === 0) {
      return {};
    }

    const abandonmentCounts: { [stepIndex: number]: number } = {};
    const tour = this.tourDefinitionService.getTour(tourId);
    
    if (!tour) {
      return {};
    }

    tour.steps.forEach((_, index) => {
      const stepAbandoned = analytics.filter(
        a => a.action === 'step_abandoned' && a.step === index
      ).length;
      abandonmentCounts[index] = (stepAbandoned / starts) * 100;
    });

    return abandonmentCounts;
  }

  private setupRouteListener(): void {
    this.router.events
      .pipe(filter((event): event is NavigationEnd => event instanceof NavigationEnd))
      .subscribe((event) => {
        this.checkAutoStartTour(event.url);
      });
  }

  private checkAutoStartTour(url: string): void {
    if (url === '/dossiers/create' && !this.isTourCompleted('dossier-creation')) {
      setTimeout(() => this.startDossierCreationTour(), 500);
    } else if (url.match(/\/dossiers\/\d+/) && !this.isTourCompleted('dossier-detail')) {
      setTimeout(() => this.startDossierDetailTour(), 500);
    }
  }

  isTourCompleted(tourId: string): boolean {
    return this.tourProgress[tourId]?.completed || false;
  }

  resetTour(tourId: string): void {
    if (this.tourProgress[tourId]) {
      delete this.tourProgress[tourId];
      this.saveProgress();
    }
  }

  resetAllTours(): void {
    this.tourProgress = {};
    this.saveProgress();
    localStorage.removeItem(this.ANALYTICS_KEY);
  }

  getAnalytics(): TourAnalytics[] {
    try {
      const stored = localStorage.getItem(this.ANALYTICS_KEY);
      return stored ? JSON.parse(stored) : [];
    } catch (error) {
      console.error('Failed to get analytics:', error);
      return [];
    }
  }

  private async loadShepherd(): Promise<any> {
    if (this.shepherdLoaded && this.shepherdModule) {
      return this.shepherdModule;
    }

    try {
      const { default: Shepherd } = await import('shepherd.js');
      this.shepherdModule = Shepherd;
      this.shepherdLoaded = true;
      return Shepherd;
    } catch (error) {
      console.error('Failed to load Shepherd.js:', error);
      throw error;
    }
  }

  private async createTour(tourId: string, options?: any): Promise<ShepherdTour> {
    if (this.currentTour) {
      this.currentTour.complete();
    }

    const Shepherd = await this.loadShepherd();

    const defaultOptions: any = {
      useModalOverlay: true,
      defaultStepOptions: {
        classes: 'shepherd-theme-custom',
        scrollTo: { behavior: 'smooth', block: 'center' },
        cancelIcon: {
          enabled: true
        }
      },
      ...options
    };

    this.currentTour = new Shepherd.Tour(defaultOptions);

    this.currentTour.on('complete', () => {
      const duration = this.tourStartTime ? Date.now() - this.tourStartTime : undefined;
      this.tourProgress[tourId] = {
        completed: true,
        completedAt: new Date().toISOString()
      };
      this.saveProgress();
      this.trackAnalytics({
        tourId,
        action: 'completed',
        timestamp: new Date().toISOString(),
        duration
      });
      this.tourStartTime = null;
    });

    this.currentTour.on('cancel', () => {
      const currentStep = this.currentTour?.getCurrentStep();
      const stepIndex = currentStep ? this.currentTour?.steps.indexOf(currentStep) : -1;
      
      if (!this.tourProgress[tourId]?.completed) {
        if (!this.tourProgress[tourId]) {
          this.tourProgress[tourId] = {
            completed: false,
            skipped: false
          };
        }
        
        // Track abandonment at specific step
        if (stepIndex !== undefined && stepIndex >= 0) {
          if (!this.tourProgress[tourId].stepAbandonment) {
            this.tourProgress[tourId].stepAbandonment = {};
          }
          const currentCount = this.tourProgress[tourId].stepAbandonment![stepIndex] || 0;
          this.tourProgress[tourId].stepAbandonment![stepIndex] = currentCount + 1;
          
          this.trackAnalytics({
            tourId,
            action: 'step_abandoned',
            step: stepIndex,
            stepName: currentStep?.id,
            timestamp: new Date().toISOString()
          });
        } else {
          this.tourProgress[tourId].skipped = true;
          this.trackAnalytics({
            tourId,
            action: 'skipped',
            timestamp: new Date().toISOString()
          });
        }
        
        this.tourProgress[tourId].abandonedAt = new Date().toISOString();
        this.saveProgress();
      }
      this.tourStartTime = null;
    });

    this.currentTour.on('start', () => {
      this.tourStartTime = Date.now();
      this.trackAnalytics({
        tourId,
        action: 'started',
        timestamp: new Date().toISOString()
      });
    });

    return this.currentTour;
  }

  async startDossierCreationTour(): Promise<void> {
    const tourId = 'dossier-creation';
    
    if (this.isTourCompleted(tourId)) {
      return;
    }

    const tour = await this.createTour(tourId);

    tour.addStep({
      id: 'welcome',
      title: '👋 Bienvenue dans la création de dossier',
      text: `
        <p>Ce guide vous accompagnera dans la création de votre premier dossier.</p>
        <p>Un dossier représente un lead ou prospect immobilier.</p>
      `,
      buttons: [
        {
          text: 'Passer',
          action: tour.cancel,
          secondary: true
        },
        {
          text: 'Suivant',
          action: tour.next
        }
      ]
    });

    tour.addStep({
      id: 'lead-name',
      title: '📝 Nom du prospect',
      text: `
        <p>Commencez par renseigner le nom du prospect.</p>
        <p>Ce champ est optionnel mais recommandé pour une meilleure organisation.</p>
      `,
      attachTo: {
        element: '[formControlName="leadName"]',
        on: 'bottom'
      },
      buttons: [
        {
          text: 'Précédent',
          action: tour.back,
          secondary: true
        },
        {
          text: 'Suivant',
          action: tour.next
        }
      ],
      when: {
        show: () => {
          this.trackAnalytics({
            tourId,
            action: 'step_completed',
            step: 1,
            timestamp: new Date().toISOString()
          });
        }
      }
    });

    tour.addStep({
      id: 'lead-phone',
      title: '📱 Téléphone du prospect',
      text: `
        <p>Le numéro de téléphone permet de contacter le prospect.</p>
        <p><strong>Astuce :</strong> Le système détecte automatiquement les doublons pour éviter de créer plusieurs dossiers pour le même prospect.</p>
      `,
      attachTo: {
        element: '[formControlName="leadPhone"]',
        on: 'bottom'
      },
      buttons: [
