import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { BehaviorSubject, Observable, map } from 'rxjs';

export interface Listing {
  id: string;
  slug: string;
  title: string;
  tx: 'vente' | 'location';
  price: number;
  city: string;
  zone: string;
  surface: number;
  pieces: number;
  desc: string;
  agent: { name: string; agency: string; initials: string };
  verified: boolean;
  date: string;
  imgs: string[];
}

export interface City {
  name: string;
  count: number;
  icon: string;
}

export interface FilterState {
  tx: string;
  ville: string;
  prixMin: number | null;
  prixMax: number | null;
  surfMin: number | null;
  surfMax: number | null;
  pieces: number;
  sort: 'recent' | 'prix-asc' | 'prix-desc' | 'surface-desc';
  page: number;
}

@Injectable({ providedIn: 'root' })
export class PortailService {
  readonly PAGE_SIZE = 9;

  readonly CITIES: City[] = [
    { name: 'Casablanca', count: 342, icon: '🏙️' },
    { name: 'Rabat',      count: 187, icon: '🏛️' },
    { name: 'Tanger',     count: 156, icon: '🌊' },
    { name: 'Marrakech',  count: 203, icon: '🌴' },
    { name: 'Fès',        count: 98,  icon: '🕌' },
    { name: 'Agadir',     count: 112, icon: '☀️' },
    { name: 'Meknès',     count: 67,  icon: '🏰' },
    { name: 'Tétouan',    count: 54,  icon: '🏔️' },
  ];

  private filterState$ = new BehaviorSubject<FilterState>({
    tx: '', ville: '', prixMin: null, prixMax: null,
    surfMin: null, surfMax: null, pieces: 0, sort: 'recent', page: 1
  });

  constructor(private http: HttpClient) {}

  getFilters() { return this.filterState$.asObservable(); }
  getFiltersSnapshot() { return this.filterState$.value; }

  updateFilters(partial: Partial<FilterState>): void {
    this.filterState$.next({ ...this.filterState$.value, ...partial, page: 1 });
  }

  setPage(page: number): void {
    this.filterState$.next({ ...this.filterState$.value, page });
  }

  // Maps Backend AnnonceResponse to Frontend Listing interface
  private mapToListing(annonce: any): Listing {
    return {
      id: annonce.id.toString(),
      slug: annonce.meta?.slug || `annonce-${annonce.id}`,
      title: annonce.title,
      tx: annonce.type === 'SALE' ? 'vente' : 'location',
      price: annonce.price || 0,
      city: annonce.city || '',
      zone: annonce.address || '',
      surface: annonce.surface || 0,
      pieces: annonce.meta?.pieces || 0,
      desc: annonce.description || '',
      agent: annonce.meta?.agent || { name: 'Agent', agency: 'Agence', initials: 'AG' },
      verified: annonce.meta?.verified || false,
      date: annonce.createdAt || new Date().toISOString(),
      imgs: annonce.photos && annonce.photos.length > 0 
        ? annonce.photos 
        : ['https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=800&q=80']
    };
  }

  searchAnnonces(state: FilterState): Observable<{ content: Listing[], totalElements: number }> {
    let params = new HttpParams()
      .set('page', (state.page - 1).toString())
      .set('size', this.PAGE_SIZE.toString());

    if (state.tx) {
      params = params.set('type', state.tx === 'vente' ? 'SALE' : 'RENT');
    }
    if (state.ville) {
      params = params.set('city', state.ville);
    }
    
    // Sort mapping
    let sortStr = 'id,desc';
    if (state.sort === 'prix-asc') sortStr = 'price,asc';
    if (state.sort === 'prix-desc') sortStr = 'price,desc';
    if (state.sort === 'surface-desc') sortStr = 'surface,desc';
    params = params.set('sort', sortStr);

    return this.http.get<any>('/api/v1/portal/annonces', { params }).pipe(
      map((res: any) => {
        const content = res.content ? res.content.map((item: any) => this.mapToListing(item)) : [];
        // Optional client-side filtering if API misses some filters (like pieces or surface)
        // Since the current controller search endpoint in MVP is limited, we might filter further here
        let filtered = content;
        if (state.prixMin) filtered = filtered.filter((l: Listing) => l.price >= state.prixMin!);
        if (state.prixMax) filtered = filtered.filter((l: Listing) => l.price <= state.prixMax!);
        if (state.surfMin) filtered = filtered.filter((l: Listing) => l.surface >= state.surfMin!);
        if (state.surfMax) filtered = filtered.filter((l: Listing) => l.surface <= state.surfMax!);
        if (state.pieces)  filtered = filtered.filter((l: Listing) => state.pieces >= 4 ? l.pieces >= 4 : l.pieces === state.pieces);

        return { content: filtered, totalElements: res.totalElements || filtered.length };
      })
    );
  }

  getListingById(id: string): Observable<Listing> {
    // Technically should call /api/v1/annonces/{id} but since Portal is public, 
    // it's easier to just search and find it. Or add a getById endpoint to PortalPublicController.
    // For now, doing a basic authenticated fetch bypass or we just add it later.
    return this.http.get<any>(`/api/v1/annonces/${id}`).pipe(
      map(res => this.mapToListing(res))
    );
  }

  formatPrice(price: number, tx: 'vente' | 'location'): string {
    if (tx === 'location') return price.toLocaleString('fr-MA') + ' MAD/mois';
    if (price >= 1000000)  return (price / 1000000).toFixed(price % 1000000 === 0 ? 0 : 2) + ' M MAD';
    return price.toLocaleString('fr-MA') + ' MAD';
  }
}

import { Injectable } from '@angular/core';

export interface LinearRegressionResult {
  slope: number;
  intercept: number;
  rSquared: number;
  predictions: number[];
}

export interface PipelineForecast {
  date: string;
  predictedValue: number;
  confidence: number;
  upperBound: number;
  lowerBound: number;
}

export interface CloseProbability {
  dossierId: number;
  probability: number;
  factors: {
    responseTime: number;
    stageProgression: number;
    engagement: number;
    source: number;
  };
  recommendation: string;
}

@Injectable({
  providedIn: 'root'
})
export class PredictiveAnalyticsService {

  constructor() { /* no-op */ }

  performLinearRegression(xValues: number[], yValues: number[]): LinearRegressionResult {
    if (xValues.length !== yValues.length || xValues.length === 0) {
      throw new Error('Invalid input data for regression');
    }

    const n = xValues.length;
    const sumX = xValues.reduce((a, b) => a + b, 0);
    const sumY = yValues.reduce((a, b) => a + b, 0);
    const sumXY = xValues.reduce((sum, x, i) => sum + x * yValues[i], 0);
    const sumXX = xValues.reduce((sum, x) => sum + x * x, 0);

    const slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
    const intercept = (sumY - slope * sumX) / n;

    const predictions = xValues.map(x => slope * x + intercept);
    const meanY = sumY / n;
    const ssTotal = yValues.reduce((sum, y) => sum + Math.pow(y - meanY, 2), 0);
    const ssResidual = yValues.reduce((sum, y, i) => sum + Math.pow(y - predictions[i], 2), 0);
    const rSquared = 1 - (ssResidual / ssTotal);

    return { slope, intercept, rSquared, predictions };
  }

  forecastPipelineValue(historicalData: { date: string; value: number }[], daysAhead: number): PipelineForecast[] {
    if (historicalData.length < 2) {
      return [];
    }

    const xValues = historicalData.map((_, i) => i);
    const yValues = historicalData.map(d => d.value);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const stdDev = this.calculateStdDev(yValues, regression.predictions.slice(0, yValues.length));
    
    const forecasts: PipelineForecast[] = [];
    const lastDate = new Date(historicalData[historicalData.length - 1].date);

    for (let i = 1; i <= daysAhead; i++) {
      const xValue = historicalData.length + i - 1;
      const predictedValue = regression.slope * xValue + regression.intercept;
      
      const confidence = Math.max(0, Math.min(100, regression.rSquared * 100));
      
      const forecastDate = new Date(lastDate);
      forecastDate.setDate(lastDate.getDate() + i);

      const uncertaintyFactor = Math.sqrt(i);
      forecasts.push({
        date: forecastDate.toISOString().split('T')[0],
        predictedValue: Math.max(0, predictedValue),
        confidence,
        upperBound: Math.max(0, predictedValue + stdDev * uncertaintyFactor),
        lowerBound: Math.max(0, predictedValue - stdDev * uncertaintyFactor)
      });
    }

    return forecasts;
  }

  calculateCloseProbability(dossier: {
    id: number;
    averageResponseTimeHours: number;
    daysInCurrentStage: number;
    messageCount: number;
    appointmentCount: number;
    source: string;
    status: string;
  }): CloseProbability {
    let probability = 50;

    const responseTimeFactor = this.scoreResponseTime(dossier.averageResponseTimeHours);
    const stageProgressionFactor = this.scoreStageProgression(dossier.status, dossier.daysInCurrentStage);
    const engagementFactor = this.scoreEngagement(dossier.messageCount, dossier.appointmentCount);
    const sourceFactor = this.scoreSource(dossier.source);

    probability += responseTimeFactor * 0.25;
    probability += stageProgressionFactor * 0.30;
    probability += engagementFactor * 0.30;
    probability += sourceFactor * 0.15;

    probability = Math.max(0, Math.min(100, probability));

    const recommendation = this.generateRecommendation(probability, {
      responseTimeFactor,
      stageProgressionFactor,
      engagementFactor,
      sourceFactor
    });

    return {
      dossierId: dossier.id,
      probability,
      factors: {
        responseTime: responseTimeFactor,
        stageProgression: stageProgressionFactor,
        engagement: engagementFactor,
        source: sourceFactor
      },
      recommendation
    };
  }

  private calculateStdDev(actual: number[], predicted: number[]): number {
    const residuals = actual.map((y, i) => y - predicted[i]);
    const sumSquaredResiduals = residuals.reduce((sum, r) => sum + r * r, 0);
    return Math.sqrt(sumSquaredResiduals / actual.length);
  }

  private scoreResponseTime(avgResponseTimeHours: number): number {
    if (avgResponseTimeHours <= 1) return 20;
    if (avgResponseTimeHours <= 4) return 10;
    if (avgResponseTimeHours <= 24) return 0;
    if (avgResponseTimeHours <= 48) return -10;
    return -20;
  }

  private scoreStageProgression(status: string, daysInStage: number): number {
    const stageWeights: Record<string, number> = {
      'NEW': 0,
      'QUALIFYING': 10,
      'QUALIFIED': 20,
      'APPOINTMENT': 30,
      'PROPOSAL': 35,
      'NEGOTIATION': 40,
      'WON': 50,
      'LOST': -50
    };

    let score = stageWeights[status] || 0;

    if (daysInStage > 30) {
      score -= 15;
    } else if (daysInStage > 14) {
      score -= 10;
    } else if (daysInStage > 7) {
      score -= 5;
    }

    return score;
  }

  private scoreEngagement(messageCount: number, appointmentCount: number): number {
    let score = 0;

    if (messageCount > 10) {
      score += 20;
    } else if (messageCount > 5) {
      score += 15;
    } else if (messageCount > 2) {
      score += 10;
    } else if (messageCount > 0) {
      score += 5;
    }

    if (appointmentCount > 2) {
      score += 15;
    } else if (appointmentCount > 1) {
      score += 10;
    } else if (appointmentCount > 0) {
      score += 5;
    }

    return score;
  }

  private scoreSource(source: string): number {
    const sourceWeights: Record<string, number> = {
      'REFERRAL': 15,
      'WEBSITE': 10,
      'SOCIAL_MEDIA': 5,
      'PHONE': 5,
      'EMAIL': 3,
      'WALK_IN': 0,
      'OTHER': 0
    };

    return sourceWeights[source] || 0;
  }

  private generateRecommendation(probability: number, factors: any): string {
    if (probability >= 80) {
      return 'High probability - Schedule final negotiation';
    } else if (probability >= 60) {
      return 'Good probability - Continue nurturing with regular follow-ups';
    } else if (probability >= 40) {
      if (factors.responseTimeFactor < 0) {
        return 'Medium probability - Improve response time to increase chances';
      } else if (factors.engagementFactor < 5) {
        return 'Medium probability - Increase engagement through appointments';
      } else {
        return 'Medium probability - Address any concerns and provide additional value';
      }
    } else if (probability >= 20) {
      return 'Low probability - Re-qualify lead and adjust strategy';
    } else {
      return 'Very low probability - Consider reassigning or archiving';
    }
  }

  calculateTeamPerformanceTrend(
    performanceData: { date: string; metric: number }[],
    _metricName: string
  ): { trend: 'improving' | 'declining' | 'stable'; changeRate: number } {
    if (performanceData.length < 2) {
      return { trend: 'stable', changeRate: 0 };
    }

    const xValues = performanceData.map((_, i) => i);
    const yValues = performanceData.map(d => d.metric);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const avgMetric = yValues.reduce((a, b) => a + b, 0) / yValues.length;
    const changeRate = avgMetric !== 0 ? (regression.slope / avgMetric) * 100 : 0;

    let trend: 'improving' | 'declining' | 'stable';
    if (changeRate > 5) {
      trend = 'improving';
    } else if (changeRate < -5) {
      trend = 'declining';
    } else {
      trend = 'stable';
    }

    return { trend, changeRate };
  }

  predictMarketTrend(
    historicalPrices: { date: string; avgPrice: number }[],
    forecastMonths: number
  ): { date: string; predictedPrice: number; confidence: number }[] {
    if (historicalPrices.length < 3) {
      return [];
    }

    const xValues = historicalPrices.map((_, i) => i);
    const yValues = historicalPrices.map(d => d.avgPrice);

    const regression = this.performLinearRegression(xValues, yValues);
    
    const predictions: { date: string; predictedPrice: number; confidence: number }[] = [];
    const lastDate = new Date(historicalPrices[historicalPrices.length - 1].date);

    for (let i = 1; i <= forecastMonths; i++) {
      const xValue = historicalPrices.length + i - 1;
      const predictedPrice = regression.slope * xValue + regression.intercept;
      
      const forecastDate = new Date(lastDate);
      forecastDate.setMonth(lastDate.getMonth() + i);

      const confidence = Math.max(0, Math.min(100, regression.rSquared * 100 * (1 - i * 0.05)));

      predictions.push({
        date: forecastDate.toISOString().split('T')[0],
        predictedPrice: Math.max(0, predictedPrice),
        confidence
      });
    }

    return predictions;
  }
}

import { Injectable } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { filter, debounceTime } from 'rxjs/operators';
import { Subject } from 'rxjs';
import { DossierApiService } from './dossier-api.service';
import { AnnonceApiService } from './annonce-api.service';

interface PrefetchConfig {
  route: string;
  probability: number;
  fetcher: () => void;
}

@Injectable({
  providedIn: 'root'
})
export class PrefetchService {
  private prefetchQueue = new Subject<string>();
  private prefetchedRoutes = new Set<string>();
  private navigationHistory: string[] = [];
  private maxHistorySize = 10;

  private routeProbabilities = new Map<string, number>();

  constructor(
    private router: Router,
    private dossierApiService: DossierApiService,
    private annonceApiService: AnnonceApiService
  ) {
    this.initializeNavigationTracking();
    this.initializePrefetchQueue();
  }

  private initializeNavigationTracking(): void {
    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: any) => {
        this.trackNavigation(event.urlAfterRedirects);
        this.predictAndPrefetch(event.urlAfterRedirects);
      });
  }

  private initializePrefetchQueue(): void {
    this.prefetchQueue
      .pipe(debounceTime(100))
      .subscribe(route => {
        if (!this.prefetchedRoutes.has(route)) {
          this.executePrefetch(route);
          this.prefetchedRoutes.add(route);
        }
      });
  }

  private trackNavigation(url: string): void {
    this.navigationHistory.push(url);
    if (this.navigationHistory.length > this.maxHistorySize) {
      this.navigationHistory.shift();
    }
    this.updateRouteProbabilities();
  }

  private updateRouteProbabilities(): void {
    if (this.navigationHistory.length < 2) return;

    const lastRoute = this.navigationHistory[this.navigationHistory.length - 2];
    const currentRoute = this.navigationHistory[this.navigationHistory.length - 1];
    const key = `${lastRoute}→${currentRoute}`;

    const currentProb = this.routeProbabilities.get(key) || 0;
    this.routeProbabilities.set(key, currentProb + 1);
  }

  private predictAndPrefetch(currentRoute: string): void {
    const predictions = this.getPredictions(currentRoute);
    predictions.forEach(prediction => {
      if (prediction.probability > 0.3) {
        this.prefetchQueue.next(prediction.route);
      }
    });
  }

  private getPredictions(currentRoute: string): PrefetchConfig[] {
    const predictions: PrefetchConfig[] = [];

    // Common patterns
    if (currentRoute.includes('/dossiers') && !currentRoute.includes('/dossiers/')) {
      predictions.push({
        route: '/dossiers/details',
        probability: 0.7,
        fetcher: () => this.prefetchDossiersList()
      });
    }

    if (currentRoute.match(/\/dossiers\/\d+$/)) {
      predictions.push({
        route: '/dossiers/list',
        probability: 0.5,
        fetcher: () => this.prefetchDossiersList()
      });
    }

    if (currentRoute.includes('/annonces') && !currentRoute.includes('/annonces/')) {
      predictions.push({
        route: '/annonces/details',
        probability: 0.6,
        fetcher: () => this.prefetchAnnoncesList()
      });
    }

    if (currentRoute === '/dashboard') {
      predictions.push(
        {
          route: '/dossiers',
          probability: 0.8,
          fetcher: () => this.prefetchDossiersList()
        },
        {
          route: '/annonces',
          probability: 0.6,
          fetcher: () => this.prefetchAnnoncesList()
        }
      );
    }

    // History-based predictions
    this.routeProbabilities.forEach((count, key) => {
      const [from, to] = key.split('→');
      if (from === currentRoute) {
        const totalFromRoute = Array.from(this.routeProbabilities.entries())
          .filter(([k]) => k.startsWith(from + '→'))
          .reduce((sum, [, c]) => sum + c, 0);
        
        const probability = count / totalFromRoute;
        if (probability > 0.3) {
          predictions.push({
            route: to,
            probability,
            fetcher: () => this.prefetchByRoute(to)
          });
        }
      }
    });

    return predictions.sort((a, b) => b.probability - a.probability);
  }

  private executePrefetch(route: string): void {
    if (route.includes('/dossiers')) {
      this.prefetchDossiersList();
    } else if (route.includes('/annonces')) {
      this.prefetchAnnoncesList();
    }
  }

  private prefetchByRoute(route: string): void {
    if (route.includes('/dossiers')) {
      this.prefetchDossiersList();
    } else if (route.includes('/annonces')) {
      this.prefetchAnnoncesList();
    }
  }

  private prefetchDossiersList(): void {
    // Prefetch first page with small size
    this.dossierApiService.list({ page: 0, size: 10 }).subscribe({
      next: () => console.log('[Prefetch] Dossiers list prefetched'),
      error: () => console.warn('[Prefetch] Failed to prefetch dossiers')
    });
  }

  private prefetchAnnoncesList(): void {
    // Prefetch first page with small size
    this.annonceApiService.list({ page: 0, size: 10 }).subscribe({
      next: () => console.log('[Prefetch] Annonces list prefetched'),
      error: () => console.warn('[Prefetch] Failed to prefetch annonces')
    });
  }

  public manualPrefetch(route: string): void {
    this.prefetchQueue.next(route);
  }

  public clearPrefetchCache(): void {
    this.prefetchedRoutes.clear();
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, BehaviorSubject } from 'rxjs';
import { environment } from '../../environments/environment';

export interface PushSubscriptionData {
  endpoint: string;
  keys: {
    p256dh: string;
    auth: string;
  };
}

export interface NotificationPayload {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  data?: any;
  actions?: Array<{
    action: string;
    title: string;
    icon?: string;
  }>;
  tag?: string;
  requireInteraction?: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class PushNotificationService {
  private subscription$ = new BehaviorSubject<PushSubscription | null>(null);
  private permission$ = new BehaviorSubject<NotificationPermission>('default');
  private vapidPublicKey = environment.vapidPublicKey || '';

  constructor(private http: HttpClient) {
    this.checkPermission();
  }

  /**
   * Check current notification permission
   */
  private checkPermission(): void {
    if ('Notification' in window) {
      this.permission$.next(Notification.permission);
    }
  }

  /**
   * Request notification permission from user
   */
  async requestPermission(): Promise<NotificationPermission> {
    if (!('Notification' in window)) {
      console.warn('This browser does not support notifications');
      return 'denied';
    }

    try {
      const permission = await Notification.requestPermission();
      this.permission$.next(permission);
      
      if (permission === 'granted') {
        await this.subscribeToPush();
      }
      
      return permission;
    } catch (error) {
      console.error('Error requesting notification permission:', error);
      return 'denied';
    }
  }

  /**
   * Subscribe to push notifications
   */
  async subscribeToPush(): Promise<PushSubscription | null> {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      console.warn('Push notifications not supported');
      return null;
    }

    try {
      const registration = await navigator.serviceWorker.ready;
      
      // Check if already subscribed
      let subscription = await registration.pushManager.getSubscription();
      
      if (!subscription) {
        // Subscribe to push
        const applicationServerKey = this.urlBase64ToUint8Array(this.vapidPublicKey);
        
        subscription = await registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: applicationServerKey as BufferSource
        });
      }

      // Send subscription to backend
      await this.sendSubscriptionToBackend(subscription);
      
      this.subscription$.next(subscription);
      return subscription;
    } catch (error) {
      console.error('Error subscribing to push:', error);
      return null;
    }
  }

  /**
   * Unsubscribe from push notifications
   */
  async unsubscribeFromPush(): Promise<boolean> {
    const subscription = this.subscription$.value;
    
    if (!subscription) {
      return false;
    }

    try {
      // Remove subscription from backend
      await this.removeSubscriptionFromBackend(subscription);
      
      // Unsubscribe from browser
      await subscription.unsubscribe();
      
      this.subscription$.next(null);
      return true;
    } catch (error) {
      console.error('Error unsubscribing from push:', error);
      return false;
    }
  }

  /**
   * Show local notification (doesn't require push)
   */
  async showNotification(payload: NotificationPayload): Promise<void> {
    if (!('Notification' in window)) {
      console.warn('Notifications not supported');
      return;
    }

    if (Notification.permission !== 'granted') {
      const permission = await this.requestPermission();
      if (permission !== 'granted') {
        return;
      }
    }

    try {
      const registration = await navigator.serviceWorker.ready;
      
      await registration.showNotification(payload.title, {
        body: payload.body,
        icon: payload.icon || '/assets/icons/icon-192x192.png',
        badge: payload.badge || '/assets/icons/icon-96x96.png',
        data: payload.data,
        actions: payload.actions,
        tag: payload.tag,
        requireInteraction: payload.requireInteraction || false,
        vibrate: [200, 100, 200],
        timestamp: Date.now()
      } as any);
    } catch (error) {
      console.error('Error showing notification:', error);
    }
  }

  /**
   * Get current subscription
   */
  getSubscription(): Observable<PushSubscription | null> {
    return this.subscription$.asObservable();
  }

  /**
   * Get current permission status
   */
  getPermission(): Observable<NotificationPermission> {
    return this.permission$.asObservable();
  }

  /**
   * Check if push notifications are supported
   */
  isSupported(): boolean {
    return 'Notification' in window && 
           'serviceWorker' in navigator && 
           'PushManager' in window;
  }

  /**
   * Send subscription to backend
   */
  private async sendSubscriptionToBackend(subscription: PushSubscription): Promise<void> {
    const subscriptionData = this.subscriptionToData(subscription);
    
    try {
      await this.http.post('/api/v1/push/subscribe', subscriptionData).toPromise();
    } catch (error) {
      console.error('Error sending subscription to backend:', error);
    }
  }

  /**
   * Remove subscription from backend
   */
  private async removeSubscriptionFromBackend(subscription: PushSubscription): Promise<void> {
    const subscriptionData = this.subscriptionToData(subscription);
    
    try {
      await this.http.post('/api/v1/push/unsubscribe', subscriptionData).toPromise();
    } catch (error) {
      console.error('Error removing subscription from backend:', error);
    }
  }

  /**
   * Convert subscription to data format for backend
   */
  private subscriptionToData(subscription: PushSubscription): PushSubscriptionData {
    const key = subscription.getKey('p256dh');
    const auth = subscription.getKey('auth');
    
    return {
      endpoint: subscription.endpoint,
      keys: {
        p256dh: key ? this.arrayBufferToBase64(key) : '',
        auth: auth ? this.arrayBufferToBase64(auth) : ''
      }
    };
  }

  /**
   * Convert URL-safe base64 to Uint8Array
   */
  private urlBase64ToUint8Array(base64String: string): Uint8Array {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding)
      .replace(/-/g, '+')
      .replace(/_/g, '/');

    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);

    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }

  /**
   * Convert ArrayBuffer to base64
   */
  private arrayBufferToBase64(buffer: ArrayBuffer): string {
    const bytes = new Uint8Array(buffer);
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return window.btoa(binary);
  }

  /**
   * Test notification (for debugging)
   */
  async testNotification(): Promise<void> {
    await this.showNotification({
      title: 'Test Notification',
      body: 'This is a test notification from CRM Immobilier',
      icon: '/assets/icons/icon-192x192.png',
      data: { test: true },
      actions: [
        {
          action: 'view',
          title: 'View'
        },
        {
          action: 'dismiss',
          title: 'Dismiss'
        }
      ]
    });
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

@Injectable({
  providedIn: 'root'
})
export class PwaService {
  private deferredPrompt: BeforeInstallPromptEvent | null = null;
  private showInstallPrompt$ = new BehaviorSubject<boolean>(false);
  private isInstalled$ = new BehaviorSubject<boolean>(false);
  private isStandalone$ = new BehaviorSubject<boolean>(false);

  constructor() {
    this.init();
  }

  private init(): void {
    // Check if already installed
    this.checkInstallStatus();

    // Listen for install prompt
    window.addEventListener('beforeinstallprompt', (e: Event) => {
      e.preventDefault();
      this.deferredPrompt = e as BeforeInstallPromptEvent;
      
      // Show install prompt if not dismissed before
      const dismissed = localStorage.getItem('pwa_install_dismissed');
      if (!dismissed) {
        this.showInstallPrompt$.next(true);
      }
    });

    // Listen for app installed
    window.addEventListener('appinstalled', () => {
      console.log('PWA installed');
      this.deferredPrompt = null;
      this.showInstallPrompt$.next(false);
      this.isInstalled$.next(true);
      localStorage.removeItem('pwa_install_dismissed');
    });
  }

  private checkInstallStatus(): void {
    // Check if running in standalone mode
    const isStandalone = window.matchMedia('(display-mode: standalone)').matches ||
                        (window.navigator as any).standalone ||
                        document.referrer.includes('android-app://');
    
    this.isStandalone$.next(isStandalone);
    this.isInstalled$.next(isStandalone);
  }

  /**
   * Prompt user to install PWA
   */
  async promptInstall(): Promise<boolean> {
    if (!this.deferredPrompt) {
      console.warn('Install prompt not available');
      return false;
    }

    try {
      await this.deferredPrompt.prompt();
      const { outcome } = await this.deferredPrompt.userChoice;
      
      if (outcome === 'accepted') {
        console.log('User accepted install');
        this.showInstallPrompt$.next(false);
        return true;
      } else {
        console.log('User dismissed install');
        this.dismissInstallPrompt();
        return false;
      }
    } catch (error) {
      console.error('Error prompting install:', error);
      return false;
    }
  }

  /**
   * Dismiss install prompt
   */
  dismissInstallPrompt(): void {
    localStorage.setItem('pwa_install_dismissed', Date.now().toString());
    this.showInstallPrompt$.next(false);
  }

  /**
   * Get install prompt status
   */
  getInstallPromptStatus(): Observable<boolean> {
    return this.showInstallPrompt$.asObservable();
  }

  /**
   * Check if app is installed
   */
  getInstallStatus(): Observable<boolean> {
    return this.isInstalled$.asObservable();
  }

  /**
   * Check if running in standalone mode
   */
  getStandaloneStatus(): Observable<boolean> {
    return this.isStandalone$.asObservable();
  }

  /**
   * Check if install is available
   */
  isInstallAvailable(): boolean {
    return this.deferredPrompt !== null;
  }

  /**
   * Get display mode
   */
  getDisplayMode(): 'browser' | 'standalone' | 'minimal-ui' | 'fullscreen' {
    if (window.matchMedia('(display-mode: fullscreen)').matches) {
      return 'fullscreen';
    }
    if (window.matchMedia('(display-mode: standalone)').matches) {
      return 'standalone';
    }
    if (window.matchMedia('(display-mode: minimal-ui)').matches) {
      return 'minimal-ui';
    }
    return 'browser';
  }

  /**
   * Check if PWA features are supported
   */
  isPWASupported(): boolean {
    return 'serviceWorker' in navigator && 'BeforeInstallPromptEvent' in window;
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

export interface QuickAction {
  id: string;
  icon: string;
  label: string;
  shortcut: string;
  color: 'primary' | 'accent' | 'warn';
  disabled?: boolean;
  action: () => void;
}

export interface RecentAction {
  dossierId: number;
  actionId: string;
  actionLabel: string;
  timestamp: string;
  metadata?: Record<string, any>;
}

@Injectable({
  providedIn: 'root'
})
export class QuickActionsService {
  private readonly STORAGE_KEY = 'quick_actions_history';
  private readonly MAX_RECENT_ACTIONS = 5;
  
  private recentActionsSubject = new BehaviorSubject<RecentAction[]>([]);
  public recentActions$ = this.recentActionsSubject.asObservable();

  constructor() {
    this.loadRecentActions();
  }

  private loadRecentActions(): void {
    const stored = localStorage.getItem(this.STORAGE_KEY);
    if (stored) {
      try {
        const actions = JSON.parse(stored) as RecentAction[];
        this.recentActionsSubject.next(actions);
      } catch (e) {
        console.error('Failed to load recent actions', e);
        this.recentActionsSubject.next([]);
      }
    }
  }

  addRecentAction(action: RecentAction): void {
    const currentActions = this.recentActionsSubject.value;
    
    const filteredActions = currentActions.filter(
      a => !(a.dossierId === action.dossierId && a.actionId === action.actionId)
    );
    
    const updatedActions = [action, ...filteredActions].slice(0, this.MAX_RECENT_ACTIONS);
    
    this.recentActionsSubject.next(updatedActions);
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(updatedActions));
  }

  getRecentActions(dossierId?: number): RecentAction[] {
    const actions = this.recentActionsSubject.value;
    if (dossierId !== undefined) {
      return actions.filter(a => a.dossierId === dossierId);
    }
    return actions;
  }

  clearRecentActions(): void {
    this.recentActionsSubject.next([]);
    localStorage.removeItem(this.STORAGE_KEY);
  }

  clearDossierActions(dossierId: number): void {
    const currentActions = this.recentActionsSubject.value;
    const filteredActions = currentActions.filter(a => a.dossierId !== dossierId);
    this.recentActionsSubject.next(filteredActions);
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(filteredActions));
  }
}

import { Injectable } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { BehaviorSubject, Observable } from 'rxjs';
import { filter } from 'rxjs/operators';

export interface RecentItem {
  id: string;
  type: 'dossier' | 'annonce';
  title: string;
  subtitle?: string;
  route: string;
  timestamp: number;
}

@Injectable({
  providedIn: 'root'
})
export class RecentNavigationService {
  private readonly STORAGE_KEY = 'recent_navigation';
  private readonly MAX_ITEMS = 10;
  
  private recentItemsSubject: BehaviorSubject<RecentItem[]>;
  public recentItems$: Observable<RecentItem[]>;

  constructor(private router: Router) {
    const stored = this.loadFromStorage();
    this.recentItemsSubject = new BehaviorSubject<RecentItem[]>(stored);
    this.recentItems$ = this.recentItemsSubject.asObservable();
    
    this.initializeRouterTracking();
  }

  private initializeRouterTracking(): void {
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd)
    ).subscribe((event) => {
      this.trackNavigation(event.url);
    });
  }

  private trackNavigation(url: string): void {
    // Parse dossier/annonce routes
    const dossierMatch = url.match(/\/dossiers\/(\d+)/);
    const annonceMatch = url.match(/\/annonces\/(\d+)/);
    
    if (dossierMatch) {
      const _id = dossierMatch[1];
      // Don't add immediately - wait for title to be set via addRecentItem
      return;
    } else if (annonceMatch) {
      const _id = annonceMatch[1];
      // Don't add immediately - wait for title to be set via addRecentItem
      return;
    }
  }

  addRecentItem(item: Omit<RecentItem, 'timestamp'>): void {
    const items = this.recentItemsSubject.value;
    const timestamp = Date.now();
    
    // Remove existing entry with same id
    const filtered = items.filter(i => i.id !== item.id);
    
    // Add new item at the beginning
    const newItems = [{ ...item, timestamp }, ...filtered].slice(0, this.MAX_ITEMS);
    
    this.recentItemsSubject.next(newItems);
    this.saveToStorage(newItems);
  }

  getRecentItems(): RecentItem[] {
    return this.recentItemsSubject.value;
  }

  clearRecentItems(): void {
    this.recentItemsSubject.next([]);
    localStorage.removeItem(this.STORAGE_KEY);
  }

  private loadFromStorage(): RecentItem[] {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch (e) {
      console.error('Failed to load recent navigation', e);
    }
    return [];
  }

  private saveToStorage(items: RecentItem[]): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(items));
    } catch (e) {
      console.error('Failed to save recent navigation', e);
    }
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, of } from 'rxjs';
import { catchError, retry, timeout } from 'rxjs/operators';

export interface RegionConfig {
  name: string;
  displayName: string;
  endpoint: string;
  continent: string;
  isPrimary: boolean;
  priority: number;
  healthCheckUrl: string;
}

export interface GeoLocationData {
  country: string;
  continent: string;
  city: string;
  latitude: number;
  longitude: number;
  timezone: string;
}

export interface RegionHealth {
  region: string;
  healthy: boolean;
  latency: number;
  lastChecked: Date;
}

@Injectable({
  providedIn: 'root'
})
export class RegionRoutingService {
  private readonly REGIONS: RegionConfig[] = [
    {
      name: 'eu-west-1',
      displayName: 'Europe (Paris)',
      endpoint: 'https://eu-west-1.atlas-crm.com',
      continent: 'EU',
      isPrimary: true,
      priority: 1,
      healthCheckUrl: '/actuator/health'
    },
    {
      name: 'us-east-1',
      displayName: 'North America (Virginia)',
      endpoint: 'https://us-east-1.atlas-crm.com',
      continent: 'NA',
      isPrimary: false,
      priority: 2,
      healthCheckUrl: '/actuator/health'
    },
    {
      name: 'ap-southeast-1',
      displayName: 'Asia Pacific (Singapore)',
      endpoint: 'https://ap-southeast-1.atlas-crm.com',
      continent: 'AS',
      isPrimary: false,
      priority: 3,
      healthCheckUrl: '/actuator/health'
    }
  ];

  private selectedRegionSubject = new BehaviorSubject<RegionConfig | null>(null);
  public selectedRegion$ = this.selectedRegionSubject.asObservable();

  private regionHealthSubject = new BehaviorSubject<Map<string, RegionHealth>>(new Map());
  public regionHealth$ = this.regionHealthSubject.asObservable();

  private failoverInProgressSubject = new BehaviorSubject<boolean>(false);
  public failoverInProgress$ = this.failoverInProgressSubject.asObservable();

  private readonly LATENCY_THRESHOLD_MS = 200;
  private readonly HEALTH_CHECK_INTERVAL_MS = 30000;
  private readonly STORAGE_KEY = 'atlas_selected_region';

  constructor(private http: HttpClient) {
    this.initializeRegionSelection();
    this.startHealthMonitoring();
  }

  private async initializeRegionSelection(): Promise<void> {
    const savedRegion = localStorage.getItem(this.STORAGE_KEY);
    
    if (savedRegion) {
      const region = this.REGIONS.find(r => r.name === savedRegion);
      if (region && await this.checkRegionHealth(region)) {
        this.selectRegion(region);
        return;
      }
    }

    try {
      const geoLocation = await this.detectGeoLocation();
      const optimalRegion = await this.findOptimalRegion(geoLocation);
      this.selectRegion(optimalRegion);
    } catch (error) {
      console.error('Failed to detect optimal region, using primary', error);
      const primaryRegion = this.REGIONS.find(r => r.isPrimary) || this.REGIONS[0];
      this.selectRegion(primaryRegion);
    }
  }

  private detectGeoLocation(): Promise<GeoLocationData> {
    return this.http.get<GeoLocationData>('https://ipapi.co/json/')
      .pipe(
        timeout(5000),
        retry(2),
        catchError(error => {
          console.error('Geolocation detection failed', error);
          return of({
            country: 'US',
            continent: 'NA',
            city: 'Unknown',
            latitude: 0,
            longitude: 0,
            timezone: 'UTC'
          });
        })
      )
      .toPromise() as Promise<GeoLocationData>;
  }

  private async findOptimalRegion(geoLocation: GeoLocationData): Promise<RegionConfig> {
    const continentMap: { [key: string]: string } = {
      'EU': 'EU',
      'NA': 'NA',
      'SA': 'NA',
      'AS': 'AS',
      'OC': 'AS',
      'AF': 'EU'
    };

    const targetContinent = continentMap[geoLocation.continent] || 'EU';
    
    const continentRegions = this.REGIONS.filter(r => r.continent === targetContinent);
    
    if (continentRegions.length > 0) {
      const latencies = await Promise.all(
        continentRegions.map(async region => ({
          region,
          latency: await this.measureLatency(region)
        }))
      );

      latencies.sort((a, b) => a.latency - b.latency);
      
      const fastestHealthyRegion = latencies.find(l => l.latency < this.LATENCY_THRESHOLD_MS);
      if (fastestHealthyRegion) {
        return fastestHealthyRegion.region;
      }
    }

    const allLatencies = await Promise.all(
      this.REGIONS.map(async region => ({
        region,
        latency: await this.measureLatency(region)
      }))
    );

    allLatencies.sort((a, b) => a.latency - b.latency);
    return allLatencies[0].region;
  }

  private async measureLatency(region: RegionConfig): Promise<number> {
    const startTime = performance.now();
    
    try {
      await this.http.get(region.endpoint + region.healthCheckUrl, {
        observe: 'response'
      }).pipe(
        timeout(5000)
      ).toPromise();
      
      const endTime = performance.now();
      return endTime - startTime;
    } catch (error) {
      return Infinity;
    }
  }

  private async checkRegionHealth(region: RegionConfig): Promise<boolean> {
    try {
      const response = await this.http.get<any>(region.endpoint + region.healthCheckUrl)
        .pipe(
          timeout(5000),
          retry(1)
        )
        .toPromise();
      
      return response?.status === 'UP';
    } catch (error) {
      return false;
    }
  }

  private selectRegion(region: RegionConfig): void {
    this.selectedRegionSubject.next(region);
    localStorage.setItem(this.STORAGE_KEY, region.name);
    console.log(`Selected region: ${region.displayName} (${region.name})`);
  }

  public getApiEndpoint(): string {
    const region = this.selectedRegionSubject.value;
    return region ? region.endpoint : this.REGIONS[0].endpoint;
  }

  public getCurrentRegion(): RegionConfig | null {
    return this.selectedRegionSubject.value;
  }

  public getAllRegions(): RegionConfig[] {
    return [...this.REGIONS];
  }

  public async switchRegion(regionName: string): Promise<boolean> {
    const region = this.REGIONS.find(r => r.name === regionName);
    
    if (!region) {
      console.error(`Region ${regionName} not found`);
      return false;
    }

    const isHealthy = await this.checkRegionHealth(region);
    
    if (!isHealthy) {
      console.error(`Region ${regionName} is unhealthy`);
      return false;
    }

    this.selectRegion(region);
    return true;
  }

  private startHealthMonitoring(): void {
    setInterval(async () => {
      const healthMap = new Map<string, RegionHealth>();

      for (const region of this.REGIONS) {
        const latency = await this.measureLatency(region);
        const healthy = latency < this.LATENCY_THRESHOLD_MS && latency !== Infinity;

        healthMap.set(region.name, {
          region: region.name,
          healthy,
          latency,
          lastChecked: new Date()
        });

        if (latency > this.LATENCY_THRESHOLD_MS && latency !== Infinity) {
          console.warn(`High latency detected for region ${region.name}: ${latency.toFixed(2)}ms`);
          this.reportLatencyMetric(region.name, latency);
        }
      }

      this.regionHealthSubject.next(healthMap);

      const currentRegion = this.selectedRegionSubject.value;
      if (currentRegion) {
        const currentHealth = healthMap.get(currentRegion.name);
        if (currentHealth && !currentHealth.healthy) {
          await this.performFailover();
        }
      }
    }, this.HEALTH_CHECK_INTERVAL_MS);
  }

  private async performFailover(): Promise<void> {
    if (this.failoverInProgressSubject.value) {
      return;
    }

    this.failoverInProgressSubject.next(true);
    console.warn('Performing automatic failover due to unhealthy region');

    try {
      const healthyRegions = this.REGIONS.filter(async r => {
        const health = await this.checkRegionHealth(r);
        return health;
      });

      healthyRegions.sort((a, b) => a.priority - b.priority);

      if (healthyRegions.length > 0) {
        const targetRegion = healthyRegions[0];
        console.log(`Failing over to region: ${targetRegion.displayName}`);
        this.selectRegion(targetRegion);
      } else {
        console.error('No healthy regions available for failover');
      }
    } finally {
      this.failoverInProgressSubject.next(false);
    }
  }

  private reportLatencyMetric(region: string, latency: number): void {
    if (typeof navigator !== 'undefined' && 'sendBeacon' in navigator) {
      const data = JSON.stringify({
        metric: 'cross_region_latency',
        region,
        latency,
        timestamp: new Date().toISOString()
      });
      
      navigator.sendBeacon('/api/metrics/latency', data);
    }
  }

  public async testAllRegions(): Promise<Map<string, number>> {
    const latencies = new Map<string, number>();

    for (const region of this.REGIONS) {
      const latency = await this.measureLatency(region);
      latencies.set(region.name, latency);
    }

    return latencies;
  }

  public getRegionByName(name: string): RegionConfig | undefined {
    return this.REGIONS.find(r => r.name === name);
  }

  public isRegionHealthy(regionName: string): boolean {
    const healthMap = this.regionHealthSubject.value;
    const health = healthMap.get(regionName);
    return health?.healthy ?? false;
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface ReportColumn {
  field: string;
  header: string;
  format?: 'text' | 'number' | 'currency' | 'date' | 'percentage';
  width?: number;
}

export interface ReportExportOptions {
  format: 'csv' | 'excel' | 'pdf';
  columns?: ReportColumn[];
  title?: string;
  subtitle?: string;
  includeHeaders?: boolean;
  includeFooter?: boolean;
  branding?: {
    logoUrl?: string;
    companyName?: string;
    primaryColor?: string;
  };
}

export interface CustomReportDefinition {
  dimensions: string[];
  metrics: string[];
  filters?: Record<string, any>;
  groupBy?: string[];
  orderBy?: { field: string; direction: 'asc' | 'desc' }[];
  limit?: number;
}

@Injectable({
  providedIn: 'root'
})
export class ReportApiService {
  private readonly apiUrl = '/api/v1/reports';

  constructor(private http: HttpClient) {}

  generateCustomReport(definition: CustomReportDefinition, orgId?: string): Observable<any> {
    let params = new HttpParams();
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.post<any>(`${this.apiUrl}/custom`, definition, { params });
  }

  exportReport(reportId: string, options: ReportExportOptions, orgId?: string): Observable<Blob> {
    let params = new HttpParams();
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.post(`${this.apiUrl}/${reportId}/export`, options, {
      params,
      responseType: 'blob'
    });
  }

  exportCustomReport(definition: CustomReportDefinition, options: ReportExportOptions, orgId?: string): Observable<Blob> {
    let params = new HttpParams();
    if (orgId) {
      params = params.set('orgId', orgId);
    }
    return this.http.post(`${this.apiUrl}/custom/export`, { definition, options }, {
      params,
      responseType: 'blob'
    });
  }

  getAvailableDimensions(): Observable<string[]> {
    return this.http.get<string[]>(`${this.apiUrl}/dimensions`);
  }

  getAvailableMetrics(): Observable<string[]> {
    return this.http.get<string[]>(`${this.apiUrl}/metrics`);
  }

  private downloadFile(blob: Blob, filename: string): void {
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  async exportToCSV(data: any[], columns: ReportColumn[], filename = 'report.csv'): Promise<void> {
    const Papa = await import('papaparse');
    
    const csvData = data.map(row => {
      const csvRow: any = {};
      columns.forEach(col => {
        csvRow[col.header] = this.formatValue(row[col.field], col.format);
      });
      return csvRow;
    });

    const csv = Papa.unparse(csvData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    this.downloadFile(blob, filename);
  }

  async exportToExcel(data: any[], columns: ReportColumn[], filename = 'report.xlsx'): Promise<void> {
    const XLSX = await import('xlsx');
    
    const worksheetData = [
      columns.map(col => col.header),
      ...data.map(row => columns.map(col => this.formatValue(row[col.field], col.format)))
    ];

    const ws = XLSX.utils.aoa_to_sheet(worksheetData);
    
    columns.forEach((col, idx) => {
      if (col.width) {
        if (!ws['!cols']) ws['!cols'] = [];
        ws['!cols'][idx] = { wch: col.width };
      }
    });

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Report');
    XLSX.writeFile(wb, filename);
  }

  async exportToPDF(
    data: any[], 
    columns: ReportColumn[], 
    options: { title?: string; subtitle?: string; branding?: any } = {},
    filename = 'report.pdf'
  ): Promise<void> {
    const [jsPDFModule] = await Promise.all([
      import('jspdf'),
      import('jspdf-autotable')
    ]);

    const { jsPDF: JsPDFClass } = jsPDFModule;
    const doc = new JsPDFClass();

    let yPosition = 20;

    if (options.branding?.logoUrl) {
      const img = new Image();
      img.src = options.branding.logoUrl;
      doc.addImage(img, 'PNG', 14, 10, 30, 15);
      yPosition = 35;
    }

    if (options.branding?.companyName) {
      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(options.branding.companyName, 200, 15, { align: 'right' });
    }

    if (options.title) {
      doc.setFontSize(18);
      doc.setTextColor(0);
      doc.text(options.title, 14, yPosition);
      yPosition += 10;
    }

    if (options.subtitle) {
      doc.setFontSize(11);
      doc.setTextColor(100);
      doc.text(options.subtitle, 14, yPosition);
      yPosition += 10;
    }

    (doc as any).autoTable({
      startY: yPosition,
      head: [columns.map(col => col.header)],
      body: data.map(row => columns.map(col => this.formatValue(row[col.field], col.format))),
      theme: 'grid',
      styles: { fontSize: 10 },
      headStyles: { 
        fillColor: options.branding?.primaryColor ? this.hexToRgb(options.branding.primaryColor) : [66, 139, 202] 
      }
    });

    doc.save(filename);
  }

  private formatValue(value: any, format?: string): string {
    if (value == null) return '';
    
    switch (format) {
      case 'currency':
        return new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR' }).format(value);
      case 'number':
        return new Intl.NumberFormat('fr-FR').format(value);
      case 'percentage':
        return `${(value * 100).toFixed(2)}%`;
      case 'date':
        return new Date(value).toLocaleDateString('fr-FR');
      default:
        return String(value);
    }
  }

  private hexToRgb(hex: string): [number, number, number] {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? [
      parseInt(result[1], 16),
      parseInt(result[2], 16),
      parseInt(result[3], 16)
    ] : [66, 139, 202];
  }
}

