      minCols: 4,
      minRows: 3,
      maxCols: 12,
      maxRows: 8,
      category: 'list'
    });
  }

  register(metadata: WidgetMetadata): void {
    this.widgets.set(metadata.id, metadata);
  }

  unregister(widgetId: string): void {
    this.widgets.delete(widgetId);
  }

  getMetadata(widgetId: string): WidgetMetadata | undefined {
    return this.widgets.get(widgetId);
  }

  getAllWidgets(): WidgetMetadata[] {
    return Array.from(this.widgets.values());
  }

  getWidgetsByCategory(category: WidgetMetadata['category']): WidgetMetadata[] {
    return this.getAllWidgets().filter(w => w.category === category);
  }

  isRegistered(widgetId: string): boolean {
    return this.widgets.has(widgetId);
  }

  getDefaultDimensions(widgetId: string): { cols: number; rows: number } {
    const metadata = this.getMetadata(widgetId);
    return metadata 
      ? { cols: metadata.defaultCols, rows: metadata.defaultRows }
      : { cols: 4, rows: 3 };
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface WorkflowState {
  stateCode: string;
  stateName: string;
  stateType: 'initial' | 'intermediate' | 'final';
  color: string;
  positionX: number;
  positionY: number;
  isInitial: boolean;
  isFinal: boolean;
  description?: string;
}

export interface WorkflowTransition {
  fromState: string;
  toState: string;
  label: string;
  requiredFields: string[];
  allowedRoles: string[];
  isActive: boolean;
  priority?: number;
  conditionsJson?: any;
  actionsJson?: any[];
}

export interface WorkflowDefinition {
  id?: number;
  orgId?: string;
  name: string;
  description?: string;
  caseType: string;
  version?: number;
  isActive: boolean;
  isPublished: boolean;
  isTemplate?: boolean;
  templateCategory?: string;
  parentVersionId?: number;
  statesJson: WorkflowState[];
  transitionsJson: WorkflowTransition[];
  metadataJson?: any;
  initialState: string;
  finalStates: string;
