import { Injectable } from '@angular/core';
import { HttpInterceptor, HttpRequest, HttpHandler, HttpEvent, HttpErrorResponse } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';
import { ToastNotificationService } from '../services/toast-notification.service';

interface ProblemDetail {
  type?: string;
  title?: string;
  status?: number;
  detail?: string;
  instance?: string;
  [key: string]: unknown;
}

@Injectable()
export class CorrelationIdInterceptor implements HttpInterceptor {
  private pendingRequests = new Map<string, HttpRequest<any>>();

  constructor(
    private toastService: ToastNotificationService,
    private router: Router,
    private authService: AuthService
  ) { }

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    if (!req.url.includes('/api/')) {
      return next.handle(req);
    }

    const correlationId = this.generateCorrelationId();

    const modifiedReq = req.clone({
      setHeaders: {
        'X-Correlation-Id': correlationId
      }
    });

    this.pendingRequests.set(correlationId, modifiedReq);

    return next.handle(modifiedReq).pipe(
      catchError((error: HttpErrorResponse) => {
        console.error(`HTTP Error [${correlationId}]:`, {
          status: error.status,
          statusText: error.statusText,
          message: error.message,
          url: error.url,
          correlationId: correlationId
        });

        this.handleError(error, modifiedReq, correlationId);
        this.pendingRequests.delete(correlationId);
        return throwError(() => error);
      })
    );
  }

  private handleError(error: HttpErrorResponse, originalRequest: HttpRequest<any>, correlationId: string): void {
    const problemDetail = this.parseProblemDetail(error);

    switch (error.status) {
      case 401:
        this.toastService.error(
          'Session expirée. Veuillez vous reconnecter.',
          {
            label: 'Reconnecter',
            handler: () => {
              this.authService.handleSessionExpired();
            }
          }
        );
        break;

      case 403:
        this.toastService.error(
          "Accès refusé. Vous n'avez pas les droits nécessaires.",
          'Fermer'
        );
        break;

      case 400: {
        const badRequestMessage = problemDetail?.detail || 'Requête invalide. Veuillez vérifier votre saisie.';
        this.toastService.error(badRequestMessage, 'Fermer');
        break;
      }

      case 404: {
        const notFoundMessage = problemDetail?.detail || 'La ressource demandée est introuvable.';
        this.toastService.error(notFoundMessage, 'Fermer');
        break;
      }

      case 409: {
        const conflictMessage = problemDetail?.detail || 'Un conflit est survenu. Veuillez réessayer.';
        this.toastService.warning(
          conflictMessage,
          {
            label: 'Réessayer',
            handler: () => this.retryRequest(originalRequest, correlationId)
          }
        );
        break;
      }

      case 500: {
        const serverErrorMessage = problemDetail?.detail || 'Une erreur interne est survenue.';
        this.toastService.error(
          serverErrorMessage,
          {
            label: 'Réessayer',
            handler: () => this.retryRequest(originalRequest, correlationId)
          }
        );
        break;
      }

      case 0:
      case 504:
      case 503: {
        this.toastService.error(
          'Impossible de contacter le serveur. Vérifiez votre connexion.',
          {
            label: 'Réessayer',
            handler: () => this.retryRequest(originalRequest, correlationId)
          }
        );
        break;
      }

      default: {
        if (error.status >= 500) {
          this.toastService.error(
            'Une erreur serveur est survenue.',
            {
              label: 'Réessayer',
              handler: () => this.retryRequest(originalRequest, correlationId)
            }
          );
        }
        break;
      }
    }
  }

  private retryRequest(request: HttpRequest<any>, correlationId: string): void {
    console.log(`Retrying request [${correlationId}]:`, request.url);
    window.location.reload();
  }

  private parseProblemDetail(error: HttpErrorResponse): ProblemDetail | null {
    if (!error.error) {
      return null;
    }

    if (typeof error.error === 'object' &&
      ('detail' in error.error || 'title' in error.error || 'type' in error.error)) {
      return error.error as ProblemDetail;
    }

    return null;
  }

  private generateCorrelationId(): string {
    return `${Date.now()}-${Math.random().toString(36).substring(2, 15)}`;
  }
}

import { Injectable } from '@angular/core';
import { HttpInterceptor, HttpRequest, HttpHandler, HttpEvent } from '@angular/common/http';
import { Observable } from 'rxjs';
import { AuthService } from '../services/auth.service';

@Injectable()
export class HttpAuthInterceptor implements HttpInterceptor {
  private readonly ORG_ID_KEY = 'org_id';
  private readonly DEFAULT_ORG_ID = 'ORG-001';

  constructor(private authService: AuthService) { }

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    if (!req.url.includes('/api/')) {
      return next.handle(req);
    }

    const token = this.authService.getToken();
    const orgId = localStorage.getItem(this.ORG_ID_KEY);

    const headers: { [key: string]: string } = {};

    if (token) {
      headers['Authorization'] = `Bearer ${token}`;

      // Tenant header is mandatory for backend calls. If the user did not select one yet,
      // keep a deterministic default to avoid 400 Bad Request on endpoints like /ping.
      if (!orgId) {
        headers['X-Org-Id'] = this.DEFAULT_ORG_ID;
      }
    }

    if (orgId) {
      headers['X-Org-Id'] = orgId;
    }

    if (Object.keys(headers).length > 0) {
      const modifiedReq = req.clone({ setHeaders: headers });
      return next.handle(modifiedReq);
    }

    return next.handle(req);
  }
}

import { Injectable } from '@angular/core';
import { HttpRequest, HttpHandler, HttpEvent, HttpInterceptor, HttpResponse } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { tap } from 'rxjs/operators';
import { HttpCacheService } from '../services/http-cache.service';

/**
 * Cache GET requests for 60 seconds to improve performance.
 * Skips caching if URL contains 'no-cache'.
 */
@Injectable()
export class HttpCacheInterceptor implements HttpInterceptor {

    // Endpoints known to be safely cacheable
    private cacheableEndpoints = [
        '/api/v1/kpi',
        '/api/v1/users',
        '/api/v1/partie-prenante-roles',
        '/api/v1/cities' // example lookup endpoints
    ];

    constructor(private cacheService: HttpCacheService) { }

    intercept(request: HttpRequest<unknown>, next: HttpHandler): Observable<HttpEvent<unknown>> {

        // Only cache GET requests
        if (request.method !== 'GET') {
            // Invalidate cache safely if it's a mutation (e.g POST/PUT/DELETE)
            // This could be made smarter depending on the endpoint
            return next.handle(request);
        }

        // Check if the request should be cached
        const isCacheable = this.cacheableEndpoints.some(endpoint => request.url.includes(endpoint));
        if (!isCacheable || request.headers.has('X-No-Cache')) {
            return next.handle(request);
        }

        // Try to get from cache
        const cachedResponse = this.cacheService.get(request.urlWithParams);
        if (cachedResponse) {
            // Returns a cached response
            return of(cachedResponse);
        }

        // If not in cache, send the request and cache the response
        return next.handle(request).pipe(
            tap(event => {
                if (event instanceof HttpResponse && event.status === 200) {
                    // Cache for 60 seconds (60000ms)
                    this.cacheService.put(request.urlWithParams, event, 60000);
                }
            })
        );
    }
}

import { Injectable } from '@angular/core';
import { HttpInterceptor, HttpRequest, HttpHandler, HttpEvent, HttpErrorResponse } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { OfflineService } from '../services/offline.service';
import { OfflineQueueService, QueuedActionType } from '../services/offline-queue.service';
import { OfflineStorageService } from '../services/offline-storage.service';
import { NotificationService } from '../services/notification.service';

@Injectable()
export class OfflineInterceptor implements HttpInterceptor {
  constructor(
    private offlineService: OfflineService,
    private queueService: OfflineQueueService,
    private storageService: OfflineStorageService,
    private notificationService: NotificationService
  ) {}

  intercept(request: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    if (this.shouldBypassOfflineHandling(request)) {
      return next.handle(request);
    }

    if (!this.offlineService.isOnline()) {
      return this.handleOfflineRequest(request);
    }

    return next.handle(request).pipe(
      catchError((error: HttpErrorResponse) => {
        if (this.isNetworkError(error)) {
          return this.handleOfflineRequest(request);
        }
        return throwError(() => error);
      })
    );
  }

  private shouldBypassOfflineHandling(request: HttpRequest<any>): boolean {
    const bypassUrls = [
      '/api/v1/ping',
      '/api/v1/observability'
    ];

    return bypassUrls.some(url => request.url.includes(url));
  }

  private isNetworkError(error: HttpErrorResponse): boolean {
    return error.status === 0 || 
           error.status === 504 || 
           error.statusText === 'Unknown Error';
  }

  private handleOfflineRequest(request: HttpRequest<any>): Observable<HttpEvent<any>> {
    if (request.method === 'GET') {
      return this.handleOfflineGet(request);
    }

    if (this.canQueueRequest(request)) {
      return this.queueRequest(request);
    }

    this.notificationService.error(
      'Action impossible en mode hors ligne',
      'OK'
    );

    return throwError(() => new HttpErrorResponse({
      error: 'Offline',
      status: 0,
      statusText: 'Offline',
      url: request.url
    }));
  }

  private handleOfflineGet(request: HttpRequest<any>): Observable<HttpEvent<any>> {
    return new Observable(observer => {
      this.storageService.getCachedData(request.url).then(cachedData => {
        if (cachedData) {
          observer.next(cachedData);
          observer.complete();
        } else {
          this.notificationService.warning(
            'Données non disponibles hors ligne'
          );
          observer.error(new HttpErrorResponse({
            error: 'No cached data',
            status: 0,
            statusText: 'Offline',
            url: request.url
          }));
        }
      }).catch(error => {
        observer.error(error);
      });
    });
  }

  private canQueueRequest(request: HttpRequest<any>): boolean {
    if (request.method !== 'POST' && request.method !== 'PUT' && request.method !== 'PATCH') {
      return false;
    }

    const queueableUrls = [
      '/api/v1/messages',
      '/api/v1/dossiers/',
      '/api/v1/appointments'
    ];

    return queueableUrls.some(url => request.url.includes(url));
  }

  private queueRequest(request: HttpRequest<any>): Observable<HttpEvent<any>> {
    return new Observable(observer => {
      const actionType = this.getActionType(request);
      const localId = this.generateLocalId();

      if (!actionType) {
        observer.error(new HttpErrorResponse({
          error: 'Cannot queue this request type',
          status: 0,
          statusText: 'Offline',
          url: request.url
        }));
        return;
      }

      this.queueService.queueAction({
        type: actionType,
        payload: request.body,
        localId
      }).then(() => {
        const mockResponse: any = {
          ...request.body,
          id: localId,
          _isLocal: true,
          _queuedAt: Date.now()
        };

        observer.next(mockResponse as any);
        observer.complete();

        this.notificationService.success(
          'Action enregistrée hors ligne',
          'Voir'
        );
      }).catch(error => {
        observer.error(error);
      });
    });
  }

  private getActionType(request: HttpRequest<any>): QueuedActionType | null {
    const url = request.url;

    if (url.includes('/api/v1/messages') && request.method === 'POST') {
      return QueuedActionType.CREATE_MESSAGE;
    }

    if (url.includes('/api/v1/dossiers') && url.includes('/status') && request.method === 'PATCH') {
      return QueuedActionType.UPDATE_DOSSIER_STATUS;
    }

    if (url.includes('/api/v1/appointments')) {
      if (request.method === 'POST') {
        return QueuedActionType.CREATE_APPOINTMENT;
      }
      if (request.method === 'PUT' || request.method === 'PATCH') {
        return QueuedActionType.UPDATE_APPOINTMENT;
      }
    }

    return null;
  }

  private generateLocalId(): string {
    return `local-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

import { Injectable } from '@angular/core';
import {
  HttpRequest,
  HttpHandler,
  HttpEvent,
  HttpInterceptor,
  HttpErrorResponse
} from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError, retry, timeout } from 'rxjs/operators';
import { RegionRoutingService } from '../services/region-routing.service';

@Injectable()
export class RegionRoutingInterceptor implements HttpInterceptor {
  private readonly REQUEST_TIMEOUT = 30000;
  private readonly MAX_RETRIES = 2;

  constructor(private regionRoutingService: RegionRoutingService) { }

  intercept(request: HttpRequest<unknown>, next: HttpHandler): Observable<HttpEvent<unknown>> {
    if (this.isExternalRequest(request)) {
      return next.handle(request);
    }

    const regionEndpoint = this.regionRoutingService.getApiEndpoint();
    const currentRegion = this.regionRoutingService.getCurrentRegion();

    if (!currentRegion) {
      console.warn('No region selected, using default endpoint');
      return next.handle(request);
    }

    const modifiedRequest = request.clone({
      url: this.buildRegionalUrl(request.url, regionEndpoint),
      setHeaders: {
        'X-Region': currentRegion.name,
        'X-Request-Id': this.generateRequestId()
      }
    });

    const startTime = performance.now();

    return next.handle(modifiedRequest).pipe(
      timeout(this.REQUEST_TIMEOUT),
      retry({
        count: this.MAX_RETRIES,
        delay: (error, retryCount) => {
          if (error instanceof HttpErrorResponse) {
            if (error.status >= 500 || error.status === 0) {
              console.warn(`Retrying request to ${currentRegion.name}, attempt ${retryCount}`);
              return new Observable(subscriber => {
                setTimeout(() => subscriber.next(null as any), 1000 * retryCount);
              });
            }
          }
          throw error;
        }
      }),
      catchError((error: HttpErrorResponse) => {
        const endTime = performance.now();
        const latency = endTime - startTime;

        if (latency > 200) {
          console.warn(`High latency detected: ${latency.toFixed(2)}ms for ${request.url}`);
          this.reportLatency(currentRegion.name, latency);
        }

        if (error.status === 0 || error.status >= 500) {
          console.error(`Region ${currentRegion.name} appears to be down, attempting failover`);
          this.regionRoutingService.switchRegion(this.getNextHealthyRegion(currentRegion.name));
        }

        return throwError(() => error);
      })
    );
  }

  private isExternalRequest(request: HttpRequest<any>): boolean {
    return request.url.startsWith('http://') || request.url.startsWith('https://');
  }

  private buildRegionalUrl(url: string, regionEndpoint: string): string {
    if (url.startsWith('/')) {
      return `${regionEndpoint}${url}`;
    }
    return url;
  }

  private generateRequestId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  private getNextHealthyRegion(currentRegion: string): string {
    const allRegions = this.regionRoutingService.getAllRegions();
    const otherRegions = allRegions.filter(r => r.name !== currentRegion);

    otherRegions.sort((a, b) => a.priority - b.priority);

    return otherRegions.length > 0 ? otherRegions[0].name : currentRegion;
  }

  private reportLatency(region: string, latency: number): void {
    if (typeof navigator !== 'undefined' && 'sendBeacon' in navigator) {
      const data = JSON.stringify({
        metric: 'api_latency',
        region,
        latency,
        timestamp: new Date().toISOString()
      });

      navigator.sendBeacon('/api/metrics/latency', data);
    }
  }
}

