import { Directive, ElementRef, HostListener, Renderer2, OnInit } from '@angular/core';

/**
 * Directive that adds hover animations to buttons
 * Scales to 1.02 and adds shadow-lg on hover
 */
@Directive({ 
    selector: 'button[appAnimatedButton], a[appAnimatedButton]',
    standalone: true
})
export class AnimatedButtonDirective implements OnInit {
  constructor(
    private el: ElementRef,
    private renderer: Renderer2
  ) {}

  ngOnInit(): void {
    this.renderer.setStyle(this.el.nativeElement, 'transition', 'all 150ms cubic-bezier(0.4, 0, 0.2, 1)');
    this.renderer.setStyle(this.el.nativeElement, 'transform-origin', 'center');
  }

  @HostListener('mouseenter')
  onMouseEnter(): void {
    if (!this.el.nativeElement.disabled) {
      this.renderer.setStyle(this.el.nativeElement, 'transform', 'scale(1.02)');
      this.renderer.addClass(this.el.nativeElement, 'shadow-lg');
    }
  }

  @HostListener('mouseleave')
  onMouseLeave(): void {
    this.renderer.setStyle(this.el.nativeElement, 'transform', 'scale(1)');
    this.renderer.removeClass(this.el.nativeElement, 'shadow-lg');
  }

  @HostListener('mousedown')
  onMouseDown(): void {
    if (!this.el.nativeElement.disabled) {
      this.renderer.setStyle(this.el.nativeElement, 'transform', 'scale(0.98)');
    }
  }

  @HostListener('mouseup')
  onMouseUp(): void {
    if (!this.el.nativeElement.disabled) {
      this.renderer.setStyle(this.el.nativeElement, 'transform', 'scale(1.02)');
    }
  }
}

import { Directive, ElementRef, HostListener, Renderer2, OnInit, Input } from '@angular/core';

/**
 * Directive that adds pulse animation to border on focus
 */
@Directive({ selector: 'input[appAnimatedFocus], textarea[appAnimatedFocus], select[appAnimatedFocus], [contenteditable][appAnimatedFocus]' })
export class AnimatedFocusDirective implements OnInit {
  @Input() pulseColor = 'rgba(59, 130, 246, 0.5)';
  @Input() pulseSize = '3px';

  constructor(
    private el: ElementRef,
    private renderer: Renderer2
  ) {}

  ngOnInit(): void {
    this.renderer.setStyle(this.el.nativeElement, 'transition', 'box-shadow 200ms ease-out');
  }

  @HostListener('focus')
  onFocus(): void {
    this.renderer.setStyle(
      this.el.nativeElement,
      'box-shadow',
      `0 0 0 ${this.pulseSize} ${this.pulseColor}`
    );
  }

  @HostListener('blur')
  onBlur(): void {
    this.renderer.setStyle(
      this.el.nativeElement,
      'box-shadow',
      '0 0 0 0 rgba(59, 130, 246, 0)'
    );
  }
}

import { Directive, OnInit, OnDestroy, ElementRef, HostListener, input } from '@angular/core';
import { AbstractControl } from '@angular/forms';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

export interface ContextualHint {
  default: string;
  pristine?: string;
  touched?: string;
  dirty?: string;
  valid?: string;
  invalid?: string;
  focused?: string;
  hasValue?: string;
}

@Directive({
    selector: '[appContextualHint]',
    standalone: true
})
export class ContextualHintDirective implements OnInit, OnDestroy {
  readonly appContextualHint = input.required<ContextualHint | string>();
  readonly hintControl = input<AbstractControl>();
  readonly hintPosition = input<'above' | 'below' | 'left' | 'right'>('above');

  private destroy$ = new Subject<void>();
  private isFocused = false;

  constructor(private elementRef: ElementRef<HTMLInputElement | HTMLTextAreaElement>) {}

  ngOnInit(): void {
    this.updateHintAttributes();

    const hintControl = this.hintControl();
    if (hintControl) {
      hintControl.statusChanges
        .pipe(takeUntil(this.destroy$))
        .subscribe(() => this.updateHintAttributes());

      hintControl.valueChanges
        .pipe(takeUntil(this.destroy$))
        .subscribe(() => this.updateHintAttributes());
    }
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  @HostListener('focus')
  onFocus(): void {
    this.isFocused = true;
    this.updateHintAttributes();
  }

  @HostListener('blur')
  onBlur(): void {
    this.isFocused = false;
    this.updateHintAttributes();
  }

  private updateHintAttributes(): void {
    const message = this.getContextualMessage();
    const nativeElement = this.elementRef.nativeElement;
    nativeElement.setAttribute('title', message);
    nativeElement.setAttribute('aria-description', message);
  }

  private getContextualMessage(): string {
    const appContextualHint = this.appContextualHint();
    if (typeof appContextualHint === 'string') {
      return appContextualHint;
    }

    const hints = appContextualHint;

    const hintControl = this.hintControl();
    if (!hintControl) {
      return hints.default;
    }

    // Priority order for contextual hints
    if (this.isFocused && hints.focused) {
      return hints.focused;
    }

    if (hintControl.invalid && hintControl.touched && hints.invalid) {
      return hints.invalid;
    }

    if (hintControl.valid && hintControl.dirty && hints.valid) {
      return hints.valid;
    }

    if (hintControl.value && hints.hasValue) {
      return hints.hasValue;
    }

    if (hintControl.dirty && hints.dirty) {
      return hints.dirty;
    }

    if (hintControl.touched && hints.touched) {
      return hints.touched;
    }

    if (hintControl.pristine && hints.pristine) {
      return hints.pristine;
    }

    return hints.default;
  }
}

import { Directive, EventEmitter, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { Subject } from 'rxjs';

import type { DashboardWidgetConfig } from '../models/dashboard-layout.model';

/**
 * Logique partagée des widgets du tableau de bord personnalisable.
 * La surface visuelle est `ds-card` dans le template de chaque widget ; ce fichier ne fournit pas de carte Material/HTML maison.
 */
@Directive()
export abstract class DashboardWidgetBase implements OnInit, OnDestroy {
  @Input({ required: true }) config!: DashboardWidgetConfig;
  @Input() editMode = false;
  @Output() remove = new EventEmitter<string>();
  @Output() settingsChange = new EventEmitter<Record<string, unknown>>();
  @Output() refresh = new EventEmitter<void>();

  loading = false;
  error: string | null = null;
  protected destroy$ = new Subject<void>();

  ngOnInit(): void {
    this.loadData();
    this.setupAutoRefresh();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  abstract loadData(): void;

  onRemove(): void {
    this.remove.emit(this.config.id);
  }

  onRefresh(): void {
    this.loadData();
    this.refresh.emit();
  }

  updateSettings(settings: Record<string, unknown>): void {
    const updatedSettings = { ...this.config.settings, ...settings };
    this.settingsChange.emit(updatedSettings);
    this.loadData();
  }

  protected setLoading(loading: boolean): void {
    this.loading = loading;
  }

  protected setError(error: string | null): void {
    this.error = error;
  }

  private setupAutoRefresh(): void {
    const interval = this.config.refreshInterval;
    if (interval != null && interval > 0) {
      setInterval(() => {
        if (!this.editMode) {
          this.loadData();
        }
      }, interval * 1000);
    }
  }
}

import { Directive, ElementRef, AfterViewInit, OnDestroy } from '@angular/core';
import { FocusManagementService } from '../services/focus-management.service';

@Directive({ selector: '[appFocusTrap]' })
export class FocusTrapDirective implements AfterViewInit, OnDestroy {
  private releaseFocusTrap: (() => void) | null = null;

  constructor(
    private elementRef: ElementRef,
    private focusManagementService: FocusManagementService
  ) {}

  ngAfterViewInit(): void {
    this.focusManagementService.saveFocus();
    
    setTimeout(() => {
      this.releaseFocusTrap = this.focusManagementService.trapFocus(
        this.elementRef.nativeElement
      );
    }, 100);
  }

  ngOnDestroy(): void {
    if (this.releaseFocusTrap) {
      this.releaseFocusTrap();
    }
    this.focusManagementService.restoreFocus();
  }
}

import { Directive, ElementRef, Renderer2, OnInit, OnDestroy } from '@angular/core';
import { NgControl } from '@angular/forms';
import { Subscription } from 'rxjs';

@Directive({ 
  selector: '[appFormValidationAnimation]',
  standalone: true
})
export class FormValidationAnimationDirective implements OnInit, OnDestroy {
  private statusChangeSubscription?: Subscription;
  private errorContainer?: HTMLElement;

  constructor(
    private el: ElementRef,
    private renderer: Renderer2,
    private control: NgControl
  ) {}

  ngOnInit(): void {
    if (this.control && this.control.control) {
      this.statusChangeSubscription = this.control.control.statusChanges.subscribe(() => {
        this.updateValidationState();
      });

      const formField = this.findFormField();
      if (formField) {
        this.errorContainer = this.renderer.createElement('div');
        this.renderer.addClass(this.errorContainer, 'validation-error-container');
        this.renderer.setStyle(this.errorContainer, 'overflow', 'hidden');
        this.renderer.setStyle(this.errorContainer, 'transition', 'max-height 300ms cubic-bezier(0.4, 0, 0.2, 1)');
        this.renderer.setStyle(this.errorContainer, 'max-height', '0');
        this.renderer.insertBefore(formField, this.errorContainer, this.el.nativeElement.nextSibling);
      }
    }
  }

  ngOnDestroy(): void {
    this.statusChangeSubscription?.unsubscribe();
    if (this.errorContainer) {
      this.renderer.removeChild(this.errorContainer.parentNode, this.errorContainer);
    }
  }

  private findFormField(): HTMLElement | null {
    let element = this.el.nativeElement;
    while (element && element.parentElement) {
      if (element.parentElement.classList.contains('mat-mdc-form-field') ||
          element.parentElement.classList.contains('form-field')) {
        return element.parentElement;
      }
      element = element.parentElement;
    }
    return null;
  }

  private updateValidationState(): void {
    if (!this.control || !this.control.control || !this.errorContainer) {
      return;
    }

    const control = this.control.control;
    const isInvalid = control.invalid && (control.dirty || control.touched);

    if (isInvalid) {
      this.renderer.addClass(this.el.nativeElement, 'validation-error');
      
      const errorMessage = this.getErrorMessage();
      if (errorMessage) {
        this.errorContainer.innerHTML = `<div class="error-message">${errorMessage}</div>`;
        this.renderer.setStyle(this.errorContainer, 'max-height', `${this.errorContainer.scrollHeight}px`);
        
        setTimeout(() => {
          if (this.errorContainer) {
            this.renderer.setStyle(this.errorContainer, 'max-height', 'none');
          }
        }, 300);
      }
    } else {
      this.renderer.removeClass(this.el.nativeElement, 'validation-error');
      this.renderer.setStyle(this.errorContainer, 'max-height', '0');
      
      setTimeout(() => {
        if (this.errorContainer) {
          this.errorContainer.innerHTML = '';
        }
      }, 300);
    }
  }

  private getErrorMessage(): string {
    if (!this.control || !this.control.control || !this.control.errors) {
      return '';
    }

    const errors = this.control.errors;
    
    if (errors['required']) {
      return 'Ce champ est requis';
    }
    if (errors['email']) {
      return 'Email invalide';
    }
    if (errors['minlength']) {
      return `Minimum ${errors['minlength'].requiredLength} caractères requis`;
    }
    if (errors['maxlength']) {
      return `Maximum ${errors['maxlength'].requiredLength} caractères autorisés`;
    }
    if (errors['pattern']) {
      return 'Format invalide';
    }
    if (errors['min']) {
      return `La valeur minimum est ${errors['min'].min}`;
    }
    if (errors['max']) {
      return `La valeur maximum est ${errors['max'].max}`;
    }

    return 'Champ invalide';
  }
}

import { Directive, ElementRef, OnDestroy, OnInit, input, output } from '@angular/core';

@Directive({
  selector: '[appInfiniteScroll]',
  standalone: true
})
export class InfiniteScrollDirective implements OnInit, OnDestroy {
  readonly scrollThreshold = input(0.8);
  readonly scrollDebounceTime = input(200);
  readonly scrolled = output<void>();

  private intersectionObserver?: IntersectionObserver;
  private scrollTimeout?: any;

  constructor(private el: ElementRef) {}

  ngOnInit(): void {
    this.setupIntersectionObserver();
  }

  ngOnDestroy(): void {
    if (this.intersectionObserver) {
      this.intersectionObserver.disconnect();
    }
    if (this.scrollTimeout) {
      clearTimeout(this.scrollTimeout);
    }
  }

  private setupIntersectionObserver(): void {
    const element = this.el.nativeElement;

    if ('IntersectionObserver' in window) {
      this.intersectionObserver = new IntersectionObserver(
        (entries) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              this.onScroll();
            }
          });
        },
        {
          root: null,
          rootMargin: `${(1 - this.scrollThreshold()) * 100}%`,
          threshold: 0.1
        }
      );

      // Create a sentinel element at the bottom
      const sentinel = document.createElement('div');
      sentinel.className = 'infinite-scroll-sentinel';
      sentinel.style.height = '1px';
      element.appendChild(sentinel);
      this.intersectionObserver.observe(sentinel);
    } else {
      // Fallback to scroll event
      element.addEventListener('scroll', this.handleScroll.bind(this));
    }
  }

  private handleScroll(): void {
    if (this.scrollTimeout) {
      clearTimeout(this.scrollTimeout);
    }

    this.scrollTimeout = setTimeout(() => {
      const element = this.el.nativeElement;
      const scrollTop = element.scrollTop;
      const scrollHeight = element.scrollHeight;
      const clientHeight = element.clientHeight;

      const scrollPosition = (scrollTop + clientHeight) / scrollHeight;

      if (scrollPosition >= this.scrollThreshold()) {
        this.onScroll();
      }
    }, this.scrollDebounceTime());
  }

  private onScroll(): void {
    // The 'emit' function requires a mandatory void argument
    this.scrolled.emit();
  }
}

import { Directive, OnInit, ElementRef, Renderer2, OnDestroy, input } from '@angular/core';
import { KeyboardShortcutService } from '../services/keyboard-shortcut.service';
import { Subscription } from 'rxjs';

@Directive({
    selector: '[appKeyboardShortcutHint]',
    standalone: true
})
export class KeyboardShortcutHintDirective implements OnInit, OnDestroy {
  readonly appKeyboardShortcutHint = input('');

  private hintElement: HTMLElement | null = null;
  private subscription: Subscription | null = null;

  constructor(
    private el: ElementRef,
    private renderer: Renderer2,
    private keyboardShortcutService: KeyboardShortcutService
  ) {}

  ngOnInit(): void {
    this.subscription = this.keyboardShortcutService.preferences$.subscribe(prefs => {
      if (prefs.showShortcutHints && this.appKeyboardShortcutHint()) {
        this.addHint();
      } else {
        this.removeHint();
      }
    });
  }

  ngOnDestroy(): void {
    this.removeHint();
    if (this.subscription) {
      this.subscription.unsubscribe();
    }
  }

  private addHint(): void {
    if (this.hintElement) {
      return;
    }

    this.hintElement = this.renderer.createElement('span');
    this.renderer.addClass(this.hintElement, 'keyboard-hint');

    const text = this.renderer.createText(this.appKeyboardShortcutHint());
    this.renderer.appendChild(this.hintElement, text);

    const hostElement = this.el.nativeElement;
    this.renderer.setStyle(hostElement, 'position', 'relative');
    this.renderer.appendChild(hostElement, this.hintElement);
  }

  private removeHint(): void {
    if (this.hintElement) {
      this.renderer.removeChild(this.el.nativeElement, this.hintElement);
      this.hintElement = null;
    }
  }
}

import { Directive, ElementRef, Input, OnInit, Renderer2 } from '@angular/core';

/**
 * Directive iOS — Large Title pattern (Cupertino HIG).
 * Ajoute la classe `ios-large-title` et gère la transition
 * vers le titre compact à l'usage de `(scroll)`.
 *
 * Usage : <h1 dsLargeTitle [compact]="isScrolled">Titre</h1>
 */
@Directive({
  selector: '[dsLargeTitle]',
  standalone: true,
  host: {
    class: 'ds-ios-large-title',
    '[class.ds-ios-large-title--compact]': 'compact',
  },
})
export class LargeTitleDirective implements OnInit {
  @Input() compact = false;

  constructor(private el: ElementRef, private renderer: Renderer2) {}

  ngOnInit(): void {
    this.renderer.setStyle(this.el.nativeElement, 'font-family', 'var(--ds-font-display)');
    this.renderer.setStyle(this.el.nativeElement, 'font-size', this.compact ? '17px' : '34px');
    this.renderer.setStyle(this.el.nativeElement, 'font-weight', '700');
    this.renderer.setStyle(this.el.nativeElement, 'letter-spacing', this.compact ? '-0.2px' : '-0.5px');
    this.renderer.setStyle(this.el.nativeElement, 'transition', 'font-size 200ms ease, letter-spacing 200ms ease');
  }
}

import { Directive, ElementRef, OnInit, OnDestroy, Renderer2, input } from '@angular/core';

@Directive({ selector: '[appLazyLoadImage]', standalone: true })
export class LazyLoadImageDirective implements OnInit, OnDestroy {
  readonly appLazyLoadImage = input.required<string>();
  readonly placeholder = input('data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300"%3E%3Crect width="400" height="300" fill="%23f0f0f0"/%3E%3C/svg%3E');
  readonly blurUpPlaceholder = input<string>();
  readonly errorImage = input('data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300"%3E%3Crect width="400" height="300" fill="%23e0e0e0"/%3E%3Ctext x="50%25" y="50%25" text-anchor="middle" fill="%23999" font-family="sans-serif" font-size="16"%3EImage non disponible%3C/text%3E%3C/svg%3E');

  private intersectionObserver?: IntersectionObserver;

  constructor(
    private el: ElementRef<HTMLImageElement>,
    private renderer: Renderer2
  ) {}

  ngOnInit(): void {
    this.setupLazyLoading();
  }

  ngOnDestroy(): void {
    if (this.intersectionObserver) {
      this.intersectionObserver.disconnect();
    }
  }

  private setupLazyLoading(): void {
    const img = this.el.nativeElement;

    // Apply blur effect class
    this.renderer.addClass(img, 'lazy-image');
    this.renderer.addClass(img, 'lazy-image-loading');

    // Set placeholder
    const blurUpPlaceholder = this.blurUpPlaceholder();
    if (blurUpPlaceholder) {
      this.renderer.setAttribute(img, 'src', blurUpPlaceholder);
    } else {
      this.renderer.setAttribute(img, 'src', this.placeholder());
    }

    // Setup intersection observer
    if ('IntersectionObserver' in window) {
      this.intersectionObserver = new IntersectionObserver(
        (entries) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              this.loadImage();
              if (this.intersectionObserver) {
                this.intersectionObserver.unobserve(img);
              }
            }
          });
        },
        {
          rootMargin: '50px'
        }
      );

      this.intersectionObserver.observe(img);
    } else {
      // Fallback for browsers that don't support IntersectionObserver
      this.loadImage();
    }
  }

  private loadImage(): void {
    const img = this.el.nativeElement;
    const tempImg = new Image();

    tempImg.onload = () => {
      this.renderer.setAttribute(img, 'src', this.appLazyLoadImage());
      this.renderer.removeClass(img, 'lazy-image-loading');
      this.renderer.addClass(img, 'lazy-image-loaded');
    };

    tempImg.onerror = () => {
      this.renderer.setAttribute(img, 'src', this.errorImage());
      this.renderer.removeClass(img, 'lazy-image-loading');
      this.renderer.addClass(img, 'lazy-image-error');
    };

    tempImg.src = this.appLazyLoadImage();
  }
}

import { Directive, OnInit, OnDestroy } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { Subscription } from 'rxjs';
import { filter } from 'rxjs/operators';
import { NavigationService } from '../services/navigation.service';

@Directive({ selector: '[appMaintainScroll]' })
export class MaintainScrollDirective implements OnInit, OnDestroy {
  private subscription!: Subscription;

  constructor(
    private router: Router,
    private navigationService: NavigationService
  ) {}

  ngOnInit(): void {
    this.subscription = this.router.events.pipe(
      filter(event => event instanceof NavigationEnd)
    ).subscribe(() => {
      this.navigationService.restoreScrollPosition();
    });

    window.addEventListener('beforeunload', () => {
      this.navigationService.saveScrollPosition();
    });
  }

  ngOnDestroy(): void {
    this.navigationService.saveScrollPosition();
    if (this.subscription) {
      this.subscription.unsubscribe();
    }
  }
}

import { Directive, ElementRef, EventEmitter, HostListener, Input, Output, OnDestroy } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import { Haptics, ImpactStyle } from '@capacitor/haptics';

export interface SwipeEvent {
  direction: 'left' | 'right' | 'up' | 'down';
  distance: number;
  velocity: number;
}

export interface PinchEvent {
  scale: number;
  centerX: number;
  centerY: number;
}

/**
 * Directive for mobile gesture handling
 * Provides swipe, long-press, pinch-zoom, and double-tap gestures
 */
@Directive({
  selector: '[appMobileGestures]',
  standalone: true
})
export class MobileGesturesDirective implements OnDestroy {
  @Input() swipeThreshold = 50; // pixels
  @Input() longPressDelay = 500; // ms
  @Input() doubleTapDelay = 300; // ms
  @Input() enableHaptics = true;
  @Input() preventContextMenu = true;

  @Output() swipe = new EventEmitter<SwipeEvent>();
  @Output() swipeLeft = new EventEmitter<SwipeEvent>();
  @Output() swipeRight = new EventEmitter<SwipeEvent>();
  @Output() swipeUp = new EventEmitter<SwipeEvent>();
  @Output() swipeDown = new EventEmitter<SwipeEvent>();
  @Output() longPress = new EventEmitter<TouchEvent>();
  @Output() doubleTap = new EventEmitter<TouchEvent>();
  @Output() pinch = new EventEmitter<PinchEvent>();

  private touchStartX = 0;
  private touchStartY = 0;
  private touchStartTime = 0;
  private lastTapTime = 0;
  private longPressTimer: any;
  private initialPinchDistance = 0;
  private isNative = Capacitor.isNativePlatform();

  constructor(private el: ElementRef) {
    if (this.preventContextMenu) {
      this.el.nativeElement.style.webkitTouchCallout = 'none';
      this.el.nativeElement.style.webkitUserSelect = 'none';
      this.el.nativeElement.style.userSelect = 'none';
    }
  }

  @HostListener('touchstart', ['$event'])
  onTouchStart(event: TouchEvent): void {
    if (event.touches.length === 1) {
      this.handleSingleTouchStart(event);
    } else if (event.touches.length === 2) {
      this.handlePinchStart(event);
    }
  }

  @HostListener('touchmove', ['$event'])
  onTouchMove(event: TouchEvent): void {
    if (event.touches.length === 2) {
      this.handlePinchMove(event);
    } else if (this.longPressTimer) {
      // Cancel long press if finger moves
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }
  }

  @HostListener('touchend', ['$event'])
  onTouchEnd(event: TouchEvent): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }

    if (event.changedTouches.length === 1) {
      this.handleSingleTouchEnd(event);
    }

    this.initialPinchDistance = 0;
  }

  @HostListener('touchcancel')
  onTouchCancel(): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }
    this.initialPinchDistance = 0;
  }

  @HostListener('contextmenu', ['$event'])
  onContextMenu(event: Event): void {
    if (this.preventContextMenu) {
      event.preventDefault();
      return;
    }
  }

  private handleSingleTouchStart(event: TouchEvent): void {
    const touch = event.touches[0];
    this.touchStartX = touch.clientX;
    this.touchStartY = touch.clientY;
    this.touchStartTime = Date.now();

    // Setup long press detection
    this.longPressTimer = setTimeout(() => {
      this.handleLongPress(event);
    }, this.longPressDelay);
  }

  private handleSingleTouchEnd(event: TouchEvent): void {
    const touch = event.changedTouches[0];
    const touchEndX = touch.clientX;
    const touchEndY = touch.clientY;
    const touchEndTime = Date.now();

    const deltaX = touchEndX - this.touchStartX;
    const deltaY = touchEndY - this.touchStartY;
    const deltaTime = touchEndTime - this.touchStartTime;
    const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);

    // Check for swipe
    if (distance > this.swipeThreshold && deltaTime < 1000) {
      this.handleSwipe(deltaX, deltaY, distance, deltaTime);
      return;
    }

    // Check for double tap
    const timeSinceLastTap = touchEndTime - this.lastTapTime;
    if (timeSinceLastTap < this.doubleTapDelay && distance < 10) {
      this.handleDoubleTap(event);
      this.lastTapTime = 0;
    } else {
      this.lastTapTime = touchEndTime;
    }
  }

  private handleSwipe(deltaX: number, deltaY: number, distance: number, deltaTime: number): void {
    const velocity = distance / deltaTime;
    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);

    let direction: 'left' | 'right' | 'up' | 'down';

    if (absX > absY) {
      direction = deltaX > 0 ? 'right' : 'left';
    } else {
      direction = deltaY > 0 ? 'down' : 'up';
    }

    const swipeEvent: SwipeEvent = { direction, distance, velocity };

    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Light });
    }

    this.swipe.emit(swipeEvent);

    switch (direction) {
      case 'left':
        this.swipeLeft.emit(swipeEvent);
        break;
      case 'right':
        this.swipeRight.emit(swipeEvent);
        break;
      case 'up':
        this.swipeUp.emit(swipeEvent);
        break;
      case 'down':
        this.swipeDown.emit(swipeEvent);
        break;
    }
  }

  private handleLongPress(event: TouchEvent): void {
    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Medium });
    }

    this.longPress.emit(event);
    this.longPressTimer = null;
  }

  private handleDoubleTap(event: TouchEvent): void {
    if (this.enableHaptics && this.isNative) {
      Haptics.impact({ style: ImpactStyle.Light });
    }

    this.doubleTap.emit(event);
  }

  private handlePinchStart(event: TouchEvent): void {
    const touch1 = event.touches[0];
    const touch2 = event.touches[1];
    
    this.initialPinchDistance = this.getDistance(
      touch1.clientX, touch1.clientY,
      touch2.clientX, touch2.clientY
    );
  }

  private handlePinchMove(event: TouchEvent): void {
    if (this.initialPinchDistance === 0) {
      return;
    }

    event.preventDefault();

    const touch1 = event.touches[0];
    const touch2 = event.touches[1];
    
    const currentDistance = this.getDistance(
      touch1.clientX, touch1.clientY,
      touch2.clientX, touch2.clientY
    );

    const scale = currentDistance / this.initialPinchDistance;
    const centerX = (touch1.clientX + touch2.clientX) / 2;
    const centerY = (touch1.clientY + touch2.clientY) / 2;

    this.pinch.emit({ scale, centerX, centerY });
  }

  private getDistance(x1: number, y1: number, x2: number, y2: number): number {
    const dx = x2 - x1;
    const dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  ngOnDestroy(): void {
    if (this.longPressTimer) {
      clearTimeout(this.longPressTimer);
    }
  }
}

import { Directive, ElementRef, HostListener, input, output } from '@angular/core';

export interface SwipeEvent {
  direction: 'left' | 'right' | 'up' | 'down';
  deltaX: number;
  deltaY: number;
  target: HTMLElement;
}

@Directive({ selector: '[appSwipeGesture]' })
export class SwipeGestureDirective {
  readonly swipeThreshold = input(50);
  readonly swipeVelocityThreshold = input(0.3);
  readonly enableSwipeLeft = input(true);
  readonly enableSwipeRight = input(true);
  readonly enableSwipeUp = input(false);
  readonly enableSwipeDown = input(false);
  
  readonly swipe = output<SwipeEvent>();
  readonly swipeLeft = output<SwipeEvent>();
  readonly swipeRight = output<SwipeEvent>();
  readonly swipeUp = output<SwipeEvent>();
  readonly swipeDown = output<SwipeEvent>();
  readonly swipeStart = output<TouchEvent>();
  readonly swipeMove = output<{
    progress: number;
    direction: string;
}>();
  readonly swipeCancel = output<void>();

  private startX = 0;
  private startY = 0;
  private startTime = 0;
  private isSwiping = false;
  private currentDirection: 'left' | 'right' | 'up' | 'down' | null = null;

  constructor(private el: ElementRef<HTMLElement>) {}

  @HostListener('touchstart', ['$event'])
  onTouchStart(event: TouchEvent): void {
    this.startX = event.touches[0].clientX;
    this.startY = event.touches[0].clientY;
    this.startTime = Date.now();
    this.isSwiping = true;
    this.currentDirection = null;
    this.swipeStart.emit(event);
  }

  @HostListener('touchmove', ['$event'])
  onTouchMove(event: TouchEvent): void {
    if (!this.isSwiping) return;

    const currentX = event.touches[0].clientX;
    const currentY = event.touches[0].clientY;
    const deltaX = currentX - this.startX;
    const deltaY = currentY - this.startY;

    const absDeltaX = Math.abs(deltaX);
    const absDeltaY = Math.abs(deltaY);

    // Determine direction
    if (absDeltaX > absDeltaY) {
      this.currentDirection = deltaX > 0 ? 'right' : 'left';
      const progress = Math.min(Math.abs(deltaX) / this.swipeThreshold(), 1);
      this.swipeMove.emit({ progress, direction: this.currentDirection });
    } else {
      this.currentDirection = deltaY > 0 ? 'down' : 'up';
      const progress = Math.min(Math.abs(deltaY) / this.swipeThreshold(), 1);
      this.swipeMove.emit({ progress, direction: this.currentDirection });
    }
  }

  @HostListener('touchend', ['$event'])
  onTouchEnd(event: TouchEvent): void {
    if (!this.isSwiping) return;

    const endX = event.changedTouches[0].clientX;
    const endY = event.changedTouches[0].clientY;
    const deltaX = endX - this.startX;
    const deltaY = endY - this.startY;
    const deltaTime = Date.now() - this.startTime;

    const absDeltaX = Math.abs(deltaX);
    const absDeltaY = Math.abs(deltaY);
    const velocity = Math.max(absDeltaX, absDeltaY) / deltaTime;

    // Determine if it's a valid swipe
    if (velocity >= this.swipeVelocityThreshold() || absDeltaX >= this.swipeThreshold() || absDeltaY >= this.swipeThreshold()) {
      if (absDeltaX > absDeltaY) {
        // Horizontal swipe
        if (deltaX > 0 && this.enableSwipeRight()) {
          this.emitSwipe('right', deltaX, deltaY);
        } else if (deltaX < 0 && this.enableSwipeLeft()) {
          this.emitSwipe('left', deltaX, deltaY);
        }
      } else {
        // Vertical swipe
        if (deltaY > 0 && this.enableSwipeDown()) {
          this.emitSwipe('down', deltaX, deltaY);
        } else if (deltaY < 0 && this.enableSwipeUp()) {
          this.emitSwipe('up', deltaX, deltaY);
        }
      }
    } else {
      // TODO: The 'emit' function requires a mandatory void argument
      this.swipeCancel.emit();
    }

    this.isSwiping = false;
    this.currentDirection = null;
  }

  @HostListener('touchcancel')
  onTouchCancel(): void {
    this.isSwiping = false;
    this.currentDirection = null;
    // TODO: The 'emit' function requires a mandatory void argument
    this.swipeCancel.emit();
  }

  private emitSwipe(direction: 'left' | 'right' | 'up' | 'down', deltaX: number, deltaY: number): void {
    const swipeEvent: SwipeEvent = {
      direction,
      deltaX,
      deltaY,
      target: this.el.nativeElement
    };

    this.swipe.emit(swipeEvent);

    switch (direction) {
      case 'left':
        this.swipeLeft.emit(swipeEvent);
        break;
      case 'right':
        this.swipeRight.emit(swipeEvent);
        break;
      case 'up':
        this.swipeUp.emit(swipeEvent);
        break;
      case 'down':
        this.swipeDown.emit(swipeEvent);
        break;
    }
  }
}

