@use '../../styles/variables' as vars;

/* ========================================
   ACTIVITY TIMELINE CONTAINER
   ======================================== */
.activity-timeline-container {
  padding: var(--spacing-5);
}

/* ========================================
   TIMELINE HEADER
   ======================================== */
.timeline-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--spacing-6);
  padding-bottom: var(--spacing-4);
  border-bottom: var(--border-width-2) solid var(--ds-divider);
}

.timeline-header h3 {
  margin: 0;
  font-size: var(--font-size-2xl);
  font-weight: var(--font-weight-semibold);
  color: var(--ds-text);
}



/* ========================================
   LOADING STATE
   ======================================== */
.loading-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-12);
}

.loading-container p {
  margin-top: var(--spacing-4);
  color: var(--ds-text-muted);
  font-size: var(--font-size-base);
}

/* ========================================
   NO ACTIVITIES STATE
   ======================================== */
.no-activities {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-16);
  color: var(--ds-text-faint);
}

.no-activities-icon {
  margin-bottom: var(--spacing-4);
  opacity: 0.4;
  color: var(--ds-text-faint);
  width: 80px;
  height: 80px;
}

.no-activities-icon svg {
  width: 80px;
  height: 80px;
}

.no-activities p {
  margin: 0;
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-medium);
}

/* ========================================
   ENHANCED TIMELINE WITH VERTICAL CONNECTORS
   ======================================== */
.timeline {
  position: relative;
  padding-left: var(--spacing-12);
  padding-top: var(--spacing-2);
  padding-bottom: var(--spacing-2);
}

/* Vertical connector line */
.timeline::before {
  content: '';
  position: absolute;
  left: 20px;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    var(--ds-marine-hl) 5%,
    var(--ds-marine-light) 50%,
    var(--ds-marine-hl) 95%,
    transparent 100%
  );
  border-radius: var(--radius-full);
}

/* ========================================
   TIMELINE ITEMS
   ======================================== */
.timeline-item {
  position: relative;
  margin-bottom: var(--spacing-6);
  animation: slideInTimeline var(--duration-moderate) var(--ease-out);
}

@keyframes slideInTimeline {
  from {
    opacity: 0;
    transform: translateX(-24px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.timeline-item:last-child {
  margin-bottom: 0;
}

/* Enhanced timeline marker with icons */
.timeline-marker {
  position: absolute;
  left: -48px;
  top: 16px;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ds-surface);
  box-shadow: var(--shadow-md);
  border: 3px solid var(--ds-marine-hl);
  z-index: var(--z-above);
  transition: all var(--duration-moderate) var(--ease-out);
}

.timeline-item:hover .timeline-marker {
  box-shadow: var(--shadow-lg);
  transform: scale(1.1);
  border-color: var(--ds-marine-light);
}

.timeline-marker .activity-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition-transform);
}

.timeline-item:hover .timeline-marker .activity-badge {
  transform: scale(1.1);
}

/* Icon colors based on activity type */
.activity-badge.activity-note {
  color: var(--ds-marine);
}

.activity-badge.activity-status {
  color: var(--ds-warning);
}

.activity-badge.activity-appointment {
  color: var(--ds-success);
}

.activity-badge.activity-message {
  color: var(--ds-primary);
}

.activity-badge.activity-system {
  color: var(--ds-text-muted);
}

.activity-badge.activity-consent {
  color: var(--ds-marine);
}

/* ========================================
   ACTIVITY CARD
   ======================================== */
.activity-card {
  display: block;
  margin-left: var(--spacing-5);
}

.activity-card > .ds-card {
  border-radius: var(--radius-xl);
  overflow: hidden;
  transition: all var(--duration-moderate) var(--ease-out);
  border-left: 4px solid transparent;
}

.activity-card:hover > .ds-card {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-left-color: var(--ds-marine);
}

/* Border color based on activity type */
.timeline-item:has(.activity-badge.activity-note) .activity-card > .ds-card {
  border-left-color: var(--ds-marine-hl);
}

.timeline-item:has(.activity-badge.activity-status) .activity-card > .ds-card {
  border-left-color: var(--ds-warning-hl);
}

.timeline-item:has(.activity-badge.activity-appointment) .activity-card > .ds-card {
  border-left-color: var(--ds-success-hl);
}

.timeline-item:has(.activity-badge.activity-message) .activity-card > .ds-card {
  border-left-color: var(--ds-primary-hl);
}

/* ========================================
   ACTIVITY CARD HEADER
   ======================================== */
.activity-card-header {
  display: flex;
  padding: var(--spacing-4);
  background: linear-gradient(135deg, var(--ds-surface-2), var(--ds-bg));
  border-bottom: var(--border-width-1) solid var(--ds-divider);
  align-items: flex-start;
}

.activity-card-body {
  padding: var(--spacing-4);
}

.avatar-container {
  margin-right: var(--spacing-3);
  flex-shrink: 0;
}

.user-avatar {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: linear-gradient(135deg, var(--ds-marine), var(--ds-marine-hover));
  color: var(--ds-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
  text-transform: uppercase;
  box-shadow: var(--shadow-sm);
  border: 2px solid var(--ds-surface);
}

.activity-header-content {
  flex: 1;
  min-width: 0;
}

.activity-header-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--spacing-2);
  margin-bottom: var(--spacing-2);
}

.activity-title-row {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);
  flex-wrap: wrap;
}

.activity-type {
  font-weight: var(--font-weight-semibold);
  font-size: var(--font-size-lg);
  color: var(--ds-text);
}

.actions-menu-button {
  flex-shrink: 0;
  margin: calc(-1 * var(--spacing-2)) calc(-1 * var(--spacing-2)) 0 0;
  opacity: 0.7;
  transition: opacity var(--duration-fast) var(--ease-out);
}

.actions-menu-button:hover {
  opacity: 1;
}

.actions-menu-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--ds-border);
  border-radius: var(--radius-sm);
  background: transparent;
  padding: var(--spacing-1);
  cursor: pointer;
  color: var(--ds-text-muted);
}

.actions-menu-trigger:focus-visible {
  outline: 2px solid var(--ds-marine);
  outline-offset: 2px;
}

.activity-meta {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
  font-size: var(--font-size-sm);
  color: var(--ds-text-muted);
}

.activity-author {
  font-weight: var(--font-weight-medium);
  color: var(--ds-text-muted);
}

.meta-separator {
  color: var(--ds-text-faint);
}

.activity-time {
  color: var(--ds-text-faint);
}

/* ========================================
   ACTIVITY CARD CONTENT
   ======================================== */
.activity-content {
  line-height: var(--line-height-relaxed);
  color: var(--ds-text);
  font-size: var(--font-size-base);
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.activity-content ::ng-deep p {
  margin: 0 0 var(--spacing-3) 0;
}

.activity-content ::ng-deep p:last-child {
  margin-bottom: 0;
}

.expand-button {
  margin-top: var(--spacing-3);
  color: var(--ds-marine);
}

.expand-button ds-icon {
  margin-right: var(--spacing-1);
}

/* ========================================
   VISIBILITY BADGE
   ======================================== */
.visibility-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-1);
  padding: var(--spacing-1) var(--spacing-3);
  border-radius: var(--radius-full);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border: var(--border-width-1) solid transparent;
}

.visibility-badge .badge-icon {
  flex-shrink: 0;
}

.visibility-badge.visibility-internal {
  background-color: var(--ds-marine-hl);
  color: var(--ds-marine-light);
  border-color: var(--ds-marine-hl);
}

.visibility-badge.visibility-internal .badge-icon {
  color: inherit;
}

.visibility-badge.visibility-client {
  background-color: var(--ds-warning-hl);
  color: var(--ds-warning);
  border-color: var(--ds-warning-hl);
}

.visibility-badge.visibility-client .badge-icon {
  color: inherit;
}

.menu-item-icon {
  flex-shrink: 0;
  margin-right: var(--spacing-2);
  vertical-align: middle;
}

.menu-item-icon--warn {
  color: var(--ds-error);
}

.tl-note-menu-origin {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

.tl-note-menu-dropdown {
  min-width: 200px;
  background: var(--ds-surface-elevated);
  color: var(--ds-text-primary);
  border-radius: var(--ds-radius-lg, var(--radius-lg));
  box-shadow: var(--ds-shadow-lg);
  border: 1px solid var(--ds-border-subtle);
  overflow: hidden;
}

.tl-note-menu-item {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
  width: 100%;
  margin: 0;
  padding: var(--spacing-3) var(--spacing-4);
  border: none;
  background: transparent;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--ds-text-primary);
  transition: background-color var(--duration-fast) var(--ease-out);
}

.tl-note-menu-item:hover {
  background: var(--ds-primary-subtle);
}

.tl-note-menu-item:focus-visible {
  outline: 2px solid var(--ds-marine);
  outline-offset: -2px;
}

.tl-note-menu-item .menu-item-icon {
  margin-right: 0;
}

/* ========================================
   RESPONSIVE LAYOUT - MOBILE
   ======================================== */
@media (max-width: 768px) {
  .activity-timeline-container {
    padding: var(--spacing-4);
  }

  .timeline-header {
    flex-direction: column;
    align-items: stretch;
    gap: var(--spacing-3);
  }

  .timeline-header h3 {
    font-size: var(--font-size-xl);
  }

  .timeline {
    padding-left: var(--spacing-10);
  }

  .timeline::before {
    left: 16px;
    width: 2px;
  }

  .timeline-marker {
    left: -40px;
    width: 36px;
    height: 36px;
  }

  .timeline-marker mat-icon {
    font-size: 20px;
    width: 20px;
    height: 20px;
  }

  .activity-card {
    margin-left: var(--spacing-3);
  }

  .user-avatar {
    width: 40px;
    height: 40px;
    font-size: var(--font-size-base);
  }

  .activity-header-top {
    flex-direction: column;
    gap: var(--spacing-2);
  }

  .activity-title-row {
    width: 100%;
  }

  .actions-menu-button {
    align-self: flex-end;
    margin: 0;
  }

  .activity-type {
    font-size: var(--font-size-base);
  }

  .activity-meta {
    flex-wrap: wrap;
  }
}

@media (max-width: 576px) {
  .activity-timeline-container {
    padding: var(--spacing-3);
  }

  .timeline-header h3 {
    font-size: var(--font-size-lg);
  }

  .timeline {
    padding-left: var(--spacing-8);
  }

  .timeline::before {
    left: 12px;
  }

  .timeline-marker {
    left: -32px;
    width: 28px;
    height: 28px;
    border-width: 2px;
  }

  .activity-card {
    margin-left: var(--spacing-2);
  }

  .user-avatar {
    width: 36px;
    height: 36px;
    font-size: var(--font-size-sm);
  }

  .avatar-container {
    margin-right: var(--spacing-2);
  }

  .activity-card-header,
  .activity-card-body {
    padding: var(--spacing-3);
  }

  .activity-type {
    font-size: var(--font-size-sm);
  }

  .activity-content {
    font-size: var(--font-size-sm);
  }

  .activity-title-row {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-2);
  }
}

/* ========================================
   ANIMATION FOR SMOOTH TRANSITIONS
   ======================================== */
.timeline-item {
  transition: all var(--duration-moderate) var(--ease-out);
}

/* Stagger animation for multiple items */
.timeline-item:nth-child(1) { animation-delay: 0ms; }
.timeline-item:nth-child(2) { animation-delay: 50ms; }
.timeline-item:nth-child(3) { animation-delay: 100ms; }
.timeline-item:nth-child(4) { animation-delay: 150ms; }
.timeline-item:nth-child(5) { animation-delay: 200ms; }
.timeline-item:nth-child(n+6) { animation-delay: 250ms; }

