/* ── FAB button ───────────────────────────────────────── */
.ai-panel-fab {
  position: fixed;
  bottom: 24px;
  right: 24px;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--ds-marine), var(--ds-primary));
  color: var(--ds-text-inverse);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 8000;
  box-shadow: 0 4px 20px color-mix(in srgb, var(--ds-marine) 40%, transparent);
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1),
              box-shadow 0.2s ease;
  animation: fabIn 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.ai-panel-fab:hover {
  transform: scale(1.1);
  box-shadow: 0 6px 28px color-mix(in srgb, var(--ds-marine) 55%, transparent);
}
.ai-panel-fab mat-icon {
  font-size: 24px;
  width: 24px;
  height: 24px;
  animation: rotateStar 8s linear infinite;
}
@keyframes fabIn {
  from { transform: scale(0) rotate(-90deg); opacity: 0; }
  to   { transform: scale(1) rotate(0deg);   opacity: 1; }
}
@keyframes rotateStar {
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* ── Panel ────────────────────────────────────────────── */
.ai-panel {
  position: fixed;
  bottom: 24px;
  right: 24px;
  width: 380px;
  max-width: calc(100vw - 32px);
  max-height: 560px;
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  z-index: 8001;
  overflow: hidden;
  animation: panelIn 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  border: 1px solid rgba(255,255,255,0.15);
}
@keyframes panelIn {
  from { transform: translateY(20px) scale(0.95); opacity: 0; }
  to   { transform: translateY(0)    scale(1);    opacity: 1; }
}

/* ── Header ───────────────────────────────────────────── */
.ai-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 8px 12px 16px;
  background: linear-gradient(135deg, var(--ds-marine-hl), var(--ds-primary-hl));
  border-bottom: 1px solid rgba(255,255,255,0.1);
  flex-shrink: 0;
}
.ai-panel-title-group {
  display: flex;
  align-items: center;
  gap: 10px;
}
.ai-panel-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--ds-marine), var(--ds-primary));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ds-text-inverse);
  flex-shrink: 0;
}
.ai-panel-avatar mat-icon {
  font-size: 18px;
  width: 18px;
  height: 18px;
}
.ai-panel-title {
  font-family: 'Urbanist', sans-serif;
  font-size: 0.9375rem;
  font-weight: 700;
  color: var(--ds-text);
  line-height: 1.2;
}
.ai-panel-status {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.6875rem;
  color: var(--ds-text-muted);
}
.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ds-success);
  animation: pulse 2s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}
.ai-panel-actions {
  display: flex;
  gap: 2px;
}

/* ── Welcome ──────────────────────────────────────────── */
.ai-panel-welcome {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px 20px;
  text-align: center;
  gap: 8px;
}
.welcome-icon mat-icon {
  font-size: 40px;
  width: 40px;
  height: 40px;
  color: var(--ds-primary);
  opacity: 0.85;
}
.welcome-title {
  font-family: 'Urbanist', sans-serif;
  font-size: 1rem;
  font-weight: 700;
  color: var(--ds-text);
  margin: 4px 0 0;
}
.welcome-text {
  font-size: 0.8125rem;
  color: var(--ds-text-muted);
  line-height: 1.5;
  margin: 0 0 8px;
}
.welcome-examples {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
}
.example-chip {
  border: 1px solid color-mix(in srgb, var(--ds-primary) 25%, transparent);
  background: color-mix(in srgb, var(--ds-primary) 6%, transparent);
  color: var(--ds-primary);
  padding: 5px 12px;
  border-radius: 999px;
  font-size: 0.75rem;
  cursor: pointer;
  font-family: 'Urbanist', sans-serif;
  transition: all 0.15s ease;
}
.example-chip:hover {
  background: color-mix(in srgb, var(--ds-primary) 14%, transparent);
  transform: translateY(-1px);
}

/* ── Conversation ─────────────────────────────────────── */
.ai-panel-conversation {
  flex: 1;
  overflow-y: auto;
  padding: 16px 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  scroll-behavior: smooth;
}
.ai-panel-conversation::-webkit-scrollbar {
  width: 4px;
}
.ai-panel-conversation::-webkit-scrollbar-thumb {
  background: rgba(0,0,0,0.12);
  border-radius: 4px;
}
.message-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.user-row {
  align-items: flex-end;
}
.agent-row {
  align-items: flex-start;
}
.agent-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--ds-marine), var(--ds-primary));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ds-text-inverse);
  flex-shrink: 0;
  margin-bottom: 2px;
}
.agent-avatar mat-icon {
  font-size: 14px;
  width: 14px;
  height: 14px;
}
.message-bubble {
  max-width: 85%;
  padding: 10px 14px;
  border-radius: 14px;
  font-size: 0.8125rem;
  line-height: 1.5;
  word-break: break-word;
}
.user-bubble {
  background: linear-gradient(135deg, var(--ds-marine), var(--ds-primary));
  color: var(--ds-text-inverse);
  border-bottom-right-radius: 4px;
}
.agent-bubble {
  background: var(--ds-surface-dynamic);
  color: var(--ds-text);
  border-bottom-left-radius: 4px;
}

/* ── Typing indicator ─────────────────────────────────── */
.typing-bubble {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 10px 14px;
  background: var(--ds-surface-dynamic);
  border-radius: 14px;
  border-bottom-left-radius: 4px;
}
.typing-bubble span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ds-text-faint);
  animation: typingBounce 1.2s ease-in-out infinite;
}
.typing-bubble span:nth-child(2) { animation-delay: 0.2s; }
.typing-bubble span:nth-child(3) { animation-delay: 0.4s; }
@keyframes typingBounce {
  0%, 60%, 100% { transform: translateY(0); }
  30% { transform: translateY(-6px); }
}

/* ── Action chips ─────────────────────────────────────── */
.action-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  max-width: 90%;
}
.action-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px 4px 7px;
  border: 1px solid color-mix(in srgb, var(--ds-marine) 20%, transparent);
  background: color-mix(in srgb, var(--ds-marine) 6%, transparent);
  color: var(--ds-marine);
  border-radius: 999px;
  font-size: 0.7rem;
  cursor: pointer;
  font-family: 'Urbanist', sans-serif;
  font-weight: 500;
  transition: all 0.15s ease;
}
.action-chip:hover {
  background: color-mix(in srgb, var(--ds-marine) 14%, transparent);
  transform: translateY(-1px);
}
.action-chip mat-icon {
  font-size: 14px;
  width: 14px;
  height: 14px;
}

/* ── Input ────────────────────────────────────────────── */
.ai-panel-input {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding: 10px 12px;
  border-top: 1px solid var(--ds-divider);
  flex-shrink: 0;
}
.ai-input {
  flex: 1;
  border: none;
  outline: none;
  resize: none;
  background: transparent;
  font-family: 'Urbanist', sans-serif;
  font-size: 0.875rem;
  color: var(--ds-text);
  line-height: 1.4;
  max-height: 96px;
  overflow-y: auto;
}
.ai-input::placeholder {
  color: var(--ds-text-faint);
  font-size: 0.8125rem;
}
.send-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: var(--ds-divider);
  color: var(--ds-text-faint);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: not-allowed;
  transition: all 0.2s ease;
  flex-shrink: 0;
}
.send-btn.active {
  background: linear-gradient(135deg, var(--ds-marine), var(--ds-primary));
  color: var(--ds-text-inverse);
  cursor: pointer;
  box-shadow: 0 2px 10px color-mix(in srgb, var(--ds-primary) 30%, transparent);
}
.send-btn.active:hover {
  transform: scale(1.08);
}
.send-btn mat-icon {
  font-size: 18px;
  width: 18px;
  height: 18px;
}

/* ── Hint ─────────────────────────────────────────────── */
.ai-panel-hint {
  text-align: center;
  font-size: 0.6875rem;
  color: var(--ds-text-faint);
  padding: 4px 0 8px;
  flex-shrink: 0;
}
.ai-panel-hint kbd {
  background: var(--ds-divider);
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 0.625rem;
}

/* ── Dark theme ───────────────────────────────────────── */
:host-context(.dark-theme) .ai-panel-title { color: #f0f0f0; }
:host-context(.dark-theme) .ai-panel-header {
  border-bottom-color: rgba(255,255,255,0.06);
}
:host-context(.dark-theme) .agent-bubble {
  background: rgba(255,255,255,0.07);
  color: #e0e0e0;
}
:host-context(.dark-theme) .typing-bubble {
  background: rgba(255,255,255,0.07);
}
