  border-top-color: rgba(255,255,255,0.08);
}
:host-context(.dark-theme) .welcome-title { color: #f0f0f0; }

/* ── Mobile ───────────────────────────────────────────── */
@media (max-width: 480px) {
  .ai-panel {
