@use '../../../styles/variables' as vars;

.page-container {
  padding: var(--spacing-6);
  max-width: 1200px;
  margin: 0 auto;
}

.page-header {
  margin-bottom: var(--spacing-6);
}

.page-title {
  font-size: var(--font-size-3xl);
  font-weight: var(--font-weight-bold);
  color: var(--ds-text);
  margin: 0;
}

.page-content {
  background: var(--ds-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  padding: var(--spacing-8);
}

.error-alert {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);
  padding: var(--spacing-4);
  background-color: var(--ds-error-hl);
  border: 1px solid var(--ds-error);
  border-radius: var(--radius-md);
  color: var(--ds-error);
  margin-bottom: var(--spacing-6);
  font-size: var(--font-size-sm);
}

.error-icon {
  font-size: var(--font-size-xl);
  color: var(--ds-error);
}

/* ========================================
   MAT-STEPPER STYLING
   ======================================== */

::ng-deep .annonce-stepper {
  background: transparent;
}

::ng-deep .annonce-stepper .mat-stepper-horizontal {
  background: transparent;
}

::ng-deep .annonce-stepper .mat-horizontal-stepper-header-container {
  margin-bottom: var(--spacing-8);
  padding: var(--spacing-4);
  background: var(--ds-surface-2);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

::ng-deep .annonce-stepper .mat-step-header {
  padding: var(--spacing-4);
  border-radius: var(--radius-md);
  transition: var(--transition-base);
}

::ng-deep .annonce-stepper .mat-step-header:hover {
  background: color-mix(in oklab, var(--ds-marine) 10%, transparent);
}

::ng-deep .annonce-stepper .mat-step-header.cdk-keyboard-focused,
::ng-deep .annonce-stepper .mat-step-header.cdk-program-focused {
  background: color-mix(in oklab, var(--ds-marine) 20%, transparent);
}

::ng-deep .annonce-stepper .mat-step-header .mat-step-icon {
  background-color: var(--ds-text-faint);
  color: var(--ds-surface);
  width: 32px;
  height: 32px;
  margin-right: var(--spacing-2);
}

::ng-deep .annonce-stepper .mat-step-header .mat-step-icon-selected {
  background-color: var(--ds-marine);
  color: var(--ds-surface);
}

::ng-deep .annonce-stepper .mat-step-header .mat-step-icon-state-done {
  background-color: var(--ds-success);
  color: var(--ds-surface);
}

::ng-deep .annonce-stepper .mat-step-header .mat-step-icon-state-edit {
  background-color: var(--ds-marine);
  color: var(--ds-surface);
}

::ng-deep .annonce-stepper .mat-step-header .mat-step-icon-state-error {
  background-color: var(--ds-error);
  color: var(--ds-surface);
}

::ng-deep .annonce-stepper .mat-step-label {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  color: var(--ds-text-muted);
  white-space: nowrap;
  overflow: visible !important;
  text-overflow: unset !important;
}

::ng-deep .annonce-stepper .mat-step-label-selected {
  color: var(--ds-marine-hover);
  font-weight: var(--font-weight-semibold);
}

::ng-deep .annonce-stepper .mat-stepper-horizontal-line {
  border-top-color: var(--ds-border);
  border-top-width: 2px;
  margin: 0 var(--spacing-2);
}

.step-label {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
}

.step-icon {
  font-size: 18px;
  width: 18px;
  height: 18px;
}

.step-form {
  padding: var(--spacing-6) var(--spacing-4);
  animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.step-title {
  font-size: var(--font-size-2xl);
  font-weight: var(--font-weight-semibold);
  color: var(--ds-text);
  margin-bottom: var(--spacing-6);
  padding-bottom: var(--spacing-3);
  border-bottom: 2px solid var(--ds-marine-hl);
}

/* ========================================
   FORM FIELDS WITH MATERIAL
   ======================================== */

::ng-deep .step-form .mat-form-field {
  display: block;
  margin-bottom: var(--spacing-4);
}

::ng-deep .step-form .mat-form-field.full-width {
  width: 100%;
}

::ng-deep .step-form .mat-form-field.half-width {
  width: calc(50% - var(--spacing-2));
}

::ng-deep .step-form .mat-form-field.full-grid-width {
  grid-column: 1 / -1;
  width: 100%;
}

.form-row {
  display: flex;
  flex-wrap: wrap;
  /* Allow wrapping for better responsive behavior */
  gap: var(--spacing-4);
  margin-bottom: var(--spacing-4);
}

::ng-deep .mat-form-field-appearance-outline .mat-form-field-outline {
  color: var(--ds-border);
}

::ng-deep .mat-form-field-appearance-outline .mat-form-field-outline-thick {
  color: var(--ds-marine);
}

::ng-deep .mat-form-field-appearance-outline.mat-focused .mat-form-field-outline-thick {
  color: var(--ds-marine);
  box-shadow: 0 0 0 2px color-mix(in oklab, var(--ds-marine) 20%, transparent);
}

::ng-deep .mat-form-field-appearance-outline.mat-form-field-invalid .mat-form-field-outline-thick {
  color: var(--ds-error);
}

::ng-deep .mat-form-field-appearance-outline .mat-form-field-label {
  color: var(--ds-text-muted);
}

::ng-deep .mat-form-field-appearance-outline.mat-focused .mat-form-field-label {
  color: var(--ds-marine);
}

::ng-deep .mat-form-field-appearance-outline.mat-form-field-invalid .mat-form-field-label {
  color: var(--ds-error);
}

::ng-deep .mat-error {
  font-size: var(--font-size-xs);
  color: var(--ds-error);
  margin-top: var(--spacing-1);
}

::ng-deep .mat-hint {
  font-size: var(--font-size-xs);
  color: var(--ds-text-muted);
  margin-top: var(--spacing-1);
}

.required {
  color: var(--ds-error);
}

/* ========================================
   PHOTOS SECTION
   ======================================== */

.photos-section {
  margin-bottom: var(--spacing-6);
}

.drag-drop-zone {
  border: 2px dashed var(--ds-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-8);
  text-align: center;
  background: var(--ds-surface-2);
  transition: var(--transition-base);
  cursor: pointer;
  margin-bottom: var(--spacing-6);
}

.drag-drop-zone:hover {
  border-color: var(--ds-marine-light);
  background: color-mix(in oklab, var(--ds-marine) 10%, transparent);
}

.drag-drop-zone.drag-active {
  border-color: var(--ds-marine);
  background: color-mix(in oklab, var(--ds-marine) 20%, transparent);
  border-style: solid;
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--ds-marine) 10%, transparent);
}

.upload-icon {
  font-size: 64px;
  width: 64px;
  height: 64px;
  color: var(--ds-marine-light);
  margin: 0 auto var(--spacing-4);
}

.upload-text {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-medium);
  color: var(--ds-text-muted);
  margin-bottom: var(--spacing-2);
}

.upload-subtext {
  font-size: var(--font-size-sm);
  color: var(--ds-text-muted);
}

.add-photo-section {
  margin-bottom: var(--spacing-6);
}

.empty-photos {
  text-align: center;
  padding: var(--spacing-8);
  background: var(--ds-surface-2);
  border-radius: var(--radius-lg);
  border: 1px solid var(--ds-divider);
}

.empty-icon {
  font-size: 72px;
  width: 72px;
  height: 72px;
  color: var(--ds-text-faint);
  margin: 0 auto var(--spacing-4);
}

.empty-title {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-medium);
  color: var(--ds-text-muted);
  margin-bottom: var(--spacing-2);
}

.empty-subtitle {
  font-size: var(--font-size-sm);
  color: var(--ds-text-muted);
}

/* ========================================
   PHOTO THUMBNAILS GRID WITH DRAG-DROP
   ======================================== */

.photos-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--spacing-4);
  margin-top: var(--spacing-4);
}

.photo-item {
  position: relative;
  cursor: move;
  transition: var(--transition-base);
}

.photo-item:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.photo-drag-placeholder {
  background: color-mix(in oklab, var(--ds-marine) 10%, transparent);
  border: 2px dashed var(--ds-marine-light);
  border-radius: var(--radius-lg);
  min-height: 200px;
}

.photo-thumbnail-wrapper {
  background: var(--ds-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: var(--transition-base);
}

.photo-thumbnail {
  position: relative;
  width: 100%;
  padding-top: 100%;
  background: var(--ds-bg);
  overflow: hidden;
}

.photo-preview {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: var(--transition-base);
}

.photo-item:hover .photo-preview {
  transform: scale(1.05);
}

.photo-error-placeholder {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: var(--ds-error-hl);
  color: var(--ds-error);
  font-size: var(--font-size-sm);
  gap: var(--spacing-2);
}

.photo-error-placeholder mat-icon {
  font-size: 48px;
  width: 48px;
  height: 48px;
}

.photo-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: var(--transition-base);
}

.photo-thumbnail:hover .photo-overlay {
  opacity: 1;
}

.btn-delete-photo {
  background: var(--ds-error);
  color: var(--ds-surface);
}

.btn-delete-photo:hover {
  background: var(--ds-error);
}

.photo-index {
  padding: var(--spacing-2) var(--spacing-3);
  text-align: center;
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
  color: var(--ds-text-muted);
  background: var(--ds-surface-2);
  border-top: 1px solid var(--ds-divider);
}

/* ========================================
   JSON EDITOR
   ======================================== */

.json-editor-controls {
  margin-bottom: var(--spacing-4);
}

::ng-deep .json-field .mat-form-field-wrapper {
  padding-bottom: 0;
}

.json-editor {
  font-family: 'Courier New', Consolas, monospace;
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
  resize: vertical;
}

/* ========================================
   STEP ACTIONS
   ======================================== */

.step-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-4);
  margin-top: var(--spacing-8);
  padding-top: var(--spacing-6);
  border-top: 1px solid var(--ds-divider);
}

.btn-cancel,
.btn-back {
  padding: var(--spacing-2) var(--spacing-6);
}

.btn-next,
.btn-submit {
  padding: var(--spacing-2) var(--spacing-6);
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
}

.btn-loading {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
}

::ng-deep .btn-spinner {
  display: inline-block;
}

::ng-deep .btn-spinner .mat-progress-spinner circle {
  stroke: currentColor;
}

/* ========================================
   MATERIAL BUTTON OVERRIDES
   ======================================== */

::ng-deep .mat-raised-button {
  box-shadow: var(--shadow-md);
  transition: var(--transition-base);
}

::ng-deep .mat-raised-button:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

::ng-deep .mat-raised-button:active {
  box-shadow: var(--shadow-sm);
  transform: translateY(0);
}

::ng-deep .mat-stroked-button {
  border-width: 2px;
  transition: var(--transition-base);
}

::ng-deep .mat-stroked-button:hover {
  background: var(--ds-surface-2);
}

/* ========================================
   RESPONSIVE DESIGN
   ======================================== */

@media (max-width: 768px) {
  .page-container {
    padding: var(--spacing-4);
  }

  .page-content {
    padding: var(--spacing-4);
  }

  .step-form {
    padding: var(--spacing-4) var(--spacing-2);
  }

  .form-row {
    flex-direction: column;
  }

  ::ng-deep .step-form .mat-form-field.half-width {
    width: 100%;
  }

  .photos-grid {
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: var(--spacing-3);
  }

  .step-actions {
    flex-direction: column;
  }

  .step-actions button {
    width: 100%;
  }

  ::ng-deep .annonce-stepper .mat-horizontal-stepper-header-container {
    padding: var(--spacing-2);
  }

  ::ng-deep .annonce-stepper .mat-step-header {
    padding: var(--spacing-2);
  }

  .step-label {
    font-size: var(--font-size-xs);
  }

  .step-icon {
    font-size: 16px;
    width: 16px;
    height: 16px;
  }
}

@media (max-width: 576px) {
  .page-title {
    font-size: var(--font-size-xl);
  }

  .step-title {
    font-size: var(--font-size-lg);
  }

  .photos-grid {
    grid-template-columns: 1fr;
  }

  ::ng-deep .annonce-stepper .mat-step-header .mat-step-icon {
    width: 28px;
    height: 28px;
  }
}

