/* ====================================================================
   ATLASIA DS — Annonce Detail (Phase 5)
   100% tokens --ds-*, CSS plat (sans nesting SCSS).
   ==================================================================== */

.ad-detail-page {
  max-width: var(--ds-content-md, 900px);
  margin: 0 auto;
  padding: var(--ds-space-5) var(--ds-space-6) var(--ds-space-12);
}

/* ── En-tête ─────────────────────────────────────────────────────── */
.ad-detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--ds-space-6);
  flex-wrap: wrap;
  gap: var(--ds-space-3);
}

.ad-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 0;
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--ds-text-muted);
  transition: color var(--ds-transition-fast);
}
.ad-back-btn:hover { color: var(--ds-marine); }
.ad-back-btn:focus-visible {
  outline: 2px solid var(--ds-marine);
  outline-offset: 4px;
  border-radius: 4px;
}

.ad-detail-header__actions { display: flex; gap: var(--ds-space-2); }

/* ── Skeleton ────────────────────────────────────────────────────── */
.ad-detail-skeleton { display: flex; flex-direction: column; gap: var(--ds-space-3); }

/* ── Titre + statut ──────────────────────────────────────────────── */
.ad-detail-title-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--ds-space-4);
  margin-bottom: var(--ds-space-7);
  flex-wrap: wrap;
}

.ad-detail-title {
  font-family: var(--ds-font-display, var(--ds-font-body));
  font-size: 22px;
  font-weight: 700;
  color: var(--ds-text);
  margin: 0 0 4px;
  letter-spacing: -0.3px;
  line-height: 1.25;
}

.ad-detail-meta {
  font-size: 13.5px;
  color: var(--ds-text-muted);
  margin: 0;
  display: flex;
  gap: 6px;
  align-items: center;
  flex-wrap: wrap;
}
.ad-sep { opacity: 0.4; }

/* ── Grille d'infos ──────────────────────────────────────────────── */
.ad-detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--ds-space-3);
  margin-bottom: var(--ds-space-5);
}

.ad-info-card {
  padding: var(--ds-space-4) var(--ds-space-5);
}

.ad-card-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--ds-text-faint);
  margin-bottom: 4px;
}

.ad-card-value {
  font-size: 14px;
  font-weight: 500;
  color: var(--ds-text);
}
.ad-card-value.ad-card-value--price {
  font-size: 18px;
  font-weight: 700;
  color: var(--ds-marine);
}

/* ── Description / Photos ────────────────────────────────────────── */
.ad-description-card,
.ad-photos-card {
  padding: var(--ds-space-5);
  margin-bottom: var(--ds-space-4);
}

.ad-section-title {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--ds-text-faint);
  margin: 0 0 var(--ds-space-3);
}

.ad-description {
  font-size: 14px;
  line-height: 1.6;
  color: var(--ds-text);
  margin: 0;
  white-space: pre-line;
}

.ad-photos-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: var(--ds-space-2);
}

.ad-photo-thumb {
  aspect-ratio: 4 / 3;
  border-radius: var(--ds-radius-md, 8px);
  overflow: hidden;
  background: var(--ds-surface-offset);
  border: 1px solid var(--ds-divider);
  cursor: zoom-in;
  transition: transform 150ms, box-shadow 150ms;
}
.ad-photo-thumb:hover { transform: translateY(-2px); box-shadow: 0 4px 16px rgba(13,44,74,.12); }
.ad-photo-thumb img {
  width: 100%; height: 100%;
  object-fit: cover;
  display: block;
}

/* ── Mobile ──────────────────────────────────────────────────────── */
@media (max-width: 640px) {
  .ad-detail-page { padding: var(--ds-space-3) var(--ds-space-4) var(--ds-space-8); }
  .ad-detail-title { font-size: 18px; }
  .ad-detail-grid { grid-template-columns: 1fr 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  .ad-photo-thumb { transition: none; }
}

