:host { display: block; }

/* ------ PAGE  ------ */
.ad-page { padding-bottom: var(--ds-space-16); }

/* ------ LAYOUT ------ */
.ad-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: var(--ds-space-8);
  align-items: start;
  padding-top: var(--ds-space-5);
}

/* ------ GALLERY ------ */
.ad-gallery { margin-bottom: var(--ds-space-6); }

.ad-gallery-main {
  position: relative;
  aspect-ratio: 16/9;
  border-radius: var(--ds-radius-xl);
  overflow: hidden;
  border: 1px solid var(--ds-border);
}

.ad-gallery-main img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ad-gallery-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: var(--ds-radius-pill);
  background: oklch(1 0 0 / 0.85);
  backdrop-filter: blur(4px);
  border: 1px solid var(--ds-divider);
  color: var(--ds-text);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--ds-transition-fast);
}
.ad-gallery-arrow:hover { background: white; }
.ad-gallery-prev { left: var(--ds-space-3); }
.ad-gallery-next { right: var(--ds-space-3); }

.ad-gallery-counter {
  position: absolute;
  bottom: var(--ds-space-3);
  right: var(--ds-space-3);
  background: oklch(0 0 0 / 0.55);
  color: white;
  font-size: var(--ds-text-xs);
  font-weight: 600;
  padding: var(--ds-space-1) var(--ds-space-3);
  border-radius: var(--ds-radius-pill);
}

.ad-gallery-badges {
  position: absolute;
  top: var(--ds-space-3);
  left: var(--ds-space-3);
  display: flex;
  gap: var(--ds-space-2);
  align-items: center;
}

.ad-gallery-thumbs {
  display: flex;
  gap: var(--ds-space-2);
  margin-top: var(--ds-space-3);
  flex-wrap: wrap;
}

.ad-thumb {
  width: 72px;
  height: 52px;
  border-radius: var(--ds-radius-md);
  overflow: hidden;
  border: 2px solid transparent;
  cursor: pointer;
  padding: 0;
  transition: border-color var(--ds-transition-fast), opacity var(--ds-transition-fast);
  opacity: 0.65;
}
.ad-thumb.active { border-color: var(--ds-primary); opacity: 1; }
.ad-thumb:hover  { opacity: 1; }
.ad-thumb img    { width: 100%; height: 100%; object-fit: cover; }

/* Shared badges */
.ph-tx-badge { font-size: var(--ds-text-xs); font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; padding: var(--ds-space-1) var(--ds-space-3); border-radius: var(--ds-radius-pill); }
.tx-vente    { background: var(--ds-marine); color: white; }
.tx-location { background: var(--ds-success); color: var(--ds-text-inverse); }

/* ------ INFO BLOCK ------ */
.ad-info-block {
  background: var(--ds-surface);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-xl);
  padding: var(--ds-space-8);
  margin-bottom: var(--ds-space-6);
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-5);
}

.ad-price {
  font-family: var(--ds-font-display);
  font-size: var(--ds-text-2xl);
  font-weight: 700;
  color: var(--ds-text);
  line-height: 1;
}

.ad-title {
  font-family: var(--ds-font-display);
  font-size: var(--ds-text-xl);
  font-weight: 700;
  color: var(--ds-text);
  margin: var(--ds-space-2) 0 var(--ds-space-2);
  line-height: 1.2;
}

.ad-location {
  display: flex;
  align-items: center;
  gap: var(--ds-space-2);
  color: var(--ds-text-muted);
  font-size: var(--ds-text-sm);
}

.ad-specs {
  display: flex;
  gap: var(--ds-space-6);
  flex-wrap: wrap;
  padding: var(--ds-space-5) 0;
  border-block: 1px solid var(--ds-divider);
}

.ad-spec {
  display: flex;
  align-items: center;
  gap: var(--ds-space-3);
}

.ad-spec-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--ds-radius-md);
  background: var(--ds-primary-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ds-primary);
  flex-shrink: 0;
}

.ad-spec-val { font-weight: 700; font-size: var(--ds-text-base); color: var(--ds-text); }
.ad-spec-lbl { font-size: var(--ds-text-xs); color: var(--ds-text-muted); }

.ad-section-title {
  font-family: var(--ds-font-display);
  font-size: var(--ds-text-base);
  font-weight: 700;
  color: var(--ds-text);
  padding-bottom: var(--ds-space-3);
  border-bottom: 1px solid var(--ds-divider);
  margin-bottom: var(--ds-space-3);
}

.ad-desc {
  font-size: var(--ds-text-sm);
  color: var(--ds-text-muted);
  line-height: 1.8;
  max-width: none;
}

.ad-report-btn {
  display: flex;
  align-items: center;
  gap: var(--ds-space-2);
  font-size: var(--ds-text-xs);
  color: var(--ds-text-faint);
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  font-family: var(--ds-font-body);
  width: fit-content;
  transition: color var(--ds-transition-fast);
}
.ad-report-btn:hover { color: var(--ds-error); }

/* ------ SIDEBAR ------ */
.ad-sidebar { position: sticky; top: 80px; display: flex; flex-direction: column; gap: var(--ds-space-4); }

.ad-agent-card {
  background: var(--ds-surface);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-xl);
  padding: var(--ds-space-6);
}

.ad-agent-header { display: flex; align-items: center; gap: var(--ds-space-4); margin-bottom: var(--ds-space-5); padding-bottom: var(--ds-space-5); border-bottom: 1px solid var(--ds-divider); }

.ad-agent-avatar {
  width: 52px;
  height: 52px;
  border-radius: var(--ds-radius-pill);
  background: var(--ds-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--ds-font-display);
  font-weight: 700;
  font-size: var(--ds-text-base);
  color: white;
  flex-shrink: 0;
}

.ad-agent-name   { font-weight: 700; color: var(--ds-text); }
.ad-agent-agency { font-size: var(--ds-text-xs); color: var(--ds-text-muted); margin-top: 2px; }
.ad-agent-verified {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 700;
  color: var(--ds-success);
  background: var(--ds-success-hl);
  padding: 2px 8px;
  border-radius: var(--ds-radius-pill);
  margin-top: var(--ds-space-1);
}

.ad-contact-btns { display: flex; flex-direction: column; gap: var(--ds-space-2); }

.ad-whatsapp-btn {
  background: color-mix(in srgb, var(--ds-success) 22%, rgb(37 211 102));
  color: var(--ds-text-inverse);
  border: none;
}
.ad-whatsapp-btn:hover {
  background: color-mix(in srgb, var(--ds-success) 45%, rgb(18 140 126));
}

.ad-ref-text { font-size: 10px; color: var(--ds-text-faint); text-align: center; margin-top: var(--ds-space-3); }

.ad-info-box {
  background: var(--ds-surface-2);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-xl);
  padding: var(--ds-space-5);
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-2);
}

.ad-info-box-price { font-family: var(--ds-font-display); font-size: var(--ds-text-xl); font-weight: 700; color: var(--ds-text); }
.ad-info-box-note  { font-size: var(--ds-text-xs); color: var(--ds-text-muted); }

/* ------ SIMILAR ------ */
.ad-similar-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--ds-space-4);
  margin-top: var(--ds-space-4);
}

.ad-similar-card {
  background: var(--ds-surface);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-xl);
  overflow: hidden;
  cursor: pointer;
  transition: box-shadow var(--ds-transition-med), transform var(--ds-transition-med);
}
.ad-similar-card:hover { box-shadow: var(--ds-shadow-md); transform: translateY(-2px); }

.ad-similar-img { aspect-ratio: 16/9; overflow: hidden; }
.ad-similar-img img { width: 100%; height: 100%; object-fit: cover; }
.ad-similar-body { padding: var(--ds-space-4); display: flex; flex-direction: column; gap: var(--ds-space-1); }
.ph-price { font-family: var(--ds-font-display); font-weight: 700; color: var(--ds-text); }
.ph-title { font-size: var(--ds-text-xs); font-weight: 600; color: var(--ds-text); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; max-width: none; }
.ph-location { display: flex; align-items: center; gap: 4px; font-size: 10px; color: var(--ds-text-muted); }

/* ------ MODAL ------ */
.at-modal-overlay {
  position: fixed;
  inset: 0;
  background: oklch(0 0 0 / 0.5);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--ds-space-4);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--ds-transition-med);
}
.at-modal-overlay.open { opacity: 1; pointer-events: all; }

.at-modal {
  background: var(--ds-surface);
  border-radius: var(--ds-radius-2xl);
  width: 100%;
  max-width: 520px;
  max-height: 90dvh;
  overflow-y: auto;
  box-shadow: var(--ds-shadow-xl);
}

.at-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--ds-space-5) var(--ds-space-6);
  border-bottom: 1px solid var(--ds-divider);
}

.at-modal-header h2 { font-family: var(--ds-font-display); font-size: var(--ds-text-base); font-weight: 700; margin: 0; }

.at-modal-close {
  width: 32px;
  height: 32px;
  border-radius: var(--ds-radius-pill);
  border: 1.5px solid var(--ds-border);
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ds-text-muted);
  transition: all var(--ds-transition-fast);
}
.at-modal-close:hover { color: var(--ds-text); border-color: var(--ds-text-muted); }

.at-modal-body { padding: var(--ds-space-6); }

/* Button disable state */
.at-btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none !important; }

/* ------ RESPONSIVE ------ */
@media (max-width: 900px) {
  .ad-layout { grid-template-columns: 1fr; }
  .ad-sidebar { position: static; }
}

@media (max-width: 600px) {
  .ad-similar-grid { grid-template-columns: 1fr; }
}

