.api-status-indicator {
  display: flex;
  align-items: center;
  margin-left: 16px;
}

.status-button {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  height: 36px;
  border-radius: 18px;
  font-size: 14px;
  font-weight: 500;
  transition: background-color 0.3s ease;
}

.status-button:hover {
  background-color: rgba(255, 255, 255, 0.1);
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  transition: background-color 0.3s ease;
}

.status-connected .status-dot {
  background-color: var(--ds-success);
  box-shadow: 0 0 8px rgba(76, 175, 80, 0.6);
}

.status-disconnected .status-dot {
  background-color: var(--ds-error);
  box-shadow: 0 0 8px rgba(244, 67, 54, 0.6);
}

.status-checking .status-dot {
  background-color: var(--ds-warning);
  animation: pulse 1.5s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.status-text {
  color: white;
  white-space: nowrap;
}

.status-menu-content {
  padding: 16px;
  cursor: default;
}

.status-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.status-menu-leading-icon {
  flex-shrink: 0;
}

.status-menu-leading-icon.status-connected {
  color: var(--ds-success);
}

.status-menu-leading-icon.status-disconnected {
  color: var(--ds-error);
}

.status-menu-leading-icon.status-checking {
  color: var(--ds-warning);
}

.api-status-menu-origin {
  display: inline-flex;
  align-items: center;
}

.api-status-dropdown {
  min-width: 280px;
  background: var(--ds-surface-elevated, #fff);
  color: var(--ds-text-primary, rgba(0, 0, 0, 0.87));
  border-radius: var(--ds-radius-lg, 8px);
  box-shadow: var(--ds-shadow-lg, 0 8px 24px rgba(0, 0, 0, 0.15));
  border: 1px solid var(--ds-border-subtle, rgba(0, 0, 0, 0.08));
  overflow: hidden;
}

.api-status-dropdown-divider {
  height: 1px;
  background: var(--ds-divider, rgba(0, 0, 0, 0.08));
  margin: 0;
}

.api-status-menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  margin: 0;
  padding: 12px 16px;
  border: none;
  background: transparent;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: inherit;
  transition: background-color 0.15s ease;
}

.api-status-menu-item:hover:not(:disabled) {
  background: var(--ds-primary-subtle, rgba(0, 0, 0, 0.04));
}

.api-status-menu-item:focus-visible {
  outline: 2px solid var(--ds-marine);
  outline-offset: -2px;
}

.api-status-menu-item:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.api-status-menu-item .ds-icon {
  flex-shrink: 0;
  color: var(--ds-text-muted);
}

.status-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.status-label {
  font-weight: 500;
  font-size: 14px;
}

.status-timestamp {
  font-size: 12px;
  color: rgba(0, 0, 0, 0.6);
}

@media (max-width: 768px) {
  .status-text {
    display: none;
  }
  
  .api-status-indicator {
    margin-left: 8px;
  }
  
  .status-button {
    padding: 0 8px;
    min-width: auto;
  }
}

