/* Espace Pro — shell Atlasia (tokens DS). Anciennement _atlasia-pro-shell + layout local. */

:host {
  display: block;
  height: 100%;
}

/* Garde-fou overflow horizontal limité au shell Pro. */
:host ::ng-deep .mat-drawer-container,
:host ::ng-deep .mat-sidenav-container,
:host ::ng-deep .mat-drawer-content,
:host ::ng-deep .mat-sidenav-content {
  max-width: 100%;
  overflow-x: hidden;
}

/* Animation backdrop sidenav — scoppée au shell Pro. */
:host ::ng-deep .mat-drawer-backdrop {
  animation: fadeIn 250ms ease-out;
}

.skip-to-content {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--ds-primary);
  color: var(--ds-text-inverse);
  padding: var(--ds-space-2) var(--ds-space-4);
  text-decoration: none;
  z-index: 10000;
  font-weight: 500;
  border-radius: 0 0 var(--ds-radius-sm) 0;
}

.skip-to-content:focus {
  top: 0;
  outline: 2px solid var(--ds-text-inverse);
  outline-offset: -2px;
}

:host-context(.dark-theme) .skip-to-content {
  background: var(--ds-primary);
  color: var(--ds-text-inverse);
}

:host-context(.dark-theme) .skip-to-content:focus {
  outline: 2px solid color-mix(in oklab, var(--ds-primary-hl) 70%, white);
}

.sidenav-container {
  height: 100vh;
  width: 100%;
}

/* ── Sidebar ── */
.sidenav {
  width: 240px;
  background: color-mix(in oklab, var(--ds-surface) 96%, var(--ds-bg));
  border-right: 1px solid var(--ds-divider);
  box-shadow: var(--ds-shadow-sm);
  transition: transform var(--ds-transition-med);
}

.sidenav-header {
  background: linear-gradient(
    135deg,
    var(--ds-marine) 0%,
    color-mix(in oklab, var(--ds-marine) 86%, black) 100%
  ) !important;
  color: var(--ds-text-inverse) !important;
  min-height: 64px;
  padding: 0 18px !important;
  display: flex;
  align-items: center;
  box-shadow: none;
  border-bottom: 1px solid color-mix(in oklab, white 12%, transparent);
}

.brand-text {
  font-family: var(--ds-font-display);
  font-size: 1.12rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: inherit;
}

.nav-list {
  padding: var(--ds-space-4) var(--ds-space-2) var(--ds-space-2);
  display: flex;
  flex-direction: column;
}

.layout-divider {
  height: 1px;
  margin: var(--ds-space-2) var(--ds-space-4);
  background: var(--ds-divider);
  flex-shrink: 0;
}

.menu-divider {
  height: 1px;
  margin: 0;
  background: var(--ds-divider);
  border: none;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: var(--ds-space-3);
  margin: var(--ds-space-1) var(--ds-space-2);
  padding: var(--ds-space-2) var(--ds-space-3) !important;
  min-height: 42px;
  border-radius: var(--ds-radius-lg) !important;
  color: var(--ds-text-muted) !important;
  text-decoration: none;
  box-sizing: border-box;
  transition:
    background var(--ds-transition-fast),
    color var(--ds-transition-fast),
    transform var(--ds-transition-fast);
}

.nav-link:focus-visible {
  outline: 2px solid var(--ds-primary);
  outline-offset: 2px;
}

.nav-link-icon {
  flex-shrink: 0;
}

.nav-link-title {
  flex: 1;
  min-width: 0;
}

.nav-link .nav-link-icon,
.nav-link ds-icon {
  color: inherit;
}

.nav-link:hover {
  background: var(--ds-primary-subtle) !important;
  color: var(--ds-text) !important;
}

.nav-link.active {
  background: linear-gradient(
    135deg,
    color-mix(in oklab, var(--ds-primary-hl) 72%, white),
    color-mix(in oklab, var(--ds-marine-hl) 62%, white)
  ) !important;
  color: var(--ds-marine) !important;
  font-weight: 700 !important;
  box-shadow: inset 3px 0 0 var(--ds-primary);
}

.nav-link.active .nav-link-icon,
.nav-link.active ds-icon {
  color: var(--ds-primary) !important;
}

.badge-count {
  font-weight: 600;
  color: color-mix(in oklab, var(--ds-primary) 55%, var(--ds-text-muted));
}

/* ── Content column ── */
.sidenav-content {
  display: flex;
  flex-direction: column;
  height: 100%;
  background:
    radial-gradient(
      circle at top right,
      color-mix(in oklab, var(--ds-primary-hl) 55%, transparent) 0,
      transparent 30rem
    ),
    var(--ds-bg) !important;
}

.top-toolbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--ds-space-2);
  min-height: 56px !important;
  height: auto;
  padding: 0 var(--ds-space-4) !important;
  background: linear-gradient(
    135deg,
    var(--ds-marine) 0%,
    color-mix(in oklab, var(--ds-marine) 88%, black) 100%
  ) !important;
  color: var(--ds-text-inverse) !important;
  box-shadow: var(--ds-shadow-md);
  border-bottom: 1px solid color-mix(in oklab, white 10%, transparent);
}

:host ::ng-deep .top-toolbar .mat-icon,
:host ::ng-deep .top-toolbar mat-icon,
:host ::ng-deep .top-toolbar ds-icon {
  color: var(--ds-text-inverse) !important;
}

:host ::ng-deep .top-toolbar .theme-toggle-button:hover,
:host ::ng-deep .top-toolbar .menu-button:hover,
:host ::ng-deep .top-toolbar .keyboard-shortcuts-button:hover,
:host ::ng-deep .top-toolbar .notification-menu-button:hover,
:host ::ng-deep .top-toolbar .help-menu-button:hover,
:host ::ng-deep .top-toolbar .user-menu-button:hover {
  background-color: color-mix(in oklab, white 14%, transparent) !important;
}

.menu-button {
  margin-right: var(--ds-space-3);
}

.toolbar-spacer {
  flex: 1 1 auto;
}

/* ── Toolbar search (dense) ── */
:host ::ng-deep .top-toolbar app-global-search-bar,
:host ::ng-deep .top-toolbar .global-search {
  max-height: 42px;
}

.main-content {
  flex: 1;
  overflow-y: auto;
  padding: clamp(var(--ds-space-4), 2vw, 1.75rem);
}

/* ── Menus utilisateur / aide ── */
.help-menu-anchor {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
}

/* Backdrop des overlays du shell (aide, notifications, utilisateur). */
:host ::ng-deep .cdk-overlay-backdrop.shell-toolbar-overlay-backdrop {
  background: color-mix(in oklab, var(--ds-marine, #0f2744) 42%, transparent);
}

:host-context(.dark-theme) ::ng-deep .cdk-overlay-backdrop.shell-toolbar-overlay-backdrop {
  background: color-mix(in oklab, black 55%, transparent);
}

.help-menu-dropdown {
  min-width: 260px;
  max-width: min(320px, 92vw);
  background: var(--ds-surface-elevated);
  color: var(--ds-text-primary);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  border: 1px solid var(--ds-border-subtle);
  overflow: hidden;
}

.help-menu-dropdown .help-menu-header {
  display: flex;
  align-items: center;
  gap: var(--ds-space-3);
  padding: var(--ds-space-3) var(--ds-space-4);
  font-weight: 600;
  color: var(--ds-marine);
  cursor: default;
  pointer-events: none;

  ds-icon {
    color: var(--ds-marine);
    flex-shrink: 0;
  }

  span {
    font-size: 15px;
  }
}

.help-menu-item {
  display: flex;
  align-items: center;
  gap: var(--ds-space-3);
  width: 100%;
  padding: var(--ds-space-3) var(--ds-space-4);
  margin: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--ds-text-primary);
  transition: background-color var(--ds-transition-fast);

  ds-icon {
    flex-shrink: 0;
    margin-right: 0;
    color: var(--ds-marine);
  }

  &:hover {
    background: var(--ds-primary-subtle);
  }

  &:hover ds-icon {
    color: var(--ds-primary);
  }

  &:focus-visible {
    outline: 2px solid var(--ds-focus-ring, var(--ds-primary));
    outline-offset: -2px;
  }
}

.user-details {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-1);
}

.submenu-arrow {
  margin-left: auto;
  opacity: 0.6;
  flex-shrink: 0;
  transition: transform var(--ds-transition-fast);
}

.submenu-arrow-open {
  transform: rotate(90deg);
}

.user-menu-container {
  position: relative;
  margin-left: var(--ds-space-4);
}

.user-menu-anchor {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
}

.user-menu-button {
  width: 40px;
  height: 40px;
  border-radius: var(--ds-radius-full);
  transition: transform var(--ds-transition-fast), background var(--ds-transition-fast);
}

.user-menu-button:hover {
  transform: scale(1.05);
}

.user-menu-button mat-icon {
  font-size: 32px;
  width: 32px;
  height: 32px;
}

.user-menu-button ds-icon {
  width: 32px;
  height: 32px;
}

:host ::ng-deep .help-menu-dropdown .help-menu-header ds-icon {
  color: var(--ds-marine) !important;
}

.notification-menu-anchor {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
}

.notification-panel-dropdown {
  width: min(400px, 94vw);
  max-height: min(560px, 72vh);
  display: flex;
  flex-direction: column;
  background: var(--ds-surface-elevated);
  color: var(--ds-text-primary);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  border: 1px solid var(--ds-border-subtle);
  overflow: hidden;
}

.notification-panel-dropdown .notification-menu-content {
  flex: 1;
  min-height: 0;
  overflow: auto;
  -webkit-overflow-scrolling: touch;
}

.user-menu-dropdown {
  min-width: 280px;
  max-width: min(360px, 94vw);
  max-height: min(85vh, 640px);
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  background: var(--ds-surface-elevated);
  color: var(--ds-text-primary);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  border: 1px solid var(--ds-border-subtle);
}

.user-menu-tours-inline {
  background: var(--ds-surface-2);
  border-top: 1px solid var(--ds-divider);
  border-bottom: 1px solid var(--ds-divider);
}

.user-menu-tours-inline .tour-menu-header {
  padding: var(--ds-space-3) var(--ds-space-4) !important;
}

.tour-progress-badge {
  display: flex;
  align-items: center;
  gap: var(--ds-space-2);
  padding: var(--ds-space-2) var(--ds-space-3);
  background: linear-gradient(
    135deg,
    color-mix(in oklab, var(--ds-primary) 76%, white) 0%,
    color-mix(in oklab, var(--ds-marine) 66%, black) 100%
  );
  color: var(--ds-text-inverse);
  border-radius: var(--ds-radius-md);
  font-weight: 500;
  font-size: 14px;
}

.tour-status-icon {
  color: var(--ds-success);
  margin-left: auto;
}

.user-menu-header {
  padding: var(--ds-space-4) !important;
  cursor: default !important;
  background: var(--ds-surface-2) !important;
}

.user-menu-header:hover {
  background: var(--ds-surface-2) !important;
}

.user-info {
  display: flex;
  align-items: center;
  gap: var(--ds-space-3);
}

.user-avatar-large {
  font-size: 48px;
  width: 48px;
  height: 48px;
  color: var(--ds-primary);
}

.user-name {
  font-weight: 600;
  font-size: 16px;
  color: var(--ds-text);
}

.user-email {
  font-size: 14px;
  color: var(--ds-text-muted);
}

.user-menu-dropdown .help-menu-item ds-icon:not(.tour-status-icon):not(.submenu-arrow) {
  color: var(--ds-marine);
}

.notification-menu-button {
  position: relative;
}

.toolbar-icon-badge-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
}

.toolbar-count-badge {
  position: absolute;
  top: -5px;
  right: -9px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: var(--ds-radius-full);
  background: var(--ds-error-hl, var(--ds-error, #c62828));
  color: var(--ds-text-inverse);
  font-size: 10px;
  font-weight: 700;
  line-height: 16px;
  text-align: center;
  box-sizing: border-box;
  pointer-events: none;
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--ds-marine) 35%, transparent);
}

@media (max-width: 599px) {
  .sidenav {
    width: 280px;
  }

  .main-content {
    padding: var(--ds-space-4);
  }

  .top-toolbar {
    padding: 0 var(--ds-space-2) !important;
  }

  .menu-button {
    margin-right: var(--ds-space-2);
  }

  .user-menu-dropdown {
    min-width: 240px;
  }

  .notification-panel-dropdown {
    width: min(100vw - var(--ds-space-4), 400px);
  }
}

@media (max-width: 400px) {
  .sidenav {
    width: calc(100vw - 56px);
  }

  .brand-text {
    font-size: 1.05rem;
  }

  .user-menu-dropdown {
    min-width: 200px;
  }

  .user-avatar-large {
    font-size: 40px;
    width: 40px;
    height: 40px;
  }

  .user-name {
    font-size: 14px;
  }

  .user-email {
    font-size: 12px;
  }
}

@media (min-width: 600px) and (max-width: 959px) {
  .sidenav {
    width: 240px;
  }
}

@media (min-width: 960px) {
  .sidenav-content {
    margin-left: 0;
  }
}

@media (hover: hover) and (pointer: fine) {
  .nav-link:hover {
    transform: translateX(2px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .sidenav,
  .nav-link,
  .user-menu-button {
    transition: none;
  }
}

