      color: #666;
    }

    .request-card {
      background: #f8f9fa;
      border-radius: 8px;
      padding: 16px;
      margin-bottom: 12px;
    }

    .request-header {
      display: flex;
      justify-content: space-between;
      margin-bottom: 8px;
    }

    .request-date {
      font-weight: 500;
      color: #333;
    }

    .request-status {
      padding: 4px 12px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 500;
    }

    .status-pending {
      background: #fff3cd;
      color: #856404;
    }

    .status-accepted {
      background: #d4edda;
      color: #155724;
    }

    .status-declined {
      background: #f8d7da;
      color: #721c24;
    }

    .request-details {
      margin-top: 8px;
      color: #666;
      font-size: 14px;
    }

    .request-response {
      margin-top: 12px;
      padding: 12px;
      background: white;
      border-radius: 4px;
      font-size: 14px;
    }

    .request-form {
      margin-top: 24px;
