.calendar-list-view {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.list-header {
  padding: 16px;
  background: var(--ds-bg);
  border-bottom: 1px solid var(--ds-divider);
}

.stats {
  display: flex;
  gap: 24px;
  justify-content: center;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stat-value {
  font-size: 24px;
  font-weight: 600;
  color: var(--ds-marine);
}

.stat-label {
  font-size: 12px;
  color: var(--ds-text-muted);
  text-transform: uppercase;
  margin-top: 4px;
}

.loading-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 16px;
  gap: 16px;
}

.loading-state p {
  color: var(--ds-text-muted);
  font-size: 14px;
}

.appointments-list {
  flex: 1;
  overflow-y: auto;
  padding: 8px;
}

.date-group {
  margin-bottom: 8px;
  background: var(--ds-surface);
  border-radius: var(--ds-radius-md, 8px);
  overflow: hidden;
  box-shadow: var(--ds-shadow-xs);
  border: 1px solid var(--ds-divider);
}

.date-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--ds-surface-2);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s;
}

.date-header:hover {
  background: var(--ds-bg);
}

.date-info {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.date-label {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--ds-text);
  text-transform: capitalize;
}

.expand-icon {
  flex-shrink: 0;
  color: var(--ds-text-muted);
}

.appointments-container {
  border-top: 1px solid var(--ds-divider);
}

.appointment-item {
  display: flex;
  gap: 12px;
  padding: 16px;
  border-bottom: 1px solid var(--ds-surface-offset);
  cursor: pointer;
  transition: background-color 0.2s;
  position: relative;
}

.appointment-item:last-child {
  border-bottom: none;
}

.appointment-item:hover {
  background: var(--ds-surface-2);
}

.appointment-item.mobile {
  padding: 12px;
}

.appointment-status-indicator {
  width: 4px;
  border-radius: 2px;
  flex-shrink: 0;
  align-self: stretch;
  min-height: 48px;
}

.appointment-status-indicator--scheduled {
  background: var(--ds-marine);
}

.appointment-status-indicator--completed {
  background: var(--ds-success);
}

.appointment-status-indicator--cancelled {
  background: var(--ds-text-muted);
}

.appointment-content {
  flex: 1;
  min-width: 0;
}

.appointment-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 8px;
}

.appointment-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--ds-text);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.appointment-time {
  font-size: 13px;
  color: var(--ds-text-muted);
  white-space: nowrap;
  font-weight: 500;
}

.appointment-details {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 8px;
}

.detail-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--ds-text-muted);
}

.detail-row ds-icon {
  flex-shrink: 0;
  color: var(--ds-text-faint);
}

.detail-row span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.appointment-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.appointment-actions {
  display: flex;
  align-items: center;
  opacity: 0;
  transition: opacity 0.2s;
}

.appointment-item:hover .appointment-actions {
  opacity: 1;
}

@media (max-width: 768px) {
  .list-header {
    padding: 12px;
  }

  .stats {
    gap: 16px;
  }

  .stat-value {
    font-size: 20px;
  }

  .stat-label {
    font-size: 11px;
  }

  .appointments-list {
    padding: 4px;
  }

  .date-header {
    padding: 10px 12px;
  }

  .date-label {
    font-size: 14px;
  }

  .appointment-item {
    gap: 8px;
  }

  .appointment-title {
    font-size: 13px;
  }

  .appointment-time {
    font-size: 12px;
  }

  .detail-row {
    font-size: 12px;
  }

}

@media (max-width: 480px) {
  .appointment-header {
    flex-direction: column;
    gap: 4px;
  }

  .appointment-title {
    white-space: normal;
    line-height: 1.3;
  }
}

