import { Component, OnInit, OnDestroy, input } from '@angular/core';
import { CollaborationService, CollaborationActivity } from '../services/collaboration.service';
import { Subscription } from 'rxjs';

@Component({
    selector: 'app-collaboration-activity-stream',
    template: `
    <div class="activity-stream">
      <h3 class="activity-header">
        <span class="header-icon">📋</span>
        Real-time Activity Stream
        @if (showNewActivityBadge) {
          <span class="new-badge">NEW</span>
        }
      </h3>
      <div class="activity-list">
        @for (activity of activities; track activity; let i = $index) {
          <div
            class="activity-item"
            [class.new-activity]="i === 0 && showNewActivityAnimation">
            <div class="activity-avatar" [style.background-color]="getActivityColor(activity.activityType)">
              {{ getActivityIcon(activity.activityType) }}
            </div>
            <div class="activity-content">
              <div class="activity-description">
                <strong>{{ activity.username }}</strong> {{ activity.description }}
              </div>
              <div class="activity-timestamp">{{ formatTimestamp(activity.timestamp) }}</div>
            </div>
          </div>
        }
        @if (activities.length === 0) {
          <div class="no-activities">
            <span class="empty-icon">🔔</span>
            <p>No recent activity</p>
          </div>
        }
      </div>
    </div>
    `,
    styles: [`
    .activity-stream {
      background: var(--ds-surface);
      border-radius: var(--ds-radius-md);
      padding: var(--ds-space-4);
      border: 1px solid var(--ds-divider);
      box-shadow: var(--ds-shadow-sm);
    }

    .activity-header {
      display: flex;
      align-items: center;
      gap: var(--ds-space-2);
      margin: 0 0 var(--ds-space-4) 0;
      font-size: 16px;
      font-weight: 600;
      color: var(--ds-text);
    }

    .header-icon {
      font-size: 20px;
    }

    .new-badge {
      background: var(--ds-error);
      color: var(--ds-text-inverse);
      font-size: 10px;
      padding: 2px 6px;
      border-radius: var(--ds-radius-pill);
      font-weight: 700;
      animation: pulse 1s infinite;
    }

    .activity-list {
      max-height: 400px;
      overflow-y: auto;
    }

    .activity-item {
      display: flex;
      gap: var(--ds-space-3);
      padding: var(--ds-space-3);
      border-radius: var(--ds-radius-sm);
      margin-bottom: var(--ds-space-2);
      transition: background var(--ds-transition-fast);
    }

    .activity-item:hover {
      background: var(--ds-surface-offset);
    }

    .activity-item.new-activity {
      animation: slideIn 0.5s ease-out;
      background: var(--ds-marine-hl);
    }

    .activity-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 18px;
    }

    .activity-content {
      flex: 1;
      min-width: 0;
    }

    .activity-description {
      font-size: 14px;
      color: var(--ds-text);
      margin-bottom: var(--ds-space-1);
      word-wrap: break-word;
    }

    .activity-timestamp {
      font-size: 12px;
      color: var(--ds-text-muted);
    }

    .no-activities {
      text-align: center;
      padding: var(--ds-space-8);
      color: var(--ds-text-faint);
    }

    .empty-icon {
      font-size: 48px;
      display: block;
      margin-bottom: var(--ds-space-2);
    }

    @keyframes slideIn {
      from {
        opacity: 0;
        transform: translateY(-20px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes pulse {
      0%, 100% {
        opacity: 1;
      }
      50% {
        opacity: 0.7;
      }
    }
  `]
})
export class CollaborationActivityStreamComponent implements OnInit, OnDestroy {
  readonly dossierId = input.required<number>();
  readonly maxActivities = input(20);

  activities: CollaborationActivity[] = [];
  showNewActivityBadge = false;
  showNewActivityAnimation = false;

  private subscriptions: Subscription[] = [];
  private badgeTimeout: any;

  constructor(private collaborationService: CollaborationService) {}

  ngOnInit(): void {
    this.subscriptions.push(
      this.collaborationService.getActivityUpdates().subscribe(activity => {
        this.addActivity(activity);
      })
    );
  }

  private addActivity(activity: CollaborationActivity): void {
    this.activities.unshift(activity);
    
    if (this.activities.length > this.maxActivities()) {
      this.activities = this.activities.slice(0, this.maxActivities());
    }

    this.showNewActivityBadge = true;
    this.showNewActivityAnimation = true;

    setTimeout(() => {
      this.showNewActivityAnimation = false;
    }, 500);

    if (this.badgeTimeout) {
      clearTimeout(this.badgeTimeout);
    }

    this.badgeTimeout = setTimeout(() => {
      this.showNewActivityBadge = false;
    }, 3000);
  }

  getActivityIcon(activityType: string): string {
    const icons: { [key: string]: string } = {
      'edit': '✏️',
      'status_change': '🔄',
      'comment': '💬',
      'appointment': '📅',
      'message': '📧',
      'document': '📄',
      'task': '✅',
      'note': '📝'
    };
    return icons[activityType] || '📋';
  }

  getActivityColor(activityType: string): string {
    const colors: { [key: string]: string } = {
      'edit': 'var(--ds-marine)',
      'status_change': 'var(--ds-warning)',
      'comment': 'var(--ds-success)',
      'appointment': 'var(--ds-primary)',
      'message': 'var(--ds-marine-light)',
      'document': 'var(--ds-text-muted)',
      'task': 'var(--ds-success)',
      'note': 'var(--ds-text-muted)'
    };
    return colors[activityType] || 'var(--ds-text-muted)';
  }

  formatTimestamp(timestamp: Date): string {
    const now = new Date();
    const diff = now.getTime() - new Date(timestamp).getTime();
    const seconds = Math.floor(diff / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (seconds < 60) {
      return 'Just now';
    } else if (minutes < 60) {
      return `${minutes} minute${minutes !== 1 ? 's' : ''} ago`;
    } else if (hours < 24) {
      return `${hours} hour${hours !== 1 ? 's' : ''} ago`;
    } else if (days < 7) {
      return `${days} day${days !== 1 ? 's' : ''} ago`;
    } else {
      return new Date(timestamp).toLocaleDateString();
    }
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach(sub => sub.unsubscribe());
    if (this.badgeTimeout) {
      clearTimeout(this.badgeTimeout);
    }
  }
}

