}

.viewer-avatar:hover {
  transform: scale(1.1);
}

.viewer-count {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--ds-text-muted);
  color: var(--ds-text-inverse);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  border: 2px solid var(--ds-surface);
  box-shadow: var(--ds-shadow-sm);
}

.viewer-text {
  color: var(--ds-text-muted);
  font-weight: 500;
}

.recent-activity {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--ds-text-muted);
  font-size: 13px;
}

.activity-indicator {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ds-success);
}

.activity-indicator.pulse {
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.5;
    transform: scale(1.2);
  }
}

.activity-text {
  font-style: italic;
}

