.comment-search-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 24px;
}

.search-header h3 {
  margin: 0 0 24px 0;
  font-size: 24px;
}

.search-form {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
}

.search-input {
  flex: 1;
}

.loading-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  color: var(--ds-text-muted);
}

.loading-state p {
  margin-top: 16px;
}

.no-results {
