@use '../design-system/patterns/messaging-thread/messaging-thread-bubbles' as *;

.comment-thread-container {
  display: flex;
  height: 600px;
  border: 1px solid var(--ds-divider);
  border-radius: 8px;
  overflow: hidden;
  background: var(--ds-surface);
}

.comment-sidebar {
  width: 350px;
  border-right: 1px solid var(--ds-divider);
  display: flex;
  flex-direction: column;
  background: var(--ds-surface-2);
}

.sidebar-header {
  padding: 16px;
  border-bottom: 1px solid var(--ds-divider);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--ds-surface);
}

.sidebar-title {
  margin: 0;
  font-size: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.sidebar-actions {
  display: flex;
  gap: 4px;
}

.new-thread-form {
  padding: 16px;
  background: var(--ds-surface);
  border-bottom: 1px solid var(--ds-divider);

  .full-width {
    width: 100%;
  }
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 8px;
}

.thread-list {
  flex: 1;
  overflow-y: auto;
}

.thread-item {
  padding: 12px 16px;
  border-bottom: 1px solid var(--ds-divider);
  cursor: pointer;
  transition: background-color 0.2s;
  background: var(--ds-surface);

  &:hover {
    background: var(--ds-bg);
  }

  &.selected {
    background: var(--ds-marine-hl);
    border-left: 3px solid var(--ds-marine);
  }

  &.resolved {
    opacity: 0.7;
  }
}

.thread-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.thread-title {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 14px;
}

.resolved-icon {
  font-size: 16px;
  width: 16px;
  height: 16px;
  color: var(--ds-success);
}

.comment-count {
  background: var(--ds-divider);
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 500;
}

.thread-meta {
  display: flex;
  gap: 8px;
  font-size: 12px;
  color: var(--ds-text-muted);
  margin-bottom: 4px;
}

.thread-preview {
  font-size: 13px;
  color: var(--ds-text-muted);
  line-height: 1.4;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
  color: var(--ds-text-faint);

  mat-icon {
    font-size: 48px;
    width: 48px;
    height: 48px;
    margin-bottom: 16px;
  }
}

.loading-state {
  display: flex;
  justify-content: center;
  padding: 40px;
}

.comment-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--ds-surface);
}

.thread-detail-header {
  padding: 16px;
  border-bottom: 1px solid var(--ds-divider);
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.thread-info h2 {
  margin: 0 0 8px;
  font-size: 20px;
}

.thread-status {
  margin-top: 8px;
}

.thread-actions {
  display: flex;
  gap: 4px;
}

.ct-export-menu-origin {
  display: inline-flex;
  align-items: center;
}

.ct-export-menu-dropdown {
  min-width: 200px;
  background: var(--ds-surface-elevated);
  color: var(--ds-text-primary);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  border: 1px solid var(--ds-border-subtle);
  overflow: hidden;
}

.ct-export-menu-item {
  display: flex;
  align-items: center;
  gap: var(--ds-space-2);
  width: 100%;
  margin: 0;
  padding: var(--ds-space-3) var(--ds-space-4);
  border: none;
  background: transparent;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--ds-text-primary);
  transition: background-color var(--ds-transition-fast);
}

.ct-export-menu-item:hover {
  background: var(--ds-primary-subtle);
}

.ct-export-menu-item:focus-visible {
  outline: 2px solid var(--ds-marine);
  outline-offset: -2px;
}

.ct-export-menu-item .ds-icon {
  flex-shrink: 0;
  color: var(--ds-text-muted);
}

.ct-export-menu-item:hover .ds-icon {
  color: var(--ds-primary);
}

.comments-container {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.comments-container.ds-thread--comments {
  gap: var(--ds-space-4);
}

.comments-container .ds-thread__msg {
  margin-bottom: 0;
}

.comment-mentions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;

  mat-icon {
    font-size: 16px;
    width: 16px;
    height: 16px;
    color: var(--ds-text-faint);
  }
}

.mention-tag {
  background: var(--ds-marine-hl);
  color: var(--ds-marine);
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 500;
}

.add-comment-section {
  padding: 16px;
  border-top: 1px solid var(--ds-divider);
  background: var(--ds-surface-2);
}

.comment-input-container {
  width: 100%;
  position: relative;
}

.mention-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: 4px;
  box-shadow: var(--ds-shadow-md);
  max-height: 200px;
  overflow-y: auto;
  z-index: 1000;
}

.mention-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  cursor: pointer;
  transition: background-color 0.2s;

  &:hover {
    background: var(--ds-bg);
  }

  mat-icon {
    font-size: 20px;
    width: 20px;
    height: 20px;
    color: var(--ds-text-muted);
  }
}

.empty-selection {
  display: flex;
  align-items: center;
  justify-content: center;
}

.empty-state-large {
  text-align: center;
  color: var(--ds-text-faint);

  mat-icon {
    font-size: 72px;
    width: 72px;
    height: 72px;
    margin-bottom: 16px;
  }

  h3 {
    margin: 0 0 8px;
    font-size: 20px;
  }

  p {
    margin: 0;
    font-size: 14px;
  }
}

@media (max-width: 768px) {
  .comment-thread-container {
    flex-direction: column;
    height: auto;
  }

  .comment-sidebar {
    width: 100%;
    max-height: 300px;
    border-right: none;
    border-bottom: 1px solid var(--ds-divider);
  }

  .comment-main {
    min-height: 400px;
  }
}

