.dashboard-container {
  min-height: 100vh;
  background: var(--ds-bg);
}

.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--ds-space-4) var(--ds-space-6);
  background: var(--ds-surface);
  box-shadow: var(--ds-shadow-sm);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

.logo {
  height: 40px;
}

h1 {
  margin: 0;
  font-size: 20px;
  color: var(--ds-text);
}

.header-right {
  display: flex;
  align-items: center;
  gap: var(--ds-space-4);
}

.user-name {
  font-weight: 500;
  color: var(--ds-text);
}

.logout-button {
  padding: var(--ds-space-2) var(--ds-space-4);
  background: var(--ds-surface-offset);
  color: var(--ds-text);
  border: none;
  border-radius: var(--ds-radius-sm);
  cursor: pointer;
  font-size: 14px;
  transition: background var(--ds-transition-fast);
}

.logout-button:hover {
  background: var(--ds-divider);
}

.loading-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 60vh;
}

.spinner {
  width: 48px;
  height: 48px;
  border: 4px solid var(--ds-surface-offset);
  border-top: 4px solid var(--ds-marine);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: var(--ds-space-4);
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.dashboard-content {
  max-width: var(--ds-content-full);
  margin: 0 auto;
  padding: var(--ds-space-6);
}

.status-banner {
  background: linear-gradient(135deg, var(--ds-marine) 0%, var(--ds-marine-light) 100%);
  color: var(--ds-text-inverse);
  padding: var(--ds-space-8);
  border-radius: var(--ds-radius-lg);
  margin-bottom: var(--ds-space-6);
}

.status-info {
  margin-bottom: 16px;
}

.status-info h2 {
  margin: 0 0 8px 0;
  font-size: 18px;
  opacity: 0.9;
}

.status-badge {
  display: inline-block;
  background: color-mix(in srgb, var(--ds-text-inverse) 22%, transparent);
  padding: var(--ds-space-2) var(--ds-space-4);
  border-radius: var(--ds-radius-sm);
  font-size: 16px;
  font-weight: 500;
}

.progress-container {
  margin-top: 16px;
}

.progress-bar {
  width: 100%;
  height: 8px;
  background: color-mix(in srgb, var(--ds-text-inverse) 22%, transparent);
  border-radius: var(--ds-radius-sm);
  overflow: hidden;
  margin-bottom: var(--ds-space-2);
}

.progress-fill {
  height: 100%;
  background: var(--ds-text-inverse);
  transition: width 0.5s ease;
}

.progress-text {
  font-size: 14px;
  opacity: 0.9;
}

.tabs {
  display: flex;
  gap: var(--ds-space-2);
  background: var(--ds-surface);
  padding: var(--ds-space-4);
  border-radius: var(--ds-radius-md);
  margin-bottom: var(--ds-space-6);
  overflow-x: auto;
}

.tab-button {
  position: relative;
  padding: var(--ds-space-3) var(--ds-space-5);
  background: transparent;
  color: var(--ds-text-muted);
  border: none;
  border-radius: var(--ds-radius-sm);
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  transition: background var(--ds-transition-fast), color var(--ds-transition-fast);
  white-space: nowrap;
}

.tab-button:hover {
  background: var(--ds-surface-offset);
  color: var(--ds-text);
}

.tab-button.active {
  background: var(--ds-marine);
  color: var(--ds-text-inverse);
}

.badge {
  position: absolute;
  top: 4px;
  right: 4px;
  background: var(--ds-error);
  color: var(--ds-text-inverse);
  font-size: 11px;
  padding: 2px 6px;
  border-radius: var(--ds-radius-pill);
  min-width: 18px;
  text-align: center;
}

.tab-content {
  animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
  gap: 24px;
}

@media (max-width: 768px) {
  .grid-2 {
    grid-template-columns: 1fr;
  }

  .dashboard-content {
    padding: 16px;
  }

  .tabs {
    flex-wrap: wrap;
  }
}

