  font-size: 20px;
  font-weight: 600;
  color: var(--ds-text);
}

.modal-body {
  padding: var(--ds-space-5);
  overflow-y: auto;
  color: var(--ds-text);
}

.template-grid,
.widget-library-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--ds-space-4);
}

.template-card,
.widget-type-card {
  padding: var(--ds-space-5);
  border: 2px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  cursor: pointer;
  transition: border-color var(--ds-transition-fast), background var(--ds-transition-fast), transform var(--ds-transition-fast);
  text-align: center;
  background: var(--ds-surface);
}

.template-card:hover,
.widget-type-card:hover {
  border-color: var(--ds-marine);
  background: var(--ds-marine-hl);
  transform: translateY(-2px);
}

.template-icon {
  margin-bottom: var(--ds-space-3);
}

.template-icon .material-icons,
.widget-type-card .material-icons {
  font-size: 48px;
  color: var(--ds-marine);
}

.template-card h3,
.widget-type-card h3 {
