  border-radius: var(--ds-radius-pill);
  font-size: 12px;
  background: var(--ds-marine-hl);
  color: var(--ds-marine);
  font-weight: 500;
}

.import-textarea {
  width: 100%;
  min-height: 300px;
  padding: var(--ds-space-3);
