    align-items: flex-start;
    gap: var(--ds-space-4);
  }

  .dashboard-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .dashboard-grid {
    grid-template-columns: 1fr;
  }

  .widget-container {
    grid-column: span 1 !important;
  }

  .template-grid,
  .widget-library-grid {
    grid-template-columns: 1fr;
  }
}

