/* ── Layout pro-page ── */
.pro-page {
  padding: var(--ds-space-8);
  max-width: var(--ds-content-full);
  margin: 0 auto;
  @media (max-width: 768px) { padding: var(--ds-space-4); }
}

/* ── Sélecteur de période ── */
.dash-period {
  display: flex;
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-pill);
  overflow: hidden;
  background: var(--ds-surface);

  &__btn {
    height: 32px;
    padding: 0 14px;
    border: none;
    background: transparent;
    font-family: var(--ds-font-body);
    font-size: 12.5px;
    color: var(--ds-text-muted);
    cursor: pointer;
    transition: background var(--ds-transition-fast), color var(--ds-transition-fast);
    &--active { background: var(--ds-marine); color: var(--ds-text-inverse); }
    &:hover:not(&--active) { background: var(--ds-surface-offset); }
  }
}

/* ── KPI Grid ── */
.dash-panel--kpi {
  margin-bottom: var(--ds-space-8);
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--ds-space-4);
}

/* ── Main grid 2 colonnes ── */
.dash-main-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: var(--ds-space-6);
  @media (max-width: 1024px) { grid-template-columns: 1fr; }
}

/* Contenu des cartes DS */
.dash-stack {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-4);
}

.dash-section__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.dash-section__title {
  font-family: var(--ds-font-body);
  font-size: 13.5px;
  font-weight: 700;
  color: var(--ds-text);
  letter-spacing: 0.2px;
  margin: 0;
}

.dash-section__actions {
  display: flex;
  gap: var(--ds-space-1);
}

.dash-right-col {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-4);
}

.dash-panel ds-card {
  display: block;
  width: 100%;
}

/* ── Boutons icône export ── */
.dash-icon-btn {
  width: 32px;
  height: 32px;
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-sm);
  background: transparent;
  color: var(--ds-text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background var(--ds-transition-fast), color var(--ds-transition-fast);
  &:hover { background: var(--ds-surface-offset); color: var(--ds-text); }
  &:disabled { opacity: 0.4; cursor: not-allowed; }
}

.dash-link {
  font-size: 12.5px;
  color: var(--ds-marine);
  font-weight: 600;
  text-decoration: none;
  &:hover { text-decoration: underline; }
}

.dash-error {
  padding: var(--ds-space-3) var(--ds-space-4);
  background: var(--ds-error-hl);
  color: var(--ds-error);
  border: 1px solid var(--ds-error);
  border-radius: var(--ds-radius-md);
  font-size: 13.5px;
}

.dash-skeleton-list { display: flex; flex-direction: column; gap: var(--ds-space-2); }

/* ── Dossier rows ── */
.dossier-rows { display: flex; flex-direction: column; }

.dossier-row {
  display: flex;
  align-items: center;
  gap: var(--ds-space-3);
  padding: 10px var(--ds-space-3);
  border-radius: var(--ds-radius-md);
  cursor: pointer;
  transition: background var(--ds-transition-fast);

  &:hover { background: var(--ds-surface-offset); }
  &:focus-visible { outline: 2px solid var(--ds-marine); outline-offset: 2px; }

  &__info { flex: 1; min-width: 0; }
  &__name { font-size: 13.5px; font-weight: 600; color: var(--ds-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &__meta { font-size: 12px; color: var(--ds-text-muted); }
  &__date { font-size: 11.5px; color: var(--ds-text-faint); white-space: nowrap; }
}

/* ── Annonce rows ── */
.annonce-rows { display: flex; flex-direction: column; }

.annonce-row {
  display: flex;
  align-items: center;
  gap: var(--ds-space-3);
  padding: 8px var(--ds-space-2);
  border-radius: var(--ds-radius-md);
  cursor: pointer;
  transition: background var(--ds-transition-fast);
  &:hover { background: var(--ds-surface-offset); }
  &:focus-visible { outline: 2px solid var(--ds-marine); outline-offset: 2px; }

  &__photo {
    width: 48px; height: 40px;
    border-radius: var(--ds-radius-sm);
    overflow: hidden;
    background: var(--ds-surface-offset);
    flex: none;
    display: flex; align-items: center; justify-content: center;
    img { width: 100%; height: 100%; object-fit: cover; }
  }

  &__photo-placeholder { color: var(--ds-text-faint); }
  &__info { flex: 1; min-width: 0; }
  &__title { font-size: 13px; font-weight: 600; color: var(--ds-text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  &__sub { font-size: 11.5px; color: var(--ds-text-muted); }
}

/* ── Quick actions ── */
.quick-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--ds-space-2);
}

.quick-action-btn {
  display: flex;
  align-items: center;
  gap: var(--ds-space-2);
  padding: 12px;
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  background: var(--ds-surface);
  cursor: pointer;
  font-family: var(--ds-font-body);
  font-size: 13px;
  font-weight: 600;
  color: var(--ds-text);
  transition: background var(--ds-transition-fast), box-shadow var(--ds-transition-fast);
  text-align: left;

  &:hover {
    background: var(--ds-surface-offset);
    box-shadow: var(--ds-shadow-xs);
  }

  &__icon {
    width: 36px; height: 36px;
    border-radius: var(--ds-radius-sm);
    background: var(--ds-marine-hl);
    color: var(--ds-marine);
    display: flex; align-items: center; justify-content: center;
    flex: none;

    &--copper  { background: var(--ds-primary-hl);  color: var(--ds-primary); }
    &--success { background: var(--ds-success-hl); color: var(--ds-success); }
    &--warning { background: var(--ds-warning-hl);   color: var(--ds-warning); }
  }
}

.kpi-error { font-size: 12px; color: var(--ds-error); padding: 8px; }

/* a11y */
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .dossier-row, .annonce-row { transition: none !important; }
}

