.developer-portal {
  padding: 2rem;
  max-width: 1400px;
  margin: 0 auto;

  .header {
    margin-bottom: 2rem;

    h1 {
      font-size: 2rem;
      font-weight: bold;
      margin-bottom: 0.5rem;
    }

    p {
      color: var(--ds-text-muted);
    }
  }

  .tabs {
    display: flex;
    gap: 1rem;
    border-bottom: 2px solid var(--ds-divider);
    margin-bottom: 2rem;

    button {
      padding: 0.75rem 1.5rem;
      background: none;
      border: none;
      border-bottom: 3px solid transparent;
      cursor: pointer;
      font-weight: 500;
      transition: all 0.2s;

      &:hover {
        background-color: var(--ds-surface-2);
      }

      &.active {
        color: var(--ds-marine);
        border-bottom-color: var(--ds-marine);
      }
    }
  }

  .section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1.5rem;

    h2 {
      font-size: 1.5rem;
      font-weight: 600;
    }
  }

  .api-keys-list,
  .webhooks-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
    gap: 1.5rem;
  }

  .api-key-card,
  .webhook-card {
    background: var(--ds-surface);
    border: 1px solid var(--ds-divider);
    border-radius: var(--ds-radius-md);
    padding: 1.5rem;
    box-shadow: var(--ds-shadow-xs);

    .key-header,
    .webhook-header {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-bottom: 1rem;

      h3 {
        flex: 1;
        font-size: 1.125rem;
        font-weight: 600;
      }
    }

    .key-details,
    .webhook-details {
      margin-bottom: 1rem;

      p {
        margin: 0.5rem 0;
        font-size: 0.875rem;
        color: var(--ds-text-muted);

        strong {
          color: var(--ds-text);
        }
      }
    }

    .key-actions,
    .webhook-actions {
      display: flex;
      gap: 0.5rem;
    }
  }

  .webhook-details-panel {
    margin-top: 2rem;
    padding: 1.5rem;
    background: var(--ds-surface);
    border: 1px solid var(--ds-divider);
    border-radius: var(--ds-radius-md);

    h3 {
      font-size: 1.25rem;
      margin-bottom: 1rem;
    }

    h4 {
      font-size: 1rem;
      margin: 1.5rem 0 1rem;
    }

    .secret-section {
      margin-bottom: 1.5rem;

      .secret-display {
        display: flex;
        gap: 0.5rem;
        align-items: center;

        code {
          flex: 1;
          padding: 0.5rem;
          background: var(--ds-surface-offset);
          border-radius: var(--ds-radius-sm);
          font-family: monospace;
        }
      }
    }
  }

  .usage-stats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;

    .stat-card {
      background: var(--ds-surface);
      border: 1px solid var(--ds-divider);
      border-radius: var(--ds-radius-md);
      padding: 1.5rem;
      text-align: center;

      h3 {
        font-size: 0.875rem;
        color: var(--ds-text-muted);
        margin-bottom: 0.5rem;
      }

      .stat-value {
        font-size: 2rem;
        font-weight: bold;
        color: var(--ds-text);
      }
    }
  }

  .deliveries-table,
  .usage-table {
    background: var(--ds-surface);
    border: 1px solid var(--ds-divider);
    border-radius: var(--ds-radius-md);
    overflow: hidden;

    table {
      width: 100%;
      border-collapse: collapse;

      thead {
        background: var(--ds-surface-2);

        th {
          padding: 0.75rem 1rem;
          text-align: left;
          font-weight: 600;
          font-size: 0.875rem;
          color: var(--ds-text);
          border-bottom: 1px solid var(--ds-divider);
        }
      }

      tbody {
        tr {
          border-bottom: 1px solid var(--ds-divider);

          &:last-child {
            border-bottom: none;
          }

          &:hover {
            background: var(--ds-surface-2);
          }
        }

        td {
          padding: 0.75rem 1rem;
          font-size: 0.875rem;
          color: var(--ds-text-muted);
        }
      }
    }
  }

  .badge {
    padding: 0.25rem 0.75rem;
    border-radius: var(--ds-radius-pill);
    font-size: 0.75rem;
    font-weight: 600;
  }

  .btn-primary,
  .btn-secondary,
  .btn-danger {
    padding: 0.5rem 1rem;
    border-radius: var(--ds-radius-sm);
    border: none;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }

  .btn-primary {
    background: var(--ds-marine);
    color: var(--ds-text-inverse);

    &:hover:not(:disabled) {
      background: color-mix(in srgb, var(--ds-marine) 88%, var(--ds-text) 12%);
    }
  }

  .btn-secondary {
    background: var(--ds-surface-offset);
    color: var(--ds-text);

    &:hover:not(:disabled) {
      background: var(--ds-divider);
    }
  }

  .btn-danger {
    background: var(--ds-error);
    color: var(--ds-text-inverse);

    &:hover:not(:disabled) {
      background: color-mix(in srgb, var(--ds-error) 88%, var(--ds-text) 12%);
    }
  }

  .modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: color-mix(in srgb, var(--ds-text) 35%, transparent);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
  }

  .modal-content {
    background: var(--ds-surface);
    border-radius: var(--ds-radius-md);
    padding: 2rem;
    max-width: 500px;
    width: 90%;
    max-height: 90vh;
    overflow-y: auto;

    h2 {
      font-size: 1.5rem;
      margin-bottom: 1.5rem;
    }

    .form-group {
      margin-bottom: 1.5rem;

      label {
        display: block;
        font-weight: 500;
        margin-bottom: 0.5rem;
        color: var(--ds-text);
      }

      input,
      select,
      textarea {
        width: 100%;
        padding: 0.5rem;
        border: 1px solid var(--ds-border);
        border-radius: var(--ds-radius-sm);
        font-size: 0.875rem;

        &:focus {
          outline: none;
          border-color: var(--ds-marine);
          box-shadow: 0 0 0 2px color-mix(in srgb, var(--ds-marine) 18%, transparent);
        }
      }
    }

    .modal-actions {
      display: flex;
      gap: 0.5rem;
      justify-content: flex-end;
      margin-top: 1.5rem;
    }

    .key-created {
      .alert {
        padding: 1rem;
        border-radius: var(--ds-radius-sm);
        margin-bottom: 1rem;

        &.alert-warning {
          background: var(--ds-warning-hl);
          color: var(--ds-warning);
          border: 1px solid var(--ds-warning);
        }
      }

      .key-display {
        margin-bottom: 1rem;

        code {
          display: block;
          padding: 1rem;
          background: var(--ds-surface-offset);
          border-radius: var(--ds-radius-sm);
          font-family: monospace;
          word-break: break-all;
          margin-bottom: 0.5rem;
        }
      }
    }
  }
}

