.dialog-container {
  width: 600px;
  max-width: 90vw;
}

mat-dialog-content {
  padding: 20px 24px;
  max-height: 70vh;
  overflow-y: auto;
}

.error-alert {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  margin-bottom: 16px;
  background-color: var(--ds-error-hl);
  border: 1px solid var(--ds-error-hl);
  border-radius: 8px;
  color: var(--ds-error);
}

.error-icon {
  color: var(--ds-error);
  flex-shrink: 0;
}

.warning-banner {
  margin-bottom: 20px;
  padding: 16px;
  background-color: var(--ds-warning-hl);
  border: 1px solid var(--ds-warning-hl);
  border-radius: 8px;
  color: var(--ds-warning);
}

.warning-content {
  display: flex;
  gap: 12px;
  margin-bottom: 12px;
}

.warning-icon {
  color: var(--ds-warning);
  flex-shrink: 0;
}

.warning-text {
  flex: 1;
}

.warning-text strong {
  display: block;
  margin-bottom: 4px;
  font-size: 14px;
  font-weight: 600;
}

.warning-text p {
  margin: 0;
  font-size: 13px;
}

.warning-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 12px;
}

.dossier-form {
  margin-top: 16px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.full-width {
  width: 100%;
}

.advanced-panel {
  margin-top: 16px;
  box-shadow: none;
  border: 1px solid var(--ds-divider);
}

.advanced-panel mat-form-field {
  margin-top: 16px;
}

mat-dialog-actions {
  padding: 16px 24px;
  margin: 0;
  border-top: 1px solid var(--ds-divider);
}

.btn-loading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.inline-spinner {
  display: inline-block;
}

@media (max-width: 768px) {
  .dialog-container {
    width: 100%;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  mat-dialog-content {
    padding: 16px;
  }

  mat-dialog-actions {
    padding: 12px 16px;
  }
}

