    this.consentementApiService.update(id, request).subscribe({
      next: () => {
        this.snackBar.open('Consentement mis à jour avec succès', 'Fermer', {
          duration: 3000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['success-snackbar']
        });
        this.loadConsentements();
      },
      error: (err) => {
        const errorMessage = err.error?.message || 'Échec de la mise à jour du consentement';
        this.snackBar.open(errorMessage, 'Fermer', {
          duration: 5000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['error-snackbar']
        });
        console.error('Error updating consentement:', err);
      }
    });
  }

  getMessagesSorted(): MessageResponse[] {
    return this.messages.slice().sort((a, b) => {
      const dateA = new Date(a.timestamp).getTime();
      const dateB = new Date(b.timestamp).getTime();
      return dateB - dateA;
    });
  }

  /** Fil chronologique onglet Messages (pattern ds-messaging-thread). */
  getMessagesForDsThread(): DsMessage[] {
    const lead = this.dossier?.leadName || 'Prospect';
    return this.getMessagesSorted().map((m) => ({
      id: m.id,
      content: this.truncateContent(m.content),
      direction: m.direction === MessageDirection.INBOUND ? 'inbound' : 'outbound',
      time: this.formatMessageTimestamp(m.timestamp),
      senderName: m.direction === MessageDirection.INBOUND ? lead : undefined
    }));
  }

  openMessageDialog(): void {
    if (!this.dossier) {
      return;
    }

    const dialogData: MessageFormData = {
      dossierId: this.dossier.id
    };

    const dialogRef = this.dialog.open(MessageFormDialogComponent, {
      width: '500px',
      maxWidth: '100vw',
      maxHeight: '100vh',
      panelClass: 'responsive-dialog',
      data: dialogData
    });

    dialogRef.afterClosed().subscribe((result: MessageCreateRequest) => {
      if (result) {
        this.createMessage(result);
      }
    });
  }

  createMessage(request: MessageCreateRequest): void {
    this.messageApiService.create(request).subscribe({
      next: (newMessage) => {
        this.snackBar.open('Message créé avec succès', 'Fermer', {
          duration: 3000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['success-snackbar']
        });
        this.messages = [newMessage, ...this.messages];
      },
      error: (err) => {
        const errorMessage = err.error?.message || 'Échec de la création du message';
        this.snackBar.open(errorMessage, 'Fermer', {
          duration: 5000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['error-snackbar']
        });
        console.error('Error creating message:', err);
      }
    });
  }

  formatMessageTimestamp(timestamp: string): string {
    const date = new Date(timestamp);
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return `${day}/${month}/${year} ${hours}:${minutes}`;
  }

  truncateContent(content: string, maxLength = 200): string {
    if (content.length <= maxLength) {
      return content;
    }
    return content.substring(0, maxLength) + '...';
  }

  shouldShowVoirPlus(content: string, maxLength = 200): boolean {
    return content.length > maxLength;
  }

  getChannelBadgeClass(channel: string): string {
    switch (channel) {
      case 'EMAIL': return 'channel-badge channel-email';
      case 'SMS': return 'channel-badge channel-sms';
      case 'PHONE': return 'channel-badge channel-phone';
      case 'WHATSAPP': return 'channel-badge channel-whatsapp';
      case 'CHAT': return 'channel-badge channel-chat';
      case 'IN_APP': return 'channel-badge channel-inapp';
      case 'WEB': return 'channel-badge channel-web';
      default: return 'channel-badge';
    }
  }

  getDirectionBadgeClass(direction: string): string {
    return direction === 'INBOUND' ? 'direction-badge direction-inbound' : 'direction-badge direction-outbound';
  }

  getRdvStatusBadgeClass(status: string): string {
    switch (status) {
      case 'SCHEDULED': return 'status-badge status-scheduled';
      case 'CONFIRMED': return 'status-badge status-confirmed';
      case 'COMPLETED': return 'status-badge status-completed';
      case 'CANCELLED': return 'status-badge status-cancelled';
      default: return 'status-badge';
    }
  }

  getRdvStatusLabel(status: string): string {
    switch (status) {
      case 'SCHEDULED': return 'Planifié';
      case 'CONFIRMED': return 'Confirmé';
      case 'COMPLETED': return 'Terminé';
      case 'CANCELLED': return 'Annulé';
      default: return status;
    }
  }

  getRoleLabel(role: PartiePrenanteRole): string {
    switch (role) {
      case PartiePrenanteRole.LEAD: return 'Lead';
      case PartiePrenanteRole.BUYER: return 'Acheteur';
      case PartiePrenanteRole.SELLER: return 'Vendeur';
      case PartiePrenanteRole.AGENT: return 'Agent';
      case PartiePrenanteRole.OWNER: return 'Propriétaire';
      case PartiePrenanteRole.TENANT: return 'Locataire';
      case PartiePrenanteRole.LANDLORD: return 'Bailleur';
      case PartiePrenanteRole.NOTARY: return 'Notaire';
      case PartiePrenanteRole.BANK: return 'Banque';
      case PartiePrenanteRole.ATTORNEY: return 'Avocat';
      default: return role;
    }
  }

  getRoleBadgeClass(role: PartiePrenanteRole): string {
    switch (role) {
      case PartiePrenanteRole.BUYER: return 'role-badge-buyer';
      case PartiePrenanteRole.SELLER: return 'role-badge-seller';
      case PartiePrenanteRole.AGENT: return 'role-badge-agent';
      case PartiePrenanteRole.OWNER: return 'role-badge-owner';
      case PartiePrenanteRole.TENANT: return 'role-badge-tenant';
      case PartiePrenanteRole.LANDLORD: return 'role-badge-landlord';
      case PartiePrenanteRole.NOTARY: return 'role-badge-notary';
      case PartiePrenanteRole.BANK: return 'role-badge-bank';
      case PartiePrenanteRole.ATTORNEY: return 'role-badge-attorney';
      case PartiePrenanteRole.LEAD: return 'role-badge-lead';
      default: return 'role-badge-default';
    }
  }

  getAppointmentStatusBadgeClass(status: AppointmentStatus): string {
    switch (status) {
      case AppointmentStatus.SCHEDULED: return 'status-badge status-scheduled';
      case AppointmentStatus.COMPLETED: return 'status-badge status-completed';
      case AppointmentStatus.CANCELLED: return 'status-badge status-cancelled';
      default: return 'status-badge';
    }
  }

  getAppointmentStatusLabel(status: AppointmentStatus): string {
    switch (status) {
      case AppointmentStatus.SCHEDULED: return 'Planifié';
      case AppointmentStatus.COMPLETED: return 'Terminé';
      case AppointmentStatus.CANCELLED: return 'Annulé';
      default: return status;
    }
  }

  formatAppointmentDateTime(dateTime: string): string {
    if (!dateTime) {
      return '—';
    }
    const date = new Date(dateTime);
    return date.toLocaleString('fr-FR', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  getConsentementStatusLabel(status: ConsentementStatus): string {
    switch (status) {
      case ConsentementStatus.GRANTED: return 'Accordé';
      case ConsentementStatus.DENIED: return 'Refusé';
      case ConsentementStatus.REVOKED: return 'Révoqué';
      case ConsentementStatus.PENDING: return 'En attente';
      case ConsentementStatus.EXPIRED: return 'Expiré';
      default: return status;
    }
  }

  getConsentementStatusBadgeClass(status: ConsentementStatus): string {
    switch (status) {
      case ConsentementStatus.GRANTED: return 'consent-badge consent-granted';
      case ConsentementStatus.DENIED: return 'consent-badge consent-denied';
      case ConsentementStatus.REVOKED: return 'consent-badge consent-revoked';
      case ConsentementStatus.PENDING: return 'consent-badge consent-pending';
      case ConsentementStatus.EXPIRED: return 'consent-badge consent-expired';
      default: return 'consent-badge';
    }
  }

  getChannelLabel(channel: ConsentementChannel): string {
    switch (channel) {
      case ConsentementChannel.EMAIL: return 'Email';
      case ConsentementChannel.SMS: return 'SMS';
      case ConsentementChannel.PHONE: return 'Téléphone';
      case ConsentementChannel.WHATSAPP: return 'WhatsApp';
      case ConsentementChannel.POSTAL_MAIL: return 'Courrier postal';
      case ConsentementChannel.IN_PERSON: return 'En personne';
      default: return channel;
    }
  }

  getConsentementsHistory(): ConsentementResponse[] {
    return this.consentements.slice().sort((a, b) => {
      const dateA = new Date(a.updatedAt).getTime();
      const dateB = new Date(b.updatedAt).getTime();
      return dateB - dateA;
    });
  }

  getUserFromMeta(consent: ConsentementResponse): string {
    if (consent.meta && consent.meta['user']) {
      return consent.meta['user'];
    }
    return '—';
  }

  getConsentDate(consent: ConsentementResponse): string {
    if (consent.status === ConsentementStatus.GRANTED && consent.createdAt) {
      return this.formatDate(consent.createdAt);
    }
    if (consent.status === ConsentementStatus.REVOKED && consent.updatedAt) {
      return this.formatDate(consent.updatedAt);
    }
    return this.formatDate(consent.updatedAt);
  }

  getScoreDisplay(): string {
    if (!this.dossier) {
      return '—';
    }
    if (this.dossier.score !== undefined && this.dossier.score !== null) {
      return String(this.dossier.score);
    }
    return '—';
  }

  hasEmptyFields(): boolean {
    if (!this.dossier) {
      return false;
    }
    const emptyFields = [];

    if (!this.dossier.leadName) {
      emptyFields.push('leadName');
    }
    if (!this.dossier.leadSource) {
      emptyFields.push('leadSource');
    }

    return emptyFields.length > 0;
  }

  getEmptyFieldsList(): string {
    if (!this.dossier) {
      return '';
    }
    const emptyFields = [];

    if (!this.dossier.leadName) {
      emptyFields.push('Nom du prospect');
    }
    if (!this.dossier.leadSource) {
      emptyFields.push('Source du prospect');
    }

    return emptyFields.join(', ');
  }

  loadWhatsAppMessages(): void {
    const id = this.route.snapshot.paramMap.get('id');
    if (!id) {
      return;
    }

    const dossierId = parseInt(id, 10);
    if (isNaN(dossierId)) {
      return;
    }

    this.loadingWhatsAppMessages = true;
    this.messageApiService.list({
      dossierId,
      channel: MessageChannel.WHATSAPP,
      size: 100,
      sort: 'timestamp,asc'
    }).subscribe({
      next: (response) => {
        this.whatsappMessages = response.content;
        this.loadingWhatsAppMessages = false;
      },
      error: (err) => {
        console.error('Error loading WhatsApp messages:', err);
        this.loadingWhatsAppMessages = false;
      }
    });
  }

  onTemplateSelect(): void {
    if (this.selectedTemplate) {
      this.initializeTemplateVariables();
      this.updateWhatsAppPreview();
    } else {
      this.templateVariables = {};
      this.whatsappMessageContent = '';
    }
  }

  initializeTemplateVariables(): void {
    if (!this.selectedTemplate) {
      return;
    }

    this.templateVariables = {};
    this.selectedTemplate.variables.forEach(variable => {
      if (variable === 'name' && this.dossier?.leadName) {
        this.templateVariables[variable] = this.dossier.leadName;
      } else {
        this.templateVariables[variable] = '';
      }
    });
  }

  updateWhatsAppPreview(): void {
    if (!this.selectedTemplate) {
      this.whatsappMessageContent = '';
      return;
    }

    let preview = this.selectedTemplate.content;
    this.selectedTemplate.variables.forEach(variable => {
      const value = this.templateVariables[variable] || `{{${variable}}}`;
      preview = preview.replace(`{{${variable}}}`, value);
    });
    this.whatsappMessageContent = preview;
  }

  onVariableChange(): void {
    this.updateWhatsAppPreview();
  }

  canSendWhatsAppMessage(): boolean {
    if (!this.whatsappMessageContent || this.whatsappMessageContent.trim() === '') {
      return false;
    }

    if (this.selectedTemplate) {
      const hasEmptyVariables = this.selectedTemplate.variables.some(
        variable => !this.templateVariables[variable] || this.templateVariables[variable].trim() === ''
      );
      if (hasEmptyVariables) {
        return false;
      }
    }

    return true;
  }

  getWhatsAppConsentStatus(): ConsentementStatus | null {
    const whatsappConsent = this.consentements.find(
      c => c.channel === ConsentementChannel.WHATSAPP
    );
    return whatsappConsent?.status || null;
  }

  isWhatsAppConsentGranted(): boolean {
    return this.getWhatsAppConsentStatus() === ConsentementStatus.GRANTED;
  }

  sendWhatsAppMessage(): void {
    if (!this.dossier || !this.canSendWhatsAppMessage()) {
      return;
    }

    if (!this.isWhatsAppConsentGranted()) {
      this.snackBar.open(
        '⚠️ Le consentement WhatsApp n\'est pas accordé. Veuillez obtenir le consentement avant d\'envoyer un message.',
        'Fermer',
        {
          duration: 5000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['warning-snackbar']
        }
      );
      return;
    }

    this.sendingWhatsAppMessage = true;

    const request: MessageCreateRequest = {
      dossierId: this.dossier.id,
      channel: MessageChannel.WHATSAPP,
      direction: MessageDirection.OUTBOUND,
      content: this.whatsappMessageContent,
      timestamp: new Date().toISOString(),
      templateId: this.selectedTemplate?.id,
      templateVariables: this.selectedTemplate ? this.templateVariables : undefined
    };

    this.messageApiService.create(request).subscribe({
      next: (newMessage) => {
        this.snackBar.open('Message WhatsApp envoyé avec succès', 'Fermer', {
          duration: 3000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['success-snackbar']
        });
        this.whatsappMessages.push(newMessage);
        this.resetWhatsAppForm();
        this.sendingWhatsAppMessage = false;
      },
      error: (err) => {
        const errorMessage = err.error?.message || 'Échec de l\'envoi du message WhatsApp';
        this.snackBar.open(errorMessage, 'Fermer', {
          duration: 5000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['error-snackbar']
        });
        console.error('Error sending WhatsApp message:', err);
        this.sendingWhatsAppMessage = false;
      }
    });
  }

  resetWhatsAppForm(): void {
    this.selectedTemplate = null;
    this.templateVariables = {};
    this.whatsappMessageContent = '';
  }

  retryWhatsAppMessage(message: MessageResponse): void {
    if (message.deliveryStatus !== MessageDeliveryStatus.FAILED) {
      return;
    }

    this.messageApiService.retry(message.id).subscribe({
      next: (updatedMessage) => {
        this.snackBar.open('Message en cours de renvoi...', 'Fermer', {
          duration: 3000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['success-snackbar']
        });
        const index = this.whatsappMessages.findIndex(m => m.id === message.id);
        if (index !== -1) {
          this.whatsappMessages[index] = updatedMessage;
        }
      },
      error: (err) => {
        const errorMessage = err.error?.message || 'Échec du renvoi du message';
        this.snackBar.open(errorMessage, 'Fermer', {
          duration: 5000,
          horizontalPosition: 'center',
          verticalPosition: 'top',
          panelClass: ['error-snackbar']
        });
        console.error('Error retrying message:', err);
      }
    });
  }

  getDeliveryStatusLabel(status: MessageDeliveryStatus): string {
    switch (status) {
      case MessageDeliveryStatus.PENDING: return 'En attente';
      case MessageDeliveryStatus.SENT: return 'Envoyé';
      case MessageDeliveryStatus.DELIVERED: return 'Délivré';
      case MessageDeliveryStatus.FAILED: return 'Échec';
      case MessageDeliveryStatus.READ: return 'Lu';
      default: return 'Inconnu';
    }
  }

  getDeliveryStatusClass(status: MessageDeliveryStatus): string {
    switch (status) {
      case MessageDeliveryStatus.PENDING: return 'delivery-status-pending';
      case MessageDeliveryStatus.SENT: return 'delivery-status-sent';
      case MessageDeliveryStatus.DELIVERED: return 'delivery-status-delivered';
      case MessageDeliveryStatus.FAILED: return 'delivery-status-failed';
      case MessageDeliveryStatus.READ: return 'delivery-status-read';
      default: return '';
    }
  }

  getDeliveryStatusIcon(status: MessageDeliveryStatus): string {
    switch (status) {
      case MessageDeliveryStatus.PENDING: return '⏳';
      case MessageDeliveryStatus.SENT: return '✓';
      case MessageDeliveryStatus.DELIVERED: return '✓✓';
      case MessageDeliveryStatus.FAILED: return '✗';
      case MessageDeliveryStatus.READ: return '✓✓';
      default: return '';
    }
  }

  formatWhatsAppTimestamp(timestamp: string): string {
    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) {
      return 'À l\'instant';
    } else if (diffMins < 60) {
      return `Il y a ${diffMins} min`;
    } else if (diffHours < 24) {
      return `Il y a ${diffHours}h`;
    } else if (diffDays < 7) {
      return `Il y a ${diffDays}j`;
    } else {
      return date.toLocaleDateString('fr-FR', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      });
    }
  }
}

styleUrlsData.data:
/* ====================================================================
   ATLASIA DS - Dossier Detail (Phase 5)
   Toutes les classes mappees sur les tokens --ds-* uniquement.
   ==================================================================== */

/* Layout */
.page-container {
  padding: var(--ds-space-8);
  max-width: var(--ds-content-full, 1280px);
  margin: 0 auto;
}
.page-content { width: 100%; }

/* ── ds-entity-detail-layout (pilote 4.3) ── */
.dd-layout {
  display: block;
}
.dd-topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--ds-space-3);
  width: 100%;
}
.dd-left-stack {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-4);
}
.dd-meta-card .dd-meta-body {
  padding: var(--ds-space-4);
}
.dd-center-stack {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-5);
  min-width: 0;
}
.messages-thread-card {
  display: block;
}

/* Retour */
.link-back {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12.5px; color: var(--ds-marine);
  font-weight: 600; cursor: pointer; user-select: none;
  text-decoration: none;
}
.link-back:hover { text-decoration: underline; }
.arrow-left { font-size: 14px; }

/* En-tête : topbar + carte résumé (colonnes layout) */
.title-and-badge { display: flex; align-items: center; gap: var(--ds-space-3); flex-wrap: wrap; }
.dossier-title {
  font-size: 20px; font-weight: 700;
  color: var(--ds-text); margin: 0;
  font-family: var(--ds-font-display, var(--ds-font-body));
}
.header-line-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: var(--ds-space-4) var(--ds-space-5);
}
.metadata-item { display: flex; flex-direction: column; gap: 2px; }
.metadata-label {
  font-size: 11px; font-weight: 700;
  color: var(--ds-text-faint); text-transform: uppercase;
  letter-spacing: 0.6px;
}
.metadata-value { font-size: 13.5px; color: var(--ds-text); }

/* Boutons DS-aligned */
.btn-change-status-secondary,
.btn-update-status,
.btn-cancel,
.btn-retry,
.btn-add-lead,
.btn-update-lead,
.btn-add,
.btn-edit,
.btn-delete,
.btn-complete,
.btn-icon,
.btn-icon-action,
.btn-reset,
.btn-send-whatsapp {
  height: 36px;
  padding: 0 14px;
  border-radius: var(--ds-radius-md, 8px);
  font-family: var(--ds-font-body);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center;
  gap: 6px;
  border: 1px solid var(--ds-divider);
  background: var(--ds-surface);
  color: var(--ds-text);
  transition: background var(--ds-transition-fast), color var(--ds-transition-fast);
}
.btn-change-status-secondary:hover,
.btn-cancel:hover,
.btn-retry:hover,
.btn-add:hover,
.btn-edit:hover,
.btn-icon:hover,
.btn-icon-action:hover,
.btn-reset:hover { background: var(--ds-surface-offset); }

.btn-update-status,
.btn-update-lead,
.btn-add-lead,
.btn-send-whatsapp {
  background: var(--ds-marine);
  color: var(--ds-text-inverse);
  border-color: var(--ds-marine);
}
.btn-update-status:hover:not(:disabled),
.btn-update-lead:hover:not(:disabled),
.btn-add-lead:hover:not(:disabled),
.btn-send-whatsapp:hover:not(:disabled) { background: var(--ds-marine-hover, var(--ds-marine-hover)); }

.btn-delete { color: var(--ds-error); border-color: var(--ds-error); background: transparent; }
.btn-delete:hover { background: rgba(198,40,40,.08); }
.btn-complete { color: var(--ds-success); border-color: var(--ds-success); background: transparent; }
.btn-complete:hover { background: rgba(46,125,50,.08); }

button:disabled { opacity: 0.5; cursor: not-allowed; }

.btn-icon, .btn-icon-action { width: 36px; height: 36px; padding: 0; }

/* Spinner */
.spinner-small {
  width: 14px; height: 14px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: ds-spin 0.7s linear infinite;
}
@keyframes ds-spin { to { transform: rotate(360deg); } }

/* Messages d'etat */
.success-message,
.error-message,
.warning-message {
  padding: 12px 14px;
  border-radius: var(--ds-radius-md, 8px);
  font-size: 13px;
  border: 1px solid transparent;
}
.success-message { background: rgba(46,125,50,.08); color: var(--ds-success); border-color: var(--ds-success); }
.error-message   { background: rgba(198,40,40,.08); color: var(--ds-error);   border-color: var(--ds-error); }
.warning-message { background: rgba(230,81,0,.08);  color: var(--ds-warning); border-color: var(--ds-warning); }
.error-state {
  display: flex; flex-direction: column; align-items: center; gap: var(--ds-space-3);
  padding: var(--ds-space-8);
}

/* Coach Virtuel */
.coach-virtuel-card {
  display: flex; gap: var(--ds-space-3);
  padding: 14px 16px;
  background: linear-gradient(135deg, rgba(13,44,74,.04) 0%, rgba(175,97,30,.04) 100%);
  border: 1px solid var(--ds-divider);
  border-left: 3px solid var(--ds-primary);
  border-radius: var(--ds-radius-md, 8px);
}
.coach-icon-container {
  width: 36px; height: 36px;
  border-radius: var(--ds-radius-md, 8px);
  background: var(--ds-primary-hl);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.coach-icon { font-size: 18px; }
.coach-content { flex: 1; }
.coach-header-row { display: flex; align-items: center; gap: 8px; }
.coach-title { margin: 0; font-size: 13px; font-weight: 700; color: var(--ds-text); }
.coach-message { margin: 4px 0 0; font-size: 13px; line-height: 1.5; color: var(--ds-text-muted); }
.explainer-icon { font-size: 14px !important; width: 14px !important; height: 14px !important; color: var(--ds-text-faint); cursor: help; }

/* Status change form */
.status-change-section,
.lead-form-section {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-lg, 12px);
  padding: var(--ds-space-4);
  display: flex; flex-direction: column; gap: var(--ds-space-3);
}
.status-change-form,
.lead-form,
.form-actions {
  display: flex; gap: var(--ds-space-2); flex-wrap: wrap; align-items: flex-end;
}
.form-group { display: flex; flex-direction: column; gap: 4px; flex: 1; min-width: 200px; }
.form-label {
  font-size: 11px; font-weight: 700;
  color: var(--ds-text-faint); text-transform: uppercase;
  letter-spacing: 0.6px;
}
.form-select,
.form-input {
  height: 36px;
  padding: 0 12px;
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md, 8px);
  background: var(--ds-surface);
  color: var(--ds-text);
  font-family: var(--ds-font-body); font-size: 13px;
  transition: border-color var(--ds-transition-fast);
}
.form-select:focus,
.form-input:focus { outline: 2px solid var(--ds-marine); outline-offset: 1px; border-color: var(--ds-marine); }

/* Onglet contenu */
.tab-content-host { margin-top: var(--ds-space-4); }
.tab-content { display: flex; flex-direction: column; gap: var(--ds-space-4); }

/* Cartes dossier (ds-card) */
.info-section,
.info-section-essential,
ds-card.info-section,
ds-card.info-section-essential,
ds-card.collab-notes-card {
  display: block;
}

ds-card.info-section > .ds-card,
ds-card.info-section-essential > .ds-card,
ds-card.collab-notes-card > .ds-card {
  background: var(--ds-surface) !important;
  border: 1px solid var(--ds-divider) !important;
  border-radius: var(--ds-radius-lg, 12px) !important;
  box-shadow: none !important;
}

.info-section-header {
  padding: 14px 18px 10px !important;
  border-bottom: 1px solid var(--ds-divider);
}

.info-section-title {
  margin: 0;
  font-size: 13px !important;
  font-weight: 700 !important;
  color: var(--ds-text) !important;
  letter-spacing: 0.2px;
  text-transform: uppercase;
}

.info-section-body {
  padding: 18px !important;
}

.essential-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--ds-space-4);
}
.essential-item { display: flex; flex-direction: column; gap: 4px; }
.essential-label {
  font-size: 11px; font-weight: 700;
  color: var(--ds-text-faint); text-transform: uppercase;
  letter-spacing: 0.6px;
}
.essential-value { font-size: 13.5px; color: var(--ds-text); }
.essential-empty { color: var(--ds-text-faint); font-style: italic; }
.essential-annonce-ref { color: var(--ds-marine); font-weight: 600; }

.sections-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--ds-space-4);
}

.lead-empty-state {
  display: flex; flex-direction: column; align-items: flex-start; gap: var(--ds-space-3);
}
.lead-empty-message { color: var(--ds-text-muted); margin: 0; font-size: 13px; }

/* Listes (parties prenantes, rendez-vous, consentements) */
.list-section {
  display: flex; flex-direction: column; gap: var(--ds-space-3);
}
.action-buttons {
  display: flex; gap: var(--ds-space-2); flex-wrap: wrap;
}

.party-item,
.appointment-card,
.consent-item {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md, 8px);
  padding: var(--ds-space-3) var(--ds-space-4);
  display: flex; gap: var(--ds-space-3);
  align-items: center; flex-wrap: wrap;
}
.party-item:hover,
.appointment-card:hover,
.consent-item:hover { background: var(--ds-surface-offset); }

.appointment-datetime { font-size: 13px; font-weight: 600; color: var(--ds-text); }
.appointments-section,
.consentements-section {
  display: flex; flex-direction: column; gap: var(--ds-space-3);
}

/* Audit table */
.audit-table {
  width: 100%;
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-lg, 12px);
  overflow: hidden;
  border-collapse: collapse;
}
.audit-table th,
.audit-table td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--ds-divider);
  text-align: left;
  font-size: 13px;
}
.audit-table th {
  background: var(--ds-surface-offset);
  font-size: 10.5px; font-weight: 700;
  color: var(--ds-text-faint);
  letter-spacing: 1px; text-transform: uppercase;
}
.audit-action-badge,
.channel-whatsapp,
.channel-email,
.channel-sms,
.channel-phone,
.channel-chat,
.channel-web,
.channel-inapp {
  display: inline-flex; align-items: center;
  height: 22px; padding: 0 10px;
  background: var(--ds-marine-hl); color: var(--ds-marine);
  border-radius: 99px;
  font-size: 11px; font-weight: 700;
  letter-spacing: 0.5px;
}
.changes-list { display: flex; flex-direction: column; gap: 2px; }
.change-item { font-size: 12px; color: var(--ds-text-muted); }
.change-field { font-weight: 700; color: var(--ds-text); }
.change-arrow { color: var(--ds-text-faint); }
.change-old { color: var(--ds-error); text-decoration: line-through; }
.change-new { color: var(--ds-success); }
.audit-filters { display: flex; gap: var(--ds-space-2); flex-wrap: wrap; align-items: center; }
.audit-date { font-size: 11.5px; color: var(--ds-text-faint); white-space: nowrap; }

/* Chat / WhatsApp bubbles */
.chat-messages { display: flex; flex-direction: column; gap: var(--ds-space-2); padding: var(--ds-space-3); }
.chat-bubble { display: flex; max-width: 85%; }
.chat-bubble-inbound  { align-self: flex-start; }
.chat-bubble-outbound { align-self: flex-end; }
.chat-bubble-content {
  padding: 8px 12px; border-radius: 12px;
  background: var(--ds-surface-offset);
  font-size: 13px; color: var(--ds-text);
}
.chat-bubble-outbound .chat-bubble-content {
  background: var(--ds-marine); color: var(--ds-text-inverse);
}
.chat-bubble-meta { font-size: 11px; color: var(--ds-text-faint); margin-top: 4px; }
.chat-bubble-time, .chat-bubble-status, .chat-bubble-retry { font-size: 11px; }
.chat-bubble-text { line-height: 1.4; }

/* Consentements */
.consent-actions { display: flex; gap: var(--ds-space-1); flex-wrap: wrap; }
.consent-btn,
.consent-btn-granted,
.consent-btn-denied,
.consent-btn-revoked {
  height: 28px; padding: 0 10px;
  border: 1px solid var(--ds-divider);
  border-radius: 99px;
  background: transparent;
  font-size: 11.5px; font-weight: 600;
  cursor: pointer;
}
.consent-btn-granted { color: var(--ds-success); border-color: var(--ds-success); }
.consent-btn-denied  { color: var(--ds-error);   border-color: var(--ds-error); }
.consent-btn-revoked { color: var(--ds-warning); border-color: var(--ds-warning); }

/* Collaboration */
.collaboration-section,
.collaboration-panel,
.collaboration-grid {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md, 8px);
  padding: var(--ds-space-2) var(--ds-space-3);
}

/* Composer (messages) */
.composer-actions {
  display: flex; gap: var(--ds-space-2);
  padding: var(--ds-space-2);
  border-top: 1px solid var(--ds-divider);
  align-items: center;
}

/* Empty state generic & advanced filters */
.advanced-content {
  padding: var(--ds-space-3);
  background: var(--ds-surface-offset);
  border-radius: var(--ds-radius-md, 8px);
}

/* Animations legeres */
.slide-in-top { animation: ds-slide-in-top 220ms cubic-bezier(.25,.46,.45,.94); }
@keyframes ds-slide-in-top {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .slide-in-top { animation: none; }
  .spinner-small { animation: none; border-right-color: currentColor; }
}

/* Liens internes */
.link {
  color: var(--ds-marine);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 2px;
}

/* WhatsApp tab */
.whatsapp-tab {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-lg, 12px);
  overflow: hidden;
}

/* Mobile */
@media (max-width: 768px) {
  .page-container { padding: var(--ds-space-4); }
  .dossier-title { font-size: 17px; }
  .header-line-1, .header-line-2 { gap: var(--ds-space-2); }
  .sections-container { grid-template-columns: 1fr; }
  .audit-table th, .audit-table td { padding: 8px 10px; font-size: 12px; }
}

