/* ── Atlasia DS Layout ── */
.pro-page {
  padding: var(--ds-space-8);
  max-width: var(--ds-content-full);
  margin: 0 auto;
}

/* ── Toggle vue ── */
.dos-view-toggle {
  display: flex;
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-sm);
  overflow: hidden;
  background: var(--ds-surface);
}
.dos-view-btn {
  width: 36px;
  height: 32px;
  border: none;
  background: transparent;
  color: var(--ds-text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--ds-transition-fast), color var(--ds-transition-fast);
  &--active { background: var(--ds-marine-hl); color: var(--ds-marine); }
  &:hover:not(&--active) { background: var(--ds-surface-offset); }
}

/* ── Filtres ── */
.dos-filters { margin-bottom: var(--ds-space-5); display: flex; flex-direction: column; gap: var(--ds-space-3); }

.dos-active-filters {
  display: flex;
  align-items: center;
  gap: var(--ds-space-2);
  flex-wrap: wrap;
}
.dos-filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.dos-filter-chip__remove {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--ds-text-muted);
  padding: 2px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--ds-radius-sm);
  line-height: 0;
  &:hover {
    color: var(--ds-text);
    background: var(--ds-surface-offset);
  }
}
.dos-clear-all {
  background: none;
  border: none;
  color: var(--ds-text-muted);
  font-size: 12px;
  cursor: pointer;
  text-decoration: underline;
  padding: 0;
  &:hover { color: var(--ds-error); }
}

/* ── Skeleton ── */
.dos-skeleton-list { display: flex; flex-direction: column; gap: var(--ds-space-2); }

/* ── Erreur ── */
.dos-error {
  padding: 14px 18px;
  background: var(--ds-error-hl);
  color: var(--ds-error);
  border-radius: var(--ds-radius-md);
  font-size: 13.5px;
}

/* ── Liste desktop : ds-card + ds-table ── */
.dos-list-card {
  border-radius: var(--ds-radius-lg);
  overflow: hidden;
}

/* Cellules rendues en HTML (ds-table) */
.dos-ds-lead-cell {
  display: inline-flex;
  align-items: center;
  gap: var(--ds-space-3);
  min-width: 0;
  max-width: 100%;
}
.dos-ds-lead-cell__ava {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--ds-marine-hl);
  color: var(--ds-marine);
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.dos-ds-lead-cell__meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.dos-ds-lead-cell__name {
  font-weight: 600;
  font-size: 13.5px;
  color: var(--ds-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dos-ds-lead-cell__id {
  font-size: 11px;
  color: var(--ds-text-faint);
}
.dos-ds-phone {
  font-size: 13px;
  color: var(--ds-text-muted);
}
.dos-ds-date {
  font-size: 12px;
  color: var(--ds-text-faint);
}
.dos-ds-annonce {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--ds-marine);
}
.dos-ds-empty {
  color: var(--ds-text-faint);
}

/* Badges statut (innerHTML) : taille icône Material */
.dos-list-card .status-icon {
  font-size: 14px;
  vertical-align: middle;
  margin-right: 4px;
}

/* ── Pagination ── */
.dos-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px var(--ds-space-4);
  border-top: 1px solid var(--ds-divider);
  &__info { font-size: 12.5px; color: var(--ds-text-muted); }
  &__btns { display: flex; gap: var(--ds-space-1); }
  &__btn {
    width: 32px;
    height: 32px;
    border: 1px solid var(--ds-divider);
    border-radius: var(--ds-radius-sm);
    background: var(--ds-surface);
    cursor: pointer;
    color: var(--ds-text-muted);
    font-size: 16px;
    transition: background var(--ds-transition-fast);
    &:hover:not(:disabled) { background: var(--ds-surface-offset); }
    &:disabled { opacity: 0.4; cursor: not-allowed; }
  }
}

/* ── Kanban ── */
.dos-kanban-wrap { display: flex; flex-direction: column; gap: var(--ds-space-4); }
.dos-kanban-search { max-width: 380px; }

/* ── Mobile ── */
.dos-mobile-list { display: flex; flex-direction: column; gap: var(--ds-space-3); }

