import { Component, Input } from '@angular/core';
import { CommonModule } from '@angular/common';

export type DsBadgeStatus =
  | 'new' | 'qualification' | 'rdv' | 'won' | 'lost'
  | 'draft' | 'active' | 'paused' | 'archived'
  | 'success' | 'warning' | 'error' | 'info' | 'neutral';

@Component({
  selector: 'ds-badge',
  standalone: true,
  imports: [CommonModule],
  template: `
    <span [class]="classes" [attr.aria-label]="ariaLabel || null">
      @if (showDot) {
        <span class="ds-badge__dot" aria-hidden="true"></span>
      }
      <ng-content></ng-content>
    </span>
  `,
})
export class DsBadgeComponent {
  @Input() status: DsBadgeStatus = 'neutral';
  @Input() size: 'sm' | 'md' = 'md';
  @Input() ariaLabel: string | null = null;
  /** Affiche le point d’état (par défaut oui). Désactiver quand une icône est injectée via ng-content. */
  @Input() showDot = true;
  /** Animation légère pour les statuts « vivants » (nouveau, actif publié…). */
  @Input() pulse = false;

  get classes(): string {
    const parts = ['ds-badge', `ds-badge--${this.status}`, `ds-badge--${this.size}`];
    if (!this.showDot) {
      parts.push('ds-badge--no-dot');
    }
    if (this.pulse) {
      parts.push('ds-badge--pulse');
    }
    return parts.join(' ');
  }
}

import { Component, Input, Output, EventEmitter, HostListener } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatRippleModule } from '@angular/material/core';

export type DsButtonVariant = 'marine' | 'copper' | 'ghost' | 'danger' | 'icon';
export type DsButtonSize = 'sm' | 'md' | 'lg';

@Component({
  selector: 'ds-button',
  standalone: true,
  imports: [CommonModule, MatRippleModule],
  template: `
    <button
      [attr.type]="nativeType"
      [class]="classes"
      [disabled]="disabled || loading"
      [attr.aria-busy]="loading"
      [attr.aria-label]="ariaLabel || null"
      matRipple
      [matRippleColor]="rippleColor"
      [matRippleDisabled]="disabled || loading"
      (click)="onClick($event)">
      @if (loading) {
        <span class="ds-btn__spinner" aria-hidden="true"></span>
      }
      @if (!loading && prefixIcon) {
        <span class="ds-btn__icon" aria-hidden="true" [innerHTML]="prefixIcon"></span>
      }
      <ng-content></ng-content>
    </button>
  `,
  styleUrls: ['./ds-button.component.scss'],
})
export class DsButtonComponent {
  /** Par défaut `button` pour éviter une soumission involontaire dans les <form>. */
  @Input() nativeType: 'button' | 'submit' | 'reset' = 'button';
  @Input() variant: DsButtonVariant = 'marine';
  @Input() size: DsButtonSize = 'md';
  @Input() disabled = false;
  @Input() loading = false;
  @Input() prefixIcon: string | null = null;
  @Input() ariaLabel: string | null = null;
  @Output() dsClick = new EventEmitter<MouseEvent>();

  get classes(): string {
    return [
      'ds-btn',
      `ds-btn--${this.variant}`,
      `ds-btn--${this.size}`,
      this.loading ? 'ds-btn--loading' : '',
      this.disabled ? 'ds-btn--disabled' : '',
    ].filter(Boolean).join(' ');
  }

  get rippleColor(): string {
    const map: Record<DsButtonVariant, string> = {
      marine:  'rgba(255,255,255,0.15)',
      copper:  'rgba(255,255,255,0.15)',
      ghost:   'rgba(13,44,74,0.08)',
      danger:  'rgba(255,255,255,0.15)',
      icon:    'rgba(13,44,74,0.08)',
    };
    return map[this.variant] ?? 'rgba(0,0,0,0.06)';
  }

  onClick(event: MouseEvent): void {
    if (!this.disabled && !this.loading) {
      this.dsClick.emit(event);
    }
  }
}

styleUrlsData.data:
.ds-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--ds-space-2);
  border: none;
  border-radius: var(--ds-radius-md);
  font-family: var(--ds-font-body);
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition:
    background var(--ds-transition-fast),
    box-shadow var(--ds-transition-fast),
    transform var(--ds-transition-fast);

  &:focus-visible {
    outline: 2px solid var(--ds-marine);
    outline-offset: 2px;
  }

  /* ── Sizes ── */
  &--sm  { height: 32px; padding: 0 12px; font-size: 13px; }
  &--md  { height: 40px; padding: 0 var(--ds-space-4); font-size: 14px; }
  &--lg  { height: 48px; padding: 0 var(--ds-space-5); font-size: 15px; }

  /* ── Variants ── */
  &--marine {
    background: var(--ds-marine);
    color: var(--ds-text-inverse);
    &:hover:not(:disabled) {
      background: var(--ds-marine-hover);
      box-shadow: var(--ds-shadow-sm);
    }
  }

  &--copper {
    background: var(--ds-primary);
    color: var(--ds-text-inverse);
    &:hover:not(:disabled) {
      background: var(--ds-primary-hover);
      box-shadow: var(--ds-shadow-sm);
    }
  }

  &--ghost {
    background: transparent;
    color: var(--ds-text);
    border: 1px solid var(--ds-border);
    &:hover:not(:disabled) {
      background: var(--ds-surface-offset);
    }
  }

  &--danger {
    background: var(--ds-error);
    color: var(--ds-text-inverse);
    &:hover:not(:disabled) {
      background: color-mix(in srgb, var(--ds-error) 88%, var(--ds-text) 12%);
    }
  }

  &--icon {
    width: 36px;
    height: 36px;
    padding: 0;
    border-radius: var(--ds-radius-sm);
    background: transparent;
    color: var(--ds-text-muted);
    border: 1px solid var(--ds-border);
    font-size: 14px;
    &:hover:not(:disabled) {
      background: var(--ds-surface-offset);
      color: var(--ds-text);
    }
  }

  /* ── States ── */
  &--disabled,
  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    pointer-events: none;
  }

  &--loading {
    cursor: wait;
    pointer-events: none;
    .ds-btn__icon { display: none; }
  }

  /* ── Spinner ── */
  &__spinner {
    width: 14px;
    height: 14px;
    border: 2px solid rgba(255, 255, 255, 0.35);
    border-top-color: var(--ds-text-inverse);
    border-radius: 50%;
    animation: ds-spin 0.7s linear infinite;
  }

  &--ghost &__spinner {
    border-color: rgba(13, 44, 74, 0.2);
    border-top-color: var(--ds-marine);
  }
}

@keyframes ds-spin {
  to { transform: rotate(360deg); }
}

