  @Input() size: DsIconSize = 20;
  @Input() ariaLabel = '';

  svgContent: SafeHtml = '';

  constructor(private sanitizer: DomSanitizer) {}

  ngOnChanges(): void {
    const path = ICONS[this.name] ?? ICONS['info'];
