:host {
  display: block;
  width: 100%;
}

.ds-field {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-1);

  &__label {
    font-size: 11px;
    font-weight: 600;
    color: var(--ds-text-muted);
    letter-spacing: 1.2px;
    text-transform: uppercase;
  }

  &__wrap {
    position: relative;
  }

  &__prefix {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--ds-text-faint);
    display: flex;
    pointer-events: none;
  }

  &__input {
    height: 42px;
    width: 100%;
    border-radius: var(--ds-radius-md);
    border: 1px solid var(--ds-divider);
    background: var(--ds-surface);
    padding: 0 14px;
    font-family: var(--ds-font-body);
    font-size: 14px;
    color: var(--ds-text);
    outline: none;
    transition: border-color var(--ds-transition-fast), box-shadow var(--ds-transition-fast);

    &::placeholder { color: var(--ds-text-faint); }

    &:focus {
      border-color: var(--ds-marine);
      box-shadow: 0 0 0 4px var(--ds-marine-hl);
    }

    &:disabled {
      opacity: 0.45;
      cursor: not-allowed;
    }

    &--has-prefix { padding-left: 36px; }
  }

  &--error &__input {
    border-color: var(--ds-error);
    &:focus { box-shadow: 0 0 0 4px var(--ds-error-hl); }
  }

  &__error {
    font-size: 12px;
    color: var(--ds-error);
    margin: 0;
  }
}

