@keyframes ds-shimmer {
  0%   { background-position: -400px 0; }
  100% { background-position: 400px 0; }
}

.ds-skeleton {
  background: linear-gradient(
    90deg,
    var(--ds-surface-offset) 25%,
    var(--ds-surface-dynamic) 50%,
    var(--ds-surface-offset) 75%
  );
  background-size: 800px 100%;
  animation: ds-shimmer 1.4s ease-in-out infinite;
  border-radius: var(--ds-radius-sm);

  &--text    { height: 14px; width: 100%; margin-bottom: var(--ds-space-2); }
  &--heading { height: 24px; width: 60%; margin-bottom: var(--ds-space-3); }
  &--rect    { width: 100%; height: 120px; }
  &--circle  { width: 40px; height: 40px; border-radius: 50%; }
  &--card    { width: 100%; height: 180px; border-radius: var(--ds-radius-lg); }

  &--static {
    animation: none;
    background: var(--ds-surface-offset);
  }
}

