import { Component, Inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA, MatSnackBarRef } from '@angular/material/snack-bar';
import { NotificationConfig } from '../services/notification.service';
import { trigger, state, style, transition, animate } from '@angular/animations';
import { MatIcon } from '@angular/material/icon';
import { MatButton, MatIconButton } from '@angular/material/button';

@Component({
    selector: 'app-enhanced-snackbar',
    template: `
    <div class="enhanced-snackbar-content" [@slideIn]="animationState" [class.critical]="data.priority === 'critical'">
      <div class="snackbar-icon" [class]="'icon-' + data.type">
        @if (data.type === 'success') {
          <mat-icon>check_circle</mat-icon>
        }
        @if (data.type === 'error') {
          <mat-icon>error</mat-icon>
        }
        @if (data.type === 'warning') {
          <mat-icon>warning</mat-icon>
        }
        @if (data.type === 'info') {
          <mat-icon>info</mat-icon>
        }
      </div>
      <div class="snackbar-message">{{ data.message }}</div>
      <div class="snackbar-actions">
        @if (data.action && data.onAction) {
          <button
            mat-button
            class="snackbar-action-btn"
            (click)="onAction()"
            [attr.aria-label]="data.action">
            {{ data.action }}
          </button>
        }
        @if (data.dismissible) {
          <button
            mat-icon-button
            class="snackbar-close-btn"
            (click)="dismiss()"
            aria-label="Fermer">
            <mat-icon>close</mat-icon>
          </button>
        }
      </div>
    </div>
    `,
    styles: [`
    .enhanced-snackbar-content {
      display: flex;
      align-items: center;
      gap: var(--ds-space-3);
      padding: var(--ds-space-1) var(--ds-space-2);
      min-width: 344px;
      max-width: 568px;
    }

    .enhanced-snackbar-content.critical {
      border-left: 4px solid var(--ds-error);
      padding-left: var(--ds-space-3);
    }

    .snackbar-icon {
      display: flex;
      align-items: center;
      flex-shrink: 0;
    }

    .snackbar-icon mat-icon {
      font-size: 24px;
      width: 24px;
      height: 24px;
    }

    .snackbar-icon.icon-success mat-icon {
      color: var(--ds-success);
    }

    .snackbar-icon.icon-error mat-icon {
      color: var(--ds-error);
    }

    .snackbar-icon.icon-warning mat-icon {
      color: var(--ds-warning);
    }

    .snackbar-icon.icon-info mat-icon {
      color: var(--ds-marine);
    }

    .snackbar-message {
      flex: 1;
      font-size: 14px;
      line-height: 20px;
      font-weight: 400;
    }

    .snackbar-actions {
      display: flex;
      align-items: center;
      gap: var(--ds-space-1);
      flex-shrink: 0;
    }

    .snackbar-action-btn {
      font-weight: 500;
      font-size: 14px;
      text-transform: uppercase;
      letter-spacing: 0.4px;
    }

    .snackbar-close-btn {
      width: 32px;
      height: 32px;
      line-height: 32px;
    }

    .snackbar-close-btn mat-icon {
      font-size: 18px;
      width: 18px;
      height: 18px;
    }

    @media (max-width: 599px) {
      .enhanced-snackbar-content {
        min-width: auto;
        max-width: 100%;
      }
    }
  `],
    animations: [
        trigger('slideIn', [
            state('void', style({ transform: 'translateY(-100%)', opacity: 0 })),
            state('*', style({ transform: 'translateY(0)', opacity: 1 })),
            transition('void => *', animate('300ms cubic-bezier(0, 0, 0.2, 1)')),
            transition('* => void', animate('200ms cubic-bezier(0.4, 0, 1, 1)'))
        ])
    ],
    imports: [MatIcon, MatButton, MatIconButton]
})
export class EnhancedSnackbarComponent {
  animationState = 'in';

  constructor(
    @Inject(MAT_SNACK_BAR_DATA) public data: NotificationConfig & { dismissible: boolean },
    private snackBarRef: MatSnackBarRef<EnhancedSnackbarComponent>
  ) {}

  onAction(): void {
    if (this.data.onAction) {
      this.data.onAction();
    }
    this.dismiss();
  }

  dismiss(): void {
    this.snackBarRef.dismiss();
  }
}

