}

.snackbar-icon.icon-warning mat-icon {
  color: var(--ds-warning);
}

.snackbar-icon.icon-info mat-icon {
  color: var(--ds-marine);
}

.snackbar-message {
  flex: 1;
  font-size: 14px;
  line-height: 20px;
  font-weight: 400;
}

.snackbar-actions {
  display: flex;
  align-items: center;
  gap: var(--ds-space-1);
  flex-shrink: 0;
}

.snackbar-action-btn {
  font-weight: 500;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.snackbar-close-btn {
  width: 32px;
  height: 32px;
  line-height: 32px;
}

.snackbar-close-btn mat-icon {
  font-size: 18px;
  width: 18px;
  height: 18px;
}

@media (max-width: 599px) {
  .enhanced-snackbar-content {
    min-width: auto;
    max-width: 100%;
  }
}

