.ds-detail {
  display: flex;
  flex-direction: column;
  min-height: 100%;

  &__breadcrumb {
    padding: 12px var(--ds-space-8);
    border-bottom: 1px solid var(--ds-divider);
    background: var(--ds-surface);
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
    font-size: 13px;
    color: var(--ds-text-muted);
  }

  &__topbar {
    padding: var(--ds-space-4) var(--ds-space-8);
    border-bottom: 1px solid var(--ds-divider);
    background: var(--ds-surface);
    display: flex;
    align-items: center;
    gap: var(--ds-space-3);
  }

  &__body {
    display: grid;
    grid-template-columns: 360px 1fr 320px;
    gap: var(--ds-space-6);
    padding: var(--ds-space-6) var(--ds-space-8) var(--ds-space-16);
    flex: 1;
    align-items: start;
  }

  &--full &__body {
    grid-template-columns: 360px 1fr;
  }

  &__left,
  &__right {
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-4);
    position: sticky;
    top: var(--ds-space-6);
    max-height: calc(100vh - 120px);
    overflow-y: auto;
  }

  &__center {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: var(--ds-space-4);
  }

  @media (max-width: 1100px) {
    &__body {
      grid-template-columns: 1fr;
    }
    &__left,
    &__right {
      position: static;
      max-height: unset;
    }
  }
}

