@use '../../styles/utilities' as *;

.table-container {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  /* Important:
     Keep a single scroll container for the table (the wrapper).
     Having both the container and wrapper scroll horizontally can
     create header/body desynchronization and duplicate scrollbars. */
  overflow-x: hidden;
}

.table-wrapper {
  position: relative;
  width: 100%;
  min-width: 0;
  /*
    UX decision (Ergo P1):
    - On Desktop, we avoid the permanent horizontal scrollbar that appears even
      when the table is visually fitting.
    - If a screen truly needs horizontal navigation later, we should treat it
      as a dedicated UX pattern (column chooser / responsive columns), not a
      generic always-on scrollbar.
  */
  overflow-y: visible;
  /*
    Scroll horizontal géré par le wrapper:
    - auto: pas de scrollbar si le tableau « fit »
    - garde l'accès à la colonne Actions si l'espace devient insuffisant
  */
  overflow-x: auto;
  max-height: none;

  @include mobile-only {
    max-height: none;
  }
}


/* Table Header with Counter and Pagination */
.table-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-4) var(--spacing-5);
  background: var(--ds-surface-2);
  border-bottom: 1px solid var(--ds-divider);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;

  @include mobile-only {
    padding: var(--spacing-3) var(--spacing-4);
    flex-direction: column;
    gap: var(--spacing-3);
  }
}

.table-counter {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-2);

  .counter-value {
    font-size: var(--font-size-2xl);
    font-weight: var(--font-weight-bold);
    color: var(--ds-marine);
    line-height: 1;
  }

  .counter-label {
    font-size: var(--font-size-base);
    font-weight: var(--font-weight-medium);
    color: var(--ds-text-muted);
  }

  @include mobile-only {
    .counter-value {
      font-size: var(--font-size-xl);
    }
    
    .counter-label {
      font-size: 12px;
    }
  }
}

.table-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);

  button {
    transition: var(--transition-base);

    &:hover:not(:disabled) {
      background-color: var(--ds-marine-hl);
      
      mat-icon {
        color: var(--ds-marine);
      }
    }

    &:disabled {
      opacity: 0.4;
      cursor: not-allowed;
    }
  }

  @include mobile-only {
    gap: var(--spacing-1);
  }
}

.selection-info {
  font-size: 12px;
  color: var(--ds-marine);
  font-weight: var(--font-weight-medium);
  margin-left: var(--spacing-2);

  @include mobile-only {
    font-size: 11px;
  }
}

.table-pagination-controls {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);

  .pagination-range {
    font-size: 12px;
    font-weight: var(--font-weight-medium);
    color: var(--ds-text-muted);
    min-width: 96px;
    text-align: center;

    @include mobile-only {
      min-width: 90px;
      font-size: 11px;
    }
  }

  button {
    transition: var(--transition-base);

    &:hover:not(:disabled) {
      background-color: var(--ds-marine-hl);
      
      mat-icon {
        color: var(--ds-marine);
      }
    }

    &:disabled {
      opacity: 0.4;
    }
  }
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-12) var(--spacing-6);
  text-align: center;

  @include mobile-only {
    padding: var(--spacing-8) var(--spacing-4);
  }

  @include tablet {
    padding: var(--spacing-10) var(--spacing-5);
  }
}

.empty-icon {
  font-size: 64px;
  width: 64px;
  height: 64px;
  color: var(--ds-text-faint);
  margin-bottom: var(--spacing-4);

  @include mobile-only {
    font-size: 48px;
    width: 48px;
    height: 48px;
  }
}

.empty-title {
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-semibold);
  color: var(--ds-text-muted);
  margin: 0 0 var(--spacing-2) 0;

  @include mobile-only {
    font-size: var(--font-size-lg);
  }
}

.empty-message {
  font-size: var(--font-size-base);
  color: var(--ds-text-faint);
  margin: 0;
  max-width: 400px;

  @include mobile-only {
    font-size: 12px;
    max-width: 300px;
  }
}

/* Mobile Card View */
.card-container {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
  padding: var(--spacing-2);

  @include mobile-only {
    gap: var(--spacing-3);
  }
}

/* Virtual Scroll Viewport */
.virtual-scroll-viewport {
  height: 600px;
  width: 100%;

  @include mobile-only {
    height: calc(100vh - 200px);
  }

  .cdk-virtual-scroll-content-wrapper {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-4);

    @include mobile-only {
      gap: var(--spacing-3);
    }
  }
}

.data-card {
  display: block;
  position: relative;

  > .ds-card {
    transition: var(--transition-base);
    cursor: pointer;
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-1);
  }

  &:hover > .ds-card {
    box-shadow: var(--shadow-3);
    transform: translateY(-2px);
  }

  &:active > .ds-card {
    transform: translateY(0);
    box-shadow: var(--shadow-1);
  }
}

.data-card-body {
  padding: var(--spacing-4);
}

.card-selection {
  position: absolute;
  top: var(--spacing-3);
  right: var(--spacing-3);
  z-index: var(--z-default);

  @include mobile-only {
    top: var(--spacing-2);
    right: var(--spacing-2);
  }
}

.card-field {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-1);
  margin-bottom: var(--spacing-3);

  &:last-child {
    margin-bottom: 0;
  }

  @include mobile-only {
    margin-bottom: var(--spacing-2);
  }
}

.field-label {
  font-size: 11px;
  font-weight: var(--font-weight-semibold);
  color: var(--ds-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.field-value {
  font-size: var(--font-size-base);
  color: var(--ds-text);
  word-break: break-word;

  @include mobile-only {
    font-size: 12px;
  }
}

.card-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--spacing-2);
  padding: var(--spacing-2) var(--spacing-4);
  margin: 0 !important;
  border-top: 1px solid var(--ds-divider);

  @include mobile-only {
    padding: var(--spacing-2) var(--spacing-3);
    flex-wrap: wrap;
  }
}

/* Paginator */
mat-paginator {
  background: var(--ds-surface-2);
  border-top: 1px solid var(--ds-border);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
}

/* Material Design Overrides for better integration */
::ng-deep {
  .mat-sort-header-arrow {
    color: var(--ds-marine);
  }

  .mat-checkbox-checked.mat-accent .mat-checkbox-background {
    background-color: var(--ds-marine);
  }

  .mat-checkbox-indeterminate.mat-accent .mat-checkbox-background {
    background-color: var(--ds-marine);
  }

  // Responsive paginator adjustments
  @include mobile-only {
    .mat-mdc-paginator {
      font-size: 11px;
    }

    .mat-mdc-paginator-container {
      flex-wrap: wrap;
      min-height: auto;
      padding: var(--spacing-2);
    }

    .mat-mdc-paginator-page-size {
      margin: var(--spacing-2) 0;
    }

    .mat-mdc-paginator-range-label {
      margin: var(--spacing-2) var(--spacing-3);
    }
  }
}

/* Print Styles */
@media print {
  .card-container .data-card > .ds-card {
    page-break-inside: avoid;
    box-shadow: none;
    border: 1px solid var(--ds-border);
  }
}

/* Prefers reduced motion */
@media (prefers-reduced-motion: reduce) {
  .data-card > .ds-card,
  .data-card {
    transition: none;
    animation: none;
  }

  .data-card:hover > .ds-card {
    transform: none;
  }
}

