.search-container {
  position: relative;
  width: 100%;
  max-width: 600px;

  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
  }
}

.search-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;

  ds-input {
    flex: 1;
    min-width: 0;
  }

  &--has-clear ::ng-deep .ds-field__input {
    padding-right: 40px;
  }
}

.clear-button {
  position: absolute;
  right: 10px;
  z-index: 2;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--ds-text-muted);
  padding: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--ds-radius-sm);
  transition: all 0.2s ease;

  &:hover {
    background-color: var(--ds-bg);
    color: var(--ds-text);
  }

  &:active {
    transform: scale(0.95);
  }
}

.search-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  max-height: 500px;
  overflow-y: auto;
  z-index: 1000;
  animation: slideDown 0.2s ease-out;

  &::-webkit-scrollbar {
    width: 8px;
  }

  &::-webkit-scrollbar-track {
    background: var(--ds-surface-offset);
    border-radius: var(--ds-radius-md);
  }

  &::-webkit-scrollbar-thumb {
    background: var(--ds-border);
    border-radius: var(--ds-radius-md);

    &:hover {
      background: var(--ds-text-faint);
    }
  }
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.loading {
  padding: 24px;
  text-align: center;
  color: var(--ds-text-muted);
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.error {
  padding: 16px;
  text-align: center;
  color: var(--ds-error);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.no-results {
  padding: 32px 24px;
  text-align: center;
  color: var(--ds-text-faint);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;

  svg {
    opacity: 0.5;
  }

  .no-results-text {
    font-size: 16px;
    font-weight: 500;
    color: var(--ds-text-muted);
  }

  .no-results-hint {
    font-size: 13px;
    color: var(--ds-text-faint);
  }
}

.recent-searches {
  padding: 12px 0;
  border-bottom: 1px solid var(--ds-surface-offset);

  .section-header {
    padding: 8px 16px;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    font-weight: 600;
    color: var(--ds-text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .recent-search-list {
    padding: 4px 0;
  }

  .recent-search-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 16px;
    cursor: pointer;
    transition: background-color 0.2s ease;
    color: var(--ds-text-muted);

    svg {
      flex-shrink: 0;
      opacity: 0.6;
    }

    .recent-search-query {
      flex: 1;
      font-size: 14px;
    }

    .remove-recent-btn {
      opacity: 0;
      background: none;
      border: none;
      cursor: pointer;
      padding: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: var(--ds-radius-sm);
      transition: all 0.2s ease;
      color: var(--ds-text-faint);

      &:hover {
        background-color: var(--ds-error-hl);
        color: var(--ds-error);
      }
    }

    &:hover {
      background-color: var(--ds-surface-2);

      .remove-recent-btn {
        opacity: 1;
      }
    }
  }
}

.results {
  padding: 8px 0;
}

.result-group {
  margin-bottom: 8px;

  &:last-child {
    margin-bottom: 0;
  }

  .group-header {
    padding: 10px 16px 6px;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 11px;
    font-weight: 700;
    color: var(--ds-text-muted);
    text-transform: uppercase;
    letter-spacing: 0.8px;
    border-bottom: 1px solid var(--ds-bg);
  }
}

.result-item {
  display: flex;
  align-items: flex-start;
  padding: 12px 16px;
  cursor: pointer;
  transition: all 0.2s ease;
  gap: 12px;
  border-left: 3px solid transparent;

  &:hover,
  &.selected {
    background-color: color-mix(in srgb, var(--ds-success-hl) 45%, var(--ds-surface));
    border-left-color: var(--ds-success);
  }

  &.selected {
    background-color: var(--ds-success-hl);
  }

  .result-icon {
    width: 36px;
    height: 36px;
    border-radius: var(--ds-radius-md);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: transform 0.2s ease;

    &.annonce {
      background: linear-gradient(
        135deg,
        var(--ds-marine-hl) 0%,
        color-mix(in srgb, var(--ds-marine-hl) 55%, var(--ds-marine-light)) 100%
      );
      color: var(--ds-marine-light);
    }

    &.dossier {
      background: linear-gradient(
        135deg,
        var(--ds-primary-subtle) 0%,
        var(--ds-primary-hl) 100%
      );
      color: var(--ds-primary-active);
    }

    &.contact {
      background: linear-gradient(
        135deg,
        var(--ds-warning-hl) 0%,
        color-mix(in srgb, var(--ds-warning-hl) 65%, var(--ds-warning)) 100%
      );
      color: var(--ds-warning);
    }
  }

  &:hover .result-icon {
    transform: scale(1.1);
  }

  .result-content {
    flex: 1;
    min-width: 0;
  }

  .result-title {
    font-weight: 600;
    font-size: 14px;
    margin-bottom: 4px;
    color: var(--ds-text);
    line-height: 1.4;

    ::ng-deep mark {
      background-color: color-mix(in srgb, var(--ds-warning-hl) 75%, var(--ds-warning));
      color: var(--ds-text);
      padding: 1px 2px;
      border-radius: var(--ds-radius-sm);
      font-weight: 700;
    }
  }

  .result-description {
    font-size: 13px;
    color: var(--ds-text-muted);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    ::ng-deep mark {
      background-color: color-mix(in srgb, var(--ds-warning-hl) 75%, var(--ds-warning));
      color: var(--ds-text);
      padding: 1px 2px;
      border-radius: var(--ds-radius-sm);
      font-weight: 600;
    }
  }

  .result-meta {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .result-badge {
    padding: 4px 10px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.3px;

    &.annonce {
      background-color: var(--ds-marine-hl);
      color: var(--ds-marine-light);
    }

    &.dossier {
      background-color: var(--ds-primary-hl);
      color: var(--ds-primary-active);
    }

    &.contact {
      background-color: var(--ds-warning-hl);
      color: var(--ds-warning);
    }
  }
}

.search-footer {
  border-top: 1px solid var(--ds-surface-offset);
  padding: 10px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--ds-surface-2);
  border-radius: 0 0 var(--ds-radius-lg) var(--ds-radius-lg);

  .footer-left,
  .footer-right {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .view-all-button {
    background: none;
    border: none;
    color: var(--ds-success);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    padding: 6px 12px;
    border-radius: var(--ds-radius-sm);
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 6px;

    &:hover {
      background-color: var(--ds-success-hl);
    }
  }

  .keyboard-hints {
    display: flex;
    align-items: center;
    gap: 12px;

    .hint {
      display: flex;
      align-items: center;
      gap: 4px;
      font-size: 11px;
      color: var(--ds-text-faint);
    }

    kbd {
      background: var(--ds-surface);
      border: 1px solid var(--ds-border);
      border-radius: var(--ds-radius-sm);
      padding: 2px 6px;
      font-family: monospace;
      font-size: 11px;
      color: var(--ds-text-muted);
      box-shadow: var(--ds-shadow-xs);
    }
  }

  .es-status {
    color: var(--ds-warning);
    display: flex;
    align-items: center;
  }
}

.preview-panel {
  position: absolute;
  left: calc(100% + 12px);
  top: 0;
  width: 280px;
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  padding: 16px;
  animation: fadeIn 0.2s ease-out;
  z-index: 1001;

  .preview-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--ds-surface-offset);

    .preview-type-badge {
      padding: 4px 10px;
      border-radius: 12px;
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.5px;

      &.annonce {
        background-color: var(--ds-marine-hl);
        color: var(--ds-marine-light);
      }

      &.dossier {
        background-color: var(--ds-primary-hl);
        color: var(--ds-primary-active);
      }

      &.contact {
        background-color: var(--ds-warning-hl);
        color: var(--ds-warning);
      }
    }

    .preview-id {
      font-size: 12px;
      color: var(--ds-text-faint);
      font-weight: 500;
    }
  }

  .preview-title {
    font-size: 15px;
    font-weight: 600;
    color: var(--ds-text);
    margin-bottom: 16px;
    line-height: 1.4;
  }

  .preview-details {
    display: flex;
    flex-direction: column;
    gap: 10px;

