    margin-top: 16px;
    padding-top: 12px;
    border-top: 1px solid var(--ds-surface-offset);

    .preview-hint {
      font-size: 11px;
      color: var(--ds-text-faint);
      font-style: italic;
    }
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateX(-10px);
