    max-height: 400px;
  }

  .preview-panel {
    display: none;
  }

  .keyboard-hints {
    display: none !important;
  }

  .search-footer {
    flex-direction: column;
    gap: 8px;
    align-items: flex-start;
  }
}

/* Thème sombre app : suit les tokens --ds-* ([data-theme='dark'] défini sur un ancêtre) */
:host-context([data-theme='dark']),
:host-context(.dark-theme) {
  .search-input {
    &:focus {
      border-color: var(--ds-success);
      box-shadow: 0 0 0 4px color-mix(in srgb, var(--ds-success) 18%, transparent);
    }
  }

  .result-item {
    &:hover,
    &.selected {
      background-color: color-mix(in srgb, var(--ds-success-hl) 35%, var(--ds-surface));
