        align-items: stretch;
      }

      .arrow-icon {
        transform: rotate(90deg);
        align-self: center;
      }

      .original-value,
      .suggested-value {
        width: 100%;
      }
    }
  `],
    animations: [
        trigger('slideIn', [
            transition(':enter', [
                style({ transform: 'translateY(-10px)', opacity: 0 }),
                animate('200ms ease-out', style({ transform: 'translateY(0)', opacity: 1 }))
            ]),
            transition(':leave', [
                animate('200ms ease-in', style({ transform: 'translateY(-10px)', opacity: 0 }))
            ])
        ])
    ],
    imports: [MatIcon, MatButton]
})
export class InlineValidationSuggestionComponent {
  readonly suggestion = input<ValidationSuggestion | null>(null);
  readonly accept = output<ValidationSuggestion>();
  readonly dismiss = output<void>();

  onAccept(): void {
    const suggestion = this.suggestion();
    if (suggestion) {
      this.accept.emit(suggestion);
    }
  }

  onDismiss(): void {
    // TODO: The 'emit' function requires a mandatory void argument
    this.dismiss.emit();
  }

  getConfidenceIcon(): string {
    const suggestion = this.suggestion();
    if (!suggestion) return 'info';
    
    switch (suggestion.confidence) {
      case 'high':
        return 'verified';
      case 'medium':
        return 'help_outline';
      case 'low':
        return 'info';
      default:
        return 'info';
    }
  }
}

