/* ── ds-kanban-column ── */

/* ── Colonne ── */
.dsk-col {
  display: flex;
  flex-direction: column;
  width: 280px;
  min-width: 280px;
  max-height: 100%;
  background: var(--ds-surface-offset);
  border-radius: var(--ds-radius-lg);
  overflow: hidden;

  &__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 14px;
    border-bottom: 1px solid var(--ds-divider);
    background: var(--ds-surface);
    position: sticky;
    top: 0;
    z-index: 2;
  }

  &__header-left {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  &__dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    flex-shrink: 0;
    background: var(--dsk-col-accent, var(--ds-text-faint));
  }

  &__title {
    font-size: 12.5px;
    font-weight: 700;
    letter-spacing: 0.4px;
    text-transform: uppercase;
    color: var(--ds-text-muted);
    margin: 0;
  }

  &__count {
    min-width: 20px;
    height: 20px;
    padding: 0 6px;
    border-radius: var(--ds-radius-pill);
    background: var(--ds-surface-offset);
    font-size: 11px;
    font-weight: 700;
    color: var(--ds-text-muted);
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  &__limit {
    font-size: 11px;
    color: var(--ds-text-faint);
    &--exceeded { color: var(--ds-error); font-weight: 700; }
  }

  /* Couleurs par statut */
  &--marine  { --dsk-col-accent: var(--ds-marine); .dsk-col__dot { background: var(--ds-marine); } }
  &--copper  { --dsk-col-accent: var(--ds-primary); .dsk-col__dot { background: var(--ds-primary); } }
  &--success { --dsk-col-accent: var(--ds-success); .dsk-col__dot { background: var(--ds-success); } }
  &--warning { --dsk-col-accent: var(--ds-warning); .dsk-col__dot { background: var(--ds-warning); } }
  &--error   { --dsk-col-accent: var(--ds-error);   .dsk-col__dot { background: var(--ds-error); } }
  &--neutral { --dsk-col-accent: var(--ds-text-faint); }

  /* ── Drop zone ── */
  &__drop-zone {
    flex: 1;
    overflow-y: auto;
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-height: 80px;

    &.cdk-drop-list-dragging .dsk-card:not(.cdk-drag-placeholder) {
      transition: transform 200ms cubic-bezier(0.25, 0.8, 0.25, 1);
    }

    &.cdk-drop-list-receiving {
      background: color-mix(in srgb, var(--dsk-col-accent, var(--ds-marine)), transparent 90%);
      border: 2px dashed var(--dsk-col-accent, var(--ds-marine));
      border-radius: var(--ds-radius-md);
    }
  }

  &__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    padding: 32px 16px;
    color: var(--ds-text-faint);
    font-size: 12px;
    text-align: center;
  }
}

/* ── Carte ── */
.dsk-card {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  overflow: hidden;
  cursor: pointer;
  display: flex;
  align-items: flex-start;
  gap: 0;
  transition: box-shadow var(--ds-transition-fast), border-color var(--ds-transition-fast),
              transform var(--ds-transition-fast);
  position: relative;

  &:hover {
    border-color: var(--ds-border);
    box-shadow: var(--ds-shadow-sm);
  }

  &:focus-visible {
    outline: 2px solid var(--ds-marine);
    outline-offset: 2px;
  }

  &.cdk-drag-animating {
    transition: transform 250ms cubic-bezier(0.25, 0.8, 0.25, 1);
  }

  &.cdk-drag-preview {
    box-shadow: var(--ds-shadow-lg);
    border-color: var(--ds-marine);
    opacity: 0.95;
    transform: rotate(1.5deg);
  }

  &--placeholder {
    border: 2px dashed var(--ds-marine);
    border-radius: var(--ds-radius-md);
    height: 88px;
    background: var(--ds-marine-hl);
    opacity: 0.5;
  }

  /* Handle drag */
  &__handle {
    width: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    align-self: stretch;
    color: var(--ds-text-faint);
    cursor: grab;
    flex-shrink: 0;
    border-right: 1px solid var(--ds-surface-offset);
    transition: color var(--ds-transition-fast), background var(--ds-transition-fast);

    &:active { cursor: grabbing; }
    &:hover { color: var(--ds-text-muted); background: var(--ds-surface-offset); }
  }

  /* Corps */
  &__body {
    flex: 1;
    padding: 10px 12px;
    overflow: hidden;
  }

  &__title {
    font-size: 13px;
    font-weight: 600;
    color: var(--ds-text);
    line-height: 1.35;
    margin-bottom: 4px;
    overflow: hidden;
    text-overflow: ellipsis;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
  }

  &__subtitle {
    font-size: 11.5px;
    color: var(--ds-text-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-bottom: 6px;
  }

  /* Tags */
  &__tags {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-bottom: 8px;
  }

  &__tag {
    font-size: 10px;
    font-weight: 600;
    padding: 2px 7px;
    border-radius: var(--ds-radius-pill);
    background: var(--ds-marine-hl);
    color: var(--ds-marine);
    letter-spacing: 0.2px;
  }

  /* Footer */
  &__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    margin-top: 6px;
  }

  &__footer-right {
    display: flex;
    align-items: center;
    gap: 6px;
  }

  &__due {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 10.5px;
    color: var(--ds-text-faint);

    &--urgent {
      color: var(--ds-error);
      font-weight: 600;
    }
  }
}

