  align-items: center;
  justify-content: center;
  z-index: 9999;
  animation: fadeIn 0.2s ease-in-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.shortcuts-modal {
  background: white;
  border-radius: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
  max-width: 900px;
  width: 90%;
  max-height: 85vh;
  overflow-y: auto;
  animation: slideUp 0.3s ease-out;
}

@keyframes slideUp {
  from {
    transform: translateY(20px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.shortcuts-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 32px;
  border-bottom: 1px solid var(--ds-divider);
}

.shortcuts-header h2 {
  margin: 0;
  font-size: 24px;
  font-weight: 600;
  color: var(--ds-text);
}

.close-button {
  color: var(--ds-text-muted);
}

.shortcuts-content {
  padding: 24px 32px;
}

.preferences-section {
  display: flex;
  gap: 24px;
  margin-bottom: 32px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--ds-divider);
}

.shortcuts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 32px;
}

.shortcuts-column h3 {
  margin: 0 0 16px 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--ds-success);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.shortcut-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  gap: 16px;
}

.shortcut-keys {
  display: flex;
  gap: 4px;
  align-items: center;
  flex-shrink: 0;
}

.key {
  display: inline-block;
  padding: 4px 8px;
  background: linear-gradient(180deg, var(--ds-bg) 0%, var(--ds-divider) 100%);
  border: 1px solid var(--ds-divider);
  border-radius: 4px;
  font-family: 'Courier New', monospace;
  font-size: 13px;
  font-weight: 600;
  color: var(--ds-text-muted);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  min-width: 24px;
  text-align: center;
}

.shortcut-description {
  color: var(--ds-text-muted);
  font-size: 14px;
  flex: 1;
}

.shortcuts-footer {
  padding: 16px 32px;
  background: var(--ds-bg);
  border-top: 1px solid var(--ds-divider);
  border-radius: 0 0 12px 12px;
}

.footer-tip {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ds-text-muted);
  font-size: 14px;
