    max-height: 90vh;
  }

  .shortcuts-header {
    padding: 16px 20px;
  }

  .shortcuts-header h2 {
    font-size: 20px;
  }

  .shortcuts-content {
    padding: 16px 20px;
  }

  .shortcuts-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .preferences-section {
    flex-direction: column;
    gap: 12px;
  }

  .shortcuts-footer {
    padding: 12px 20px;
  }
}

:host-context(.dark-theme) .shortcuts-modal {
  background: var(--ds-text);
  color: var(--ds-divider);
}

:host-context(.dark-theme) .shortcuts-header {
  border-bottom-color: var(--ds-text-muted);
}

:host-context(.dark-theme) .shortcuts-header h2 {
  color: var(--ds-divider);
}

:host-context(.dark-theme) .preferences-section {
  border-bottom-color: var(--ds-text-muted);
}

:host-context(.dark-theme) .key {
  background: linear-gradient(180deg, var(--ds-text) 0%, var(--ds-text) 100%);
  border-color: var(--ds-text-muted);
  color: var(--ds-divider);
}

:host-context(.dark-theme) .shortcut-description {
  color: var(--ds-text-faint);
}

:host-context(.dark-theme) .shortcuts-footer {
  background: var(--ds-text);
  border-top-color: var(--ds-text-muted);
}

