import { Component, OnInit } from '@angular/core';

import { DsCardComponent } from '../design-system';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatChipsModule } from '@angular/material/chips';
import { Router } from '@angular/router';
import { LeadScoringApiService, LeadPriority } from '../services/lead-scoring-api.service';
import { ToastNotificationService } from '../services/toast-notification.service';
import { DsSkeletonComponent } from '../design-system/primitives/ds-skeleton/ds-skeleton.component';

@Component({
  selector: 'app-lead-priority-queue',
  standalone: true,
  imports: [
    DsCardComponent,
    MatButtonModule,
    MatIconModule,
    MatChipsModule,
    DsSkeletonComponent,
],
  template: `
    <ds-card class="priority-queue-card" [pad]="false" [elevation]="'md'">
      <div class="pq-header">
        <div class="pq-title">
          <mat-icon class="title-icon">trending_up</mat-icon>
          High-Priority Leads
        </div>
        <div class="header-actions">
          <button type="button" mat-icon-button (click)="refresh()" [disabled]="loading" title="Refresh">
            <mat-icon>refresh</mat-icon>
          </button>
          <button type="button" mat-icon-button (click)="recalculateAll()" [disabled]="loading" title="Recalculate All Scores">
            <mat-icon>calculate</mat-icon>
          </button>
        </div>
      </div>
    
      <div class="pq-body">
        @if (loading) {
          <div class="loading-container">
            <ds-skeleton variant="circle" width="40px" height="40px"></ds-skeleton>
          </div>
        }
    
        @if (!loading && leads.length === 0) {
          <div class="empty-state">
            <mat-icon class="empty-icon">inbox</mat-icon>
            <p>No high-priority leads at the moment</p>
          </div>
        }
    
        @if (!loading && leads.length > 0) {
          <div class="leads-list">
            @for (lead of leads; track lead) {
              <div
                class="lead-item"
                role="button"
                tabindex="0"
                [class.urgent]="lead.urgencyLevel === 'urgent'"
                [class.high]="lead.urgencyLevel === 'high'"
                [class.medium]="lead.urgencyLevel === 'medium'"
                (click)="viewDossier(lead.dossier.id)"
                (keydown.enter)="viewDossier(lead.dossier.id)"
                (keydown.space)="$event.preventDefault(); viewDossier(lead.dossier.id)">
                <div class="lead-score">
                  <div class="score-value">{{ lead.score.totalScore }}</div>
                  <div class="score-label">pts</div>
                </div>
                <div class="lead-info">
                  <div class="lead-name">
                    {{ lead.dossier.leadName || 'Unknown Lead' }}
                  </div>
                  <div class="lead-details">
                    @if (lead.dossier.leadPhone) {
                      <span class="detail-item">
                        <mat-icon class="detail-icon">phone</mat-icon>
                        {{ lead.dossier.leadPhone }}
                      </span>
                    }
                    @if (lead.dossier.source) {
                      <span class="detail-item">
                        <mat-icon class="detail-icon">source</mat-icon>
                        {{ lead.dossier.source }}
                      </span>
                    }
                    <span class="detail-item">
                      <mat-icon class="detail-icon">schedule</mat-icon>
                      {{ formatDate(lead.dossier.createdAt) }}
                    </span>
                  </div>
                  <div class="score-breakdown">
                    <span class="breakdown-item" title="Source Score">
                      <mat-icon class="breakdown-icon">business</mat-icon>
                      {{ lead.score.sourceScore }}
                    </span>
                    <span class="breakdown-item" title="Response Time Score">
                      <mat-icon class="breakdown-icon">schedule</mat-icon>
                      {{ lead.score.responseTimeScore }}
                    </span>
                    <span class="breakdown-item" title="Engagement Score">
                      <mat-icon class="breakdown-icon">chat</mat-icon>
                      {{ lead.score.engagementScore }}
                    </span>
                    <span class="breakdown-item" title="Property Match Score">
                      <mat-icon class="breakdown-icon">home</mat-icon>
                      {{ lead.score.propertyMatchScore }}
                    </span>
                  </div>
                </div>
                <div class="lead-urgency">
                  <mat-chip [class]="'urgency-chip ' + lead.urgencyLevel">
                    {{ getUrgencyLabel(lead.urgencyLevel) }}
                  </mat-chip>
                </div>
                <div class="lead-actions">
                  <button type="button" mat-icon-button (click)="viewDossier(lead.dossier.id); $event.stopPropagation()" title="View Details">
                    <mat-icon>visibility</mat-icon>
                  </button>
                </div>
              </div>
            }
          </div>
        }
      </div>
    </ds-card>
    `,
  styles: [`
    .priority-queue-card {
      display: block;
      margin: var(--ds-space-5);
    }

    .pq-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: var(--ds-space-4);
      border-bottom: 1px solid var(--ds-divider);
    }

    .pq-title {
      display: flex;
      align-items: center;
      font-size: 20px;
      font-weight: 600;
      color: var(--ds-text);
      margin: 0;
    }

    .pq-body {
      padding: 0 var(--ds-space-4) var(--ds-space-4);
    }

    .title-icon {
      margin-right: var(--ds-space-2);
      color: var(--ds-marine);
    }

    .header-actions {
      display: flex;
      gap: 8px;
    }

    .loading-container {
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 60px 0;
    }

    .empty-state {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 60px var(--ds-space-5);
      color: var(--ds-text-muted);
    }

    .empty-icon {
      font-size: 64px;
      width: 64px;
      height: 64px;
      color: var(--ds-text-faint);
      margin-bottom: var(--ds-space-4);
    }

    .leads-list {
      display: flex;
      flex-direction: column;
      gap: 12px;
      padding: 16px 0;
    }

    .lead-item {
      display: flex;
      align-items: center;
      padding: var(--ds-space-4);
      background: var(--ds-surface);
      border: 1px solid var(--ds-divider);
      border-radius: var(--ds-radius-md);
      border-left: 4px solid var(--ds-marine);
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .lead-item:hover {
      box-shadow: var(--ds-shadow-md);
      transform: translateY(-2px);
    }

    .lead-item.urgent {
      border-left-color: var(--ds-error);
      background: var(--ds-error-hl);
    }

    .lead-item.high {
      border-left-color: var(--ds-warning);
      background: var(--ds-warning-hl);
    }

    .lead-item.medium {
      border-left-color: var(--ds-marine);
      background: var(--ds-marine-hl);
    }

    .lead-score {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-width: 80px;
      margin-right: 20px;
    }

    .score-value {
      font-size: 32px;
      font-weight: bold;
      color: var(--ds-text);
      line-height: 1;
    }

    .score-label {
      font-size: 12px;
      color: var(--ds-text-muted);
      text-transform: uppercase;
    }

    .lead-info {
      flex: 1;
      min-width: 0;
    }

    .lead-name {
      font-size: 18px;
      font-weight: 600;
      color: var(--ds-text);
      margin-bottom: var(--ds-space-2);
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .lead-details {
      display: flex;
      flex-wrap: wrap;
      gap: 16px;
      margin-bottom: 8px;
      font-size: 14px;
      color: #7f8c8d;
    }

    .detail-item {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .detail-icon {
      font-size: 16px;
      width: 16px;
      height: 16px;
    }

    .score-breakdown {
      display: flex;
      gap: 12px;
      font-size: 13px;
      color: var(--ds-text-muted);
    }

    .breakdown-item {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .breakdown-icon {
      font-size: 14px;
      width: 14px;
      height: 14px;
    }

    .lead-urgency {
      margin: 0 16px;
    }

    .urgency-chip {
      font-weight: 600;
      text-transform: uppercase;
      font-size: 11px;
    }

    .urgency-chip.urgent {
      background-color: var(--ds-error) !important;
      color: var(--ds-text-inverse) !important;
    }

    .urgency-chip.high {
      background-color: var(--ds-warning) !important;
      color: var(--ds-text-inverse) !important;
    }

    .urgency-chip.medium {
      background-color: var(--ds-marine) !important;
      color: var(--ds-text-inverse) !important;
    }

    .urgency-chip.low {
      background-color: var(--ds-surface-dynamic) !important;
      color: var(--ds-text-muted) !important;
    }

    .lead-actions {
      display: flex;
      gap: 8px;
    }

    @media (max-width: 768px) {
      .lead-item {
        flex-wrap: wrap;
      }

      .lead-score {
        margin-right: 16px;
        min-width: 60px;
      }

      .score-value {
        font-size: 24px;
      }

      .lead-details {
        flex-direction: column;
        gap: 4px;
      }

      .score-breakdown {
        flex-wrap: wrap;
      }

      .lead-urgency {
        order: -1;
        margin: 0 0 8px 0;
        width: 100%;
      }
    }
  `]
})
export class LeadPriorityQueueComponent implements OnInit {
  leads: LeadPriority[] = [];
  loading = false;

  constructor(
    private leadScoringApi: LeadScoringApiService,
    private router: Router,
    private toastService: ToastNotificationService
  ) { }

  ngOnInit(): void {
    this.loadLeads();
  }

  loadLeads(): void {
    this.loading = true;
    this.leadScoringApi.getPriorityQueue(50).subscribe({
      next: (leads) => {
        this.leads = leads;
        this.loading = false;
      },
      error: (error) => {
        console.error('Error loading priority queue:', error);
        this.toastService.error('Failed to load priority leads');
        this.loading = false;
      }
    });
  }

  refresh(): void {
    this.loadLeads();
  }

  recalculateAll(): void {
    this.loading = true;
    this.leadScoringApi.recalculateAllScores().subscribe({
      next: () => {
        this.toastService.success('Score recalculation initiated');
        setTimeout(() => this.loadLeads(), 2000);
      },
      error: (error) => {
        console.error('Error recalculating scores:', error);
        this.toastService.error('Failed to recalculate scores');
        this.loading = false;
      }
    });
  }

  viewDossier(dossierId: number): void {
    this.router.navigate(['/dossiers', dossierId]);
  }

  formatDate(dateString: string): string {
    if (!dateString) return '';
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 60) {
      return `${diffMins}m ago`;
    } else if (diffHours < 24) {
      return `${diffHours}h ago`;
    } else if (diffDays < 7) {
      return `${diffDays}d ago`;
    } else {
      return date.toLocaleDateString();
    }
  }

  getUrgencyLabel(level: string): string {
    const labels: { [key: string]: string } = {
      urgent: 'URGENT',
      high: 'HIGH',
      medium: 'MEDIUM',
      low: 'LOW'
    };
    return labels[level] || level.toUpperCase();
  }
}

