.empty-icon {
  font-size: 64px;
  width: 64px;
  height: 64px;
  color: var(--ds-text-faint);
  margin-bottom: var(--ds-space-4);
}

.leads-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 0;
}

.lead-item {
  display: flex;
  align-items: center;
  padding: var(--ds-space-4);
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  border-left: 4px solid var(--ds-marine);
  cursor: pointer;
  transition: all 0.2s ease;
}

.lead-item:hover {
  box-shadow: var(--ds-shadow-md);
  transform: translateY(-2px);
}

.lead-item.urgent {
  border-left-color: var(--ds-error);
  background: var(--ds-error-hl);
}

.lead-item.high {
  border-left-color: var(--ds-warning);
  background: var(--ds-warning-hl);
}

.lead-item.medium {
  border-left-color: var(--ds-marine);
  background: var(--ds-marine-hl);
}

.lead-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 80px;
  margin-right: 20px;
}

.score-value {
  font-size: 32px;
  font-weight: bold;
  color: var(--ds-text);
  line-height: 1;
}

.score-label {
  font-size: 12px;
  color: var(--ds-text-muted);
  text-transform: uppercase;
}

.lead-info {
  flex: 1;
  min-width: 0;
}

.lead-name {
  font-size: 18px;
  font-weight: 600;
  color: var(--ds-text);
  margin-bottom: var(--ds-space-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.lead-details {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 8px;
  font-size: 14px;
  color: #7f8c8d;
}

.detail-item {
  display: flex;
  align-items: center;
  gap: 4px;
}

.detail-icon {
  font-size: 16px;
  width: 16px;
  height: 16px;
}

.score-breakdown {
  display: flex;
  gap: 12px;
  font-size: 13px;
  color: var(--ds-text-muted);
}

.breakdown-item {
  display: flex;
  align-items: center;
  gap: 4px;
}

.breakdown-icon {
  font-size: 14px;
  width: 14px;
  height: 14px;
}

.lead-urgency {
  margin: 0 16px;
}

.urgency-chip {
  font-weight: 600;
  text-transform: uppercase;
  font-size: 11px;
}

.urgency-chip.urgent {
  background-color: var(--ds-error) !important;
  color: var(--ds-text-inverse) !important;
}

.urgency-chip.high {
  background-color: var(--ds-warning) !important;
  color: var(--ds-text-inverse) !important;
}

.urgency-chip.medium {
  background-color: var(--ds-marine) !important;
  color: var(--ds-text-inverse) !important;
}

.urgency-chip.low {
  background-color: var(--ds-surface-dynamic) !important;
  color: var(--ds-text-muted) !important;
}

.lead-actions {
  display: flex;
  gap: 8px;
}

@media (max-width: 768px) {
  .lead-item {
    flex-wrap: wrap;
  }

  .lead-score {
    margin-right: 16px;
    min-width: 60px;
  }

  .score-value {
    font-size: 24px;
  }

  .lead-details {
    flex-direction: column;
    gap: 4px;
  }

  .score-breakdown {
    flex-wrap: wrap;
  }

  .lead-urgency {
    order: -1;
    margin: 0 0 8px 0;
    width: 100%;
  }
}

