.skeleton-container {
  width: 100%;
}

.skeleton-spinner-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 200px;
  padding: var(--ds-space-8);
}

/* Card */
.skeleton-card-inner {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-4);
}

.skeleton-card-item {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  padding: var(--ds-space-4);
}

.skeleton-card-header {
  display: flex;
  gap: var(--ds-space-3);
  margin-bottom: var(--ds-space-3);
}

.skeleton-card-header ds-skeleton:first-child {
  flex-shrink: 0;
}

.skeleton-card-header-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-2);
  min-width: 0;
}

.skeleton-card-body {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-2);
  margin-bottom: var(--ds-space-3);
}

.skeleton-card-footer {
  display: flex;
  gap: var(--ds-space-2);
  padding-top: var(--ds-space-3);
  border-top: 1px solid var(--ds-divider);
}

/* List */
.skeleton-list-inner {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-3);
}

.skeleton-list-item {
  display: flex;
  align-items: center;
  gap: var(--ds-space-3);
  padding: var(--ds-space-3);
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-sm);
}

.skeleton-list-item ds-skeleton:first-child {
  flex-shrink: 0;
}

.skeleton-list-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.skeleton-list-item ds-skeleton:last-child {
  flex-shrink: 0;
}

/* Table */
.skeleton-table-inner {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  overflow: hidden;
}

.skeleton-table-header {
  display: flex;
  gap: var(--ds-space-3);
  padding: var(--ds-space-4);
  border-bottom: 2px solid var(--ds-divider);
  background: var(--ds-surface-2);
}

.skeleton-table-header ds-skeleton {
  flex: 1;
  min-width: 0;
}

.skeleton-table-body {
  display: flex;
  flex-direction: column;
}

.skeleton-table-row {
  display: flex;
  gap: var(--ds-space-3);
  padding: var(--ds-space-4);
  border-bottom: 1px solid var(--ds-divider);
}

.skeleton-table-row:last-child {
  border-bottom: none;
}

.skeleton-table-row ds-skeleton {
  flex: 1;
  min-width: 0;
}

/* Form */
.skeleton-form-inner {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  padding: var(--ds-space-6);
}

.skeleton-form-group {
  margin-bottom: var(--ds-space-6);
}

.skeleton-form-actions {
  display: flex;
  gap: var(--ds-space-3);
  margin-top: var(--ds-space-8);
}

/* Dashboard KPI */
.skeleton-dashboard-kpi-inner {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  padding: var(--ds-space-5);
}

.skeleton-kpi-header {
  margin-bottom: var(--ds-space-4);
}

.skeleton-kpi-value {
  margin-bottom: var(--ds-space-5);
}

.skeleton-kpi-footer {
  padding-top: var(--ds-space-3);
  border-top: 1px solid var(--ds-divider);
}

/* Detail */
.skeleton-detail-inner {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  padding: var(--ds-space-6);
}

.skeleton-detail-header {
  display: flex;
  align-items: center;
  gap: var(--ds-space-4);
  padding-bottom: var(--ds-space-6);
  margin-bottom: var(--ds-space-6);
  border-bottom: 2px solid var(--ds-divider);
}

.skeleton-detail-header ds-skeleton:nth-child(2) {
  flex: 1;
  min-width: 0;
}

.skeleton-detail-header ds-skeleton:last-child {
  flex-shrink: 0;
}

.skeleton-detail-header ds-skeleton:first-child {
  flex-shrink: 0;
}

.skeleton-detail-content {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-4);
}

.skeleton-detail-row {
  display: flex;
  gap: var(--ds-space-6);
  align-items: center;
}

.skeleton-detail-row ds-skeleton:first-child {
  flex-shrink: 0;
}

.skeleton-detail-value-slot {
  flex: 1;
  max-width: 400px;
  min-width: 0;
}

/* Grid */
.skeleton-grid-inner {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--ds-space-5);
}

.skeleton-grid-item {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  overflow: hidden;
}

.skeleton-grid-item ds-skeleton:first-child {
  border-radius: 0;
}

.skeleton-grid-content {
  padding: var(--ds-space-4);
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-2);
}

.skeleton-grid-content ds-skeleton:last-child {
  margin-top: var(--ds-space-2);
}

/* Message */
.skeleton-message-inner {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-4);
  padding: var(--ds-space-4);
}

.skeleton-message-item {
  display: flex;
  gap: var(--ds-space-3);
  align-items: flex-start;
}

.skeleton-message-right {
  flex-direction: row-reverse;
}

.skeleton-message-item ds-skeleton:is(:first-child, :last-child) {
  flex-shrink: 0;
}

.skeleton-message-bubble {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: var(--ds-space-3);
  background: var(--ds-surface-offset);
  border-radius: var(--ds-radius-lg);
  max-width: 70%;
}

.skeleton-message-right .skeleton-message-bubble {
  background: var(--ds-marine-hl);
}

/* Timeline */
.skeleton-container.skeleton-timeline {
  position: relative;
  padding-left: 40px;
}

.skeleton-timeline-inner {
  position: relative;
}

.skeleton-timeline-item {
  position: relative;
  padding-bottom: var(--ds-space-8);
}

.skeleton-timeline-item:last-child {
  padding-bottom: 0;
}

.skeleton-timeline-item::before {
  content: '';
  position: absolute;
  left: -32px;
  top: 8px;
  bottom: -32px;
  width: 2px;
  background: var(--ds-divider);
}

.skeleton-timeline-item:last-child::before {
  display: none;
}

.skeleton-timeline-marker {
  position: absolute;
  left: -40px;
  top: 0;
}

.skeleton-timeline-content {
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  padding: var(--ds-space-4);
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-2);
}

.skeleton-timeline-content ds-skeleton:last-child {
  margin-top: 4px;
}

@media (max-width: 768px) {
  .skeleton-card-item {
    padding: var(--ds-space-3);
  }

  .skeleton-table-header,
  .skeleton-table-row {
    padding: var(--ds-space-3);
    gap: var(--ds-space-2);
  }

  .skeleton-detail-row {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--ds-space-2);
  }

  .skeleton-detail-value-slot {
    width: 100%;
    max-width: none;
  }

  .skeleton-grid-inner {
    grid-template-columns: 1fr;
  }

  .skeleton-message-bubble {
    max-width: 85%;
  }

  .skeleton-container.skeleton-timeline {
    padding-left: 32px;
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

