      color: var(--ds-text-primary, rgba(0, 0, 0, 0.87));
      text-align: center;
    }

    .locale-dropdown-divider {
      height: 1px;
      background: var(--ds-divider, rgba(0, 0, 0, 0.08));
    }

    .locale-menu-item {
      display: flex;
