/* Login component — styles spécifiques au formulaire de connexion.
   Le layout général est géré par ds-auth-hero. */

.login-error {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px;
  background: var(--ds-error-hl);
  color: var(--ds-error);
  border-radius: var(--ds-radius-md);
  font-size: 13.5px;
  font-weight: 500;
}

/* ── Champs ── */
.login-label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  color: var(--ds-text-muted);
  letter-spacing: 1.2px;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.login-input {
  width: 100%;
  height: 44px;
  border-radius: var(--ds-radius-md);
  border: 1px solid var(--ds-divider);
  background: var(--ds-surface);
  padding: 0 14px;
  font-family: var(--ds-font-body);
  font-size: 14px;
  color: var(--ds-text);
  outline: none;
  transition: border-color 150ms ease, box-shadow 150ms ease;
  box-sizing: border-box;
}

.login-input:focus {
  border-color: var(--ds-marine);
  box-shadow: 0 0 0 4px var(--ds-marine-hl);
}

.login-input--textarea {
  height: auto;
  padding: 10px 14px;
  resize: vertical;
  font-family: ui-monospace, 'SF Mono', monospace;
  font-size: 12.5px;
  line-height: 1.5;
}

.login-hint {
  display: block;
  font-size: 11.5px;
  color: var(--ds-text-faint);
  margin-top: 4px;
}

/* ── Boutons ── */
.login-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 48px;
  padding: 0 20px;
  border: none;
  border-radius: var(--ds-radius-md);
  font-family: var(--ds-font-body);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  width: 100%;
  transition: background 150ms ease, box-shadow 150ms ease;
}

.login-btn--marine {
  background: var(--ds-marine);
  color: white;
}
.login-btn--marine:hover:not(:disabled) {
  background: var(--ds-marine-hover);
  box-shadow: var(--ds-shadow-sm);
}

.login-btn--ghost {
  background: transparent;
  color: var(--ds-text-muted);
  border: 1px solid var(--ds-border);
  font-size: 13.5px;
  height: 40px;
  width: auto;
  flex: 1;
}
.login-btn--ghost:hover:not(:disabled) {
  background: var(--ds-surface-offset);
  color: var(--ds-text);
}

.login-btn--danger {
  color: var(--ds-error);
  border-color: var(--ds-error-hl);
}
.login-btn--danger:hover:not(:disabled) {
  background: var(--ds-error-hl);
}

.login-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.login-btn--loading { cursor: wait; }

.login-btn__spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255,255,255,.3);
  border-top-color: white;
  border-radius: 50%;
  animation: login-spin .7s linear infinite;
}
.login-btn__spinner--dark {
  border-color: rgba(13,44,74,.2);
  border-top-color: var(--ds-marine);
}

@keyframes login-spin {
  to { transform: rotate(360deg); }
}

/* ── Séparateur ── */
.login-sep {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--ds-text-faint);
  font-size: 12px;
}
.login-sep::before,
.login-sep::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--ds-divider);
}

/* ── Dev row ── */
.login-dev-form { display: flex; flex-direction: column; gap: 12px; }
.login-dev-row { display: flex; gap: 8px; }

/* ── Legal ── */
.login-legal {
  font-size: 12px;
  color: var(--ds-text-faint);
  line-height: 1.55;
  margin: 0;
}
.login-legal a {
  color: var(--ds-marine);
  text-decoration: underline;
  text-underline-offset: 2px;
}

