.ml-insights-dashboard {
  padding: 24px;
  background: var(--ds-bg);
  min-height: 100vh;

  .dashboard-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 24px;

    h1 {
      margin: 0;
      color: var(--ds-text);
    }

    .btn {
      padding: 10px 20px;
      font-size: 14px;
    }
  }

  .alert {
    margin-bottom: 24px;
    padding: 16px;
    border-radius: var(--ds-radius-sm);
  }

  .loading-spinner {
    text-align: center;
    padding: 60px 20px;
    color: var(--ds-text-muted);

    i {
      color: var(--ds-marine-light);
      margin-bottom: 16px;
    }

    p {
      font-size: 16px;
    }
  }

  .dashboard-content {
    .card {
      background: var(--ds-surface);
      border-radius: var(--ds-radius-md);
      box-shadow: var(--ds-shadow-sm);
      margin-bottom: 24px;

      .card-header {
        padding: 16px 24px;
        border-bottom: 1px solid var(--ds-divider);

        h3 {
          margin: 0;
          font-size: 18px;
          color: var(--ds-text);
          display: flex;
          align-items: center;
          gap: 8px;

          i {
            color: var(--ds-marine-light);
          }
        }
      }

      .card-body {
        padding: 24px;
      }
    }

    .model-info-card {
      .info-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
        gap: 16px;
        margin-bottom: 24px;

        .info-item {
          display: flex;
          flex-direction: column;
          gap: 4px;

          label {
            font-weight: 600;
            color: var(--ds-text-muted);
            font-size: 14px;
          }

          span {
            font-size: 16px;
            color: var(--ds-text);

            &.badge {
              font-size: 14px;
              padding: 4px 12px;
              display: inline-block;
              width: fit-content;
            }
          }
        }
      }

      .metrics-summary {
        border-top: 1px solid var(--ds-divider);
        padding-top: 24px;

        h4 {
          margin-bottom: 16px;
          font-size: 16px;
          color: var(--ds-text);
        }

        .metrics-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
          gap: 16px;

          .metric-card {
            text-align: center;
            padding: 16px;
            background: var(--ds-surface-2);
            border-radius: var(--ds-radius-md);
            border: 1px solid var(--ds-divider);

            .metric-label {
              font-size: 12px;
              color: var(--ds-text-muted);
              text-transform: uppercase;
              margin-bottom: 8px;
            }

            .metric-value {
              font-size: 24px;
              font-weight: 700;
              color: var(--ds-marine-light);
            }
          }
        }
      }
    }

    .charts-section {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
      gap: 24px;

      .chart-card {
        .chart-container {
          position: relative;
          height: 300px;
        }
      }
    }

    .versions-card,
    .experiments-card {
      .table {
        margin: 0;
        width: 100%;

        thead {
          background: var(--ds-surface-2);

          th {
            padding: 12px;
            font-weight: 600;
            color: var(--ds-text-muted);
            font-size: 14px;
            border-bottom: 2px solid var(--ds-divider);
          }
        }

        tbody {
          td {
            padding: 12px;
            font-size: 14px;
            color: var(--ds-text);
            border-bottom: 1px solid var(--ds-divider);

            .badge {
              padding: 4px 8px;
              font-size: 12px;
              font-weight: 600;
            }

            .btn {
              padding: 4px 12px;
              font-size: 12px;
            }
          }

          tr:hover {
            background: var(--ds-surface-2);
          }
        }
      }
    }
  }

  .badge {
    display: inline-block;
    padding: 4px 8px;
    font-size: 12px;
    font-weight: 600;
    border-radius: var(--ds-radius-sm);

    &.badge-primary {
      background: var(--ds-marine-light);
      color: var(--ds-text-inverse);
    }

    &.badge-success {
      background: var(--ds-success);
      color: var(--ds-text-inverse);
    }

    &.badge-secondary {
      background: var(--ds-surface-dynamic);
      color: var(--ds-text);
    }

    &.badge-info {
      background: var(--ds-marine-hl);
      color: var(--ds-marine);
    }

    &.badge-warning {
      background: var(--ds-warning-hl);
      color: var(--ds-text);
    }

    &.badge-danger {
      background: var(--ds-error);
      color: var(--ds-text-inverse);
    }
  }

  .btn {
    border: none;
    border-radius: var(--ds-radius-sm);
    cursor: pointer;
    transition: all 0.2s;

    &.btn-primary {
      background: var(--ds-marine-light);
      color: var(--ds-text-inverse);

      &:hover:not(:disabled) {
        background: color-mix(in srgb, var(--ds-marine-light) 82%, var(--ds-text) 18%);
      }
    }

    &.btn-outline-primary {
      background: transparent;
      border: 1px solid var(--ds-marine-light);
      color: var(--ds-marine-light);

      &:hover {
        background: var(--ds-marine-light);
        color: var(--ds-text-inverse);
      }
    }

    &:disabled {
      opacity: 0.6;
      cursor: not-allowed;
    }
  }
}

