.notification-center-shell {
  display: block;
  width: 400px;
  max-height: 600px;
  overflow: hidden;
}

.notification-center {
  display: flex;
  flex-direction: column;
  height: 100%;
  max-height: 600px;
  min-height: 0;
  background: transparent;
}

.notification-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--ds-space-4);
  border-bottom: 1px solid var(--ds-divider);
  flex-shrink: 0;

  .header-title {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);

    .header-icon {
      color: var(--ds-marine);
      font-size: 24px;
      width: 24px;
      height: 24px;
    }

    h2 {
      margin: 0;
      font-size: var(--ds-text-lg);
      font-weight: 600;
      color: var(--ds-text);
    }
  }

  ds-button {
    flex-shrink: 0;
  }
}

.notification-filters {
  padding: var(--ds-space-3) var(--ds-space-4);
  border-bottom: 1px solid var(--ds-divider);
  flex-shrink: 0;

  mat-button-toggle-group {
    display: flex;
    flex-wrap: wrap;
  }

  mat-button-toggle {
    font-size: var(--ds-text-xs);
  }
}

.notification-list {
  flex: 1;
  overflow-y: auto;
  padding: var(--ds-space-2) 0;

  .empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: var(--ds-space-12) var(--ds-space-4);
    color: var(--ds-text-muted);

    mat-icon {
      font-size: 64px;
      width: 64px;
      height: 64px;
      margin-bottom: var(--ds-space-4);
      opacity: 0.5;
    }

    p {
      margin: 0;
      font-size: var(--ds-text-sm);
    }
  }
}

.notification-group {
  margin-bottom: var(--ds-space-4);

  .group-header {
    padding: var(--ds-space-2) var(--ds-space-4);
    background: var(--ds-surface-offset);
    position: sticky;
    top: 0;
    z-index: 1;

    .group-date {
      font-size: var(--ds-text-xs);
      font-weight: 600;
      color: var(--ds-text-muted);
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
  }
}

.notification-item {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: var(--ds-space-3);
  padding: var(--ds-space-3) var(--ds-space-4);
  cursor: pointer;
  transition: background-color var(--ds-transition-fast);
  border-bottom: 1px solid var(--ds-divider);

  &:hover {
    background: var(--ds-bg);
  }

  &:focus {
    outline: 2px solid var(--ds-marine);
    outline-offset: -2px;
  }

  &.unread {
    background: var(--ds-marine-hl);

    .notification-title {
      font-weight: 600;
    }
  }

  .notification-icon {
    flex-shrink: 0;
    margin-top: 2px;
    color: var(--ds-text-muted);

    ds-icon {
      display: block;
      color: var(--ds-text-muted);
    }

    ds-icon.unread-icon {
      color: var(--ds-marine);
    }
  }

  .notification-content {
    flex: 1;
    min-width: 0;

    .notification-title {
      font-size: var(--ds-text-sm);
      line-height: 1.4;
      margin-bottom: var(--ds-space-1);
      color: var(--ds-text);
    }

    .notification-message {
      font-size: 13px;
      line-height: 1.4;
      color: var(--ds-text-muted);
      margin-bottom: var(--ds-space-2);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .notification-meta {
      display: flex;
      align-items: center;
      gap: var(--ds-space-2);
      flex-wrap: wrap;
      font-size: 11px;
      color: var(--ds-text-muted);

      .type-badge {
        text-transform: uppercase;
      }
    }
  }

  .notification-actions {
    flex-shrink: 0;
    opacity: 0;
    transition: opacity var(--ds-transition-fast);

    ds-button mat-icon {
      font-size: 18px;
      width: 18px;
      height: 18px;
    }
  }

  &:hover .notification-actions {
    opacity: 1;
  }

  .unread-indicator {
    position: absolute;
    left: 4px;
    top: 50%;
    transform: translateY(-50%);
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--ds-marine);
  }
}

.load-more-container {
  display: flex;
  justify-content: center;
  padding: var(--ds-space-4);

  ds-button {
    width: 100%;
    max-width: 200px;
  }
}

.notification-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--ds-space-12) var(--ds-space-4);

  p {
    margin: var(--ds-space-4) 0 0;
    font-size: var(--ds-text-sm);
    color: var(--ds-text-muted);
  }
}

@media (max-width: 600px) {
  .notification-center-shell {
    width: 100vw;
    max-height: 100vh;
    border-radius: 0;
  }
}

