}

.pref-card-title {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 20px;
  font-weight: 600;
  margin: 0 0 8px;
}

.pref-card-title mat-icon {
  color: var(--primary-color, var(--ds-marine));
}

.pref-card-subtitle {
  font-size: 14px;
  color: rgba(0, 0, 0, 0.6);
  margin: 0;
}

.pref-card-body {
  padding: 0 16px 16px;
}

/* Channels Grid */
.channels-grid,
.types-grid {
  display: grid;
  gap: 16px;
}

@media (min-width: 768px) {
  .channels-grid,
  .types-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.channel-item,
.type-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.02);
  transition: all 0.3s ease;
}

.channel-item:hover,
.type-item:hover {
  background: rgba(0, 0, 0, 0.04);
  border-color: var(--primary-color, var(--ds-marine));
}

.channel-info,
.type-info {
  display: flex;
  align-items: center;
  gap: 16px;
  flex: 1;
}

.channel-info mat-icon,
.type-info mat-icon {
  font-size: 32px;
  width: 32px;
  height: 32px;
  color: rgba(0, 0, 0, 0.4);
  transition: color 0.3s ease;
}

.channel-icon-active,
.type-icon-active {
  color: var(--primary-color, var(--ds-marine)) !important;
}

.channel-text,
.type-text {
  flex: 1;
}

.channel-text strong,
.type-text strong {
  display: block;
  font-size: 16px;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.87);
  margin-bottom: 4px;
}

.channel-description,
.type-description {
  margin: 0;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.6);
  line-height: 1.4;
}

/* Quiet Hours */
.quiet-hours-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.02);
  margin-bottom: 16px;
}

.toggle-info {
  flex: 1;
}

.toggle-info strong {
  display: block;
  font-size: 16px;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.87);
  margin-bottom: 4px;
}

.quiet-status {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 8px 0 0;
  font-size: 14px;
  color: rgba(0, 0, 0, 0.6);
}

.quiet-status mat-icon {
  font-size: 18px;
  width: 18px;
  height: 18px;
}

.quiet-status.active {
  color: var(--primary-color, var(--ds-marine));
  font-weight: 500;
}

.quiet-hours-config {
  padding: 16px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.02);
  animation: slideDown 0.3s ease;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.slider-section {
  margin-bottom: 24px;
}

.slider-section:last-of-type {
  margin-bottom: 16px;
}

.slider-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: rgba(0, 0, 0, 0.87);
  margin-bottom: 12px;
}

.slider-label mat-icon {
  font-size: 20px;
  width: 20px;
  height: 20px;
  color: var(--primary-color, var(--ds-marine));
}

.quiet-hours-slider {
  width: 100%;
}

.quiet-hours-hint {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.6);
  padding: 8px 12px;
  background: rgba(25, 118, 210, 0.08);
  border-radius: 4px;
}

.quiet-hours-hint mat-icon {
  font-size: 16px;
  width: 16px;
  height: 16px;
  color: var(--primary-color, var(--ds-marine));
}

/* Digest Frequency */
.digest-frequency-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.digest-frequency-option {
  padding: 16px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.02);
  transition: all 0.3s ease;
}

.digest-frequency-option:hover {
  background: rgba(0, 0, 0, 0.04);
  border-color: var(--primary-color, var(--ds-marine));
}

.digest-frequency-option.mat-radio-checked {
  background: rgba(25, 118, 210, 0.08);
  border-color: var(--primary-color, var(--ds-marine));
}

.frequency-content {
  margin-left: 8px;
}

.frequency-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 4px;
}

.frequency-header mat-icon {
  font-size: 24px;
  width: 24px;
  height: 24px;
  color: var(--primary-color, var(--ds-marine));
}

.frequency-header strong {
  font-size: 16px;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.87);
}

.frequency-description {
  margin: 0;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.6);
  line-height: 1.4;
}

/* Preview Section */
.preview-card {
  background: linear-gradient(135deg, rgba(25, 118, 210, 0.05) 0%, rgba(25, 118, 210, 0.02) 100%);
}

.preview-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.summary-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
  background: white;
}

.summary-item mat-icon {
  font-size: 32px;
  width: 32px;
  height: 32px;
  color: var(--primary-color, var(--ds-marine));
}

.summary-item mat-icon.active {
  color: var(--ds-warning);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.summary-item div {
  display: flex;
  flex-direction: column;
}

.summary-item strong {
  font-size: 18px;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.87);
}

.summary-item span {
  font-size: 12px;
  color: rgba(0, 0, 0, 0.6);
}

.preview-divider {
  margin: 24px 0;
}

.preview-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 16px;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.87);
  margin: 0 0 16px;
}

.preview-title mat-icon {
  color: var(--primary-color, var(--ds-marine));
}

.notification-examples {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.notification-example {
  display: flex;
  gap: 16px;
  padding: 16px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
  background: white;
  transition: all 0.3s ease;
  animation: fadeInUp 0.5s ease;
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.notification-example:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transform: translateY(-2px);
}

.notification-icon {
  flex-shrink: 0;
}

.notification-icon mat-icon {
  font-size: 40px;
  width: 40px;
  height: 40px;
  padding: 8px;
  border-radius: 50%;
  background: rgba(25, 118, 210, 0.1);
  color: var(--primary-color, var(--ds-marine));
}

.notification-icon-newDossier {
  background: rgba(76, 175, 80, 0.1) !important;
  color: var(--ds-success) !important;
}

.notification-icon-newMessage {
  background: rgba(33, 150, 243, 0.1) !important;
  color: var(--ds-marine) !important;
}

.notification-icon-appointment {
  background: rgba(255, 152, 0, 0.1) !important;
  color: var(--ds-warning) !important;
}

.notification-icon-statusChange {
  background: rgba(156, 39, 176, 0.1) !important;
  color: var(--ds-primary) !important;
}

.notification-content {
  flex: 1;
}

.notification-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.notification-header strong {
  font-size: 14px;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.87);
}

.notification-time {
  font-size: 12px;
  color: rgba(0, 0, 0, 0.5);
}

.notification-message {
  margin: 0 0 8px;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.7);
  line-height: 1.4;
}

.notification-channels {
  display: flex;
  gap: 6px;
}

.channel-badge {
  font-size: 16px;
  width: 16px;
  height: 16px;
  color: rgba(0, 0, 0, 0.4);
}

.no-notifications {
  text-align: center;
  padding: 48px 24px;
}

.no-notifications mat-icon {
  font-size: 64px;
  width: 64px;
  height: 64px;
  color: rgba(0, 0, 0, 0.3);
  margin-bottom: 16px;
}

.no-notifications p {
  margin: 8px 0;
  font-size: 16px;
  color: rgba(0, 0, 0, 0.6);
}

.hint-text {
  font-size: 13px !important;
  color: rgba(0, 0, 0, 0.5) !important;
}

/* Form Actions */
.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  padding: 24px;
  border-top: 1px solid rgba(0, 0, 0, 0.12);
  background: rgba(0, 0, 0, 0.02);
  position: sticky;
  bottom: 0;
  z-index: 10;
}

.button-spinner {
  display: inline-block;
  margin-right: 8px;
}

/* Responsive */
@media (max-width: 767px) {
  .notification-preferences-form {
    padding: 16px;
  }

  .preferences-card {
    margin-bottom: 16px;
  }

  .channels-grid,
  .types-grid {
    grid-template-columns: 1fr;
  }

  .preview-summary {
    grid-template-columns: repeat(2, 1fr);
  }

  .notification-example {
    flex-direction: column;
  }

  .form-actions {
    flex-direction: column;
  }

  .form-actions button {
    width: 100%;
  }
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  .preferences-card .pref-card-subtitle {
    color: rgba(255, 255, 255, 0.6);
  }

  .channel-item,
  .type-item,
  .quiet-hours-toggle,
  .quiet-hours-config,
  .digest-frequency-option {
    border-color: rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.05);
  }

  .channel-item:hover,
  .type-item:hover,
  .digest-frequency-option:hover {
    background: rgba(255, 255, 255, 0.08);
  }

  .channel-text strong,
  .type-text strong,
  .toggle-info strong,
  .frequency-header strong,
  .notification-header strong {
    color: rgba(255, 255, 255, 0.87);
  }

  .channel-description,
  .type-description,
  .quiet-status,
  .frequency-description,
  .notification-message {
    color: rgba(255, 255, 255, 0.6);
  }

  .summary-item,
  .notification-example {
    background: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.12);
  }

  .no-notifications mat-icon {
    color: rgba(255, 255, 255, 0.3);
  }

  .no-notifications p {
    color: rgba(255, 255, 255, 0.6);
  }

  .hint-text {
    color: rgba(255, 255, 255, 0.5) !important;
  }
}

