.toast-wrapper {
  position: fixed;
  z-index: var(--z-index-notification);
  pointer-events: none;
  inset: 0;
}

.toast-container {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-3);
  padding: var(--ds-space-4);
  pointer-events: none;
  max-width: 420px;
  width: 100%;
}

.toast-container-top-right {
  top: 0;
  right: 0;
}

.toast-container-top-left {
  top: 0;
  left: 0;
}

.toast-container-top-center {
  top: 0;
  left: 50%;
  transform: translateX(-50%);
}

.toast-container-bottom-right {
  bottom: 0;
  right: 0;
}

.toast-container-bottom-left {
  bottom: 0;
  left: 0;
}

.toast-container-bottom-center {
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
}

.toast {
  pointer-events: auto;
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  overflow: hidden;
  min-height: 64px;
  display: flex;
  flex-direction: column;
  position: relative;
  border-left: 4px solid transparent;
  transition:
    box-shadow var(--ds-transition-fast),
    transform var(--ds-transition-fast);
  cursor: default;
  user-select: none;
  -webkit-user-select: none;

  &:hover {
    box-shadow: var(--ds-shadow-xl);
  }

  &:active {
    transform: scale(0.98);
  }
}

.toast-success {
  border-left-color: var(--ds-success);
}

.toast-error {
  border-left-color: var(--ds-error);
}

.toast-warning {
  border-left-color: var(--ds-warning);
}

.toast-info {
  border-left-color: var(--ds-marine);
}

.toast-content {
  display: flex;
  align-items: flex-start;
  gap: var(--ds-space-3);
  padding: var(--ds-space-4);
  position: relative;
}

.toast-icon {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  margin-top: 2px;
  color: var(--ds-marine);

  .ds-icon {
    display: block;
  }
}

.toast-success .toast-icon {
  color: var(--ds-success);
}

.toast-error .toast-icon {
  color: var(--ds-error);
}

.toast-warning .toast-icon {
  color: var(--ds-warning);
}

.toast-info .toast-icon {
  color: var(--ds-marine);
}

.toast-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-2);
}

.toast-message {
  color: var(--ds-text);
  font-size: var(--ds-text-sm);
  line-height: 1.5;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.toast-action {
  align-self: flex-start;
  margin-top: var(--ds-space-1);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
}

.toast-close {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  margin: -2px -2px 0 0;
  padding: 0;
  border: none;
  border-radius: var(--ds-radius-sm);
  background: transparent;
  color: var(--ds-text-muted);
  cursor: pointer;
  transition: background var(--ds-transition-fast), color var(--ds-transition-fast);

  &:hover {
    background: var(--ds-surface-offset);
    color: var(--ds-text);
  }

  &:focus-visible {
    outline: 2px solid var(--ds-marine);
    outline-offset: 2px;
  }

  .ds-icon {
    display: block;
  }
}

.toast-progress {
  position: relative;
  height: 4px;
  background: var(--ds-divider);
  overflow: hidden;
}

.toast-progress-bar {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  background: currentColor;
  transition: width 100ms linear;
}

.toast-success .toast-progress-bar {
  background: var(--ds-success);
}

.toast-error .toast-progress-bar {
  background: var(--ds-error);
}

.toast-warning .toast-progress-bar {
  background: var(--ds-warning);
}

.toast-info .toast-progress-bar {
  background: var(--ds-marine);
}

@media (max-width: 640px) {
  .toast-container {
    max-width: 100%;
    padding: var(--ds-space-3);
  }

  .toast-container-top-center,
  .toast-container-bottom-center {
    left: 0;
    right: 0;
    transform: none;
  }

  .toast-content {
    padding: var(--ds-space-3);
  }

  .toast-message {
    font-size: var(--ds-text-xs);
  }
}

.toast.swiping {
  transition: none;
  cursor: grabbing;
}

@media (hover: none) and (pointer: coarse) {
  .toast {
    touch-action: pan-y;
  }

  .toast-close,
  .toast-action {
    min-height: 44px;
    min-width: 44px;
  }
}

@media (prefers-contrast: high) {
  .toast {
    border-width: 2px;
  }

  .toast-close:focus-visible,
  .toast-action:focus-visible {
    outline-width: 3px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .toast,
  .toast-progress-bar,
  .toast-close,
  .toast-action {
    transition: none;
  }
}

:host-context(.dark-theme) .toast,
:host-context([data-theme='dark']) .toast {
  background: var(--ds-surface);
  border-color: var(--ds-border);
  box-shadow: var(--ds-shadow-xl);
}

:host-context(.dark-theme) .toast-message,
:host-context([data-theme='dark']) .toast-message {
  color: var(--ds-text);
}

:host-context(.dark-theme) .toast-close:hover,
:host-context([data-theme='dark']) .toast-close:hover {
  background: var(--ds-surface-offset);
  color: var(--ds-text);
}

@media print {
  .toast-wrapper {
    display: none;
  }
}

