.message-recipient {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--ds-text);
}

.message-status {
  flex-shrink: 0;
}

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 500;
  white-space: nowrap;
}

.status-badge.status-queued {
  background: var(--ds-warning-hl);
  color: var(--ds-warning);
}

.status-badge.status-sending {
  background: var(--ds-marine-hl);
  color: var(--ds-marine);
}

.status-badge.status-sent {
  background: var(--ds-success-hl);
  color: var(--ds-success);
}

.status-badge.status-failed {
  background: var(--ds-error-hl);
  color: var(--ds-error);
}

.status-icon {
  font-size: 1rem;
}

.message-body {
  margin-bottom: 0.75rem;
}

.message-content {
  color: var(--ds-text);
  line-height: 1.6;
  margin: 0 0 0.5rem 0;
  word-wrap: break-word;
}

.message-template-info {
  margin-top: 0.5rem;
}

.template-badge {
  display: inline-block;
  padding: 0.25rem 0.5rem;
  background: var(--ds-bg);
  color: var(--ds-text-muted);
  border-radius: 0.25rem;
  font-size: 0.75rem;
  font-weight: 500;
}

.message-footer {
  border-top: 1px solid var(--ds-divider);
  padding-top: 0.75rem;
}

.message-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 0.5rem;
}

.meta-item {
  font-size: 0.75rem;
  color: var(--ds-text-muted);
}

.failure-info {
  margin-top: 0.75rem;
}

.failure-reason {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  padding: 0.5rem;
  background: var(--ds-error-hl);
  border: 1px solid var(--ds-error-hl);
  border-radius: 0.375rem;
  margin-bottom: 0.75rem;
}

.failure-icon {
  flex-shrink: 0;
  font-size: 1rem;
}

.failure-text {
  font-size: 0.875rem;
  color: var(--ds-error);
  line-height: 1.4;
}

.btn-retry-message {
  background: var(--ds-marine);
  color: white;
  border: none;
  border-radius: 0.375rem;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background 0.2s;
}

.btn-retry-message:hover:not(:disabled) {
  background: var(--ds-marine);
}

.btn-retry-message:disabled {
  background: var(--ds-text-faint);
  cursor: not-allowed;
}

@media (max-width: 640px) {
  .message-header {
    flex-direction: column;
    gap: 0.5rem;
  }

  .message-status {
    align-self: flex-start;
  }

  .message-meta {
    flex-direction: column;
    gap: 0.25rem;
  }

  .timeline {
    padding-left: 1.5rem;
  }

  .timeline::before {
    left: 0.5rem;
  }

  .timeline-marker {
    left: -1rem;
  }
}

