.ds-page-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--ds-space-4);
  margin-bottom: var(--ds-space-6);

  &--compact { margin-bottom: var(--ds-space-4); }

  &__main { min-width: 0; flex: 1; }

  &__eyebrow {
    font-size: 11px;
    font-weight: 600;
    color: var(--ds-text-muted);
    letter-spacing: 1.4px;
    text-transform: uppercase;
    margin-bottom: var(--ds-space-1);
  }

  &__title {
    font-family: var(--ds-font-display);
    font-size: clamp(24px, 2vw + 16px, 36px);
    font-weight: 500;
    /* Défense : certains patchs globaux historiques forçaient h1 en blanc (hero). */
    color: var(--ds-text) !important;
    letter-spacing: -0.3px;
    line-height: 1.05;
    margin: 0;
  }

  &__accent {
    font-style: italic;
    color: var(--ds-primary);
  }

  &__desc {
    font-size: 14px;
    color: var(--ds-text-muted);
    line-height: 1.55;
    max-width: 72ch;
    margin: var(--ds-space-2) 0 0;
  }

  &__actions {
    display: flex;
    align-items: center;
    gap: var(--ds-space-2);
    flex-wrap: wrap;
    flex-shrink: 0;
  }

  @media (max-width: 600px) {
    flex-direction: column;
    align-items: flex-start;
    &__actions { width: 100%; }
  }
}

