.photo-gallery-container {
  width: 100%;
  padding: 16px;
}

.empty-state {
  padding: 60px 20px;
  text-align: center;
  background-color: var(--ds-surface-2);
  border-radius: 8px;
  border: 1px dashed var(--ds-divider);
}

.empty-icon {
  font-size: 64px;
  width: 64px;
  height: 64px;
  color: var(--ds-border);
  margin: 0 auto 16px;
}

.empty-text {
  font-size: 18px;
  font-weight: 500;
  color: var(--ds-text-muted);
  margin: 0;
}

.masonry-grid {
  display: flex;
  gap: 16px;
  width: 100%;
}

.masonry-column {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.photo-item {
  position: relative;
  cursor: pointer;
  border-radius: 8px;
  overflow: hidden;
  background-color: var(--ds-bg);
  transition: transform 0.2s ease, box-shadow 0.3s ease;
  break-inside: avoid;
}

.photo-item:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
}

.photo-item.editable {
  cursor: grab;
}

.photo-item.editable:active {
  cursor: grabbing;
}

.photo-item.cdk-drag-preview {
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
  transform: rotate(2deg);
  opacity: 0.9;
}

.photo-item.cdk-drag-animating {
  transition: transform 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

.photo-wrapper {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.photo-placeholder {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  filter: blur(20px);
  transform: scale(1.1);
  z-index: 1;
}

.photo-image {
  position: relative;
  width: 100%;
  height: auto;
  display: block;
  opacity: 0;
  transition: opacity 0.4s ease;
  z-index: 2;
}

.photo-image.loading {
  opacity: 0;
}

.photo-image.loaded {
  opacity: 1;
}

.photo-image.error {
  opacity: 0.5;
  background-color: var(--ds-error-hl);
}

.photo-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.3s ease;
  z-index: 3;
}

.photo-item:hover .photo-overlay {
  opacity: 1;
}

.zoom-icon {
  color: white;
  font-size: 48px;
  width: 48px;
  height: 48px;
}

.delete-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 4;
  background-color: rgba(255, 255, 255, 0.9);
  color: var(--ds-error);
}

.delete-btn:hover {
  background-color: white;
}

.drag-handle {
  position: absolute;
  top: 8px;
  left: 8px;
  z-index: 4;
  background-color: rgba(255, 255, 255, 0.9);
  padding: 4px;
  border-radius: 4px;
  cursor: grab;
  display: flex;
  align-items: center;
  justify-content: center;
}

.drag-handle:active {
  cursor: grabbing;
}

.drag-handle mat-icon {
  color: var(--ds-text-muted);
  font-size: 20px;
  width: 20px;
  height: 20px;
}

.photo-title {
  padding: 12px;
  font-size: 14px;
  color: var(--ds-text);
  background-color: white;
  border-top: 1px solid var(--ds-divider);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lightbox-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.95);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.lightbox-container {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.lightbox-close {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 10001;
  background-color: rgba(255, 255, 255, 0.1);
  color: white;
  backdrop-filter: blur(10px);
}

.lightbox-close:hover {
  background-color: rgba(255, 255, 255, 0.2);
}

.lightbox-controls {
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10001;
  display: flex;
  align-items: center;
  gap: 8px;
  background-color: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 24px;
  padding: 8px 16px;
}

.control-btn {
  color: white;
}

.control-btn:disabled {
  color: rgba(255, 255, 255, 0.3);
}

.zoom-indicator {
  color: white;
  font-size: 14px;
  font-weight: 500;
  min-width: 48px;
  text-align: center;
}

.lightbox-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10001;
  background-color: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  color: white;
  width: 56px;
  height: 56px;
}

.lightbox-nav:hover {
  background-color: rgba(255, 255, 255, 0.2);
}

.lightbox-nav mat-icon {
  font-size: 36px;
  width: 36px;
  height: 36px;
}

.lightbox-prev {
  left: 16px;
}

.lightbox-next {
  right: 16px;
}

.lightbox-image-container {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 80px 80px 160px 80px;
}

.lightbox-image {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  transform-origin: center center;
  user-select: none;
}

.lightbox-image.zoomed {
  cursor: move;
}

.lightbox-image.dragging {
  transition: none;
}

.lightbox-info {
  position: absolute;
  bottom: 140px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10001;
  background-color: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(10px);
  border-radius: 8px;
  padding: 12px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.photo-counter {
  color: white;
  font-size: 14px;
  font-weight: 500;
}

.photo-title-lightbox {
  color: rgba(255, 255, 255, 0.9);
  font-size: 16px;
  max-width: 400px;
  text-align: center;
}

.lightbox-thumbnails {
  position: absolute;
  bottom: 16px;
  left: 0;
  right: 0;
  z-index: 10001;
  padding: 0 80px;
  overflow-x: auto;
  overflow-y: hidden;
}

.lightbox-thumbnails::-webkit-scrollbar {
  height: 4px;
}

.lightbox-thumbnails::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.1);
}

.lightbox-thumbnails::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.3);
  border-radius: 2px;
}

.lightbox-thumbnails::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.5);
}

.thumbnails-wrapper {
  display: flex;
  gap: 8px;
  padding: 8px 0;
  min-width: min-content;
}

.thumbnail-item {
  flex-shrink: 0;
  width: 80px;
  height: 60px;
  border-radius: 4px;
  overflow: hidden;
  cursor: pointer;
  border: 2px solid transparent;
  transition: border-color 0.2s ease, transform 0.2s ease;
  background-color: rgba(255, 255, 255, 0.1);
}

.thumbnail-item:hover {
  border-color: rgba(255, 255, 255, 0.5);
  transform: scale(1.05);
}

.thumbnail-item.active {
  border-color: white;
  box-shadow: 0 4px 12px rgba(255, 255, 255, 0.3);
}

.thumbnail-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.lightbox-keyboard-hints {
  position: absolute;
  bottom: 92px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10001;
  display: flex;
  gap: 16px;
  background-color: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(10px);
  border-radius: 8px;
  padding: 8px 16px;
}

.hint {
  color: rgba(255, 255, 255, 0.8);
  font-size: 12px;
  display: flex;
  align-items: center;
  gap: 4px;
}

kbd {
  background-color: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 4px;
  padding: 2px 6px;
  font-size: 11px;
  font-family: monospace;
  color: white;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

@media (max-width: 1024px) {
  .masonry-grid {
    gap: 12px;
  }

  .masonry-column {
    gap: 12px;
  }

  .photo-item:hover {
    transform: none;
  }

  .lightbox-image-container {
    padding: 80px 60px 160px 60px;
  }

  .lightbox-thumbnails {
    padding: 0 60px;
  }

  .thumbnail-item {
    width: 70px;
    height: 52px;
  }

  .lightbox-keyboard-hints {
    display: none;
  }
}

@media (max-width: 768px) {
  .photo-gallery-container {
    padding: 12px;
  }

  .masonry-grid {
    gap: 8px;
  }

  .masonry-column {
    gap: 8px;
  }

  .photo-item {
    border-radius: 4px;
  }

  .delete-btn {
    top: 4px;
    right: 4px;
  }

  .drag-handle {
    top: 4px;
    left: 4px;
  }

  .photo-title {
    padding: 8px;
    font-size: 12px;
  }

  .lightbox-controls {
    top: 12px;
    padding: 4px 12px;
  }

  .zoom-indicator {
    font-size: 12px;
    min-width: 40px;
  }

  .lightbox-nav {
    width: 48px;
    height: 48px;
  }

  .lightbox-nav mat-icon {
    font-size: 32px;
    width: 32px;
    height: 32px;
  }

  .lightbox-prev {
    left: 8px;
  }

  .lightbox-next {
    right: 8px;
  }

  .lightbox-image-container {
    padding: 70px 16px 140px 16px;
  }

  .lightbox-info {
    bottom: 120px;
    padding: 8px 16px;
  }

  .photo-counter {
    font-size: 12px;
  }

  .photo-title-lightbox {
    font-size: 14px;
    max-width: 280px;
  }

  .lightbox-thumbnails {
    padding: 0 16px;
  }

  .thumbnail-item {
    width: 60px;
    height: 45px;
  }

  .thumbnails-wrapper {
    gap: 6px;
  }
}

@media (max-width: 480px) {
  .photo-gallery-container {
    padding: 8px;
  }

  .masonry-grid {
    gap: 6px;
  }

  .masonry-column {
    gap: 6px;
  }

  .zoom-icon {
    font-size: 36px;
    width: 36px;
    height: 36px;
  }

  .lightbox-controls {
    flex-wrap: wrap;
    gap: 4px;
    padding: 4px 8px;
  }

  .control-btn {
    width: 36px;
    height: 36px;
    padding: 0;
  }

  .control-btn mat-icon {
    font-size: 20px;
    width: 20px;
    height: 20px;
  }

  .lightbox-nav {
    width: 40px;
    height: 40px;
  }

  .lightbox-nav mat-icon {
    font-size: 28px;
    width: 28px;
    height: 28px;
  }

  .lightbox-image-container {
    padding: 60px 8px 120px 8px;
  }

  .lightbox-info {
    bottom: 100px;
    padding: 6px 12px;
  }

  .photo-title-lightbox {
    font-size: 12px;
    max-width: 240px;
  }

  .thumbnail-item {
    width: 50px;
    height: 38px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .photo-item,
  .lightbox-image,
  .photo-image,
  .photo-overlay,
  .thumbnail-item {
    transition: none;
  }

  .lightbox-overlay {
    animation: none;
  }
}

