    styleUrls: ['./promoteurs.component.scss'],
    imports: [RouterLink]
})
export class PromoTeursComponent {
  readonly features = [
    { icon: '🏗️', title: 'Gestion de programmes', desc: 'Créez et gérez vos programmes avec lots, plans, disponibilités et prix.' },
