.pwa-install-banner {
  position: fixed;
  bottom: 80px;
  left: var(--ds-space-4);
  right: var(--ds-space-4);
  background: var(--ds-surface);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-lg);
  padding: var(--ds-space-4);
  z-index: 1001; /* au-dessus de la barre mobile (1000) ; non couvert par l’échelle --ds-z-* */
  max-width: 500px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .pwa-install-banner {
    bottom: var(--ds-space-6);
    left: var(--ds-space-6);
    right: auto;
  }
}

.banner-content {
  display: flex;
  align-items: flex-start;
  gap: var(--ds-space-3);
}

.banner-icon {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--ds-marine) 0%, var(--ds-marine-light) 100%);
  border-radius: var(--ds-radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ds-text-inverse);
}

.banner-icon mat-icon {
  font-size: 28px;
  width: 28px;
  height: 28px;
}

.banner-text {
  flex: 1;
  min-width: 0;
}

.banner-text h4 {
  margin: 0 0 var(--ds-space-1) 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--ds-text);
}

.banner-text p {
  margin: 0;
  font-size: 13px;
  color: var(--ds-text-muted);
  line-height: 1.4;
}

.banner-actions {
  display: flex;
  gap: var(--ds-space-2);
  margin-top: var(--ds-space-3);
  flex-wrap: wrap;
}

.btn-dismiss,
.btn-install {
