:host { display: block; }

.sr-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--ds-space-6);
  align-items: start;
  max-width: var(--ds-content-wide);
  margin-inline: auto;
  padding: var(--ds-space-8) clamp(var(--ds-space-4), 4vw, var(--ds-space-12));
}

/* SIDEBAR */
.sr-sidebar {
  background: var(--ds-surface);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-xl);
  padding: var(--ds-space-6);
  position: sticky;
  top: 80px;
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-5);
}

.sr-filters-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: var(--ds-space-4);
  border-bottom: 1px solid var(--ds-divider);
}

.sr-filters-header h2 {
  font-family: var(--ds-font-display);
  font-size: var(--ds-text-base);
  font-weight: 700;
  color: var(--ds-text);
  margin: 0;
}

.sr-filter-group { display: flex; flex-direction: column; gap: var(--ds-space-2); }
.sr-filter-label { font-size: var(--ds-text-xs); font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ds-text-faint); margin: 0; }

.sr-chip-group { display: flex; flex-wrap: wrap; gap: var(--ds-space-2); }
.sr-chip {
  padding: var(--ds-space-1) var(--ds-space-3);
  border-radius: var(--ds-radius-pill);
  font-size: var(--ds-text-xs);
  font-weight: 600;
  cursor: pointer;
  border: 1.5px solid var(--ds-border);
  background: transparent;
  color: var(--ds-text-muted);
  font-family: var(--ds-font-body);
  transition: all var(--ds-transition-fast);
}
.sr-chip.active { background: var(--ds-primary); color: white; border-color: var(--ds-primary); }
.sr-chip:not(.active):hover { border-color: var(--ds-primary); color: var(--ds-primary); }

.sr-range-row { display: flex; align-items: center; gap: var(--ds-space-2); }
.sr-range-row .at-form-input { font-size: var(--ds-text-xs); padding: var(--ds-space-2) var(--ds-space-3); }

/* RESULTS */
.sr-results-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-space-4);
  margin-bottom: var(--ds-space-6);
  flex-wrap: wrap;
}

.sr-count { font-size: var(--ds-text-sm); color: var(--ds-text-muted); margin: 0; }
.sr-count strong { color: var(--ds-text); }

.sr-sort { display: flex; align-items: center; gap: var(--ds-space-3); }
.sr-sort .at-form-select { width: auto; min-width: 160px; padding: var(--ds-space-2) var(--ds-space-8) var(--ds-space-2) var(--ds-space-3); font-size: var(--ds-text-xs); }

/* GRID — shared with home */
.sr-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--ds-space-5);
  margin-bottom: var(--ds-space-8);
}

.sr-listing-card {
  background: var(--ds-surface);
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-xl);
  overflow: hidden;
  cursor: pointer;
  transition: box-shadow var(--ds-transition-med), transform var(--ds-transition-med);
  display: flex;
  flex-direction: column;
}

.sr-listing-card:hover {
  box-shadow: var(--ds-shadow-lg);
  transform: translateY(-3px);
}

.sr-listing-card:hover .sr-listing-img img { transform: scale(1.04); }

.sr-listing-img {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
  flex-shrink: 0;
}

.sr-listing-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Inherit shared classes from portail-home */
.ph-tx-badge { position: absolute; top: var(--ds-space-3); left: var(--ds-space-3); font-size: var(--ds-text-xs); font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; padding: var(--ds-space-1) var(--ds-space-3); border-radius: var(--ds-radius-pill); }
.tx-vente    { background: var(--ds-marine); color: white; }
.tx-location { background: var(--ds-success); color: var(--ds-text-inverse); }
.ph-badges   { position: absolute; top: var(--ds-space-3); right: var(--ds-space-3); }
.ph-listing-body { padding: var(--ds-space-5); display: flex; flex-direction: column; gap: var(--ds-space-2); flex: 1; }
.ph-price  { font-family: var(--ds-font-display); font-size: 1.1rem; font-weight: 700; color: var(--ds-text); line-height: 1; }
.ph-title  { font-size: var(--ds-text-sm); font-weight: 600; color: var(--ds-text); line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; max-width: none; }
.ph-location { display: flex; align-items: center; gap: var(--ds-space-1); font-size: var(--ds-text-xs); color: var(--ds-text-muted); }
.ph-meta { display: flex; align-items: center; gap: var(--ds-space-4); padding-top: var(--ds-space-3); margin-top: auto; border-top: 1px solid var(--ds-divider); }
.ph-meta-item { display: flex; align-items: center; gap: var(--ds-space-1); font-size: var(--ds-text-xs); color: var(--ds-text-muted); font-weight: 500; }
.ph-meta-date { margin-left: auto; font-size: 10px; color: var(--ds-text-faint); }

@media (max-width: 1024px) {
  .sr-layout { grid-template-columns: 240px 1fr; }
  .sr-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .sr-layout { grid-template-columns: 1fr; }
  .sr-sidebar { position: static; }
  .sr-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .sr-grid { grid-template-columns: 1fr; }
}

