  }

  .rb-card-subtitle {
    margin: 0;
    font-size: 0.875rem;
    color: var(--ds-text-muted);
  }

  .rb-card-body {
    padding: 16px;
  }

  .builder-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 30px;
    margin: 20px 0;

    @media (max-width: 768px) {
      grid-template-columns: 1fr;
    }
  }

  h3 {
    margin-bottom: 12px;
    font-size: 16px;
    font-weight: 500;
    color: var(--ds-text);
  }

