    align-items: center;
    padding: 12px;
    margin-bottom: 8px;
    background-color: var(--ds-surface);
    border: 1px solid var(--ds-border);
    border-radius: var(--ds-radius-sm);
    cursor: move;
    transition: all 0.2s;

    &:hover {
      box-shadow: var(--ds-shadow-sm);
    }

    &.cdk-drag-preview {
      box-shadow: var(--ds-shadow-md);
      opacity: 0.8;
    }

    &.cdk-drag-placeholder {
      opacity: 0.3;
    }

    &.selected-item {
      border-color: var(--ds-marine);
      background-color: var(--ds-marine-hl);
    }

    mat-icon {
      margin-right: 8px;
      color: var(--ds-text-faint);
    }

    .item-content {
      flex: 1;

      strong {
        display: block;
        font-size: 14px;
        margin-bottom: 4px;
      }

      small {
        display: block;
        color: var(--ds-text-muted);
        font-size: 12px;
      }
    }

    button {
      margin-left: auto;
    }
  }

  .empty-message {
    text-align: center;
    color: var(--ds-text-faint);
    padding: 40px 20px;
    font-style: italic;
  }

  .actions-section {
    margin-top: 24px;
    display: flex;
    gap: 12px;

    button {
      mat-icon {
        margin-right: 8px;
      }
    }
  }

  .export-controls {
    display: flex;
    gap: 16px;
    align-items: center;
    margin-bottom: 20px;
    flex-wrap: wrap;

    mat-form-field {
      flex: 0 0 auto;
      min-width: 200px;
    }

    button {
      mat-icon {
        margin-right: 8px;
      }
    }
  }

  .table-container {
    overflow-x: auto;
    margin-top: 20px;

    .report-table {
      width: 100%;

      th {
        background-color: var(--ds-surface-offset);
        font-weight: 600;
      }

      td, th {
        padding: 12px;
        text-align: left;
      }

      tr:hover {
        background-color: var(--ds-surface-2);
      }
    }
  }

  .loading-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: color-mix(in srgb, var(--ds-surface) 90%, transparent);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
  }
}

