            return `${label}: €${(value || 0).toLocaleString()}`;
          }
        }
      }
    },
    scales: {
      y: {
        beginAtZero: true,
        title: {
          display: true,
          text: 'Revenue (€)'
        },
        ticks: {
          callback: (value: any) => '€' + value.toLocaleString()
        }
      },
      x: {
        title: {
          display: true,
          text: 'Date'
        }
      }
    }
  }

