/* ── Access Denied / Session Expired — shared error page DS ── */
.err-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ds-bg);
  padding: 24px;
}

.err-page__card {
  max-width: 440px;
  width: 100%;
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-xl, 20px);
  padding: 48px 40px 40px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 28px;
  box-shadow: 0 8px 40px rgba(13,44,74,.08);
  position: relative;
  overflow: hidden;
}

.err-page__circle {
  position: absolute;
  border-radius: 50%;
  opacity: 0.06;
  pointer-events: none;
}
.err-page__circle--1 {
  width: 320px; height: 320px;
  background: var(--ds-marine);
  top: -120px; right: -100px;
}
.err-page__circle--2 {
  width: 200px; height: 200px;
  background: var(--ds-primary);
  bottom: -80px; left: -60px;
}

.err-page__illus {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.err-page__icon-svg { width: 80px; height: 80px; }

.err-page__body { text-align: center; }

.err-page__code {
  display: block;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--ds-text-faint);
  margin-bottom: 8px;
}

.err-page__title {
  font-size: 26px;
  font-weight: 800;
  color: var(--ds-text);
  margin: 0 0 12px;
  font-family: var(--ds-font-display, var(--ds-font-body));
}

.err-page__message {
  font-size: 14px;
  color: var(--ds-text-muted);
  line-height: 1.6;
  margin: 0;
}

.err-page__actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
}

.err-page__help {
  font-size: 12.5px;
  color: var(--ds-text-faint);
  text-decoration: none;
}
.err-page__help:hover {
  color: var(--ds-marine);
  text-decoration: underline;
}

