}

.notification-info strong {
  display: block;
  margin-bottom: 4px;
  font-size: 14px;
}

.notification-info p {
  margin: 0;
  font-size: 12px;
  color: var(--ds-text-muted);
}

.dark-theme .notification-info p {
  color: var(--ds-text-faint);
}

.theme-selector {
  margin-bottom: 24px;
}

.theme-toggle-group {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 8px;
