  color: white;
  margin-bottom: 16px;
  transition: all 0.3s ease;
}

.preview-card.dark-preview {
  background: linear-gradient(135deg, var(--ds-text) 0%, var(--ds-text) 100%);
}

.preview-card h3 {
  margin: 0 0 8px 0;
  font-size: 18px;
  font-weight: 500;
}

.preview-card p {
  margin: 0 0 16px 0;
  opacity: 0.9;
}

.preview-box {
  background: var(--ds-bg);
  padding: 16px;
  border-radius: 8px;
  margin-top: 16px;
}

.dark-theme .preview-box {
  background: var(--ds-text);
}

.preview-box h4 {
  margin: 0 0 12px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--ds-text-muted);
}

.dark-theme .preview-box h4 {
  color: var(--ds-text-faint);
}

.preview-content p {
  margin: 8px 0;
  font-size: 14px;
}

.section-divider {
  margin: 24px 0;
}

.shortcuts-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 24px;
}

.shortcut-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.shortcut-info {
  flex: 1;
}

.shortcut-info strong {
  display: block;
  margin-bottom: 4px;
  font-size: 14px;
}

.shortcut-info p {
  margin: 0;
  font-size: 12px;
  color: var(--ds-text-muted);
}

.dark-theme .shortcut-info p {
  color: var(--ds-text-faint);
}

.shortcut-input {
  width: 150px;
}

.shortcuts-hint {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 24px;
  padding: 12px;
  background: var(--ds-marine-hl);
  border-radius: 4px;
  color: var(--ds-marine);
  font-size: 13px;
}

.dark-theme .shortcuts-hint {
  background: var(--ds-marine-hl);
  color: var(--ds-marine-light);
}

.shortcuts-hint mat-icon,
.shortcuts-hint ds-icon {
  font-size: 18px;
  width: 18px;
  height: 18px;
}

kbd {
  display: inline-block;
  padding: 2px 6px;
  background: var(--ds-bg);
  border: 1px solid var(--ds-border);
  border-radius: 3px;
  font-family: monospace;
  font-size: 12px;
  box-shadow: var(--ds-shadow-xs);
}

.dark-theme kbd {
  background: var(--ds-text);
  border-color: var(--ds-text-muted);
  color: var(--ds-text-inverse);
}

.integration-item {
  padding: 16px 0;
}

.integration-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 12px;
}

.integration-header mat-icon {
  color: var(--ds-marine);
  font-size: 32px;
  width: 32px;
  height: 32px;
}

.integration-header ds-icon {
  color: var(--ds-marine);
}

.dark-theme .integration-header mat-icon {
  color: var(--ds-marine-light);
}

.dark-theme .integration-header ds-icon {
  color: var(--ds-marine-light);
}

.integration-header > div {
  flex: 1;
}

.integration-header strong {
  display: block;
  margin-bottom: 4px;
  font-size: 14px;
}

.integration-header p {
  margin: 0;
  font-size: 12px;
  color: var(--ds-text-muted);
}

.dark-theme .integration-header p {
  color: var(--ds-text-faint);
}

.integration-config {
  width: 100%;
  margin-left: 48px;
}

.system-settings {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.warn-text {
  color: var(--ds-error) !important;
}

.settings-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
  background: var(--ds-surface);
  border-radius: 8px;
  box-shadow: var(--ds-shadow-xs);
  position: sticky;
  bottom: 24px;
}

.dark-theme .settings-actions {
  background: var(--ds-text);
}

.actions-right {
  display: flex;
  gap: 12px;
}

.button-spinner {
  display: inline-block;
  margin-right: 8px;
}

.settings-actions ds-button {
  --settings-action-gap: 8px;
}

/* Responsive */
@media (max-width: 768px) {
  .settings-page {
    padding: 16px;
  }

  .settings-header {
    padding: 16px;
  }

  .settings-title {
    font-size: 24px;
  }

  .tab-content {
    padding: 16px;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .theme-toggle-group {
    grid-template-columns: 1fr;
  }

  .shortcut-item {
    flex-direction: column;
    align-items: flex-start;
  }

  .shortcut-input {
    width: 100%;
  }

  .settings-actions {
    flex-direction: column;
    gap: 12px;
  }

  .actions-right {
    width: 100%;
  }

  .actions-right button {
    flex: 1;
  }
}

/* Animations */
ds-card.settings-card {
  animation: slideIn 0.3s ease-out;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Form validation feedback */
mat-form-field.ng-invalid.ng-touched .mat-form-field-outline {
  border-color: var(--ds-error);
}

mat-form-field.ng-valid.ng-touched .mat-form-field-outline {
  border-color: var(--ds-success);
}

/* Hover effects */
.notification-item:hover,
.integration-item:hover {
  background-color: var(--ds-surface-offset);
  border-radius: 4px;
}

.dark-theme .notification-item:hover,
.dark-theme .integration-item:hover {
  background-color: var(--ds-surface-offset);
}

/* Button states */
button[disabled] {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Smooth transitions */
mat-slide-toggle,
mat-checkbox,
mat-button-toggle {
  transition: all 0.2s ease;
}

