/* ========================================
   SPINNER CONTAINER
   ======================================== */
.spinner-container {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-3, 0.75rem);
}

/* ========================================
   SIZE VARIANTS
   ======================================== */

/* Small: 16px */
.spinner-sm .spinner-svg {
  width: 16px;
  height: 16px;
}

.spinner-sm .spinner-linear {
  width: 80px;
  height: 3px;
}

.spinner-sm .spinner-dots {
  gap: var(--spacing-1, 0.25rem);
}

.spinner-sm .spinner-dot {
  width: 4px;
  height: 4px;
}

.spinner-sm .spinner-message,
.spinner-sm .spinner-timeout-message {
  font-size: var(--font-size-xs, 0.75rem);
}

/* Medium: 24px */
.spinner-md .spinner-svg {
  width: 24px;
  height: 24px;
}

.spinner-md .spinner-linear {
  width: 120px;
  height: 4px;
}

.spinner-md .spinner-dots {
  gap: var(--spacing-2, 0.5rem);
}

.spinner-md .spinner-dot {
  width: 6px;
  height: 6px;
}

.spinner-md .spinner-message,
.spinner-md .spinner-timeout-message {
  font-size: var(--font-size-sm, 0.875rem);
}

/* Large: 48px */
.spinner-lg .spinner-svg {
  width: 48px;
  height: 48px;
}

.spinner-lg .spinner-linear {
  width: 200px;
  height: 6px;
}

.spinner-lg .spinner-dots {
  gap: var(--spacing-3, 0.75rem);
}

.spinner-lg .spinner-dot {
  width: 10px;
  height: 10px;
}

.spinner-lg .spinner-message,
.spinner-lg .spinner-timeout-message {
  font-size: var(--font-size-base, 0.875rem);
}

/* ========================================
   COLOR VARIANTS
   ======================================== */

/* Primary */
.spinner-primary .spinner-path {
  stroke: var(--ds-marine);
}

.spinner-primary .spinner-track {
  stroke: var(--ds-divider);
}

.spinner-primary .spinner-linear-bar {
  background-color: var(--ds-marine);
}

.spinner-primary .spinner-linear-track {
  background-color: var(--ds-divider);
}

.spinner-primary .spinner-dot {
  background-color: var(--ds-marine);
}

.spinner-primary .spinner-message,
.spinner-primary .spinner-timeout-message {
  color: var(--ds-text-muted);
}

/* White */
.spinner-white .spinner-path {
  stroke: var(--ds-surface);
}

.spinner-white .spinner-track {
  stroke: rgba(255, 255, 255, 0.2);
}

.spinner-white .spinner-linear-bar {
  background-color: var(--ds-surface);
}

.spinner-white .spinner-linear-track {
  background-color: rgba(255, 255, 255, 0.2);
}

.spinner-white .spinner-dot {
  background-color: var(--ds-surface);
}

.spinner-white .spinner-message,
.spinner-white .spinner-timeout-message {
  color: var(--ds-surface);
}

/* Neutral */
.spinner-neutral .spinner-path {
  stroke: var(--ds-text-muted);
}

.spinner-neutral .spinner-track {
  stroke: var(--ds-divider);
}

.spinner-neutral .spinner-linear-bar {
  background-color: var(--ds-text-muted);
}

.spinner-neutral .spinner-linear-track {
  background-color: var(--ds-divider);
}

.spinner-neutral .spinner-dot {
  background-color: var(--ds-text-muted);
}

.spinner-neutral .spinner-message,
.spinner-neutral .spinner-timeout-message {
  color: var(--ds-text-muted);
}

/* ========================================
   CIRCULAR SPINNER
   ======================================== */
.spinner-circular {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.spinner-svg {
  display: block;
  animation: spinner-rotate 1.4s linear infinite;
  will-change: transform;
}

.spinner-track {
  opacity: 0.2;
}

.spinner-path {
  stroke-dasharray: 90, 150;
  stroke-dashoffset: 0;
  animation: spinner-dash 1.4s ease-in-out infinite;
  transform-origin: center;
  will-change: stroke-dasharray, stroke-dashoffset;
}

@keyframes spinner-rotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

@keyframes spinner-dash {
  0% {
    stroke-dasharray: 1, 150;
    stroke-dashoffset: 0;
  }
  50% {
    stroke-dasharray: 90, 150;
    stroke-dashoffset: -35;
  }
  100% {
    stroke-dasharray: 90, 150;
    stroke-dashoffset: -124;
  }
}

/* ========================================
   LINEAR SPINNER
   ======================================== */
.spinner-linear {
  position: relative;
  overflow: hidden;
}

.spinner-linear-track {
  width: 100%;
  height: 100%;
  border-radius: var(--radius-full, 9999px);
  position: relative;
  overflow: hidden;
}

.spinner-linear-bar {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  border-radius: var(--radius-full, 9999px);
  will-change: transform, opacity;
}

.spinner-linear-bar-1 {
  animation: spinner-linear-1 2s cubic-bezier(0.65, 0.815, 0.735, 0.395) infinite;
}

.spinner-linear-bar-2 {
  animation: spinner-linear-2 2s cubic-bezier(0.165, 0.84, 0.44, 1) infinite;
  animation-delay: 0.5s;
}

@keyframes spinner-linear-1 {
  0% {
    left: -35%;
    right: 100%;
    opacity: 1;
  }
  60% {
    left: 100%;
    right: -90%;
    opacity: 1;
  }
  100% {
    left: 100%;
    right: -90%;
    opacity: 0;
  }
}

@keyframes spinner-linear-2 {
  0% {
    left: -200%;
    right: 100%;
    opacity: 1;
  }
  60% {
    left: 107%;
    right: -8%;
    opacity: 1;
  }
  100% {
    left: 107%;
    right: -8%;
    opacity: 0;
  }
}

/* ========================================
   DOTS SPINNER
   ======================================== */
.spinner-dots {
  display: inline-flex;
  align-items: center;
}

.spinner-dot {
  border-radius: var(--radius-full, 9999px);
  animation: spinner-dots-bounce 1.4s ease-in-out infinite;
  will-change: transform, opacity;
}

.spinner-dot:nth-child(1) {
  animation-delay: 0s;
}

.spinner-dot:nth-child(2) {
  animation-delay: 0.2s;
}

.spinner-dot:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes spinner-dots-bounce {
  0%, 80%, 100% {
    transform: scale(0.8);
    opacity: 0.5;
  }
  40% {
    transform: scale(1.2);
    opacity: 1;
  }
}

/* ========================================
   MESSAGES
   ======================================== */
.spinner-message {
  text-align: center;
  line-height: var(--line-height-normal, 1.5);
  font-weight: var(--font-weight-medium, 500);
  margin: 0;
  animation: spinner-fade-in 0.3s ease-out;
}

.spinner-timeout-message {
  text-align: center;
  line-height: var(--line-height-normal, 1.5);
  font-weight: var(--font-weight-medium, 500);
  margin: 0;
  color: var(--ds-warning);
  animation: spinner-fade-in 0.3s ease-out;
}

@keyframes spinner-fade-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ========================================
   CANCEL BUTTON
   ======================================== */
.spinner-cancel-btn {
  margin-top: var(--spacing-2, 0.5rem);
  padding: var(--spacing-2, 0.5rem) var(--spacing-4, 1rem);
  font-size: var(--font-size-sm, 0.875rem);
  font-weight: var(--font-weight-medium, 500);
  color: var(--ds-marine);
  background-color: transparent;
  border: 1px solid var(--ds-marine);
  border-radius: var(--radius-md, 0.375rem);
  cursor: pointer;
  transition: background-color var(--duration-normal, 200ms) ease-in-out,
              transform var(--duration-fast, 100ms) ease-out,
              opacity var(--duration-normal, 200ms) ease-in-out;
  animation: spinner-fade-in 0.3s ease-out;
  will-change: transform, opacity;
}

.spinner-cancel-btn:hover {
  background-color: color-mix(in oklab, var(--ds-marine) 10%, transparent);
}

.spinner-cancel-btn:active {
  transform: scale(0.96);
}

.spinner-cancel-btn:focus {
  outline: 2px solid var(--ds-marine);
  outline-offset: 2px;
}

.spinner-white .spinner-cancel-btn {
  color: var(--ds-surface);
  border-color: var(--ds-surface);
}

.spinner-white .spinner-cancel-btn:hover {
  background-color: rgba(255, 255, 255, 0.1);
}

/* ========================================
   PERFORMANCE OPTIMIZATIONS
   ======================================== */

/* Use GPU acceleration for animations */
.spinner-svg,
.spinner-linear-bar,
.spinner-dot,
.spinner-message,
.spinner-timeout-message,
.spinner-cancel-btn {
  transform: translateZ(0);
  backface-visibility: hidden;
}

/* Reduce motion for accessibility */
@media (prefers-reduced-motion: reduce) {
  .spinner-svg,
  .spinner-path,
  .spinner-linear-bar,
  .spinner-dot,
  .spinner-message,
  .spinner-timeout-message,
  .spinner-cancel-btn {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .spinner-path {
    stroke-dasharray: 90, 150;
    stroke-dashoffset: -35;
  }

  .spinner-dot {
    transform: scale(1);
    opacity: 1;
  }
}

