.task-card {
  display: block;
  margin-bottom: 16px;
  position: relative;
}

.task-card > .ds-card {
  transition: all 0.3s ease;
}

.task-card:hover > .ds-card {
  box-shadow: var(--ds-shadow-md);
  transform: translateY(-2px);
}

.task-card.overdue > .ds-card {
  border-left: 4px solid var(--ds-error);
  animation: pulse 2s ease-in-out infinite;
}

.task-card.completed > .ds-card {
  opacity: 0.7;
  background-color: var(--ds-surface-offset);
}

@keyframes pulse {
  0%, 100% {
    box-shadow: 0 2px 4px rgba(231, 76, 60, 0.3);
  }
  50% {
    box-shadow: 0 4px 12px rgba(231, 76, 60, 0.6);
  }
}

.task-card-header {
  padding: 16px 16px 0;
}

.task-card-body {
  padding: 0 16px 16px;
}

.task-header {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
}

.task-done-checkbox {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  accent-color: var(--ds-marine);
  cursor: pointer;
}

.task-title {
  flex: 1;
  font-size: 16px;
  font-weight: 500;
  color: var(--ds-text);
}

.task-title.completed-text {
  text-decoration: line-through;
  color: var(--ds-text-faint);
}

.priority-badge {
  padding: 4px 12px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.priority-badge.priority-high {
  background-color: var(--ds-error-hl);
  color: var(--ds-error);
  border: 1px solid var(--ds-error);
}

.priority-badge.priority-medium {
  background-color: var(--ds-warning-hl);
  color: var(--ds-warning);
  border: 1px solid var(--ds-warning);
}

.priority-badge.priority-low {
  background-color: var(--ds-success-hl);
  color: var(--ds-success);
  border: 1px solid var(--ds-success);
}

.task-description {
  margin: 12px 0;
  color: var(--ds-text-muted);
  font-size: 14px;
  line-height: 1.5;
}

.task-meta {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 12px;
}

.meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--ds-text-muted);
}

.meta-item ds-icon {
  flex-shrink: 0;
  color: var(--ds-text-faint);
}

.meta-item.due-date {
  font-weight: 500;
}

.overdue-text {
  color: var(--ds-error) !important;
}

.overdue-text mat-icon {
  color: var(--ds-error) !important;
}

.approaching-text {
  color: var(--ds-warning) !important;
}

.approaching-text ds-icon {
  color: var(--ds-warning) !important;
}

.warning-icon {
  animation: warningBlink 1.5s ease-in-out infinite;
}

@keyframes warningBlink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

.task-card-actions {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: var(--ds-space-2);
  padding: 8px 16px 16px;
}

.task-card-actions ds-button ds-icon {
  margin-right: 2px;
}

@media (max-width: 599px) {
  .task-header {
    flex-wrap: wrap;
  }
  
  .priority-badge {
    order: -1;
    margin-left: 36px;
  }
}

