/* Task list — Atlasia DS */

.task-pro .task-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ds-space-2);
  align-items: center;
}

.task-layout-toggle {
  display: flex;
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-sm);
  overflow: hidden;
  background: var(--ds-surface);
}

.task-layout-btn {
  width: 36px;
  height: 32px;
  border: none;
  background: transparent;
  color: var(--ds-text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--ds-transition-fast), color var(--ds-transition-fast);
}

.task-layout-btn--active {
  background: var(--ds-marine-hl);
  color: var(--ds-marine);
}

.task-layout-btn:hover:not(.task-layout-btn--active) {
  background: var(--ds-surface-offset);
}

.task-table-card {
  border-radius: var(--ds-radius-lg);
  overflow: hidden;
}

.task-ds-title {
  font-weight: 600;
  font-size: 13.5px;
  color: var(--ds-text);
}

.task-ds-muted {
  font-size: 13px;
  color: var(--ds-text-muted);
}

.task-ds-due {
  font-size: 12.5px;
  color: var(--ds-text-muted);
}

.task-ds-due--late {
  color: var(--ds-error);
  font-weight: 600;
}

.task-toolbar-card {
  margin-bottom: var(--ds-space-6);
}

.task-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--ds-space-5);
}

.task-toolbar__left,
.task-toolbar__right {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: var(--ds-space-4);
  min-width: 0;
}

.task-status-field {
  width: 240px;
}

.task-content {
  margin-top: var(--ds-space-4);
}

.tasks-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 340px), 1fr));
  gap: var(--ds-space-4);
}

.task-calendar-card {
  overflow: hidden;
}

.task-calendar-inner {
  padding: var(--ds-space-4);
}

.task-week-grid-wrap {
  min-height: 520px;
}

.task-week-grid-wrap ds-week-grid {
  display: block;
  min-height: 480px;
}

.task-loading {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-4);
  margin-top: var(--ds-space-4);
}

@media (max-width: 768px) {
  .task-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .task-toolbar__left,
  .task-toolbar__right {
    flex-direction: column;
    align-items: stretch;
  }

  .task-status-field {
    width: 100%;
  }
}

