/* ── Tasks page ── */
.tasks-page {
  max-width: 860px;
  margin: 0 auto;
  padding: 20px 24px 48px;
}

/* ── KPIs ── */
.tasks-kpi-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin: 20px 0;
}

.tasks-kpi {
  padding: 14px 16px;
  text-align: center;
  transition: box-shadow var(--ds-transition-fast), border-color var(--ds-transition-fast);
  border: 1px solid transparent;

  &--active {
    border-color: var(--ds-marine);
    box-shadow: 0 0 0 2px var(--ds-marine-hl);
  }

  &__count {
    font-size: 24px;
    font-weight: 700;
    color: var(--ds-marine);
    line-height: 1.2;
  }

  &__label {
    font-size: 12px;
    color: var(--ds-text-muted);
    margin-top: 2px;
  }
}

/* ── Filtres ── */
.tasks-filters {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.tasks-search {
  flex: 1;
  min-width: 200px;
  height: 38px;
  padding: 0 14px;
  border: 1px solid var(--ds-border);
  border-radius: var(--ds-radius-md);
  background: var(--ds-surface);
  color: var(--ds-text);
  font-size: 13.5px;
  font-family: var(--ds-font-body);
  outline: none;
  transition: border-color var(--ds-transition-fast);

  &:focus { border-color: var(--ds-marine); }
  &::placeholder { color: var(--ds-text-faint); }
}

.tasks-priority-chips {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

/* ── Liste ── */
.tasks-list {
  margin-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: var(--ds-surface);
  border: 1px solid var(--ds-divider);
  border-radius: var(--ds-radius-md);
  transition: border-color var(--ds-transition-fast), background var(--ds-transition-fast);

  &:hover { border-color: var(--ds-border); background: var(--ds-surface-2); }

  &--done {
    opacity: 0.55;
    .task-title { text-decoration: line-through; color: var(--ds-text-muted); }
  }
}

.task-check {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border: 1.5px solid var(--ds-border);
  border-radius: var(--ds-radius-sm);
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ds-text-inverse);
  transition: border-color var(--ds-transition-fast), background var(--ds-transition-fast);

  &:hover { border-color: var(--ds-marine); }

  &--done {
    background: var(--ds-marine);
    border-color: var(--ds-marine);
  }
}

.task-body {
  flex: 1;
  overflow: hidden;
}

.task-title {
  font-size: 13.5px;
  font-weight: 500;
  color: var(--ds-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.task-meta {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-top: 3px;
}

.task-ref {
  font-size: 11px;
  font-weight: 600;
  color: var(--ds-marine);
  background: var(--ds-marine-hl);
  padding: 1px 6px;
  border-radius: var(--ds-radius-sm);
}

.task-due {
  font-size: 11px;
  color: var(--ds-text-faint);
  display: inline-flex;
  align-items: center;
  gap: 3px;

  &--urgent {
    color: var(--ds-error);
    font-weight: 600;
  }
}

