.template-editor-container {
  padding: 24px;
  max-width: 1600px;
  margin: 0 auto;
}

.editor-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}

.editor-header h2 {
  margin: 0;
  font-size: 28px;
  font-weight: 500;
}

.editor-content {
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: 24px;
}

.form-section {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.te-section-card {
  display: block;
  margin-bottom: 24px;
}

.te-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  padding: 16px 16px 0;
  gap: 8px;
}

.te-card-title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
}

.te-card-body {
  padding: 0 16px 16px;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.full-width {
  width: 100%;
}

.buttons-list,
.variables-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.button-item,
.variable-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--ds-divider);
  border-radius: 4px;
  background-color: var(--ds-surface-2);
}

.variable-item {
  cursor: move;
}

.drag-handle {
  cursor: grab;
  color: var(--ds-text-faint);
}

.drag-handle:active {
  cursor: grabbing;
}

.cdk-drag-preview {
  box-shadow: 0 5px 5px -3px rgba(0, 0, 0, 0.2),
              0 8px 10px 1px rgba(0, 0, 0, 0.14),
              0 3px 14px 2px rgba(0, 0, 0, 0.12);
  opacity: 0.8;
}

.cdk-drag-animating {
  transition: transform 250ms cubic-bezier(0, 0, 0.2, 1);
}

.variables-list.cdk-drop-list-dragging .variable-item:not(.cdk-drag-placeholder) {
  transition: transform 250ms cubic-bezier(0, 0, 0.2, 1);
}

.empty-variables {
  padding: 32px;
  text-align: center;
  color: var(--ds-text-muted);
  font-style: italic;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  padding-top: 24px;
  border-top: 1px solid var(--ds-divider);
}

.preview-section {
  position: sticky;
  top: 24px;
  height: fit-content;
}

@media (max-width: 1200px) {
  .editor-content {
    grid-template-columns: 1fr;
  }

  .preview-section {
    position: relative;
    top: 0;
  }
}

@media (max-width: 768px) {
  .button-item,
  .variable-item {
    flex-wrap: wrap;
  }

  .form-row {
    grid-template-columns: 1fr;
  }
}

