  background: var(--ds-surface-2);
  border-left: 3px solid var(--ds-marine);
  padding: 12px;
  border-radius: 4px;
  margin-bottom: 12px;
}

.preview-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--ds-text-muted);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.preview-content {
  font-size: 14px;
  color: var(--ds-text);
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.template-variables {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: var(--ds-warning-hl);
  border-radius: 4px;
}

.variables-icon {
  color: var(--ds-warning);
  font-size: 18px;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

.variables-text {
  font-size: 12px;
  color: var(--ds-warning);
  font-family: monospace;
}

.sheet-actions {
  display: flex;
  gap: 12px;
  padding: 16px 20px;
  border-top: 1px solid var(--ds-divider);
  position: sticky;
  bottom: 0;
  background: white;
  z-index: 10;
}

.clear-button {
  flex: 1;
}

.sheet-actions button:last-child {
  flex: 2;
}

