    padding: 12px 16px;
  }

  .template-card {
    padding: 12px 16px;
  }

  .template-title h3 {
    font-size: 15px;
  }

  .template-description {
    font-size: 12px;
  }

  .preview-content {
    font-size: 13px;
  }

  .sheet-actions {
    padding: 12px 16px;
    flex-direction: column;
  }

  .sheet-actions button {
    width: 100%;
  }
}

