.ds-timeline {
  list-style: none;
  margin: 0;
  padding: 0 0 0 22px;
  position: relative;

  &::before {
    content: '';
    position: absolute;
    left: 7px;
    top: 6px;
    bottom: 0;
    width: 1px;
    background: var(--ds-divider);
  }

  &__event {
    position: relative;
    padding-bottom: var(--ds-space-5);
    display: flex;
    gap: var(--ds-space-3);

    &::before {
      content: '';
      position: absolute;
      left: -22px;
      top: 6px;
      width: 8px;
      height: 8px;
      border-radius: 50%;
      border: 2px solid var(--ds-surface);
      box-shadow: 0 0 0 1px currentColor;
    }

    &--marine::before { background: var(--ds-marine);   color: var(--ds-marine); }
    &--copper::before { background: var(--ds-primary);  color: var(--ds-primary); }
    &--muted::before  { background: var(--ds-text-faint); color: var(--ds-text-faint); }
  }

  &__date {
    font-size: 11.5px;
    color: var(--ds-text-faint);
    white-space: nowrap;
    min-width: 52px;
    padding-top: 2px;
  }

  &__content { flex: 1; }

  &__title {
    font-size: 14px;
    font-weight: 600;
    color: var(--ds-text);
    line-height: 1.3;
  }

  &__desc {
    font-size: 13px;
    color: var(--ds-text-muted);
    margin-top: var(--ds-space-1);
    line-height: 1.45;
  }
}

