.tour-progress-container {
  padding: 24px;
  max-width: 1200px;
  margin: 0 auto;
}

.tour-progress-header {
  margin-bottom: 32px;
}

.tour-progress-header h2 {
  font-size: 28px;
  font-weight: 600;
  margin: 0 0 8px 0;
  color: var(--ds-text);
}

.tour-progress-subtitle {
  font-size: 16px;
  color: var(--ds-text-muted);
  margin: 0;
}

.progress-overview {
  background: linear-gradient(135deg, var(--ds-marine-light) 0%, var(--ds-primary) 100%);
  color: white;
  border-radius: 12px;
  padding: 24px;
  margin-bottom: 32px;
  box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
}

.progress-stats {
  display: flex;
  gap: 32px;
  margin-bottom: 20px;
}

.stat-item {
  flex: 1;
}

.stat-value {
  font-size: 32px;
  font-weight: 700;
  margin-bottom: 4px;
}

.stat-label {
  font-size: 14px;
  opacity: 0.9;
}

.progress-bar-container {
  margin-bottom: 16px;
}

.progress-bar-container mat-progress-bar {
  height: 8px;
  border-radius: 4px;
}

.progress-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 16px;
}

.progress-actions button {
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border-color: rgba(255, 255, 255, 0.4);
}

.progress-actions button:hover {
  background: rgba(255, 255, 255, 0.3);
}

.tour-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 20px;
  margin-bottom: 32px;
}

.tour-card {
  display: block;
  transition: all 0.3s ease;
  border-radius: 8px;
  cursor: pointer;
}

.tour-card:hover ::ng-deep .ds-card {
  box-shadow: var(--ds-shadow-md);
  transform: translateY(-2px);
}

.tour-card.completed ::ng-deep .ds-card {
  border-left: 4px solid var(--ds-success);
}

.tour-card-header {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 16px 16px 0;
}

.tour-card-headings {
  min-width: 0;
  flex: 1;
}

.tour-card-body {
  padding: 0 16px 16px;
}

.tour-card-avatar {
  flex-shrink: 0;
}

.tour-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  background-color: var(--ds-bg);
  border-radius: 50%;
}

.tour-icon mat-icon {
  font-size: 28px;
  width: 28px;
  height: 28px;
}

.tour-card-title {
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 4px;
}

.tour-card-subtitle {
  display: flex;
  gap: 16px;
  align-items: center;
  font-size: 13px;
  color: var(--ds-text-muted);
}

.tour-duration,
.tour-steps {
  display: flex;
  align-items: center;
  gap: 4px;
}

.duration-icon,
.steps-icon {
  font-size: 16px;
  width: 16px;
  height: 16px;
}

.tour-description {
  margin: 16px 0;
  color: var(--ds-text-muted);
  line-height: 1.6;
}

.tour-status {
  margin-top: 12px;
}

.completed-chip {
  background-color: var(--ds-success) !important;
  color: white !important;
  font-weight: 500;
}

.completed-chip mat-icon {
  color: white;
  font-size: 18px;
  width: 18px;
  height: 18px;
  margin-right: 4px;
}

.tour-card-actions {
  display: flex;
  gap: 8px;
  padding: 8px 16px;
  border-top: 1px solid var(--ds-divider);
}

.tour-card-actions button {
  flex: 1;
}

.loading-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 64px 24px;
  text-align: center;
}

.loading-state p {
  margin-top: 16px;
  color: var(--ds-text-muted);
}

.tour-info-banner {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 16px 20px;
  background-color: var(--ds-marine-hl);
  border-left: 4px solid var(--ds-marine);
  border-radius: 4px;
}

.tour-info-banner mat-icon {
  color: var(--ds-marine);
  margin-top: 2px;
}

.banner-content h3 {
  margin: 0 0 8px 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--ds-marine);
}

.banner-content p {
  margin: 0;
  font-size: 14px;
  color: var(--ds-text-muted);
  display: flex;
  align-items: center;
  gap: 4px;
}

.inline-icon {
  font-size: 18px;
  width: 18px;
  height: 18px;
  vertical-align: middle;
}

/* Dark theme support */
.dark-theme .tour-progress-header h2 {
  color: var(--ds-surface);
}

.dark-theme .tour-progress-subtitle {
  color: var(--ds-text-faint);
}

.dark-theme .tour-description {
  color: var(--ds-divider);
}

.dark-theme .tour-card-subtitle {
  color: var(--ds-text-faint);
}

.dark-theme .tour-icon {
  background-color: var(--ds-text-muted);
}

.dark-theme .tour-card-actions {
  border-top-color: var(--ds-text-muted);
}

.dark-theme .loading-state p {
  color: var(--ds-text-faint);
}

.dark-theme .tour-info-banner {
  background-color: rgba(33, 150, 243, 0.1);
  border-left-color: var(--ds-marine-light);
}

.dark-theme .banner-content h3 {
  color: var(--ds-marine-light);
}

.dark-theme .banner-content p {
  color: var(--ds-divider);
}

/* Responsive design */
@media (max-width: 768px) {
  .tour-progress-container {
    padding: 16px;
  }

  .tour-list {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .progress-stats {
    flex-direction: column;
    gap: 16px;
  }

  .tour-card-subtitle {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .tour-card-actions {
    flex-direction: column;
  }

  .tour-card-actions button {
    width: 100%;
  }
}

@media (max-width: 599px) {
  .tour-progress-header h2 {
    font-size: 24px;
  }

  .stat-value {
    font-size: 28px;
  }
}

