.ui-preferences-form {
  max-width: 1000px;
  margin: 0 auto;
  padding: 24px;
}

.preferences-card {
  display: block;
  overflow: hidden;
}

.pref-ui-card-header {
  background: linear-gradient(135deg, var(--ds-marine-light) 0%, var(--ds-primary) 100%);
  color: white;
  padding: 24px;
}

.dark-theme .pref-ui-card-header {
