}

.title-icon {
  margin-right: 12px;
  vertical-align: middle;
}

.pref-ui-card-title {
  display: flex;
  align-items: center;
  font-size: 24px;
  font-weight: 500;
  margin: 0 0 8px;
  color: white;
}

.pref-ui-card-subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 14px;
  margin: 0;
}

.pref-ui-card-body {
  padding: 0 24px;
}

.loading-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
}

.preferences-form-content {
  padding: 24px 0;
}

/* Form Sections */
.form-section {
  margin-bottom: 32px;
}

.section-title {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 18px;
  font-weight: 500;
  color: var(--ds-text);
  margin: 0 0 16px 0;
}

.dark-theme .section-title {
  color: var(--ds-text-inverse);
}

.section-title mat-icon {
  color: var(--ds-marine-light);
  font-size: 24px;
  width: 24px;
  height: 24px;
}

.dark-theme .section-title mat-icon {
  color: var(--ds-marine-light);
}

.section-divider {
  margin: 32px 0;
}

/* Theme Radio Group */
.theme-radio-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 16px;
}

.theme-radio-button {
  flex: 1;
  min-width: 150px;
}

.theme-radio-button .radio-content {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 16px;
  border: 2px solid var(--ds-divider);
  border-radius: 8px;
