}

/* Density variations */
.preview-zone.density-compact {
  padding: 16px;
}

.preview-zone.density-compact .preview-item {
  padding: 8px 0;
}

.preview-zone.density-comfortable {
  padding: 24px;
}

.preview-zone.density-comfortable .preview-item {
  padding: 12px 0;
}

.preview-zone.density-spacious {
  padding: 32px;
}

.preview-zone.density-spacious .preview-item {
  padding: 16px 0;
}

.preview-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 16px;
  border-bottom: 2px solid rgba(0, 0, 0, 0.1);
}

.preview-zone.theme-dark .preview-header {
