}

.sample-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.15);
}

.card-content {
  display: flex;
  align-items: flex-start;
  gap: 16px;
}

.card-content mat-icon {
  font-size: 32px;
  width: 32px;
  height: 32px;
  color: var(--ds-marine-light);
}

.preview-zone.theme-dark .card-content mat-icon {
  color: var(--ds-marine-light);
}

.card-content h5 {
  margin: 0 0 8px 0;
  font-size: 16px;
  font-weight: 500;
}

.card-content p {
  margin: 0;
  font-size: 13px;
  opacity: 0.8;
}

.preview-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 2px solid rgba(0, 0, 0, 0.1);
}

.preview-zone.theme-dark .preview-footer {
  border-top-color: rgba(255, 255, 255, 0.1);
}

.footer-icon {
  font-size: 16px;
  width: 16px;
  height: 16px;
}

.preview-footer small {
  font-size: 12px;
  opacity: 0.8;
}

/* Card Actions */
.card-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  padding: 16px 24px;
  background-color: var(--ds-bg);
  border-top: 1px solid var(--ds-divider);
  margin: 0;
}

.dark-theme .card-actions {
  background-color: var(--ds-text);
}

.button-spinner {
  display: inline-block;
  margin-right: 8px;
}

/* Animations */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Responsive */
@media (max-width: 768px) {
  .ui-preferences-form {
    padding: 16px;
  }

  .pref-ui-card-header {
    padding: 16px;
  }

  .pref-ui-card-title {
    font-size: 20px;
  }

  .theme-radio-group {
    flex-direction: column;
  }

  .theme-radio-button {
    min-width: 100%;
  }

  .density-toggle-group {
    flex-direction: column;
  }

  .preview-details {
    grid-template-columns: 1fr;
  }

  .preview-actions {
    flex-direction: column;
  }

  .preview-actions button {
    width: 100%;
  }

  .card-actions {
    flex-direction: column;
  }

  .card-actions button {
    width: 100%;
  }
}

/* Material overrides */
::ng-deep .mat-radio-button .mat-radio-label {
  width: 100%;
}

::ng-deep .mat-button-toggle-appearance-standard .mat-button-toggle-label-content {
  padding: 0;
  line-height: normal;
}

::ng-deep .mat-form-field-appearance-outline .mat-form-field-outline {
  color: var(--ds-divider);
}

.dark-theme ::ng-deep .mat-form-field-appearance-outline .mat-form-field-outline {
  color: var(--ds-text-muted);
}

::ng-deep .mat-form-field-appearance-outline.mat-focused .mat-form-field-outline-thick {
  color: var(--ds-marine-light);
}

.dark-theme ::ng-deep .mat-form-field-appearance-outline.mat-focused .mat-form-field-outline-thick {
  color: var(--ds-marine-light);
}

/* Transitions */
* {
  transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease;
}

button,
mat-radio-button,
mat-button-toggle {
  transition: all 0.2s ease;
}

button:hover:not([disabled]),
mat-radio-button:hover,
mat-button-toggle:hover {
  transform: translateY(-1px);
}

button:active:not([disabled]) {
  transform: translateY(0);
}

