/* ─── HERO ─── */
.vz-hero {
  background: var(--ds-marine);
  padding-block: clamp(4rem, 10vw, 7rem);
  position: relative;
  overflow: hidden;
  color: var(--ds-text-inverse);
}

.vz-hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 65% 35%, oklch(0.5 0.08 220 / 0.3) 0%, transparent 60%),
    radial-gradient(ellipse at 15% 75%, oklch(0.4 0.06 40 / 0.2) 0%, transparent 50%),
    linear-gradient(oklch(1 0 0 / 0.025) 1px, transparent 1px)  0 0/48px 48px,
    linear-gradient(90deg, oklch(1 0 0 / 0.025) 1px, transparent 1px) 0 0/48px 48px;
}

.vz-hero-content { position: relative; z-index: 2; }

.vz-hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--ds-space-2);
  font-size: var(--ds-text-xs);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ds-primary);
  background: oklch(1 0 0 / 0.06);
  padding: var(--ds-space-2) var(--ds-space-4);
  border-radius: var(--ds-radius-pill);
  border: 1px solid oklch(1 0 0 / 0.1);
  margin-bottom: var(--ds-space-6);
}

.vz-hero-title {
  font-family: var(--ds-font-display);
  font-size: var(--ds-text-3xl);
  font-weight: 700;
  color: white;
  line-height: 1.1;
  margin-bottom: var(--ds-space-6);
  max-width: 20ch;
}

.vz-hero-title em {
  font-style: italic;
  color: var(--ds-primary);
}

.vz-hero-lead {
  font-size: var(--ds-text-lg);
  color: oklch(1 0 0 / 0.65);
  max-width: 50ch;
  line-height: 1.7;
  margin-bottom: var(--ds-space-8);
}

.vz-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ds-space-4);
  align-items: center;
  margin-bottom: var(--ds-space-4);
}

.vz-hero-note {
  font-size: var(--ds-text-xs);
  color: oklch(1 0 0 / 0.35);
  margin-bottom: var(--ds-space-12);
}

.vz-stats {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ds-space-8);
  padding-top: var(--ds-space-8);
  border-top: 1px solid oklch(1 0 0 / 0.1);
}

.vz-stat-value {
  font-family: var(--ds-font-display);
  font-size: var(--ds-text-2xl);
  font-weight: 700;
  color: white;
  line-height: 1;
}

.vz-stat-label {
  font-size: var(--ds-text-xs);
  color: oklch(1 0 0 / 0.5);
  margin-top: var(--ds-space-1);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* ─── PROFILES ─── */
.vz-profiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--ds-space-6);
}

.vz-profile-card {
  display: block;
  background: var(--ds-surface);
  border: 1.5px solid var(--ds-border);
  border-radius: var(--ds-radius-xl);
  padding: var(--ds-space-8);
  text-decoration: none;
  transition: all var(--ds-transition-med);
  cursor: pointer;
}

.vz-profile-card:hover {
  border-color: var(--ds-primary-hl);
  box-shadow: var(--ds-shadow-md);
  transform: translateY(-2px);
}

.vz-profile-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--ds-radius-lg);
  background: var(--ds-marine);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  margin-bottom: var(--ds-space-5);
}

.vz-profile-card h3 {
  font-family: var(--ds-font-display);
  font-size: var(--ds-text-lg);
  font-weight: 700;
  color: var(--ds-text);
  margin-bottom: var(--ds-space-3);
}

.vz-profile-card p {
  font-size: var(--ds-text-sm);
  color: var(--ds-text-muted);
  line-height: 1.7;
  margin-bottom: var(--ds-space-5);
  max-width: none;
}

.vz-profile-link {
  font-size: var(--ds-text-sm);
  font-weight: 600;
  color: var(--ds-primary);
}

/* ─── RESPONSIVE ─── */
@media (max-width: 600px) {
  .vz-hero-actions { flex-direction: column; align-items: flex-start; }
  .vz-stats { gap: var(--ds-space-6); }
}

