.template-button {
  flex-shrink: 0;
  margin-bottom: 4px;
}

.message-textarea {
  flex: 1;
  min-height: 40px;
  max-height: 120px;
  padding: 10px 12px;
  border: 1px solid var(--ds-divider);
  border-radius: 20px;
  font-size: 14px;
  font-family: inherit;
  resize: none;
  overflow-y: auto;
  line-height: 1.5;
  background: white;
  transition: border-color 0.2s;
}

.message-textarea:focus {
  outline: none;
  border-color: var(--ds-success);
}

.message-textarea:disabled {
  background: var(--ds-bg);
  color: var(--ds-text-faint);
  cursor: not-allowed;
}

.send-button {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  min-height: 48px;
  background: var(--ds-success);
  transition: all 0.2s;
}

.send-button:not(:disabled):hover {
  background: var(--ds-success);
  transform: scale(1.05);
}

.send-button:disabled {
  background: var(--ds-divider);
  cursor: not-allowed;
}

.send-button.sending {
  pointer-events: none;
}

.send-button mat-icon {
  font-size: 24px;
  width: 24px;
  height: 24px;
}

@media (max-width: 768px) {
  .input-wrapper {
    padding: 8px 12px;
  }

  .template-button {
    width: 40px;
    height: 40px;
    min-width: 40px;
  }

  .send-button {
    width: 44px;
    height: 44px;
    min-height: 44px;
  }

  .message-textarea {
    font-size: 16px; /* Prevents zoom on iOS */
    padding: 8px 12px;
  }

  .template-variables {
    max-height: 150px;
    padding: 8px 12px;
  }
}

@media (max-width: 480px) {
  .queue-indicator {
    font-size: 12px;
    padding: 6px 12px;
  }

  .template-chip-container {
    padding: 8px 12px 0;
  }
}

