@use '../design-system/patterns/messaging-thread/messaging-thread-bubbles' as *;

.whatsapp-messaging-ui {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--ds-bg);
  position: relative;
  overflow: hidden;
}

.messaging-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  background: var(--ds-marine);
  color: var(--ds-text-inverse);
  box-shadow: var(--ds-shadow-sm);
  z-index: 10;
}

.recipient-info {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
}

.whatsapp-icon {
  font-size: 32px;
  width: 32px;
  height: 32px;
}

.recipient-details {
  display: flex;
  flex-direction: column;
}

.recipient-name {
  font-size: 16px;
  font-weight: 500;
}

.recipient-phone {
  font-size: 13px;
  opacity: 0.9;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;

  button {
    color: var(--ds-text-inverse);
  }
}

.connection-indicator {
  font-size: 20px;
  width: 20px;
  height: 20px;

  &.online {
    color: var(--ds-success);
  }

  &.offline {
    color: var(--ds-warning);
  }
}

.consent-warning {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--ds-warning-hl);
  color: var(--ds-warning);
  border-bottom: 1px solid var(--ds-divider);
  font-size: 14px;
  line-height: 1.5;
  z-index: 9;

  mat-icon {
    color: var(--ds-warning);
    font-size: 24px;
    width: 24px;
    height: 24px;
  }
}

.messages-container {
  flex: 1;
  min-height: 0;
  background: var(--ds-bg);
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" opacity="0.05"><rect width="400" height="400" fill="%23075e54"/></svg>');
  position: relative;

  &.with-consent-warning {
    flex: 1;
  }
}

.messages-viewport {
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
}

.loading-indicator {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
  gap: 16px;

  span {
    color: var(--ds-text-muted);
    font-size: 14px;
  }
}

.messages-list {
  padding: 16px 12px;
  min-height: 100%;
}

.messages-list.ds-thread--whatsapp {
  padding: 16px 12px;
  gap: 0;
}

.ds-thread__msg {
  position: relative;
  margin-bottom: 8px;
  transition: transform 0.2s ease-out;
  touch-action: pan-y;
  box-shadow: var(--ds-shadow-xs);
}

.ds-thread__bubble {
  animation: bubbleIn 0.2s ease-out;
}

@keyframes bubbleIn {
  from {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.swipe-actions {
  display: flex;
  gap: 4px;
  align-items: center;
  opacity: 0;
  transition: opacity 0.2s;
  position: absolute;
  right: 100%;
  top: 50%;
  transform: translateY(-50%);
  margin-right: 8px;

  &.visible {
    opacity: 1;
  }

  button {
    width: 32px;
    height: 32px;
    min-width: 32px;
    line-height: 32px;
  }

  .mat-icon {
    font-size: 18px;
    width: 18px;
    height: 18px;
  }

  .action-retry {
    color: var(--ds-marine);
  }

  .action-copy {
    color: var(--ds-success);
  }
}

.ds-thread__meta mat-icon.ds-thread__delivery {
  display: inline-flex;
  align-items: center;
  font-size: 16px;
  width: 16px;
  height: 16px;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  color: var(--ds-text-muted);
  text-align: center;

  mat-icon {
    font-size: 64px;
    width: 64px;
    height: 64px;
    margin-bottom: 16px;
    opacity: 0.3;
  }

  p {
    font-size: 16px;
    font-weight: 500;
    margin: 0 0 8px;
  }

  small {
    font-size: 13px;
    opacity: 0.8;
  }
}

.message-input-area {
  background: var(--ds-bg);
  border-top: 1px solid var(--ds-divider);
  padding: 8px 16px 16px;
  z-index: 10;

  &.disabled {
    opacity: 0.6;
    pointer-events: none;
  }
}

.template-chip-container {
  margin-bottom: 8px;
}

.template-chip {
  background: var(--ds-marine-hl) !important;
  border: 1px solid var(--ds-marine) !important;

  mat-icon {
    color: var(--ds-marine);
  }
}

.template-variables {
  margin-bottom: 12px;
  padding: 12px;
  background: var(--ds-surface);
  border-radius: var(--ds-radius-md, 8px);
  box-shadow: var(--ds-shadow-xs);
}

.variables-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  font-size: 14px;
  font-weight: 500;
  color: var(--ds-marine);

  mat-icon {
    font-size: 18px;
    width: 18px;
    height: 18px;
  }
}

.variable-inputs {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.variable-field {
  width: 100%;
  font-size: 14px;
}

.attachments-preview {
  margin-bottom: 12px;
  padding: 12px;
  background: var(--ds-surface);
  border-radius: var(--ds-radius-md, 8px);
  box-shadow: var(--ds-shadow-xs);
}

.attachments-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  font-size: 14px;
  font-weight: 500;
  color: var(--ds-marine);

  mat-icon {
    font-size: 18px;
    width: 18px;
    height: 18px;
  }
}

.attachment-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.attachment-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px;
  background: var(--ds-bg);
  border-radius: 8px;
  border: 1px solid var(--ds-divider);
}

.attachment-preview {
  width: 48px;
  height: 48px;
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ds-divider);

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  &.document {
    background: var(--ds-warning-hl);

    mat-icon {
      font-size: 32px;
      width: 32px;
      height: 32px;
      color: var(--ds-warning);
    }
  }
}

.attachment-info {
  flex: 1;
  min-width: 0;
}

.attachment-name {
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.attachment-size {
  font-size: 12px;
  color: var(--ds-text-muted);
}

.remove-attachment {
  color: var(--ds-error);
}

.input-controls {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}

.template-button,
.attachment-button {
  flex-shrink: 0;
}

.message-input-wrapper {
  flex: 1;
  min-width: 0;
  background: var(--ds-surface);
  border-radius: 24px;
  padding: 8px 16px;
  box-shadow: var(--ds-shadow-xs);
}

.message-textarea {
  width: 100%;
  border: none;
  outline: none;
  resize: none;
  font-size: 14px;
  font-family: inherit;
  line-height: 1.5;
  background: transparent;
  max-height: 120px;
  overflow-y: auto;

  &:disabled {
    color: var(--ds-text-faint);
    cursor: not-allowed;
  }
}

.send-button {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  min-width: 48px;
  transition: transform 0.2s;

  &:not(:disabled):hover {
    transform: scale(1.05);
  }

  &:not(:disabled):active {
    transform: scale(0.95);
  }

  &.sending {
    pointer-events: none;
  }
}

.message-info {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  font-size: 12px;
  color: var(--ds-text-muted);
  padding: 0 8px;
}

.character-count {
  font-weight: 500;
}

.separator {
  opacity: 0.5;
}

@media (max-width: 768px) {
  .whatsapp-messaging-ui.mobile {
    height: 100vh;
    max-height: 100vh;
  }

  .messaging-header {
    padding: 12px 16px;
  }

  .recipient-name {
    font-size: 15px;
  }

  .recipient-phone {
    font-size: 12px;
  }

  .messages-list {
    padding: 12px 8px;
  }

  .message-input-area {
    padding: 8px 12px 12px;
  }

  .input-controls {
    gap: 6px;
  }

  .message-input-wrapper {
    padding: 6px 12px;
  }

  .send-button {
    width: 42px;
    height: 42px;
    min-width: 42px;
  }

  .template-variables,
  .attachments-preview {
    padding: 8px;
  }

  .variable-inputs {
    gap: 6px;
  }

  .attachment-item {
    padding: 6px;
  }

  .attachment-preview {
    width: 40px;
    height: 40px;
  }
}

@media (max-width: 480px) {
  .ds-thread__text {
    font-size: 13px;
  }

  .ds-thread__meta {
    font-size: 10px;
  }

  .messaging-header {
    padding: 10px 12px;
  }

  .recipient-name {
    font-size: 14px;
  }

  .consent-warning {
    padding: 10px 12px;
    font-size: 13px;
  }
}

@media (min-width: 769px) {
  .whatsapp-messaging-ui {
    max-width: 800px;
    margin: 0 auto;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: var(--ds-shadow-lg);
  }

  .messaging-header {
    border-radius: 8px 8px 0 0;
  }
}

::ng-deep .template-bottom-sheet {
  max-height: 70vh;
}

::ng-deep .template-bottom-sheet-desktop {
  max-width: 500px;
  margin: 0 auto;
}

::ng-deep .success-snackbar {
  background: var(--ds-success) !important;
  color: var(--ds-text-inverse) !important;
}

::ng-deep .error-snackbar {
  background: var(--ds-error) !important;
  color: var(--ds-text-inverse) !important;
}

::ng-deep .warning-snackbar {
  background: var(--ds-warning) !important;
  color: var(--ds-text-inverse) !important;
}

::ng-deep .info-snackbar {
  background: var(--ds-marine) !important;
  color: var(--ds-text-inverse) !important;
}

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--ds-divider);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--ds-text-faint);
}

