trigger('routeSlideRightAnimation', [
  transition('* => *', [
    query(':enter, :leave', [
      style({
        position: 'absolute',
        width: '100%',
        left: 0,
        right: 0
      })
    ], { optional: true }),
    group([
      query(':leave', [
        style({ transform: 'translateX(0)', opacity: 1 }),
        animate(getAnimationDuration('200ms') + ' ease-out', style({ 
          transform: 'translateX(100%)', 
          opacity: 0 
        }))
      ], { optional: true }),
      query(':enter', [
        style({ transform: 'translateX(-100%)', opacity: 0 }),
        animate(getAnimationDuration('200ms') + ' ease-out', style({ 
          transform: 'translateX(0)', 
          opacity: 1 
        }))
      ], { optional: true })
    ])
  ])
])

